/// The input module, imported under a name that does not collide with the app's
/// `input` buffer field. A module shadowed by a local reads as "the buffer"
/// when it means "the module", which is the kind of ambiguity that costs an
/// hour.
const inputmod = @import("input");

const builtin = @import("builtin");

const Allocator = std.mem.Allocator;
const Dir = std.Io.Dir;
const File = std.Io.File;
const Io = std.Io;
const Writer = std.Io.Writer;

/// Overrides the standard library's logging entry point.
///
/// `log_level` is `debug` unconditionally and the real filtering happens at run
/// time in `appLog`. The cost is that `debug` format strings are compiled into
/// release builds; the benefit, which is the requirement, is that
/// `--log-level=debug` and `CONDUIT_LOG_LEVEL=debug` work on the binary a user
/// already has.
pub const std_options: std.Options = .{
    .log_level = .debug,
    .logFn = appLog,
};

/// Replaces the default panic handler with one that writes a crash report
/// first. See `writeCrashReport` for the report's contents and location.
pub const panic = std.debug.FullPanic(onPanic);

/// The log scope for process-level events. Every line the app logs goes
/// through a scope, never straight to a stream.
pub const log = std.log.scoped(.app);

/// The product name Conduit lends to the platform before its video subsystem starts.
pub const app_name: [:0]const u8 = "Conduit";
/// The stable reverse-domain identity shared with Conduit's Linux desktop payload.
pub const app_identifier: [:0]const u8 = "io.github.thowd22.Conduit";

/// The version Conduit reports at startup and for `--version`. Stamped by
/// `zig build -Dversion=<semver>` through the generated `build_options`
/// module; a build without the flag reports `0.0.0-dev`.
pub const version: [:0]const u8 = @import("build_options").version;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

/// A log level, ordered `err` < `warn` < `info` < `debug`. That is the order
/// `std.log.Level` declares, and therefore the order the filter uses.
pub const Level = std.log.Level;

/// The level used when neither the flag nor the environment variable is given:
/// the standard library's own default, `debug` in a debug build and `info` in
/// a release one.
pub const default_level: Level = std.log.default_level;

/// Environment fallback for `--log-level`.
pub const level_env = "CONDUIT_LOG_LEVEL";
/// Environment fallback for `--log-file`.
pub const file_env = "CONDUIT_LOG_FILE";
/// Environment fallback for `--log-dir`.
pub const dir_env = "CONDUIT_LOG_DIR";

/// The environment variables that stand in for a command line, in the order
/// they are consulted. `dir_vars` are the platform's own temporary-directory
/// variables, tried after `dir_env`.
pub const temp_dir_vars = [_][]const u8{ "TMPDIR", "TEMP", "TMP" };

/// The directory the log file falls back to when no temporary directory is
/// named by the environment. It is inside the build cache so a run never
/// writes into the user's working tree.
pub const fallback_log_dir = ".zig-cache/conduit";

/// The longest path Conduit stores: comfortably above `MAX_PATH` on Windows
/// and above any plausible temporary directory on POSIX.
pub const path_capacity = 1024;

/// A read-only view of the environment, so that `parseArgs` stays pure and
/// testable without a real process environment.
pub const EnvSource = struct {
    ctx: *const anyopaque,
    getFn: *const fn (ctx: *const anyopaque, key: []const u8) ?[]const u8,
    /// Enumerate the source by position, or null for a lookup-only source.
    /// Only a Local child inherits through this; see `ChildSpec`.
    entryFn: ?*const fn (ctx: *const anyopaque, index: usize) ?Entry = null,

    /// The value of `key`, or `null` when it is unset or empty. An empty
    /// variable counts as unset: `FOO=` is how a shell says "nothing", not
    /// "the empty path".
    pub fn get(self: EnvSource, key: []const u8) ?[]const u8 {
        const value = self.getFn(self.ctx, key) orelse return null;
        return if (value.len == 0) null else value;
    }

    /// One variable of an enumerable source, exactly as the source holds it:
    /// an empty value is kept, because a child inheriting `FOO=` must see the
    /// same `FOO=` its parent did.
    pub const Entry = struct { key: []const u8, value: []const u8 };

    /// The `index`th variable, or null past the end or for a lookup-only
    /// source.
    pub fn entry(self: EnvSource, index: usize) ?Entry {
        const entry_fn = self.entryFn orelse return null;
        return entry_fn(self.ctx, index);
    }
};

/// Everything the command line and the environment can say about diagnostics,
/// resolved and ready for the filesystem to act on.
pub const Options = struct {
    /// The effective minimum level.
    level: Level = default_level,
    /// An exact log file path, from `--log-file` or `CONDUIT_LOG_FILE`. When
    /// set, the file is truncated if it already exists: the caller named that
    /// path, so the caller owns its uniqueness. When `null`, a unique per-run
    /// path is generated inside `dir`.
    file: ?[]const u8 = null,
    /// The directory a generated per-run log file is created in. Never null:
    /// `parseArgs` resolves it from the flags, then the environment, then the
    /// platform temporary directory, then `fallback_log_dir`.
    dir: []const u8 = fallback_log_dir,
    /// Print the resolved log path on stdout and exit, without running the app.
    print_log_path: bool = false,
    /// Print usage on stdout and exit.
    help: bool = false,
    /// Print `conduit <version>` on stdout and exit.
    print_version: bool = false,
    /// The window to open and how long to run, from the window flags.
    run: Run = .{},
    /// A `conduit <command>` (TASK-66): forwarded to a running instance, or,
    /// when none answers, executed by this run once it has started. Null for
    /// a plain `conduit`.
    command: ?CliCommand = null,
    /// The directory `command` was typed in, absolute; set by `main` when
    /// this run executes the command itself.
    command_cwd: ?[]const u8 = null,
};

/// One `conduit` subcommand, as typed. Every slice borrows the command line.
pub const CliCommand = union(enum) {
    /// `conduit .` or `conduit <dir>`: open or focus a workspace there. The
    /// path is resolved against the caller's working directory before it is
    /// sent, because the running instance has a working directory of its own.
    open_directory: []const u8,
    /// `conduit ssh <host>`: open an SSH workspace.
    open_ssh: []const u8,
    /// `conduit workspace open <name>`: focus that workspace, or open one of
    /// that name in the caller's working directory.
    open_workspace: []const u8,
    /// `conduit agent <harness> [prompt...]`: launch a harness in the current
    /// workspace.
    agent: struct { harness: []const u8, prompt: []const []const u8 },
    /// `conduit control <method> [params-json]`: one raw request to this
    /// terminal's control endpoint (the hook helper).
    control: struct {
        method: []const u8,
        params: ?[]const u8 = null,
        /// `--event=<Hook>`: wrap stdin as a Claude Code hook line.
        event: ?[]const u8 = null,
        /// `--agent=<token>`: the agent token instead of `$CONDUIT_AGENT_TOKEN`.
        agent: ?[]const u8 = null,
    },

    /// The instance method this command forwards, or null for `control`.
    pub fn method(self: CliCommand) ?control_api.Method {
        return switch (self) {
            .open_directory => .instance_open_directory,
            .open_ssh => .instance_open_ssh,
            .open_workspace => .instance_open_workspace,
            .agent => .instance_agent,
            .control => null,
        };
    }
};

/// The window the run opens and how long it runs for.
///
/// These settings decide what the app *does*, where the ones above decide what it
/// *says* about what it does. Both come from the same command line in one pass: a
/// person typing `--hidden --width=640` means both, and two passes over one
/// command line would mean two places that have to know about each other's flags.
///
/// There are no environment fallbacks for these, on purpose: doc-2 fixes the
/// window size and scale by flag at startup, so that a screenshot in CI is the
/// same image on every machine.
pub const Run = struct {
    /// The window's width in logical pixels.
    width: u32 = default_width,
    /// The window's height in logical pixels.
    height: u32 = default_height,
    /// Fix physical pixels per logical pixel instead of following the display.
    /// Null preserves the native display scale.
    scale: ?f32 = null,
    /// Create the window hidden and never show it. The window and its GL context
    /// are real all the same (doc-2): headless is a peer of the on-screen path.
    hidden: bool = false,
    /// Draw a frame every iteration of the loop whether or not anything changed.
    ///
    /// A measurement mode, not a feature: it is what the idle cost of
    /// render-on-demand is measured against, and `--self-test` reports the frame
    /// count either way.
    force_redraw: bool = false,
    /// Leave after this many milliseconds. `null` runs until the window closes.
    run_ms: ?u32 = null,
    /// Run the TASK-7 integration check — a real window, real events, real
    /// pixels — and print what it measured.
    self_test: bool = false,
    /// Print numbered lines, scroll back with a real wheel event, read the
    /// surface back and print what the viewport showed — then exit.
    scroll_test: bool = false,
    /// Drive a real press and drag through SDL's queue, `App.handle`, `input`
    /// and the terminal, with Shift held and not held, then read the surface
    /// back — print what it measured, then exit.
    mouse_test: bool = false,
    /// Prove copy, paste, bracketed paste, middle-click primary paste, the
    /// Ctrl+C rule and the OSC 52 policies through SDL's queue and a real
    /// child, on SDL's offscreen driver so only process-local clipboards are
    /// touched — print what it measured, then exit.
    clipboard_test: bool = false,
    /// Draw and mutate all four UI primitives over a real terminal surface,
    /// measure their pixels and idle work, then exit.
    ui_test: bool = false,
    /// Drive a real SDL text-editing/commit sequence over a real PTY, measure
    /// the inline preedit and exact committed bytes, then exit.
    ime_test: bool = false,
    /// Exercise the production workspace/sidebar tree, inset geometry and
    /// mouse/keyboard switching paths, capture them, then exit.
    sidebar_test: bool = false,
    /// Exercise production tab creation, rename, switching, reordering,
    /// attention and close confirmation through real SDL events, then exit.
    tabs_test: bool = false,
    /// Exercise nested pane layout, focus, resize, zoom and close through real
    /// PTYs and SDL events, then exit.
    panes_test: bool = false,
    /// Exercise the persistent scratchpad's startup, presentations, input
    /// isolation and restart lifecycle through real PTYs and SDL events.
    scratchpad_test: bool = false,
    /// Exercise the production command palette through real SDL keyboard and
    /// mouse events, including fuzzy search and nested arguments.
    palette_test: bool = false,
    /// Exercise multiple independent workspace terminals, pane layouts and
    /// scratchpads through production palette/sidebar actions and real PTYs.
    workspaces_test: bool = false,
    /// Exercise terminal URL semantics, modifier hover and opening through
    /// real SDL pointer events while recording the requested URL in process.
    links_test: bool = false,
    /// Exercise full-scrollback search through production actions, semantic
    /// Input, SDL events and the shared renderer.
    search_test: bool = false,
    /// Exercise the terminal context menu: right-click placement and rows,
    /// keyboard navigation, the paste alternative and DEC mouse reporting
    /// through real PTYs and SDL events, then exit.
    menu_test: bool = false,
    /// Exercise the settings file: startup load, configured keybindings and
    /// scratchpad sizes, a malformed line's visible error, hot reload and the
    /// open-config action, through real SDL events, then exit.
    config_test: bool = false,
    /// Exercise the theme engine: a bundled scheme and a user Ghostty-format
    /// file from the settings, the palette theme picker's live preview by
    /// keyboard and hover, Escape reverting it and a mouse choice saved to the
    /// settings file, through real SDL events, then exit.
    theme_test: bool = false,
    /// Exercise the font commands: size by chord, palette and mouse with cell
    /// metrics, ligatures, built-in symbols, fallbacks and the family picker's
    /// preview, revert and saved choice through real SDL events, then exit.
    font_test: bool = false,
    /// Exercise the settings view: opened from the palette and by its chord,
    /// every editor kind by keyboard and mouse with file readback, keybinding
    /// capture and conflicts, the raw-file row and modal isolation, then exit.
    settings_test: bool = false,
    /// Exercise TASK-46's shell profiles against a private settings file:
    /// the chooser by keyboard and mouse, a new tab's and a split's argv,
    /// environment and directory through real input, `shell` as the
    /// default, the Shells settings rows and a malformed line, then exit.
    profiles_test: bool = false,
    /// Exercise TASK-76's branch rows against real repositories in a private
    /// temporary directory through real PTYs and SDL events, then exit.
    git_test: bool = false,
    /// Exercise TASK-56: a scripted fake agent launched from the palette, its
    /// live sidebar glyphs, the notification list by chord, palette and
    /// mouse, a hot-reloaded notification switch, a background tab's OSC 777
    /// and the OS notification seam, through real PTYs and SDL events.
    agent_test: bool = false,
    /// Exercise TASK-57: the fake agent's structured view, by chord, palette,
    /// keyboard and mouse. Runs in `--agent-test`'s environment (the flag
    /// sets `agent_test` too) with the view script instead of TASK-56's.
    agent_view_test: bool = false,
    /// Exercise TASK-58: the agent manager across two workspaces, by chord,
    /// palette, keyboard and mouse. Runs in `--agent-test`'s environment
    /// (the flag sets `agent_test` too) with TASK-56's fake script.
    agent_manager_test: bool = false,
    /// Exercise TASK-59: one agent's prompts view over a fixture project, by
    /// palette, the agent view's row, keyboard and mouse, an instruction
    /// file edited in vi and re-read, a harness-owned file viewed read-only
    /// and the restart that applies an edit. Runs in `--agent-test`'s
    /// environment (the flag sets `agent_test` too).
    agent_prompts_test: bool = false,
    /// Exercise TASK-63 and TASK-64: the backlog view over a fixture project
    /// with a fake `backlog` CLI, its board, list and detail by keyboard and
    /// mouse, writes, live reloads and an agent started on a task. Runs in
    /// `--agent-test`'s environment (the flag sets `agent_test` too).
    backlog_test: bool = false,
    /// The private directory `--agent-test` keeps its agent sinks and its
    /// background-tab trigger in. Not a command-line flag: `runApp` sets it.
    agent_test_dir: ?[]const u8 = null,
    /// Exercise SSH workspaces (TASK-43/44/45) against a throwaway sshd
    /// container: the connection manager, OpenSSH's prompts in the connection
    /// view, remote tabs, panes and scratchpad in the originating cwd, loss
    /// and reconnect, through real SDL events, then exit. Skipped (exit 0)
    /// without Docker.
    ssh_test: bool = false,
    /// The private directory `--ssh-test` keeps its isolated home, keys,
    /// settings file and control sockets in. Not a command-line flag:
    /// `runApp` sets it. With it the app reads `<dir>/home/.ssh/config`
    /// instead of `~/.ssh/config`, passes it to `ssh -F`, and keeps control
    /// sockets under `<dir>/run`.
    ssh_test_dir: ?[]const u8 = null,
    /// The settings file to load and watch instead of the platform location.
    /// Not a command-line flag: `runApp` sets it for `--config-test`,
    /// `--theme-test`, `--font-test` and `--settings-test`, which
    /// writes into a private directory. Null means the platform location for
    /// an ordinary run and no file at all for every other built-in check, so
    /// a user's settings never change what a check measures.
    config_path: ?[]const u8 = null,
    /// The session layer of the `mouse.right_click` setting, from
    /// `--right-click=`. Null leaves the built-in default standing.
    right_click: ?config.RightClick = null,
    /// Explicit local endpoint for the in-app JSON-RPC automation server.
    /// Null means no listener exists in any build mode.
    test_driver_endpoint: ?[]const u8 = null,
    /// The run-scoped directory where driver screenshots are created. When the
    /// driver is enabled and this is null, `runApp` generates a unique one.
    test_artifact_dir: ?[]const u8 = null,
    /// Exercise the automation endpoint end to end and exit with its result.
    driver_test: bool = false,
    /// Run this line through the shell and leave when it does, instead of
    /// opening an interactive one.
    ///
    /// How a headless run reaches a *known* screen: a person types, this does
    /// not need a keyboard, and the app ends by itself when the line is done
    /// rather than waiting for a window that will never be closed.
    command: ?[]const u8 = null,
    /// Write the last frame the app drew to this path as an RGBA PNG.
    screenshot: ?[]const u8 = null,
    /// The family to draw the grid with. Empty is the bundled face, and a
    /// family that is not installed falls back to it with a log line.
    font_family: []const u8 = "",
    /// Run the grid renderer's own check — a screen whose every cell is known,
    /// read back pixel by pixel at two display scales, with the work each frame
    /// did counted — and exit.
    grid_test: bool = false,
    /// Run with no child behind the terminal.
    ///
    /// A check needs a grid that is not moving under it. `--self-test` turns
    /// this on unless a `--command` says otherwise, because a shell's output
    /// arriving mid-measurement would make the measurement about the shell.
    no_child: bool = false,
    /// The session layer of `control.enabled` (TASK-60): `--control` or
    /// `--no-control`. Null leaves the file and the build default standing.
    control: ?bool = null,
    /// Exercise TASK-60 part two and TASK-66: the control endpoint from a
    /// real tab's shell, the scratchpad's exclusion and the single-instance
    /// commands as separate processes, against a private runtime and state
    /// directory. Runs in `--agent-test`'s environment (the flag sets
    /// `agent_test` too).
    control_test: bool = false,
    /// The runtime directory the control and instance sockets live in instead
    /// of `$XDG_RUNTIME_DIR`. Not a command-line flag: `runApp` sets it for
    /// `--control-test`.
    runtime_dir: ?[]const u8 = null,
    /// The state directory the instance token is written to instead of the
    /// platform one. Not a command-line flag: `runApp` sets it for
    /// `--control-test`.
    state_dir: ?[]const u8 = null,
    /// Skip this launch's restore of the saved workspaces (TASK-65) and start
    /// clean; the run still saves its own state as usual.
    no_restore: bool = false,
    /// Whether `--width` or `--height` was given: a saved window size is then
    /// not restored over the size the command line asked for.
    size_explicit: bool = false,
    /// Exercise TASK-65 end to end: build workspaces, tabs, splits, a theme
    /// and an SSH workspace through real input, quit, relaunch a second app
    /// on the same window and prove what came back, then corrupt the file
    /// and write a newer version and prove the clean starts, then exit.
    restore_test: bool = false,
    /// Exercise TASK-68's app wiring: a private D-Bus session bus and a
    /// stand-in AT-SPI registry, the bridge publishing the live tree, a bus
    /// client walking the sidebar, palette and settings, and `DoAction` on a
    /// palette row running its command, then exit. Skipped (exit 0) without
    /// `dbus-daemon`.
    a11y_test: bool = false,
    /// The state file to save to and restore from instead of the platform
    /// one. Not a command-line flag: `runApp` sets it for `--restore-test`,
    /// the one check that persists. Every other check neither saves nor
    /// restores.
    state_path: ?[]const u8 = null,
    /// The session bus the accessibility bridge connects to instead of
    /// `DBUS_SESSION_BUS_ADDRESS`. Not a command-line flag: `runApp` sets it
    /// for `--a11y-test`'s private bus. Every other check runs without the
    /// bridge, so a check never appears on the person's accessibility bus.
    a11y_bus_address: ?[]const u8 = null,
    /// Start the shell exactly as it would start without Conduit: no `--posix`,
    /// no `ENV`, no `ZDOTDIR` swap, and therefore no working-directory or prompt
    /// reports from Conduit's scripts. The settings file has no shell key yet, so
    /// this flag is how shell integration is turned off.
    no_shell_integration: bool = false,
};

/// The palette a run draws with until the `theme` setting is resolved, and
/// whenever it names nothing: `conduit-dark`, derived by `theme.derive`. That
/// is exactly the palette Conduit drew with before themes existed (the theme
/// unit tests pin it slot for slot), so built-in checks that never load a
/// settings file see the same colours as before.
pub const default_palette: theme.Palette = theme.derive(theme.conduit_dark);

/// A palette colour as a surface colour.
///
/// This function is the whole bridge between the two types. `theme.Color` and
/// `render.Rgba` are deliberately different types and neither module may
/// import the other, so the conversion happens here, in the one module that is
/// allowed to see both, and everything downstream works with `Rgba`.
pub fn surfaceColor(color: theme.Color) render.Rgba {
    return .{ .r = color.r, .g = color.g, .b = color.b, .a = color.a };
}

/// `palette` as the colours the grid renderer draws with.
///
/// Only the sixteen ANSI roles are named: the grid resolves the rest of the
/// terminal's 256 slots arithmetically, because those are the same in every
/// terminal and are not a theme's to change.
pub fn gridColors(palette: theme.Palette) render.Colors {
    var ansi: [render.ansi_count]render.Rgba = undefined;
    for (std.enums.values(theme.Role), 0..) |role, slot| {
        if (role.isAnsi()) ansi[slot] = surfaceColor(palette.get(role));
    }
    return .{
        .ansi = ansi,
        .foreground = surfaceColor(palette.get(.foreground)),
        .background = surfaceColor(palette.get(.background)),
        .cursor = surfaceColor(palette.get(.cursor)),
        .selection = surfaceColor(palette.get(.selection)),
    };
}

/// The window size a run opens with when the command line does not say.
pub const default_width: u32 = 960;
pub const default_height: u32 = 640;

/// The renderer checks own their viewport and font so captures are comparable
/// between runs rather than inheriting whichever diagnostic flags happened to
/// be on the command line.
const ui_test_width: u32 = 640;
const ui_test_height: u32 = 360;

fn optionsForRun(options: Options) Options {
    if (!options.run.ui_test and !options.run.ime_test and !options.run.driver_test and
        !options.run.sidebar_test and !options.run.tabs_test and !options.run.panes_test and
        !options.run.scratchpad_test and !options.run.palette_test and
        !options.run.workspaces_test and !options.run.links_test and
        !options.run.search_test and !options.run.menu_test and !options.run.config_test and
        !options.run.theme_test and !options.run.font_test and !options.run.settings_test and
        !options.run.profiles_test and !options.run.git_test and !options.run.agent_test and !options.run.ssh_test and
        !options.run.restore_test and !options.run.a11y_test) return options;
    var resolved = options;
    resolved.run.width = ui_test_width;
    resolved.run.height = ui_test_height;
    resolved.run.scale = 1.0;
    resolved.run.hidden = true;
    resolved.run.force_redraw = false;
    resolved.run.run_ms = null;
    resolved.run.command = null;
    resolved.run.font_family = "";
    resolved.run.no_child = options.run.ui_test or options.run.driver_test or options.run.sidebar_test or
        options.run.scratchpad_test or options.run.ssh_test or options.run.a11y_test;
    return resolved;
}

/// A rejected command line or environment value. None of these are panics:
/// malformed external input must never crash the app (CONDUIT.md §11).
pub const ConfigError = error{
    UnknownFlag,
    MissingValue,
    InvalidLogLevel,
    InvalidSize,
    InvalidScale,
    InvalidRightClick,
    /// `conduit workspace <verb>` with a verb other than `open`.
    UnknownCommand,
    /// A subcommand without its required argument.
    MissingArgument,
    /// A subcommand followed by more than it takes.
    UnexpectedArgument,
};

/// A window dimension: at least one pixel, because a window of no pixels is not a
/// window, and there is no honest reading of `--width=0`.
fn parseDimension(text: []const u8) ConfigError!u32 {
    const value = std.fmt.parseInt(u32, text, 10) catch return error.InvalidSize;
    if (value < 1) return error.InvalidSize;
    return value;
}

/// A deterministic screenshot scale. Display scale follows the platform only
/// when the flag is absent; malformed or vanishing factors are rejected.
fn parseScale(text: []const u8) ConfigError!f32 {
    const value = std.fmt.parseFloat(f32, text) catch return error.InvalidScale;
    if (!std.math.isFinite(value) or value < platform.Scale.min_factor) return error.InvalidScale;
    return value;
}

/// A millisecond count, where zero is a real answer: a run budget of zero leaves as
/// soon as the first frame is on the surface.
fn parseMilliseconds(text: []const u8) ConfigError!u32 {
    return std.fmt.parseInt(u32, text, 10) catch error.InvalidSize;
}

/// Parse a level name, case-insensitively.
///
/// Both spellings are accepted: the enum tag (`err`, `warn`, `info`, `debug`)
/// and the word `std.log.Level` prints (`error`, `warning`, `info`, `debug`),
/// because both are what people type.
pub fn parseLevel(text: []const u8) ConfigError!Level {
    inline for (comptime std.enums.values(Level)) |level| {
        if (std.ascii.eqlIgnoreCase(text, @tagName(level))) return level;
        if (std.ascii.eqlIgnoreCase(text, level.asText())) return level;
    }
    return error.InvalidLogLevel;
}

/// Resolve the diagnostics options from a command line and an environment.
///
/// `args` includes `argv[0]`, exactly as the operating system hands it over.
///
/// Precedence is flag, then environment, then the built-in default. The flag
/// wins even when the environment variable is also set, so a person at a
/// terminal is never overruled by a stale export. Every value is taken from the
/// flag if the flag is present, otherwise from the environment, and the
/// environment is consulted at most once per setting.
pub fn parseArgs(args: []const []const u8, env: EnvSource) ConfigError!Options {
    var flag_level: ?[]const u8 = null;
    var flag_file: ?[]const u8 = null;
    var flag_dir: ?[]const u8 = null;
    var print_log_path = false;
    var help = false;
    var print_version = false;
    var run: Run = .{};
    var command: ?CliCommand = null;

    var i: usize = if (args.len == 0) 0 else 1;
    while (i < args.len) : (i += 1) {
        const arg = args[i];
        // The first word that is not a flag starts a subcommand, which takes
        // the rest of the line (TASK-66).
        if (arg.len != 0 and arg[0] != '-') {
            command = try parseCommand(args[i..]);
            break;
        }
        if (std.mem.eql(u8, arg, "--help") or std.mem.eql(u8, arg, "-h")) {
            help = true;
            break;
        } else if (std.mem.eql(u8, arg, "--version") or std.mem.eql(u8, arg, "-V")) {
            print_version = true;
            break;
        } else if (std.mem.eql(u8, arg, "--print-log-path")) {
            print_log_path = true;
        } else if (namesValue(arg, "--log-level")) {
            flag_level = try takeValue(arg, "--log-level", args, &i);
        } else if (namesValue(arg, "--log-file")) {
            flag_file = try takeValue(arg, "--log-file", args, &i);
        } else if (namesValue(arg, "--log-dir")) {
            flag_dir = try takeValue(arg, "--log-dir", args, &i);
        } else if (namesValue(arg, "--width")) {
            run.width = try parseDimension(try takeValue(arg, "--width", args, &i));
            run.size_explicit = true;
        } else if (namesValue(arg, "--height")) {
            run.height = try parseDimension(try takeValue(arg, "--height", args, &i));
            run.size_explicit = true;
        } else if (std.mem.eql(u8, arg, "--no-restore")) {
            run.no_restore = true;
        } else if (std.mem.eql(u8, arg, "--restore-test")) {
            run.restore_test = true;
        } else if (std.mem.eql(u8, arg, "--a11y-test")) {
            run.a11y_test = true;
        } else if (namesValue(arg, "--scale")) {
            run.scale = try parseScale(try takeValue(arg, "--scale", args, &i));
        } else if (namesValue(arg, "--run-ms")) {
            run.run_ms = try parseMilliseconds(try takeValue(arg, "--run-ms", args, &i));
        } else if (std.mem.eql(u8, arg, "--hidden")) {
            run.hidden = true;
        } else if (std.mem.eql(u8, arg, "--force-redraw")) {
            run.force_redraw = true;
        } else if (std.mem.eql(u8, arg, "--self-test")) {
            run.self_test = true;
        } else if (std.mem.eql(u8, arg, "--scroll-test")) {
            run.scroll_test = true;
        } else if (std.mem.eql(u8, arg, "--mouse-test")) {
            run.mouse_test = true;
        } else if (std.mem.eql(u8, arg, "--clipboard-test")) {
            run.clipboard_test = true;
        } else if (std.mem.eql(u8, arg, "--ui-test")) {
            run.ui_test = true;
        } else if (std.mem.eql(u8, arg, "--ime-test")) {
            run.ime_test = true;
        } else if (std.mem.eql(u8, arg, "--sidebar-test")) {
            run.sidebar_test = true;
        } else if (std.mem.eql(u8, arg, "--tabs-test")) {
            run.tabs_test = true;
        } else if (std.mem.eql(u8, arg, "--panes-test")) {
            run.panes_test = true;
        } else if (std.mem.eql(u8, arg, "--scratchpad-test")) {
            run.scratchpad_test = true;
        } else if (std.mem.eql(u8, arg, "--palette-test")) {
            run.palette_test = true;
        } else if (std.mem.eql(u8, arg, "--workspaces-test")) {
            run.workspaces_test = true;
        } else if (std.mem.eql(u8, arg, "--links-test")) {
            run.links_test = true;
        } else if (std.mem.eql(u8, arg, "--search-test")) {
            run.search_test = true;
        } else if (std.mem.eql(u8, arg, "--menu-test")) {
            run.menu_test = true;
        } else if (std.mem.eql(u8, arg, "--config-test")) {
            run.config_test = true;
        } else if (std.mem.eql(u8, arg, "--theme-test")) {
            run.theme_test = true;
        } else if (std.mem.eql(u8, arg, "--settings-test")) {
            run.settings_test = true;
        } else if (std.mem.eql(u8, arg, "--profiles-test")) {
            run.profiles_test = true;
        } else if (std.mem.eql(u8, arg, "--git-test")) {
            run.git_test = true;
        } else if (std.mem.eql(u8, arg, "--agent-test")) {
            run.agent_test = true;
        } else if (std.mem.eql(u8, arg, "--agent-view-test")) {
            run.agent_test = true;
            run.agent_view_test = true;
        } else if (std.mem.eql(u8, arg, "--agent-manager-test")) {
            run.agent_test = true;
            run.agent_manager_test = true;
        } else if (std.mem.eql(u8, arg, "--agent-prompts-test")) {
            run.agent_test = true;
            run.agent_prompts_test = true;
        } else if (std.mem.eql(u8, arg, "--backlog-test")) {
            run.agent_test = true;
            run.backlog_test = true;
        } else if (std.mem.eql(u8, arg, "--control-test")) {
            run.agent_test = true;
            run.control_test = true;
        } else if (std.mem.eql(u8, arg, "--control")) {
            run.control = true;
        } else if (std.mem.eql(u8, arg, "--no-control")) {
            run.control = false;
        } else if (std.mem.eql(u8, arg, "--ssh-test")) {
            run.ssh_test = true;
        } else if (std.mem.eql(u8, arg, "--font-test")) {
            run.font_test = true;
        } else if (namesValue(arg, "--right-click")) {
            run.right_click = config.RightClick.parse(try takeValue(arg, "--right-click", args, &i)) catch
                return error.InvalidRightClick;
        } else if (namesValue(arg, "--test-driver")) {
            run.test_driver_endpoint = try takeValue(arg, "--test-driver", args, &i);
        } else if (namesValue(arg, "--test-artifact-dir")) {
            run.test_artifact_dir = try takeValue(arg, "--test-artifact-dir", args, &i);
        } else if (std.mem.eql(u8, arg, "--driver-test")) {
            run.driver_test = true;
        } else if (namesValue(arg, "--command")) {
            run.command = try takeValue(arg, "--command", args, &i);
        } else if (namesValue(arg, "--screenshot")) {
            run.screenshot = try takeValue(arg, "--screenshot", args, &i);
        } else if (namesValue(arg, "--font")) {
            run.font_family = try takeValue(arg, "--font", args, &i);
        } else if (std.mem.eql(u8, arg, "--grid-test")) {
            run.grid_test = true;
        } else if (std.mem.eql(u8, arg, "--no-child")) {
            run.no_child = true;
        } else if (std.mem.eql(u8, arg, "--no-shell-integration")) {
            run.no_shell_integration = true;
        } else {
            return error.UnknownFlag;
        }
    }

    // The environment is only read for a setting the flag did not already
    // decide, which is what makes "flag beats environment" true by
    // construction rather than by an ordering argument.
    const level_text = flag_level orelse env.get(level_env);
    const dir = flag_dir orelse env.get(dir_env) orelse firstEnv(env, temp_dir_vars[0..]) orelse fallback_log_dir;

    return .{
        .level = if (level_text) |text| try parseLevel(text) else default_level,
        .file = flag_file orelse env.get(file_env),
        .dir = dir,
        .print_log_path = print_log_path,
        .help = help,
        .print_version = print_version,
        .run = run,
        .command = command,
    };
}

/// Parse a subcommand: `words[0]` is its first word. Pure, like `parseArgs`.
///
/// `ssh`, `workspace`, `agent` and `control` are commands; any other word is
/// a directory (`./ssh` names a directory called `ssh`).
pub fn parseCommand(words: []const []const u8) ConfigError!CliCommand {
    std.debug.assert(words.len != 0);
    const first = words[0];
    const rest = words[1..];
    if (std.mem.eql(u8, first, "ssh")) {
        if (rest.len == 0 or rest[0].len == 0) return error.MissingArgument;
        if (rest.len > 1) return error.UnexpectedArgument;
        return .{ .open_ssh = rest[0] };
    }
    if (std.mem.eql(u8, first, "workspace")) {
        if (rest.len == 0) return error.MissingArgument;
        if (!std.mem.eql(u8, rest[0], "open")) return error.UnknownCommand;
        if (rest.len < 2 or rest[1].len == 0) return error.MissingArgument;
        if (rest.len > 2) return error.UnexpectedArgument;
        return .{ .open_workspace = rest[1] };
    }
    if (std.mem.eql(u8, first, "agent")) {
        if (rest.len == 0 or rest[0].len == 0) return error.MissingArgument;
        return .{ .agent = .{ .harness = rest[0], .prompt = rest[1..] } };
    }
    if (std.mem.eql(u8, first, "control")) {
        if (rest.len == 0 or rest[0].len == 0 or rest[0][0] == '-') return error.MissingArgument;
        var parsed: @FieldType(CliCommand, "control") = .{ .method = rest[0] };
        for (rest[1..]) |word| {
            if (std.mem.startsWith(u8, word, "--event=")) {
                parsed.event = word["--event=".len..];
                if (parsed.event.?.len == 0) return error.MissingValue;
            } else if (std.mem.startsWith(u8, word, "--agent=")) {
                parsed.agent = word["--agent=".len..];
                if (parsed.agent.?.len == 0) return error.MissingValue;
            } else if (parsed.params == null and (word.len == 0 or word[0] != '-')) {
                parsed.params = word;
            } else return error.UnexpectedArgument;
        }
        return .{ .control = parsed };
    }
    if (rest.len != 0) return error.UnexpectedArgument;
    return .{ .open_directory = first };
}

/// The value of the first of `keys` that the environment sets.
fn firstEnv(env: EnvSource, keys: []const []const u8) ?[]const u8 {
    for (keys) |key| {
        if (env.get(key)) |value| return value;
    }
    return null;
}

/// Whether `arg` names `name` as a value-taking flag, in either the
/// `--name=value` or the bare `--name` spelling. The value itself is read by
/// `takeValue`; this only decides which branch of the walk a flag belongs to.
fn namesValue(arg: []const u8, name: []const u8) bool {
    if (std.mem.eql(u8, arg, name)) return true;
    return std.mem.startsWith(u8, arg, name) and arg.len > name.len and arg[name.len] == '=';
}

/// Read the value of a flag that `namesValue` matched, and leave `i` pointing at
/// the next unread argument in both spellings.
///
/// A missing or empty value is `error.MissingValue` rather than a silent
/// fallback: `--log-level` with nothing after it is a mistake in the command
/// line, and quietly logging at a different level than the one that was typed
/// is the worst possible answer to that mistake.
fn takeValue(arg: []const u8, name: []const u8, args: []const []const u8, i: *usize) ConfigError![]const u8 {
    if (std.mem.eql(u8, arg, name)) {
        if (i.* + 1 >= args.len) return error.MissingValue;
        const value = args[i.* + 1];
        // A value that looks like the next flag is a missing value, not a value.
        if (value.len == 0 or std.mem.startsWith(u8, value, "-")) return error.MissingValue;
        i.* += 1;
        return value;
    }
    const value = arg[name.len + 1 ..];
    // A value that looks like a flag is a missing value in this spelling too:
    // `--log-level=--dir` is a mistyped command line, not a level named
    // "--dir".
    if (value.len == 0 or std.mem.startsWith(u8, value, "-")) return error.MissingValue;
    return value;
}

// ---------------------------------------------------------------------------
// Per-run paths
// ---------------------------------------------------------------------------

/// A per-run identifier: `run-20261004T213800Z-112233`.
///
/// The timestamp makes a run readable at a glance; the random bytes are what
/// make it unique. Uniqueness is not merely probable: the generated file is
/// opened with `exclusive = true`, so a collision is a detectable error and
/// never a silent overwrite.
pub fn runIdPattern(buf: []u8, stamp: []const u8, random: [3]u8) std.fmt.BufPrintError![]const u8 {
    return std.fmt.bufPrint(buf, "run-{s}-{x:0>2}{x:0>2}{x:0>2}", .{
        stamp,
        random[0],
        random[1],
        random[2],
    });
}

/// Seconds since the epoch at 9999-12-31T23:59:59Z. A clock beyond that is
/// not a plausible date, and clamping it keeps the year loop bounded.
const max_stamp_seconds: i96 = 253_402_300_799;

/// The UTC stamp inside a run id: `YYYYMMDDTHHMMSSZ`.
///
/// The input is clamped rather than trusted: the clock is external input, and
/// a nonsensical value must produce a stamp, not a five-hundred-billion-iteration
/// loop in `calculateYearDay`.
pub fn stampPattern(buf: []u8, epoch_seconds: i96) std.fmt.BufPrintError![]const u8 {
    const clamped = std.math.clamp(epoch_seconds, 0, max_stamp_seconds);
    const seconds = std.time.epoch.EpochSeconds{ .secs = @intCast(clamped) };
    const year_day = seconds.getEpochDay().calculateYearDay();
    const month_day = year_day.calculateMonthDay();
    const day_seconds = seconds.getDaySeconds();
    const year: u16 = year_day.year;
    const month: u8 = @intCast(@intFromEnum(month_day.month));
    const day: u32 = @intCast(month_day.day_index + 1);
    const hours: u32 = day_seconds.getHoursIntoDay();
    const minutes: u32 = day_seconds.getMinutesIntoHour();
    const seconds_of_minute: u32 = day_seconds.getSecondsIntoMinute();
    return std.fmt.bufPrint(buf, "{d:0>4}{d:0>2}{d:0>2}T{d:0>2}{d:0>2}{d:0>2}Z", .{
        year,
        month,
        day,
        hours,
        minutes,
        seconds_of_minute,
    });
}

/// Join `dir` and `name` with the platform separator.
pub fn joinPath(buf: []u8, dir: []const u8, name: []const u8) std.fmt.BufPrintError![]const u8 {
    return std.fmt.bufPrint(buf, "{s}{c}{s}", .{ dir, std.fs.path.sep, name });
}

/// The crash report path belonging to a log file: the log's name with its
/// `.log` suffix replaced by `.crash.txt`, so a report is always found beside
/// the log it explains and never mistaken for a log itself.
pub fn crashPathFor(buf: []u8, log_path: []const u8) std.fmt.BufPrintError![]const u8 {
    const stem = if (std.mem.endsWith(u8, log_path, ".log"))
        log_path[0 .. log_path.len - ".log".len]
    else
        log_path;
    return std.fmt.bufPrint(buf, "{s}.crash.txt", .{stem});
}

// ---------------------------------------------------------------------------
// The sink
// ---------------------------------------------------------------------------

/// How much of one formatted log line is kept. A longer line is truncated with
/// a marker rather than dropped: a truncated log line is still evidence.
const line_capacity = 1024;
/// The write buffer in front of the log file.
const file_buffer_capacity = 8192;
/// How much of the end of the log a crash report carries.
pub const log_tail_capacity = 16 * 1024;

/// Why a log file could not be opened. A bad path or a full disk lands here and
/// leaves the app running on stderr, rather than in a crash.
pub const LogFileError = error{CannotCreateLogFile};

/// The one process-wide log destination.
///
/// It is a global because `std.options.logFn` is a bare function with no
/// userdata: the standard library's logging seam leaves the app no way to pass a
/// receiver. Everything it owns is installed once in `main`, before any other
/// module runs, and released on the way out. The mutex is what makes a line
/// from the PTY, render or agent threads arrive whole.
const Sink = struct {
    mutex: Io.Mutex = .init,
    io: Io = undefined,
    /// False until `install` succeeds, so a log call made before `main` — or
    /// after `deinit` — is dropped rather than reading uninitialised memory.
    installed: bool = false,
    level: Level = default_level,

    file: ?File.Writer = null,
    file_buffer: [file_buffer_capacity]u8 = undefined,
    log_path_buffer: [path_capacity]u8 = undefined,
    log_path_len: usize = 0,
    crash_path_buffer: [path_capacity]u8 = undefined,
    crash_path_len: usize = 0,
    /// Bounded in-memory tail used by the test driver without filesystem IO on
    /// the render thread. Bytes are kept in chronological order.
    tail_buffer: [log_tail_capacity]u8 = undefined,
    tail_len: usize = 0,

    /// This run's log file path. Empty when no file was opened.
    fn logPath(self: *const Sink) []const u8 {
        return self.log_path_buffer[0..self.log_path_len];
    }

    /// Where a panic in this run writes its report.
    fn crashPath(self: *const Sink) []const u8 {
        return self.crash_path_buffer[0..self.crash_path_len];
    }

    /// Set the level and start routing to stderr, then open the log file.
    ///
    /// The sink is marked installed before the file is opened: a log file
    /// that cannot be created costs the file, not the run, so stderr keeps
    /// working and the resolved level keeps applying. That is why `install`
    /// reports `LogFileError` without leaving the sink unusable.
    fn install(self: *Sink, io: Io, options: Options) LogFileError!void {
        self.deinit();
        self.io = io;
        self.level = options.level;
        self.installed = true;
        var generated: [path_capacity]u8 = undefined;
        var generated_crash: [path_capacity]u8 = undefined;
        const log_path: []const u8 = if (options.file) |exact| exact else blk: {
            Dir.cwd().createDirPath(io, options.dir) catch return error.CannotCreateLogFile;

            var id_buffer: [path_capacity]u8 = undefined;
            const id = generateRunId(io, &id_buffer) catch return error.CannotCreateLogFile;
            var name_buffer: [path_capacity]u8 = undefined;
            const name = std.fmt.bufPrint(&name_buffer, "{s}.log", .{id}) catch
                return error.CannotCreateLogFile;
            break :blk joinPath(&generated, options.dir, name) catch return error.CannotCreateLogFile;
        };
        const crash_path = crashPathFor(&generated_crash, log_path) catch return error.CannotCreateLogFile;

        // An exact path is the caller's to reuse, so it is truncated. A
        // generated name must never land on an existing file, so it is created
        // exclusively: a collision fails loudly instead of overwriting a
        // concurrent run's log.
        const generated_name = options.file == null;
        const file = Dir.cwd().createFile(io, log_path, .{
            .truncate = !generated_name,
            .exclusive = generated_name,
        }) catch return error.CannotCreateLogFile;

        self.file = file.writerStreaming(io, &self.file_buffer);
        @memcpy(self.log_path_buffer[0..log_path.len], log_path);
        self.log_path_len = log_path.len;
        @memcpy(self.crash_path_buffer[0..crash_path.len], crash_path);
        self.crash_path_len = crash_path.len;
    }

    /// Flush and close the log file. Safe to call more than once.
    fn deinit(self: *Sink) void {
        if (self.file) |*writer| {
            writer.interface.flush() catch {};
            writer.file.close(self.io);
        }
        self.file = null;
        self.log_path_len = 0;
        self.crash_path_len = 0;
        self.tail_len = 0;
        self.installed = false;
    }

    /// Copy at most `destination.len` bytes from the current log tail.
    ///
    /// The caller supplies storage so reading logs never touches the filesystem
    /// or allocates while holding the process-wide log mutex.
    fn copyTail(self: *Sink, destination: []u8) []const u8 {
        if (destination.len == 0) return destination[0..0];
        self.mutex.lockUncancelable(self.io);
        defer self.mutex.unlock(self.io);
        const count = @min(destination.len, self.tail_len);
        @memcpy(destination[0..count], self.tail_buffer[self.tail_len - count .. self.tail_len]);
        if (count == self.tail_len) return destination[0..count];
        const newline = std.mem.indexOfScalar(u8, destination[0..count], '\n') orelse
            return destination[0..count];
        return destination[newline + 1 .. count];
    }

    fn appendTailLocked(self: *Sink, bytes: []const u8) void {
        if (bytes.len >= self.tail_buffer.len) {
            const suffix = bytes[bytes.len - self.tail_buffer.len ..];
            @memcpy(self.tail_buffer[0..], suffix);
            self.tail_len = self.tail_buffer.len;
            return;
        }
        const overflow = bytes.len -| (self.tail_buffer.len - self.tail_len);
        if (overflow != 0) {
            std.mem.copyForwards(
                u8,
                self.tail_buffer[0 .. self.tail_len - overflow],
                self.tail_buffer[overflow..self.tail_len],
            );
            self.tail_len -= overflow;
        }
        @memcpy(self.tail_buffer[self.tail_len .. self.tail_len + bytes.len], bytes);
        self.tail_len += bytes.len;
    }

    /// Flush and close the log file, leaving the sink installed and routing to
    /// stderr.
    ///
    /// `deinit` is the full teardown; this is what `main` calls on its way out.
    /// The debug allocator's leak report runs *after* `main` returns and reaches
    /// the program through `std.options.logFn`, which is this sink — so a sink
    /// that had gone quiet here would swallow every leak line, and "closes
    /// cleanly with no leaks" would be a claim nobody could check.
    fn closeFile(self: *Sink) void {
        if (self.file) |*writer| {
            writer.interface.flush() catch {};
            writer.file.close(self.io);
        }
        self.file = null;
    }
};

/// The destination installed by `main`. Read by every `std.log` call in the
/// program, and by the panic handler.
var sink: Sink = .{};

fn environGet(ctx: *const anyopaque, key: []const u8) ?[]const u8 {
    const map: *const std.process.Environ.Map = @ptrCast(@alignCast(ctx));
    return map.get(key);
}

fn environEntry(ctx: *const anyopaque, index: usize) ?EnvSource.Entry {
    const map: *const std.process.Environ.Map = @ptrCast(@alignCast(ctx));
    const keys = map.keys();
    if (index >= keys.len) return null;
    return .{ .key = keys[index], .value = map.values()[index] };
}

/// This process's environment, as an `EnvSource`.
pub fn processEnv(init: std.process.Init) EnvSource {
    return .{ .ctx = init.environ_map, .getFn = environGet, .entryFn = environEntry };
}

/// Build a fresh, unique run id from the wall clock and the entropy source.
fn generateRunId(io: Io, buf: []u8) ![]const u8 {
    var stamp_buffer: [32]u8 = undefined;
    const now = Io.Clock.real.now(io);
    const stamp = try stampPattern(&stamp_buffer, @divTrunc(now.nanoseconds, std.time.ns_per_s));
    var random: [3]u8 = undefined;
    io.random(&random);
    return runIdPattern(buf, stamp, random);
}

/// Whether `level` passes the sink's current level.
fn enabled(level: Level) bool {
    return sink.installed and @intFromEnum(level) <= @intFromEnum(sink.level);
}

/// `std.options.logFn`. Writes one line to stderr and to the log file.
fn appLog(comptime level: Level, comptime scope: @EnumLiteral(), comptime format: []const u8, args: anytype) void {
    emit(level, scope, format, args);
}

/// Log a line only ever at `debug` level, in the `.sensitive` scope.
///
/// This is the only sanctioned way to put terminal contents, clipboard data,
/// credentials or agent prompts into the log (CONDUIT.md §11, AGENTS.md). It
/// takes no level: the level is `debug`, unconditionally, and `emit` refuses to
/// write the `.sensitive` scope above `debug` even when some other caller asks
/// it to. A caller therefore cannot move such content above debug by choosing
/// `--log-level` or by setting `CONDUIT_LOG_LEVEL`.
pub fn sensitiveLog(comptime format: []const u8, args: anytype) void {
    emit(.debug, .sensitive, format, args);
}

/// Format and dispatch one log line.
fn emit(comptime level: Level, comptime scope: @EnumLiteral(), comptime format: []const u8, args: anytype) void {
    // The clamp is redundant while `sensitiveLog` is the only caller of the
    // `.sensitive` scope, and that is exactly why it stays: the safety property
    // keeps holding when that is no longer true.
    if (scope == .sensitive and level != .debug) return;
    if (!enabled(level)) return;

    var buffer: [line_capacity]u8 = undefined;
    var writer: Writer = .fixed(&buffer);
    writeTimestamp(&writer, sink.io) catch {};
    writer.writeByte(' ') catch {};
    writer.writeAll(level.asText()) catch {};
    writer.writeByte('(') catch {};
    writer.writeAll(@tagName(scope)) catch {};
    writer.writeAll("): ") catch {};
    writer.print(format, args) catch {};
    // A line that filled the buffer has no room for the newline, so the last
    // byte becomes it. The line is truncated either way; this keeps every line
    // in the file terminated, which is what makes the log tail readable.
    if (writer.end == buffer.len) {
        buffer[buffer.len - 1] = '\n';
    } else {
        writer.writeByte('\n') catch {};
    }

    const line = writer.buffered();
    sink.mutex.lockUncancelable(sink.io);
    defer sink.mutex.unlock(sink.io);
    sink.appendTailLocked(line);
    writeStderr(level, line);
    if (sink.file) |*file| {
        file.interface.writeAll(line) catch {};
        file.interface.flush() catch {};
    }
}

/// The same line to stderr, with the level in colour, matching what the
/// standard library's own default log function looks like.
fn writeStderr(level: Level, line: []const u8) void {
    var buffer: [line_capacity]u8 = undefined;
    const stderr = std.debug.lockStderr(&buffer).terminal();
    defer std.debug.unlockStderr();

    stderr.setColor(switch (level) {
        .err => .red,
        .warn => .yellow,
        .info => .green,
        .debug => .magenta,
    }) catch {};
    stderr.setColor(.bold) catch {};
    stderr.writer.writeAll(line) catch {};
    stderr.setColor(.reset) catch {};
    stderr.writer.flush() catch {};
}

/// `2026-10-04T21:38:00.123Z`, from the wall clock in UTC.
fn writeTimestamp(writer: *Writer, io: Io) Writer.Error!void {
    const now = Io.Clock.real.now(io);
    const epoch = std.time.epoch.EpochSeconds{
        .secs = @intCast(@max(@divTrunc(now.nanoseconds, std.time.ns_per_s), 0)),
    };
    const year_day = epoch.getEpochDay().calculateYearDay();
    const month_day = year_day.calculateMonthDay();
    const day_seconds = epoch.getDaySeconds();
    const year: u16 = year_day.year;
    const month: u8 = @intCast(@intFromEnum(month_day.month));
    const day: u32 = @intCast(month_day.day_index + 1);
    const hours: u32 = day_seconds.getHoursIntoDay();
    const minutes: u32 = day_seconds.getMinutesIntoHour();
    const seconds: u32 = day_seconds.getSecondsIntoMinute();
    const millis: u32 = @intCast(@divTrunc(@mod(now.nanoseconds, std.time.ns_per_s), std.time.ns_per_ms));
    try writer.print("{d:0>4}-{d:0>2}-{d:0>2}T{d:0>2}:{d:0>2}:{d:0>2}.{d:0>3}Z", .{
        year,
        month,
        day,
        hours,
        minutes,
        seconds,
        millis,
    });
}

// ---------------------------------------------------------------------------
// Crash reports
// ---------------------------------------------------------------------------

/// A re-entry guard: a fault inside the reporter must not start another one,
/// and `std.debug.defaultPanic` is what actually stops the process.
var reporting_crash = std.atomic.Value(bool).init(false);

/// What a crash report is written from. `log_path` and `crash_path` are `null`
/// when logging was never installed, which is the case for a fault before
/// `main` reaches `install`.
pub const CrashReport = struct {
    message: []const u8,
    log_path: ?[]const u8 = null,
    crash_path: ?[]const u8 = null,
    first_address: ?usize = null,
};

/// Write a crash report: the panic message, the stack trace, and the tail of
/// this run's log.
///
/// The report goes to `crash_path`, which is the log file's own name with a
/// `.crash.txt` suffix, so `--print-log-path` is enough to find both. Every
/// failure here is swallowed on purpose: the process is already dying, the
/// report is a best effort, and a second fault inside the reporter would hide
/// the first. `std.debug.defaultPanic` still prints the message and the trace
/// to stderr, so a report that could not be written costs the log tail and
/// nothing else.
pub fn writeCrashReport(io: Io, report: CrashReport) void {
    if (reporting_crash.swap(true, .acq_rel)) return;
    defer reporting_crash.store(false, .release);

    const path = report.crash_path orelse return;
    const file = Dir.cwd().createFile(io, path, .{ .truncate = true }) catch return;
    defer file.close(io);

    var buffer: [file_buffer_capacity]u8 = undefined;
    var writer = file.writerStreaming(io, &buffer);
    const out = &writer.interface;

    var target_buffer: [64]u8 = undefined;
    out.print("conduit crash report\n", .{}) catch {};
    out.print("version: {s}\n", .{version}) catch {};
    out.print("target: {s}\n", .{buildTarget(&target_buffer) catch "unknown"}) catch {};
    out.print("log file: {s}\n", .{report.log_path orelse "(none)"}) catch {};
    out.print("panic: {s}\n", .{report.message}) catch {};
    out.writeAll("\n--- stack trace ---\n") catch {};
    std.debug.writeCurrentStackTrace(
        .{ .first_address = report.first_address },
        .{ .writer = out, .mode = .no_color },
    ) catch {};
    out.writeAll("\n--- log tail ---\n") catch {};

    var tail: [log_tail_capacity]u8 = undefined;
    if (readLogTail(io, report.log_path orelse "", &tail)) |bytes| {
        out.writeAll(bytes) catch {};
    } else {
        out.writeAll("(no log tail available)\n") catch {};
    }
    out.flush() catch {};
}

/// The last `buffer.len` bytes of `path`, trimmed to start at a line boundary
/// so the tail reads as whole lines rather than as a fragment of one.
fn readLogTail(io: Io, path: []const u8, buffer: []u8) ?[]const u8 {
    if (path.len == 0 or buffer.len == 0) return null;
    const file = Dir.cwd().openFile(io, path, .{}) catch return null;
    defer file.close(io);
    const length = file.length(io) catch return null;
    if (length == 0) return null;
    const start = if (length > buffer.len) length - buffer.len else 0;
    // `readPositionalAll` insists on filling the whole buffer, so the buffer is
    // trimmed to what is actually there. A log shorter than the buffer is the
    // common case at the moment of an early crash.
    const want: usize = @intCast(@min(length - start, buffer.len));
    const read = file.readPositionalAll(io, buffer[0..want], start) catch return null;
    const window = buffer[0..read];
    if (start == 0) return window;
    const newline = std.mem.indexOfScalar(u8, window, '\n') orelse return window;
    return window[newline + 1 ..];
}

/// The panic handler: write the report, then hand over to the standard library
/// so the message and the trace still reach stderr and the process still aborts.
fn onPanic(message: []const u8, first_trace_addr: ?usize) noreturn {
    const io = if (sink.installed) sink.io else std.Options.debug_io;
    writeCrashReport(io, .{
        .message = message,
        .log_path = if (sink.installed) sink.logPath() else null,
        .crash_path = if (sink.installed) sink.crashPath() else null,
        .first_address = first_trace_addr,
    });
    std.debug.defaultPanic(message, first_trace_addr);
}

// ---------------------------------------------------------------------------
// The window, the surface and the loop
// ---------------------------------------------------------------------------

/// The colour the surface is cleared to before the theme is resolved: the
/// default palette's background. A surface that has never had anything drawn
/// into it is this colour, so a window that has just opened shows a terminal's
/// background rather than a hole. `App.background` follows the active theme.
pub const background: render.Rgba = surfaceColor(default_palette.get(.background));

/// The window title. A window manager's task list, a screenshot's header and a
/// log reader all name the app from here.
pub const window_title: [:0]const u8 = "conduit";

/// What the loop should do next.
///
/// Render-on-demand is one bit: the loop draws when something changed what should
/// be on screen — the first frame, a resize, a display-scale change, an expose —
/// and does nothing at all otherwise. `force` is the one exception, and it exists
/// so the cost of this can be measured against the cost of not doing it.
pub const Scheduler = struct {
    /// Whether what is on the surface no longer matches what the app wants there.
    dirty: bool,
    /// Whether to draw every iteration whatever else is true.
    force: bool,
    /// How many frames have been drawn. A count is how `--self-test` shows that an
    /// idle window drew none.
    frames: u64,

    /// A scheduler with one frame owed: there is nothing on the surface until one
    /// is drawn, so the very first iteration must draw.
    pub fn init(force: bool) Scheduler {
        return .{ .dirty = true, .force = force, .frames = 0 };
    }

    /// Something happened that changes what the surface should look like.
    pub fn invalidate(self: *Scheduler) void {
        self.dirty = true;
    }

    /// Whether this iteration of the loop draws a frame.
    pub fn shouldDraw(self: *const Scheduler) bool {
        return self.dirty or self.force;
    }

    /// Record that a frame has been drawn. The surface is clean again until
    /// something invalidates it.
    pub fn drawn(self: *Scheduler) void {
        self.dirty = false;
        self.frames += 1;
    }
};

/// When an owed frame is drawn while child output keeps arriving.
///
/// Draining and drawing are separate steps of the loop. Without pacing, a
/// flood would still draw once per wake, and on a software renderer a frame
/// costs far more than the bytes it shows. While output is active (this wake
/// drained bytes, or a session is still readable) an owed frame waits until
/// the previous one is at least `interval` old; the moment output pauses, an
/// owed frame is drawn at once. The interval is the longer of one 60 Hz
/// display period and the last frame's own cost, so a slow renderer spends at
/// most about half of a flood drawing rather than all of it. Pure state plus
/// timestamps, so the policy is tested without a window or a clock.
pub const FramePacer = struct {
    /// One display period at 60 Hz, in nanoseconds.
    pub const min_interval_ns: u64 = 16 * std.time.ns_per_ms;
    /// How long a deferred frame waits for more output when none is readable
    /// right now, in milliseconds. A reader thread that is mid-read looks
    /// idle for an instant; this grace keeps that instant from counting as
    /// a pause, and is short enough that a real pause still draws promptly.
    pub const pause_grace_ms: i32 = 1;

    /// When the last frame finished, on the awake clock; null before the first.
    last_frame_end_ns: ?i96 = null,
    /// How long the last frame took to draw.
    last_frame_cost_ns: u64 = 0,

    /// The shortest gap between frames while output is active.
    pub fn interval(self: *const FramePacer) u64 {
        return @max(min_interval_ns, self.last_frame_cost_ns);
    }

    /// Whether an owed frame is drawn now. `output_active` says the wake
    /// drained bytes or a session still has output waiting.
    pub fn shouldDraw(self: *const FramePacer, owed: bool, output_active: bool, now_ns: i96) bool {
        if (!owed) return false;
        if (!output_active) return true;
        return self.untilDueNs(now_ns) == 0;
    }

    /// Nanoseconds until a frame is due under the active-output interval.
    pub fn untilDueNs(self: *const FramePacer, now_ns: i96) u64 {
        const last = self.last_frame_end_ns orelse return 0;
        const age = now_ns - last;
        const gap: i96 = @intCast(self.interval());
        if (age >= gap) return 0;
        if (age <= 0) return self.interval();
        return @intCast(gap - age);
    }

    /// The longest the loop may wait for an event while a frame is deferred:
    /// nothing while output is still readable, otherwise the pause grace,
    /// which is far shorter than any interval, so a deferred frame is never
    /// held much past the moment it falls due.
    pub fn deferredWaitMs(readable: bool) i32 {
        return if (readable) 0 else pause_grace_ms;
    }

    /// Record a frame drawn between `started_ns` and `ended_ns`.
    pub fn noteFrame(self: *FramePacer, started_ns: i96, ended_ns: i96) void {
        self.last_frame_end_ns = ended_ns;
        self.last_frame_cost_ns = if (ended_ns > started_ns) @intCast(ended_ns - started_ns) else 0;
    }
};

/// The surface size a window state implies.
fn surfaceSize(state: platform.State) render.Size {
    return .{ .width = state.surface.width_px, .height = state.surface.height_px };
}

/// A font manager and a child process, built on a worker thread.
///
/// Ownership: the worker allocates with the app's allocator and publishes what
/// it built; the render thread takes those values once `finished` says so, and
/// nothing touches them in between. The publish is a release store and every
/// read an acquire, which is what makes the `Manager` and the `Pty` visible to
/// the thread that takes them without a second lock.
///
/// `io` is used from both threads, which is what Zig 0.16's `Io` is for —
/// `std.Io.Threaded` documents itself as thread-safe, and the only IO here is
/// listing font directories and opening files.
const Load = struct {
    allocator: Allocator,
    io: Io,
    /// The face to build, or null when this job is only spawning a child.
    font_request: ?font.Request = null,
    /// The secondary small face built after `font_request` (TASK-76), or
    /// null. Its failure is not the job's failure: small text then draws at
    /// the normal size.
    small_font_request: ?font.Request = null,
    /// The owned settings every string of `font_request` borrows. A reload may
    /// replace the app's settings while this worker still reads them, so the
    /// job keeps its own copy.
    font_settings_owned: ?FontSettings = null,
    /// `FontValues.faceKey` of the face `font_request` builds.
    font_key: u64 = 0,
    /// The child to start, or null when this job is only loading a face.
    spawn: ?pty.SpawnRequest = null,
    /// A copied cwd used by `spawn`, or null when the request borrows the
    /// workspace's stable default. A newly tracked terminal cwd may change on
    /// the next feed, so an asynchronous worker may never borrow it.
    spawn_cwd: ?[]u8 = null,
    /// Owned argv used by `spawn` instead of the app-level child spec, or null
    /// when the request borrows that stable spec. A file-reference editor is
    /// built per job from terminal-derived text and dies with the job.
    spawn_argv: ?[][]const u8 = null,
    /// Owned environment used by `spawn` instead of the app-level child spec:
    /// that spec plus this session's control variables (TASK-60). Null when
    /// the request borrows the stable spec.
    spawn_env: ?[][]const u8 = null,
    /// The stable session that requested `spawn`. Selection may change while
    /// the worker runs, but ownership of its result may not.
    spawn_session_id: ?session.SessionId = null,
    /// The registry workspace that owns a spawn result. Session identifiers
    /// are workspace-local and are not sufficient attribution on their own.
    workspace_key: ?workspace.WorkspaceKey = null,
    /// This job spawned a transactional scratchpad replacement rather than a
    /// child for a starting session.
    scratchpad_replacement: bool = false,
    /// This job restarts a session whose child ended (an SSH reconnect,
    /// TASK-43): the result replaces that child under the same id.
    respawn: bool = false,
    /// The launched agent whose adapter describes this spawn (TASK-56). Its
    /// `prepare` runs here, before the spawn, and fills argv and env; the
    /// runtime keeps the runner alive until this job is reported finished.
    agent_runner: ?*app_agents.Runner = null,
    /// Borrowed from the workspace that owns this job's target session. The
    /// owner outlives and joins the worker before releasing its context.
    execution_context: ?workspace.ExecutionContext.Ref = null,
    /// Zero while the worker runs, one once the values below may be read.
    state: std.atomic.Value(u32) = std.atomic.Value(u32).init(0),
    fonts: ?font.Manager = null,
    small_fonts: ?font.Manager = null,
    child: ?pty.Pty = null,
    /// Failures as names rather than as errors: a log line outlives the error
    /// set that produced it, and the app carries on either way.
    font_failure: ?[]const u8 = null,
    spawn_failure: ?[]const u8 = null,
    thread: ?std.Thread = null,
    /// The window whose loop is woken once the result is published, so a
    /// finished spawn or face is collected at once rather than at the next
    /// idle tick (TASK-67). `postDriverWake` is thread-safe and the window
    /// outlives every job; null for a job nobody waits on through the loop.
    waker: ?*const platform.Window = null,

    fn start(self: *Load, waker: ?*const platform.Window) !void {
        self.waker = waker;
        self.thread = try std.Thread.spawn(.{}, work, .{self});
    }

    fn finished(self: *const Load) bool {
        return self.state.load(.acquire) != 0;
    }

    /// Release the copied cwd and owned argv a spawn job carried. Safe on
    /// every completion and failure path once the worker is no longer running.
    fn freeSpawnInputs(self: *Load) void {
        if (self.font_settings_owned) |*settings| settings.deinit();
        self.font_settings_owned = null;
        if (self.spawn_cwd) |cwd| self.allocator.free(cwd);
        self.spawn_cwd = null;
        if (self.spawn_argv) |argv| freeEntries(self.allocator, argv);
        self.spawn_argv = null;
        if (self.spawn_env) |env| freeEntries(self.allocator, env);
        self.spawn_env = null;
    }

    fn work(worker_context: *anyopaque) void {
        const self: *Load = @ptrCast(@alignCast(worker_context));
        // Copied first: once `state` is published the owner may collect the
        // job, although it joins this thread before freeing it.
        const waker = self.waker;
        self.produce();
        self.state.store(1, .release);
        if (waker) |window| window.postDriverWake() catch |err| {
            // The loop still collects the job at its next idle tick.
            log.debug("could not wake the loop for a finished load: {s}", .{@errorName(err)});
        };
    }

    fn produce(self: *Load) void {
        if (self.font_request) |request| {
            const fonts = font.Manager.init(self.allocator, self.io, request);
            if (fonts) |loaded| {
                self.fonts = loaded;
                if (self.small_font_request) |small_request| {
                    if (font.Manager.init(self.allocator, self.io, small_request)) |small| {
                        self.small_fonts = small;
                    } else |err| log.warn("the small UI face could not be loaded: {s}", .{@errorName(err)});
                }
            } else |err| {
                self.font_failure = @errorName(err);
            }
        }
        if (self.spawn) |spawn_request| {
            const context = self.execution_context orelse {
                self.spawn_failure = "MissingExecutionContext";
                return;
            };
            var request = spawn_request;
            if (self.agent_runner) |runner| {
                const prepared = runner.prepare(request.env) catch |err| {
                    self.spawn_failure = @errorName(err);
                    return;
                };
                request.argv = prepared.argv;
                request.env = prepared.env;
            }
            const child = context.spawn(request);
            if (child) |spawned| {
                self.child = spawned;
            } else |err| {
                self.spawn_failure = @errorName(err);
            }
        }
    }
};

/// The git branch shown under one session's tab (TASK-76).
///
/// Thread ownership: the owner (UI) thread. The only worker is `lookup`,
/// which owns its own copy of the cwd; `App.pollGit` finishes it. `watch`
/// belongs to the owner thread like every `WatchHandle`.
///
/// Refreshes are event-driven, never per frame: a new OSC 7 cwd, an OSC 133
/// prompt start (a checkout has finished by the next prompt), a terminal
/// reset, or the Local context's watch on the git directory reporting a
/// change. Each refresh is at most one bounded `git.resolve` on a worker; no
/// git process is ever started.
const GitTrack = struct {
    key: workspace.WorkspaceKey,
    session_id: session.SessionId,
    /// A refresh is owed. Set by events, consumed when a lookup starts.
    stale: bool = true,
    lookup: ?*git.Lookup = null,
    /// Whether `repo` describes the session's current cwd.
    found: bool = false,
    repo: git.Repo = .{ .head = .{ .kind = .branch } },
    /// A Local watch on `repo.gitDir()`, so a checkout made elsewhere (or a
    /// `HEAD` rewritten without a new prompt) refreshes too.
    watch: ?workspace.WatchHandle = null,

    /// Join any worker and release the watch. The context the lookup borrows
    /// must still be alive.
    fn release(self: *GitTrack) void {
        if (self.lookup) |job| {
            var discarded: git.Repo = .{ .head = .{ .kind = .branch } };
            _ = job.finish(&discarded);
            self.lookup = null;
        }
        if (self.watch) |*handle| handle.deinit();
        self.watch = null;
    }
};

/// The fixed line a run's tabs execute instead of an interactive shell: a
/// PTY check's deterministic peer, or `--command`. Null for an interactive
/// run. The PTY checks run fixed children, so what the program receives is
/// known and nothing of the user's shell configuration is involved.
fn fixedChildCommand(options: Options) ?[]const u8 {
    return if (options.run.clipboard_test)
        clipboard_test_script
    else if (options.run.ime_test)
        ime_test_script
    else if (options.run.tabs_test)
        tabs_test_script
    else if (options.run.panes_test)
        panes_test_script
    else if (options.run.palette_test)
        palette_test_script
    else if (options.run.workspaces_test)
        workspaces_test_script
    else if (options.run.restore_test)
        restore_test_script
    else if (options.run.links_test)
        links_test_script
    else if (options.run.search_test)
        search_test_script
    else if (options.run.menu_test)
        menu_test_script
    else if (options.run.config_test)
        config_test_script
    else if (options.run.theme_test)
        theme_test_script
    else if (options.run.font_test)
        font_test_script
    else if (options.run.settings_test)
        settings_test_script
    else if (options.run.profiles_test)
        profiles_test_script
    else if (options.run.git_test)
        git_test_script
    else if (options.run.control_test)
        control_test_script
    else if (options.run.agent_prompts_test)
        agent_prompts_test_script
    else if (options.run.agent_test)
        agent_test_script
    else
        options.run.command;
}

/// The profile `name` resolves to: a configured one, else a built-in one,
/// else null (an empty name, or one that names nothing, keeps the built-in
/// default). The result borrows `profiles` and `builtins`.
fn resolveNamedProfile(name: []const u8, profiles: []const config.ShellProfile, builtins: *const BuiltinProfiles) ?ResolvedProfile {
    if (name.len == 0) return null;
    if (config.findShellProfile(profiles, name)) |profile| return .fromConfig(profile);
    return builtins.find(name);
}

/// What a child process is started with: its program, its environment and its
/// size.
///
/// Ownership: every string is allocated with the app's allocator and freed by
/// `deinit`, and the child is given copies of what it needs, so the whole
/// struct can go once the child has been spawned.
///
/// Where the environment starts depends on the execution context (P7). A
/// Local context is this machine, so its children inherit Conduit's own
/// environment exactly as every other terminal's local shell does: the
/// desktop session (DISPLAY, WAYLAND_DISPLAY, XDG_RUNTIME_DIR,
/// DBUS_SESSION_BUS_ADDRESS, SSH_AUTH_SOCK, LC_*) and whatever the user
/// exported before starting Conduit. Only `inherited_exclusions` is dropped.
/// A context that cannot forward this process's environment (SSH, WSL) gets
/// the curated set instead, and its remote side supplies the rest. Either way
/// Conduit's terminal identity and the PATH/HOME/LANG fallbacks are set on top.
const ChildSpec = struct {
    allocator: Allocator,
    argv: [][]const u8,
    env: [][]const u8,

    fn deinit(self: *ChildSpec) void {
        freeEntries(self.allocator, self.argv);
        freeEntries(self.allocator, self.env);
    }

    /// The environment a child gets when the process itself was started with
    /// none, because an empty `PATH` means "find nothing".
    const fallback_path = "/usr/local/bin:/usr/bin:/bin";

    /// Variables a Local child never inherits, and why:
    ///
    /// - `CONDUIT_TEST_RUN` / `CONDUIT_TEST_ROOT` are `conduit-test`'s run and
    ///   root fallbacks. Inherited, they would point any `conduit-test` a child
    ///   runs at a test driver and its isolated run by default.
    /// - `CONDUIT_LOG_FILE` names one exact log file that this run truncated
    ///   and owns; a nested Conduit inheriting it would truncate and share it.
    /// - `CONDUIT_SHELL_INTEGRATION_DIR`, `CONDUIT_BASH_INJECT`,
    ///   `CONDUIT_ZSH_ZDOTDIR` and `CONDUIT_SHELL_INTEGRATION_XDG_DIR` are this
    ///   builder's own per-spawn shell-integration handshake. They are set only
    ///   when this spawn injects integration, never copied from an enclosing
    ///   Conduit, so `--no-shell-integration` and `--command` stay clean.
    /// - `TERM_PROGRAM_VERSION` describes the enclosing terminal's
    ///   `TERM_PROGRAM`, which Conduit replaces.
    ///
    /// The test driver itself and the artifact directory reach the app only as
    /// flags (`--test-driver`, `--test-artifact-dir`), never through the
    /// environment, so nothing else names them. `conduit-test launch`'s
    /// isolated HOME/XDG_*/TMPDIR overrides are deliberately kept: they are
    /// this process's environment, and a child of an isolated run must not
    /// touch the user's real config either.
    const inherited_exclusions = [_][]const u8{
        "CONDUIT_TEST_RUN",
        "CONDUIT_TEST_ROOT",
        "CONDUIT_LOG_FILE",
        "CONDUIT_SHELL_INTEGRATION_DIR",
        "CONDUIT_BASH_INJECT",
        "CONDUIT_ZSH_ZDOTDIR",
        "CONDUIT_SHELL_INTEGRATION_XDG_DIR",
        "TERM_PROGRAM_VERSION",
        // An enclosing Conduit's agent correlation token (TASK-52) must not reach a
        // nested child, or a harness started inside it would report to the wrong agent.
        "CONDUIT_AGENT_TOKEN",
        // An enclosing agent's sink, and the switch that offers the scripted fake
        // harness (TASK-56): neither may leak into a child.
        "CONDUIT_AGENT_SINK",
        "CONDUIT_AGENT_GATE",
        fake_agent_env,
        // The backlog view's test stand-in (TASK-63) is the app's, not a child's.
        backlog_cli_env,
        // An enclosing Conduit's control endpoint, token and session (TASK-60)
        // name that Conduit's workspace and terminal. They are added per spawn
        // by `appendControlEnv` for this run's own non-scratchpad children
        // only, so a scratchpad (or a nested Conduit's child) never inherits a
        // way to address an endpoint.
        control_api.endpoint_env_name,
        control_api.token_env_name,
        control_api.session_env_name,
    };

    /// A child's environment while it is being built: the key-replacing map
    /// std uses for spawns, so an identity variable set on top of an
    /// inherited one replaces it rather than appearing twice.
    const Variables = std.process.Environ.Map;

    fn build(allocator: Allocator, io: Io, env: EnvSource, context: workspace.ExecutionContextKind, options: Options) !ChildSpec {
        return buildIn(allocator, io, env, context, options, null);
    }

    /// Build the workspace scratchpad's interactive shell independently of
    /// every run/check command. A scratchpad is a user's persistent terminal,
    /// never a second copy of `--command` or a deterministic test peer.
    fn buildInteractive(
        allocator: Allocator,
        io: Io,
        env: EnvSource,
        context: workspace.ExecutionContextKind,
        no_shell_integration: bool,
        shell_override: ?[]const u8,
    ) !ChildSpec {
        var argv: std.ArrayList([]const u8) = .empty;
        errdefer freeEntries(allocator, argv.items);
        var variables = try baseEnvironment(allocator, env, context);
        defer variables.deinit();

        var default_buffer: [path_capacity]u8 = undefined;
        const shell = shell_override orelse defaultShellProgram(io, env, &default_buffer);
        try put(allocator, &argv, shell);

        if (!no_shell_integration) {
            if (ShellKind.detect(shell)) |kind| {
                try injectShellIntegration(allocator, io, env, kind, null, &argv, &variables);
            }
        }

        return finish(allocator, &argv, &variables);
    }

    /// `build`, with the directory the integration scripts are written to
    /// chosen by the caller. A test passes its own temporary directory; the app
    /// passes null and gets `shellIntegrationDir`.
    fn buildIn(
        allocator: Allocator,
        io: Io,
        env: EnvSource,
        context: workspace.ExecutionContextKind,
        options: Options,
        integration_root: ?[]const u8,
    ) !ChildSpec {
        var argv: std.ArrayList([]const u8) = .empty;
        errdefer freeEntries(allocator, argv.items);
        var variables = try baseEnvironment(allocator, env, context);
        defer variables.deinit();

        const command = fixedChildCommand(options);
        // `--control-test`'s tabs see the check's private runtime and state
        // directories, so the `conduit` commands they run reach this run's
        // instance endpoint and never the user's.
        if (options.run.control_test) {
            if (options.run.runtime_dir) |dir| try variables.put("XDG_RUNTIME_DIR", dir);
            if (options.run.state_dir) |dir| try variables.put("XDG_STATE_HOME", dir);
        }
        // `--agent-test`'s first tab arms a background notification that a
        // file in the check's private directory releases.
        if (options.run.agent_test_dir) |dir| {
            var trigger_buffer: [path_capacity]u8 = undefined;
            try variables.put(agent_test_trigger_env, try std.fmt.bufPrint(&trigger_buffer, "{s}/trigger", .{dir}));
        }
        var default_buffer: [path_capacity]u8 = undefined;
        const shell: ?[]const u8 = if (command) |line| blk: {
            // `/bin/sh` rather than `$SHELL`: a line to run is a script, and a
            // script should not depend on which login shell the person running
            // it happens to have. A script is not an interactive shell, so it
            // gets no shell integration either.
            try put(allocator, &argv, "/bin/sh");
            try put(allocator, &argv, "-c");
            try put(allocator, &argv, line);
            break :blk null;
        } else defaultShellProgram(io, env, &default_buffer);
        if (shell) |program| try put(allocator, &argv, program);

        if (shell) |program| if (!options.run.no_shell_integration) {
            if (ShellKind.detect(program)) |kind| {
                try injectShellIntegration(allocator, io, env, kind, integration_root, &argv, &variables);
            }
        };

        return finish(allocator, &argv, &variables);
    }

    /// What `profile` runs in a workspace of `context` (TASK-46): the
    /// context's environment with the profile's `NAME=value` entries on top,
    /// the program, `loginFlag` when the profile asks for a login shell, the
    /// profile's own arguments and, for a Local bare shell Conduit has a
    /// script for, its integration. A remote context gets no local
    /// integration: its shell runs elsewhere. An empty argv (the remote
    /// login shell) stays empty.
    fn buildProfile(
        allocator: Allocator,
        io: Io,
        env: EnvSource,
        context: workspace.ExecutionContextKind,
        profile: ResolvedProfile,
        no_shell_integration: bool,
        integration_root: ?[]const u8,
    ) !ChildSpec {
        var argv: std.ArrayList([]const u8) = .empty;
        errdefer freeEntries(allocator, argv.items);
        var variables = try baseEnvironment(allocator, env, context);
        defer variables.deinit();
        for (profile.env) |entry| {
            const equals = std.mem.indexOfScalar(u8, entry, '=') orelse continue;
            if (!Variables.validateKeyForPut(entry[0..equals])) continue;
            try variables.put(entry[0..equals], entry[equals + 1 ..]);
        }
        if (profile.argv.len != 0) {
            const program = profile.argv[0];
            try put(allocator, &argv, program);
            if (profile.login) if (loginFlag(program, builtin.os.tag)) |flag| try put(allocator, &argv, flag);
            for (profile.argv[1..]) |arg| try put(allocator, &argv, arg);
            if (context == .local and !no_shell_integration) {
                if (ShellKind.detect(program)) |kind| {
                    if (profileIntegrationAllowed(kind, profile.argv[1..])) {
                        try injectShellIntegration(allocator, io, env, kind, integration_root, &argv, &variables);
                    }
                }
            }
        }
        return finish(allocator, &argv, &variables);
    }

    /// The environment every child of `context` starts from: inherited for
    /// Local, empty otherwise, then Conduit's terminal identity and the three
    /// variables a program cannot start without. The caller owns the map.
    fn baseEnvironment(allocator: Allocator, env: EnvSource, context: workspace.ExecutionContextKind) !Variables {
        var variables = Variables.init(allocator);
        errdefer variables.deinit();
        switch (context) {
            .local => {
                var index: usize = 0;
                while (env.entry(index)) |inherited| : (index += 1) {
                    // A malformed name from the parent cannot become a child's
                    // variable; it is dropped rather than trusted.
                    if (!Variables.validateKeyForPut(inherited.key)) continue;
                    if (isExcluded(inherited.key)) continue;
                    try variables.put(inherited.key, inherited.value);
                }
            },
            // This process's environment belongs to this machine; a remote
            // side supplies its own, so only the curated set crosses.
            .ssh, .wsl => {},
        }
        // The two that decide what a program draws and how much colour it may
        // use, then the three it cannot start without. An inherited empty
        // value counts as unset, as everywhere else Conduit reads one.
        try variables.put("TERM", "xterm-256color");
        try variables.put("COLORTERM", "truecolor");
        try variables.put("TERM_PROGRAM", "conduit");
        // An SSH session's PATH and HOME are the remote host's own: this
        // machine's would name directories that do not exist there
        // (decision-8: the curated set is the *remote* overlay).
        if (context != .ssh) {
            try variables.put("PATH", env.get("PATH") orelse fallback_path);
            try variables.put("HOME", env.get("HOME") orelse "/");
        }
        try variables.put("LANG", env.get("LANG") orelse "C.UTF-8");
        return variables;
    }

    /// The remote overlay every SSH session starts with (decision-8): the
    /// terminal identity and a LANG fallback, rendered by the context into
    /// the remote `/bin/sh` script, and an empty argv, which is the remote
    /// user's own login shell. Remote shell integration is the context's
    /// concern (`ssh.ShellIntegration`), so no local handshake variable is
    /// set here.
    fn buildRemote(allocator: Allocator, env: EnvSource) !ChildSpec {
        var argv: std.ArrayList([]const u8) = .empty;
        var variables = try baseEnvironment(allocator, env, .ssh);
        defer variables.deinit();
        return finish(allocator, &argv, &variables);
    }

    /// The environment the local `ssh` client of an SSH workspace runs with:
    /// it is a Local child, so it inherits Conduit's environment exactly as a
    /// local shell does (`SSH_AUTH_SOCK`, `SSH_ASKPASS`, `DISPLAY`,
    /// `KRB5CCNAME`, proxies), minus `inherited_exclusions`, with the terminal
    /// identity on top so `TERM` reaches the remote side in the PTY request.
    fn buildSshClient(allocator: Allocator, env: EnvSource) !ChildSpec {
        var argv: std.ArrayList([]const u8) = .empty;
        var variables = try baseEnvironment(allocator, env, .local);
        defer variables.deinit();
        return finish(allocator, &argv, &variables);
    }

    fn isExcluded(key: []const u8) bool {
        for (inherited_exclusions) |excluded| {
            if (std.mem.eql(u8, key, excluded)) return true;
        }
        return false;
    }

    /// Transfer `argv` and copies of `variables` into an owned spec.
    fn finish(allocator: Allocator, argv: *std.ArrayList([]const u8), variables: *const Variables) !ChildSpec {
        var entries: std.ArrayList([]const u8) = .empty;
        errdefer {
            for (entries.items) |entry| allocator.free(entry);
            entries.deinit(allocator);
        }
        try entries.ensureTotalCapacity(allocator, variables.count());
        for (variables.keys(), variables.values()) |key, value| {
            entries.appendAssumeCapacity(try std.fmt.allocPrint(allocator, "{s}={s}", .{ key, value }));
        }
        const env_entries = try entries.toOwnedSlice(allocator);
        errdefer freeEntries(allocator, env_entries);
        return .{
            .allocator = allocator,
            .argv = try argv.toOwnedSlice(allocator),
            .env = env_entries,
        };
    }

    fn put(allocator: Allocator, list: *std.ArrayList([]const u8), text: []const u8) !void {
        try list.append(allocator, try allocator.dupe(u8, text));
    }
};

/// Whether a child of `kind` in a workspace of `context` gets this run's
/// control variables (TASK-60). Only a Local context's terminals can reach a
/// local socket, and the scratchpad and an SSH connection terminal never get
/// a way to address the endpoint at all.
fn controlEnvAllowed(kind: session.Session.Kind, context: workspace.ExecutionContextKind) bool {
    if (context != .local) return false;
    return switch (kind) {
        .human_terminal, .agent_terminal => true,
        .scratchpad, .connection => false,
    };
}

/// `base` plus `CONDUIT_CONTROL_ENDPOINT`, `CONDUIT_CONTROL_TOKEN` and
/// `CONDUIT_CONTROL_SESSION`, as a new owned list of owned strings (free with
/// `freeEntries`). Any control variable already in `base` is dropped first, so
/// the child sees exactly these three.
fn appendControlEnv(
    allocator: Allocator,
    base: []const []const u8,
    endpoint: []const u8,
    token: []const u8,
    session_id: session.SessionId,
) Allocator.Error![][]const u8 {
    var entries: std.ArrayList([]const u8) = .empty;
    errdefer {
        for (entries.items) |entry| allocator.free(entry);
        entries.deinit(allocator);
    }
    try entries.ensureTotalCapacity(allocator, base.len + 3);
    for (base) |entry| {
        const name = entry[0 .. std.mem.indexOfScalar(u8, entry, '=') orelse entry.len];
        if (std.mem.eql(u8, name, control_api.endpoint_env_name) or std.mem.eql(u8, name, control_api.token_env_name) or
            std.mem.eql(u8, name, control_api.session_env_name)) continue;
        entries.appendAssumeCapacity(try allocator.dupe(u8, entry));
    }
    entries.appendAssumeCapacity(try std.fmt.allocPrint(allocator, "{s}={s}", .{ control_api.endpoint_env_name, endpoint }));
    entries.appendAssumeCapacity(try std.fmt.allocPrint(allocator, "{s}={s}", .{ control_api.token_env_name, token }));
    entries.appendAssumeCapacity(try std.fmt.allocPrint(allocator, "{s}={d}", .{ control_api.session_env_name, @intFromEnum(session_id) }));
    return entries.toOwnedSlice(allocator);
}

/// An owned copy of `argv` (free with `freeEntries`).
fn dupeArgv(allocator: Allocator, argv: []const []const u8) Allocator.Error![][]const u8 {
    const out = try allocator.alloc([]const u8, argv.len);
    var filled: usize = 0;
    errdefer {
        for (out[0..filled]) |arg| allocator.free(arg);
        allocator.free(out);
    }
    for (argv) |arg| {
        out[filled] = try allocator.dupe(u8, arg);
        filled += 1;
    }
    return out;
}

/// The harness `conduit agent <name>` names: `claude` is Claude Code; every
/// other name is the harness's own (`codex`, `pi`, `opencode`, or the
/// spelling `agent.launch` takes), and `fake` the scripted test harness.
fn controlHarnessChoice(name: []const u8) ?app_agents.Choice {
    if (std.mem.eql(u8, name, "claude")) return .{ .harness = .claude_code };
    return app_agents.Choice.parse(name);
}

/// The real user id, for the shared-`/tmp` socket directory's name.
fn currentUid() u32 {
    if (comptime builtin.os.tag == .windows) return 0;
    return @intCast(std.posix.system.getuid());
}

/// Where this run's control and instance sockets live: `<override>/conduit`
/// for `--control-test`, else `control_api.runtimeDirectory`.
fn controlRuntimeDir(buffer: []u8, env: EnvSource, override: ?[]const u8) ?[]const u8 {
    if (override) |dir| return std.fmt.bufPrint(buffer, "{s}/conduit", .{dir}) catch null;
    return control_api.runtimeDirectory(buffer, builtin.os.tag, .{
        .xdg_runtime_dir = env.get("XDG_RUNTIME_DIR"),
        .tmpdir = env.get("TMPDIR"),
        .uid = currentUid(),
    });
}

/// `<state directory>/instance.token`, beside `state.json`. `state_home`
/// stands in for `$XDG_STATE_HOME` (`--control-test`).
fn instanceTokenPath(buffer: []u8, env: EnvSource, state_home: ?[]const u8) ?[]const u8 {
    var state_buffer: [path_capacity]u8 = undefined;
    const state_path = state_mod.statePath(&state_buffer, builtin.os.tag, .{
        .xdg_state_home = state_home orelse env.get("XDG_STATE_HOME"),
        .home = env.get("HOME"),
        .local_app_data = env.get("LOCALAPPDATA"),
    }) orelse return null;
    const dir = std.fs.path.dirname(state_path) orelse return null;
    return std.fmt.bufPrint(buffer, "{s}{c}{s}", .{ dir, std.fs.path.sep, control_api.instance_token_file_name }) catch null;
}

/// Write the instance token, replacing any earlier one, as a new 0600 file in
/// a 0700 directory: only this user's `conduit` commands can read it.
fn writeInstanceToken(io: Io, path: []const u8, token: []const u8) !void {
    const dir = std.fs.path.dirname(path) orelse return error.InvalidPath;
    _ = try Dir.cwd().createDirPathStatus(io, dir, privateArtifactPermissions(true));
    Dir.cwd().deleteFile(io, path) catch |err| switch (err) {
        error.FileNotFound => {},
        else => return err,
    };
    const file = try Dir.cwd().createFile(io, path, .{ .exclusive = true, .permissions = privateArtifactPermissions(false) });
    defer file.close(io);
    var line: [control_api.Token.text_len + 1]u8 = undefined;
    @memcpy(line[0..token.len], token);
    line[token.len] = '\n';
    try file.writePositionalAll(io, line[0 .. token.len + 1], 0);
}

/// Free a list of owned strings and the list itself. An empty slice is the
/// literal `&.{}`, which owns nothing, so it is not freed.
fn freeEntries(allocator: Allocator, entries: [][]const u8) void {
    if (entries.len == 0) return;
    for (entries) |entry| allocator.free(entry);
    allocator.free(entries);
}

/// The scripts `build.zig` embeds from `assets/shell-integration/`.
const shell_scripts = @import("shell-integration");

/// The shells Conduit has an integration script for. Anything else gets
/// nothing: Conduit never guesses (see `assets/shell-integration/README.md`).
const ShellKind = enum {
    bash,
    zsh,
    fish,
    /// PowerShell 7 (`pwsh`) and Windows PowerShell (`powershell`), on any
    /// platform (TASK-46).
    powershell,

    /// The shell a program path names, judged by its file name only. A login
    /// shell's leading `-` is not stripped because Conduit never starts one
    /// that way (a login profile passes `-l`). PowerShell is matched
    /// ignoring case and an `.exe` suffix, as Windows names it.
    fn detect(program: []const u8) ?ShellKind {
        const name = programName(program);
        if (std.mem.eql(u8, name, "bash")) return .bash;
        if (std.mem.eql(u8, name, "zsh")) return .zsh;
        if (std.mem.eql(u8, name, "fish")) return .fish;
        const stem = if (std.ascii.endsWithIgnoreCase(name, ".exe")) name[0 .. name.len - 4] else name;
        if (std.ascii.eqlIgnoreCase(stem, "pwsh") or std.ascii.eqlIgnoreCase(stem, "powershell")) return .powershell;
        return null;
    }
};

/// Where the scripts are written for a shell to read: a private directory
/// under the platform temporary directory, falling back to the build cache.
/// The scripts are the same bytes every run, so the directory is reused.
fn shellIntegrationDir(buffer: []u8, env: EnvSource) ![]const u8 {
    const base = firstEnv(env, temp_dir_vars[0..]) orelse fallback_log_dir;
    return std.fmt.bufPrint(buffer, "{s}{c}conduit-shell-integration", .{ base, std.fs.path.sep });
}

/// Write the embedded scripts under `root`, in the layout each shell expects:
/// `bash/conduit.bash`, `zsh/.zshenv` + `zsh/conduit.zsh`,
/// `fish/vendor_conf.d/conduit.fish` (fish finds that through `XDG_DATA_DIRS`)
/// and `powershell/conduit.ps1`.
fn writeShellScripts(io: Io, root: []const u8) !void {
    var path: [path_capacity]u8 = undefined;
    const files = [_]struct { dir: []const u8, name: []const u8, data: []const u8 }{
        .{ .dir = "bash", .name = "conduit.bash", .data = shell_scripts.bash },
        .{ .dir = "zsh", .name = ".zshenv", .data = shell_scripts.zsh_env },
        .{ .dir = "zsh", .name = "conduit.zsh", .data = shell_scripts.zsh },
        .{ .dir = "fish" ++ std.fs.path.sep_str ++ "vendor_conf.d", .name = "conduit.fish", .data = shell_scripts.fish },
        .{ .dir = "powershell", .name = "conduit.ps1", .data = shell_scripts.powershell },
    };
    for (files) |file| {
        const dir = try std.fmt.bufPrint(&path, "{s}{c}{s}", .{ root, std.fs.path.sep, file.dir });
        try Dir.cwd().createDirPath(io, dir);
        var full: [path_capacity]u8 = undefined;
        const sub_path = try std.fmt.bufPrint(&full, "{s}{c}{s}", .{ dir, std.fs.path.sep, file.name });
        try Dir.cwd().writeFile(io, .{ .sub_path = sub_path, .data = file.data });
    }
}

/// Add what `kind` needs to load Conduit's integration to a child's `argv` and
/// environment. Writing the scripts can fail (a read-only temporary
/// directory); that leaves the shell exactly as it would have started without
/// integration, and says so, rather than failing the spawn.
fn injectShellIntegration(
    allocator: Allocator,
    io: Io,
    env: EnvSource,
    kind: ShellKind,
    integration_root: ?[]const u8,
    argv: *std.ArrayList([]const u8),
    variables: *ChildSpec.Variables,
) !void {
    var root_buffer: [path_capacity]u8 = undefined;
    const relative = integration_root orelse try shellIntegrationDir(&root_buffer, env);
    writeShellScripts(io, relative) catch |err| {
        log.warn("shell integration is off for this shell: its scripts could not be written ({s})", .{@errorName(err)});
        return;
    };
    // The shell starts in its own working directory, not Conduit's, so every
    // path handed to it must be absolute: a relative ENV or ZDOTDIR names a
    // file that does not exist from where the shell stands, and the shell then
    // loads nothing without saying so.
    const root = Dir.cwd().realPathFileAlloc(io, relative, allocator) catch |err| {
        log.warn("shell integration is off for this shell: its directory could not be resolved ({s})", .{@errorName(err)});
        return;
    };
    defer allocator.free(root);

    try variables.put("CONDUIT_SHELL_INTEGRATION_DIR", root);
    var path: [path_capacity]u8 = undefined;
    switch (kind) {
        // POSIX mode makes an interactive bash read `ENV` instead of its usual
        // startup files; the script turns POSIX mode back off and replays them.
        .bash => {
            try ChildSpec.put(allocator, argv, "--posix");
            const script = try std.fmt.bufPrint(&path, "{s}{c}bash{c}conduit.bash", .{ root, std.fs.path.sep, std.fs.path.sep });
            try variables.put("ENV", script);
            try variables.put("CONDUIT_BASH_INJECT", "1");
        },
        // `ZDOTDIR` points at the integration directory, and the user's own
        // value — or its absence, as an empty value — rides along so the
        // script's `.zshenv` can put it back before anything else runs.
        .zsh => {
            try variables.put("CONDUIT_ZSH_ZDOTDIR", env.get("ZDOTDIR") orelse "");
            const dir = try std.fmt.bufPrint(&path, "{s}{c}zsh", .{ root, std.fs.path.sep });
            try variables.put("ZDOTDIR", dir);
        },
        // Untested by decision (see the README). fish reads `vendor_conf.d`
        // from every directory in `XDG_DATA_DIRS`, and the script removes this
        // one again so programs the shell starts see the user's value.
        .fish => {
            const dir = try std.fmt.bufPrint(&path, "{s}{c}fish", .{ root, std.fs.path.sep });
            try variables.put("CONDUIT_SHELL_INTEGRATION_XDG_DIR", dir);
            var data_dirs: [path_capacity]u8 = undefined;
            const existing = env.get("XDG_DATA_DIRS") orelse "/usr/local/share:/usr/share";
            const joined = try std.fmt.bufPrint(&data_dirs, "{s}:{s}", .{ dir, existing });
            try variables.put("XDG_DATA_DIRS", joined);
        },
        // TASK-46. `-Command` runs after PowerShell has loaded the user's own
        // profile, and `-NoExit` keeps the shell interactive afterwards, so
        // loading the script here changes nothing else about startup. The
        // file's text is dot-sourced as a script block rather than as a
        // script file, so an execution policy that forbids unsigned script
        // files (Windows PowerShell's default on client Windows) does not
        // stop it, and the command holds no double quote for Windows'
        // command-line parsing to disagree about. Single quotes keep the path
        // literal; a quote in it is doubled.
        .powershell => {
            const script = try std.fmt.bufPrint(&path, "{s}{c}powershell{c}conduit.ps1", .{ root, std.fs.path.sep, std.fs.path.sep });
            var command: std.ArrayList(u8) = .empty;
            defer command.deinit(allocator);
            try command.appendSlice(allocator, ". ([scriptblock]::Create([System.IO.File]::ReadAllText('");
            for (script) |byte| {
                if (byte == '\'') try command.append(allocator, '\'');
                try command.append(allocator, byte);
            }
            try command.appendSlice(allocator, "')))");
            try ChildSpec.put(allocator, argv, "-NoExit");
            try ChildSpec.put(allocator, argv, "-Command");
            try ChildSpec.put(allocator, argv, command.items);
        },
    }
}

// ---------------------------------------------------------------------------
// Shell profiles (TASK-46)
// ---------------------------------------------------------------------------

/// A profile ready to start in one workspace: a configured `profile` line
/// or one of the built-in profiles detected for that workspace's context.
/// Every slice is borrowed from the config or from `BuiltinProfiles`.
const ResolvedProfile = struct {
    name: []const u8,
    /// Empty only for the built-in `login` profile of a remote workspace,
    /// which is the remote user's own login shell.
    argv: []const []const u8,
    env: []const []const u8 = &.{},
    cwd: ?[]const u8 = null,
    login: bool = false,
    builtin: bool = false,

    fn fromConfig(profile: config.ShellProfile) ResolvedProfile {
        return .{ .name = profile.name, .argv = profile.argv, .env = profile.env, .cwd = profile.cwd, .login = profile.login };
    }
};

/// Whether a file exists, asked of a workspace's execution context so a
/// remote workspace would be asked on its own host.
const PathProbe = struct {
    ctx: *const anyopaque,
    exists_fn: *const fn (ctx: *const anyopaque, path: []const u8) bool,

    fn exists(self: PathProbe, path: []const u8) bool {
        return self.exists_fn(self.ctx, path);
    }
};

/// A `PathProbe` over an execution context's `statPath`.
const ContextProbe = struct {
    ref: workspace.ExecutionContext.Ref,
    io: Io,

    fn probe(self: *const ContextProbe) PathProbe {
        return .{ .ctx = self, .exists_fn = exists };
    }

    fn exists(ctx: *const anyopaque, path: []const u8) bool {
        const self: *const ContextProbe = @ptrCast(@alignCast(ctx));
        const stat = self.ref.statPath(self.io, path) catch return false;
        return stat.kind == .file;
    }
};

/// The built-in profiles of one workspace, detected when a chooser opens or
/// a default is needed (AC3):
///
/// - a Local POSIX workspace: `login`, the user's `$SHELL` (else the shell
///   `/etc/passwd` names for this user, else `/bin/sh`) as a login shell;
/// - a Local Windows workspace: `pwsh` (PowerShell 7, on `PATH` or in
///   `%ProgramFiles%\PowerShell\7`), `powershell` (Windows PowerShell) and
///   `cmd`, each only when it exists; the first is the default;
/// - a remote workspace: `login`, the remote user's own login shell.
///
/// Filled in place: `argv` slices point into this value, so it lives in a
/// stable place (the app) and is never copied while in use.
const BuiltinProfiles = struct {
    const capacity = 4;

    names: [capacity][]const u8 = undefined,
    programs: [capacity][path_capacity]u8 = undefined,
    argv: [capacity][1][]const u8 = undefined,
    program_lens: [capacity]usize = undefined,
    login: [capacity]bool = undefined,
    count: usize = 0,

    fn add(self: *BuiltinProfiles, name: []const u8, program: []const u8, login: bool) void {
        if (self.count == capacity or program.len > path_capacity) return;
        const index = self.count;
        self.names[index] = name;
        @memcpy(self.programs[index][0..program.len], program);
        self.program_lens[index] = program.len;
        self.argv[index][0] = self.programs[index][0..program.len];
        self.login[index] = login;
        self.count += 1;
    }

    fn at(self: *const BuiltinProfiles, index: usize) ResolvedProfile {
        return .{
            .name = self.names[index],
            .argv = if (self.program_lens[index] == 0) &.{} else self.argv[index][0..1],
            .login = self.login[index],
            .builtin = true,
        };
    }

    fn find(self: *const BuiltinProfiles, name: []const u8) ?ResolvedProfile {
        for (0..self.count) |index| {
            if (std.mem.eql(u8, self.names[index], name)) return self.at(index);
        }
        return null;
    }

    /// Detect the built-in profiles for a workspace of `kind` whose files
    /// `probe` answers for, on `os`. `passwd` is the context's
    /// `/etc/passwd`, when it could be read.
    fn detect(self: *BuiltinProfiles, kind: workspace.ExecutionContextKind, os: std.Target.Os.Tag, env: EnvSource, probe: PathProbe, passwd: ?[]const u8) void {
        self.count = 0;
        if (kind.isRemote()) return self.add("login", "", true);
        if (os == .windows) return self.detectWindows(env, probe);
        const shell = env.get("SHELL") orelse
            (if (passwd) |text| passwdShell(text, currentUid()) else null) orelse "/bin/sh";
        self.add("login", shell, true);
    }

    fn detectWindows(self: *BuiltinProfiles, env: EnvSource, probe: PathProbe) void {
        var buffer: [path_capacity]u8 = undefined;
        if (findOnWindowsPath(&buffer, firstEnv(env, &.{ "PATH", "Path" }), "pwsh.exe", probe)) |found| {
            self.add("pwsh", found, false);
        } else if (env.get("ProgramFiles") orelse env.get("PROGRAMFILES")) |program_files| {
            if (std.fmt.bufPrint(&buffer, "{s}\\PowerShell\\7\\pwsh.exe", .{std.mem.trimEnd(u8, program_files, "\\")})) |path| {
                if (probe.exists(path)) self.add("pwsh", path, false);
            } else |_| {}
        }
        const system_root = std.mem.trimEnd(u8, firstEnv(env, &.{ "SystemRoot", "SYSTEMROOT", "windir" }) orelse "C:\\Windows", "\\");
        if (std.fmt.bufPrint(&buffer, "{s}\\System32\\WindowsPowerShell\\v1.0\\powershell.exe", .{system_root})) |path| {
            if (probe.exists(path)) self.add("powershell", path, false);
        } else |_| {}
        // cmd is always offered: it is part of every Windows install, and a
        // bare name is still found on the child's PATH if the probe missed it.
        const comspec = firstEnv(env, &.{ "ComSpec", "COMSPEC" });
        if (comspec != null and probe.exists(comspec.?)) {
            self.add("cmd", comspec.?, false);
        } else if (std.fmt.bufPrint(&buffer, "{s}\\System32\\cmd.exe", .{system_root})) |path| {
            self.add("cmd", if (probe.exists(path)) path else "cmd.exe", false);
        } else |_| self.add("cmd", "cmd.exe", false);
    }
};

/// The first `<dir>\<program>` that exists among the `;`-separated `path`
/// entries, written into `buffer`. At most 64 entries are tried.
fn findOnWindowsPath(buffer: []u8, path: ?[]const u8, program: []const u8, probe: PathProbe) ?[]const u8 {
    var entries = std.mem.splitScalar(u8, path orelse return null, ';');
    var tried: usize = 0;
    while (entries.next()) |raw| {
        if (tried == 64) return null;
        tried += 1;
        const dir = std.mem.trimEnd(u8, std.mem.trim(u8, raw, " \""), "\\");
        if (dir.len == 0) continue;
        const candidate = std.fmt.bufPrint(buffer, "{s}\\{s}", .{ dir, program }) catch continue;
        if (probe.exists(candidate)) return candidate;
    }
    return null;
}

/// The login shell `/etc/passwd` text names for `uid`, or null. Only the
/// seventh field of the first line with that uid is read.
fn passwdShell(text: []const u8, uid: u32) ?[]const u8 {
    var lines = std.mem.splitScalar(u8, text, '\n');
    while (lines.next()) |line| {
        var fields = std.mem.splitScalar(u8, line, ':');
        var values: [7][]const u8 = undefined;
        var count: usize = 0;
        while (fields.next()) |field| {
            if (count == values.len) break;
            values[count] = field;
            count += 1;
        }
        if (count < 7) continue;
        const line_uid = std.fmt.parseUnsigned(u32, values[2], 10) catch continue;
        if (line_uid != uid) continue;
        const shell = std.mem.trimEnd(u8, values[6], "\r");
        return if (shell.len != 0 and shell[0] == '/') shell else null;
    }
    return null;
}

/// The program a default local shell runs: the user's `$SHELL` (else
/// `/bin/sh`) on POSIX; on Windows, the first built-in profile that exists,
/// probed on this machine. `buffer` holds a detected path.
fn defaultShellProgram(io: Io, env: EnvSource, buffer: *[path_capacity]u8) []const u8 {
    if (comptime builtin.os.tag != .windows) return env.get("SHELL") orelse "/bin/sh";
    var probe_state: ContextProbe = .{ .ref = workspace.localFiles(), .io = io };
    var detected: BuiltinProfiles = .{};
    detected.detect(.local, .windows, env, probe_state.probe(), null);
    if (detected.count == 0) return "cmd.exe";
    const program = detected.at(0).argv[0];
    @memcpy(buffer[0..program.len], program);
    return buffer[0..program.len];
}

/// What `login` adds to a profile's program: `-l` for a POSIX shell,
/// `--login` for bash (whose long options must precede the `--posix` its
/// integration adds), `-Login` for PowerShell 7 off Windows, and nothing for
/// Windows PowerShell, cmd or PowerShell on Windows, which have no login
/// mode.
fn loginFlag(program: []const u8, os: std.Target.Os.Tag) ?[]const u8 {
    const name = programName(program);
    if (ShellKind.detect(program) == .bash) return "--login";
    if (std.ascii.eqlIgnoreCase(name, "cmd") or std.ascii.eqlIgnoreCase(name, "cmd.exe")) return null;
    if (ShellKind.detect(program) == .powershell) {
        if (os == .windows) return null;
        return if (std.ascii.startsWithIgnoreCase(name, "pwsh")) "-Login" else null;
    }
    return "-l";
}

/// The file name of a program path, split at either separator so a Windows
/// path names its program on any host.
fn programName(program: []const u8) []const u8 {
    const index = std.mem.lastIndexOfAny(u8, program, "/\\") orelse return program;
    return program[index + 1 ..];
}

/// Whether Conduit may add its integration to `kind` started with the
/// profile's own `args`. A shell given a script or a command is not an
/// interactive shell, so only a bare shell qualifies; PowerShell also keeps
/// it with `-NoLogo`, `-NoProfile` or `-Login`, which change nothing the
/// integration's `-NoExit -Command` relies on.
fn profileIntegrationAllowed(kind: ShellKind, args: []const []const u8) bool {
    if (args.len == 0) return true;
    if (kind != .powershell) return false;
    for (args) |arg| {
        const harmless = std.ascii.eqlIgnoreCase(arg, "-NoLogo") or std.ascii.eqlIgnoreCase(arg, "-NoProfile") or
            std.ascii.eqlIgnoreCase(arg, "-Login") or std.ascii.eqlIgnoreCase(arg, "-l");
        if (!harmless) return false;
    }
    return true;
}

/// A tracked working directory as a spawn on `os` takes it. PowerShell
/// reports `C:\Users` as OSC 7 `file://localhost/C:/Users`, which the
/// terminal keeps as `/C:/Users`; a Windows spawn needs `C:\Users`, written
/// into `buffer`. Every other directory is returned unchanged.
fn spawnDirectory(buffer: []u8, tracked: []const u8, os: std.Target.Os.Tag) []const u8 {
    if (os != .windows) return tracked;
    if (tracked.len < 3 or tracked[0] != '/' or !std.ascii.isAlphabetic(tracked[1]) or tracked[2] != ':') return tracked;
    const rest = tracked[1..];
    if (rest.len > buffer.len) return tracked;
    for (rest, 0..) |byte, index| buffer[index] = if (byte == '/') '\\' else byte;
    // `C:` alone is the drive's current directory, not its root.
    if (rest.len == 2) {
        if (buffer.len < 3) return tracked;
        buffer[2] = '\\';
        return buffer[0..3];
    }
    return buffer[0..rest.len];
}

/// The profile choosers' list (TASK-46): the built-in profiles detected for
/// the active workspace, then every configured profile not named like one.
/// Heap-owned by the app so the registry can borrow `slice()` from before
/// the app exists; rebuilt in place only while the palette is closed, since
/// an open chooser's rows are indices into it.
const ProfileChoices = struct {
    const capacity = config.max_shell_profiles + BuiltinProfiles.capacity;

    choices: [capacity]inputmod.PaletteChoice = undefined,
    labels: [capacity][palette_label_capacity]u8 = undefined,
    values: [capacity][config.max_shell_profile_name_bytes]u8 = undefined,
    count: usize = 0,
    builtins: BuiltinProfiles = .{},

    /// Detect the built-ins for a workspace whose context is `ref`, and
    /// list them with `profiles`.
    fn rebuild(self: *ProfileChoices, io: Io, env: EnvSource, ref: workspace.ExecutionContext.Ref, profiles: []const config.ShellProfile) void {
        detectBuiltins(&self.builtins, io, env, ref);
        self.count = 0;
        for (0..self.builtins.count) |index| {
            const builtin_profile = self.builtins.at(index);
            if (config.findShellProfile(profiles, builtin_profile.name) != null) continue;
            self.add(builtin_profile);
        }
        for (profiles) |profile| self.add(.fromConfig(profile));
    }

    fn add(self: *ProfileChoices, profile: ResolvedProfile) void {
        if (self.count == capacity or profile.name.len > config.max_shell_profile_name_bytes) return;
        const index = self.count;
        @memcpy(self.values[index][0..profile.name.len], profile.name);
        self.choices[index] = .{
            .label = profileChoiceLabel(&self.labels[index], profile),
            .value = self.values[index][0..profile.name.len],
        };
        self.count += 1;
    }

    fn slice(self: *const ProfileChoices) []const inputmod.PaletteChoice {
        return self.choices[0..self.count];
    }
};

/// Detect `builtins` for a workspace whose context is `ref`: the context
/// answers whether a file exists and, on a Local POSIX host without
/// `$SHELL`, what `/etc/passwd` says.
fn detectBuiltins(builtins: *BuiltinProfiles, io: Io, env: EnvSource, ref: workspace.ExecutionContext.Ref) void {
    var probe: ContextProbe = .{ .ref = ref, .io = io };
    var passwd_buffer: [64 * 1024]u8 = undefined;
    const passwd: ?[]const u8 = if (builtin.os.tag != .windows and !ref.kind().isRemote() and env.get("SHELL") == null)
        ref.readFile(io, "/etc/passwd", &passwd_buffer) catch null
    else
        null;
    builtins.detect(ref.kind(), builtin.os.tag, env, probe.probe(), passwd);
}

/// A profile's label in the chooser: its name, the command it runs and
/// where it comes from.
fn profileChoiceLabel(buffer: []u8, profile: ResolvedProfile) []const u8 {
    var writer: std.Io.Writer = .fixed(buffer);
    writer.writeAll(profile.name) catch return writer.buffered();
    writer.writeAll("  ") catch return writer.buffered();
    if (profile.argv.len == 0) {
        writer.writeAll("remote login shell") catch return writer.buffered();
    } else {
        for (profile.argv, 0..) |arg, index| {
            if (index != 0) writer.writeByte(' ') catch return writer.buffered();
            writer.writeAll(arg) catch return writer.buffered();
            if (index == 0 and profile.login) {
                if (loginFlag(arg, builtin.os.tag)) |flag| writer.print(" {s}", .{flag}) catch return writer.buffered();
            }
        }
    }
    writer.writeAll(if (profile.builtin) "  built-in" else "  profile") catch return writer.buffered();
    // A clipped label never ends inside a UTF-8 sequence.
    var len = writer.end;
    while (len != 0 and !std.unicode.utf8ValidateSlice(buffer[0..len])) len -= 1;
    return buffer[0..len];
}

/// The grid that fits a surface of `size` at a given cell size, in whole
/// cells. The grid is integral and the surface is not, so the leftover pixels
/// along the right and bottom edges are simply not part of the terminal.
fn gridSizeFor(cell: font.CellSize, size: render.Size) !term.GridSize {
    const fits = cell.cellsPer(size.width, size.height);
    // At least one cell in each direction: a surface smaller than a single cell
    // is a window with a terminal in it, not a terminal of no cells, and every
    // grid calculation divides by the cell size.
    return try term.GridSize.init(
        @intCast(@max(1, @min(fits.columns, std.math.maxInt(u16)))),
        @intCast(@max(1, @min(fits.rows, std.math.maxInt(u16)))),
    );
}

/// The size a terminal's cells are rasterised at, in points, before the display
/// scale. The scale multiplies it, so a 2x display rasterises 28px glyphs
/// rather than enlarging 14px ones — which is the whole of TASK-11's HiDPI
/// story, and why the grid never has to scale anything itself.
const font_points: f32 = config.default_font_points;

/// The glyph atlas edge, in pixels, below `large_atlas_scale`. `font`
/// allocates it and `render` uploads it as one texture, so both are told the
/// same number (`atlasSizeFor`).
const atlas_width_px: u32 = 1024;
const atlas_height_px: u32 = 1024;
/// The atlas edge from `large_atlas_scale` up. A face rasterised at 2x has
/// four times the glyph area, which crowded CJK and symbol-heavy screens out
/// of a 1024² atlas (TASK-67's profiling); 2048² holds them at 16 MiB of
/// coverage, still one texture.
const large_atlas_px: u32 = 2048;
const large_atlas_scale: f32 = 1.5;

/// The coverage atlas for a face rasterised at display `scale`. Every grid
/// that draws that face is attached with the same size (TASK-67).
fn atlasSizeFor(scale: f32) render.AtlasSize {
    if (scale >= large_atlas_scale) return .{ .width_px = large_atlas_px, .height_px = large_atlas_px };
    return .{ .width_px = atlas_width_px, .height_px = atlas_height_px };
}

test "the atlas grows to 2048 square from display scale 1.5" {
    try std.testing.expectEqual(@as(u32, 1024), atlasSizeFor(1).width_px);
    try std.testing.expectEqual(@as(u32, 1024), atlasSizeFor(1.25).height_px);
    try std.testing.expectEqual(@as(u32, 2048), atlasSizeFor(1.5).width_px);
    try std.testing.expectEqual(@as(u32, 2048), atlasSizeFor(2).height_px);
    const request = (FontValues{}).request("", try font.Size.init(14, 2), null);
    try std.testing.expectEqual(@as(u32, 2048), request.atlas_width_px);
    try std.testing.expectEqual(@as(u32, 2048), request.atlas_height_px);
    const small = smallFontRequest(request).?;
    try std.testing.expectEqual(small_atlas.width_px, small.atlas_width_px);
}

/// The fixed buffer child output is copied into. A program's output
/// arrives in whatever sizes the pipe hands over, and this buffer is never
/// resized, so a frame never allocates.
const pty_read_capacity = 64 * 1024;

/// How many bytes one pump pass feeds a session's terminal, at most.
///
/// The drain loop checks its time slice between passes, so this is the
/// granularity of that slice. Parsing cost is dominated by the content rather
/// than the byte count: a pass of newline-heavy output costs far more than a
/// pass of plain text, so a smaller pass keeps input and the test driver
/// answered during such floods without lowering throughput, which per-pass
/// overhead does not limit.
const pty_pass_capacity = 16 * 1024;

/// How long the cursor is on, and how long it is off, in nanoseconds.
const blink_period_ns: i128 = 600 * std.time.ns_per_ms;

/// How long the loop blocks for a window event when something outside the
/// queue can change the screen, in milliseconds. It bounds how long a byte
/// from the child can wait for a frame.
const idle_tick_ms: i32 = 16;

/// Whether a run spawns a child at all. The checks that need a grid that is
/// not moving under them ask for none; PTY-facing checks ask for their own,
/// because terminal input is only proved by what a program reads.
fn wantsChild(options: Options) bool {
    if (options.run.ui_test or options.run.sidebar_test or options.run.ssh_test or options.run.a11y_test) return false;
    if (options.run.restore_test) return true;
    if (options.run.clipboard_test or options.run.ime_test or options.run.tabs_test or
        options.run.panes_test or options.run.palette_test or options.run.workspaces_test or
        options.run.links_test or options.run.search_test or options.run.menu_test or
        options.run.config_test or options.run.theme_test or options.run.font_test or options.run.settings_test or
        options.run.profiles_test or options.run.git_test or options.run.agent_test) return true;
    return !options.run.no_child and !options.run.self_test and !options.run.grid_test and
        !options.run.scroll_test and !options.run.mouse_test and !options.run.ui_test and
        !options.run.sidebar_test;
}

/// Built-in checks must not source the user's shell configuration through the
/// workspace scratchpad. They still start and pump the reserved session, but
/// use a deterministic plain shell so late rc/integration output cannot alter
/// an unrelated pixel or idle-work measurement.
fn usesDeterministicScratchpad(options: Options) bool {
    const run = options.run;
    return run.self_test or run.grid_test or run.scroll_test or run.mouse_test or
        run.clipboard_test or run.ui_test or run.ime_test or run.sidebar_test or
        run.tabs_test or run.panes_test or run.scratchpad_test or run.palette_test or
        run.workspaces_test or run.links_test or run.search_test or run.menu_test or
        run.config_test or run.theme_test or run.font_test or run.settings_test or run.driver_test or run.git_test or
        run.profiles_test or run.agent_test or run.ssh_test or run.restore_test or run.a11y_test;
}

