const SearchBarLayout = struct {
    bounds: ui.Rect,
    query: ui.Rect,
    detail: ?ui.Rect,
    bordered: bool,
};

/// Search must keep its text target visible whenever the canvas has even one
/// cell. The full box is useful at ordinary sizes; a compact bar spends no
/// cells on chrome and drops its optional detail row when height is scarce.
fn calculateSearchBarLayout(canvas: ui.Rect) ?SearchBarLayout {
    if (canvas.width == 0 or canvas.height == 0) return null;

    const bordered = canvas.width >= 42 and canvas.height >= 4;
    const width = @min(@as(u32, 72), canvas.width);
    const height = @min(@as(u32, 4), canvas.height);
    const bounds: ui.Rect = .{
        .x = canvas.x +| (canvas.width - width),
        .y = canvas.y,
        .width = width,
        .height = height,
    };
    if (!bordered) return .{
        .bounds = bounds,
        .query = .{ .x = bounds.x, .y = bounds.y, .width = bounds.width, .height = 1 },
        .detail = if (bounds.height >= 2) .{
            .x = bounds.x,
            .y = bounds.y + 1,
            .width = bounds.width,
            .height = 1,
        } else null,
        .bordered = false,
    };

    return .{
        .bounds = bounds,
        .query = .{
            .x = bounds.x + 2,
            .y = bounds.y + 1,
            .width = bounds.width - 4,
            .height = 1,
        },
        .detail = .{
            .x = bounds.x + 2,
            .y = bounds.y + 2,
            .width = bounds.width - 4,
            .height = 1,
        },
        .bordered = true,
    };
}

/// One bounded materialization window. A replacement page uses the inactive
/// slot so the current selection remains usable until at least one adjacent
/// match has actually been found.
const SearchPageScan = struct {
    cursor: term.SearchCursor,
    slot: usize,
    count: usize = 0,
    activation: SearchPageActivation,
    allow_wrap: bool,
    wrapped: bool = false,
};

/// Existing renderer checks predate the workspace shell and retain their
/// fixed full-terminal geometry. The sidebar check and ordinary runs exercise
/// the production inset instead.
fn sidebarEnabled(options: Options) bool {
    return !(options.run.self_test or options.run.grid_test or options.run.scroll_test or
        options.run.mouse_test or options.run.clipboard_test or options.run.ui_test or
        options.run.ime_test or options.run.links_test or options.run.search_test or
        options.run.menu_test or options.run.driver_test);
}

fn sidebarStartsVisible(options: Options) bool {
    return sidebarEnabled(options);
}

fn sidebarColumns(total_cols: u16, preferred: u16, visible: bool) u16 {
    if (!visible or total_cols <= 1) return 0;
    const available = total_cols - 1;
    const bounded = @min(@max(preferred, sidebar_min_width), sidebar_max_width);
    return @min(bounded, available);
}

/// Why a copy did not happen. Logged by name; the text never is.
const CopyError = platform.ClipboardError || error{NothingSelected};

/// Why a paste did not happen. Logged by name; the text never is.
const PasteFailure = platform.ClipboardError || term.PasteError || error{
    /// The previous paste has not gone out yet. One at a time keeps a frame's
    /// memory bounded by one clipboard rather than by however many presses.
    PasteInFlight,
};

/// What a paste did, by size.
const PasteOutcome = union(enum) {
    /// Encoded and queued for `pumpChild`; this many bytes will be written.
    queued: usize,
    /// Nothing was sent: this many bytes of multi-line text into a program
    /// without bracketed paste wait for a confirmation M1 cannot ask for.
    confirmation_required: usize,
};

/// The native clipboard an OSC 52 selector names.
///
/// `s` (selection) and `p` (primary) are both the primary selection where one
/// exists: X11 and Wayland have exactly one besides the clipboard. Elsewhere
/// they are refused rather than quietly redirected to the clipboard a program
/// did not name.
fn nativeTarget(location: term.ClipboardLocation) term.ClipboardAccessError!ClipboardTarget {
    return switch (location) {
        .standard => .standard,
        .selection, .primary => if (platform.primary_selection_supported) .primary else error.Unsupported,
    };
}

fn accessError(err: platform.ClipboardError) term.ClipboardAccessError {
    return switch (err) {
        error.OutOfMemory => error.OutOfMemory,
        error.PayloadTooLarge => error.PayloadTooLarge,
        error.InvalidText => error.InvalidText,
        error.ClipboardReadFailed, error.ClipboardWriteFailed => error.Unavailable,
    };
}

/// `term.ClipboardAccess.read_fn`: an OSC 52 read that policy allowed. The
/// caller owns the returned text, allocated with `alloc`.
fn readNativeClipboard(_: ?*anyopaque, location: term.ClipboardLocation, alloc: Allocator) term.ClipboardAccessError![]u8 {
    return switch (try nativeTarget(location)) {
        .standard => platform.getClipboardText(alloc),
        .primary => platform.getPrimarySelectionText(alloc),
    } catch |err| accessError(err);
}

/// `term.ClipboardAccess.write_fn`: an OSC 52 write that policy allowed.
/// `text` is borrowed for the call.
fn writeNativeClipboard(_: ?*anyopaque, location: term.ClipboardLocation, text: []const u8, alloc: Allocator) term.ClipboardAccessError!void {
    return switch (try nativeTarget(location)) {
        .standard => platform.setClipboardText(alloc, text),
        .primary => platform.setPrimarySelectionText(alloc, text),
    } catch |err| accessError(err);
}

/// What `--clipboard-test` observes of the child, in the order it happened.
///
/// Ownership: both lists are allocated with the app's allocator and freed by
/// `deinit`. Only fixtures the check wrote itself ever pass through it.
const ClipboardTrace = struct {
    /// Every byte `writeToChild` handed the child, in order.
    sent: std.ArrayList(u8) = .empty,
    /// Every byte the child wrote back, in order.
    received: std.ArrayList(u8) = .empty,
    /// The last OSC 52 permission request the app saw.
    last_permission: ?term.PermissionRequest = null,

    fn deinit(self: *ClipboardTrace, allocator: Allocator) void {
        self.sent.deinit(allocator);
        self.received.deinit(allocator);
    }
};

/// What one platform text-input event changed in the app's composition state.
///
/// Committed text borrows the event's payload and must be staged before the
/// next platform event is pumped. The other two input-method events have
/// already copied everything the app needs into `Composition`.
const InputMethodOutcome = union(enum) {
    unrelated,
    preedit,
    candidates,
    committed: []const u8,
};

/// Route the text-input part of the platform event stream into one composition.
///
/// Kept independent of `App` so the state transition and the lifetime of a
/// committed payload can be proved without constructing a window, renderer or
/// PTY. The app calls this before its ordinary event switch and stages a
/// `.committed` payload in the same iteration, while SDL still owns it.
fn routeInputMethodEvent(composition: *inputmod.Composition, event: platform.Event) InputMethodOutcome {
    return switch (event) {
        .text_editing => |editing| changed: {
            composition.update(editing);
            break :changed .preedit;
        },
        .candidates => |candidates| changed: {
            composition.setCandidates(candidates);
            break :changed .candidates;
        },
        .text_input => |committed| .{ .committed = composition.commit(committed) },
        else => .unrelated,
    };
}

/// Translate one key against the app's live input-method state.
fn translateAppKey(
    composition: *const inputmod.Composition,
    scratch: *inputmod.TextScratch,
    key: platform.KeyEvent,
) inputmod.Press {
    return inputmod.translate(scratch, key, composition.isComposing());
}

/// Append one event's bytes to the fixed child-input staging value.
///
/// False means the whole event was refused: keeping the prefix would turn
/// valid UTF-8 or an escape sequence into malformed input. The caller logs
/// only byte counts, never the user's text.
fn appendChildInput(staged: *term.EncodedKey, bytes: []const u8) bool {
    if (bytes.len == 0) return true;
    const free = staged.bytes.len - staged.len;
    if (bytes.len > free) return false;
    @memcpy(staged.bytes[staged.len..][0..bytes.len], bytes);
    staged.len += bytes.len;
    return true;
}

/// Hold one committed-text payload until the event handler reaches the app's
/// single child-write site. The slice is borrowed from the platform event and
/// therefore must be taken before another event is pumped.
fn queueCommittedText(pending: *[]const u8, text: []const u8) void {
    // Every handled event flushes before the next pump. A non-empty value here
    // would mean a caller broke that lifetime contract.
    std.debug.assert(pending.*.len == 0);
    pending.* = text;
}

/// Take and clear the borrowed committed-text payload in one operation.
fn takeCommittedText(pending: *[]const u8) []const u8 {
    const text = pending.*;
    pending.* = "";
    return text;
}

/// Convert a device-pixel cell extent to the logical pixels SDL expects for
/// text-input placement.
fn logicalPixels(physical: u32, scale: platform.Scale) u32 {
    const value = @round(
        @as(f64, @floatFromInt(physical)) /
            @as(f64, @floatCast(scale.factor)),
    );
    if (value >= @as(f64, @floatFromInt(std.math.maxInt(u32)))) return std.math.maxInt(u32);
    return @max(1, @as(u32, @intFromFloat(value)));
}

const ui_test_initial_origin = ui.Rect{ .x = 4, .y = 2, .width = 0, .height = 0 };
const ui_test_moved_origin = ui.Rect{ .x = 34, .y = 2, .width = 0, .height = 0 };
const ui_test_surface_width: u32 = 24;
const ui_test_surface_height: u32 = 9;
const ui_test_min_cols: u32 = ui_test_moved_origin.x + ui_test_surface_width;
const ui_test_min_rows: u32 = ui_test_initial_origin.y + ui_test_surface_height + 1;
const ui_test_terminal_background = render.Rgba{ .r = 17, .g = 31, .b = 47 };
const ui_test_terminal_damage = render.Rgba{ .r = 41, .g = 73, .b = 59 };

/// The state owned by `uiTest` while its borrowed pointer is attached to App.
/// No production UI state or routing is introduced by this fixture.
const UiTestFixture = struct {
    tree: ui.Tree,
    canvas: ui.Canvas,
    field: ui.Input,
    origin: ui.Rect = ui_test_initial_origin,
    last_dispatch: ?UiTestDispatch = null,
    dispatch_count: usize = 0,

    fn init(allocator: Allocator, size: term.GridSize) !UiTestFixture {
        var tree = try ui.Tree.init(allocator, 6, 4);
        errdefer tree.deinit();
        var canvas = try ui.Canvas.init(allocator, size.cols, size.rows);
        errdefer canvas.deinit();
        var field = try ui.Input.init(allocator, 32, "seed");
        field.selectAll();
        return .{ .tree = tree, .canvas = canvas, .field = field };
    }

    fn deinit(self: *UiTestFixture) void {
        self.field.deinit();
        self.canvas.deinit();
        self.tree.deinit();
        self.* = undefined;
    }

    fn surfaceRect(self: *const UiTestFixture) ui.Rect {
        return .{
            .x = self.origin.x,
            .y = self.origin.y,
            .width = ui_test_surface_width,
            .height = ui_test_surface_height,
        };
    }

    fn textRect(self: *const UiTestFixture) ui.Rect {
        return .{ .x = self.origin.x + 3, .y = self.origin.y + 2, .width = 10, .height = 1 };
    }

    fn interactiveRect(self: *const UiTestFixture) ui.Rect {
        return .{ .x = self.origin.x + 3, .y = self.origin.y + 4, .width = 10, .height = 1 };
    }

    fn inputRect(self: *const UiTestFixture) ui.Rect {
        return .{ .x = self.origin.x + 3, .y = self.origin.y + 6, .width = 10, .height = 1 };
    }

    fn overlappingRect(self: *const UiTestFixture) ui.Rect {
        return .{ .x = self.origin.x + 14, .y = self.origin.y + 3, .width = 8, .height = 4 };
    }

    fn transparentPosition(self: *const UiTestFixture) render.OverlayPosition {
        return .{ .col = self.origin.x - 2, .row = self.origin.y + 1 };
    }

    fn baseSample(self: *const UiTestFixture) render.OverlayPosition {
        return .{ .col = self.origin.x + 10, .row = self.origin.y + 7 };
    }

    fn overlapSample(self: *const UiTestFixture) render.OverlayPosition {
        return .{ .col = self.origin.x + 16, .row = self.origin.y + 4 };
    }

    /// Rebuild the sole semantic frame and derive the canvas from it without
    /// allocating. Stable ids preserve focus and presses across every rebuild.
    fn compose(self: *UiTestFixture, geometry: ui.Geometry) !void {
        try self.tree.beginFrame(geometry);
        const surface_id = ui.Id{ .value = "ui-test.surface" };
        try self.tree.addSurface(.{
            .id = surface_id,
            .role = "surface",
            .label = "UI test surface",
            .bounds = self.surfaceRect(),
        }, .{
            .rect = ui.Rect.empty,
            .fill = .blue,
            .border = .single,
            .border_style = .{ .foreground = .bright_white },
            .title = " UI ",
            .title_style = .{ .foreground = .bright_yellow, .face_style = .bold },
        });

        const styled_runs = [_]ui.Run{.{
            .text = "Styled",
            .style = .{ .foreground = .bright_white, .face_style = .bold_italic },
        }};
        try self.tree.addText(.{
            .id = .{ .value = "ui-test.styled" },
            .parent = surface_id,
            .role = "text",
            .label = "Styled",
            .bounds = self.textRect(),
        }, .{ .runs = &styled_runs });

        try self.tree.addInteractiveText(.{
            .id = .{ .value = "ui-test.action" },
            .parent = surface_id,
            .role = "action",
            .label = "Action",
            .action = "ui-test.activate",
            .bounds = self.interactiveRect(),
        }, .{
            .id = .{ .value = "ui-test.action" },
            .label = "Action",
            .action = "ui-test.activate",
            .normal = .{ .foreground = .bright_white },
            .hovered = .{
                .foreground = .bright_yellow,
                .face_style = .italic,
                .underline = .accent,
            },
            .focused = .{
                .foreground = .black,
                .background = .accent,
                .face_style = .bold,
            },
        });

        try self.tree.addInput(.{
            .id = .{ .value = "ui-test.input" },
            .parent = surface_id,
            .role = "input",
            .label = "Input",
            .bounds = self.inputRect(),
        }, &self.field, .{
            .text = .{ .foreground = .foreground, .background = .black },
            .selection_background = .selection,
            .cursor_background = .accent,
            .cursor_foreground = .background,
        });

        try self.tree.addSurface(.{
            .id = .{ .value = "ui-test.overlap" },
            .parent = surface_id,
            .role = "surface",
            .label = "Overlap",
            .bounds = self.overlappingRect(),
        }, .{
            .rect = ui.Rect.empty,
            .fill = .red,
        });

        const transparent_runs = [_]ui.Run{.{
            .text = " ",
            .style = .{ .foreground = .foreground },
        }};
        const transparent = self.transparentPosition();
        try self.tree.addText(.{
            .id = .{ .value = "ui-test.transparent" },
            .role = "text",
            .label = "Transparent",
            .bounds = .{
                .x = transparent.col,
                .y = transparent.row,
                .width = 1,
                .height = 1,
            },
        }, .{ .runs = &transparent_runs });
        try self.tree.endFrame();
        try self.tree.render(&self.canvas);
    }

    fn remove(self: *UiTestFixture, geometry: ui.Geometry) !void {
        try self.tree.beginFrame(geometry);
        try self.tree.endFrame();
        try self.tree.render(&self.canvas);
    }

    fn rerender(self: *UiTestFixture) !void {
        try self.tree.render(&self.canvas);
    }

    fn recordDispatch(self: *UiTestFixture, invocation: inputmod.Invocation) void {
        self.last_dispatch = .{
            .source = invocation.source,
            .origin = invocation.origin,
            .action = "ui-test.activate",
        };
        self.dispatch_count += 1;
    }

    fn view(self: *UiTestFixture) render.OverlayView {
        return self.canvas.view(&default_palette);
    }
};

const UiTestDispatch = struct {
    source: inputmod.InvocationSource,
    origin: ?ui.Id,
    action: []const u8,
};

const UiInteractionState = struct {
    hovered: ?usize = null,
    focused: ?usize = null,
    pressed: ?usize = null,
};

const TerminalInputDebt = struct {
    encoded: usize = 0,
    staged: usize = 0,
    committed: usize = 0,
    paste: bool = false,
    responses: usize = 0,

    fn remains(self: TerminalInputDebt) bool {
        return self.encoded != 0 or self.staged != 0 or self.committed != 0 or
            self.paste or self.responses != 0;
    }
};

const ui_key_capacity: usize = 16;

const UiKeyIdentity = union(enum) {
    named: platform.Key,
    character: u21,
};

fn uiKeyIdentity(raw: platform.KeyEvent) ?UiKeyIdentity {
    if (raw.key != .unidentified) return .{ .named = raw.key };
    if (raw.unshifted_codepoint == 0) return null;
    return .{ .character = raw.unshifted_codepoint };
}

fn uiKeyIdentityEql(a: UiKeyIdentity, b: UiKeyIdentity) bool {
    return switch (a) {
        .named => |a_named| switch (b) {
            .named => |b_named| a_named == b_named,
            .character => false,
        },
        .character => |a_character| switch (b) {
            .named => false,
            .character => |b_character| a_character == b_character,
        },
    };
}

const UiKeyText = struct {
    bytes: [4]u8 = undefined,
    len: u3 = 0,

    fn copy(text: []const u8) UiKeyText {
        std.debug.assert(text.len <= 4);
        var copied: UiKeyText = .{ .len = @intCast(text.len) };
        @memcpy(copied.bytes[0..text.len], text);
        return copied;
    }

    fn slice(self: *const UiKeyText) []const u8 {
        return self.bytes[0..self.len];
    }
};

const UiInputEdit = enum {
    previous,
    next,
    home,
    end,
    backspace,
    delete,
};

const UiTextOperation = struct { origin: ui.Id, value: UiKeyText };
const UiEditOperation = struct { origin: ui.Id, operation: UiInputEdit, extend: bool };

const UiKeyRepeat = union(enum) {
    none,
    text: UiTextOperation,
    edit: UiEditOperation,
};

const UiOwnedKey = struct {
    identity: UiKeyIdentity,
    repeat: UiKeyRepeat,
};

fn searchKeyAction(
    profile: inputmod.PlatformProfile,
    visible: bool,
    key: platform.KeyEvent,
) ?[]const u8 {
    const letter = std.ascii.toLower(@as(u8, @intCast(@min(key.unshifted_codepoint, 0xff))));
    const open = switch (profile) {
        .macos => letter == 'f' and key.mods.super and !key.mods.ctrl and !key.mods.alt and !key.mods.shift,
        .linux_windows => letter == 'f' and key.mods.ctrl and key.mods.shift and !key.mods.alt and !key.mods.super,
    };
    if (!visible) return if (open) search_open_action else null;
    if (open) return search_open_action;
    if (key.key == .escape and !key.mods.ctrl and !key.mods.alt and !key.mods.shift and !key.mods.super) {
        return search_close_action;
    }
    if ((key.key == .enter or key.key == .f3) and !key.mods.ctrl and !key.mods.alt and !key.mods.super) {
        return if (key.mods.shift) search_previous_action else search_next_action;
    }
    if (key.mods.alt and !key.mods.ctrl and !key.mods.shift and !key.mods.super) {
        if (letter == 'c') return search_case_action;
        if (letter == 'r') return search_regex_action;
    }
    return null;
}

fn nextSearchIndex(current: usize, count: usize, next: bool) usize {
    if (count == 0) return 0;
    const bounded = @min(current, count - 1);
    if (next) return (bounded + 1) % count;
    return if (bounded == 0) count - 1 else bounded - 1;
}

fn searchWorkPending(
    visible: bool,
    engine_live: bool,
    needs_sync: bool,
    progress: term.SearchProgress,
    has_page_scan: bool,
) bool {
    return visible and engine_live and
        (needs_sync or searchVisibleProgress(progress, has_page_scan) == .running);
}

/// Engine progress covers literal history preparation. Page materialization
/// is separate work (and all regex work), so it remains user-visible as a
/// running search until its cursor reaches a real boundary.
fn searchVisibleProgress(progress: term.SearchProgress, has_page_scan: bool) term.SearchProgress {
    return if (has_page_scan) .running else progress;
}

fn searchFailureText(err: anyerror) []const u8 {
    return switch (err) {
        error.InvalidRegex => "invalid regex",
        error.RegexTooComplex => "regex too complex",
        error.RegexWorkLimit => "regex work limit",
        else => @errorName(err),
    };
}

/// Inline transition ownership survives App's return-by-value move without a
/// self-referential slice. Identity deliberately excludes modifiers: releasing
/// them before the target key cannot change who owns that target's release.
const UiKeyState = struct {
    storage: [ui_key_capacity]UiOwnedKey = undefined,
    len: usize = 0,

    fn indexOf(self: *const UiKeyState, identity: UiKeyIdentity) ?usize {
        for (self.storage[0..self.len], 0..) |owned, index| {
            if (uiKeyIdentityEql(owned.identity, identity)) return index;
        }
        return null;
    }

    fn claim(self: *UiKeyState, identity: UiKeyIdentity, repeat: UiKeyRepeat) bool {
        if (self.indexOf(identity) != null or self.len == self.storage.len) return false;
        self.storage[self.len] = .{ .identity = identity, .repeat = repeat };
        self.len += 1;
        return true;
    }

    fn release(self: *UiKeyState, index: usize) void {
        var destination = index;
        while (destination + 1 < self.len) : (destination += 1) {
            self.storage[destination] = self.storage[destination + 1];
        }
        self.len -= 1;
    }
};

/// One row of the terminal context menu: a stable semantic id, its terse label
/// and the completed named action the row dispatches. All strings are
/// comptime constants, so a composed row borrows nothing that can move.
const ContextMenuItem = struct {
    id: []const u8,
    label: []const u8,
    action: []const u8,
};

const context_menu_copy_item: ContextMenuItem = .{ .id = "context-menu.copy", .label = "copy", .action = clipboard_copy_action };
const context_menu_paste_item: ContextMenuItem = .{ .id = "context-menu.paste", .label = "paste", .action = clipboard_paste_action };
const context_menu_open_link_item: ContextMenuItem = .{ .id = "context-menu.open-link", .label = "open link", .action = terminal_open_link_action };
const context_menu_split_right_item: ContextMenuItem = .{ .id = "context-menu.split-right", .label = "split right", .action = pane_split_action };
const context_menu_split_down_item: ContextMenuItem = .{ .id = "context-menu.split-down", .label = "split down", .action = pane_split_action };
const context_menu_search_item: ContextMenuItem = .{ .id = "context-menu.search", .label = "search", .action = search_open_action };

/// Every row the menu can show; the composed list is a subset in this order.
const context_menu_max_items: usize = 6;
/// Border, one cell of padding each side and the widest label (`split right`).
const context_menu_width: u32 = 15;

/// The rows the menu shows for one gesture. `copy` needs something to copy and
/// `open link` needs a link under the pointer; the rest always apply to a
/// terminal pane. Pure so the rule is unit-testable without a window.
fn contextMenuItems(
    has_selection: bool,
    has_link: bool,
    storage: *[context_menu_max_items]ContextMenuItem,
) []const ContextMenuItem {
    var count: usize = 0;
    if (has_selection) {
        storage[count] = context_menu_copy_item;
        count += 1;
    }
    storage[count] = context_menu_paste_item;
    count += 1;
    if (has_link) {
        storage[count] = context_menu_open_link_item;
        count += 1;
    }
    storage[count] = context_menu_split_right_item;
    count += 1;
    storage[count] = context_menu_split_down_item;
    count += 1;
    storage[count] = context_menu_search_item;
    count += 1;
    return storage[0..count];
}

/// Where the menu panel sits: its top-left corner on the anchor cell, moved
/// left or up only as far as needed to keep every row inside the canvas. A
/// canvas too small for the whole panel gets no menu rather than a clipped one.
fn contextMenuBounds(anchor_col: u32, anchor_row: u32, item_count: usize, canvas: ui.Rect) ?ui.Rect {
    const height: u32 = @as(u32, @intCast(item_count)) + 2;
    if (canvas.width < context_menu_width or canvas.height < height) return null;
    return .{
        .x = @min(anchor_col, canvas.width - context_menu_width),
        .y = @min(anchor_row, canvas.height - height),
        .width = context_menu_width,
        .height = height,
    };
}

/// The open context menu. Everything a row needs at activation is copied here
/// when the menu opens, because the semantic tree it was read from is rebuilt
/// before any row runs.
const ContextMenu = struct {
    /// The canvas cell the panel is anchored to before clamping.
    col: u32,
    row: u32,
    /// Whether the presented terminal had a selection when the menu opened.
    has_selection: bool,
    /// The stable id of the terminal link under the pointer, if any.
    link_id_len: usize = 0,
    link_id: [terminal_link_semantic_capacity]u8 = undefined,

    fn linkId(self: *const ContextMenu) ?[]const u8 {
        return if (self.link_id_len == 0) null else self.link_id[0..self.link_id_len];
    }
};

const UiKeyPlan = union(enum) {
    consume,
    focus: bool,
    focus_id: ui.Id,
    workspace_focus: bool,
    activate: ui.Activation,
    palette_close,
    palette_move: bool,
    palette_activate,
    context_menu_close,
    context_menu_move: bool,
    context_menu_activate,
    notifications_close,
    notifications_move: bool,
    notifications_activate,
    select_all: ui.Id,
    copy: ui.Id,
    paste: ui.Id,
    text: UiTextOperation,
    edit: UiEditOperation,

    fn repeat(self: UiKeyPlan) UiKeyRepeat {
        return switch (self) {
            .text => |text| .{ .text = text },
            .edit => |edit| .{ .edit = edit },
            else => .none,
        };
    }
};

fn uiInteractionState(tree: *const ui.Tree) UiInteractionState {
    var state: UiInteractionState = .{};
    for (tree.elements(), 0..) |element, index| {
        if (element.state.hovered) state.hovered = index;
        if (element.state.focused) state.focused = index;
        if (element.state.pressed) state.pressed = index;
    }
    return state;
}

fn devicePointerPoint(x: f32, y: f32, scale: platform.Scale) ui.Point {
    return .{
        .x = devicePointerCoordinate(x, scale),
        .y = devicePointerCoordinate(y, scale),
    };
}

fn devicePointerCoordinate(logical: f32, scale: platform.Scale) i32 {
    if (!std.math.isFinite(logical)) return 0;
    const device = @as(f64, @floatCast(logical)) * @as(f64, scale.factor);
    if (!std.math.isFinite(device)) return if (device < 0) std.math.minInt(i32) else std.math.maxInt(i32);
    const rounded = @floor(device);
    if (rounded <= @as(f64, @floatFromInt(std.math.minInt(i32)))) return std.math.minInt(i32);
    if (rounded >= @as(f64, @floatFromInt(std.math.maxInt(i32)))) return std.math.maxInt(i32);
    return @intFromFloat(rounded);
}

/// Cell width of a valid UTF-8 preedit prefix. This mirrors Text's grapheme
/// measurement without allocating, so the native candidate window can follow
/// the caret that the inline renderer actually draws.
fn preeditCellWidth(text: []const u8) ?u32 {
    const view = std.unicode.Utf8View.init(text) catch return null;
    var codepoints: [inputmod.Composition.max_preedit]u21 = undefined;
    var count: usize = 0;
    var iterator = view.iterator();
    while (iterator.nextCodepoint()) |codepoint| {
        if (codepoint < 0x20 or (codepoint >= 0x7f and codepoint < 0xa0)) continue;
        codepoints[count] = codepoint;
        count += 1;
    }

    var width: u32 = 0;
    var index: usize = 0;
    while (index < count) {
        const measured = term.graphemeWidth(codepoints[index..count]);
        width +|= measured.width;
        index += @max(measured.len, 1);
    }
    return width;
}

/// Terminal cells `text` occupies. Invalid UTF-8 counts one cell per byte so
/// a malformed label can never under-size its row.
fn labelCellWidth(text: []const u8) u32 {
    const view = std.unicode.Utf8View.init(text) catch return @intCast(@min(text.len, std.math.maxInt(u32)));
    var codepoints: [64]u21 = undefined;
    var count: usize = 0;
    var width: u32 = 0;
    var iterator = view.iterator();
    while (true) {
        const next = iterator.nextCodepoint();
        if (next) |codepoint| {
            if (codepoint < 0x20 or (codepoint >= 0x7f and codepoint < 0xa0)) continue;
            codepoints[count] = codepoint;
            count += 1;
            if (count < codepoints.len) continue;
        }
        // Measure whole buffers; a grapheme split across two buffers is
        // measured as two, which only ever over-sizes a row.
        var index: usize = 0;
        while (index < count) {
            const measured = term.graphemeWidth(codepoints[index..count]);
            width +|= measured.width;
            index += @max(measured.len, 1);
        }
        count = 0;
        if (next == null) break;
    }
    return width;
}

/// One sidebar footer row with `label` centred in the content columns. A
/// label wider than the content starts at the first column and clips.
fn centeredFooterRow(label: []const u8, content_width: u32, y: u32) ui.Rect {
    const cells = labelCellWidth(label);
    if (cells >= content_width) return .{ .x = 1, .y = y, .width = content_width, .height = 1 };
    return .{ .x = 1 + (content_width - cells) / 2, .y = y, .width = cells, .height = 1 };
}

fn utf8Boundary(text: []const u8, offset: usize) bool {
    if (offset > text.len) return false;
    return std.unicode.utf8ValidateSlice(text[0..offset]);
}

fn privateArtifactPermissions(comptime directory: bool) File.Permissions {
    if (comptime builtin.os.tag == .windows) {
        return if (directory) .default_dir else .default_file;
    } else {
        return .fromMode(if (directory) 0o700 else 0o600);
    }
}

/// One PNG artifact encoded and persisted away from the render thread.
///
/// The main thread owns the OpenGL readback and hands this job an independent
/// pixel copy. The worker owns PNG compression and filesystem IO, then wakes
/// SDL so the driver response can be completed on the main thread.
const ScreenshotJob = struct {
    allocator: Allocator,
    io: Io,
    window: ?*platform.Window,
    path: []u8,
    pixels: []u8,
    size: render.Size,
    state: std.atomic.Value(u32) = .init(0),
    failure: ?[]const u8 = null,
    thread: ?std.Thread = null,

    fn start(self: *ScreenshotJob) !void {
        self.thread = try std.Thread.spawn(.{}, work, .{self});
    }

    fn finished(self: *const ScreenshotJob) bool {
        return self.state.load(.acquire) != 0;
    }

    fn work(self: *ScreenshotJob) void {
        self.write() catch |err| {
            self.failure = @errorName(err);
        };
        self.state.store(1, .release);
        if (self.window) |window| window.postDriverWake() catch |err| {
            log.warn("screenshot worker could not wake the event loop: {s}", .{@errorName(err)});
        };
    }

    fn write(self: *ScreenshotJob) !void {
        const encoded = try render.encodePng(self.allocator, self.size, self.pixels);
        defer self.allocator.free(encoded);

        const parent = std.fs.path.dirname(self.path) orelse ".";
        _ = try Dir.cwd().createDirPathStatus(self.io, parent, privateArtifactPermissions(true));
        var file = try Dir.cwd().createFile(self.io, self.path, .{
            .exclusive = true,
            .permissions = privateArtifactPermissions(false),
        });
        var complete = false;
        defer {
            file.close(self.io);
            if (!complete) Dir.cwd().deleteFile(self.io, self.path) catch |err| {
                log.warn("could not remove an incomplete screenshot: {s}", .{@errorName(err)});
            };
        }
        var buffer: [4096]u8 = undefined;
        var streaming = file.writerStreaming(self.io, &buffer);
        try streaming.interface.writeAll(encoded);
        try streaming.interface.flush();
        complete = true;
    }

    fn deinit(self: *ScreenshotJob) void {
        if (self.thread) |thread| thread.join();
        self.allocator.free(self.pixels);
        self.allocator.free(self.path);
        const allocator = self.allocator;
        self.* = undefined;
        allocator.destroy(self);
    }
};

const DriverPendingState = union(enum) {
    barrier: struct {
        id: u32,
        posted: bool,
    },
    wait: i128,
    screenshot: *ScreenshotJob,
};

/// One parsed driver request retained across event-loop turns.
///
/// Input requests retain their arena through the SDL barrier because a posted
/// text-input event borrows its UTF-8 bytes. Wait requests retain their
/// condition strings through their deadline.
const DriverPending = struct {
    token: u64,
    parsed: testdriver.ParsedRequest,
    state: DriverPendingState,
    text: ?[:0]u8 = null,

    fn deinit(self: *DriverPending, allocator: Allocator) void {
        if (self.text) |text| allocator.free(text);
        switch (self.state) {
            .screenshot => |job| job.deinit(),
            else => {},
        }
        self.parsed.deinit();
        self.* = undefined;
    }
};

const driver_pending_capacity = platform.max_driver_pending;

const PaneRenderer = struct {
    session_id: session.SessionId,
    grid: render.Grid,

    fn deinit(self: *PaneRenderer) void {
        self.grid.deinit();
        self.* = undefined;
    }
};

/// App-owned rendering and asynchronous presentation state for one
/// registry-owned workspace. The registry keeps the `Workspace` itself at a
/// stable heap address; this parallel record is also heap-stable so a worker
/// result can remain attributed to its originating workspace while selection
/// changes.
const WorkspacePresentation = struct {
    key: workspace.WorkspaceKey,
    active_session_id: session.SessionId,
    pane_renderers: std.ArrayList(PaneRenderer),
    scratchpad_grid: render.Grid,
    scratchpad_presentation: ScratchpadPresentation = .hidden,
    load: ?*Load = null,
    scratchpad_load: ?*Load = null,
    closing: bool = false,
    /// The SSH half of an SSH workspace (TASK-43), or null for a Local one.
    /// Owned; released with the presentation.
    remote: ?*RemotePresentation = null,
    /// The workspace's backlog view (TASK-63), created the first time it
    /// opens. Owned; released (its write joined) before the workspace.
    backlog: ?*backlog_view.Panel = null,
    /// The workspace's control token (TASK-60), issued the first time one of
    /// its terminals is spawned while the endpoint runs, revoked when the
    /// workspace closes.
    control_token: ?control_api.Token = null,
    /// Restored shells still to start, in plan order (TASK-65). One starts
    /// whenever `load` is free; an SSH workspace's wait for its connection.
    /// Each cwd is owned.
    restore_queue: std.ArrayList(RestoreStart) = .empty,

    fn releaseRestoreQueue(self: *WorkspacePresentation, allocator: Allocator) void {
        for (self.restore_queue.items) |item| allocator.free(item.cwd);
        self.restore_queue.deinit(allocator);
        self.restore_queue = .empty;
    }
};

/// One restored session whose shell has not been started yet (TASK-65).
const RestoreStart = struct {
    session_id: session.SessionId,
    /// Where it starts, owned: the saved directory, or a fallback, or empty
    /// for the inherited (Local) or home (SSH) directory.
    cwd: []u8,
};

// ---------------------------------------------------------------------------
// Workspace persistence (TASK-65)
// ---------------------------------------------------------------------------

/// The line a corrupt, unreadable or newer state file leaves in the sidebar.
const restore_unreadable_status = "previous state was unreadable; starting clean";
/// How an SSH workspace's own directory is saved: the remote home, which has
/// no local spelling (`state` refuses an empty cwd).
const remote_home_marker = "~";
/// A restored window size is kept within these logical pixels.
const min_restored_window: u32 = 200;
const max_restored_window: u32 = 16384;
/// How long the layout must stay unchanged before it is saved.
const save_debounce_ns: i128 = 2 * std.time.ns_per_s;

/// When process startup began, for the debug startup phase log (TASK-67).
/// Written once by `runApp` on the main thread before anything else reads it.
var startup_epoch_ns: i128 = 0;

/// One startup phase as the debug log prints it.
fn startupPhaseLine(buffer: []u8, phase: []const u8, elapsed_ns: i128) []const u8 {
    const tenths = @divTrunc(@max(elapsed_ns, 0), std.time.ns_per_ms / 10);
    return std.fmt.bufPrint(buffer, "startup: {s} after {d}.{d} ms", .{ phase, @divTrunc(tenths, 10), @mod(tenths, 10) }) catch "startup: phase";
}

test "startup phase lines name the phase and the milliseconds since start" {
    var buffer: [96]u8 = undefined;
    try std.testing.expectEqualStrings("startup: window after 12.3 ms", startupPhaseLine(&buffer, "window", 12_345_678));
    try std.testing.expectEqualStrings("startup: first frame after 0.0 ms", startupPhaseLine(&buffer, "first frame", 10));
    try std.testing.expectEqualStrings("startup: fonts after 0.0 ms", startupPhaseLine(&buffer, "fonts", -5));
    var tiny: [8]u8 = undefined;
    try std.testing.expectEqualStrings("startup: phase", startupPhaseLine(&tiny, "first child", 1));
}

/// Saves after the layout has stayed unchanged for `save_debounce_ns`, and
/// never twice for the same layout. Pure: the loop feeds it fingerprints and
/// times.
const SaveDebounce = struct {
    /// The layout last observed and when it was first seen.
    current: ?u64 = null,
    changed_ns: i128 = 0,
    /// The layout last handed to a save.
    saved: ?u64 = null,

    fn note(self: *SaveDebounce, fingerprint: u64, now_ns: i128) void {
        if (self.current) |current| if (current == fingerprint) return;
        self.current = fingerprint;
        self.changed_ns = now_ns;
    }

    fn pending(self: *const SaveDebounce) bool {
        const current = self.current orelse return false;
        const saved = self.saved orelse return true;
        return saved != current;
    }

    fn due(self: *const SaveDebounce, now_ns: i128) bool {
        return self.pending() and now_ns - self.changed_ns >= save_debounce_ns;
    }

    /// When the pending save falls due, or null when nothing is owed.
    fn deadline(self: *const SaveDebounce) ?i128 {
        if (!self.pending()) return null;
        return self.changed_ns + save_debounce_ns;
    }

    fn markSaved(self: *SaveDebounce) void {
        self.saved = self.current;
    }
};

test "a save is due two seconds after the last change and never twice for one layout" {
    var debounce: SaveDebounce = .{};
    try std.testing.expect(!debounce.due(0));
    try std.testing.expectEqual(@as(?i128, null), debounce.deadline());
    debounce.note(1, 0);
    debounce.markSaved();
    try std.testing.expect(!debounce.due(10 * std.time.ns_per_s));

    debounce.note(2, std.time.ns_per_s);
    try std.testing.expectEqual(@as(?i128, 3 * std.time.ns_per_s), debounce.deadline());
    try std.testing.expect(!debounce.due(2 * std.time.ns_per_s));
    // Another change restarts the wait; the same layout seen again does not.
    debounce.note(3, 2 * std.time.ns_per_s);
    debounce.note(3, 3 * std.time.ns_per_s);
    try std.testing.expect(!debounce.due(3 * std.time.ns_per_s));
    try std.testing.expect(debounce.due(4 * std.time.ns_per_s));
    debounce.markSaved();
    try std.testing.expect(!debounce.due(60 * std.time.ns_per_s));
    // Returning to a layout that was saved earlier is still a change.
    debounce.note(2, 61 * std.time.ns_per_s);
    try std.testing.expect(debounce.due(63 * std.time.ns_per_s));
}

/// What the app adds to the registry's snapshot (TASK-65).
const SnapshotExtras = struct {
    theme: ?[]const u8 = null,
    window: ?state_mod.Window = null,
    saved_at_unix: i64 = 0,
    /// The directory a workspace with an empty cwd means (the one Conduit
    /// was started in), or null when unknown.
    process_cwd: ?[]const u8 = null,
    /// Per registry index: the scratchpad's percentage while shown.
    scratchpad_percents: []const ?u8 = &.{},
    /// Per registry index: whether the workspace is closing (not saved).
    closing: []const bool = &.{},
};

/// Complete `owned` with the app's values and make it representable: an
/// empty Local cwd becomes the process cwd (or `/`), an empty SSH cwd the
/// remote home marker, a leaf that tracked no directory of its own falls
/// back to its workspace's, and closing workspaces are dropped.
fn completeSnapshot(owned: *state_mod.Owned, extras: SnapshotExtras) Allocator.Error!void {
    const arena = owned.allocator();
    const snapshot = &owned.snapshot;
    snapshot.saved_at_unix = extras.saved_at_unix;
    snapshot.theme = if (extras.theme) |name| try arena.dupe(u8, name) else null;
    snapshot.window = extras.window;
    var kept = try arena.alloc(state_mod.WorkspaceState, snapshot.workspaces.len);
    var kept_len: usize = 0;
    var active: ?usize = null;
    for (snapshot.workspaces, 0..) |source, index| {
        if (index < extras.closing.len and extras.closing[index]) continue;
        if (snapshot.active_workspace) |selected| if (selected == index) {
            active = kept_len;
        };
        var item = source;
        if (item.cwd.len == 0) item.cwd = switch (item.kind) {
            .ssh, .wsl => remote_home_marker,
            .local => if (extras.process_cwd) |cwd| try arena.dupe(u8, cwd) else "/",
        };
        if (index < extras.scratchpad_percents.len) item.scratchpad_percent = extras.scratchpad_percents[index];
        const tabs = try arena.alloc(state_mod.TabState, item.tabs.len);
        for (item.tabs, tabs) |tab, *out| {
            out.* = tab;
            out.panes = try dropEmptyCwds(arena, &tab.panes);
        }
        item.tabs = tabs;
        kept[kept_len] = item;
        kept_len += 1;
    }
    snapshot.workspaces = kept[0..kept_len];
    snapshot.active_workspace = if (kept_len == 0) null else active orelse 0;
}

fn dropEmptyCwds(arena: Allocator, node: *const state_mod.PaneNode) Allocator.Error!state_mod.PaneNode {
    switch (node.*) {
        .leaf => |leaf| {
            const cwd = leaf.cwd orelse return node.*;
            return if (cwd.len == 0) .{ .leaf = .{} } else node.*;
        },
        .split => |split| {
            const first = try arena.create(state_mod.PaneNode);
            first.* = try dropEmptyCwds(arena, split.first);
            const second = try arena.create(state_mod.PaneNode);
            second.* = try dropEmptyCwds(arena, split.second);
            var out = split;
            out.first = first;
            out.second = second;
            return .{ .split = out };
        },
    }
}

test "a completed snapshot carries the app's values and is always representable" {
    const testing = std.testing;
    const empty_leaf: state_mod.PaneNode = .{ .leaf = .{ .cwd = "" } };
    const kept_leaf: state_mod.PaneNode = .{ .leaf = .{ .cwd = "/srv/app" } };
    const tabs = [_]state_mod.TabState{.{ .panes = .{ .split = .{ .direction = .right, .ratio = 0.5, .first = &empty_leaf, .second = &kept_leaf } } }};
    const remote_tabs = [_]state_mod.TabState{.{ .panes = .{ .leaf = .{ .cwd = "/home/deploy/www" } } }};
    const workspaces = [_]state_mod.WorkspaceState{
        .{ .name = "default", .cwd = "", .tabs = &tabs, .active_tab = 0 },
        .{ .name = "closing", .cwd = "/tmp", .tabs = &tabs, .active_tab = 0 },
        .{ .name = "prod", .kind = .ssh, .cwd = "", .ssh = .{ .destination = "deploy@prod" }, .tabs = &remote_tabs, .active_tab = 0 },
    };
    var owned: state_mod.Owned = .{ .arena = .init(testing.allocator), .snapshot = .{ .active_workspace = 2, .workspaces = &workspaces } };
    defer owned.deinit();
    try completeSnapshot(&owned, .{
        .theme = "Nord",
        .window = .{ .width = 640, .height = 360 },
        .saved_at_unix = 1_800_000_000,
        .process_cwd = "/home/u",
        .scratchpad_percents = &.{ 90, null, null },
        .closing = &.{ false, true, false },
    });
    const snapshot = owned.snapshot;
    try testing.expectEqualStrings("Nord", snapshot.theme.?);
    try testing.expectEqual(@as(u32, 640), snapshot.window.?.width);
    try testing.expectEqual(@as(i64, 1_800_000_000), snapshot.saved_at_unix);
    try testing.expectEqual(@as(usize, 2), snapshot.workspaces.len);
    try testing.expectEqual(@as(?usize, 1), snapshot.active_workspace);
    try testing.expectEqualStrings("/home/u", snapshot.workspaces[0].cwd);
    try testing.expectEqual(@as(?u8, 90), snapshot.workspaces[0].scratchpad_percent);
    try testing.expectEqual(@as(?[]const u8, null), snapshot.workspaces[0].tabs[0].panes.split.first.leaf.cwd);
    try testing.expectEqualStrings("/srv/app", snapshot.workspaces[0].tabs[0].panes.split.second.leaf.cwd.?);
    try testing.expectEqualStrings(remote_home_marker, snapshot.workspaces[1].cwd);
    try testing.expectEqualStrings("deploy@prod", snapshot.workspaces[1].ssh.?.destination);
    // What used to be refused (an empty cwd) now encodes and decodes.
    var diagnostic: state_mod.Diagnostic = .{};
    const bytes = try state_mod.encode(testing.allocator, &snapshot, &diagnostic);
    defer testing.allocator.free(bytes);
    var decoded = try state_mod.decode(testing.allocator, bytes, &diagnostic);
    defer decoded.deinit();
    try state_mod.expectSameSnapshot(&snapshot, &decoded.snapshot);
}

test "only a plain run or the restore check persists, and checks never read a state file" {
    const testing = std.testing;
    const env = test_env{ .vars = &.{ .{ "XDG_STATE_HOME", "/state" }, .{ "HOME", "/home/u" }, .{ "LOCALAPPDATA", "C:\\state" } } };
    var plain = Persistence.forRun(testing.allocator, testing.io, env.source(), .{}, true);
    defer plain.deinit();
    // Each platform's own state location (`state.statePath`).
    const expected_path = switch (builtin.os.tag) {
        .windows => "C:\\state\\conduit\\state.json",
        .macos => "/home/u/Library/Application Support/conduit/state.json",
        else => "/state/conduit/state.json",
    };
    try testing.expectEqualStrings(expected_path, plain.path orelse return error.TestUnexpectedResult);

    var off = Persistence.forRun(testing.allocator, testing.io, env.source(), .{}, false);
    defer off.deinit();
    try testing.expect(off.path == null);

    const refused = [_]Run{
        .{ .tabs_test = true },
        .{ .workspaces_test = true },
        .{ .panes_test = true },
        .{ .driver_test = true },
        .{ .ui_test = true },
        .{ .a11y_test = true },
        .{ .command = "true" },
        .{ .test_driver_endpoint = "/tmp/driver.sock" },
    };
    for (refused) |run| {
        var check = Persistence.forRun(testing.allocator, testing.io, env.source(), .{ .run = run }, true);
        defer check.deinit();
        try testing.expect(check.path == null);
    }

    var restore = Persistence.forRun(testing.allocator, testing.io, env.source(), .{ .run = .{ .restore_test = true, .state_path = "/tmp/r/state.json" } }, true);
    defer restore.deinit();
    try testing.expectEqualStrings("/tmp/r/state.json", restore.path.?);
}

test "--no-restore, --restore-test and --a11y-test parse, and the checks run fixed and isolated" {
    const env = test_env{ .vars = &.{} };
    const parsed = try parseArgs(&.{ "conduit", "--no-restore", "--width=800" }, env.source());
    try std.testing.expect(parsed.run.no_restore);
    try std.testing.expect(parsed.run.size_explicit);
    try std.testing.expect(!(try parseArgs(&.{"conduit"}, env.source())).run.size_explicit);
    const restore = optionsForRun(try parseArgs(&.{ "conduit", "--restore-test" }, env.source()));
    try std.testing.expect(restore.run.restore_test and restore.run.hidden and restore.run.width == ui_test_width);
    try std.testing.expect(wantsChild(restore) and usesDeterministicScratchpad(restore));
    const a11y = optionsForRun(try parseArgs(&.{ "conduit", "--a11y-test" }, env.source()));
    try std.testing.expect(a11y.run.a11y_test and a11y.run.no_child and !wantsChild(a11y));
}

/// Whether `path` is a directory in `context`.
fn directoryExists(io: Io, context: workspace.ExecutionContext.Ref, path: []const u8) bool {
    const stat = context.statPath(io, path) catch return false;
    return stat.kind == .directory;
}

/// Whether a plan creates a workspace named `name` (names compare trimmed).
fn planNamesWorkspace(plan: *const state_mod.RestorePlan, name: []const u8) bool {
    const wanted = std.mem.trim(u8, name, std.ascii.whitespace[0..]);
    for (plan.steps) |step| switch (step) {
        .create_workspace => |value| if (std.mem.eql(u8, std.mem.trim(u8, value.name, std.ascii.whitespace[0..]), wanted)) return true,
        else => {},
    };
    return false;
}

/// Writes one encoded state file on a worker, so the loop never waits on
/// the disk. Main thread creates, polls and destroys it; the worker owns
/// nothing but reads `bytes` and `path` and publishes `done`.
const SaveJob = struct {
    allocator: Allocator,
    io: Io,
    path: []const u8,
    /// The encoded document, owned.
    bytes: []u8,
    thread: ?std.Thread = null,
    done: std.atomic.Value(bool) = .init(false),
    failure: ?[]const u8 = null,

    fn work(self: *SaveJob) void {
        state_mod.save(self.io, self.path, self.bytes) catch |err| {
            self.failure = @errorName(err);
        };
        self.done.store(true, .release);
    }

    fn finish(self: *SaveJob) void {
        if (self.thread) |thread| thread.join();
        self.thread = null;
        if (self.failure) |name| log.warn("the workspace state was not saved: {s}", .{name}) else log.debug("workspace state saved", .{});
        self.allocator.free(self.bytes);
        self.allocator.destroy(self);
    }
};

/// The app's persistence state (TASK-65). Main thread.
const Persistence = struct {
    allocator: ?Allocator = null,
    io: ?Io = null,
    /// The state file, owned; null when this run neither saves nor restores.
    path: ?[]u8 = null,
    /// The directory Conduit was started in, owned: what a workspace with no
    /// directory of its own (the default one) is saved as.
    process_cwd: ?[:0]u8 = null,
    debounce: SaveDebounce = .{},
    worker: ?*SaveJob = null,
    /// Saves completed (or attempted), for `--restore-test`.
    saves: usize = 0,
    /// The theme restored from the file, used while the settings file names
    /// none (`resolveTheme`).
    restored_theme_storage: [theme_name_capacity]u8 = undefined,
    restored_theme_len: usize = 0,
    /// Backs a restore status line.
    status_storage: [palette_label_capacity]u8 = undefined,

    /// Decide whether this run persists, and where: `--restore-test`'s
    /// private file, else the platform state file for a plain run with
    /// `restore.enabled` on. Checks, `--command` runs and driven runs never
    /// save or restore, so automation leaves no state behind.
    fn forRun(allocator: Allocator, io: Io, env: EnvSource, options: Options, setting: bool) Persistence {
        var result: Persistence = .{ .allocator = allocator, .io = io };
        var buffer: [path_capacity]u8 = undefined;
        const path = options.run.state_path orelse path: {
            if (!setting) return result;
            if (usesDeterministicScratchpad(options) or options.run.command != null or
                options.run.test_driver_endpoint != null) return result;
            break :path state_mod.statePath(&buffer, builtin.os.tag, .{
                .xdg_state_home = env.get("XDG_STATE_HOME"),
                .home = env.get("HOME"),
                .local_app_data = env.get("LOCALAPPDATA"),
            }) orelse {
                log.info("no state directory: workspaces are not saved", .{});
                return result;
            };
        };
        result.path = allocator.dupe(u8, path) catch return result;
        result.process_cwd = std.process.currentPathAlloc(io, allocator) catch null;
        log.debug("workspace state at {s}", .{path});
        return result;
    }

    fn deinit(self: *Persistence) void {
        self.joinWorker();
        const allocator = self.allocator orelse return;
        if (self.path) |path| allocator.free(path);
        if (self.process_cwd) |cwd| allocator.free(cwd);
        self.path = null;
        self.process_cwd = null;
    }

    fn noteLayout(self: *Persistence, fingerprint: u64, now_ns: i128) void {
        self.debounce.note(fingerprint, now_ns);
    }

    fn markSaved(self: *Persistence) void {
        self.debounce.markSaved();
    }

    fn restoredTheme(self: *const Persistence) ?[]const u8 {
        if (self.restored_theme_len == 0) return null;
        return self.restored_theme_storage[0..self.restored_theme_len];
    }

    fn setRestoredTheme(self: *Persistence, name: []const u8) void {
        const len = @min(name.len, self.restored_theme_storage.len);
        @memcpy(self.restored_theme_storage[0..len], name[0..len]);
        self.restored_theme_len = len;
    }

    /// Collect a finished save.
    fn collect(self: *Persistence) void {
        const job = self.worker orelse return;
        if (!job.done.load(.acquire)) return;
        job.finish();
        self.worker = null;
        self.saves += 1;
    }

    fn joinWorker(self: *Persistence) void {
        const job = self.worker orelse return;
        job.finish();
        self.worker = null;
        self.saves += 1;
    }

    /// Write `bytes` (ownership transfers) on a worker, or right here when
    /// the worker cannot start.
    fn saveAsync(self: *Persistence, bytes: []u8) void {
        const allocator = self.allocator.?;
        self.markSaved();
        const job = allocator.create(SaveJob) catch {
            defer allocator.free(bytes);
            self.saveNow(bytes);
            return;
        };
        job.* = .{ .allocator = allocator, .io = self.io.?, .path = self.path.?, .bytes = bytes };
        job.thread = std.Thread.spawn(.{}, SaveJob.work, .{job}) catch {
            allocator.destroy(job);
            defer allocator.free(bytes);
            self.saveNow(bytes);
            return;
        };
        self.worker = job;
    }

    /// Write `bytes` (borrowed) on this thread.
    fn saveNow(self: *Persistence, bytes: []const u8) void {
        const path = self.path orelse return;
        self.markSaved();
        state_mod.save(self.io.?, path, bytes) catch |err| {
            log.warn("the workspace state was not saved: {s}", .{@errorName(err)});
        };
        self.saves += 1;
    }
};

/// One control request the owner has not answered yet (TASK-60).
const ControlPending = struct {
    /// The server that holds the ticket; null for the startup command.
    server: ?*control_api.Server,
    ticket: control_api.Ticket,
    /// Borrowed from the server's queue slot (or the startup request) until
    /// the ticket is completed.
    request: *const control_api.Request,
    /// When a waiting request gives up with `Unavailable` (awake clock).
    deadline_ns: i96,
    state: union(enum) {
        /// Input, a modal or the workspace's spawn slot is busy; retried on
        /// every loop iteration, in order.
        waiting,
        /// The tab, pane or agent exists and its child is being spawned; the
        /// reply goes out when the worker reports back.
        spawning: struct { key: workspace.WorkspaceKey, session_id: session.SessionId, opened: control_api.Opened },
    },
};

/// How long a deferred control request waits for the app to be free before
/// it is refused, kept under the server's own five-second reply deadline.
const control_wait_ms: i96 = 4000;
/// The most deferred control requests at once: one per queue slot.
const control_pending_capacity: usize = 32;
/// The most tabs with a `tab.status` mark at once.
const control_status_capacity: usize = 64;
/// How many queued control requests one loop iteration takes.
const control_service_batch: usize = 8;

/// One tab's `tab.status` mark (TASK-60): a short text shown before the tab's
/// name and an attention mark like a bell's, until cleared or the tab is
/// activated by the person.
const ControlTabStatus = struct {
    key: workspace.WorkspaceKey,
    tab_id: workspace.TabId,
    text: [control_api.protocol.max_status_bytes]u8 = undefined,
    text_len: u8 = 0,
    attention: bool = false,

    fn textSlice(self: *const ControlTabStatus) []const u8 {
        return self.text[0..self.text_len];
    }
};

/// The sidebar label for a tab with a `tab.status` mark: the attention mark
/// (or the tab's own `* `/`! `), the status text and the name.
fn controlTabLabel(buffer: []u8, display_label: []const u8, name: []const u8, mark: *const ControlTabStatus) []const u8 {
    const prefix = if (mark.attention) "! " else display_label[0 .. display_label.len - name.len];
    if (mark.text_len == 0) return std.fmt.bufPrint(buffer, "{s}{s}", .{ prefix, name }) catch display_label;
    return std.fmt.bufPrint(buffer, "{s}{s} {s}", .{ prefix, mark.textSlice(), name }) catch display_label;
}

/// Release a workspace's backlog view, joining a write in flight that borrows
/// the workspace's context. Main thread.
fn releaseBacklog(allocator: Allocator, presentation: *WorkspacePresentation) void {
    const panel = presentation.backlog orelse return;
    panel.deinit();
    allocator.destroy(panel);
    presentation.backlog = null;
}

/// The app's state for one SSH workspace (TASK-43 part two, decision-8).
///
/// Thread ownership: the main thread. `context` is borrowed from the
/// workspace that owns it and outlives this record (the record is released
/// before the workspace is removed). The only worker is `host_probe`, which
/// borrows the context's capability and is joined before release.
///
/// The connection terminal (`connection_id`, a `connection` session whose
/// PTY is the master's view) is presented over the workspace's panes while
/// the master is not connected, so OpenSSH's own host-key, passphrase,
/// password and 2FA prompts are what the person sees and answers; and on
/// request (`remote.show-connection`) once connected. Its renderer lives in
/// the presentation's `pane_renderers` beside the panes', so fonts, colours
/// and invalidation reach it the same way.
const RemotePresentation = struct {
    context: *ssh.SshContext,
    connection_id: session.SessionId,
    /// The state the app last acted on; `context.poll` reports the next.
    state: ssh.State = .disconnected,
    /// Show the connection terminal while connected.
    view_requested: bool = false,
    /// The first `connected` spawns the first tab and the scratchpad; every
    /// later one respawns what the lost connection ended.
    ever_connected: bool = false,
    /// Sessions to respawn in place after a reconnect, one at a time through
    /// the presentation's spawn slots. Each cwd is owned.
    respawn: std.ArrayList(RespawnItem) = .empty,
    /// The remote host's own name, learned with one exec once connected; the
    /// OSC 7 host remote shells report (`term.Terminal.setWorkingDirectoryHost`).
    remote_host: [remote.max_host_bytes]u8 = undefined,
    remote_host_len: usize = 0,
    host_probe: ?*HostProbe = null,
    /// The connection view's header, `ssh <destination> ─ <state>`.
    header_storage: [palette_label_capacity]u8 = undefined,
    /// The header as painted, cut short of the row's control.
    header_paint_storage: [palette_label_capacity + 3]u8 = undefined,
    /// Restored from the state file and not yet asked to connect (TASK-65):
    /// the view says so, and Enter or `reconnect` starts the first master,
    /// so no credential prompt appears before the person asks for one.
    saved: bool = false,

    fn remoteHost(self: *const RemotePresentation) ?[]const u8 {
        if (self.remote_host_len == 0) return null;
        return self.remote_host[0..self.remote_host_len];
    }

    /// Whether new remote sessions may start now: connected, and the host
    /// probe that names OSC 7's host has answered.
    fn ready(self: *const RemotePresentation) bool {
        return self.state == .connected and self.host_probe == null;
    }
};

/// One session to start again after a reconnect.
const RespawnItem = struct {
    id: session.SessionId,
    /// The remote cwd it last reported, owned, or empty for the remote home.
    cwd: []u8,
    scratchpad: bool,
};

/// Asks the remote host its name (`uname -n`) over an exec channel, once per
/// connection, on a worker: the name OSC 7 reports from remote shells carry.
///
/// Ownership: the main thread creates, polls and destroys it; the worker
/// writes `name` and then publishes `state` with a release store.
const HostProbe = struct {
    allocator: Allocator,
    io: Io,
    context: workspace.ExecutionContext.Ref,
    state: std.atomic.Value(u32) = .init(0),
    thread: ?std.Thread = null,
    name: [remote.max_host_bytes]u8 = undefined,
    name_len: usize = 0,

    fn start(allocator: Allocator, io: Io, context: workspace.ExecutionContext.Ref) !*HostProbe {
        const self = try allocator.create(HostProbe);
        errdefer allocator.destroy(self);
        self.* = .{ .allocator = allocator, .io = io, .context = context };
        self.thread = try std.Thread.spawn(.{}, work, .{self});
        return self;
    }

    fn finished(self: *const HostProbe) bool {
        return self.state.load(.acquire) != 0;
    }

    fn work(self: *HostProbe) void {
        defer self.state.store(1, .release);
        var result = self.context.run(self.allocator, self.io, .{
            .argv = &.{ "uname", "-n" },
            .cwd = "",
            .max_output = 256,
            .timeout_ms = 15_000,
        }) catch |err| {
            log.debug("the remote host name probe failed: {s}", .{@errorName(err)});
            return;
        };
        defer result.deinit(self.allocator);
        if (!result.succeeded()) return;
        const name = std.mem.trim(u8, result.stdout, " \t\r\n");
        if (!remote.concreteAlias(name)) return;
        @memcpy(self.name[0..name.len], name);
        self.name_len = name.len;
    }

    /// Join the worker and release the probe.
    fn destroy(self: *HostProbe) void {
        if (self.thread) |thread| thread.join();
        self.allocator.destroy(self);
    }
};

const WorkspaceEventContext = struct {
    app: *App,
    key: workspace.WorkspaceKey,
};

const PendingPaneClose = struct {
    tab_id: workspace.TabId,
    pane_id: workspace.PaneId,
};

const WorkspaceSemanticTarget = struct {
    key: workspace.WorkspaceKey,
    ordinal: u32,
};

const pane_semantic_capacity = workspace_semantic_capacity;

const UrlOpener = struct {
    context: ?*anyopaque = null,
    open_fn: *const fn (?*anyopaque, Allocator, []const u8) anyerror!void = openSystemUrl,

    fn open(self: UrlOpener, allocator: Allocator, url: []const u8) !void {
        try self.open_fn(self.context, allocator, url);
    }
};

fn openSystemUrl(_: ?*anyopaque, allocator: Allocator, url: []const u8) !void {
    try platform.openUrl(allocator, url);
}

const TerminalLinkTarget = struct {
    id: []const u8,
    kind: TerminalLinkTargetKind,
    /// The exact URL for `.url`, or the visible path spelling for `.file`.
    /// Borrows `App.terminal_link_text` until the next UI composition.
    target: []const u8,
    line: ?u32 = null,
    column: ?u32 = null,
    session_id: session.SessionId,
};

/// Sees the exact editor spawn a file reference produced before its worker
/// starts. Deterministic checks record argv and cwd here; the real spawn
/// through the workspace `ExecutionContext` proceeds regardless.
const EditorSpawnObserver = struct {
    context: ?*anyopaque = null,
    observe_fn: ?*const fn (?*anyopaque, []const []const u8, []const u8) void = null,

    fn observe(self: EditorSpawnObserver, argv: []const []const u8, cwd: []const u8) void {
        const observe_fn = self.observe_fn orelse return;
        observe_fn(self.context, argv, cwd);
    }
};

/// How many app-bound keys may be held at once.
const binding_key_capacity: usize = 64;

/// What a configured family that is not installed reports. The bundled face
/// stands in, which the font manager already guarantees.
const missing_family_message = "font.family: not installed; using the bundled face";

/// The settings file a run loads: the explicit path a check supplies, none for
/// every other built-in check (a user's settings must not change what a check
/// measures), and otherwise the platform location from the environment.
fn configPathFor(options: Options, env: EnvSource, buffer: []u8) ?[]const u8 {
    if (options.run.config_path) |path| return path;
    if (usesDeterministicScratchpad(options)) return null;
    return config.defaultPath(buffer, builtin.os.tag, .{
        .xdg_config_home = env.get("XDG_CONFIG_HOME"),
        .home = env.get("HOME"),
        .appdata = env.get("APPDATA"),
    });
}

/// `font.family` through its layers: `--font` beats the file, which beats the
/// bundled face (the empty family).
fn configuredFamily(session_layer: ?[]const u8, file: ?[]const u8) []const u8 {
    return config.Layer.resolve([]const u8, "", file, session_layer);
}

/// What a `font.fallbacks` family that is not installed reports. The family is
/// skipped and the rest of the chain still applies.
const missing_fallback_message = "font.fallbacks: a family is not installed; it is skipped";

/// The font settings that decide which face is built, as borrowed values.
/// `FontSettings` owns a copy; `fontValuesFrom` borrows a parsed file.
const FontValues = struct {
    /// The primary family after the `--font` session layer; empty is bundled.
    family: []const u8 = "",
    bold: []const u8 = "",
    italic: []const u8 = "",
    bold_italic: []const u8 = "",
    fallbacks: []const []const u8 = &.{},
    points: f32 = config.default_font_points,
    ligatures: bool = true,
    builtin_symbols: bool = true,

    /// Identifies the face these values build at `scale`: everything but
    /// ligatures, which `font.Manager.setLigatures` toggles without a rebuild.
    fn faceKey(self: FontValues, scale: f32) u64 {
        var hasher = std.hash.Wyhash.init(0);
        for ([_][]const u8{ self.family, self.bold, self.italic, self.bold_italic }) |text| {
            hasher.update(text);
            hasher.update(&.{0});
        }
        for (self.fallbacks) |family| {
            hasher.update(family);
            hasher.update(&.{1});
        }
        hasher.update(std.mem.asBytes(&self.points));
        hasher.update(std.mem.asBytes(&scale));
        hasher.update(&.{@intFromBool(self.builtin_symbols)});
        return hasher.final();
    }

    /// Whether `self` and `other` build the same face at any one scale.
    fn sameFace(self: FontValues, other: FontValues) bool {
        return self.faceKey(1) == other.faceKey(1);
    }

    /// The manager request for these values with `family` as the primary
    /// (the committed family, or the picker's preview). Borrows every string.
    fn request(self: FontValues, family: []const u8, size: font.Size, home_dir: ?[]const u8) font.Request {
        return .{
            .family = family,
            .bold_family = self.bold,
            .italic_family = self.italic,
            .bold_italic_family = self.bold_italic,
            .size = size,
            .home_dir = home_dir,
            .atlas_width_px = atlasSizeFor(size.scale).width_px,
            .atlas_height_px = atlasSizeFor(size.scale).height_px,
            .fallbacks = self.fallbacks,
            .ligatures = self.ligatures,
            .builtin_symbols = self.builtin_symbols,
        };
    }
};

/// How large small UI text (TASK-76's branch rows) is relative to the
/// configured face. At 0.6 of the point size the glyphs' x-height reads as
/// about half the tab name's, which is what the sidebar design asks for.
const small_text_ratio: f32 = 0.6;

/// The small face's coverage atlas. A sidebar's branch names need few
/// glyphs, so it is a quarter of the main atlas.
const small_atlas: render.AtlasSize = .{ .width_px = 512, .height_px = 512 };

/// The secondary small face's request: the same family, styles and fallback
/// chain as `primary`, at `small_text_ratio` of its size, with smaller atlases.
/// Null when the scaled size falls below `font.Size.min_points`, in which
/// case small text draws at the normal size.
fn smallFontRequest(primary: font.Request) ?font.Request {
    var small = primary;
    small.size = font.Size.init(primary.size.points * small_text_ratio, primary.size.scale) catch return null;
    small.atlas_width_px = small_atlas.width_px;
    small.atlas_height_px = small_atlas.height_px;
    small.color_atlas_width_px = 128;
    small.color_atlas_height_px = 128;
    return small;
}

test "the small face request scales the size and shrinks the atlases" {
    const primary: font.Request = .{ .family = "Mono", .size = try font.Size.init(10, 1.25) };
    const small = smallFontRequest(primary).?;
    try std.testing.expectEqualStrings("Mono", small.family);
    try std.testing.expectEqual(@as(f32, 6), small.size.points);
    try std.testing.expectEqual(@as(f32, 1.25), small.size.scale);
    try std.testing.expectEqual(small_atlas.width_px, small.atlas_width_px);
    try std.testing.expect(smallFontRequest(.{ .size = try font.Size.init(1.2, 1) }) == null);
}

/// The font values a parsed settings file and the `--font` session layer
/// resolve to. Borrows from both.
fn fontValuesFrom(session_family: ?[]const u8, settings: config.Settings) FontValues {
    return .{
        .family = configuredFamily(session_family, settings.font_family),
        .bold = settings.font_bold,
        .italic = settings.font_italic,
        .bold_italic = settings.font_bold_italic,
        .fallbacks = settings.font_fallbacks,
        .points = settings.font_size,
        .ligatures = settings.font_ligatures,
        .builtin_symbols = settings.font_nerd_symbols,
    };
}

/// An owned copy of `FontValues`, so the values outlive the config they came
/// from. `App` owns the committed one and each font `Load` owns its own,
/// because its worker reads it while the main thread may replace the app's.
const FontSettings = struct {
    arena: std.heap.ArenaAllocator,
    values: FontValues,

    /// Deep-copy `source`; the caller owns the result and calls `deinit`.
    fn init(gpa: Allocator, source: FontValues) Allocator.Error!FontSettings {
        var arena = std.heap.ArenaAllocator.init(gpa);
        errdefer arena.deinit();
        const allocator = arena.allocator();
        var values = source;
        values.family = try allocator.dupe(u8, source.family);
        values.bold = try allocator.dupe(u8, source.bold);
        values.italic = try allocator.dupe(u8, source.italic);
        values.bold_italic = try allocator.dupe(u8, source.bold_italic);
        const fallbacks = try allocator.alloc([]const u8, source.fallbacks.len);
        for (fallbacks, source.fallbacks) |*slot, family| slot.* = try allocator.dupe(u8, family);
        values.fallbacks = fallbacks;
        return .{ .arena = arena, .values = values };
    }

    fn deinit(self: *FontSettings) void {
        self.arena.deinit();
        self.* = undefined;
    }
};

/// The most families the font picker lists, the bundled entry included.
const font_choice_capacity: usize = 256;
/// The longest family name the picker lists, in bytes.
const font_family_capacity: usize = 96;
/// The picker's value for the bundled face, which `font.family` spells as an
/// empty string. Parenthesised so no installed family can share it.
const bundled_font_value = "(bundled)";
const bundled_font_label = "JetBrains Mono (bundled)";

const font_pick_action = "font.pick";
const font_size_increase_action = "font.size.increase";
const font_size_decrease_action = "font.size.decrease";
const font_size_reset_action = "font.size.reset";
const font_ligatures_toggle_action = "font.ligatures.toggle";
const font_symbols_toggle_action = "font.symbols.toggle";
const font_fallbacks_action = "font.fallbacks";

/// Whether an installed family name can be listed and written back as a
/// `font.family` value that the settings parser reads back unchanged.
fn usableFontFamilyName(name: []const u8) bool {
    if (name.len == 0 or name.len > font_family_capacity) return false;
    if (name[0] == ' ' or name[name.len - 1] == ' ') return false;
    if (std.mem.eql(u8, name, bundled_font_value)) return false;
    if (!std.unicode.utf8ValidateSlice(name)) return false;
    for (name) |byte| {
        if (byte < 0x20 or byte == 0x7f or byte == '"') return false;
    }
    return true;
}

/// The families `font.pick` offers: the bundled face and every installed
/// monospace family from the font catalog, sorted, with the committed family
/// first so opening the picker previews what is already drawn.
///
/// Heap-allocated once by `App.init` and owned by `App`; the `font.pick`
/// registry entry borrows `choices`, and `App.setFontChoices` re-points it
/// after every rebuild. Rebuilt only while the palette is closed, because an
/// open picker's rows are indices into it. Main thread only.
const FontChoices = struct {
    names: [font_choice_capacity][font_family_capacity]u8 = undefined,
    choices: [font_choice_capacity]inputmod.PaletteChoice = undefined,
    count: usize = 0,

    fn slice(self: *const FontChoices) []const inputmod.PaletteChoice {
        return self.choices[0..self.count];
    }

    /// Relist from `catalog` with `current` (a `font.family` value) first.
    /// Never fails: without memory to list the catalog, only the bundled face
    /// is offered.
    fn rebuild(self: *FontChoices, gpa: Allocator, catalog: *const font.Catalog, current: []const u8) void {
        self.choices[0] = .{ .label = bundled_font_label, .value = bundled_font_value };
        self.count = 1;
        const families = catalog.monospaceFamilies(gpa, font_choice_capacity - 1) catch |err| {
            font.log.warn("the installed font families could not be listed: {s}", .{@errorName(err)});
            return;
        };
        defer gpa.free(families);
        for (families) |family| {
            if (!usableFontFamilyName(family)) continue;
            const stored = self.names[self.count][0..family.len];
            @memcpy(stored, family);
            self.choices[self.count] = .{ .label = stored, .value = stored };
            self.count += 1;
        }
        const first = self.find(current) orelse return;
        const chosen = self.choices[first];
        var cursor = first;
        while (cursor > 0) : (cursor -= 1) self.choices[cursor] = self.choices[cursor - 1];
        self.choices[0] = chosen;
    }

    /// The choice for a `font.family` value: the bundled entry for an empty
    /// one, else the listed family whose name matches ignoring case.
    fn find(self: *const FontChoices, family: []const u8) ?usize {
        for (self.slice(), 0..) |choice, index| {
            const listed = familyForChoice(choice.value);
            if (family.len == 0 and listed.len == 0) return index;
            if (family.len != 0 and std.ascii.eqlIgnoreCase(listed, family)) return index;
        }
        return null;
    }
};

/// Whether any configured fallback family is not installed, by the catalog the
/// drawn face was resolved from.
fn missingFallback(fonts: *const font.Manager, fallbacks: []const []const u8) bool {
    for (fallbacks) |family| {
        if (fonts.catalog.findFamily(family) == null) return true;
    }
    return false;
}

/// The `font.family` value a picker choice stands for.
fn familyForChoice(value: []const u8) []const u8 {
    return if (std.mem.eql(u8, value, bundled_font_value)) "" else value;
}

fn chordErrorMessage(err: inputmod.ChordError) []const u8 {
    return switch (err) {
        error.EmptyChord => "keybind: empty chord",
        error.UnknownModifier => "keybind: unknown modifier (use ctrl, shift, alt or super)",
        error.DuplicateModifier => "keybind: repeated modifier",
        error.MissingKey => "keybind: chord has no key (spell + as plus)",
        error.UnknownKey => "keybind: unknown key",
    };
}

/// Build the binding table for `loaded`: the profile's shipped defaults plus
/// the file's keybind lines in order. Each line is checked here, where the
/// registry is known; a rejected line is reported on `loaded` with its line
/// number, and its chord keeps what `previous` bound it to (at startup, the
/// default). The returned table owns everything it holds.
fn buildConfiguredBindings(
    allocator: Allocator,
    registry: *const inputmod.Registry,
    profile: inputmod.PlatformProfile,
    loaded: *config.Config,
    previous: ?*const inputmod.BindingTable,
) !inputmod.BindingTable {
    const defaults = inputmod.defaultBindings(profile);
    var overrides: std.ArrayList(inputmod.BindingOverride) = .empty;
    defer overrides.deinit(allocator);
    // One argument per configured line at most; reserved up front so the
    // slices overrides borrow never move.
    var arguments: std.ArrayList(inputmod.Argument) = .empty;
    defer arguments.deinit(allocator);
    try arguments.ensureTotalCapacity(allocator, loaded.keybinds.items.len);

    // TASK-56's list chord is the app's own default until `input` ships it
    // with the others; it goes first so a file line can still rebind or unbind
    // it.
    try overrides.append(allocator, .{ .chord = notificationsChord(profile), .action = notifications_open_action });
    try overrides.append(allocator, .{ .chord = agentViewChord(profile), .action = agent_view_action });
    try overrides.append(allocator, .{ .chord = agentsManagerChord(profile), .action = agents_open_action });
    try overrides.append(allocator, .{ .chord = backlogChord(profile), .action = backlog_open_action });
    for (loaded.keybinds.items) |keybind| {
        const chord = inputmod.parseChord(keybind.chord) catch |err| {
            loaded.addDiagnostic(keybind.line, "{s}", .{chordErrorMessage(err)});
            continue;
        };
        const action = keybind.action orelse {
            try overrides.append(allocator, .{ .chord = chord, .action = null });
            continue;
        };
        const argument = inputmod.keybindArgument(registry, defaults, action, keybind.argument) catch |err| {
            switch (err) {
                error.UnknownAction => loaded.addDiagnostic(keybind.line, "keybind: unknown action", .{}),
                error.NotBindable => loaded.addDiagnostic(keybind.line, "keybind: {s} cannot be bound to a key", .{action}),
                error.MissingArgument => loaded.addDiagnostic(keybind.line, "keybind: {s} needs an argument", .{action}),
                error.UnexpectedArgument => loaded.addDiagnostic(keybind.line, "keybind: {s} takes no argument", .{action}),
                error.InvalidArgument => loaded.addDiagnostic(keybind.line, "keybind: invalid argument for {s}", .{action}),
            }
            if (previous) |table| {
                var kept = false;
                for (table.bindings) |binding| {
                    if (!inputmod.chordEql(binding.chord, chord)) continue;
                    try overrides.append(allocator, .{ .chord = chord, .action = binding.action, .arguments = binding.arguments });
                    kept = true;
                }
                if (!kept) try overrides.append(allocator, .{ .chord = chord, .action = null });
            }
            continue;
        };
        var argument_slice: []const inputmod.Argument = &.{};
        if (argument) |value| {
            arguments.appendAssumeCapacity(value);
            argument_slice = arguments.items[arguments.items.len - 1 ..];
        }
        try overrides.append(allocator, .{ .chord = chord, .action = action, .arguments = argument_slice });
    }
    return inputmod.buildBindings(allocator, defaults, overrides.items);
}

/// Where this run keeps its agents' private sinks (TASK-56): beside the
/// check's own files for `--agent-test`, otherwise a per-run directory under
/// `$XDG_STATE_HOME/conduit/agents` (or `~/.local/state/...`), created 0700 on
/// first use and removed when the run ends. Null when there is no home.
fn agentSinkRoot(io: Io, env: EnvSource, options: Options, buffer: []u8) ?[]const u8 {
    if (options.run.agent_test_dir) |dir| return std.fmt.bufPrint(buffer, "{s}/agents", .{dir}) catch null;
    var id_buffer: [path_capacity]u8 = undefined;
    const id = generateRunId(io, &id_buffer) catch return null;
    if (env.get("XDG_STATE_HOME")) |state| {
        if (state.len != 0 and state[0] == '/') return std.fmt.bufPrint(buffer, "{s}/conduit/agents/{s}", .{ state, id }) catch null;
    }
    const home = env.get("HOME") orelse return null;
    if (home.len == 0 or home[0] != '/') return null;
    return std.fmt.bufPrint(buffer, "{s}/.local/state/conduit/agents/{s}", .{ home, id }) catch null;
}

/// Ctrl+Shift+N on Linux and Windows, Cmd+Shift+N on macOS: the notification
/// list (TASK-56). Free in both shipped default tables.
/// TASK-57's view toggle, an app default beside the list chord.
/// TASK-63's backlog view: Command+Shift+K on macOS, Ctrl+Shift+K elsewhere
/// (`K` for kanban: Ctrl+Shift+B is the sidebar toggle).
fn backlogChord(profile: inputmod.PlatformProfile) inputmod.Chord {
    return switch (profile) {
        .macos => .{ .key = .{ .character = 'k' }, .modifiers = .{ .shift = true, .super = true } },
        .linux_windows => .{ .key = .{ .character = 'k' }, .modifiers = .{ .ctrl = true, .shift = true } },
    };
}

/// TASK-58's agent manager: Command+Shift+G on macOS, Ctrl+Shift+G elsewhere.
fn agentsManagerChord(profile: inputmod.PlatformProfile) inputmod.Chord {
    return switch (profile) {
        .macos => .{ .key = .{ .character = 'g' }, .modifiers = .{ .shift = true, .super = true } },
        .linux_windows => .{ .key = .{ .character = 'g' }, .modifiers = .{ .ctrl = true, .shift = true } },
    };
}

fn agentViewChord(profile: inputmod.PlatformProfile) inputmod.Chord {
    return switch (profile) {
        .macos => .{ .key = .{ .character = 'a' }, .modifiers = .{ .shift = true, .super = true } },
        .linux_windows => .{ .key = .{ .character = 'a' }, .modifiers = .{ .ctrl = true, .shift = true } },
    };
}

fn notificationsChord(profile: inputmod.PlatformProfile) inputmod.Chord {
    return switch (profile) {
        .macos => .{ .key = .{ .character = 'n' }, .modifiers = .{ .shift = true, .super = true } },
        .linux_windows => .{ .key = .{ .character = 'n' }, .modifiers = .{ .ctrl = true, .shift = true } },
    };
}

/// `macos.option_as_alt` as the platform's Option-as-Alt choice (TASK-48).
fn platformOptionAsAlt(value: config.OptionAsAlt) platform.OptionAsAlt {
    return switch (value) {
        .false => .none,
        .true => .both,
        .left => .left,
        .right => .right,
    };
}

/// Report every diagnostic of a load at warn level as `<path>:<line>: <message>`.
/// Messages name the key, never the user's value.
fn logConfigDiagnostics(path: []const u8, loaded: *const config.Config) void {
    for (loaded.diagnostics.items) |diagnostic| {
        if (diagnostic.line == 0) {
            config.log.warn("{s}: {s}", .{ path, diagnostic.message });
        } else {
            config.log.warn("{s}:{d}: {s}", .{ path, diagnostic.line, diagnostic.message });
        }
    }
    if (loaded.dropped_diagnostics != 0) {
        config.log.warn("{s}: {d} more problem(s) not shown", .{ path, loaded.dropped_diagnostics });
    }
}

/// Create the settings file with the commented defaults document when it does
/// not exist yet. An existing file is never touched.
fn ensureConfigFile(io: Io, path: []const u8) !void {
    if (config.directoryOf(path)) |dir| try Dir.cwd().createDirPath(io, dir);
    Dir.cwd().writeFile(io, .{
        .sub_path = path,
        .data = config.defaults_document,
        .flags = .{ .exclusive = true },
    }) catch |err| switch (err) {
        error.PathAlreadyExists => return,
        else => return err,
    };
}

// ---------------------------------------------------------------------------
// Themes (TASK-38)
// ---------------------------------------------------------------------------

/// How many files of the user theme directory the catalog lists. Together
/// with the bundled schemes this must fit the palette's per-command choice
/// rows (`palette_action_capacity`).
const max_user_themes: usize = 32;
/// The longest user theme file name listed, in bytes.
const theme_name_capacity: usize = 64;
/// Every theme one run can offer.
const theme_choice_capacity: usize = theme.bundled.len + max_user_themes;

comptime {
    std.debug.assert(theme_choice_capacity <= palette_action_capacity);
}

const theme_pick_action = "theme.pick";

/// Whether a user theme file's name can be listed and written back as a
/// `theme = <name>` value: one line of printable UTF-8 that the settings
/// parser reads back unchanged and that cannot be mistaken for `auto:`.
fn usableThemeFileName(name: []const u8) bool {
    if (name.len == 0 or name.len > theme_name_capacity) return false;
    if (name[0] == '.' or name[0] == ' ' or name[name.len - 1] == ' ') return false;
    if (!std.unicode.utf8ValidateSlice(name)) return false;
    for (name) |byte| {
        if (byte < 0x20 or byte == 0x7f or byte == '"' or byte == ',' or byte == '/' or byte == '\\') return false;
    }
    if (name.len >= 5 and std.ascii.eqlIgnoreCase(name[0..5], "auto:")) return false;
    return true;
}

/// The themes a run can choose from: every bundled scheme that no user file
/// shadows, and every usable Ghostty-format file in the user theme directory,
/// already parsed and derived so previewing one costs no IO.
///
/// Heap-allocated once by `App.init` and owned by `App`; the `theme.pick`
/// registry entry borrows `choices`, and `App.setThemeChoices` re-points it
/// after every rebuild. Main thread only.
const ThemeCatalog = struct {
    const Entry = struct {
        /// Borrowed from `theme.bundled` or `user_names`.
        label: []const u8,
        /// What `theme = <value>` names: a bundled id or the file name.
        value: []const u8,
        scheme: theme.Scheme,
        palette: theme.Palette,
        user: bool,
        /// The first problem in a user file, or null.
        problem: ?theme.Diagnostic = null,
    };

    entries: [theme_choice_capacity]Entry = undefined,
    choices: [theme_choice_capacity]inputmod.PaletteChoice = undefined,
    count: usize = 0,
    user_names: [max_user_themes][theme_name_capacity]u8 = undefined,

    fn entriesSlice(self: *const ThemeCatalog) []const Entry {
        return self.entries[0..self.count];
    }

    fn choiceSlice(self: *const ThemeCatalog) []const inputmod.PaletteChoice {
        return self.choices[0..self.count];
    }

    /// Re-read the user directory (null: none) and relist every theme, sorted
    /// by label with `active` (a name, matched like the setting) first.
    /// Never fails: an unreadable directory or file costs only that entry.
    fn rebuild(self: *ThemeCatalog, io: Io, gpa: std.mem.Allocator, directory: ?[]const u8, active: []const u8) void {
        self.count = 0;
        if (directory) |path| self.loadUserThemes(io, gpa, path) catch |err| {
            theme.log.warn("the user theme directory could not be listed: {s}", .{@errorName(err)});
        };
        const user_count = self.count;
        bundled: for (theme.bundled) |*entry| {
            for (self.entries[0..user_count]) |user| {
                if (theme.sameName(user.value, entry.id) or theme.sameName(user.value, entry.label)) continue :bundled;
            }
            self.entries[self.count] = .{
                .label = entry.label,
                .value = entry.id,
                .scheme = entry.scheme,
                .palette = theme.derive(entry.scheme),
                .user = false,
            };
            self.count += 1;
        }
        self.order(active);
    }

    fn loadUserThemes(self: *ThemeCatalog, io: Io, gpa: std.mem.Allocator, path: []const u8) !void {
        var dir = Dir.cwd().openDir(io, path, .{ .iterate = true }) catch |err| switch (err) {
            error.FileNotFound => return,
            else => return err,
        };
        defer dir.close(io);

        // Collect, sort and de-duplicate first so which files are listed does
        // not depend on the directory's iteration order.
        var names: std.ArrayList([]u8) = .empty;
        defer {
            for (names.items) |name| gpa.free(name);
            names.deinit(gpa);
        }
        var iterator = dir.iterate();
        while (try iterator.next(io)) |entry| {
            if (entry.kind != .file and entry.kind != .sym_link) continue;
            if (!usableThemeFileName(entry.name)) {
                theme.log.info("a file in the theme directory was skipped: its name cannot be a theme name", .{});
                continue;
            }
            if (names.items.len >= 1024) break;
            const owned = try gpa.dupe(u8, entry.name);
            errdefer gpa.free(owned);
            try names.append(gpa, owned);
        }
        std.mem.sort([]u8, names.items, {}, struct {
            fn lessThan(_: void, a: []u8, b: []u8) bool {
                return std.mem.order(u8, a, b) == .lt;
            }
        }.lessThan);

        var listed: usize = 0;
        names: for (names.items) |name| {
            for (self.entries[0..listed]) |previous| {
                if (theme.sameName(previous.value, name)) continue :names;
            }
            if (listed == max_user_themes) {
                theme.log.warn("more than {d} user themes; the rest are not listed", .{max_user_themes});
                break;
            }
            const stored = self.user_names[listed][0..name.len];
            @memcpy(stored, name);
            var parsed: theme.Parsed = .{ .scheme = theme.conduit_dark };
            const read_problem: ?[]const u8 = if (dir.readFileAlloc(io, name, gpa, .limited(theme.max_file_bytes + 1))) |bytes| read: {
                defer gpa.free(bytes);
                parsed = theme.parseGhostty(bytes);
                break :read null;
            } else |err| switch (err) {
                error.OutOfMemory => return error.OutOfMemory,
                error.StreamTooLong => "file is larger than 64 KiB",
                else => "file could not be read",
            };
            var problem: ?theme.Diagnostic = if (read_problem) |message| .{ .line = 0, .message = message } else null;
            if (problem == null and parsed.diagnostics().len != 0) problem = parsed.diagnostics()[0];
            self.entries[listed] = .{
                .label = stored,
                .value = stored,
                .scheme = parsed.scheme,
                .palette = theme.derive(parsed.scheme),
                .user = true,
                .problem = problem,
            };
            listed += 1;
            self.count = listed;
        }
    }

    /// Sort by label, case-insensitively, then move `active` to the front.
    fn order(self: *ThemeCatalog, active: []const u8) void {
        std.mem.sort(Entry, self.entries[0..self.count], {}, struct {
            fn lessThan(_: void, a: Entry, b: Entry) bool {
                return switch (std.ascii.orderIgnoreCase(a.label, b.label)) {
                    .lt => true,
                    .gt => false,
                    .eq => std.mem.order(u8, a.label, b.label) == .lt,
                };
            }
        }.lessThan);
        if (self.find(active)) |index| {
            const chosen = self.entries[index];
            var cursor = index;
            while (cursor > 0) : (cursor -= 1) self.entries[cursor] = self.entries[cursor - 1];
            self.entries[0] = chosen;
        }
        for (self.entries[0..self.count], 0..) |entry, index| {
            self.choices[index] = .{ .label = entry.label, .value = entry.value };
        }
    }

    /// The entry `name` refers to: a user file first, then a bundled id or
    /// label, compared the way `theme.sameName` does.
    fn find(self: *const ThemeCatalog, name: []const u8) ?usize {
        for (self.entriesSlice(), 0..) |entry, index| {
            if (entry.user and theme.sameName(entry.value, name)) return index;
        }
        for (self.entriesSlice(), 0..) |entry, index| {
            if (!entry.user and (theme.sameName(entry.value, name) or theme.sameName(entry.label, name))) return index;
        }
        return null;
    }
};

/// The built-in v0.1 editor for file references (decision-5) and `config.open`. The
/// settings file has no editor key yet, so the "configured editor command" is this default. It is
/// always spawned as shell-free argv `vi +<line> -- <path>`; a detected column
/// is kept for identity but never passed.
const file_reference_editor = "vi";
/// A tab label is the referenced file name, cut on a codepoint boundary.
const file_reference_label_max_bytes: usize = 64;
/// Longest resolved path handed to the editor. The workspace may be remote,
/// so this bounds hostile terminal text rather than mirroring a local limit.
const file_reference_path_max_bytes: usize = 4096;

const FileReferenceArgvError = error{ UnsafePath, PathTooLong, OutOfMemory };

/// Whether a detected path spelling stands on its own rather than relative to
/// the session cwd. Nothing here touches the filesystem.
fn fileReferenceIsAbsolute(path: []const u8) bool {
    if (path.len == 0) return false;
    if (path[0] == '/' or path[0] == '\\') return true;
    return path.len >= 2 and path[1] == ':' and std.ascii.isAlphabetic(path[0]);
}

/// Argv text must be non-empty, valid UTF-8 and free of C0/C1 controls. The
/// detector already rejects these, but the spawn boundary re-checks them
/// because that is where terminal-derived text becomes a process argument.
fn fileReferenceTextIsSafe(text: []const u8) bool {
    if (text.len == 0) return false;
    const view = std.unicode.Utf8View.init(text) catch return false;
    var iterator = view.iterator();
    while (iterator.nextCodepoint()) |codepoint| {
        if (codepoint < 0x20 or (codepoint >= 0x7f and codepoint < 0xa0) or
            codepoint == 0x2028 or codepoint == 0x2029) return false;
    }
    return true;
}

/// Build the owned argv `vi +<line> -- <path>` (or `vi -- <path>`) for one
/// detected file reference. A relative spelling is joined to `cwd` after
/// dropping leading `./` segments; nothing is canonicalized, stat'ed or read.
/// Ownership of the returned entries and slice transfers to the caller, who
/// releases them with `freeEntries`.
fn buildFileReferenceArgv(
    allocator: Allocator,
    path: []const u8,
    line: ?u32,
    cwd: []const u8,
) FileReferenceArgvError![][]const u8 {
    if (!fileReferenceTextIsSafe(path)) return error.UnsafePath;
    const absolute = fileReferenceIsAbsolute(path);
    var spelled = path;
    if (!absolute) {
        if (!fileReferenceTextIsSafe(cwd)) return error.UnsafePath;
        while (std.mem.startsWith(u8, spelled, "./")) spelled = spelled[2..];
        if (spelled.len == 0) return error.UnsafePath;
    }
    const separator: []const u8 = if (absolute or cwd[cwd.len - 1] == '/') "" else "/";
    const resolved_len = if (absolute) spelled.len else cwd.len + separator.len + spelled.len;
    if (resolved_len > file_reference_path_max_bytes) return error.PathTooLong;

    const count: usize = if (line != null) 4 else 3;
    const argv = try allocator.alloc([]const u8, count);
    var filled: usize = 0;
    errdefer {
        for (argv[0..filled]) |entry| allocator.free(entry);
        allocator.free(argv);
    }
    argv[filled] = try allocator.dupe(u8, file_reference_editor);
    filled += 1;
    if (line) |value| {
        argv[filled] = try std.fmt.allocPrint(allocator, "+{d}", .{value});
        filled += 1;
    }
    argv[filled] = try allocator.dupe(u8, "--");
    filled += 1;
    argv[filled] = if (absolute)
        try allocator.dupe(u8, spelled)
    else
        try std.fmt.allocPrint(allocator, "{s}{s}{s}", .{ cwd, separator, spelled });
    filled += 1;
    return argv;
}

/// The tab label for a file reference: its final path component, bounded on a
/// codepoint boundary. Borrows `path`.
/// `vi -- <path>`, or `vi -R -- <path>` to view a file the harness owns
/// (TASK-59). Shell-free like a file reference's argv (decision-5); the
/// path comes from discovery, never from instruction text. Caller owns.
fn buildInstructionEditorArgv(allocator: Allocator, path: []const u8, read_only: bool) Allocator.Error![][]const u8 {
    const argv = try allocator.alloc([]const u8, if (read_only) 4 else 3);
    var filled: usize = 0;
    errdefer {
        for (argv[0..filled]) |entry| allocator.free(entry);
        allocator.free(argv);
    }
    const parts = [_][]const u8{ "vi", "-R", "--", path };
    for (parts) |part| {
        if (!read_only and std.mem.eql(u8, part, "-R")) continue;
        argv[filled] = try allocator.dupe(u8, part);
        filled += 1;
    }
    return argv;
}

fn fileReferenceLabel(path: []const u8) []const u8 {
    var name = path;
    if (std.mem.lastIndexOfAny(u8, path, "/\\")) |index| name = path[index + 1 ..];
    if (name.len == 0) name = path;
    if (name.len <= file_reference_label_max_bytes) return name;
    var end = file_reference_label_max_bytes;
    while (end > 0 and name[end] & 0xc0 == 0x80) : (end -= 1) {}
    return name[0..end];
}

const TerminalLinkTargetKind = enum(u8) {
    url = 1,
    file = 2,
};

const terminal_link_fingerprint_bytes = 16;

/// Produce a collision-resistant stable identity for an untrusted terminal
/// target. Zero encodes an absent source location because parsed line and
/// column values are one-based; fixed-width fields keep every input tuple
/// unambiguous without copying the target.
fn terminalLinkFingerprint(
    kind: TerminalLinkTargetKind,
    target: []const u8,
    line: ?u32,
    column: ?u32,
) [terminal_link_fingerprint_bytes]u8 {
    var hash = std.crypto.hash.sha2.Sha256.init(.{});
    hash.update("conduit-terminal-link-v1\x00");
    const kind_bytes = [1]u8{@intFromEnum(kind)};
    hash.update(&kind_bytes);
    var line_bytes: [4]u8 = undefined;
    std.mem.writeInt(u32, &line_bytes, line orelse 0, .big);
    hash.update(&line_bytes);
    var column_bytes: [4]u8 = undefined;
    std.mem.writeInt(u32, &column_bytes, column orelse 0, .big);
    hash.update(&column_bytes);
    hash.update(target);

    var digest: [std.crypto.hash.sha2.Sha256.digest_length]u8 = undefined;
    hash.final(&digest);
    var fingerprint: [terminal_link_fingerprint_bytes]u8 = undefined;
    @memcpy(fingerprint[0..], digest[0..fingerprint.len]);
    return fingerprint;
}

const TerminalLinkCellBounds = struct {
    col: u16,
    width: u16,
};

/// Everything one run of Conduit owns: the surface it draws into, the live
/// session behind that surface, and what should happen next.
///
/// Ownership: `init` allocates the App itself with `allocator`; its caller owns
/// the returned stable pointer and releases it with `destroy`. `allocator` is
/// otherwise borrowed from `main` and every allocation the app makes comes
/// from it. `readback`, `input` and `output` are the app's; `spec` owns the
/// strings children are started with; the app and its workspace presentation
/// records own worker jobs until they are collected. The window is borrowed
/// and destroyed after `destroy`, because a window outlives every frame and
/// dies before the process.
const App = struct {
    allocator: Allocator,
    io: Io,
    window: *platform.Window,
    surface: render.Surface,
    /// The size the surface is currently at, so a window state that implies the
    /// size already in use costs nothing.
    size: render.Size,
    /// The readback buffer, allocated once at the largest surface seen and
    /// reused by every capture.
    readback: []u8,
    /// What a full frame is cleared to, kept beside the surface because the
    /// capture report counts pixels of exactly this colour.
    background: render.Rgba,
    /// Set when what is on the window's framebuffer may not match the surface:
    /// a resize, a scale change and an expose all leave the two out of step.
    needs_present: bool,
    scheduler: Scheduler,
    /// Frame coalescing while child output is flowing; owned by the loop.
    pacer: FramePacer = .{},
    /// The face the grid is rasterised from. Owned.
    fonts: font.Manager,
    /// The secondary small face for `ui.TextStyle.small` (TASK-76), rebuilt
    /// with `fonts`; null when it could not be built.
    small_fonts: ?font.Manager = null,
    /// Git branch state per session, created by the first cwd or prompt
    /// event (TASK-76). See `GitTrack` for threads and refresh triggers.
    git_tracks: std.ArrayList(GitTrack) = .empty,
    /// Registry-owned workspace models and their parallel, heap-stable
    /// presentation records. Both collections use the same stable keys.
    workspace_registry: workspace.WorkspaceRegistry,
    workspace_presentations: std.ArrayList(*WorkspacePresentation),
    /// The overlay has its own renderer state because it spans the full canvas
    /// and is composited only after every visible pane.
    overlay_grid: render.Grid,
    pane_layouts: []workspace.PaneLayout,
    pane_layout_count: usize = 0,
    divider_layouts: []workspace.DividerLayout,
    divider_layout_count: usize = 0,
    workspace_semantic_storage: [sidebar_element_capacity][workspace_semantic_capacity]u8 = undefined,
    tab_semantic_storage: [sidebar_element_capacity][workspace_semantic_capacity]u8 = undefined,
    /// Stable ids of the TASK-76 branch rows, one slot per tab slot.
    tab_branch_semantic_storage: [sidebar_element_capacity][workspace_semantic_capacity]u8 = undefined,
    /// Frame-borrowed painted branch text, possibly ellipsized, per tab slot.
    tab_branch_label_storage: [sidebar_element_capacity][git.max_name_bytes + 3]u8 = undefined,
    tab_rename_semantic_storage: [workspace_semantic_capacity]u8 = undefined,
    /// Backs the sidebar `Palette  <chord>` hint label until the frame is drawn.
    sidebar_palette_label_storage: [128]u8 = undefined,
    pane_semantic_storage: [sidebar_element_capacity][pane_semantic_capacity]u8 = undefined,
    divider_semantic_storage: [sidebar_element_capacity][pane_semantic_capacity]u8 = undefined,
    divider_visual_storage: [sidebar_element_capacity][pane_semantic_capacity + 7]u8 = undefined,
    scratchpad_semantic_storage: [4][workspace_semantic_capacity]u8 = undefined,
    terminal_link_ids: [2][terminal_link_capacity][terminal_link_semantic_capacity]u8 = undefined,
    terminal_link_id_generation: usize = 0,
    terminal_link_targets: [terminal_link_capacity]TerminalLinkTarget = undefined,
    terminal_link_target_count: usize = 0,
    terminal_link_text: [terminal_link_frame_bytes]u8 = undefined,
    terminal_link_text_len: usize = 0,
    terminal_link_row: [terminal_link_row_bytes]u8 = undefined,
    terminal_link_ranges: [terminal_link_osc_capacity]link.Osc8Range = undefined,
    terminal_link_matches: [terminal_link_capacity]link.Match = undefined,
    terminal_link_modifier: bool = false,
    url_opener: UrlOpener = .{},
    editor_spawn_observer: EditorSpawnObserver = .{},
    /// What the child was started with.
    spec: ChildSpec,
    /// The scratchpad's independent interactive shell specification. It never
    /// contains a run's command or deterministic test peer.
    scratchpad_spec: ChildSpec,
    /// Bytes copied out of the child each frame.
    input: []u8,
    /// Answers the terminal owes the child.
    output: []u8,
    /// Bytes an input event produced for the child, waiting to go out with the
    /// terminal's own answers.
    ///
    /// A fixed value rather than a buffer: a key or a wheel report is a few
    /// dozen bytes at most, the count is fixed here so a frame allocates
    /// nothing, and `pumpChild` writes it from the same place it writes the
