            .handler = scratchpadHideAction,
        });
        try actions.register(.{
            .name = palette_open_action,
            .label = "Open command palette",
            .handler = paletteOpenAction,
            .palette = null,
        });
        try actions.register(.{
            .name = palette_activate_action,
            .label = "Activate palette selection",
            .handler = paletteActivateAction,
            .palette = null,
        });
        try actions.register(.{
            .name = terminal_open_link_action,
            .label = "Open terminal link",
            .handler = terminalOpenLinkAction,
            .palette = null,
        });
        try actions.register(.{
            .name = search_open_action,
            .label = "Open terminal search",
            .handler = searchOpenAction,
        });
        try actions.register(.{
            .name = search_close_action,
            .label = "Close terminal search",
            .handler = searchCloseAction,
            .palette = null,
        });
        try actions.register(.{
            .name = search_next_action,
            .label = "Search: Next match",
            .handler = searchNextAction,
        });
        try actions.register(.{
            .name = search_previous_action,
            .label = "Search: Previous match",
            .handler = searchPreviousAction,
        });
        try actions.register(.{
            .name = search_case_action,
            .label = "Search: Toggle case sensitivity",
            .handler = searchCaseAction,
        });
        try actions.register(.{
            .name = search_regex_action,
            .label = "Search: Toggle regex",
            .handler = searchRegexAction,
        });
        try actions.register(.{
            .name = search_activate_match_action,
            .label = "Activate search match",
            .handler = searchActivateMatchAction,
            .palette = null,
        });
        try actions.register(.{
            .name = terminal_context_menu_action,
            .label = "Open terminal context menu",
            .handler = terminalContextMenuAction,
        });
        try actions.register(.{
            .name = config_open_action,
            .label = "Open config file",
            .handler = configOpenAction,
        });
        try actions.register(.{
            .name = config_reload_action,
            .label = "Reload config",
            .handler = configReloadAction,
        });
        const theme_pick_index = actions.definitions().len;
        try actions.register(.{
            .name = theme_pick_action,
            .label = "Theme: choose",
            .handler = themePickAction,
            .palette = themePickCommand(theme_catalog),
        });
        const font_pick_index = actions.definitions().len;
        try actions.register(.{
            .name = font_pick_action,
            .label = "Font: Change Family",
            .handler = fontPickAction,
            .palette = fontPickCommand(font_choices),
        });
        try actions.register(.{
            .name = font_size_increase_action,
            .label = "Font: Increase Size",
            .handler = fontSizeIncreaseAction,
        });
        try actions.register(.{
            .name = font_size_decrease_action,
            .label = "Font: Decrease Size",
            .handler = fontSizeDecreaseAction,
        });
        try actions.register(.{
            .name = font_size_reset_action,
            .label = "Font: Reset Size",
            .handler = fontSizeResetAction,
        });
        try actions.register(.{
            .name = font_ligatures_toggle_action,
            .label = "Font: Toggle Ligatures",
            .handler = fontLigaturesToggleAction,
        });
        try actions.register(.{
            .name = font_symbols_toggle_action,
            .label = "Font: Toggle Built-in Symbols",
            .handler = fontSymbolsToggleAction,
        });
        try actions.register(.{
            .name = font_fallbacks_action,
            .label = "Font: Configure Fallbacks",
            .handler = fontFallbacksAction,
            .palette = .{ .argument = .{ .input = .{
                .name = "families",
                .prompt = "Fallback families, comma-separated (none clears)",
            } } },
        });
        try actions.register(.{
            .name = settings_open_action,
            .label = "Settings",
            .handler = settingsOpenAction,
        });
        try actions.register(.{
            .name = settings_activate_action,
            .label = "Activate settings row",
            .handler = settingsActivateAction,
            .palette = null,
        });
        // TASK-56. The three choice lists start empty and are filled from the
        // agent runtime (detected harnesses, live agents) while the palette
        // is closed, like the font and theme pickers.
        const agent_launch_index = actions.definitions().len;
        try actions.register(.{
            .name = agent_launch_action,
            .label = "Agent: launch",
            .handler = agentLaunchAction,
            .palette = agentChoiceCommand("harness", "Launch agent", &no_harness_choices),
        });
        const agent_prompt_index = actions.definitions().len;
        try actions.register(.{
            .name = agent_launch_prompt_action,
            .label = "Agent: launch with prompt",
            .handler = agentLaunchPromptAction,
            .palette = .{ .argument = .{ .input = .{
                .name = "prompt",
                .prompt = "Initial prompt (Enter for none)",
            } } },
        });
        const agent_stop_index = actions.definitions().len;
        try actions.register(.{
            .name = agent_stop_action,
            .label = "Agent: stop",
            .handler = agentStopAction,
            .palette = agentChoiceCommand("agent", "Stop agent", &no_agent_choices),
        });
        const agent_focus_index = actions.definitions().len;
        try actions.register(.{
            .name = agent_focus_action,
            .label = "Agent: focus",
            .handler = agentFocusAction,
            .palette = agentChoiceCommand("agent", "Focus agent", &no_agent_choices),
