        try actions.register(.{
            .name = remote_reconnect_action,
            .label = "Remote: reconnect",
            .handler = remoteReconnectAction,
        });
        try actions.register(.{
            .name = remote_disconnect_action,
            .label = "Remote: disconnect",
            .handler = remoteDisconnectAction,
        });
        try actions.register(.{
            .name = remote_show_connection_action,
            .label = "Remote: show connection",
            .handler = remoteShowConnectionAction,
        });
        // TASK-57: the structured view over an agent's terminal, and the two
        // semantic actions its controls dispatch.
        const agent_view_index = actions.definitions().len;
        try actions.register(.{
            .name = agent_view_action,
            .label = "Agent: toggle view",
            .handler = agentViewToggleAction,
        });
        try actions.register(.{
            .name = agent_view_answer_action,
            .label = "Answer agent permission",
            .handler = agentViewAnswerAction,
            .palette = null,
        });
        try actions.register(.{
            .name = agent_view_open_ref_action,
            .label = "Open agent file reference",
            .handler = agentViewOpenRefAction,
            .palette = null,
        });
        // TASK-58: the manager over every workspace's agents.
        try actions.register(.{
            .name = agents_open_action,
            .label = "Agents",
            .handler = agentsOpenAction,
        });
        try actions.register(.{
            .name = agents_activate_action,
            .label = "Activate agent manager element",
            .handler = agentsActivateAction,
            .palette = null,
        });
        // TASK-63: the workspace's backlog board, list and task detail.
        try actions.register(.{
            .name = backlog_open_action,
            .label = "Backlog",
            .handler = backlogOpenAction,
        });
        try actions.register(.{
            .name = backlog_activate_action,
            .label = "Activate backlog view element",
            .handler = backlogActivateAction,
            .palette = null,
        });
        // TASK-59: one agent's prompts and instruction files.
        try actions.register(.{
            .name = agent_prompts_action,
            .label = "Agent: prompts and instructions",
            .handler = agentPromptsAction,
        });
        try actions.register(.{
            .name = agent_prompts_activate_action,
            .label = "Activate prompts view element",
            .handler = agentPromptsActivateAction,
            .palette = null,
        });
        // TASK-46: the chosen profile's argv, environment and directory.
        const tab_profile_index = actions.definitions().len;
        try actions.register(.{
            .name = tab_new_profile_action,
            .label = "New tab with profile",
            .handler = tabNewProfileAction,
            .palette = .{ .argument = .{ .choices = .{
                .name = "profile",
                .prompt = "Shell profile",
                .values = profile_choices.slice(),
            } } },
        });
        const pane_profile_index = actions.definitions().len;
        try actions.register(.{
            .name = pane_split_profile_action,
            .label = "Split with profile",
            .handler = paneSplitProfileAction,
            .palette = .{ .argument = .{ .choices = .{
                .name = "profile",
                .prompt = "Shell profile",
                .values = profile_choices.slice(),
            } } },
        });
        if (options.run.ui_test or options.run.driver_test) try actions.register(.{
            .name = ui_test_activate_action,
            .label = "Activate UI test action",
            .handler = uiTestActivateAction,
            .palette = null,
        });

        const binding_profile = inputmod.PlatformProfile.native;
        var binding_table = try buildConfiguredBindings(allocator, &actions, binding_profile, &loaded_config, null);
        errdefer binding_table.deinit();
        if (config_path) |path| logConfigDiagnostics(path, &loaded_config);
        window.setOptionAsAlt(platformOptionAsAlt(loaded_config.settings.macos_option_as_alt));
        // How many app-bound keys may be held at once; independent of the
        // table's length so a reload never reallocates it under a held key.
        const binding_keys = try allocator.alloc(inputmod.BindingKey, binding_key_capacity);
        errdefer allocator.free(binding_keys);

        var palette_model = try palette_mod.Model.init(allocator, actions.definitions());
        errdefer palette_model.deinit();
        palette_model.refresh("");
        var palette_query = try ui.Input.init(allocator, palette_input_capacity, "");
        errdefer palette_query.deinit();
        var palette_argument = try ui.Input.init(allocator, palette_input_capacity, "");
        errdefer palette_argument.deinit();
        var search_query = try ui.Input.init(allocator, term.max_search_needle_bytes, "");
        errdefer search_query.deinit();
        var settings_input = try ui.Input.init(allocator, config.max_string_bytes, "");
        errdefer settings_input.deinit();
        var manager_input = try ui.Input.init(allocator, app_agents.Runner.max_message_bytes, "");
        errdefer manager_input.deinit();

        var spec: ChildSpec = .{ .allocator = allocator, .argv = &.{}, .env = &.{} };
        errdefer spec.deinit();
        if (wantsChild(options)) {
            // TASK-46: an interactive run's first tab starts the profile
            // `shell` names; a command or a check's fixed peer is unaffected.
            const startup_profile = if (fixedChildCommand(options) == null)
                resolveNamedProfile(loaded_config.settings.shell, loaded_config.settings.shell_profiles, &profile_choices.builtins)
            else
                null;
            spec = if (startup_profile) |profile|
                try ChildSpec.buildProfile(allocator, io, env, workspace_state.contextKind(), profile, options.run.no_shell_integration, null)
            else
                try ChildSpec.build(allocator, io, env, workspace_state.contextKind(), options);
        }
        const deterministic_scratchpad = usesDeterministicScratchpad(options);
        var scratchpad_spec = try ChildSpec.buildInteractive(
            allocator,
            io,
            env,
            workspace_state.contextKind(),
            options.run.no_shell_integration or deterministic_scratchpad,
            if (deterministic_scratchpad) "/bin/sh" else null,
        );
        errdefer scratchpad_spec.deinit();

        var workspace_registry = workspace.WorkspaceRegistry.init(allocator);
        errdefer workspace_registry.deinit() catch |err| log.err("could not release the initializing workspace registry: {s}", .{@errorName(err)});
        const workspace_key = try workspace_registry.insert(&workspace_state);
        workspace_state_owned = false;

        var workspace_presentations: std.ArrayList(*WorkspacePresentation) = .empty;
        errdefer workspace_presentations.deinit(allocator);
        try workspace_presentations.ensureUnusedCapacity(allocator, 1);
        const initial_presentation = try allocator.create(WorkspacePresentation);
        errdefer allocator.destroy(initial_presentation);
        initial_presentation.* = .{
            .key = workspace_key,
            .active_session_id = active_session_id,
            .pane_renderers = pane_renderers,
            .scratchpad_grid = scratchpad_grid,
        };
        workspace_presentations.appendAssumeCapacity(initial_presentation);

        var agent_spec = try ChildSpec.buildInteractive(allocator, io, env, .local, true, "/bin/sh");
        errdefer agent_spec.deinit();
        var remote_spec = try ChildSpec.buildRemote(allocator, env);
        errdefer remote_spec.deinit();
        var ssh_client_spec = try ChildSpec.buildSshClient(allocator, env);
        errdefer ssh_client_spec.deinit();
        var local_files = try workspace.ExecutionContext.local(allocator);
        errdefer local_files.deinit();
        var ssh_config_override: ?[]u8 = null;
        errdefer if (ssh_config_override) |path| allocator.free(path);
        var ssh_runtime_owned: ?[]u8 = null;
        errdefer if (ssh_runtime_owned) |path| allocator.free(path);
        if (options.run.ssh_test_dir) |dir| {
            ssh_config_override = try std.fmt.allocPrint(allocator, "{s}/home/.ssh/config", .{dir});
            ssh_runtime_owned = try std.fmt.allocPrint(allocator, "{s}/run", .{dir});
        }
        var sink_root_buffer: [path_capacity]u8 = undefined;
        var agents = try app_agents.Runtime.init(allocator, io, .{
            .sink_root = agentSinkRoot(io, env, options, &sink_root_buffer),
            .fake_enabled = options.run.agent_test or options.run.ssh_test or (options.run.test_driver_endpoint != null and
                std.mem.eql(u8, env.get(fake_agent_env) orelse "", "1")),
            .fake_view = options.run.agent_view_test,
            .fake_prompts = options.run.agent_prompts_test,
        });
        errdefer agents.deinit();
        agents.settings = loaded_config.settings.notifications;

        const app = try allocator.create(App);
        errdefer allocator.destroy(app);
        app.* = .{
            .agents = agents,
            .agent_spec = agent_spec,
            .claude_config_dir = env.get("CLAUDE_CONFIG_DIR"),
            .codex_home = env.get("CODEX_HOME"),
            .agent_launch_index = agent_launch_index,
            .agent_prompt_index = agent_prompt_index,
            .agent_stop_index = agent_stop_index,
            .agent_focus_index = agent_focus_index,
            .agent_view_index = agent_view_index,
            .remote_connect_index = remote_connect_index,
            .remote_address_index = remote_address_index,
            .remote_save_index = remote_save_index,
            .tab_profile_index = tab_profile_index,
            .pane_profile_index = pane_profile_index,
            .profile_choices = profile_choices,
            .process_env = env,
            .no_shell_integration = options.run.no_shell_integration,
            .remote_spec = remote_spec,
            .ssh_client_spec = ssh_client_spec,
            .ssh_runtime_dir = if (ssh_runtime_owned) |dir| dir else env.get("XDG_RUNTIME_DIR"),
            .ssh_config_override = ssh_config_override,
            .ssh_runtime_owned = ssh_runtime_owned,
            .local_files = local_files,
            .window_focused = window.hasInputFocus(),
            .allocator = allocator,
            .io = io,
            .window = window,
            .surface = surface,
            .size = size,
            .readback = readback,
            .background = colors.background,
            .needs_present = true,
            .scheduler = Scheduler.init(options.run.force_redraw),
            .fonts = fonts,
            .atlas = atlas,
            .small_fonts = small_fonts,
            .workspace_registry = workspace_registry,
            .workspace_presentations = workspace_presentations,
            .overlay_grid = overlay_grid,
            .pane_layouts = pane_layouts,
            .divider_layouts = divider_layouts,
            .spec = spec,
            .scratchpad_spec = scratchpad_spec,
            .input = input,
            .output = output,
            .child_input = .{},
            .composition = .{},
            .key_text_echo = .{},
            .ui_canvas = ui_canvas,
            .ui_tree = ui_tree,
            .action_definitions = action_definitions,
            .actions = actions,
            .palette_model = palette_model,
            .palette_query = palette_query,
            .palette_argument = palette_argument,
            .search_query = search_query,
            .settings_input = settings_input,
            .manager_input = manager_input,
            .backlog_frames = .{ .init(allocator), .init(allocator) },
            .backlog_program = backlogProgram(options, env),
            .right_click = config.Layer.resolve(config.RightClick, config.RightClick.built_in, loaded_config.settings.right_click, options.run.right_click),
            .session_right_click = options.run.right_click,
            .session_font_family = session_font_family,
            .config_current = loaded_config,
            .config_path = config_path_owned,
            .font_diagnostic = font_diagnostic,
            .theme_catalog = theme_catalog,
            .theme_pick_index = theme_pick_index,
            .scratchpad_percent_small = loaded_config.settings.scratchpad_size,
            .scratchpad_percent_large = loaded_config.settings.scratchpad_large_size,
            .font_settings = font_settings,
            .font_loaded_key = font_loaded_key,
            .font_choices = font_choices,
            .font_pick_index = font_pick_index,
            .family_from_file = family_from_file,
            .binding_table = binding_table,
            .binding_profile = binding_profile,
            .bindings = binding_table.bindings,
            .binding_keys = binding_keys,
            .binding_state = inputmod.BindingState.init(binding_keys),
            .sidebar_enabled = sidebarEnabled(options),
            .sidebar_visible = sidebar_visible,
            .sidebar_width_cols = sidebar_default_width,
            .pending_committed_text = "",
            .pending_child_bytes = .empty,
            .pending_child_offset = 0,
            .font_load = null,
            .font_scale = scale,
            .home_dir = env.get("HOME"),
            .blink_epoch_ns = Io.Clock.real.now(io).nanoseconds,
            .blink_visible = true,
            .exit_with_child = options.run.command != null,
            .spawn_finished = spec.argv.len == 0,
            .exit_logged = false,
            .screenshot = options.run.screenshot,
            .driver_artifact_dir = options.run.test_artifact_dir,
        };
        app.agents.wake = .{ .context = app, .wake_fn = agentWake };
        app.agents.probe = .{ .context = app, .probe_fn = agentSessionFacts };
        // A hidden window is headless automation: its agents notify the list,
        // never the desktop, unless a check installs its own seam.
        if (options.run.hidden) app.agents.notifier = .{ .notify_fn = discardOsNotification };
        app.startup_ns = startup_epoch_ns;
        app.logStartupPhase("fonts");
        // Decided before the theme so a restored theme name is known when
        // `resolveTheme` runs; the file itself is read further down.
        app.persistence = Persistence.forRun(allocator, io, env, options, loaded_config.settings.restore_enabled);
        app.resolveTheme();
        app.theme_catalog.order(app.activeThemeName());
        app.setThemeChoices();
        app.setFontChoices();
        app.logStartupPhase("theme");
        // Built-in checks other than the agent check never probe harnesses:
        // what is installed on a machine must not change what they measure.
        if (!usesDeterministicScratchpad(options)) app.ensureAgentDetection();
        app.setAgentLaunchChoices();
        app.refreshConfigError();
        try app.syncGrid();
        if (testdriver.isEnabled(options.run.test_driver_endpoint != null)) {
            const endpoint = options.run.test_driver_endpoint.?;
            app.driver = try platform.DriverTransport.start(allocator, endpoint, window);
            log.info("test driver listening on a local endpoint", .{});
        }
        // The control endpoints start before the first spawn so the first
        // tab's child already carries its control variables (TASK-60).
        app.startControl(env, options);
        // A saved layout replaces the default workspace before anything has
        // spawned (TASK-65); a run that restores nothing starts as before.
        const restored = app.restoreAtLaunch(options);
        // Start the worker only after every fallible initialization step. On
        // an earlier error the local errdefers own cleanup; once this starts,
        // the returned App owns and joins it during deinit.
        if (!restored) {
            app.startScratchpad(false);
            app.startChild();
        }
        app.startConfigWatcher();
        app.startAccessibility(env, options, loaded_config.settings.accessibility_enabled);
        app.persistence.noteLayout(app.layoutFingerprint(), Io.Clock.awake.now(io).nanoseconds);
        // What was restored is what the file already says: no save is owed.
        app.persistence.markSaved();
        return app;
    }

    // Startup phases (TASK-67) ------------------------------------------------

    /// Log, at debug, how long after process start a startup phase finished.
    fn logStartupPhase(self: *const App, phase: []const u8) void {
        if (self.startup_ns == 0) return;
        var buffer: [96]u8 = undefined;
        const elapsed = Io.Clock.awake.now(self.io).nanoseconds - self.startup_ns;
        log.debug("{s}", .{startupPhaseLine(&buffer, phase, elapsed)});
    }

    // The accessibility bridge (TASK-68) --------------------------------------

    /// The bridge's waker: post an event so a blocked loop iterates and
    /// `pollAccessibility` takes the request. Called from the bridge worker.
    fn accessibilityWake(context: ?*anyopaque) void {
        const self: *App = @ptrCast(@alignCast(context.?));
        self.window.postDriverWake() catch |err| {
            log.debug("could not wake the event loop for an accessibility request: {s}", .{@errorName(err)});
        };
    }

    /// Start the bridge for an ordinary run on the session bus, or for
    /// `--a11y-test` on its private bus. Every other check runs without it.
    /// A bridge that cannot start costs accessibility, never the run.
    fn startAccessibility(self: *App, env: EnvSource, options: Options, setting: bool) void {
        const address = options.run.a11y_bus_address orelse address: {
            if (usesDeterministicScratchpad(options) or options.run.test_driver_endpoint != null) return;
            break :address env.get("DBUS_SESSION_BUS_ADDRESS");
        };
        self.a11y = accessibility.Bridge.init(self.allocator, self.io, .{
            .enabled = setting,
            .session_bus_address = address,
            .application_name = app_name,
            .version = version,
            .waker = .{ .context = self, .wakeFn = accessibilityWake },
        }) catch |err| {
            log.warn("the accessibility bridge could not start: {s}", .{@errorName(err)});
            return;
        };
        self.publishAccessibility();
    }

    /// Hand the composed tree to the bridge; a no-op when nothing changed.
    fn publishAccessibility(self: *App) void {
        const bridge = self.a11y orelse return;
        if (self.ui_test != null) return;
        bridge.publish(&self.ui_tree);
    }

    /// Perform the requests assistive technology queued: an activation is a
    /// real click on the element, through SDL like any other, and a focus
    /// request moves keyboard focus in the tree.
    fn pollAccessibility(self: *App) bool {
        const bridge = self.a11y orelse return false;
        return bridge.drainRequests(self, handleAccessibilityRequest) != 0;
    }

    fn handleAccessibilityRequest(self: *App, request: *const accessibility.Request) void {
        const id: ui.Id = .{ .value = request.id() };
        switch (request.kind) {
            .activate => self.postDriverClick(.{ .id = id }, .{}) catch |err| {
                log.debug("an accessibility activation found no target: {s}", .{@errorName(err)});
            },
            .focus => if (self.activeUiTree().focus(id)) {
                self.refreshActiveUi() catch |err| log.warn("focus from assistive technology was not drawn: {s}", .{@errorName(err)});
            },
        }
    }

    // Workspace persistence (TASK-65) -----------------------------------------

    /// Everything that decides what a snapshot holds, folded together, so
    /// the loop can tell a changed layout from an unchanged one without
    /// building a snapshot.
    fn layoutFingerprint(self: *const App) u64 {
        var hasher = std.hash.Wyhash.init(self.workspace_registry.layoutFingerprint());
        hasher.update(self.activeThemeName());
        const logical = self.window.logicalSize();
        if (logical) |size| hasher.update(std.mem.asBytes(&[2]u32{ size.width, size.height }));
        for (self.workspace_presentations.items) |presentation| {
            hasher.update(&.{ @intFromBool(presentation.closing), @intFromEnum(presentation.scratchpad_presentation) });
        }
        return hasher.final();
    }

    /// The state this run would save now: the registry's snapshot completed
    /// with what only the app knows. Caller owns the result.
    fn captureState(self: *App) !state_mod.Owned {
        var owned = try self.workspace_registry.snapshot(self.allocator);
        errdefer owned.deinit();
        var percents: [state_mod.max_workspaces]?u8 = @splat(null);
        var closing: [state_mod.max_workspaces]bool = @splat(false);
        var index: usize = 0;
        while (index < self.workspace_registry.count() and index < state_mod.max_workspaces) : (index += 1) {
            const key = self.workspace_registry.keyAt(index) orelse continue;
            const presentation = self.presentationByKey(key) orelse continue;
            closing[index] = presentation.closing;
            percents[index] = switch (presentation.scratchpad_presentation) {
                .hidden => null,
                .fifty => self.scratchpad_percent_small,
                .ninety => self.scratchpad_percent_large,
            };
        }
        const logical = self.window.logicalSize();
        try completeSnapshot(&owned, .{
            .theme = if (self.theme_name_len == 0) null else self.activeThemeName(),
            .window = if (logical) |size| .{ .width = size.width, .height = size.height } else null,
            .saved_at_unix = Io.Clock.real.now(self.io).toSeconds(),
            .process_cwd = self.persistence.process_cwd,
            .scratchpad_percents = percents[0..],
            .closing = closing[0..],
        });
        return owned;
    }

    /// Encode the current state, or null (with a log line) when it cannot
    /// be written. Caller owns the bytes.
    fn encodeState(self: *App) ?[]u8 {
        var owned = self.captureState() catch |err| {
            log.warn("the workspace state could not be captured: {s}", .{@errorName(err)});
            return null;
        };
        defer owned.deinit();
        var diagnostic: state_mod.Diagnostic = .{};
        return state_mod.encode(self.allocator, &owned.snapshot, &diagnostic) catch |err| {
            log.warn("the workspace state was not saved: {s}: {s}", .{ @errorName(err), diagnostic.message() });
            return null;
        };
    }

    /// The loop's persistence step: notice a changed layout, collect a
    /// finished save, and start the debounced one that is due.
    fn pollPersistence(self: *App) void {
        if (self.persistence.path == null) return;
        const now = Io.Clock.awake.now(self.io).nanoseconds;
        self.persistence.collect();
        self.persistence.noteLayout(self.layoutFingerprint(), now);
        if (!self.persistence.debounce.due(now) or self.persistence.worker != null) return;
        const bytes = self.encodeState() orelse {
            // Unrepresentable or out of memory: try again after the next change.
            self.persistence.markSaved();
            return;
        };
        self.persistence.saveAsync(bytes);
    }

    /// The save every normal shutdown makes, on this thread, after any save
    /// still in flight: what the person last saw is what the next launch
    /// restores.
    fn saveStateAtExit(self: *App) void {
        if (self.persistence.path == null) return;
        self.persistence.joinWorker();
        const bytes = self.encodeState() orelse return;
        defer self.allocator.free(bytes);
        self.persistence.saveNow(bytes);
    }

    /// Restore the saved workspaces in place of the default one, when this
    /// run restores. Returns whether anything was restored; on false the
    /// default workspace starts as usual.
    fn restoreAtLaunch(self: *App, options: Options) bool {
        const path = self.persistence.path orelse return false;
        if (options.run.no_restore) {
            log.info("--no-restore: starting clean", .{});
            return false;
        }
        const buffer = self.allocator.alloc(u8, state_mod.load_buffer_bytes) catch |err| {
            log.warn("no memory to read the saved state: {s}", .{@errorName(err)});
            return false;
        };
        defer self.allocator.free(buffer);
        var diagnostic: state_mod.Diagnostic = .{};
        const now_unix = Io.Clock.real.now(self.io).toSeconds();
        const outcome = state_mod.restoreFromDisk(self.io, self.allocator, path, buffer, now_unix, &diagnostic) catch |err| {
            log.warn("the saved state could not be read: {s}", .{@errorName(err)});
            return false;
        };
        var owned = switch (outcome) {
            .clean => {
                if (diagnostic.len != 0) {
                    log.warn("previous state was unusable: {s}", .{diagnostic.message()});
                    self.setWorkspaceStatus(restore_unreadable_status);
                }
                return false;
            },
            .snapshot => |value| value,
        };
        defer owned.deinit();
        var plan = state_mod.planRestore(self.allocator, &owned.snapshot) catch |err| {
            log.warn("the saved state could not be planned: {s}", .{@errorName(err)});
            return false;
        };
        defer plan.deinit(self.allocator);
        if (plan.steps.len == 0) return false;
        const restored = self.executeRestore(&plan) catch |err| {
            log.warn("the saved workspaces could not be restored: {s}", .{@errorName(err)});
            return false;
        };
        if (!restored) return false;
        if (plan.theme) |name| self.adoptRestoredTheme(name);
        if (plan.window) |window_state| if (!options.run.size_explicit) self.applyRestoredWindow(window_state);
        log.info("restored {d} workspace(s) from the state file", .{owned.snapshot.workspaces.len});
        return true;
    }

    /// The saved theme applies when the settings file names none: a theme the
    /// person set in the file always wins over the remembered one.
    fn adoptRestoredTheme(self: *App, name: []const u8) void {
        if (self.config_current.settings.theme.len != 0) return;
        const index = self.theme_catalog.find(name) orelse {
            log.info("the restored theme is no longer available; keeping the default", .{});
            return;
        };
        self.persistence.setRestoredTheme(self.theme_catalog.entries[index].value);
        self.adoptThemeEntry(index, 0);
        self.theme_catalog.order(self.activeThemeName());
        self.setThemeChoices();
    }

    /// Give the window its saved size, within what the platform allows. The
    /// position and maximized state are not applied: `platform` has no
    /// query for the displays or a placement call yet.
    fn applyRestoredWindow(self: *App, saved: state_mod.Window) void {
        const width = std.math.clamp(saved.width, min_restored_window, max_restored_window);
        const height = std.math.clamp(saved.height, min_restored_window, max_restored_window);
        const current = self.window.logicalSize() orelse return;
        if (current.width == width and current.height == height) return;
        self.window.setLogicalSize(.{ .width = width, .height = height }) catch |err| {
            log.info("the saved window size was not applied: {s}", .{@errorName(err)});
        };
    }

    /// Replay `plan` through the normal workspace, tab and pane operations.
    /// The default workspace `init` made is closed once a restored one is
    /// active; every restored shell is queued to start in its directory.
    fn executeRestore(self: *App, plan: *const state_mod.RestorePlan) !bool {
        const initial = self.activePresentation();
        // The default workspace's name would collide with a saved "default".
        {
            var name_buffer: [64]u8 = undefined;
            var suffix: usize = 0;
            while (true) : (suffix += 1) {
                const candidate = try std.fmt.bufPrint(&name_buffer, "restoring-{d}", .{suffix});
                if (!planNamesWorkspace(plan, candidate)) {
                    try self.workspace_registry.rename(initial.key, candidate);
                    break;
                }
            }
        }
        const size = self.activeLive().terminal().gridSize();
        const bounds = self.terminalCellBounds() orelse return false;
        var created: [state_mod.max_workspaces]?*WorkspacePresentation = @splat(null);
        var selected: ?workspace.WorkspaceKey = null;
        const cursor = try self.allocator.create(workspace.RestoreCursor);
        defer self.allocator.destroy(cursor);
        for (plan.steps) |step| switch (step) {
            .create_workspace => |value| {
                cursor.* = .{};
                if (value.workspace >= created.len) continue;
                created[value.workspace] = self.createRestoredPresentation(value) catch |err| blk: {
                    log.warn("a saved workspace could not be restored: {s}", .{@errorName(err)});
                    break :blk null;
                };
            },
            .select_workspace => |value| {
                if (value.workspace < created.len) {
                    if (created[value.workspace]) |presentation| selected = presentation.key;
                }
            },
            inline else => |value| {
                if (value.workspace < created.len) {
                    if (created[value.workspace]) |presentation| {
                        try self.applyRestoreStep(presentation, cursor, step, size, bounds);
                    }
                }
            },
        };
        var first: ?workspace.WorkspaceKey = null;
        for (created) |maybe| {
            const presentation = maybe orelse continue;
            const model = self.workspace_registry.byKey(presentation.key) orelse continue;
            if (model.tabCount() == 0) {
                // Every saved tab failed: the workspace still shows one.
                try self.addRestoredTab(presentation, model, size);
            }
            const tab_id = model.activeTabId() orelse continue;
            presentation.active_session_id = model.focusedPaneSessionId(tab_id) orelse continue;
            if (first == null) first = presentation.key;
        }
        const target = selected orelse first orelse return false;
        try self.workspace_registry.activate(target);
        initial.closing = true;
        _ = self.finalizeClosingPresentations();
        self.requested_shutdown = false;
        for (created) |maybe| {
            const presentation = maybe orelse continue;
            if (presentation.remote == null) self.startScratchpadFor(presentation, false);
        }
        _ = self.driveRestoreQueues();
        try self.syncGrid();
        try self.composeUi();
        self.invalidateUi();
        return true;
    }

    /// Build an empty restored workspace: Local in its saved directory, or
    /// SSH with its saved target and no connection until the person asks.
    fn createRestoredPresentation(self: *App, value: anytype) !*WorkspacePresentation {
        const name = try self.uniqueWorkspaceName(value.name);
        defer self.allocator.free(name);
        switch (value.kind) {
            .local => return self.createEmptyPresentation(name, value.cwd, value.scratchpad_percent),
            .ssh => {
                const target = value.ssh orelse return error.MissingTarget;
                const presentation = try self.createRemotePresentationWith(name, target.destination, target.port, target.options, true);
                self.applyScratchpadPercent(presentation, value.scratchpad_percent);
                return presentation;
            },
            // WSL workspaces are not built yet; their layout is dropped.
            .wsl => return error.Unsupported,
        }
    }

    fn applyScratchpadPercent(self: *const App, presentation: *WorkspacePresentation, percent: ?u8) void {
        const value = percent orelse return;
        presentation.scratchpad_presentation = if (value == self.scratchpad_percent_large and value != self.scratchpad_percent_small)
            .ninety
        else
            .fifty;
    }

    /// A Local workspace with its scratchpad and no tab yet; the plan's
    /// `create_tab` steps add them.
    fn createEmptyPresentation(self: *App, name: []const u8, directory: []const u8, percent: ?u8) !*WorkspacePresentation {
        const grid_size = self.activeLive().terminal().gridSize();
        var candidate = try workspace.Workspace.initLocal(self.io, self.allocator, name, directory, grid_size);
        var candidate_owned = true;
        errdefer if (candidate_owned) candidate.deinit() catch |err| log.warn(
            "could not release a refused workspace: {s}",
            .{@errorName(err)},
        );
        var scratchpad_grid = try render.Grid.init(self.allocator, gridColors(self.palette));
        var scratchpad_grid_owned = true;
        errdefer if (scratchpad_grid_owned) scratchpad_grid.deinit();
        try scratchpad_grid.attachAtlas(self.fonts.atlasPixels(), self.atlas);
        try self.workspace_presentations.ensureUnusedCapacity(self.allocator, 1);
        const presentation = try self.allocator.create(WorkspacePresentation);
        errdefer self.allocator.destroy(presentation);
        const key = try self.workspace_registry.insert(&candidate);
        candidate_owned = false;
        presentation.* = .{
            .key = key,
            .active_session_id = .first,
            .pane_renderers = .empty,
            .scratchpad_grid = scratchpad_grid,
        };
        scratchpad_grid_owned = false;
        self.workspace_presentations.appendAssumeCapacity(presentation);
        self.applyScratchpadPercent(presentation, percent);
        return presentation;
    }

    /// One plan step on one restored workspace: the model replays it, and a
    /// session it created gets a renderer and a queued start in its saved
    /// directory (the workspace's when that one is gone).
    fn applyRestoreStep(
        self: *App,
        presentation: *WorkspacePresentation,
        cursor: *workspace.RestoreCursor,
        step: state_mod.Step,
        size: term.GridSize,
        bounds: workspace.CellRect,
    ) !void {
        const model = self.workspace_registry.byKey(presentation.key) orelse return;
        var name_buffer: [32]u8 = undefined;
        const derived = try std.fmt.bufPrint(&name_buffer, "Terminal {d}", .{model.registeredSessionCount()});
        try presentation.pane_renderers.ensureUnusedCapacity(self.allocator, 1);
        try presentation.restore_queue.ensureUnusedCapacity(self.allocator, 1);
        const made = model.applyRestoreStep(cursor, step, derived, size, bounds) catch |err| {
            log.warn("a saved tab or pane could not be restored: {s}", .{@errorName(err)});
            return;
        };
        const created = made orelse return;
        try self.adoptRestoredSession(presentation, model, created.session_id, created.cwd);
    }

    fn addRestoredTab(self: *App, presentation: *WorkspacePresentation, model: *workspace.Workspace, size: term.GridSize) !void {
        try presentation.pane_renderers.ensureUnusedCapacity(self.allocator, 1);
        try presentation.restore_queue.ensureUnusedCapacity(self.allocator, 1);
        const created = try model.createTab("Terminal 1", size);
        try self.adoptRestoredSession(presentation, model, created.session_id, model.workingDirectory());
    }

    /// Give a restored session its renderer and queue its shell. Capacity
    /// for both was reserved by the caller.
    fn adoptRestoredSession(
        self: *App,
        presentation: *WorkspacePresentation,
        model: *workspace.Workspace,
        session_id: session.SessionId,
        saved_cwd: []const u8,
    ) !void {
        if (model.sessionById(session_id)) |live| live.terminal().setClipboardAccess(.{
            .read_fn = readNativeClipboard,
            .write_fn = writeNativeClipboard,
        });
        const cwd = try self.restoredDirectory(model, saved_cwd);
        errdefer self.allocator.free(cwd);
        var pane_renderer = try self.newPaneRenderer(session_id);
        errdefer pane_renderer.deinit();
        presentation.pane_renderers.appendAssumeCapacity(pane_renderer);
        presentation.restore_queue.appendAssumeCapacity(.{ .session_id = session_id, .cwd = cwd });
    }

    /// The directory a restored shell starts in, owned: the saved one when
    /// it still exists, else the workspace's, else the inherited directory,
    /// with a status line naming the move. Remote directories are the
    /// remote shell's to check; `~` stands for the remote home.
    fn restoredDirectory(self: *App, model: *workspace.Workspace, saved: []const u8) ![]u8 {
        if (model.contextKind() != .local) {
            return self.allocator.dupe(u8, if (std.mem.eql(u8, saved, remote_home_marker)) "" else saved);
        }
        if (saved.len == 0 or directoryExists(self.io, model.contextRef(), saved)) return self.allocator.dupe(u8, saved);
        const fallback = model.workingDirectory();
        const usable = if (fallback.len != 0 and directoryExists(self.io, model.contextRef(), fallback)) fallback else "";
        self.setRestoreMovedStatus(saved, if (usable.len == 0) "the start directory" else usable);
        return self.allocator.dupe(u8, usable);
    }

    fn setRestoreMovedStatus(self: *App, missing: []const u8, instead: []const u8) void {
        const text = std.fmt.bufPrint(&self.persistence.status_storage, "restore: {s} is gone; started in {s}", .{ missing, instead }) catch
            "restore: a saved directory is gone";
        self.setWorkspaceStatus(text);
    }

    /// Start queued restored shells, one per workspace at a time through the
    /// workspace's spawn slot; an SSH workspace's wait for its connection.
    fn driveRestoreQueues(self: *App) bool {
        var changed = false;
        for (self.workspace_presentations.items) |presentation| {
            if (presentation.closing or presentation.load != null) continue;
            if (presentation.restore_queue.items.len == 0) continue;
            if (presentation.remote) |record| if (!record.ready()) continue;
            const item = presentation.restore_queue.orderedRemove(0);
            self.startRestoredChild(presentation, item);
            changed = true;
        }
        return changed;
    }

    fn restoreQueuesRunnable(self: *const App) bool {
        for (self.workspace_presentations.items) |presentation| {
            if (presentation.closing or presentation.restore_queue.items.len == 0) continue;
            if (presentation.remote) |record| if (!record.ready()) continue;
            return true;
        }
        return false;
    }

    /// Spawn one restored shell on a worker in its saved directory. Ownership
    /// of `item.cwd` transfers on entry.
    fn startRestoredChild(self: *App, presentation: *WorkspacePresentation, item: RestoreStart) void {
        const model = self.workspace_registry.byKey(presentation.key) orelse {
            self.allocator.free(item.cwd);
            return;
        };
        const process = self.processFor(model, &self.spec);
        if (process.argv.len == 0 and model.contextKind() != .ssh) {
            self.allocator.free(item.cwd);
            return;
        }
        var request = model.spawnRequest(item.session_id, process) catch |err| {
            log.warn("a restored shell could not be prepared: {s}", .{@errorName(err)});
            self.allocator.free(item.cwd);
            return;
        };
        request.cwd = item.cwd;
        const control_env = self.controlEnvFor(presentation, model, item.session_id, process.env);
        if (control_env) |env| request.env = env;
        const job = self.allocator.create(Load) catch |err| {
            log.warn("no memory to start a restored shell: {s}", .{@errorName(err)});
            self.allocator.free(item.cwd);
            if (control_env) |env| freeEntries(self.allocator, env);
            return;
        };
        job.* = .{
            .allocator = self.allocator,
            .io = self.io,
            .spawn = request,
            .spawn_cwd = item.cwd,
            .spawn_env = control_env,
            .spawn_session_id = item.session_id,
            .workspace_key = presentation.key,
            .execution_context = model.contextRef(),
        };
        job.start(self.window) catch |err| {
            log.warn("could not start the worker for a restored shell: {s}", .{@errorName(err)});
            job.freeSpawnInputs();
            self.allocator.destroy(job);
            return;
        };
        presentation.load = job;
    }

    /// Whether the active workspace is a restored SSH workspace that has not
    /// been asked to connect yet, so Enter connects it.
    fn savedSessionWaiting(self: *const App) bool {
        const record = self.activeRemote() orelse return false;
        return record.saved and record.state == .disconnected;
    }

    // The control API and the single instance (TASK-60, TASK-66) -------------

    /// The control servers' waker: post an event so a blocked loop iterates
    /// and `pollControl` takes the request. Called from connection threads;
    /// `window` is set once at startup and `postDriverWake` is thread-safe.
    fn controlWake(context: ?*anyopaque) void {
        const self: *App = @ptrCast(@alignCast(context.?));
        self.window.postDriverWake() catch |err| {
            log.debug("could not wake the event loop for a control request: {s}", .{@errorName(err)});
        };
    }

    /// Sixteen bytes for a token: the OS's entropy, else the process CSPRNG
    /// it seeded.
    fn controlEntropy(self: *App) [control_api.Token.byte_count]u8 {
        var bytes: [control_api.Token.byte_count]u8 = undefined;
        self.io.randomSecure(&bytes) catch self.io.random(&bytes);
        return bytes;
    }

    /// Start the run's control endpoint and the single-instance endpoint when
    /// `control.enabled` resolves on. Built-in checks other than
    /// `--control-test` never start them, so a check run cannot answer the
    /// person's `conduit` commands. Failures cost the API, never the run.
    fn startControl(self: *App, env: EnvSource, options: Options) void {
        self.control_pending.ensureTotalCapacity(self.allocator, control_pending_capacity) catch |err| {
            log.warn("the control endpoint is off: {s}", .{@errorName(err)});
            return;
        };
        if (usesDeterministicScratchpad(options) and !options.run.control_test) return;
        if (!config.controlEnabled(options.run.control, self.config_current.settings.control_enabled)) {
            log.debug("the control endpoint is off (control.enabled)", .{});
            return;
        }
        var dir_buffer: [path_capacity]u8 = undefined;
        const dir = controlRuntimeDir(&dir_buffer, env, options.run.runtime_dir) orelse {
            log.info("no runtime directory for the control endpoint; it is off", .{});
            return;
        };
        _ = Dir.cwd().createDirPathStatus(self.io, dir, privateArtifactPermissions(true)) catch |err| {
            log.warn("the control endpoint's directory could not be created: {s}", .{@errorName(err)});
            return;
        };
        // A short name: the whole path must fit `sockaddr_un` (about 104
        // bytes), and an isolated test run's runtime directory is long.
        var suffix: [4]u8 = undefined;
        self.io.random(&suffix);
        var endpoint_buffer: [path_capacity]u8 = undefined;
        const endpoint = std.fmt.bufPrint(&endpoint_buffer, "{s}/r-{x}.sock", .{ dir, &suffix }) catch return;
        const waker: control_api.Waker = .{ .context = self, .wakeFn = controlWake };
        if (control_api.Server.start(self.allocator, self.io, .{ .endpoint = endpoint, .enabled = true, .waker = waker })) |server| {
            self.control_server = server;
            self.self_exe = std.process.executablePathAlloc(self.io, self.allocator) catch null;
            self.agents.control_helper = self.self_exe;
            log.info("control endpoint listening in the runtime directory", .{});
        } else |err| log.warn("the control endpoint could not start: {s}", .{@errorName(err)});
        self.startInstance(env, options, dir, waker);
    }

    /// Serve `conduit` commands at `<dir>/instance.sock` with a fresh token
    /// written 0600 to the state directory. A live instance already there
    /// keeps it: this run then simply does not answer commands.
    fn startInstance(self: *App, env: EnvSource, options: Options, dir: []const u8, waker: control_api.Waker) void {
        var endpoint_buffer: [path_capacity]u8 = undefined;
        const endpoint = std.fmt.bufPrint(&endpoint_buffer, "{s}/{s}", .{ dir, control_api.instance_endpoint_file_name }) catch return;
        var token_buffer: [path_capacity]u8 = undefined;
        const token_path = instanceTokenPath(&token_buffer, env, options.run.state_dir) orelse {
            log.info("no state directory for the instance token; `conduit` commands will start a new window", .{});
            return;
        };
        const server = control_api.Server.start(self.allocator, self.io, .{ .endpoint = endpoint, .enabled = true, .waker = waker }) catch |err| {
            switch (err) {
                error.EndpointOccupied => log.info("another Conduit answers `conduit` commands", .{}),
                else => log.warn("the instance endpoint could not start: {s}", .{@errorName(err)}),
            }
            return;
        };
        const token = server.issueToken(.{ .workspace = control_api.instance_workspace, .scratchpad_session = 0 }, self.controlEntropy()) catch |err| {
            log.warn("the instance token could not be issued: {s}", .{@errorName(err)});
            server.deinit();
            return;
        };
        writeInstanceToken(self.io, token_path, token.text()) catch |err| {
            log.warn("the instance token could not be written: {s}", .{@errorName(err)});
            server.deinit();
            return;
        };
        self.instance_token_path = self.allocator.dupe(u8, token_path) catch null;
        self.instance_server = server;
        log.info("answering `conduit` commands", .{});
    }

    /// Stop both endpoints: answer every deferred request, join every
    /// connection thread, remove the sockets and this run's token file.
    fn stopControl(self: *App) void {
        for (self.control_pending.items) |item| {
            if (item.server) |server| server.complete(item.ticket, .{ .fault = .unavailable });
        }
        self.control_pending.deinit(self.allocator);
        self.control_pending = .empty;
        if (self.instance_server) |server| server.deinit();
        self.instance_server = null;
        if (self.instance_token_path) |path| {
            Dir.cwd().deleteFile(self.io, path) catch |err| log.debug("the instance token was not removed: {s}", .{@errorName(err)});
            self.allocator.free(path);
        }
        self.instance_token_path = null;
        if (self.control_server) |server| server.deinit();
        self.control_server = null;
        self.agents.control_helper = null;
        if (self.startup_arena) |*arena| arena.deinit();
        self.startup_arena = null;
        self.startup_request = null;
    }

    /// `presentation`'s token, issued on first use.
    fn controlTokenFor(self: *App, presentation: *WorkspacePresentation, model: *const workspace.Workspace) ?control_api.Token {
        if (presentation.control_token) |token| return token;
        const server = self.control_server orelse return null;
        const token = server.issueToken(.{
            .workspace = @intFromEnum(presentation.key),
            .scratchpad_session = @intFromEnum(model.scratchpadId()),
        }, self.controlEntropy()) catch |err| {
            log.warn("no control token for a workspace: {s}", .{@errorName(err)});
            return null;
        };
        presentation.control_token = token;
        return token;
    }

    fn revokeControl(self: *App, presentation: *WorkspacePresentation) void {
        if (self.control_server) |server| server.revokeWorkspace(@intFromEnum(presentation.key));
        presentation.control_token = null;
        for (&self.control_status) |*slot| {
            if (slot.*) |mark| if (mark.key == presentation.key) {
                slot.* = null;
            };
        }
    }

    /// The environment a child of `session_id` spawns with when it gets the
    /// control variables: `base` plus the three, owned by the caller. Null
    /// when the endpoint is off or the session may not have them.
    fn controlEnvFor(
        self: *App,
        presentation: *WorkspacePresentation,
        model: *const workspace.Workspace,
        session_id: session.SessionId,
        base: []const []const u8,
    ) ?[][]const u8 {
        const server = self.control_server orelse return null;
        const kind = model.sessionKind(session_id) orelse return null;
        if (!controlEnvAllowed(kind, model.contextKind())) return null;
        const token = self.controlTokenFor(presentation, model) orelse return null;
        return appendControlEnv(self.allocator, base, server.endpointPath(), token.text(), session_id) catch |err| {
            log.warn("a child starts without its control variables: {s}", .{@errorName(err)});
            return null;
        };
    }

    fn controlHandler(self: *App) control_api.Handler {
        return .{ .context = self, .vtable = &control_vtable };
    }

    const control_vtable: control_api.Handler.VTable = .{ .handle = handleControl };

    /// The servers' hand-off, on this thread from `pollControl`. A request
    /// that cannot run yet, or whose spawn is still running, is deferred.
    fn handleControl(context: *anyopaque, ticket: control_api.Ticket, request: *const control_api.Request) control_api.Disposition {
        const self: *App = @ptrCast(@alignCast(context));
        // Instance tokens exist only on the instance server, workspace tokens
        // only on the run's; the scope says which queue holds the ticket.
        const server = if (request.workspace == control_api.instance_workspace) self.instance_server else self.control_server;
        if (self.control_pending.items.len >= control_pending_capacity) return .{ .reply = .{ .fault = .busy } };
        // Requests run in arrival order: behind a waiting one, wait too.
        if (self.controlWaiting()) return self.deferControl(server, ticket, request, .waiting);
        return switch (self.controlPerform(request)) {
            .reply => |reply| .{ .reply = reply },
            .wait => self.deferControl(server, ticket, request, .waiting),
            .spawning => |spawn| self.deferControl(server, ticket, request, .{ .spawning = spawn }),
        };
    }

    fn deferControl(
        self: *App,
        server: ?*control_api.Server,
        ticket: control_api.Ticket,
        request: *const control_api.Request,
        state: @FieldType(ControlPending, "state"),
    ) control_api.Disposition {
        // Capacity was reserved in `startControl` and checked by the caller.
        self.control_pending.appendAssumeCapacity(.{
            .server = server,
            .ticket = ticket,
            .request = request,
            .deadline_ns = Io.Clock.awake.now(self.io).nanoseconds + control_wait_ms * std.time.ns_per_ms,
            .state = state,
        });
        return .deferred;
    }

    fn controlWaiting(self: *const App) bool {
        for (self.control_pending.items) |item| if (item.state == .waiting) return true;
        return false;
    }

    /// Take queued requests, retry deferred ones in order and expire those
    /// that waited too long. Owner thread, once per loop iteration.
    fn pollControl(self: *App) bool {
        var changed = false;
        if (self.control_server) |server| changed = server.service(self.controlHandler(), control_service_batch) != 0 or changed;
        if (self.instance_server) |server| changed = server.service(self.controlHandler(), control_service_batch) != 0 or changed;
        const now = Io.Clock.awake.now(self.io).nanoseconds;
        var index: usize = 0;
        while (index < self.control_pending.items.len) {
            const item = &self.control_pending.items[index];
            switch (item.state) {
                .spawning => |spawn| {
                    // A workspace closed under its spawn never reports back.
                    const presentation = self.presentationByKey(spawn.key);
                    if (presentation == null or presentation.?.closing) {
                        self.finishControl(index, .{ .fault = .unavailable });
                        changed = true;
                        continue;
                    }
                    index += 1;
                },
                .waiting => {
                    switch (self.controlPerform(item.request)) {
                        .reply => |reply| {
                            self.finishControl(index, reply);
                            changed = true;
                        },
                        .spawning => |spawn| {
                            item.state = .{ .spawning = spawn };
                            changed = true;
                            index += 1;
                        },
                        .wait => {
                            if (now < item.deadline_ns) break;
                            self.finishControl(index, .{ .fault = .unavailable });
                            changed = true;
                        },
                    }
                },
            }
        }
        return changed;
    }

    /// Answer and forget `control_pending[index]`.
    fn finishControl(self: *App, index: usize, reply: control_api.Reply) void {
        const item = self.control_pending.orderedRemove(index);
        if (item.server) |server| {
            server.complete(item.ticket, reply);
            return;
        }
        // The startup command has no client left to tell.
        switch (reply) {
            .result => log.info("the startup command was carried out", .{}),
            .fault => |fault| {
                log.warn("the startup command was not carried out: {s}", .{fault.message()});
                self.setWorkspaceStatus("conduit: the command could not be carried out");
            },
        }
    }

    /// A spawn job for `session_id` reported back: answer the request that
    /// started it.
    fn controlSpawnFinished(self: *App, key: workspace.WorkspaceKey, session_id: session.SessionId, started: bool) void {
        var index: usize = 0;
        while (index < self.control_pending.items.len) {
            const item = self.control_pending.items[index];
            const spawn = switch (item.state) {
                .spawning => |value| value,
                .waiting => {
                    index += 1;
                    continue;
                },
            };
            if (spawn.key != key or spawn.session_id != session_id) {
                index += 1;
                continue;
            }
            self.finishControl(index, if (started) .{ .result = .{ .opened = spawn.opened } } else .{ .fault = .internal_error });
        }
    }

    const ControlOutcome = union(enum) {
        reply: control_api.Reply,
        /// Not now: input, a modal or the spawn slot is busy.
        wait,
        spawning: ControlSpawn,
    };

    const ControlSpawn = @FieldType(@FieldType(ControlPending, "state"), "spawning");

    fn controlFault(code: control_api.FaultCode) ControlOutcome {
        return .{ .reply = .{ .fault = code } };
    }

    fn controlOk() ControlOutcome {
        return .{ .reply = .{ .result = .ok } };
    }

    fn controlOpened(opened: control_api.Opened) ControlOutcome {
        return .{ .reply = .{ .result = .{ .opened = opened } } };
    }

    /// Perform one request. Never fails: an unexpected error is logged and
    /// answered `InternalError`.
    fn controlPerform(self: *App, request: *const control_api.Request) ControlOutcome {
        return self.controlPerformChecked(request) catch |err| {
            log.warn("a control request failed: {s}", .{@errorName(err)});
            return controlFault(.internal_error);
        };
    }

    /// The caller a workspace token names: its workspace and, when it gave
    /// one, its own session, checked to belong to that workspace.
    const ControlCaller = struct {
        key: workspace.WorkspaceKey,
        presentation: *WorkspacePresentation,
        model: *workspace.Workspace,
        session_id: ?session.SessionId,
    };

    fn controlCaller(self: *App, request: *const control_api.Request) union(enum) { caller: ControlCaller, fault: control_api.FaultCode } {
        const key: workspace.WorkspaceKey = @enumFromInt(request.workspace);
        const presentation = self.presentationByKey(key) orelse return .{ .fault = .not_found };
        if (presentation.closing) return .{ .fault = .not_found };
        const model = self.workspace_registry.byKey(key) orelse return .{ .fault = .not_found };
        var session_id: ?session.SessionId = null;
        if (request.session) |raw| {
            const id: session.SessionId = @enumFromInt(raw);
            switch (model.sessionKind(id) orelse return .{ .fault = .not_found }) {
                // The server refuses the scratchpad already; this is the
                // owner's own check, never relaxed.
                .scratchpad => return .{ .fault = .scratchpad_not_addressable },
                .connection => return .{ .fault = .not_found },
                .human_terminal, .agent_terminal => session_id = id,
            }
        }
        return .{ .caller = .{ .key = key, .presentation = presentation, .model = model, .session_id = session_id } };
    }

    fn controlPerformChecked(self: *App, request: *const control_api.Request) !ControlOutcome {
        const method = std.meta.activeTag(request.params);
        if (method == .ping) return .{ .reply = .{ .result = .pong } };
        const instance = request.workspace == control_api.instance_workspace;
        // The instance token opens workspaces and launches agents; it names
        // no workspace, so it cannot open tabs or report status in one.
        if (instance and !method.isInstance()) return controlFault(.unauthorized);
        if (self.requested_shutdown or self.workspace_registry.count() == 0) return controlFault(.unavailable);
        const caller: ?ControlCaller = if (instance) null else switch (self.controlCaller(request)) {
            .caller => |value| value,
            .fault => |code| return controlFault(code),
        };
        return switch (request.params) {
            .ping => unreachable, // answered above
            .tab_open => |open| self.controlTabOpen(caller.?, open.spawn, open.title),
            .pane_split => |split| self.controlPaneSplit(caller.?, split.direction, split.spawn),
            .view_agent => |view| self.controlViewAgent(caller.?, view.agent_id),
            .view_backlog => self.controlViewBacklog(caller.?),
            .tab_status => |status| self.controlTabStatus(caller.?, status.text, status.attention),
            .notify => |note| blk: {
                const id = caller.?.session_id orelse caller.?.model.activeSessionId() orelse break :blk controlFault(.not_found);
                self.agents.raiseTerminal(caller.?.key, id, note.title, note.body);
                self.invalidateUi();
                break :blk controlOk();
            },
            .agent_event => |event| blk: {
                self.agents.ingestControlEvent(caller.?.key, &event.agent, event.payload_json) catch |err| break :blk controlFault(switch (err) {
                    error.NotFound => .not_found,
                    error.Unavailable => .unavailable,
                    error.Rejected => .invalid_params,
                });
                break :blk controlOk();
            },
            .instance_open_directory => |open| self.controlOpenDirectory(open.path),
            .instance_open_ssh => |open| self.controlOpenSsh(open.destination),
            .instance_open_workspace => |open| self.controlOpenWorkspace(open.name, open.path),
            .instance_agent => |launch| self.controlAgent(caller, launch.harness, launch.prompt),
            // TASK-79 phase two wires the editor pane (decision-12).
            .editor_open, .editor_goto, .editor_diff, .editor_reveal, .editor_close => controlFault(.unavailable),
        };
    }

    /// Whether the person is mid-gesture or a modal owns input: a control
    /// request then waits rather than move focus under them.
    fn controlUiBusy(self: *const App) bool {
        return self.paletteVisible() or self.closeModalActive() or self.workspaceTransitionBlocked();
    }

    /// Bring `key` forward and, when given, the tab and pane presenting
    /// `session_id`. False when that has to wait.
    fn controlFocus(self: *App, key: workspace.WorkspaceKey, session_id: ?session.SessionId) !bool {
        if (self.controlUiBusy()) return false;
        if (self.workspace_registry.activeKey() != key) {
            if (!try self.prepareWorkspaceTransition()) return false;
            try self.commitWorkspaceActivation(key, false);
        }
        const id = session_id orelse return true;
        const model = self.activeWorkspace();
        const location = model.paneForSession(id) orelse return true;
        if (model.activeTabId() == location.tab_id and model.focusedPaneId(location.tab_id) == location.pane_id) return true;
        if (!try self.prepareToLeaveActiveSession()) return false;
        try model.focusPane(location.tab_id, location.pane_id);
        try model.activateTab(location.tab_id);
        try self.adoptActiveTab();
        return true;
    }

    /// The working directory a new terminal inherits: the request's, else
    /// the caller session's tracked cwd, else the active session's, else the
    /// workspace's. Owned by the caller.
    fn controlCwd(self: *App, caller: ControlCaller, requested: ?[]const u8) ![]u8 {
        if (requested) |cwd| return self.allocator.dupe(u8, cwd);
        if (caller.session_id) |id| if (caller.model.sessionById(id)) |live| if (live.workingDirectory()) |cwd| {
            return self.allocator.dupe(u8, cwd);
        };
        const inherited = self.activeLive().workingDirectory() orelse self.activeWorkspace().workingDirectory();
        return self.allocator.dupe(u8, inherited);
    }

    /// Whether the caller's workspace can start a terminal now: its spawn
    /// slot is free and, for SSH, its connection is up.
    fn controlSpawnReady(caller: ControlCaller) union(enum) { ready, wait, fault: control_api.FaultCode } {
        if (caller.presentation.load != null) return .wait;
        if (caller.presentation.remote) |record| if (!record.ready()) return .{ .fault = .unavailable };
        return .ready;
    }

    fn controlTabOpen(self: *App, caller: ControlCaller, spawn: control_api.protocol.Spawn, title: ?[]const u8) !ControlOutcome {
        switch (controlSpawnReady(caller)) {
            .ready => {},
            .wait => return .wait,
            .fault => |code| return controlFault(code),
        }
        if (!try self.controlFocus(caller.key, caller.session_id)) return .wait;
        if (!try self.prepareToLeaveActiveSession()) return .wait;
        const cwd = try self.controlCwd(caller, spawn.cwd);
        var cwd_owned = true;
        defer if (cwd_owned) self.allocator.free(cwd);
        const argv: ?[][]const u8 = if (spawn.command) |command| try dupeArgv(self.allocator, command) else null;
        var argv_owned = true;
        defer if (argv_owned) if (argv) |owned| freeEntries(self.allocator, owned);

        try caller.presentation.pane_renderers.ensureUnusedCapacity(self.allocator, 1);
        const expected_session = session.SessionId.fromOrdinal(@intCast(caller.model.registeredSessionCount()));
        var pane_renderer = try self.newPaneRenderer(expected_session);
        var renderer_owned = true;
        errdefer if (renderer_owned) pane_renderer.deinit();
        var name_buffer: [32]u8 = undefined;
        const name = title orelse try std.fmt.bufPrint(&name_buffer, "Terminal {d}", .{caller.model.registeredSessionCount()});
        const created = try caller.model.createTab(name, self.activeLive().terminal().gridSize());
        pane_renderer.session_id = created.session_id;
        caller.presentation.pane_renderers.appendAssumeCapacity(pane_renderer);
        renderer_owned = false;
        try self.adoptActiveTab();
        cwd_owned = false;
        argv_owned = false;
        self.startTabChildWith(created.session_id, cwd, argv);
        const opened: control_api.Opened = .{ .tab = @intFromEnum(created.tab_id), .session = @intFromEnum(created.session_id) };
        // No child to wait for (a workspace without a shell).
        if (caller.presentation.load == null) return controlOpened(opened);
        return .{ .spawning = .{ .key = caller.key, .session_id = created.session_id, .opened = opened } };
    }

    fn controlPaneSplit(self: *App, caller: ControlCaller, direction: control_api.protocol.Direction, spawn: control_api.protocol.Spawn) !ControlOutcome {
        switch (controlSpawnReady(caller)) {
            .ready => {},
            .wait => return .wait,
            .fault => |code| return controlFault(code),
        }
        if (!try self.controlFocus(caller.key, caller.session_id)) return .wait;
        if (!try self.prepareToLeaveActiveSession()) return .wait;
        const model = caller.model;
        const tab_id = model.activeTabId() orelse return controlFault(.not_found);
        const tab = model.tab(tab_id) orelse return controlFault(.not_found);
        if (tab.paneCount() >= pane_ui_capacity) return controlFault(.unavailable);
        const focused_pane = model.focusedPaneId(tab_id) orelse return controlFault(.not_found);
        const bounds = self.terminalCellBounds() orelse return controlFault(.unavailable);
        const cwd = try self.controlCwd(caller, spawn.cwd);
        var cwd_owned = true;
        defer if (cwd_owned) self.allocator.free(cwd);
        const argv: ?[][]const u8 = if (spawn.command) |command| try dupeArgv(self.allocator, command) else null;
        var argv_owned = true;
        defer if (argv_owned) if (argv) |owned| freeEntries(self.allocator, owned);

        try caller.presentation.pane_renderers.ensureUnusedCapacity(self.allocator, 1);
        const expected_session = session.SessionId.fromOrdinal(@intCast(model.registeredSessionCount()));
        var pane_renderer = try self.newPaneRenderer(expected_session);
        var renderer_owned = true;
        errdefer if (renderer_owned) pane_renderer.deinit();
        const split: workspace.PaneSplit = switch (direction) {
            .right => .right,
            .down => .down,
        };
        const created = model.createPaneSession(tab_id, focused_pane, .human_terminal, self.activeLive().terminal().gridSize(), split, bounds) catch |err| {
            if (err == error.InvalidGeometry) {
                pane_renderer.deinit();
                renderer_owned = false;
                return controlFault(.unavailable);
            }
            return err;
        };
        pane_renderer.session_id = created.session_id;
        caller.presentation.pane_renderers.appendAssumeCapacity(pane_renderer);
        renderer_owned = false;
        try self.adoptFocusedPane();
        cwd_owned = false;
        argv_owned = false;
        self.startTabChildWith(created.session_id, cwd, argv);
        const opened: control_api.Opened = .{
            .tab = @intFromEnum(tab_id),
            .pane = @intFromEnum(created.pane_id),
            .session = @intFromEnum(created.session_id),
        };
        if (caller.presentation.load == null) return controlOpened(opened);
        return .{ .spawning = .{ .key = caller.key, .session_id = created.session_id, .opened = opened } };
    }

    fn controlViewAgent(self: *App, caller: ControlCaller, agent_id: ?[]const u8) !ControlOutcome {
        const runner = if (agent_id) |text| found: {
            const raw = std.fmt.parseInt(u64, text, 10) catch return controlFault(.not_found);
            if (raw == 0) return controlFault(.not_found);
            const record = self.agents.registry.get(@enumFromInt(raw)) orelse return controlFault(.not_found);
            if (record.workspace != caller.key) return controlFault(.not_found);
            break :found self.agents.runnerForSession(caller.key, record.session) orelse return controlFault(.not_found);
        } else self.agents.runnerForSession(caller.key, caller.session_id orelse return controlFault(.not_found)) orelse
            return controlFault(.not_found);
        if (runner.agent_id == null) return controlFault(.unavailable);
        if (!try self.controlFocus(caller.key, runner.session)) return .wait;
        runner.view.active = true;
        runner.view.follow = true;
        runner.view.selection = null;
        self.agent_view_pointer = null;
        self.ui_tree.clearFocus();
        self.composition.cancel();
        try self.refreshActiveUi();
        try self.syncTextInput();
        return controlOpened(.{ .session = @intFromEnum(runner.session) });
    }

    fn controlViewBacklog(self: *App, caller: ControlCaller) !ControlOutcome {
        if (!try self.controlFocus(caller.key, caller.session_id)) return .wait;
        try self.openBacklog();
        return if (self.backlogShown()) controlOk() else controlFault(.unavailable);
    }

    fn controlStatusFor(self: *const App, key: workspace.WorkspaceKey, tab_id: workspace.TabId) ?*const ControlTabStatus {
        for (&self.control_status) |*slot| {
            if (slot.*) |*mark| if (mark.key == key and mark.tab_id == tab_id) return mark;
        }
        return null;
    }

    fn clearControlAttention(self: *App, key: workspace.WorkspaceKey, tab_id: workspace.TabId) void {
        for (&self.control_status) |*slot| {
            const mark = if (slot.*) |*value| value else continue;
            if (mark.key != key or mark.tab_id != tab_id or !mark.attention) continue;
            mark.attention = false;
            if (mark.text_len == 0) slot.* = null;
            self.invalidateUi();
        }
    }

    fn controlTabStatus(self: *App, caller: ControlCaller, text: ?[]const u8, attention: ?bool) !ControlOutcome {
        const tab_id = if (caller.session_id) |id|
            (caller.model.paneForSession(id) orelse return controlFault(.not_found)).tab_id
        else
            caller.model.activeTabId() orelse return controlFault(.not_found);
        var slot: ?*?ControlTabStatus = null;
        var free: ?*?ControlTabStatus = null;
        for (&self.control_status) |*candidate| {
            if (candidate.*) |mark| {
                if (mark.key == caller.key and mark.tab_id == tab_id) slot = candidate;
                // A mark whose tab or workspace is gone is free again.
                const model = self.workspace_registry.byKey(mark.key);
                if (free == null and (model == null or model.?.tab(mark.tab_id) == null)) free = candidate;
            } else if (free == null) free = candidate;
        }
        const target = slot orelse free orelse return controlFault(.busy);
        if (slot == null) target.* = .{ .key = caller.key, .tab_id = tab_id };
        const mark = &target.*.?;
        if (text) |value| {
            // The protocol bounds the text to the buffer.
            @memcpy(mark.text[0..value.len], value);
            mark.text_len = @intCast(value.len);
        }
        if (attention) |value| mark.attention = value;
        if (mark.text_len == 0 and !mark.attention) target.* = null;
        self.invalidateUi();
        try self.refreshActiveUi();
        return controlOk();
    }

    /// The Local workspace already open in `directory`, counting the first
    /// workspace, which opens in this process's directory without naming it.
    fn localWorkspaceForDirectory(self: *App, directory: []const u8) ?workspace.WorkspaceKey {
        if (self.workspaceForDirectory(directory)) |key| return key;
        const cwd = std.process.currentPathAlloc(self.io, self.allocator) catch return null;
        defer self.allocator.free(cwd);
        if (!std.mem.eql(u8, normalizedWorkspaceDirectory(cwd), directory)) return null;
        var index: usize = 0;
        while (index < self.workspace_registry.count()) : (index += 1) {
            const key = self.workspace_registry.keyAt(index) orelse continue;
            const presentation = self.presentationByKey(key) orelse continue;
            if (presentation.closing) continue;
            const model = self.workspace_registry.byKey(key) orelse continue;
            if (model.contextKind() == .local and model.workingDirectory().len == 0) return key;
        }
        return null;
    }

    fn controlWorkspaceOpened(key: workspace.WorkspaceKey) ControlOutcome {
        return controlOpened(.{ .workspace = std.math.cast(u32, @intFromEnum(key)) });
    }

    /// Bring an existing workspace forward. False when that has to wait.
    fn controlActivate(self: *App, key: workspace.WorkspaceKey) !bool {
        if (self.controlUiBusy()) return false;
        if (self.workspace_registry.activeKey() == key) return true;
        if (!try self.prepareWorkspaceTransition()) return false;
        try self.commitWorkspaceActivation(key, false);
        return true;
    }

    /// Open a Local workspace named after `base` in `directory`, start its
    /// first tab and scratchpad and switch to it, as `workspace.create` does.
    fn controlCreateWorkspace(self: *App, directory: []const u8, base: []const u8) !workspace.WorkspaceKey {
        const name = try self.uniqueWorkspaceName(base);
        defer self.allocator.free(name);
        const presentation = try self.createWorkspacePresentation(directory, name);
        self.startPresentationChild(presentation, presentation.active_session_id, .{
            .argv = self.scratchpad_spec.argv,
            .env = self.scratchpad_spec.env,
        });
        self.startScratchpadFor(presentation, false);
        try self.commitWorkspaceActivation(presentation.key, false);
        return presentation.key;
    }

    fn controlOpenDirectory(self: *App, path: []const u8) !ControlOutcome {
        if (!std.fs.path.isAbsolute(path)) return controlFault(.invalid_params);
        const directory = normalizedWorkspaceDirectory(path);
        if (self.localWorkspaceForDirectory(directory)) |key| {
            if (!try self.controlActivate(key)) return .wait;
            return controlWorkspaceOpened(key);
        }
        if (self.controlUiBusy() or !try self.prepareWorkspaceTransition()) return .wait;
        const base = std.mem.trim(u8, workspaceBaseName(directory), std.ascii.whitespace[0..]);
        if (base.len == 0) return controlFault(.invalid_params);
        return controlWorkspaceOpened(try self.controlCreateWorkspace(directory, base));
    }

    fn controlOpenSsh(self: *App, text: []const u8) !ControlOutcome {
        if (comptime !ssh.supported) return controlFault(.unavailable);
        const destination = config.parseDestination(text) catch return controlFault(.invalid_params);
        if (self.controlUiBusy() or !try self.prepareWorkspaceTransition()) return .wait;
        if (!try self.openRemoteWorkspace(config.destinationHost(destination), destination.target, destination.port, text)) {
            return controlFault(.unavailable);
        }
        const key = self.workspace_registry.activeKey() orelse return controlFault(.unavailable);
        return controlWorkspaceOpened(key);
    }

    fn controlOpenWorkspace(self: *App, name: []const u8, path: ?[]const u8) !ControlOutcome {
        if (self.workspace_registry.keyForName(name)) |key| {
            const presentation = self.presentationByKey(key) orelse return controlFault(.not_found);
            if (presentation.closing) return controlFault(.not_found);
            if (!try self.controlActivate(key)) return .wait;
            return controlWorkspaceOpened(key);
        }
        const directory = path orelse return controlFault(.not_found);
        if (!std.fs.path.isAbsolute(directory)) return controlFault(.invalid_params);
        if (self.controlUiBusy() or !try self.prepareWorkspaceTransition()) return .wait;
        return controlWorkspaceOpened(try self.controlCreateWorkspace(normalizedWorkspaceDirectory(directory), name));
    }

    /// Launch `harness` in the caller's workspace (a workspace token) or the
    /// active one (the instance token), as `agent.launch` does.
    fn controlAgent(self: *App, caller: ?ControlCaller, harness: []const u8, prompt: ?[]const u8) !ControlOutcome {
        const choice = controlHarnessChoice(harness) orelse return controlFault(.not_found);
        if (choice == .fake and !self.agents.fake_enabled) return controlFault(.not_found);
        const key = if (caller) |value| value.key else self.workspace_registry.activeKey() orelse return controlFault(.unavailable);
        const presentation = self.presentationByKey(key) orelse return controlFault(.not_found);
        if (presentation.load != null) return .wait;
        if (presentation.remote) |record| if (!record.ready()) return controlFault(.unavailable);
        if (!try self.controlFocus(key, if (caller) |value| value.session_id else null)) return .wait;
        if (!try self.prepareToLeaveActiveSession()) return .wait;
        const before = self.activePresentation().active_session_id;
        try self.launchAgentWith(choice, prompt, .{});
        const after = self.activePresentation().active_session_id;
        if (after == before or self.agents.runnerForSession(key, after) == null) return controlFault(.unavailable);
        const model = self.activeWorkspace();
        const opened: control_api.Opened = .{
            .workspace = std.math.cast(u32, @intFromEnum(key)),
            .tab = if (model.activeTabId()) |tab_id| @intFromEnum(tab_id) else null,
            .session = @intFromEnum(after),
        };
        if (presentation.load == null) return controlOpened(opened);
        return .{ .spawning = .{ .key = key, .session_id = after, .opened = opened } };
    }

    /// Queue `command` (TASK-66) to run as soon as this run can: a `conduit`
    /// command that found no running instance to forward it to. Its strings
    /// are copied; `cwd` is the absolute directory it was typed in.
    fn queueStartupCommand(self: *App, command: CliCommand, cwd: []const u8) !void {
        if (command == .control) return;
        self.startup_arena = .init(self.allocator);
        const arena = self.startup_arena.?.allocator();
        const params: control_api.Params = switch (command) {
            .open_directory => |path| .{ .instance_open_directory = .{ .path = try arena.dupe(u8, path) } },
            .open_ssh => |destination| .{ .instance_open_ssh = .{ .destination = try arena.dupe(u8, destination) } },
            .open_workspace => |name| .{ .instance_open_workspace = .{ .name = try arena.dupe(u8, name), .path = try arena.dupe(u8, cwd) } },
            .agent => |launch| .{ .instance_agent = .{
                .harness = try arena.dupe(u8, launch.harness),
                .prompt = if (launch.prompt.len == 0) null else try std.mem.join(arena, " ", launch.prompt),
            } },
            .control => unreachable, // returned above
        };
        self.startup_request = .{ .workspace = control_api.instance_workspace, .session = null, .params = params };
        if (self.control_pending.capacity == 0) try self.control_pending.ensureTotalCapacity(self.allocator, control_pending_capacity);
        self.control_pending.appendAssumeCapacity(.{
            .server = null,
            .ticket = .{ .slot = 0, .generation = 0 },
            .request = &self.startup_request.?,
            // Startup itself (fonts, the first shell) may take a while.
            .deadline_ns = Io.Clock.awake.now(self.io).nanoseconds + 60 * std.time.ns_per_s,
            .state = .waiting,
        });
    }

    // SSH workspaces (TASK-43 part two, TASK-44, TASK-45) -------------------

    /// The context's wake hook: a worker found the connection gone. Post an
    /// event so a blocked loop iterates and `pollRemote` applies it.
    fn sshWake(context: *anyopaque) void {
        const self: *App = @ptrCast(@alignCast(context));
        self.window.postDriverWake() catch |err| {
            log.debug("could not wake the event loop for an ssh connection change: {s}", .{@errorName(err)});
        };
    }

    /// Release a presentation's SSH record: join its host probe and free the
    /// respawn queue. Its workspace, whose context the probe borrows, must
    /// still exist.
    fn releaseRemote(self: *App, presentation: *WorkspacePresentation) void {
        const record = presentation.remote orelse return;
        if (record.host_probe) |probe| probe.destroy();
        for (record.respawn.items) |item| self.allocator.free(item.cwd);
        record.respawn.deinit(self.allocator);
        self.allocator.destroy(record);
        presentation.remote = null;
    }

    fn activeRemote(self: *const App) ?*RemotePresentation {
        if (self.workspace_registry.count() == 0) return null;
        return self.activePresentationConst().remote;
    }

    /// Whether the active workspace shows its connection terminal over its
    /// panes: always while the master is not connected, so every OpenSSH
    /// prompt is in front of the person, and on request once it is.
    fn connectionVisible(self: *const App) bool {
        const record = self.activeRemote() orelse return false;
        return record.state != .connected or record.view_requested;
    }

    fn setRemoteStatus(self: *App, comptime format: []const u8, args: anytype) void {
        const text = std.fmt.bufPrint(&self.remote_status_storage, format, args) catch "ssh: status";
        self.setWorkspaceStatus(text);
    }

    /// Refuse to start a remote session before the connection is ready: a
    /// client with no master would open a second, separately authenticated
    /// connection (decision-8). Says why on the status line.
    fn remoteNotReady(self: *App) bool {
        const record = self.activePresentation().remote orelse return false;
        if (record.ready()) return false;
        self.setRemoteStatus("ssh: {s}", .{remote.stateWords(record.state)});
        return true;
    }

    /// What a new terminal in `model` runs: the remote user's login shell
    /// with the remote overlay in an SSH workspace, otherwise `local`.
    fn processFor(self: *const App, model: *const workspace.Workspace, local: *const ChildSpec) workspace.ProcessSpec {
        const spec = if (model.contextKind() == .ssh) &self.remote_spec else local;
        return .{ .argv = spec.argv, .env = spec.env };
    }

    /// Let a session's terminal believe OSC 7 from the remote host, once that
    /// host's name is known. Called when a child attaches, before it can have
    /// printed anything.
    fn applyRemoteHost(presentation: *WorkspacePresentation, model: *workspace.Workspace, id: session.SessionId) void {
        const record = presentation.remote orelse return;
        const host = record.remoteHost() orelse return;
        const live = model.sessionById(id) orelse return;
        live.terminal().setWorkingDirectoryHost(host) catch |err| {
            log.debug("the remote host name was not usable for OSC 7: {s}", .{@errorName(err)});
        };
    }

    /// Build an SSH workspace: its context, a `Terminal 1` tab whose shell
    /// starts once connected, the connection session presenting the master,
    /// and their renderers. Starts the master; nothing remote spawns yet.
    fn createRemotePresentation(
        self: *App,
        name: []const u8,
        destination: []const u8,
        port: ?u16,
    ) !*WorkspacePresentation {
        return self.createRemotePresentationWith(name, destination, port, &.{}, false);
    }

    /// `createRemotePresentation`, with `-o` options, or `restored`: then
    /// there is no `Terminal 1` tab (the restore plan adds the saved tabs)
    /// and no master is started until the person asks (TASK-65).
    fn createRemotePresentationWith(
        self: *App,
        name: []const u8,
        destination: []const u8,
        port: ?u16,
        options: []const []const u8,
        restored: bool,
    ) !*WorkspacePresentation {
        // Elsewhere the context is not built (decision-8); nothing below is
        // analysed for those targets.
        if (comptime !ssh.supported) return error.Unsupported;
        const grid_size = self.activeLive().terminal().gridSize();
        const context = try ssh.SshContext.create(self.allocator, self.io, .{
            .target = .{ .destination = destination, .port = port, .config_file = self.ssh_config_override, .options = options },
            .local_env = self.ssh_client_spec.env,
            .runtime_dir = self.ssh_runtime_dir,
            .wake = .{ .context = self, .wake_fn = sshWake },
        });
        // The implementation is heap-stable; the workspace owns it from here.
        // `create` just made an SSH context, so the downcast cannot fail.
        const ssh_context = ssh.SshContext.fromContext(&context) orelse unreachable;
        var candidate = try workspace.Workspace.init(self.io, self.allocator, name, "", context, grid_size);
        var candidate_owned = true;
        errdefer if (candidate_owned) candidate.deinit() catch |err| log.warn(
            "could not release a refused ssh workspace: {s}",
            .{@errorName(err)},
        );
        // A restored workspace gets its tabs from the plan; its active
        // session is set once they exist.
        var session_id: session.SessionId = .first;
        if (!restored) {
            session_id = try candidate.createSession(.human_terminal, grid_size);
            _ = try candidate.registerTab("Terminal 1", session_id);
            const live = candidate.sessionById(session_id) orelse return error.SessionNotFound;
            live.terminal().setClipboardAccess(.{
                .read_fn = readNativeClipboard,
                .write_fn = writeNativeClipboard,
            });
        }
        const connection_id = try candidate.createSession(.connection, grid_size);
        // The view's `destroy` only lets go; the context keeps the master.
        try candidate.attachChild(connection_id, ssh_context.masterTerminal());

        var pane_renderers: std.ArrayList(PaneRenderer) = .empty;
        errdefer {
            for (pane_renderers.items) |*pane_renderer| pane_renderer.deinit();
            pane_renderers.deinit(self.allocator);
        }
        try pane_renderers.ensureUnusedCapacity(self.allocator, 2);
        if (!restored) pane_renderers.appendAssumeCapacity(try self.newPaneRenderer(session_id));
        pane_renderers.appendAssumeCapacity(try self.newPaneRenderer(connection_id));

        var scratchpad_grid = try render.Grid.init(self.allocator, gridColors(self.palette));
        var scratchpad_grid_owned = true;
        errdefer if (scratchpad_grid_owned) scratchpad_grid.deinit();
        try scratchpad_grid.attachAtlas(self.fonts.atlasPixels(), self.atlas);

        const record = try self.allocator.create(RemotePresentation);
        errdefer self.allocator.destroy(record);
        record.* = .{ .context = ssh_context, .connection_id = connection_id, .saved = restored };

        try self.workspace_presentations.ensureUnusedCapacity(self.allocator, 1);
        const presentation = try self.allocator.create(WorkspacePresentation);
        errdefer self.allocator.destroy(presentation);
        const key = try self.workspace_registry.insert(&candidate);
        candidate_owned = false;
        presentation.* = .{
            .key = key,
            .active_session_id = session_id,
            .pane_renderers = pane_renderers,
            .scratchpad_grid = scratchpad_grid,
            .remote = record,
        };
        scratchpad_grid_owned = false;
        self.workspace_presentations.appendAssumeCapacity(presentation);

        // A saved session waits for Enter or `reconnect`: connecting could
        // put a host-key or password prompt in front of someone who only
        // reopened the app.
        if (restored) return presentation;
        ssh_context.connect(pty.WindowSize.init(grid_size.rows, grid_size.cols)) catch |err| {
            log.warn("the ssh client could not be started: {s}", .{@errorName(err)});
        };
        record.state = ssh_context.state();
        return presentation;
    }

    /// Open an SSH workspace named after `base_name` connecting to
    /// `destination`, switch to it, and remember `recent_text` as the newest
    /// recent destination. Refusals are status lines.
    fn openRemoteWorkspace(
        self: *App,
        base_name: []const u8,
        destination: []const u8,
        port: ?u16,
        recent_text: []const u8,
    ) !bool {
        if (!ssh.supported) {
            self.setWorkspaceStatus("ssh workspaces are not supported here yet");
            return false;
        }
        if (self.closeModalActive() or self.paletteVisible() or !try self.prepareWorkspaceTransition()) return false;
        const name = try self.uniqueWorkspaceName(base_name);
        defer self.allocator.free(name);
        const presentation = self.createRemotePresentation(name, destination, port) catch |err| {
            log.warn("the ssh workspace could not be created: {s}", .{@errorName(err)});
            self.setRemoteStatus("ssh: could not start ({s})", .{@errorName(err)});
            return false;
        };
        try self.commitWorkspaceActivation(presentation.key, false);
        self.recordRecent(recent_text);
        const model = self.workspace_registry.byKey(presentation.key) orelse return true;
        const record = presentation.remote orelse return true;
        self.setRemoteStatus("ssh {s}: {s}", .{ model.name(), remote.stateWords(record.state) });
        return true;
    }

    /// Put `destination` first in `remote.recent`, dropping the oldest
    /// entries that no longer fit one settings value.
    fn recordRecent(self: *App, destination: []const u8) void {
        const path = self.config_path orelse return;
        _ = config.parseDestination(destination) catch return;
        var buffer: [config.max_string_bytes]u8 = undefined;
        const existing = self.config_current.settings.remote_recent;
        var keep = existing.len;
        const value = while (true) {
            break config.formatRecent(&buffer, destination, existing[0..keep]) catch {
                if (keep == 0) return;
                keep -= 1;
                continue;
            };
        };
        config.writeDocumentValue(self.io, self.allocator, path, .remote_recent, value) catch |err| {
            log.warn("the recent connection could not be saved: {s}", .{@errorName(err)});
            return;
        };
        self.reloadConfig();
    }

    /// Advance every SSH workspace: apply connection state changes, collect
    /// host probes and start owed respawns. Non-blocking; runs on the loop's
    /// poll and after the context's wake hook.
    fn pollRemote(self: *App) bool {
        if (comptime !ssh.supported) return false;
        var changed = false;
        for (self.workspace_presentations.items) |presentation| {
            const record = presentation.remote orelse continue;
            if (presentation.closing) continue;
            const model = self.workspace_registry.byKey(presentation.key) orelse continue;
            const next = record.context.poll();
            if (next != record.state) {
                record.state = next;
                self.remoteTransition(presentation, model, record);
                changed = true;
            }
            if (record.host_probe) |probe| {
                if (probe.finished()) {
                    if (probe.name_len != 0) {
                        @memcpy(record.remote_host[0..probe.name_len], probe.name[0..probe.name_len]);
                        record.remote_host_len = probe.name_len;
                    }
                    probe.destroy();
                    record.host_probe = null;
                    if (record.state == .connected) self.startRemoteSessions(presentation, model, record);
                    changed = true;
                }
            }
            if (record.ready() and self.driveRespawn(presentation, model, record)) changed = true;
        }
        return changed;
    }

    /// React to a new connection state: on `connected` hide the connection
    /// view and start (or restart) the remote sessions; otherwise the view is
    /// shown by `connectionVisible`. The active workspace's status line names
    /// every transition.
    fn remoteTransition(self: *App, presentation: *WorkspacePresentation, model: *workspace.Workspace, record: *RemotePresentation) void {
        if (record.state == .connected) {
            record.view_requested = false;
            if (record.host_probe == null and record.remote_host_len == 0) {
                record.host_probe = HostProbe.start(self.allocator, self.io, model.contextRef()) catch |err| probe: {
                    log.warn("could not ask the remote host its name: {s}", .{@errorName(err)});
                    break :probe null;
                };
            }
            if (record.host_probe == null) self.startRemoteSessions(presentation, model, record);
        }
        if (self.workspace_registry.activeKey() == presentation.key) {
            // The presented terminal changes: what was drawn under the
            // connection view (or over the panes) must be drawn again.
            self.composition.cancel();
            self.needs_present = true;
            self.setRemoteStatus("ssh {s}: {s}", .{ model.name(), remote.stateWords(record.state) });
        }
    }

    /// Start the sessions a ready connection owes: the first tab's shell and
    /// the scratchpad the first time, a respawn of every session the lost
    /// connection ended afterwards (decision-8: same id, last OSC 7 cwd).
    fn startRemoteSessions(self: *App, presentation: *WorkspacePresentation, model: *workspace.Workspace, record: *RemotePresentation) void {
        if (!record.ever_connected) {
            record.ever_connected = true;
            // A restored workspace's queue starts every saved shell in its
            // remote directory (`driveRestoreQueues`); only the scratchpad
            // is started here.
            if (presentation.restore_queue.items.len != 0) {
                self.startScratchpadFor(presentation, false);
                return;
            }
            if (model.tabAt(0)) |first| {
                const first_session = model.focusedPaneSessionId(first.id()) orelse first.sessionId();
                if (model.sessionById(first_session)) |live| {
                    if (live.child() == null) self.startPresentationChild(presentation, first_session, self.processFor(model, &self.spec));
                }
            }
            self.startScratchpadFor(presentation, false);
            return;
        }
        var ordinal: u32 = 0;
        while (ordinal < model.registeredSessionCount()) : (ordinal += 1) {
            const id = session.SessionId.fromOrdinal(ordinal);
            const kind = model.sessionKind(id) orelse continue;
            if (kind == .connection) continue;
            const live = model.sessionById(id) orelse continue;
            const child = live.child() orelse continue;
            const status = switch (child.state()) {
                .exited => |value| value,
                .running => continue,
            };
            // A session whose client ended with the connection is restarted;
            // one whose remote program ended by itself is left as it is.
            if (ssh.sessionEnd(status, false, false) != .disconnected) continue;
            const cwd = self.allocator.dupe(u8, live.workingDirectory() orelse "") catch |err| {
                log.warn("a session was not queued for reconnect: {s}", .{@errorName(err)});
                continue;
            };
            record.respawn.append(self.allocator, .{ .id = id, .cwd = cwd, .scratchpad = kind == .scratchpad }) catch |err| {
                self.allocator.free(cwd);
                log.warn("a session was not queued for reconnect: {s}", .{@errorName(err)});
            };
        }
    }

    /// Start queued respawns while the presentation's spawn slots are free.
    fn driveRespawn(self: *App, presentation: *WorkspacePresentation, model: *workspace.Workspace, record: *RemotePresentation) bool {
        var changed = false;
        var index: usize = 0;
        while (index < record.respawn.items.len) {
            const item = record.respawn.items[index];
            const busy = if (item.scratchpad) presentation.scratchpad_load != null else presentation.load != null;
            if (busy) {
                index += 1;
                continue;
            }
            _ = record.respawn.orderedRemove(index);
            self.startRespawn(presentation, model, item);
            changed = true;
        }
        return changed;
    }

    /// Spawn a fresh child for one ended session on a worker. Ownership of
    /// `item.cwd` transfers on entry.
    fn startRespawn(self: *App, presentation: *WorkspacePresentation, model: *workspace.Workspace, item: RespawnItem) void {
        var request = if (item.scratchpad)
            model.scratchpadRestartRequest(self.processFor(model, &self.scratchpad_spec)) catch |err| {
                log.warn("the scratchpad could not be restored: {s}", .{@errorName(err)});
                self.allocator.free(item.cwd);
                return;
            }
        else
            model.respawnRequest(item.id, self.processFor(model, &self.spec), item.cwd) catch |err| {
                log.warn("a session could not be restored: {s}", .{@errorName(err)});
                self.allocator.free(item.cwd);
                return;
            };
        request.cwd = item.cwd;
        const job = self.allocator.create(Load) catch |err| {
            log.warn("no memory to restore a session: {s}", .{@errorName(err)});
            self.allocator.free(item.cwd);
            return;
        };
        job.* = .{
            .allocator = self.allocator,
            .io = self.io,
            .spawn = request,
            .spawn_cwd = item.cwd,
            .spawn_session_id = item.id,
            .workspace_key = presentation.key,
            .scratchpad_replacement = item.scratchpad,
            .respawn = !item.scratchpad,
            .execution_context = model.contextRef(),
        };
        job.start(self.window) catch |err| {
            log.warn("could not start the worker that restores a session: {s}", .{@errorName(err)});
            job.freeSpawnInputs();
            self.allocator.destroy(job);
            return;
        };
        if (item.scratchpad) presentation.scratchpad_load = job else presentation.load = job;
    }

    // The connection manager (TASK-44) --------------------------------------

    /// Read concrete `Host` aliases from the user's ssh configuration
    /// through the Local context: `~/.ssh/config` (or `--ssh-test`'s file)
    /// and the files its `Include` lines name, one level deep. Key and
    /// known-hosts files are never read, whatever an `Include` says.
    fn readSshHosts(self: *App, hosts: *remote.Hosts) void {
        var path_buffer: [path_capacity]u8 = undefined;
        const main_path = self.ssh_config_override orelse path: {
            const home = self.home_dir orelse return;
            break :path std.fmt.bufPrint(&path_buffer, "{s}/.ssh/config", .{home}) catch return;
        };
        const buffer = self.allocator.alloc(u8, remote.max_config_bytes) catch return;
        defer self.allocator.free(buffer);
        const files = self.local_files.borrow();
        const text = files.readFile(self.io, main_path, buffer) catch |err| {
            if (err != error.NotFound) log.debug("the ssh configuration could not be read: {s}", .{@errorName(err)});
            return;
        };
        var includes: remote.Includes = .{};
        remote.parseHosts(text, hosts, &includes);
        const base_dir = std.fs.path.dirnamePosix(main_path) orelse return;
        var read_files: usize = 0;
        for (0..includes.count) |include_index| {
            var resolved_buffer: [path_capacity]u8 = undefined;
            const resolved = remote.resolveInclude(&resolved_buffer, includes.at(include_index), base_dir, self.home_dir) orelse continue;
            const dir = std.fs.path.dirnamePosix(resolved) orelse continue;
            const pattern = std.fs.path.basenamePosix(resolved);
            var matches: IncludeMatches = .{ .pattern = pattern };
            if (std.mem.indexOfAny(u8, pattern, "*?") != null) {
                files.listDir(self.io, dir, .{ .context = &matches, .visit_fn = IncludeMatches.visit }) catch continue;
                matches.sort();
            } else {
                matches.add(pattern);
            }
            for (0..matches.count) |match_index| {
                if (read_files == remote.max_include_files) return;
                const file_name = matches.at(match_index);
                if (!remote.mayReadConfigFile(file_name)) continue;
                var file_buffer: [path_capacity]u8 = undefined;
                const file_path = std.fmt.bufPrint(&file_buffer, "{s}/{s}", .{ dir, file_name }) catch continue;
                read_files += 1;
                const included = files.readFile(self.io, file_path, buffer) catch continue;
                remote.parseHosts(included, hosts, null);
            }
        }
    }

    /// Relist `remote.connect`'s choices: ssh-config hosts, saved profiles,
    /// recent destinations and the `user@host` row. Only while the palette is
    /// closed: an open chooser's rows are indices into this list.
    fn rebuildRemoteChoices(self: *App) void {
        if (self.paletteVisible()) return;
        var count: usize = 0;
        var hosts: remote.Hosts = .{};
        self.readSshHosts(&hosts);
        for (0..hosts.count) |index| {
            const alias = hosts.at(index);
            self.addRemoteChoice(&count, .{ .host = alias }, "{s}  ssh config", .{alias});
        }
        for (self.config_current.settings.remote_profiles) |profile| {
            self.addRemoteChoice(&count, .{ .profile = profile.name }, "{s}  {s}  profile", .{ profile.name, profile.destination });
        }
        for (self.config_current.settings.remote_recent) |destination| {
            self.addRemoteChoice(&count, .{ .recent = destination }, "{s}  recent", .{destination});
        }
        self.addRemoteChoice(&count, .address, "Enter user@host…", .{});
        self.remote_choice_count = count;
        self.action_definitions[self.remote_connect_index].palette = .{ .argument = .{ .choices = .{
            .name = "target",
            .prompt = "Connect to",
            .values = self.remote_choices[0..count],
        } } };
    }

    /// Relist the profile choosers (TASK-46) for the active workspace. Only
    /// while the palette is closed: an open chooser's rows index this list.
    fn rebuildProfileChoices(self: *App, profiles: []const config.ShellProfile) void {
        if (self.paletteVisible()) return;
        self.profile_choices.rebuild(self.io, self.process_env, self.activeWorkspace().contextRef(), profiles);
        for ([_]usize{ self.tab_profile_index, self.pane_profile_index }) |index| {
            self.action_definitions[index].palette = .{ .argument = .{ .choices = .{
                .name = "profile",
                .prompt = "Shell profile",
                .values = self.profile_choices.slice(),
            } } };
        }
    }

    /// The profile `name` resolves to in the active workspace: a configured
    /// one, else a built-in one detected for that workspace's context. The
    /// result borrows the config and `spawn_builtins` until the next call.
    fn resolveProfile(self: *App, name: []const u8) ?ResolvedProfile {
        detectBuiltins(&self.spawn_builtins, self.io, self.process_env, self.activeWorkspace().contextRef());
        return resolveNamedProfile(name, self.config_current.settings.shell_profiles, &self.spawn_builtins);
    }

    /// What a new tab or pane runs when none is chosen: the profile `shell`
    /// names, or null for the built-in default.
    fn defaultProfile(self: *App) ?ResolvedProfile {
        const name = self.config_current.settings.shell;
        if (name.len == 0) return null;
        return self.resolveProfile(name) orelse {
            log.debug("shell names no profile; the built-in default runs", .{});
            return null;
        };
    }

    /// The spec `profile` runs with in the active workspace.
    fn profileSpec(self: *App, profile: ResolvedProfile) !ChildSpec {
        return ChildSpec.buildProfile(
            self.allocator,
            self.io,
            self.process_env,
            self.activeWorkspace().contextKind(),
            profile,
            self.no_shell_integration,
            null,
        );
    }

    fn tabNewProfileAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const name = argument(invocation, "profile") orelse return self.openPaletteAt(self.tab_profile_index);
        const profile = self.resolveProfile(name) orelse {
            self.setWorkspaceStatus("profile: no profile with that name");
            return;
        };
        try self.openTab(profile.name, profile);
    }

    fn paneSplitProfileAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const name = argument(invocation, "profile") orelse return self.openPaletteAt(self.pane_profile_index);
        const profile = self.resolveProfile(name) orelse {
            self.setWorkspaceStatus("profile: no profile with that name");
            return;
        };
        try self.splitFocusedPane(.right, profile);
    }

    /// The directory a new terminal starts in: the profile's own, else the
    /// invoking terminal's tracked one, else the workspace's, as a spawn on
    /// this platform takes it. Owned by the caller.
    fn newTerminalCwd(self: *App, profile: ?ResolvedProfile) ![]u8 {
        if (profile) |chosen| if (chosen.cwd) |cwd| return self.allocator.dupe(u8, cwd);
        const inherited = self.activeLive().workingDirectory() orelse self.activeWorkspace().workingDirectory();
        var buffer: [path_capacity]u8 = undefined;
        const local = !self.activeWorkspace().contextKind().isRemote();
        return self.allocator.dupe(u8, if (local) spawnDirectory(&buffer, inherited, builtin.os.tag) else inherited);
    }

    fn addRemoteChoice(self: *App, count: *usize, choice: remote.Choice, comptime format: []const u8, args: anytype) void {
        if (count.* == remote_choice_capacity) return;
        const value = choice.format(&self.remote_choice_values[count.*]) catch return;
        const label = std.fmt.bufPrint(&self.remote_choice_labels[count.*], format, args) catch return;
        self.remote_choices[count.*] = .{ .label = label, .value = value };
        count.* += 1;
    }

    fn findProfile(self: *const App, name: []const u8) ?config.Profile {
        for (self.config_current.settings.remote_profiles) |profile| {
            if (std.mem.eql(u8, profile.name, name)) return profile;
        }
        return null;
    }

    /// Open the palette straight at one command's argument step.
    fn openPaletteAt(self: *App, definition_index: usize) !void {
        if (!self.paletteVisible()) try self.openPalette();
        if (!self.paletteVisible()) return;
        try self.beginPaletteArgument(definition_index);
    }

    fn remoteConnectAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const value = argument(invocation, "target") orelse return self.openPaletteAt(self.remote_connect_index);
        // Every slice below is copied first: saving a recent destination
        // reloads the settings that own profile and recent strings.
        var copy: [remote_choice_value_capacity]u8 = undefined;
        if (value.len > copy.len) return;
        @memcpy(copy[0..value.len], value);
        const choice = remote.Choice.parse(copy[0..value.len]) orelse {
            self.setWorkspaceStatus("ssh: unknown connection");
            return;
        };
        switch (choice) {
            .address => {
                if (invocation.source == .palette) {
                    try self.showPalette();
                    try self.beginPaletteArgument(self.remote_address_index);
                } else try self.openPaletteAt(self.remote_address_index);
            },
            .host => |alias| {
                if (!remote.concreteAlias(alias)) {
                    self.setWorkspaceStatus("ssh: not a host alias");
                    return;
                }
                _ = try self.openRemoteWorkspace(alias, alias, null, alias);
            },
            .profile => |name| {
                const profile = self.findProfile(name) orelse {
                    self.setWorkspaceStatus("ssh: no such profile");
                    return;
                };
                var destination_buffer: [config.max_string_bytes]u8 = undefined;
                const text = destination_buffer[0..profile.destination.len];
                @memcpy(text, profile.destination);
                const destination = config.parseDestination(text) catch {
                    self.setWorkspaceStatus("ssh: the profile's destination is not valid");
                    return;
                };
                _ = try self.openRemoteWorkspace(name, destination.target, destination.port, text);
            },
            .recent => |text| {
                const destination = config.parseDestination(text) catch {
                    self.setWorkspaceStatus("ssh: expected [user@]host[:port]");
                    return;
                };
                _ = try self.openRemoteWorkspace(config.destinationHost(destination), destination.target, destination.port, text);
            },
        }
    }

    fn remoteConnectAddressAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const supplied = argument(invocation, "destination") orelse return self.openPaletteAt(self.remote_address_index);
        const trimmed = std.mem.trim(u8, supplied, std.ascii.whitespace[0..]);
        if (trimmed.len > self.remote_pending_profile.len) {
            self.setWorkspaceStatus("ssh: expected [user@]host[:port]");
            return;
        }
        var copy: [config.max_string_bytes]u8 = undefined;
        const text = copy[0..trimmed.len];
        @memcpy(text, trimmed);
        const destination = config.parseDestination(text) catch {
            self.setWorkspaceStatus("ssh: expected [user@]host[:port]");
            return;
        };
        if (!try self.openRemoteWorkspace(config.destinationHost(destination), destination.target, destination.port, text)) return;
        // Offer to keep it: the same modal asks next (TASK-44 AC2).
        @memcpy(self.remote_pending_profile[0..text.len], text);
        self.remote_pending_profile_len = text.len;
        if (invocation.source == .palette) {
            try self.showPalette();
            try self.beginPaletteArgument(self.remote_save_index);
        }
    }

    fn remoteSaveProfileAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const answer = argument(invocation, "save") orelse return self.openPaletteAt(self.remote_save_index);
        defer self.remote_pending_profile_len = 0;
        if (!std.mem.eql(u8, answer, "yes")) return;
        var buffer: [config.max_string_bytes]u8 = undefined;
        const text = if (self.remote_pending_profile_len != 0)
            self.remote_pending_profile[0..self.remote_pending_profile_len]
        else active: {
            const record = self.activePresentation().remote orelse {
                self.setWorkspaceStatus("ssh: not an ssh workspace");
                return;
            };
            const target = record.context.destinationText();
            break :active if (record.context.portNumber()) |port|
                std.fmt.bufPrint(&buffer, "{s}:{d}", .{ target, port }) catch return
            else
                target;
        };
        const destination = config.parseDestination(text) catch {
            self.setWorkspaceStatus("ssh: expected [user@]host[:port]");
            return;
        };
        const name = config.destinationHost(destination);
        if (!config.validProfileName(name)) {
            self.setWorkspaceStatus("ssh: no usable profile name");
            return;
        }
        const path = self.config_path orelse {
            self.setWorkspaceStatus("ssh: no settings file for this run");
            return;
        };
        config.writeDocumentProfile(self.io, self.allocator, path, name, text) catch |err| {
            log.warn("the connection profile could not be saved: {s}", .{@errorName(err)});
            self.setWorkspaceStatus("ssh: the profile could not be saved");
            return;
        };
        self.reloadConfig();
        self.setRemoteStatus("ssh: saved profile {s}", .{name});
    }

    fn remoteReconnectAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        if (comptime !ssh.supported) return;
        const self: *App = @ptrCast(@alignCast(context));
        const presentation = self.activePresentation();
        const record = presentation.remote orelse {
            self.setWorkspaceStatus("ssh: not an ssh workspace");
            return;
        };
        switch (record.context.state()) {
            .connecting, .connected => {
                self.setRemoteStatus("ssh: {s}", .{remote.stateWords(record.context.state())});
                return;
            },
            .disconnected, .lost, .failed => {},
        }
        if (!try self.prepareToLeaveActiveSession()) return;
        const model = self.activeWorkspace();
        if (model.sessionById(record.connection_id)) |live| {
            // A clean screen, so the new master's prompts are the only ones.
            live.terminal().feed("\x1b[H\x1b[2J\x1b[3J");
            live.rearmChildOutput();
        }
        // Asked for: a restored session now behaves as any other.
        record.saved = false;
        record.context.reconnect() catch |err| {
            log.warn("the ssh client could not be restarted: {s}", .{@errorName(err)});
            self.setRemoteStatus("ssh: could not reconnect ({s})", .{@errorName(err)});
            return;
        };
        record.state = record.context.state();
        // A pointer activation focused the control; the next Enter belongs
        // to the prompt in the connection terminal.
        self.ui_tree.clearFocus();
        self.needs_present = true;
        self.setRemoteStatus("ssh {s}: {s}", .{ model.name(), remote.stateWords(record.state) });
        try self.refreshActiveUi();
    }

    fn remoteDisconnectAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        const record = self.activePresentation().remote orelse {
            self.setWorkspaceStatus("ssh: not an ssh workspace");
            return;
        };
        if (!try self.prepareToLeaveActiveSession()) return;
        record.context.hangUp();
        record.state = record.context.state();
        self.needs_present = true;
        self.setRemoteStatus("ssh {s}: {s}", .{ self.activeWorkspace().name(), remote.stateWords(record.state) });
        try self.refreshActiveUi();
    }

    fn remoteShowConnectionAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        const record = self.activePresentation().remote orelse {
            self.setWorkspaceStatus("ssh: not an ssh workspace");
            return;
        };
        if (record.state != .connected) return;
        if (!try self.prepareToLeaveActiveSession()) return;
        record.view_requested = !record.view_requested;
        self.composition.cancel();
        _ = takeCommittedText(&self.pending_committed_text);
        self.ui_tree.clearFocus();
        self.needs_present = true;
        try self.syncGrid();
        try self.syncTextInput();
        try self.composeUi();
        self.invalidateUi();
    }

    /// Compose the connection view over the terminal area: the header row
    /// (`workspace.<k>.connection`), the master's terminal surface, and the
    /// clickable `reconnect` or `hide` control on the header row.
    fn composeConnectionView(self: *App, layout: workspace.PaneLayout) !void {
        const presentation = self.activePresentation();
        const record = presentation.remote orelse return;
        const key = presentation.key;
        const header_y: u32 = layout.rect.row -| 1;
        const destination = record.context.destinationText();
        var port_text: [8]u8 = undefined;
        const port_suffix = if (record.context.portNumber()) |port|
            std.fmt.bufPrint(&port_text, ":{d}", .{port}) catch ""
        else
            "";
        const header = if (record.saved and record.state == .disconnected)
            std.fmt.bufPrint(&record.header_storage, "ssh {s}{s} ─ saved session; press Enter or click reconnect to connect", .{
                destination,
                port_suffix,
            }) catch "ssh ─ saved session"
        else
            std.fmt.bufPrint(&record.header_storage, "ssh {s}{s} ─ {s}", .{
                destination,
                port_suffix,
                remote.stateWords(record.state),
            }) catch "ssh";
        const header_id: ui.Id = .{ .value = try connectionSemanticId(&self.connection_semantic_storage[0], key, "") };
        // The painted header stops short of the control on its row, which a
        // long saved-session line would otherwise run under; the semantic
        // label keeps the whole line.
        const control_cells: u32 = switch (record.state) {
            .connecting => 0,
            .connected => "hide".len + 2,
            .lost, .failed, .disconnected => "reconnect".len + 2,
        };
        const painted = ellipsizeToCells(&record.header_paint_storage, header, layout.rect.cols -| control_cells);
        const header_runs = [_]ui.Run{.{
            .text = painted,
            .style = .{
                .foreground = switch (record.state) {
                    .lost, .failed => .danger,
                    .connecting => .accent,
                    .connected, .disconnected => .strong,
                },
                .background = .background,
            },
        }};
        try self.ui_tree.addText(.{
            .id = header_id,
            .role = "connection",
            .label = header,
            .bounds = .{ .x = layout.rect.col, .y = header_y, .width = layout.rect.cols, .height = 1 },
        }, .{ .runs = &header_runs });
        const terminal_bounds: ui.Rect = .{
            .x = layout.rect.col,
            .y = layout.rect.row,
            .width = layout.rect.cols,
            .height = layout.rect.rows,
        };
        try self.ui_tree.addSurface(.{
            .id = .{ .value = try connectionSemanticId(&self.connection_semantic_storage[1], key, "terminal") },
            .parent = header_id,
            .role = "terminal",
            .label = "Connection terminal",
            .bounds = terminal_bounds,
        }, .{ .rect = terminal_bounds, .fill = null });
        const control: ?struct { suffix: []const u8, label: []const u8, action: []const u8 } = switch (record.state) {
            .connecting => null,
            .connected => .{ .suffix = "hide", .label = "hide", .action = remote_show_connection_action },
            .lost, .failed, .disconnected => .{ .suffix = "reconnect", .label = "reconnect", .action = remote_reconnect_action },
        };
        if (control) |value| {
            const width: u32 = @intCast(value.label.len);
            if (layout.rect.cols > width + 2) {
                const id: ui.Id = .{ .value = try connectionSemanticId(&self.connection_semantic_storage[2], key, value.suffix) };
                try self.ui_tree.addInteractiveText(.{
                    .id = id,
                    .parent = header_id,
                    .role = "action",
                    .label = value.label,
                    .action = value.action,
                    .bounds = .{
                        .x = layout.rect.col + layout.rect.cols - width - 1,
                        .y = header_y,
                        .width = width,
                        .height = 1,
                    },
                }, .{
                    .id = id,
                    .label = value.label,
                    .action = value.action,
                    .normal = .{ .foreground = .accent, .background = .background },
                    .hovered = .{ .foreground = .strong, .background = .selection },
                    .focused = .{ .foreground = .on_accent, .background = .accent },
                });
            }
        }
    }

    // The choice step's filter (TASK-44 AC1) ---------------------------------

    /// Whether `definition_index`'s choice step filters as the person types.
    /// Only the connection manager does: its list can be long, and it is the
    /// one chooser whose rows a person searches by name.
    fn choiceStepFiltered(self: *const App, definition_index: usize) bool {
        return definition_index == self.remote_connect_index;
    }

    fn choiceFilterActive(self: *const App) bool {
        return switch (self.palette_step) {
            .choices => |step| self.choiceStepFiltered(step.definition_index),
            else => false,
        };
    }

    fn choiceValues(self: *const App, definition_index: usize) []const inputmod.PaletteChoice {
        const definition = self.actions.definitions()[definition_index];
        return switch (definition.palette.?.argument) {
            .choices => |choice_argument| choice_argument.values,
            else => &.{},
        };
    }

    /// Refilter the open choice step by `palette_argument`, best fuzzy match
    /// first (registration order among equals), and select the best match.
    fn refreshChoiceFilter(self: *App) void {
        const step = switch (self.palette_step) {
            .choices => |value| value,
            else => return,
        };
        const values = self.choiceValues(step.definition_index);
        const query = self.palette_argument.text();
        var scores: [remote_choice_capacity]i64 = undefined;
        var len: usize = 0;
        for (values, 0..) |choice, index| {
            if (index == remote_choice_capacity) break;
            const score: i64 = if (query.len == 0) 0 else palette_mod.fuzzyScore(query, choice.label) orelse continue;
            var at = len;
            while (at != 0 and scores[at - 1] < score) : (at -= 1) {
                scores[at] = scores[at - 1];
                self.choice_filter[at] = self.choice_filter[at - 1];
            }
            scores[at] = score;
            self.choice_filter[at] = index;
            len += 1;
        }
        self.choice_filter_len = len;
        self.palette_step = .{ .choices = .{
            .definition_index = step.definition_index,
            .selected = if (len != 0) self.choice_filter[0] else 0,
        } };
    }

    fn choiceFilterPosition(self: *const App, choice_index: usize) ?usize {
        for (self.choice_filter[0..self.choice_filter_len], 0..) |candidate, position| {
            if (candidate == choice_index) return position;
        }
        return null;
    }

    fn presentationByKey(self: *App, key: workspace.WorkspaceKey) ?*WorkspacePresentation {
        for (self.workspace_presentations.items) |presentation| {
            if (presentation.key == key) return presentation;
        }
        return null;
    }

    fn presentationByKeyConst(self: *const App, key: workspace.WorkspaceKey) ?*const WorkspacePresentation {
        for (self.workspace_presentations.items) |presentation| {
            if (presentation.key == key) return presentation;
        }
        return null;
    }

    fn activePresentation(self: *App) *WorkspacePresentation {
        const key = self.workspace_registry.activeKey() orelse unreachable;
        return self.presentationByKey(key) orelse unreachable;
    }

    fn activePresentationConst(self: *const App) *const WorkspacePresentation {
        const key = self.workspace_registry.activeKey() orelse unreachable;
        return self.presentationByKeyConst(key) orelse unreachable;
    }

    fn activeWorkspace(self: *App) *workspace.Workspace {
        return self.workspace_registry.active() orelse unreachable;
    }

    fn activeWorkspaceConst(self: *const App) *const workspace.Workspace {
        return @constCast(&self.workspace_registry).active() orelse unreachable;
    }

    fn activeLive(self: *App) *session.Session {
        const presentation = self.activePresentation();
        return self.activeWorkspace().sessionById(presentation.active_session_id) orelse unreachable;
    }

    fn activeLiveConst(self: *const App) *session.Session {
        const presentation = self.activePresentationConst();
        return @constCast(self.activeWorkspaceConst()).sessionById(presentation.active_session_id) orelse unreachable;
    }

    fn destroyLoad(self: *App, job: *Load) void {
        if (job.thread) |thread| {
            thread.join();
            job.thread = null;
        }
        if (job.child) |child| {
            destroyUnattachedChild(child);
            job.child = null;
        }
        if (job.fonts) |*fonts| {
            fonts.deinit();
            job.fonts = null;
        }
        if (job.small_fonts) |*fonts| {
            fonts.deinit();
            job.small_fonts = null;
        }
        job.freeSpawnInputs();
        self.allocator.destroy(job);
    }

    /// Give back everything the app owns, in the reverse of the order it was
    /// built. The window belongs to `main`, which outlives the app.
    fn deinit(self: *App) void {
        // What the person last saw is what the next launch restores; saved
        // before anything below starts taking the workspaces apart.
        self.saveStateAtExit();
        self.persistence.deinit();
        // No assistive technology may ask for anything while the tree goes.
        if (self.a11y) |bridge| bridge.deinit();
        self.a11y = null;
        // No control request may reach a workspace that is going away.
        self.stopControl();
        if (self.config_watcher) |watcher| watcher.stop();
        self.config_watcher = null;
        if (self.driver) |driver| {
            driver.stop();
            // SDL text-input events borrow the retained request bytes. Consume
            // every already-posted event before those arenas are released.
            while (self.window.pump(0) != null) {}
            driver.deinit();
            self.driver = null;
        }
        for (&self.driver_pending) |*slot| {
            if (slot.*) |*pending| pending.deinit(self.allocator);
            slot.* = null;
        }
        self.window.stopTextInput() catch |err| {
            log.warn("could not stop text input: {s}", .{@errorName(err)});
        };
        if (self.font_load) |job| self.destroyLoad(job);
        for (self.workspace_presentations.items) |presentation| {
            if (presentation.load) |job| self.destroyLoad(job);
            if (presentation.scratchpad_load) |job| self.destroyLoad(job);
        }
        // The prompts view's discovery borrows a workspace's context.
        if (self.prompts_job) |job| job.destroy();
        self.prompts_job = null;
        if (self.prompts_list) |*list| list.deinit();
        self.prompts_list = null;
        // Every spawn worker that could still be preparing an agent has been
        // joined above; the runtime's own workers stop here, before the
        // workspaces whose contexts its detections borrow.
        self.agents.deinit();
        self.agent_spec.deinit();
        // Host probes borrow their workspaces' contexts: joined before the
        // registry releases them below.
        for (self.workspace_presentations.items) |presentation| {
            self.releaseRemote(presentation);
            releaseBacklog(self.allocator, presentation);
        }
        self.remote_spec.deinit();
        self.ssh_client_spec.deinit();
        self.allocator.destroy(self.profile_choices);
        self.local_files.deinit();
        if (self.ssh_config_override) |path| self.allocator.free(path);
        if (self.ssh_runtime_owned) |path| self.allocator.free(path);
        self.stopSearchEngine();
        if (self.rename_input) |*field| field.deinit();
        self.search_query.deinit();
        self.settings_input.deinit();
        self.manager_input.deinit();
        for (&self.backlog_frames) |*frame| frame.deinit();
        self.palette_argument.deinit();
        self.palette_query.deinit();
        self.palette_model.deinit();
        self.spec.deinit();
        self.scratchpad_spec.deinit();
        if (self.pending_paste) |bytes| self.allocator.free(bytes);
        self.pending_child_bytes.deinit(self.allocator);
        self.ui_tree.deinit();
        self.ui_canvas.deinit();
        self.allocator.free(self.binding_keys);
        self.binding_table.deinit();
        self.config_current.deinit();
        if (self.config_path) |path| self.allocator.free(path);
        self.font_settings.deinit();
        self.allocator.free(self.action_definitions);
        self.allocator.destroy(self.theme_catalog);
        self.allocator.destroy(self.font_choices);
        self.overlay_grid.deinit();
        for (self.workspace_presentations.items) |presentation| {
            for (presentation.pane_renderers.items) |*pane_renderer| pane_renderer.deinit();
            presentation.pane_renderers.deinit(self.allocator);
            presentation.scratchpad_grid.deinit();
            presentation.releaseRestoreQueue(self.allocator);
            self.allocator.destroy(presentation);
        }
        self.workspace_presentations.deinit(self.allocator);
        self.dropGitTracks(null);
        self.git_tracks.deinit(self.allocator);
        self.workspace_registry.deinit() catch |err| {
            log.warn("could not signal a child during workspace shutdown: {s}", .{@errorName(err)});
        };
        self.allocator.free(self.pane_layouts);
        self.allocator.free(self.divider_layouts);
        if (self.small_fonts) |*small| small.deinit();
        self.fonts.deinit();
        self.allocator.free(self.input);
        self.allocator.free(self.output);
        self.allocator.free(self.readback);
        self.surface.deinit();
        // The adapters borrowed it until the runtime above released them.
        if (self.self_exe) |path| self.allocator.free(path);
        self.* = undefined;
    }

    /// Release the app's owned resources and its allocator-stable storage.
    fn destroy(self: *App) void {
        const allocator = self.allocator;
        self.deinit();
        allocator.destroy(self);
    }

    /// Start the child, on a worker, at the grid's size.
    ///
    /// A failure is a log line and a run with no child rather than a failed
    /// app: the window is open and the grid draws whatever the terminal has,
    /// and a machine with no shell to run is not a reason to crash.
    fn startChild(self: *App) void {
        if (self.spec.argv.len == 0) return;
        const presentation = self.activePresentation();
        self.startPresentationChild(presentation, presentation.active_session_id, .{
            .argv = self.spec.argv,
            .env = self.spec.env,
        });
    }

    fn startPresentationChild(
        self: *App,
        presentation: *WorkspacePresentation,
        session_id: session.SessionId,
        process: workspace.ProcessSpec,
    ) void {
        if (presentation.load != null) return;
        const model = self.workspace_registry.byKey(presentation.key) orelse unreachable;
        const control_env = self.controlEnvFor(presentation, model, session_id, process.env);
        var request = model.spawnRequest(session_id, process) catch |err| {
            log.warn("could not prepare the child session: {s}", .{@errorName(err)});
            if (control_env) |env| freeEntries(self.allocator, env);
            self.spawn_finished = true;
            return;
        };
        if (control_env) |env| request.env = env;
        const job = self.allocator.create(Load) catch |err| {
            log.warn("no memory to start a child process: {s}", .{@errorName(err)});
            if (control_env) |env| freeEntries(self.allocator, env);
            self.spawn_finished = true;
            return;
        };
        job.* = .{
            .allocator = self.allocator,
            .io = self.io,
            .spawn = request,
            .spawn_env = control_env,
            .spawn_session_id = session_id,
            .workspace_key = presentation.key,
            .execution_context = model.contextRef(),
        };
        job.start(self.window) catch |err| {
            log.warn("could not start the worker that spawns the child: {s}", .{@errorName(err)});
            job.freeSpawnInputs();
            self.allocator.destroy(job);
            self.spawn_finished = true;
            return;
        };
        presentation.load = job;
    }

    /// Start the reserved scratchpad, or spawn a transactional replacement,
    /// without occupying the ordinary tab/font worker slot.
    fn startScratchpad(self: *App, replacement: bool) void {
        const presentation = self.activePresentation();
        self.startScratchpadFor(presentation, replacement);
    }

    fn startScratchpadFor(self: *App, presentation: *WorkspacePresentation, replacement: bool) void {
        if (presentation.scratchpad_load != null) {
            log.warn("scratchpad start deferred while another scratchpad load is in flight", .{});
            return;
        }
        const model = self.workspace_registry.byKey(presentation.key) orelse unreachable;
        const process = self.processFor(model, &self.scratchpad_spec);
        const request = if (replacement)
            model.scratchpadRestartRequest(process) catch |err| {
                log.warn("could not prepare the scratchpad restart: {s}", .{@errorName(err)});
                return;
            }
        else
            model.spawnRequest(model.scratchpadId(), process) catch |err| {
                log.warn("could not prepare the scratchpad session: {s}", .{@errorName(err)});
                return;
            };
        const job = self.allocator.create(Load) catch |err| {
            log.warn("no memory to start the scratchpad: {s}", .{@errorName(err)});
            return;
        };
        job.* = .{
            .allocator = self.allocator,
            .io = self.io,
            .spawn = request,
            .spawn_session_id = model.scratchpadId(),
            .workspace_key = presentation.key,
            .scratchpad_replacement = replacement,
            .execution_context = model.contextRef(),
        };
        job.start(self.window) catch |err| {
            log.warn("could not start the scratchpad spawn worker: {s}", .{@errorName(err)});
            self.allocator.destroy(job);
            return;
        };
        presentation.scratchpad_load = job;
    }

    fn destroyUnattachedChild(child: pty.Pty) void {
        child.kill(.hangup) catch |kill_err| switch (kill_err) {
            error.Closed => {},
            else => log.warn("could not signal an unattached scratchpad child: {s}", .{@errorName(kill_err)}),
        };
        child.destroy();
    }

    /// Collect one workspace's scratchpad startup/restart without blocking the
    /// UI thread. Selection may have changed since this worker was started.
    fn pollScratchpadLoadFor(self: *App, presentation: *WorkspacePresentation) bool {
        const job = presentation.scratchpad_load orelse return false;
        if (!job.finished()) return false;
        if (job.thread) |thread| {
            thread.join();
            job.thread = null;
        }
        const model = self.workspace_registry.byKey(presentation.key) orelse {
            self.destroyLoad(job);
            presentation.scratchpad_load = null;
            return false;
        };
        if (job.workspace_key == null or job.workspace_key.? != presentation.key) {
            log.err("scratchpad worker result was attributed to the wrong workspace", .{});
            self.destroyLoad(job);
            presentation.scratchpad_load = null;
            return false;
        }
        if (presentation.closing) {
            self.destroyLoad(job);
            presentation.scratchpad_load = null;
            return true;
        }
        var changed = false;
        if (job.child) |child| {
            if (job.scratchpad_replacement) {
                const replaced = model.replaceScratchpad(child) catch |err| {
                    log.warn("scratchpad restart did not commit: {s}", .{@errorName(err)});
                    destroyUnattachedChild(child);
                    job.child = null;
                    job.freeSpawnInputs();
                    self.allocator.destroy(job);
                    presentation.scratchpad_load = null;
                    return false;
                };
                job.child = null;
                if (replaced.old_child_deinit_error) |err| {
                    log.warn("the old scratchpad could not be signalled cleanly after replacement: {s}", .{@errorName(err)});
                }
            } else {
                model.attachChild(model.scratchpadId(), child) catch |err| {
                    log.warn("could not attach the scratchpad child: {s}", .{@errorName(err)});
                    destroyUnattachedChild(child);
                    job.child = null;
                    job.freeSpawnInputs();
                    self.allocator.destroy(job);
                    presentation.scratchpad_load = null;
                    return false;
                };
                job.child = null;
            }
            if (model.sessionById(model.scratchpadId())) |scratchpad| {
                scratchpad.terminal().setClipboardAccess(.{
                    .read_fn = readNativeClipboard,
                    .write_fn = writeNativeClipboard,
                });
            }
            applyRemoteHost(presentation, model, model.scratchpadId());
            presentation.scratchpad_grid.invalidate();
            changed = true;
        }
        if (job.spawn_failure) |name| {
            log.warn("no scratchpad child process: {s}; the previous session remains available", .{name});
        }
        job.freeSpawnInputs();
        self.allocator.destroy(job);
        presentation.scratchpad_load = null;
        return changed;
    }

    fn pollScratchpadLoad(self: *App) bool {
        var changed = false;
        for (self.workspace_presentations.items) |presentation| {
            changed = self.pollScratchpadLoadFor(presentation) or changed;
        }
        return changed;
    }

    fn newPaneRenderer(self: *App, session_id: session.SessionId) !PaneRenderer {
        var grid = try render.Grid.init(self.allocator, gridColors(self.palette));
        errdefer grid.deinit();
        try grid.attachAtlas(self.fonts.atlasPixels(), self.atlas);
        return .{ .session_id = session_id, .grid = grid };
    }

    fn rendererForSession(self: *App, session_id: session.SessionId) ?*render.Grid {
        for (self.activePresentation().pane_renderers.items) |*record| {
            if (record.session_id == session_id) return &record.grid;
        }
        return null;
    }

    fn focusedGrid(self: *App) *render.Grid {
        return if (self.scratchpadVisible())
            &self.activePresentation().scratchpad_grid
        else
            self.rendererForSession(self.activePresentation().active_session_id) orelse &self.overlay_grid;
    }

    fn discardClosedPaneRenderers(self: *App) void {
        var index: usize = 0;
        while (index < self.activePresentation().pane_renderers.items.len) {
            const record = &self.activePresentation().pane_renderers.items[index];
            const connection = if (self.activePresentation().remote) |remote_record| remote_record.connection_id == record.session_id else false;
            if (connection or (self.activeWorkspace().paneForSession(record.session_id) != null and
                self.activeWorkspace().sessionById(record.session_id) != null))
            {
                index += 1;
                continue;
            }
            record.deinit();
            _ = self.activePresentation().pane_renderers.orderedRemove(index);
        }
    }

    /// Start one newly created tab from a cwd copied before selection changed.
    /// Ownership of `cwd` transfers on entry and remains with the Load until
    /// its worker has joined, including every failure path.
    fn startTabChild(self: *App, session_id: session.SessionId, cwd: []u8) void {
        self.startTabChildWith(session_id, cwd, null);
    }

    /// Start one newly created tab with `argv` owned by the job instead of the
    /// app-level child spec, or with that spec when `argv` is null. Ownership
    /// of `cwd` and `argv` transfers on entry and remains with the Load until
    /// its worker has joined, including every failure path.
    fn startTabChildWith(self: *App, session_id: session.SessionId, cwd: []u8, argv: ?[][]const u8) void {
        self.startTabChildProcess(session_id, cwd, argv, null);
    }

    /// `startTabChildWith`, with an owned environment (a profile's) in place
    /// of the app-level spec's when `owned_env` is not null. Ownership of
    /// `cwd`, `argv` and `owned_env` transfers on entry.
    fn startTabChildProcess(self: *App, session_id: session.SessionId, cwd: []u8, argv: ?[][]const u8, owned_env: ?[][]const u8) void {
        const presentation = self.activePresentation();
        const model = self.workspace_registry.byKey(presentation.key) orelse unreachable;
        const process = self.processFor(model, &self.spec);
        const program = argv orelse process.argv;
        const base_env: []const []const u8 = owned_env orelse process.env;
        // An empty program is "no child" locally and the remote login shell
        // in an SSH workspace.
        if (program.len == 0 and model.contextKind() != .ssh) {
            self.allocator.free(cwd);
            if (argv) |owned| freeEntries(self.allocator, owned);
            if (owned_env) |owned| freeEntries(self.allocator, owned);
            return;
        }
        if (presentation.load != null) {
            log.warn("a tab child was not started because another load is still in flight", .{});
            self.allocator.free(cwd);
            if (argv) |owned| freeEntries(self.allocator, owned);
            if (owned_env) |owned| freeEntries(self.allocator, owned);
            return;
        }
        var request = model.spawnRequest(session_id, .{
            .argv = program,
            .env = base_env,
        }) catch |err| {
            log.warn("could not prepare the new tab child: {s}", .{@errorName(err)});
            self.allocator.free(cwd);
            if (argv) |owned| freeEntries(self.allocator, owned);
            if (owned_env) |owned| freeEntries(self.allocator, owned);
            return;
        };
        request.cwd = cwd;
        const control_env = self.controlEnvFor(presentation, model, session_id, base_env);
        // The job owns exactly one environment: the control copy when there
        // is one (built from the profile's), else the profile's own.
        var spawn_env = owned_env;
        if (control_env) |env| {
            request.env = env;
            if (owned_env) |owned| freeEntries(self.allocator, owned);
            spawn_env = control_env;
        }
        const job = self.allocator.create(Load) catch |err| {
            log.warn("no memory to start the new tab child: {s}", .{@errorName(err)});
            self.allocator.free(cwd);
            if (argv) |owned| freeEntries(self.allocator, owned);
            if (spawn_env) |env| freeEntries(self.allocator, env);
            return;
        };
        job.* = .{
            .allocator = self.allocator,
            .io = self.io,
            .spawn = request,
            .spawn_cwd = cwd,
            .spawn_argv = argv,
            .spawn_env = spawn_env,
            .spawn_session_id = session_id,
            .workspace_key = presentation.key,
            .execution_context = model.contextRef(),
        };
        job.start(self.window) catch |err| {
            log.warn("could not start the worker for the new tab: {s}", .{@errorName(err)});
            job.freeSpawnInputs();
            self.allocator.destroy(job);
            return;
        };
        presentation.load = job;
    }

    /// Ask a worker for a face rasterised at the display scale the window is
    /// on now.
    ///
    /// A face rasterised for one scale is blurry on the next, so it has to be
    /// rasterised again rather than scaled up. The request is polled by the
    /// loop instead of waited on, so the frame that notices the window moved is
    /// not the frame that blocks on the scan.
    ///
    /// The face wanted is the committed settings with the font picker's
    /// previewed family, if any. A request for the face already drawn, or the
    /// one already being built, starts nothing, so a font command's own config
    /// reload and a preview that returns to the drawn family cost no rebuild.
    fn requestFontReload(self: *App) void {
        const wanted = self.wantedFontKey();
        if (self.font_load) |job| {
            // When the job lands, whatever is wanted then is requested again.
            self.font_reload_pending = job.font_key != wanted;
            if (self.font_reload_pending) log.debug("a load is already in flight; requesting again when it lands", .{});
            return;
        }
        self.font_reload_pending = false;
        if (wanted == self.font_loaded_key) return;
        const size = font.Size.init(self.font_settings.values.points, self.font_scale) catch |err| {
            log.err("a display scale of {d:.2} is not a usable font size: {s}", .{
                self.font_scale,
                @errorName(err),
            });
            return;
        };
        const job = self.allocator.create(Load) catch |err| {
            log.warn("no memory to re-load the font: {s}", .{@errorName(err)});
            return;
        };
        var values = self.font_settings.values;
        values.family = self.drawnFamily();
        const owned = FontSettings.init(self.allocator, values) catch |err| {
            log.warn("no memory to re-load the font: {s}", .{@errorName(err)});
            self.allocator.destroy(job);
            return;
        };
        // The request borrows the job's copy, whose strings live as long as
        // the job does, whatever happens to the app's settings meanwhile.
        job.* = .{
            .allocator = self.allocator,
            .io = self.io,
            .font_settings_owned = owned,
            .font_key = wanted,
            .font_request = owned.values.request(owned.values.family, size, self.home_dir),
            .small_font_request = smallFontRequest(owned.values.request(owned.values.family, size, self.home_dir)),
        };
        job.start(self.window) catch |err| {
            log.warn("could not start the worker that re-loads the font: {s}", .{@errorName(err)});
            job.freeSpawnInputs();
            self.allocator.destroy(job);
            return;
        };
        self.font_load = job;
        self.font_load_count += 1;
        log.info("re-loading the face ({s}, {d:.1} points) at display scale {d:.2}", .{
            if (values.family.len == 0) "bundled" else values.family,
            values.points,
            self.font_scale,
        });
    }

    /// Take whatever a finished job produced, and say whether the screen has to
    /// be redrawn as a result.
    fn pollPresentationLoad(self: *App, presentation: *WorkspacePresentation) bool {
        const job = presentation.load orelse return false;
        if (!job.finished()) return false;
        if (job.thread) |thread| {
            thread.join();
            job.thread = null;
        }
        const model = self.workspace_registry.byKey(presentation.key) orelse {
            self.destroyLoad(job);
            presentation.load = null;
            return false;
        };
        if (job.workspace_key == null or job.workspace_key.? != presentation.key) {
            log.err("child worker result was attributed to the wrong workspace", .{});
            self.destroyLoad(job);
            presentation.load = null;
            return false;
        }
        if (presentation.closing) {
            self.destroyLoad(job);
            presentation.load = null;
            return true;
        }
        if (job.child) |child| {
            const target_id = job.spawn_session_id orelse presentation.active_session_id;
            if (job.spawn_session_id != null and model.sessionById(target_id) == null) {
                // Closing a starting pane cannot cancel the worker synchronously.
                // Its eventual child is still ours and must be reaped instead of
                // being attached to a session that deliberately no longer exists.
                child.kill(.hangup) catch |kill_err| switch (kill_err) {
                    error.Closed => {},
                    else => log.warn("could not signal the canceled child: {s}", .{@errorName(kill_err)}),
                };
                child.destroy();
            } else if (job.respawn) {
                // A reconnect's restart: a fresh terminal and this child under
                // the session's existing id. On refusal the child is ours.
                if (model.replaceSessionChild(target_id, child)) |replaced| {
                    if (replaced.old_child_deinit_error) |err| log.debug("the ended child could not be signalled: {s}", .{@errorName(err)});
                    // A search over the old terminal must not outlive it.
                    if (self.search_engine_live and self.search_session_id == target_id and
                        self.workspace_registry.activeKey() == presentation.key) self.stopSearchEngine();
                    for (presentation.pane_renderers.items) |*pane_renderer| pane_renderer.grid.invalidate();
                    if (self.workspace_registry.activeKey() == presentation.key) self.needs_present = true;
                } else |err| {
                    log.warn("a restored session did not take its new child: {s}", .{@errorName(err)});
                    destroyUnattachedChild(child);
                }
            } else {
                model.attachChild(target_id, child) catch |err| {
                    // A spawn job exists only while this session has no child, so
                    // every failure for a session that still exists is an
                    // ownership invariant. The new handle is still ours on
                    // failure and must not leak or leave its process behind.
                    log.err("could not attach the spawned child: {s}", .{@errorName(err)});
                    child.kill(.hangup) catch |kill_err| switch (kill_err) {
                        error.Closed => {},
                        else => log.warn("could not signal the unattached child: {s}", .{@errorName(kill_err)}),
                    };
                    child.destroy();
                };
            }
            applyRemoteHost(presentation, model, target_id);
            job.child = null;
            if (model.sessionById(target_id)) |target| if (target.child() != null) {
                // The grid may have changed while the worker was spawning; the
                // child must draw for the grid it has now, not the one it was
                // requested with.
                if (job.spawn) |request| target.syncChildSize(request.size) catch |err| {
                    log.warn("could not tell the new child its window size: {s}", .{@errorName(err)});
                };
                const grid = target.terminal().gridSize();
                log.info("child started, window {d}x{d} cells", .{ grid.cols, grid.rows });
                if (!self.first_child_logged) {
                    self.first_child_logged = true;
                    self.logStartupPhase("first child");
                }
            };
        }
        if (job.spawn != null) self.spawn_finished = true;
        if (job.spawn_failure) |name| {
            log.warn("no child process: {s}; the terminal stays empty", .{name});
        }
        if (job.agent_runner) |runner| {
            const started = if (job.spawn_session_id) |id|
                (if (model.sessionById(id)) |target| target.child() != null else false)
            else
                false;
            self.agents.spawnFinished(runner, started);
            self.invalidateUi();
        }
        if (job.spawn_session_id) |id| {
            const started = if (model.sessionById(id)) |target| target.child() != null else false;
            self.controlSpawnFinished(presentation.key, id, started);
        }
        job.freeSpawnInputs();
        self.allocator.destroy(job);
        presentation.load = null;
        return false;
    }

    fn pollFontLoad(self: *App) bool {
        const job = self.font_load orelse return false;
        if (!job.finished()) return false;
        if (job.thread) |thread| {
            thread.join();
            job.thread = null;
        }
        var changed = false;
        var landed = false;
        if (job.fonts) |fonts| {
            self.fonts.deinit();
            self.fonts = fonts;
            job.fonts = null;
            // The face was rasterised for the request's scale, and so was its
            // atlas: every grid takes the size it was built with (TASK-67).
            if (job.font_request) |request| self.atlas = atlasSizeFor(request.size.scale);
            for (self.workspace_presentations.items) |presentation| {
                for (presentation.pane_renderers.items) |*pane_renderer| {
                    pane_renderer.grid.attachAtlas(self.fonts.atlasPixels(), self.atlas) catch |err| log.err("the new face could not be uploaded: {s}", .{@errorName(err)});
                }
                presentation.scratchpad_grid.attachAtlas(self.fonts.atlasPixels(), self.atlas) catch |err| log.err("the new scratchpad face could not be uploaded: {s}", .{@errorName(err)});
            }
            self.overlay_grid.attachAtlas(self.fonts.atlasPixels(), self.atlas) catch |err| log.err("the new overlay face could not be uploaded: {s}", .{@errorName(err)});
            // The small face follows the main one; without a new one the old
            // size would be wrong, so a failed build drops it and small text
            // draws at the normal size until the next load.
            if (self.small_fonts) |*small| small.deinit();
            self.small_fonts = job.small_fonts;
            job.small_fonts = null;
            if (self.small_fonts) |*small| {
                self.overlay_grid.attachSmallAtlas(small.atlasPixels(), small_atlas, small.metrics()) catch |err| {
                    log.err("the new small face could not be uploaded: {s}", .{@errorName(err)});
                    small.deinit();
                    self.small_fonts = null;
                };
            }
            log.info("now drawing with {s}, {d}x{d}px cells", .{
                self.fonts.familyName(),
                self.fonts.metrics().cell.width_px,
                self.fonts.metrics().cell.height_px,
            });
            self.font_loaded_key = job.font_key;
            // The ligature setting may have changed while the face was built.
            self.fonts.setLigatures(self.font_settings.values.ligatures);
            self.syncGrid() catch |err| {
                log.warn("the grid could not be resized for the new face: {s}", .{@errorName(err)});
            };
            landed = true;
            changed = true;
        } else if (job.font_failure != null) {
            // The previous manager stays: the screen keeps drawing with the
            // face it had, and the setting that asked for this one is named.
            self.font_diagnostic = .{
                .line = @max(self.config_current.lines.get(.font_family), self.config_current.lines.get(.font_size)),
                .message = "font: the configured face could not be loaded; keeping the previous face",
            };
            changed = true;
        }
        if (job.font_failure) |name| log.warn("the font could not be loaded: {s}", .{name});
        job.freeSpawnInputs();
        self.allocator.destroy(job);
        self.font_load = null;
        if (landed) {
            self.font_diagnostic = null;
            self.refreshFontDiagnostic();
        }
        if (changed) {
            self.refreshConfigError();
            self.invalidateUi();
        }
        if (self.font_reload_pending) {
            self.font_reload_pending = false;
            self.requestFontReload();
        }
        return changed;
    }

    fn pollLoad(self: *App) bool {
        var changed = self.pollFontLoad();
        for (self.workspace_presentations.items) |presentation| {
            changed = self.pollPresentationLoad(presentation) or changed;
        }
        return changed;
    }

    /// Bring the surface, the grid and the readback buffer to the size a window
    /// state implies, rebuilding only what actually moved.
    fn syncSurface(self: *App, state: platform.State) !void {
        const wanted = surfaceSize(state);
        if (!wanted.eql(self.size)) {
            try self.surface.resize(wanted);
            self.size = wanted;
            try self.growReadback();
            try self.syncGrid();
        }
        if (state.scale.factor != self.font_scale) {
            self.font_scale = state.scale.factor;
            self.requestFontReload();
        }
        // A resize or a scale change that lands on the size already in use still
        // invalidates: the window moved, and what is on screen has to be
        // redrawn even though the texture did not change.
        self.scheduler.invalidate();
        self.needs_present = true;
    }

    /// Fit the grid to the surface with the face the app is drawing with.
    fn syncGrid(self: *App) !void {
        const canvas_size = try gridSizeFor(self.fonts.metrics().cell, self.size);
        const origin = sidebarColumns(canvas_size.cols, self.sidebar_width_cols, self.sidebar_visible);
        const canvas_bounds = self.ui_canvas.bounds();
        if (canvas_bounds.width != canvas_size.cols or canvas_bounds.height != canvas_size.rows) {
            try self.ui_canvas.resize(canvas_size.cols, canvas_size.rows);
        }
        // Scratchpad geometry is independent of whether the workspace has a
        // currently layoutable tab. A tiny sidebar or a transient empty tab
        // must not leave the presented PTY at the previous dock size.
        if (self.scratchpadInnerRect()) |inner| {
            if (self.scratchpadLive()) |scratchpad| {
                const wanted = try term.GridSize.init(@intCast(inner.width), @intCast(inner.height));
                const current = scratchpad.terminal().gridSize();
                if (wanted.cols != current.cols or wanted.rows != current.rows) {
                    try scratchpad.resize(wanted);
                    self.noteSearchTerminalChange(self.activeWorkspace().scratchpadId());
                }
            }
        }
        self.pane_layout_count = 0;
        self.divider_layout_count = 0;
        if (self.connectionVisible()) {
            // The connection view: one terminal below a header row, in place
            // of every pane, until the master is connected (TASK-43).
            const record = self.activeRemote().?;
            const connection_cols = canvas_size.cols -| origin;
            if (connection_cols == 0 or canvas_size.rows < 2) return;
            const rect = workspace.CellRect.init(origin, 1, connection_cols, canvas_size.rows - 1) catch return;
            self.pane_layouts[0] = .{
                .pane_id = connection_pane_id,
                .session_id = record.connection_id,
                .rect = rect,
                .focused = true,
            };
            self.pane_layout_count = 1;
            const live = self.activeWorkspace().sessionById(record.connection_id) orelse return;
            const wanted = try term.GridSize.init(rect.cols, rect.rows);
            const current = live.terminal().gridSize();
            if (wanted.cols != current.cols or wanted.rows != current.rows) {
                try live.resize(wanted);
                self.noteSearchTerminalChange(record.connection_id);
            }
            return;
        }
        const tab_id = self.activeWorkspace().activeTabId() orelse return;
        const terminal_cols = canvas_size.cols -| origin;
        if (terminal_cols == 0 or canvas_size.rows == 0) return;
        const bounds = workspace.CellRect.init(origin, 0, terminal_cols, canvas_size.rows) catch return;
        self.pane_layout_count = self.activeWorkspace().layoutPanes(
            tab_id,
            bounds,
            self.pane_layouts,
        ) catch |err| switch (err) {
            error.InvalidGeometry => return,
            else => return err,
        };
        self.divider_layout_count = self.activeWorkspace().layoutDividers(
            tab_id,
            bounds,
            self.divider_layouts,
        ) catch |err| switch (err) {
            error.InvalidGeometry => 0,
            else => return err,
        };
        for (self.pane_layouts[0..self.pane_layout_count]) |layout| {
            const live = self.activeWorkspace().sessionById(layout.session_id) orelse continue;
            const wanted = try term.GridSize.init(layout.rect.cols, layout.rect.rows);
            const current = live.terminal().gridSize();
            if (wanted.cols != current.cols or wanted.rows != current.rows) {
                try live.resize(wanted);
                self.noteSearchTerminalChange(layout.session_id);
            }
        }
    }

    fn terminalCellBounds(self: *const App) ?workspace.CellRect {
        const bounds = self.ui_canvas.bounds();
        const origin = self.sidebarOriginColumns();
        const total_cols = std.math.cast(u16, bounds.width) orelse return null;
        const rows = std.math.cast(u16, bounds.height) orelse return null;
        const cols = total_cols -| origin;
        if (cols == 0 or rows == 0) return null;
        return workspace.CellRect.init(origin, 0, cols, rows) catch null;
    }

    fn focusedPaneLayout(self: *const App) ?workspace.PaneLayout {
        const target = if (self.connectionVisible())
            self.activeRemote().?.connection_id
        else
            self.activePresentationConst().active_session_id;
        for (self.pane_layouts[0..self.pane_layout_count]) |layout| {
            if (layout.session_id == target) return layout;
        }
        return null;
    }

    fn scratchpadVisible(self: *const App) bool {
        return self.activePresentationConst().scratchpad_presentation != .hidden;
    }

    fn scratchpadLive(self: *App) ?*session.Session {
        return self.activeWorkspace().sessionById(self.activeWorkspace().scratchpadId());
    }

    fn scratchpadLiveConst(self: *const App) ?*const session.Session {
        const model = self.activeWorkspaceConst();
        return @constCast(model).sessionById(model.scratchpadId());
    }

    /// The bottom-docked outer box in terminal cells. A tiny surface cannot
    /// contain a one-cell border and a terminal, so it has no presentation.
    fn scratchpadBounds(self: *const App) ?ui.Rect {
        if (!self.scratchpadVisible()) return null;
        const canvas = self.ui_canvas.bounds();
        if (canvas.width < 3 or canvas.height < 3) return null;
        const percent: u32 = switch (self.activePresentationConst().scratchpad_presentation) {
            .hidden => 0,
            .fifty => self.scratchpad_percent_small,
            .ninety => self.scratchpad_percent_large,
        };
        const wanted = (canvas.height * percent + 99) / 100;
        const height = @min(canvas.height, @max(@as(u32, 3), wanted));
        return .{
            .x = 0,
            .y = canvas.height - height,
            .width = canvas.width,
            .height = height,
        };
    }

    fn scratchpadInnerRect(self: *const App) ?ui.Rect {
        const outer = self.scratchpadBounds() orelse return null;
        return .{
            .x = outer.x + 1,
            .y = outer.y + 1,
            .width = outer.width - 2,
            .height = outer.height - 2,
        };
    }

    fn paletteVisible(self: *const App) bool {
        return self.palette_step != .closed;
    }

    fn contextMenuVisible(self: *const App) bool {
        return self.context_menu != null;
    }

    fn contextMenuBoundsNow(self: *const App) ?ui.Rect {
        const menu = self.context_menu orelse return null;
        var storage: [context_menu_max_items]ContextMenuItem = undefined;
        const items = contextMenuItems(menu.has_selection, menu.linkId() != null, &storage);
        return contextMenuBounds(menu.col, menu.row, items.len, self.ui_canvas.bounds());
    }

    /// The menu is a `Surface` panel of `InteractiveText` rows registered once
    /// in the one semantic tree. It erases the terminal cells beneath it so
    /// the rows read as a panel rather than as text over text.
    fn composeContextMenu(self: *App) !void {
        const menu = self.context_menu orelse return;
        var storage: [context_menu_max_items]ContextMenuItem = undefined;
        const items = contextMenuItems(menu.has_selection, menu.linkId() != null, &storage);
        const bounds = contextMenuBounds(menu.col, menu.row, items.len, self.ui_canvas.bounds()) orelse return;
        const menu_id: ui.Id = .{ .value = "context-menu" };
        try self.ui_tree.addSurface(.{
            .id = menu_id,
            .role = "menu",
            .label = "Terminal context menu",
            .bounds = bounds,
        }, .{
            .rect = bounds,
            .erase_underlay = true,
            .fill = .background,
            .border = .single,
            .border_style = .{ .foreground = .border, .background = .background },
        });
        for (items, 0..) |item, index| {
            const id: ui.Id = .{ .value = item.id };
            try self.ui_tree.addInteractiveText(.{
                .id = id,
                .parent = menu_id,
                .role = "menu_item",
                .label = item.label,
                .action = item.action,
                .bounds = .{
                    .x = bounds.x + 2,
                    .y = bounds.y + 1 + @as(u32, @intCast(index)),
                    .width = bounds.width - 4,
                    .height = 1,
                },
            }, .{
                .id = id,
                .label = item.label,
                .action = item.action,
                .normal = .{ .foreground = .foreground, .background = .background },
                .hovered = .{ .foreground = .strong, .underline = .accent, .background = .background },
                .focused = .{ .foreground = .on_accent, .background = .accent },
            });
        }
    }

    /// Open the menu anchored at a canvas cell. `link_id` borrows the current
    /// semantic frame and is copied before that frame is rebuilt. Nothing
    /// opens over another modal surface or while a gesture is in flight.
    fn openContextMenu(self: *App, col: u32, row: u32, link_id: ?[]const u8) !void {
        if (self.contextMenuVisible() or self.notificationsVisible() or self.paletteVisible() or self.settingsVisible() or self.closeModalActive() or
            self.managerVisible() or self.promptsVisible() or self.rename_tab_id != null or self.search_visible or self.scratchpadVisible() or
            self.backlogShown() or self.ui_pointer_owned or self.sidebar_dragging or self.dragged_divider_id != null or
            self.dragged_tab_id != null) return;
        var menu: ContextMenu = .{
            .col = col,
            .row = row,
            .has_selection = self.presentedLive().terminal().hasSelection(),
        };
        if (link_id) |id| {
            if (id.len <= menu.link_id.len) {
                @memcpy(menu.link_id[0..id.len], id);
                menu.link_id_len = id.len;
            }
        }
        var storage: [context_menu_max_items]ContextMenuItem = undefined;
        const items = contextMenuItems(menu.has_selection, menu.linkId() != null, &storage);
        if (contextMenuBounds(col, row, items.len, self.ui_canvas.bounds()) == null) return;
        self.composition.cancel();
        _ = takeCommittedText(&self.pending_committed_text);
        try self.window.stopTextInput();
        self.context_menu = menu;
        self.ui_tree.clearFocus();
        try self.composeUi();
        if (self.ui_tree.focus(.{ .value = items[0].id })) try self.composeUi();
        try self.syncTextInput();
        self.invalidateUi();
    }

    /// Open the menu from the keyboard at the focused pane's cursor cell, so the
    /// keyboard path lands where the user is working rather than at a stale
    /// pointer. A link under that cell gets its `open link` row too.
    fn openContextMenuAtCursor(self: *App) !void {
        if (self.terminal_pointer_presses != 0 or self.context_menu_pointer_owned) return;
        const layout = self.focusedPaneLayout() orelse return;
        const cursor = self.presentedLive().terminal().cursor();
        const position = cursor.position orelse term.Position{ .col = 0, .row = 0 };
        const col = @as(u32, layout.rect.col) + @min(@as(u32, position.col), @as(u32, layout.rect.cols) -| 1);
        const row = @as(u32, layout.rect.row) + @min(@as(u32, position.row), @as(u32, layout.rect.rows) -| 1);
        const cell = self.fonts.metrics().cell;
        const point: ui.Point = .{
            .x = @intCast(col * cell.width_px + cell.width_px / 2),
            .y = @intCast(row * cell.height_px + cell.height_px / 2),
        };
        const link_id: ?[]const u8 = if (self.ui_tree.hitTest(point)) |hit|
            (if (isTerminalLink(hit)) hit.id.value else null)
        else
            null;
        try self.openContextMenu(col, row, link_id);
    }

    fn closeContextMenu(self: *App) !void {
        if (!self.contextMenuVisible()) return;
        self.context_menu = null;
        self.ui_tree.clearFocus();
        try self.composeUi();
        try self.syncTextInput();
        self.invalidateUi();
    }

    /// Move the highlighted row with wrap-around. Rows are addressed by stable
    /// id through the tree's own focus, so the keyboard path and the mouse
    /// path highlight the same element.
    fn moveContextMenuFocus(self: *App, next: bool) !void {
        const menu = self.context_menu orelse return;
        var storage: [context_menu_max_items]ContextMenuItem = undefined;
        const items = contextMenuItems(menu.has_selection, menu.linkId() != null, &storage);
        var current: ?usize = null;
        if (self.ui_tree.focusedElement()) |focused| {
            for (items, 0..) |item, index| {
                if (std.mem.eql(u8, item.id, focused.id.value)) current = index;
            }
        }
        const target = if (current) |index|
            if (next) (index + 1) % items.len else (index + items.len - 1) % items.len
        else if (next) 0 else items.len - 1;
        if (self.ui_tree.focus(.{ .value = items[target].id })) try self.refreshActiveUi();
    }

    /// Run one row: close the menu first, because every row's action composes
    /// a new frame, then dispatch the row's completed named action with the
    /// arguments or origin that action already understands.
    fn activateContextMenuItem(self: *App, activation: ui.Activation, source: inputmod.InvocationSource) !void {
        const menu = self.context_menu orelse return;
        if (!std.mem.startsWith(u8, activation.id.value, "context-menu.")) return;
        var id_storage: [palette_semantic_capacity]u8 = undefined;
        if (activation.id.value.len > id_storage.len) return;
        @memcpy(id_storage[0..activation.id.value.len], activation.id.value);
        const row_id = id_storage[0..activation.id.value.len];
        var link_storage: [terminal_link_semantic_capacity]u8 = undefined;
        const link_len = menu.link_id_len;
        @memcpy(link_storage[0..link_len], menu.link_id[0..link_len]);
        try self.closeContextMenu();

        if (std.mem.eql(u8, row_id, context_menu_split_right_item.id)) {
            const args = [_]inputmod.Argument{.{ .name = "direction", .value = "right" }};
            try self.dispatchAction(pane_split_action, .{ .source = source, .arguments = &args });
        } else if (std.mem.eql(u8, row_id, context_menu_split_down_item.id)) {
            const args = [_]inputmod.Argument{.{ .name = "direction", .value = "down" }};
            try self.dispatchAction(pane_split_action, .{ .source = source, .arguments = &args });
        } else if (std.mem.eql(u8, row_id, context_menu_open_link_item.id)) {
            if (link_len == 0) return;
            try self.dispatchAction(terminal_open_link_action, .{
                .source = source,
                .origin = .{ .value = link_storage[0..link_len] },
            });
        } else if (std.mem.eql(u8, row_id, context_menu_copy_item.id)) {
            try self.dispatchAction(clipboard_copy_action, .{ .source = source });
        } else if (std.mem.eql(u8, row_id, context_menu_paste_item.id)) {
            try self.dispatchAction(clipboard_paste_action, .{ .source = source });
        } else if (std.mem.eql(u8, row_id, context_menu_search_item.id)) {
            try self.dispatchAction(search_open_action, .{ .source = source });
        }
    }

    /// A right press on the focused terminal that the program has not captured
    /// (CONDUIT.md: Shift overrides a program's mouse capture). Returns false
    /// when the press is the program's and must become a mouse report as before.
    fn handleTerminalRightPress(self: *App, point: ui.Point, hit: *const ui.Element, mods: platform.Mods) !bool {
        if (self.presentedLive().terminal().pointerOwner(inputmod.pointerMods(mods)) == .program) return false;
        self.context_menu_pointer_owned = true;
        switch (self.right_click) {
            .paste => {
                try self.dispatchAction(clipboard_paste_action, .{ .source = .mouse });
                // A consumed UI gesture skips the per-event flush, and a paste
                // must not wait for the next unrelated event to reach the child.
                try self.flushToChild();
            },
            .menu => {
                const cell = self.fonts.metrics().cell;
                const col: u32 = if (point.x <= 0) 0 else @as(u32, @intCast(point.x)) / cell.width_px;
                const row: u32 = if (point.y <= 0) 0 else @as(u32, @intCast(point.y)) / cell.height_px;
                const link_id: ?[]const u8 = if (isTerminalLink(hit)) hit.id.value else null;
                try self.openContextMenu(col, row, link_id);
            },
        }
        return true;
    }

    /// The context menu is modal like the palette: pointer gestures inside it
    /// focus or activate its own rows, a press outside closes it, and every
    /// gesture is owned through release so nothing underneath fires.
    fn handleContextMenuUiEvent(self: *App, event: platform.Event) !bool {
        const tree = self.activeUiTree();
        switch (event) {
            .mouse_motion => |motion| {
                const point = devicePointerPoint(motion.x, motion.y, self.window.state.scale);
                const before = uiInteractionState(tree);
                tree.pointerMoved(point);
                if (!std.meta.eql(before, uiInteractionState(tree))) try self.refreshActiveUi();
                return true;
            },
            .mouse_button => |button| {
                const point = devicePointerPoint(button.x, button.y, self.window.state.scale);
                const bounds = self.contextMenuBoundsNow();
                const inside = bounds != null and self.pointInCellRect(point, bounds.?);
                switch (button.action) {
                    .press => {
                        self.context_menu_pointer_owned = true;
                        if (!inside) {
                            try self.closeContextMenu();
                            return true;
                        }
                        if (button.button != .left) return true;
                        const before = uiInteractionState(tree);
                        tree.pointerPressed(point);
                        if (!std.meta.eql(before, uiInteractionState(tree))) try self.refreshActiveUi();
                        return true;
                    },
                    .repeat => return true,
                    .release => {
                        if (!self.context_menu_pointer_owned) return true;
                        self.context_menu_pointer_owned = false;
                        if (button.button != .left) return true;
                        const before = uiInteractionState(tree);
                        const activation = tree.pointerReleased(point);
                        if (!std.meta.eql(before, uiInteractionState(tree))) try self.refreshActiveUi();
                        if (activation) |requested| try self.activateContextMenuItem(requested, .mouse);
                        return true;
                    },
                }
            },
            .wheel => return true,
            .text_input, .key => return false,
            .text_editing, .candidates => return true,
            else => return false,
        }
    }

    // Agents and notifications (TASK-56) ------------------------------------

    /// Wake the loop from an agent worker: events are waiting in a queue.
    fn agentWake(context: ?*anyopaque) void {
        const self: *App = @ptrCast(@alignCast(context.?));
        self.window.postDriverWake() catch |err| {
            log.debug("could not wake the event loop for agent events: {s}", .{@errorName(err)});
        };
    }

    /// The OS notification seam of a hidden (headless) run: nothing reaches
    /// the desktop.
    fn discardOsNotification(_: ?*anyopaque, _: []const u8, _: []const u8) void {}

    /// The agent runtime's look into one session (observed agents, TASK-56):
    /// its binding, its context and the foreground process of its PTY. Null
    /// once the session or its child is gone.
    fn agentSessionFacts(context: ?*anyopaque, key: workspace.WorkspaceKey, id: session.SessionId, buffer: []u8) ?app_agents.SessionFacts {
        const self: *App = @ptrCast(@alignCast(context.?));
        const model = self.workspace_registry.byKey(key) orelse return null;
        const live = model.sessionById(id) orelse return null;
        const child = live.child() orelse return null;
        return .{
            .binding = .{ .workspace = key, .session = id, .session_kind = live.kind(), .scratchpad = model.scratchpadId() },
            .context_kind = model.contextRef().kind(),
            .process = child.foregroundProcess(buffer),
            .home = self.home_dir,
            .claude_config_dir = self.claude_config_dir,
            .codex_home = self.codex_home,
        };
    }

    /// `--agent-test`'s private directory: the parent of the sink root.
    fn agentTestDir(self: *const App) ?[]const u8 {
        const root = self.agents.sink_root orelse return null;
        return std.fs.path.dirnamePosix(root);
    }

    fn windowFocused(self: *const App) bool {
        return self.focus_override orelse self.window_focused;
    }

    /// Start finding the active workspace's harnesses, once per workspace.
    fn ensureAgentDetection(self: *App) void {
        self.startAgentDetection(true);
    }

    /// Resolve where a remote workspace keeps agent sinks without probing
    /// its harnesses: what checks that offer only the fake still need before
    /// an agent can launch there (TASK-61). Nothing for a Local workspace.
    fn ensureRemoteAgentSetup(self: *App) void {
        if (self.activeWorkspace().contextKind() == .local) return;
        self.startAgentDetection(false);
    }

    /// A remote workspace is probed only once connected: a probe through a
    /// context that is still connecting would only find nothing.
    fn startAgentDetection(self: *App, probe_harnesses: bool) void {
        const key = self.workspace_registry.activeKey() orelse return;
        const model = self.workspace_registry.byKey(key) orelse return;
        if (self.activePresentation().remote) |record| if (!record.ready()) return;
        self.agents.ensureDetection(key, model.contextRef(), self.agent_spec.env, probe_harnesses);
    }

    /// A fixed-choice command; an empty list shows its one placeholder row,
    /// whose value no handler accepts, so the step says why nothing can run.
    fn agentChoiceCommand(name: []const u8, prompt: []const u8, values: []const inputmod.PaletteChoice) inputmod.PaletteCommand {
        const shown = if (values.len != 0) values else if (std.mem.eql(u8, name, "harness")) &no_harness_choices else &no_agent_choices;
        return .{ .argument = .{ .choices = .{ .name = name, .prompt = prompt, .values = shown } } };
    }

    /// Point `agent.launch` at the active workspace's detected harnesses.
    /// Only while the palette is closed: an open picker's rows are indices.
    fn setAgentLaunchChoices(self: *App) void {
        if (self.paletteVisible()) return;
        const key = self.workspace_registry.activeKey() orelse return;
        self.action_definitions[self.agent_launch_index].palette = agentChoiceCommand("harness", "Launch agent", self.agents.launchChoices(key));
    }

    /// The tab name a session is shown under, if it is in a tab.
    fn sessionTabName(self: *App, key: workspace.WorkspaceKey, id: session.SessionId) ?[]const u8 {
        const model = self.workspace_registry.byKey(key) orelse return null;
        const location = model.paneForSession(id) orelse return null;
        const tab = model.tab(location.tab_id) orelse return null;
        return tab.name();
    }

    /// Relist the agents `agent.stop` and `agent.focus` offer. Never the
    /// scratchpad: the registry refuses to bind an agent there.
    fn rebuildAgentChoices(self: *App) void {
        if (self.paletteVisible()) return;
        var count: usize = 0;
        for (self.agents.registry.all()) |*record| {
            if (count == agent_choice_capacity) break;
            const value = std.fmt.bufPrint(&self.agent_choice_values[count], "{d}", .{@intFromEnum(record.id)}) catch continue;
            const workspace_name = if (self.workspace_registry.byKey(record.workspace)) |model| model.name() else "?";
            const label = std.fmt.bufPrint(&self.agent_choice_labels[count], "{s} {s} #{d}  {s} › {s}", .{
                app_agents.stateGlyph(record.state),
                self.agents.displayName(record),
                @intFromEnum(record.id),
                workspace_name,
                self.sessionTabName(record.workspace, record.session) orelse "(closed)",
            }) catch value;
            self.agent_choices[count] = .{ .label = label, .value = value };
            count += 1;
        }
        self.agent_choice_count = count;
        const choices = self.agent_choices[0..count];
        self.action_definitions[self.agent_stop_index].palette = agentChoiceCommand("agent", "Stop agent", choices);
        self.action_definitions[self.agent_focus_index].palette = agentChoiceCommand("agent", "Focus agent", choices);
    }

    fn agentByArgument(self: *App, invocation: inputmod.Invocation) ?*const agent.Agent {
        const text = argument(invocation, "agent") orelse return null;
        const raw = std.fmt.parseInt(u64, text, 10) catch return null;
        if (raw == 0) return null;
        return self.agents.registry.get(@enumFromInt(raw));
    }

    /// The first harness this workspace can launch, for a prompt typed
    /// before any harness was chosen.
    fn firstAgentChoice(self: *App) ?app_agents.Choice {
        const key = self.workspace_registry.activeKey() orelse return null;
        const choices = self.agents.launchChoices(key);
        self.setAgentLaunchChoices();
        if (choices.len == 0) return null;
        return app_agents.Choice.parse(choices[0].value);
    }

    fn agentLaunchAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const value = argument(invocation, "harness") orelse return;
        const choice = app_agents.Choice.parse(value) orelse {
            self.setWorkspaceStatus("no coding agent found here");
            return;
        };
        if (choice == .fake and !self.agents.fake_enabled) return;
        if (invocation.source == .palette) {
            // The palette asks for the optional prompt next, in the same
            // modal; Enter on an empty field launches without one.
            self.agent_launch_pending = choice;
            try self.showPalette();
            try self.beginPaletteArgument(self.agent_prompt_index);
            return;
        }
        try self.launchAgent(choice, argument(invocation, "prompt"));
    }

    fn agentLaunchPromptAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const pending = self.agent_launch_pending;
        self.agent_launch_pending = null;
        const choice = pending orelse self.agent_last_choice orelse self.firstAgentChoice() orelse {
            self.setWorkspaceStatus("no coding agent found here");
            return;
        };
        try self.launchAgent(choice, argument(invocation, "prompt"));
    }

    /// Launch `choice` in a new tab of the active workspace: an
    /// `agent_terminal` session, its agent registered, and the adapter's
    /// process spawned through the workspace's ExecutionContext in the
    /// invoking session's cwd. Refusals are status lines, never errors.
    fn launchAgent(self: *App, choice: app_agents.Choice, prompt: ?[]const u8) !void {
        return self.launchAgentWith(choice, prompt, .{});
    }

    /// Where and for what an agent starts beyond `agent.launch`'s defaults.
    const AgentLaunchOptions = struct {
        /// The agent's cwd instead of the active session's; borrowed.
        cwd: ?[]const u8 = null,
        /// The backlog task it works on (TASK-64); borrowed, copied by the
        /// runner.
        task_id: ?[]const u8 = null,
    };

    fn launchAgentWith(self: *App, choice: app_agents.Choice, prompt: ?[]const u8, options: AgentLaunchOptions) !void {
        const presentation = self.activePresentation();
        if (presentation.load != null) {
            self.setWorkspaceStatus("agent launch deferred: a start is in progress");
            return;
        }
        if (self.remoteNotReady()) return;
        // A remote workspace's sink root comes from its detection, which a
        // launch starts if nothing asked yet (TASK-61).
        self.ensureRemoteAgentSetup();
        if (!try self.prepareToLeaveActiveSession()) return;
        const key = presentation.key;
        const model = self.activeWorkspace();
        const inherited = options.cwd orelse self.activeLive().workingDirectory() orelse model.workingDirectory();
        const cwd = try self.allocator.dupe(u8, inherited);
        var cwd_owned = true;
        defer if (cwd_owned) self.allocator.free(cwd);

        try presentation.pane_renderers.ensureUnusedCapacity(self.allocator, 1);
        const expected_session = session.SessionId.fromOrdinal(@intCast(model.registeredSessionCount()));
        var pane_renderer = try self.newPaneRenderer(expected_session);
        var renderer_owned = true;
        errdefer if (renderer_owned) pane_renderer.deinit();
        const session_id = try model.createSession(.agent_terminal, self.activeLive().terminal().gridSize());
        var session_owned = true;
        errdefer if (session_owned) model.closeSession(session_id) catch |err| log.warn("an agent session could not be released: {s}", .{@errorName(err)});

        const runner = self.agents.createRunner(.{
            .choice = choice,
            .workspace = key,
            .session = session_id,
            .context_kind = model.contextKind(),
            .context = model.contextRef(),
            .cwd = cwd,
            .prompt = prompt,
            .probe_env = self.agent_spec.env,
            .home = self.home_dir,
            .claude_config_dir = self.claude_config_dir,
            .codex_home = self.codex_home,
            .task_id = options.task_id,
        }) catch |err| {
            self.setWorkspaceStatus(switch (err) {
                error.NoSinkRoot => if (model.contextKind() == .local)
                    "no private state directory for the agent"
                else
                    "the remote host's state directory is not known yet; try again",
                error.OutOfMemory => "out of memory",
            });
            pane_renderer.deinit();
            renderer_owned = false;
            session_owned = false;
            model.closeSession(session_id) catch |close_err| log.warn("an agent session could not be released: {s}", .{@errorName(close_err)});
            return;
        };
        var runner_owned = true;
        errdefer if (runner_owned) self.agents.discard(runner);
        const label = switch (choice) {
            .harness => |harness| harness.displayName(),
            .fake => "Fake agent",
        };
        const tab_id = try model.registerTab(label, session_id);
        _ = try self.agents.register(runner, .{
            .workspace = key,
            .session = session_id,
            .session_kind = .agent_terminal,
            .scratchpad = model.scratchpadId(),
        });
        try model.activateTab(tab_id);
        pane_renderer.session_id = session_id;
        presentation.pane_renderers.appendAssumeCapacity(pane_renderer);
        renderer_owned = false;
        session_owned = false;
        runner_owned = false;
        self.agent_last_choice = choice;
        try self.adoptActiveTab();
        cwd_owned = false;
        self.startAgentChild(session_id, cwd, runner);
        self.rebuildAgentChoices();
        self.invalidateUi();
    }

    /// `startTabChildWith` for an agent: the job carries the runner whose
    /// `prepare` describes the process on the worker. Takes `cwd`.
    fn startAgentChild(self: *App, session_id: session.SessionId, cwd: []u8, runner: *app_agents.Runner) void {
        const presentation = self.activePresentation();
        const model = self.workspace_registry.byKey(presentation.key) orelse unreachable;
        self.startAgentChildIn(presentation, model, session_id, cwd, runner, false);
    }

    /// `startAgentChild` for any workspace's presentation. With `respawn`
    /// the session's ended child is replaced under the same id, as a
    /// TASK-58 restart needs; otherwise the session is still starting.
    /// Takes `cwd`.
    fn startAgentChildIn(
        self: *App,
        presentation: *WorkspacePresentation,
        model: *workspace.Workspace,
        session_id: session.SessionId,
        cwd: []u8,
        runner: *app_agents.Runner,
        respawn: bool,
    ) void {
        const process: workspace.ProcessSpec = .{
            .argv = &agent_placeholder_argv,
            .env = self.agent_spec.env,
        };
        const prepared: anyerror!pty.SpawnRequest = if (respawn)
            model.respawnRequest(session_id, process, cwd)
        else
            model.spawnRequest(session_id, process);
        var request = prepared catch |err| {
            log.warn("could not prepare the agent's child: {s}", .{@errorName(err)});
            self.allocator.free(cwd);
            self.agents.spawnFinished(runner, false);
            return;
        };
        request.cwd = cwd;
        // The agent's hooks report through the endpoint (TASK-60); the
        // adapter's `prepare` merges its own variables over these.
        const control_env = self.controlEnvFor(presentation, model, session_id, process.env);
        if (control_env) |env| request.env = env;
        const job = self.allocator.create(Load) catch |err| {
            log.warn("no memory to start the agent's child: {s}", .{@errorName(err)});
            self.allocator.free(cwd);
            if (control_env) |env| freeEntries(self.allocator, env);
            self.agents.spawnFinished(runner, false);
            return;
        };
        job.* = .{
            .allocator = self.allocator,
            .io = self.io,
            .spawn = request,
            .spawn_cwd = cwd,
            .spawn_env = control_env,
            .spawn_session_id = session_id,
            .workspace_key = presentation.key,
            .respawn = respawn,
            .execution_context = model.contextRef(),
            .agent_runner = runner,
        };
        runner.spawning = true;
        job.start(self.window) catch |err| {
            log.warn("could not start the worker for the agent: {s}", .{@errorName(err)});
            job.freeSpawnInputs();
            self.allocator.destroy(job);
            self.agents.spawnFinished(runner, false);
            return;
        };
        presentation.load = job;
    }

    fn agentStopAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const record = self.agentByArgument(invocation) orelse return;
        const key = record.workspace;
        const id = record.session;
        switch (record.ownership) {
            // Conduit ends an agent it launched by hanging up its PTY child;
            // the exit then arrives like any other and settles the glyph.
            .owned => self.hangUpAgent(record),
            // A human's own process is never ended: stop only observing it.
            .observed => self.agents.sessionClosed(key, id),
        }
        self.rebuildAgentChoices();
        self.invalidateUi();
    }

    fn agentFocusAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const record = self.agentByArgument(invocation) orelse return;
        const id = record.id;
        try self.focusSession(record.workspace, record.session);
        self.agents.selected_agent = id;
    }

    /// Show one session: its workspace, then the tab and pane that hold it.
    fn focusSession(self: *App, key: workspace.WorkspaceKey, id: session.SessionId) !void {
        if (!try self.activateWorkspaceKey(key, false)) return;
        const model = self.activeWorkspace();
        const location = model.paneForSession(id) orelse return;
        if (model.activeTabId() == location.tab_id and model.focusedPaneId(location.tab_id) == location.pane_id) {
            try self.refreshActiveUi();
            return;
        }
        if (!try self.prepareToLeaveActiveSession()) return;
        try model.focusPane(location.tab_id, location.pane_id);
        try model.activateTab(location.tab_id);
        try self.adoptActiveTab();
    }

    /// Owner-thread agent service, once per loop iteration: drain the
    /// workers' queues, record exits and forget agents whose session closed.
    fn pollAgents(self: *App) bool {
        const now = Io.Clock.awake.now(self.io).nanoseconds;
        self.agents.focused = self.windowFocused();
        var changed = self.agents.poll(now);
        sweep: while (true) {
            for (self.agents.registry.all()) |record| {
                const model = self.workspace_registry.byKey(record.workspace);
                const live = if (model) |owner| owner.sessionById(record.session) else null;
                const present = live orelse {
                    self.agents.sessionClosed(record.workspace, record.session);
                    changed = true;
                    continue :sweep;
                };
                if (record.hasExited()) continue;
                // A restart's runner is spawning into a session whose old
                // child already ended; that exit is not the new agent's.
                if (self.agents.runnerForAgent(record.id)) |runner| if (runner.spawning) continue;
                const child = present.child() orelse continue;
                switch (child.state()) {
                    .running => {},
                    .exited => |status| {
                        self.agents.childExited(record.workspace, record.session, agentExitStatus(status), now);
                        changed = true;
                        continue :sweep;
                    },
                }
            }
            break;
        }
        if (self.agents.poll(now)) changed = true;
        if (changed) {
            self.setAgentLaunchChoices();
            self.rebuildAgentChoices();
        }
        return changed;
    }

    fn agentExitStatus(status: pty.ExitStatus) agent.ExitStatus {
        return switch (status) {
            .code => |code| .{ .code = @intCast(@min(code, 255)) },
            .signal => |signal| .{ .signal = switch (signal) {
                .hangup => 1,
                .interrupt => 2,
                .terminate => 15,
                .kill => 9,
            } },
            .unknown => .{ .signal = 0 },
        };
    }

    /// Output from a session is activity for its agent's heuristics.
    fn noteAgentOutput(self: *App, key: workspace.WorkspaceKey, id: session.SessionId) void {
        const now = Io.Clock.awake.now(self.io).nanoseconds;
        self.agents.observe(key, id, .{ .output = .{ .now_ns = monotonicNs(now) } }, now);
    }

    /// Route one terminal event to its agent's heuristics, or, for a session
    /// without an agent, raise a terminal notification: OSC 9/777 from any
    /// session, a bell only from one the human is not looking at.
    fn noteAgentTerminalEvent(self: *App, key: workspace.WorkspaceKey, id: session.SessionId, event: term.Event) void {
        const now = Io.Clock.awake.now(self.io).nanoseconds;
        const has_agent = self.agents.hasAgent(key, id);
        switch (event) {
            .title => if (has_agent) self.agents.observe(key, id, .{ .title = .{ .now_ns = monotonicNs(now) } }, now),
            .bell => if (has_agent) {
                self.agents.observe(key, id, .bell, now);
            } else if (!self.sessionVisible(key, id)) {
                var body_buffer: [tab_name_capacity + 32]u8 = undefined;
                const body = std.fmt.bufPrint(&body_buffer, "{s} rang the bell", .{self.sessionTabName(key, id) orelse "a terminal"}) catch "a terminal rang the bell";
                self.agents.raiseTerminal(key, id, "Bell", body);
            },
            .notification => |n| if (has_agent) {
                self.agents.observe(key, id, .{ .notification = .{ .title = n.title, .body = n.body, .truncated = n.truncated } }, now);
            } else {
                self.agents.raiseTerminal(key, id, n.title, n.body);
            },
            .prompt => |mark| if (has_agent) switch (mark.kind) {
                .output_start => self.agents.observe(key, id, .{ .command_started = .{ .now_ns = monotonicNs(now) } }, now),
                .prompt_start => self.agents.observe(key, id, .shell_prompt, now),
                .input_start, .command_end => {},
            },
            .permission_request, .working_directory, .reset => {},
        }
    }

    /// Whether a session is in the tab the human is looking at.
    fn sessionVisible(self: *App, key: workspace.WorkspaceKey, id: session.SessionId) bool {
        const active_key = self.workspace_registry.activeKey() orelse return false;
        if (active_key != key) return false;
        // The presented session includes a shown scratchpad, which has no tab.
        if (id == self.presentedSessionId()) return true;
        const model = self.workspace_registry.byKey(key) orelse return false;
        const location = model.paneForSession(id) orelse return false;
        return model.activeTabId() == location.tab_id;
    }

    fn monotonicNs(now: i96) u64 {
        if (now <= 0) return 0;
        return @intCast(@min(now, std.math.maxInt(u64)));
    }

    // The notification list --------------------------------------------------

    // The agent view (TASK-57) ------------------------------------------------

    /// The runner of the agent in the presented pane, view shown or not.
    fn presentedAgentRunner(self: *App) ?*app_agents.Runner {
        if (self.scratchpadVisible() or self.connectionVisible()) return null;
        return self.agents.runnerForSession(self.activePresentation().key, self.presentedSessionId());
    }

    /// The runner whose view replaces the presented pane's terminal.
    fn presentedAgentView(self: *App) ?*app_agents.Runner {
        const runner = self.presentedAgentRunner() orelse return null;
        return if (runner.view.active) runner else null;
    }

    /// The runner whose view replaces `id`'s terminal in the active workspace.
    fn agentViewForSession(self: *App, id: session.SessionId) ?*app_agents.Runner {
        const runner = self.agents.runnerForSession(self.activePresentation().key, id) orelse return null;
        return if (runner.view.active and runner.agent_id != null) runner else null;
    }

    /// The pane layout showing `runner`'s view, if one does.
    fn agentViewLayout(self: *App, runner: *const app_agents.Runner) ?workspace.PaneLayout {
        if (runner.workspace != self.activePresentation().key) return null;
        for (self.pane_layouts[0..self.pane_layout_count]) |layout| {
            if (layout.pane_id == connection_pane_id) continue;
            if (layout.session_id == runner.session) return layout;
        }
        return null;
    }

    fn agentViewRect(layout: workspace.PaneLayout) ui.Rect {
        return .{ .x = layout.rect.col, .y = layout.rect.row, .width = layout.rect.cols, .height = layout.rect.rows };
    }

    /// Where a view's event rows go: below its prompts row (TASK-59) when
    /// the pane has room for both, else the whole pane.
    fn agentViewRowsRect(layout: workspace.PaneLayout) ui.Rect {
        var rect = agentViewRect(layout);
        if (rect.height >= 2) {
            rect.y += 1;
            rect.height -= 1;
        }
        return rect;
    }

    /// The view and pane under a device-pixel point, when the point is over a
    /// pane that shows an agent view.
    fn agentViewAt(self: *App, point: ui.Point) ?struct { runner: *app_agents.Runner, layout: workspace.PaneLayout } {
        for (self.pane_layouts[0..self.pane_layout_count]) |layout| {
            if (layout.pane_id == connection_pane_id) continue;
            if (!self.pointInCellRect(point, agentViewRect(layout))) continue;
            const runner = self.agentViewForSession(layout.session_id) orelse return null;
            return .{ .runner = runner, .layout = layout };
        }
        return null;
    }

    /// The row and cell a point names inside a view, clamped to its rows.
    fn agentViewPosition(self: *const App, view: *const agent_view.View, rect: ui.Rect, point: ui.Point) agent_view.Position {
        const cell = self.fonts.metrics().cell;
        const x: u32 = if (point.x <= 0) 0 else @intCast(point.x);
        const y: u32 = if (point.y <= 0) 0 else @intCast(point.y);
        const col = std.math.clamp(x / @max(cell.width_px, 1), rect.x, rect.right()) - rect.x;
        const line = std.math.clamp(y / @max(cell.height_px, 1), rect.y, rect.bottom() -| 1) - rect.y;
        const last = view.rowCount() -| 1;
        return .{ .row = @min(view.top + line, last), .col = col };
    }

    /// Reserve the next id and target slot for a view element this frame.
    fn nextAgentViewId(self: *App, comptime format: []const u8, args: anytype, target: ?AgentViewTarget) ?[]const u8 {
        const generation = self.agent_view_generation;
        const slot = self.agent_view_used[generation];
        if (slot >= agent_view_element_capacity) return null;
        const text = std.fmt.bufPrint(&self.agent_view_ids[generation][slot], format, args) catch return null;
        self.agent_view_targets[generation][slot] = .{ .len = @intCast(text.len), .target = target };
        self.agent_view_used[generation] += 1;
        return text;
    }

    /// What a view element id addresses, from this frame or the one before.
    fn agentViewTarget(self: *const App, id: []const u8) ?AgentViewTarget {
        const current = self.agent_view_generation;
        for ([_]usize{ current, 1 - current }) |generation| {
            for (0..self.agent_view_used[generation]) |slot| {
                const entry = self.agent_view_targets[generation][slot];
                const target = entry.target orelse continue;
                if (std.mem.eql(u8, self.agent_view_ids[generation][slot][0..entry.len], id)) return target;
            }
        }
        return null;
    }

    fn agentViewRole(tone: agent_view.Tone) theme.Role {
        return switch (tone) {
            .normal => .foreground,
            .user => .accent,
            .assistant => .green,
            .system => .muted,
            .tool => .cyan,
            .reference => .blue,
            .attention => .attention,
            .dim => .muted,
            .success => .green,
            .danger => .danger,
        };
    }

    /// The painted runs of one row: its prefix and body tones, with the
    /// selected cells on the selection background. At most four runs.
    fn agentViewRuns(row: *const agent_view.Row, selected: ?agent_view.Selection, row_index: usize, out: *[4]ui.Run) []const ui.Run {
        const text = row.text;
        if (text.len == 0) return out[0..0];
        var cuts: [4]usize = .{ 0, row.prefix_len, text.len, text.len };
        var cut_count: usize = 2;
        if (selected) |selection| {
            if (selection.columnsOn(row_index, agent_view.displayCells(text))) |columns| {
                cuts[2] = agent_view.byteAtCell(text, columns.start);
                cuts[3] = agent_view.byteAtCell(text, columns.end);
                cut_count = 4;
            }
        }
        var bounds: [6]usize = undefined;
        bounds[0] = 0;
        bounds[1] = text.len;
        var bound_count: usize = 2;
        for (cuts[1..cut_count]) |cut| {
            if (cut == 0 or cut >= text.len) continue;
            if (std.mem.indexOfScalar(usize, bounds[0..bound_count], cut) != null) continue;
            bounds[bound_count] = cut;
            bound_count += 1;
        }
        std.mem.sort(usize, bounds[0..bound_count], {}, std.sort.asc(usize));
        var count: usize = 0;
        for (bounds[0 .. bound_count - 1], bounds[1..bound_count]) |start, end| {
            if (count == out.len) break;
            const in_selection = cut_count == 4 and start >= cuts[2] and end <= cuts[3];
            const tone = if (start < row.prefix_len) row.prefix_tone else row.tone;
            out[count] = .{ .text = text[start..end], .style = .{
                .foreground = if (in_selection) .strong else agentViewRole(tone),
                .background = if (in_selection) .selection else null,
                .face_style = if (start < row.prefix_len and row.kind == .message) .bold else .regular,
            } };
            count += 1;
        }
        return out[0..count];
    }

    /// A harness id as part of a semantic id, or null when it cannot be one
    /// (whitespace, controls or too long); the caller then names the element
    /// by its log position instead.
    fn agentViewIdPart(text: []const u8) ?[]const u8 {
        if (text.len == 0 or text.len > 40) return null;
        _ = ui.Id.parse(text) catch return null;
        return text;
    }

    /// Register one agent view over `layout`: a surface hiding the terminal,
    /// then one element per visible row (TASK-57).
    fn composeAgentView(self: *App, layout: workspace.PaneLayout, runner: *app_agents.Runner, pane_id: ui.Id) !void {
        const agent_id = runner.agent_id orelse return;
        const record = self.agents.registry.get(agent_id) orelse return;
        const number = @intFromEnum(agent_id);
        const pane_rect = agentViewRect(layout);
        const rect = agentViewRowsRect(layout);
        if (rect.width == 0 or rect.height == 0) return;
        const view = &runner.view;
        if (view.rows.stale(&view.log, rect.width)) {
            var name_buffer: [32]u8 = undefined;
            const speaker = agent_view.speakerName(&name_buffer, self.agents.displayName(record));
            try view.rows.build(&view.log, rect.width, speaker);
            if (view.selection) |selection| {
                const last = view.rowCount() -| 1;
                if (selection.anchor.row > last or selection.caret.row > last) view.selection = null;
            }
            if (self.search_view == agent_id) self.findAgentViewMatches(runner, false);
        }
        view.settle(rect.height);

        const surface_text = self.nextAgentViewId("agent.view.{d}", .{number}, null) orelse return;
        const surface_id: ui.Id = .{ .value = surface_text };
        try self.ui_tree.addSurface(.{
            .id = surface_id,
            .parent = pane_id,
            .role = "agent_view",
            .label = "Agent view",
            .bounds = pane_rect,
        }, .{ .rect = pane_rect, .fill = .background });
        // TASK-59: the way to the agent's prompts and instruction files.
        if (pane_rect.height >= 2) {
            const prompts_text = self.nextAgentViewId("agent.view.{d}.prompts", .{number}, null) orelse return;
            const prompts_id: ui.Id = .{ .value = prompts_text };
            const label = agent_view.prompts_row_label;
            try self.ui_tree.addInteractiveText(.{
                .id = prompts_id,
                .parent = surface_id,
                .role = "button",
                .label = label,
                .action = agent_prompts_action,
                .bounds = .{ .x = pane_rect.x, .y = pane_rect.y, .width = @min(agent_view.displayCells(label), pane_rect.width), .height = 1 },
            }, .{
                .id = prompts_id,
                .label = label,
                .action = agent_prompts_action,
                .normal = .{ .foreground = .muted },
                .hovered = .{ .foreground = .strong, .underline = .accent },
                .focused = .{ .foreground = .on_accent, .background = .accent },
            });
        }

        if (view.rowCount() == 0) {
            // A harness with no structured channel yet (or a quiet one) has
            // nothing to show; say where the session is instead of a blank.
            const empty_label = "· no structured events yet; the terminal has the full session";
            const empty_runs = [_]ui.Run{.{ .text = empty_label, .style = .{ .foreground = .muted } }};
            const id_text = self.nextAgentViewId("agent.view.{d}.empty", .{number}, null) orelse return;
            try self.ui_tree.addText(.{
                .id = .{ .value = id_text },
                .parent = surface_id,
                .role = "agent_row",
                .label = empty_label,
                .bounds = .{ .x = rect.x, .y = rect.y, .width = rect.width, .height = 1 },
            }, .{ .runs = &empty_runs });
            return;
        }
        const answerable = record.capabilities.respond_permission;
        const end = @min(view.rowCount(), view.top + rect.height);
        var row_index = view.top;
        while (row_index < end) : (row_index += 1) {
            const row = &view.rows.items[row_index];
            const bounds: ui.Rect = .{ .x = rect.x, .y = rect.y + @as(u32, @intCast(row_index - view.top)), .width = rect.width, .height = 1 };
            switch (row.kind) {
                .reference => {
                    const id_text = self.nextAgentViewId("agent.view.{d}.ref.{d}", .{ number, row.seq }, .{ .agent = agent_id, .seq = row.seq }) orelse return;
                    const id: ui.Id = .{ .value = id_text };
                    try self.ui_tree.addInteractiveText(.{
                        .id = id,
                        .parent = surface_id,
                        .role = "agent_ref",
                        .label = row.text,
                        .action = agent_view_open_ref_action,
                        .bounds = bounds,
                    }, .{
                        .id = id,
                        .label = row.text,
                        .action = agent_view_open_ref_action,
                        .normal = .{ .foreground = .blue },
                        .hovered = .{ .foreground = .strong, .underline = .accent },
                        .focused = .{ .foreground = .on_accent, .background = .accent },
                    });
                },
                .permission_choices, .permission_outcome => {
                    const entry = view.log.bySeq(row.seq) orelse continue;
                    if (entry.event != .permission_request) continue;
                    const request = entry.event.permission_request;
                    var request_part_buffer: [24]u8 = undefined;
                    const request_part = agentViewIdPart(request.id) orelse
                        (std.fmt.bufPrint(&request_part_buffer, "r{d}", .{row.seq}) catch continue);
                    var runs: [4]ui.Run = undefined;
                    if (row.kind == .permission_outcome) {
                        const id_text = self.nextAgentViewId("agent.view.{d}.perm.{s}.outcome", .{ number, request_part }, null) orelse return;
                        try self.ui_tree.addText(.{
                            .id = .{ .value = id_text },
                            .parent = surface_id,
                            .role = "agent_outcome",
                            .label = row.text,
                            .bounds = bounds,
                        }, .{ .runs = agentViewRuns(row, view.selection, row_index, &runs) });
                        continue;
                    }
                    const row_text = self.nextAgentViewId("agent.view.{d}.row.{d}", .{ number, row_index }, null) orelse return;
                    try self.ui_tree.addText(.{
                        .id = .{ .value = row_text },
                        .parent = surface_id,
                        .role = "agent_row",
                        .label = row.text,
                        .bounds = bounds,
                    }, .{ .runs = agentViewRuns(row, view.selection, row_index, &runs) });
                    // A harness that cannot take answers here keeps its
                    // choices as plain text: the human answers in its TUI.
                    if (!answerable) continue;
                    for (row.choices[0..row.choice_count]) |choice| {
                        const decision = request.decisions[choice.index];
                        var decision_part_buffer: [8]u8 = undefined;
                        const decision_part = agentViewIdPart(decision.id) orelse
                            (std.fmt.bufPrint(&decision_part_buffer, "d{d}", .{choice.index}) catch continue);
                        const id_text = self.nextAgentViewId("agent.view.{d}.perm.{s}.{s}", .{ number, request_part, decision_part }, .{
                            .agent = agent_id,
                            .seq = row.seq,
                            .decision = choice.index,
                        }) orelse return;
                        const id: ui.Id = .{ .value = id_text };
                        const label = row.text[agent_view.byteAtCell(row.text, choice.col)..agent_view.byteAtCell(row.text, choice.col + choice.cells)];
                        try self.ui_tree.addInteractiveText(.{
                            .id = id,
                            .parent = surface_id,
                            .role = "agent_decision",
                            .label = label,
                            .action = agent_view_answer_action,
                            .bounds = .{ .x = rect.x + choice.col, .y = bounds.y, .width = @min(choice.cells, rect.width -| choice.col), .height = 1 },
                        }, .{
                            .id = id,
                            .label = label,
                            .action = agent_view_answer_action,
                            .normal = .{ .foreground = .accent, .face_style = .bold },
                            .hovered = .{ .foreground = .strong, .underline = .accent },
                            .focused = .{ .foreground = .on_accent, .background = .accent },
                        });
                    }
                },
                else => {
                    const id_text = self.nextAgentViewId("agent.view.{d}.row.{d}", .{ number, row_index }, null) orelse return;
                    var runs: [4]ui.Run = undefined;
                    try self.ui_tree.addText(.{
                        .id = .{ .value = id_text },
                        .parent = surface_id,
                        .role = "agent_row",
                        .label = row.text,
                        .bounds = bounds,
                    }, .{ .runs = agentViewRuns(row, view.selection, row_index, &runs) });
                },
            }
        }

        // Search matches over the view's rows, as decorations like the
        // terminal's: same ids, same activation.
        if (self.search_visible and self.search_view == agent_id) {
            var semantic_index: usize = 0;
            for (self.agent_view_matches[0..self.search_match_count], 0..) |match, match_index| {
                if (match.row < view.top or match.row >= end) continue;
                if (semantic_index == self.search_highlight_ids[0].len or match.col >= rect.width) break;
                const id_text = try std.fmt.bufPrint(
                    &self.search_highlight_ids[self.search_highlight_id_generation][semantic_index],
                    "search.match.{d}.{d}",
                    .{ match_index, match.row },
                );
                semantic_index += 1;
                const id: ui.Id = .{ .value = id_text };
                const active = match_index == self.search_active_index;
                try self.ui_tree.addInteractiveText(.{
                    .id = id,
                    .role = "search_match",
                    .label = "Search match",
                    .selected = active,
                    .action = search_activate_match_action,
                    .bounds = .{
                        .x = rect.x + match.col,
                        .y = rect.y + @as(u32, @intCast(match.row - view.top)),
                        .width = @min(match.cells, rect.width - match.col),
                        .height = 1,
                    },
                }, .{
                    .id = id,
                    .label = "Search match",
                    .action = search_activate_match_action,
                    .paint = .decorations_only,
                    .normal = if (active)
                        .{ .underline = .accent, .overline = .accent }
                    else
                        .{ .underline = .attention },
                    .hovered = .{ .underline = .strong, .overline = .strong },
                    .focused = .{ .underline = .accent, .overline = .accent },
                });
            }
        }
    }

    /// The view's height in rows, for scrolling by keys.
    fn agentViewHeight(self: *App, runner: *const app_agents.Runner) u32 {
        const layout = self.agentViewLayout(runner) orelse return 1;
        return @max(agentViewRowsRect(layout).height, 1);
    }

    /// The interactive view elements of this frame in order: references and
    /// decisions, the Tab stops.
    fn agentViewStops(self: *App, number: u64, out: [][]const u8) [][]const u8 {
        var prefix_buffer: [32]u8 = undefined;
        const prefix = std.fmt.bufPrint(&prefix_buffer, "agent.view.{d}.", .{number}) catch return out[0..0];
        var count: usize = 0;
        for (self.ui_tree.elements()) |element| {
            if (count == out.len) break;
            if (!element.primitive.isInteractive() or !std.mem.startsWith(u8, element.id.value, prefix)) continue;
            out[count] = element.id.value;
            count += 1;
        }
        return out[0..count];
    }

    /// Move keyboard focus among the view's controls. With nothing focused
    /// the first undecided permission choice is the first stop, since a
    /// waiting agent is what the view most often needs.
    fn moveAgentViewFocus(self: *App, runner: *app_agents.Runner, forward: bool, decisions_only: bool) !void {
        const number = @intFromEnum(runner.agent_id orelse return);
        var storage: [agent_view_element_capacity][]const u8 = undefined;
        const all_stops = self.agentViewStops(number, &storage);
        var filtered: [agent_view_element_capacity][]const u8 = undefined;
        var stops: [][]const u8 = all_stops;
        const focused = if (self.ui_tree.focusedElement()) |element| element.id.value else null;
        if (decisions_only) {
            // Left and Right stay within the focused request's choices.
            const base = if (focused) |id| (if (std.mem.lastIndexOfScalar(u8, id, '.')) |dot| id[0 .. dot + 1] else id) else null;
            var count: usize = 0;
            for (all_stops) |id| {
                if (std.mem.indexOf(u8, id, ".perm.") == null) continue;
                if (base) |prefix| if (!std.mem.startsWith(u8, id, prefix)) continue;
                filtered[count] = id;
                count += 1;
            }
            stops = filtered[0..count];
        }
        if (stops.len == 0) return;
        var target: []const u8 = stops[0];
        if (focused) |id| {
            for (stops, 0..) |stop, index| {
                if (!std.mem.eql(u8, stop, id)) continue;
                target = if (forward)
                    stops[(index + 1) % stops.len]
                else
                    stops[(index + stops.len - 1) % stops.len];
                break;
            }
        } else {
            for (stops) |stop| if (std.mem.indexOf(u8, stop, ".perm.") != null) {
                target = stop;
                break;
            };
        }
        var copy: [agent_view_id_capacity]u8 = undefined;
        const kept = copy[0..target.len];
        @memcpy(kept, target);
        if (self.ui_tree.focus(.{ .value = kept })) try self.refreshActiveUi();
    }

    /// Keys while a view is presented (TASK-57): scrolling, Shift+arrow
    /// selection, Tab/Left/Right between controls, Enter to activate and
    /// Escape to let go. A view is not a terminal, so other keys stop here,
    /// except Ctrl+C without a view selection, which still interrupts the
    /// agent (invariant 8). Returns whether the key was the view's.
    fn routeAgentViewKey(self: *App, key: platform.KeyEvent) !bool {
        const runner = self.presentedAgentView() orelse return false;
        if (self.ui_tree.focusedElement()) |element| {
            if (!std.mem.startsWith(u8, element.id.value, "agent.view.")) return false;
        }
        if (key.action == .release) {
            const owned = if (uiKeyIdentity(key)) |identity| self.terminal_key_state.indexOf(identity) != null else false;
            return !owned;
        }
        const view = &runner.view;
        const height = self.agentViewHeight(runner);
        const shift = key.mods.shift and !key.mods.ctrl and !key.mods.alt and !key.mods.super;
        const plain = !key.mods.shift and !key.mods.ctrl and !key.mods.alt and !key.mods.super;
        const page: isize = @intCast(@max(height -| 1, 1));
        switch (key.key) {
            .up, .down, .left, .right => {
                if (shift) {
                    self.extendAgentViewSelection(runner, key.key, height);
                } else if (plain) switch (key.key) {
                    .up => view.scrollBy(-1, height),
                    .down => view.scrollBy(1, height),
                    .left => try self.moveAgentViewFocus(runner, false, true),
                    .right => try self.moveAgentViewFocus(runner, true, true),
                    else => unreachable,
                };
            },
            .page_up => if (plain) view.scrollBy(-page, height),
            .page_down => if (plain) view.scrollBy(page, height),
            .home => if (plain) view.scrollToTop(),
            .end => if (plain) view.scrollToBottom(height),
            .tab => if (plain or shift) try self.moveAgentViewFocus(runner, !key.mods.shift, false),
            .enter => if (plain) {
                if (self.ui_tree.activateFocused()) |activation| {
                    try self.dispatchAction(activation.action, .{ .source = .keybinding, .origin = activation.id });
                    return true;
                }
            },
            .escape => if (plain) {
                view.selection = null;
                self.ui_tree.clearFocus();
            },
            else => {
                const interrupt = key.mods.ctrl and !key.mods.shift and !key.mods.alt and !key.mods.super and
                    (key.unshifted_codepoint == 'c' or key.codepoint == 'c');
                if (interrupt) {
                    const selected = view.selection != null and !view.selection.?.isEmpty();
                    if (!selected) return false;
                    try self.copyAgentViewSelection(runner);
                    view.selection = null;
                }
            },
        }
        try self.refreshActiveUi();
        return true;
    }

    /// Shift+arrows grow the selection from where it is, or from the first
    /// visible row's start when there is none.
    fn extendAgentViewSelection(self: *App, runner: *app_agents.Runner, key: platform.Key, height: u32) void {
        _ = self;
        const view = &runner.view;
        if (view.rowCount() == 0) return;
        var selection = view.selection orelse agent_view.Selection{
            .anchor = .{ .row = view.top, .col = 0 },
            .caret = .{ .row = view.top, .col = 0 },
        };
        const last = view.rowCount() - 1;
        switch (key) {
            .up => selection.caret.row -|= 1,
            .down => selection.caret.row = @min(selection.caret.row + 1, last),
            .left => selection.caret.col -|= 1,
            .right => selection.caret.col = @min(selection.caret.col + 1, view.rows.items[selection.caret.row].cells()),
            else => {},
        }
        selection.caret.col = @min(selection.caret.col, view.rows.items[selection.caret.row].cells());
        view.selection = selection;
        view.reveal(selection.caret.row, height);
    }

    fn copyAgentViewSelection(self: *App, runner: *app_agents.Runner) !void {
        const text = (try runner.view.selectionText(self.allocator)) orelse return;
        defer self.allocator.free(text);
        platform.setClipboardText(self.allocator, text) catch |err| {
            log.warn("copy of {d} agent-view byte(s) failed: {s}", .{ text.len, @errorName(err) });
            return;
        };
        log.info("copied {d} byte(s) from the agent view to the clipboard", .{text.len});
    }

    /// Pointer events over a view: hover and clicks on its controls, drag to
    /// select, the wheel to scroll, and no text reaching the hidden
    /// terminal. Null leaves the event to the ordinary routes.
    fn handleAgentViewUiEvent(self: *App, event: platform.Event) !?bool {
        const tree = self.activeUiTree();
        switch (event) {
            .mouse_motion => |motion| {
                const point = devicePointerPoint(motion.x, motion.y, self.window.state.scale);
                if (self.agent_view_pointer) |id| {
                    const runner = self.agents.runnerForAgent(id) orelse {
                        self.agent_view_pointer = null;
                        return true;
                    };
                    const layout = self.agentViewLayout(runner) orelse return true;
                    if (runner.view.selection) |*selection| {
                        const caret = self.agentViewPosition(&runner.view, agentViewRowsRect(layout), point);
                        if (!std.meta.eql(caret, selection.caret)) {
                            selection.caret = caret;
                            try self.refreshActiveUi();
                        }
                    }
                    return true;
                }
                if (self.ui_pointer_owned) return null;
                if (self.agentViewAt(point) == null) return null;
                const before = uiInteractionState(tree);
                tree.pointerMoved(point);
                if (!std.meta.eql(before, uiInteractionState(tree))) try self.refreshActiveUi();
                return true;
            },
            .mouse_button => |button| {
                const point = devicePointerPoint(button.x, button.y, self.window.state.scale);
                if (self.agent_view_pointer != null) {
                    if (button.action == .release and button.button == .left) self.agent_view_pointer = null;
                    return true;
                }
                if (self.ui_pointer_owned) return null;
                const hit = self.agentViewAt(point) orelse return null;
                if (button.button != .left or button.action != .press) return true;
                const tab_id = self.activeWorkspace().activeTabId() orelse return true;
                if (self.activeWorkspace().focusedPaneId(tab_id) != hit.layout.pane_id) {
                    var pane_id_buffer: [pane_semantic_capacity]u8 = undefined;
                    const pane_semantic = try paneSemanticId(&pane_id_buffer, self.activePresentation().key, hit.layout.pane_id);
                    try self.dispatchAction(pane_activate_action, .{ .source = .mouse, .origin = .{ .value = pane_semantic } });
                    if (self.activeWorkspace().focusedPaneId(tab_id) != hit.layout.pane_id) {
                        self.ui_pointer_owned = true;
                        return true;
                    }
                }
                if (tree.hitTest(point)) |element| {
                    if (element.primitive.isInteractive() and std.mem.startsWith(u8, element.id.value, "agent.view.")) {
                        const before = uiInteractionState(tree);
                        tree.pointerPressed(point);
                        self.ui_pointer_owned = true;
                        if (!std.meta.eql(before, uiInteractionState(tree))) try self.refreshActiveUi();
                        return true;
                    }
                }
                tree.clearFocus();
                const position = self.agentViewPosition(&hit.runner.view, agentViewRowsRect(hit.layout), point);
                hit.runner.view.selection = .{ .anchor = position, .caret = position };
                self.agent_view_pointer = hit.runner.agent_id;
                try self.refreshActiveUi();
                return true;
            },
            .wheel => |wheel| {
                const point = devicePointerPoint(wheel.x, wheel.y, self.window.state.scale);
                const hit = self.agentViewAt(point) orelse return null;
                if (wheel.dy == 0) return true;
                var up = wheel.dy > 0;
                if (wheel.flipped) up = !up;
                hit.runner.view.scrollBy(if (up) -3 else 3, @max(agentViewRowsRect(hit.layout).height, 1));
                try self.refreshActiveUi();
                return true;
            },
            .text_input, .text_editing, .candidates => {
                if (self.presentedAgentView() == null or tree.focusedInput() != null) return null;
                return true;
            },
            else => return null,
        }
    }

    fn agentViewToggleAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        const runner = self.presentedAgentRunner() orelse {
            self.setWorkspaceStatus("no agent in this pane");
            try self.refreshActiveUi();
            return;
        };
        if (runner.agent_id == null) return;
        runner.view.active = !runner.view.active;
        runner.view.follow = true;
        runner.view.selection = null;
        self.agent_view_pointer = null;
        self.ui_tree.clearFocus();
        self.composition.cancel();
        try self.refreshActiveUi();
        try self.syncTextInput();
    }

    /// Answer a permission request from a click or Enter on one of its
    /// decisions. Only a gesture on the element reaches here: the origin
    /// names the decision, and nothing in the transcript can.
    fn agentViewAnswerAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const origin = invocation.origin orelse return;
        const target = self.agentViewTarget(origin.value) orelse return;
        const index = target.decision orelse return;
        const runner = self.agents.runnerForAgent(target.agent) orelse return;
        const entry = runner.view.log.bySeq(target.seq) orelse return;
        if (entry.event != .permission_request or entry.answered != null or entry.outcome != null) return;
        const request = entry.event.permission_request;
        if (index >= request.decisions.len) return;
        runner.answerPermission(request.id, request.decisions[index].id) catch |err| {
            log.warn("a permission answer was not queued: {s}", .{@errorName(err)});
            self.setWorkspaceStatus("the answer could not be sent; answer in the terminal");
            try self.refreshActiveUi();
            return;
        };
        _ = runner.view.log.markAnswered(target.seq, index);
        self.ui_tree.clearFocus();
        try self.refreshActiveUi();
    }

    /// Open a file reference from the view in a new tab at its line, exactly
    /// as a terminal file reference opens (decision-5).
    fn agentViewOpenRefAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const origin = invocation.origin orelse return;
        const target = self.agentViewTarget(origin.value) orelse return;
        const runner = self.agents.runnerForAgent(target.agent) orelse return;
        const entry = runner.view.log.bySeq(target.seq) orelse return;
        if (entry.event != .file_reference) return;
        const reference = entry.event.file_reference;
        if (!try self.openAgentFileReference(runner, reference.path, reference.line)) return;
        self.ui_tree.clearFocus();
        try self.refreshActiveUi();
    }

    /// The editor tab for one agent file reference. A relative path is the
    /// harness's, so it resolves against the agent session's tracked cwd, or
    /// the cwd the agent was launched in. Returns false when nothing changed.
    fn openAgentFileReference(self: *App, runner: *app_agents.Runner, reference_path: []const u8, line: ?u32) !bool {
        var path_storage: [file_reference_path_max_bytes]u8 = undefined;
        if (reference_path.len > path_storage.len) return false;
        @memcpy(path_storage[0..reference_path.len], reference_path);
        const path = path_storage[0..reference_path.len];
        if (self.activePresentation().load != null) {
            log.debug("agent file reference ignored while another load is in flight", .{});
            return false;
        }
        if (self.remoteNotReady()) return false;
        const source = self.activeWorkspace().sessionById(runner.session);
        const tracked = if (source) |live| live.workingDirectory() else null;
        const cwd = try self.allocator.dupe(u8, tracked orelse runner.cwd);
        var cwd_owned = true;
        defer if (cwd_owned) self.allocator.free(cwd);
        const argv = buildFileReferenceArgv(self.allocator, path, line, cwd) catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory,
            error.UnsafePath, error.PathTooLong => {
                log.debug("agent file reference of {d} byte(s) was not opened: {s}", .{ path.len, @errorName(err) });
                return false;
            },
        };
        cwd_owned = false;
        return self.openEditorTab(fileReferenceLabel(path), cwd, argv);
    }

    /// Search the presented view's rows instead of the terminal (TASK-57).
    /// Literal only; regex stays a terminal feature. `reveal` scrolls to the
    /// active match.
    fn findAgentViewMatches(self: *App, runner: *app_agents.Runner, reveal: bool) void {
        self.search_view = runner.agent_id;
        self.search_progress = .complete;
        self.search_failure = null;
        if (self.search_query.text().len == 0) {
            self.search_match_count = 0;
            return;
        }
        if (self.search_mode == .regex) {
            self.search_match_count = 0;
            self.search_failure = "regex searches the terminal only";
            return;
        }
        const found = agent_view.findMatches(runner.view.rows.items, self.search_query.text(), self.search_case == .sensitive, &self.agent_view_matches);
        self.search_match_count = found.count;
        self.search_truncated = found.truncated;
        if (self.search_active_index >= found.count) self.search_active_index = 0;
        if (reveal) self.revealAgentViewMatch(runner);
    }

    fn revealAgentViewMatch(self: *App, runner: *app_agents.Runner) void {
        if (self.search_active_index >= self.search_match_count) return;
        runner.view.reveal(self.agent_view_matches[self.search_active_index].row, self.agentViewHeight(runner));
    }

    fn notificationsVisible(self: *const App) bool {
        return self.notifications_visible;
    }

    fn notificationRowCount(self: *const App) usize {
        return @min(self.agents.notifications.count(), notification_visible_rows);
    }

    fn notificationsBounds(self: *const App) ?ui.Rect {
        if (!self.notifications_visible) return null;
        const canvas = self.ui_canvas.bounds();
        const rows: u32 = @intCast(@max(self.notificationRowCount(), 1));
        const width = @min(canvas.width, @as(u32, 76));
        const height = @min(canvas.height, rows + 4);
        if (width < 24 or height < 5) return null;
        return .{
            .x = (canvas.width - width) / 2,
            .y = (canvas.height - height) / 2,
            .width = width,
            .height = height,
        };
    }

    /// A short age: `now`, `42s`, `7m`, `3h`, `2d`.
    fn formatAge(buffer: []u8, raised_ns: i96, now_ns: i96) []const u8 {
        const seconds: i96 = @divTrunc(@max(now_ns - raised_ns, 0), std.time.ns_per_s);
        return (if (seconds < 5)
            std.fmt.bufPrint(buffer, "now", .{})
        else if (seconds < 60)
            std.fmt.bufPrint(buffer, "{d}s", .{seconds})
        else if (seconds < 3600)
            std.fmt.bufPrint(buffer, "{d}m", .{@divTrunc(seconds, 60)})
        else if (seconds < 86400)
            std.fmt.bufPrint(buffer, "{d}h", .{@divTrunc(seconds, 3600)})
        else
            std.fmt.bufPrint(buffer, "{d}d", .{@divTrunc(seconds, 86400)})) catch "";
    }

    /// The list is a `Surface` panel of `InteractiveText` rows, newest first,
    /// each `<age>  <workspace> › <tab>  <title>: <text>`. Text is the
    /// program's or harness's display data, clipped at the panel edge.
    fn composeNotifications(self: *App) !void {
        const bounds = self.notificationsBounds() orelse return;
        const dialog_id: ui.Id = .{ .value = "notifications" };
        try self.ui_tree.addSurface(.{
            .id = dialog_id,
            .role = "dialog",
            .label = "Notifications",
            .bounds = bounds,
        }, .{
            .rect = bounds,
            .erase_underlay = true,
            .fill = .background,
            .border = .double,
            .border_style = .{ .foreground = .border, .background = .background },
            .title = " Notifications ",
            .title_style = .{ .foreground = .strong, .background = .background, .face_style = .bold },
        });
        const inner_x = bounds.x + 2;
        const inner_width = bounds.width - 4;
        const count = self.notificationRowCount();
        if (count == 0) {
            const runs = [_]ui.Run{.{ .text = "No notifications", .style = .{ .foreground = .muted } }};
            try self.ui_tree.addText(.{
                .id = .{ .value = "notifications.empty" },
                .parent = dialog_id,
                .role = "status",
                .label = "No notifications",
                .bounds = .{ .x = inner_x, .y = bounds.y + 2, .width = inner_width, .height = 1 },
            }, .{ .runs = &runs });
        }
        const now = Io.Clock.awake.now(self.io).nanoseconds;
        for (0..count) |index| {
            if (bounds.y + 2 + index >= bounds.y + bounds.height - 1) break;
            const entry = self.agents.notifications.newest(index) orelse break;
            const id_text = try std.fmt.bufPrint(&self.notification_row_ids[index], "notification.{d}", .{index});
            var age_buffer: [16]u8 = undefined;
            const workspace_name = if (self.workspace_registry.byKey(entry.workspace)) |model| model.name() else "?";
            const label = std.fmt.bufPrint(&self.notification_row_labels[index], "{s: >4}  {s} › {s}  {s}: {s}", .{
                formatAge(&age_buffer, entry.raised_ns, now),
                workspace_name,
                self.sessionTabName(entry.workspace, entry.session) orelse "(closed)",
                entry.title(),
                entry.body(),
            }) catch entry.title();
            const id: ui.Id = .{ .value = id_text };
            try self.ui_tree.addInteractiveText(.{
                .id = id,
                .parent = dialog_id,
                .role = "notification",
                .label = label,
                .action = notifications_activate_action,
                .bounds = .{ .x = inner_x, .y = bounds.y + 2 + @as(u32, @intCast(index)), .width = inner_width, .height = 1 },
            }, .{
                .id = id,
                .label = label,
                .action = notifications_activate_action,
                .normal = .{ .foreground = if (entry.kind == .permission or entry.kind == .@"error") .attention else .foreground, .background = .background },
                .hovered = .{ .foreground = .strong, .underline = .accent, .background = .background },
                .focused = .{ .foreground = .on_accent, .background = .accent },
            });
        }
    }

    fn openNotifications(self: *App) !void {
        if (self.notificationsVisible() or self.contextMenuVisible() or self.paletteVisible() or self.settingsVisible() or
            self.managerVisible() or self.promptsVisible() or self.closeModalActive() or self.rename_tab_id != null or self.ui_pointer_owned or self.sidebar_dragging or
            self.dragged_divider_id != null or self.dragged_tab_id != null) return;
        if (self.search_visible) try self.closeSearch();
        self.composition.cancel();
        _ = takeCommittedText(&self.pending_committed_text);
        try self.window.stopTextInput();
        self.notifications_visible = true;
        self.ui_tree.clearFocus();
        try self.composeUi();
        if (self.notificationRowCount() != 0 and self.ui_tree.focus(.{ .value = "notification.0" })) try self.composeUi();
        try self.syncTextInput();
        self.invalidateUi();
    }

    fn closeNotifications(self: *App) !void {
        if (!self.notificationsVisible()) return;
        self.notifications_visible = false;
        self.ui_tree.clearFocus();
        try self.composeUi();
        try self.syncTextInput();
        self.invalidateUi();
    }

    fn moveNotificationFocus(self: *App, next: bool) !void {
        const count = self.notificationRowCount();
        if (count == 0) return;
        var current: ?usize = null;
        if (self.ui_tree.focusedElement()) |focused| current = notificationRowIndex(focused.id.value);
        const target = if (current) |index|
            if (next) (index + 1) % count else (index + count - 1) % count
        else if (next) 0 else count - 1;
        var storage: [palette_semantic_capacity]u8 = undefined;
        const id = try std.fmt.bufPrint(&storage, "notification.{d}", .{target});
        if (self.ui_tree.focus(.{ .value = id })) try self.refreshActiveUi();
    }

    fn notificationRowIndex(id: []const u8) ?usize {
        const prefix = "notification.";
        if (!std.mem.startsWith(u8, id, prefix)) return null;
        return std.fmt.parseInt(usize, id[prefix.len..], 10) catch null;
    }

    /// Activating a row closes the list and shows the entry's session:
    /// its workspace, tab and pane, and selects its agent.
    fn activateNotificationRow(self: *App, row_id: []const u8) !void {
        const index = notificationRowIndex(row_id) orelse return;
        const found = self.agents.notifications.newest(index) orelse return;
        const entry = found.*;
        try self.closeNotifications();
        try self.focusSession(entry.workspace, entry.session);
        self.agents.selected_agent = entry.agent;
    }

    fn handleNotificationsUiEvent(self: *App, event: platform.Event) !bool {
        const tree = self.activeUiTree();
        switch (event) {
            .mouse_motion => |motion| {
                const point = devicePointerPoint(motion.x, motion.y, self.window.state.scale);
                const before = uiInteractionState(tree);
                tree.pointerMoved(point);
                if (!std.meta.eql(before, uiInteractionState(tree))) try self.refreshActiveUi();
                return true;
            },
            .mouse_button => |button| {
                const point = devicePointerPoint(button.x, button.y, self.window.state.scale);
                const bounds = self.notificationsBounds();
                const inside = bounds != null and self.pointInCellRect(point, bounds.?);
                switch (button.action) {
                    .press => {
                        self.notifications_pointer_owned = true;
                        if (!inside) {
                            try self.closeNotifications();
                            return true;
                        }
                        if (button.button != .left) return true;
                        const before = uiInteractionState(tree);
                        tree.pointerPressed(point);
                        if (!std.meta.eql(before, uiInteractionState(tree))) try self.refreshActiveUi();
                        return true;
                    },
                    .repeat => return true,
                    .release => {
                        if (!self.notifications_pointer_owned) return true;
                        self.notifications_pointer_owned = false;
                        if (button.button != .left) return true;
                        const before = uiInteractionState(tree);
                        const activation = tree.pointerReleased(point);
                        if (!std.meta.eql(before, uiInteractionState(tree))) try self.refreshActiveUi();
                        if (activation) |requested| {
                            var id_storage: [palette_semantic_capacity]u8 = undefined;
                            if (requested.id.value.len > id_storage.len) return true;
                            @memcpy(id_storage[0..requested.id.value.len], requested.id.value);
                            try self.activateNotificationRow(id_storage[0..requested.id.value.len]);
                        }
                        return true;
                    },
                }
            },
            .wheel => return true,
            .text_input, .key => return false,
            .text_editing, .candidates => return true,
            else => return false,
        }
    }

    fn notificationsOpenAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        try self.openNotifications();
    }

    fn notificationsClearAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        self.agents.notifications.clear();
        if (self.notificationsVisible()) try self.refreshActiveUi() else self.invalidateUi();
    }

    fn notificationsActivateAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const origin = invocation.origin orelse return;
        var id_storage: [palette_semantic_capacity]u8 = undefined;
        if (origin.value.len > id_storage.len) return;
        @memcpy(id_storage[0..origin.value.len], origin.value);
        try self.activateNotificationRow(id_storage[0..origin.value.len]);
    }

    // The agent manager (TASK-58) -------------------------------------------

    fn managerVisible(self: *const App) bool {
        return self.manager_visible;
    }

    /// The position of a workspace in the sidebar, or null once it is gone.
    fn workspaceRank(self: *const App, key: workspace.WorkspaceKey) ?usize {
        var index: usize = 0;
        while (index < self.workspace_registry.count()) : (index += 1) {
            if (self.workspace_registry.keyAt(index) == key) return index;
        }
        return null;
    }

    /// Relist the registry's agents in manager order: workspaces as the
    /// sidebar lists them, then their tab order, then id. Never the
    /// scratchpad: the registry refuses to bind an agent there.
    fn rebuildManagerOrder(self: *App) void {
        var keys: [manager_capacity]app_agents.ManagerSortKey = undefined;
        var count: usize = 0;
        for (self.agents.registry.all()) |*record| {
            if (count == manager_capacity) break;
            const rank = self.workspaceRank(record.workspace) orelse continue;
            const model = self.workspace_registry.byKey(record.workspace) orelse continue;
            const location = model.paneForSession(record.session);
            const tab_rank: usize = if (location) |found| model.tabIndex(found.tab_id) orelse std.math.maxInt(usize) else std.math.maxInt(usize);
            keys[count] = .{ .workspace_rank = rank, .tab_rank = tab_rank, .id = record.id };
            count += 1;
        }
        app_agents.sortManagerRows(keys[0..count]);
        for (keys[0..count], 0..) |key, index| self.manager_order[index] = key.id;
        self.manager_count = count;
        if (count == 0) {
            self.manager_selected = null;
            return;
        }
        if (self.manager_selected) |id| {
            if (self.managerIndexOf(id) != null) return;
        }
        // The highlighted agent went (its tab closed): keep the position.
        self.manager_selected = self.manager_order[@min(self.manager_selected_index, count - 1)];
    }

    fn managerIndexOf(self: *const App, id: agent.AgentId) ?usize {
        for (self.manager_order[0..self.manager_count], 0..) |candidate, index| {
            if (candidate == id) return index;
        }
        return null;
    }

    fn managerListRows(self: *const App) usize {
        return switch (self.manager_mode) {
            .browse, .message => @max(self.manager_count, 1),
            .new_harness => @max(self.manager_harness_count, 1),
            .new_workspace => @max(self.workspace_registry.count(), 1),
            .new_prompt => 1,
        };
    }

    fn managerBounds(self: *const App) ?ui.Rect {
        if (!self.manager_visible) return null;
        const canvas = self.ui_canvas.bounds();
        if (canvas.width < 30 or canvas.height < 8) return null;
        const width = @min(canvas.width - 2, @as(u32, 96));
        const list: u32 = @intCast(@min(self.managerListRows(), manager_visible_capacity));
        const extra: u32 = if (self.manager_mode == .message) 1 else 0;
        // Two borders, the heading, the status line and the hint.
        const height = @min(list + extra + 5, canvas.height - 2);
        return .{
            .x = (canvas.width - width) / 2,
            .y = (canvas.height - height) / 2,
            .width = width,
            .height = height,
        };
    }

    /// Scroll so the highlighted row shows in `list_rows` rows.
    fn managerKeepVisible(self: *App, selected: usize, total: usize, list_rows: usize) void {
        if (list_rows == 0) return;
        if (selected < self.manager_scroll) self.manager_scroll = selected;
        if (selected >= self.manager_scroll + list_rows) self.manager_scroll = selected + 1 - list_rows;
        const last_start = total -| list_rows;
        if (self.manager_scroll > last_start) self.manager_scroll = last_start;
    }

    fn managerStatus(self: *const App) []const u8 {
        return self.manager_status_storage[0..self.manager_status_len];
    }

    fn setManagerStatus(self: *App, comptime format: []const u8, args: anytype) void {
        var writer: std.Io.Writer = .fixed(&self.manager_status_storage);
        writer.print(format, args) catch {
            // A status cut by the fixed buffer is still its start.
        };
        var len = writer.end;
        while (len != 0 and !std.unicode.utf8ValidateSlice(self.manager_status_storage[0..len])) len -= 1;
        self.manager_status_len = len;
    }

    /// The id of one manager element, in this frame's storage. Ids alternate
    /// storage per frame so the tree never sees an id's bytes change.
    fn managerId(self: *App, slot: usize, part: usize, comptime format: []const u8, args: anytype) ![]const u8 {
        const generation = self.manager_generation % 2;
        return std.fmt.bufPrint(&self.manager_ids[generation][slot][part], format, args);
    }

    fn addManagerControl(self: *App, parent: ui.Id, id_text: []const u8, label: []const u8, x: u32, y: u32) !void {
        const id: ui.Id = .{ .value = id_text };
        try self.ui_tree.addInteractiveText(.{
            .id = id,
            .parent = parent,
            .role = "button",
            .label = label,
            .action = agents_activate_action,
            .bounds = .{ .x = x, .y = y, .width = @intCast(label.len), .height = 1 },
        }, .{
            .id = id,
            .label = label,
            .action = agents_activate_action,
            .normal = .{ .foreground = .muted },
            .hovered = .{ .foreground = .strong, .underline = .accent },
            .focused = .{ .foreground = .on_accent, .background = .accent },
        });
    }

    fn addManagerChoiceRow(self: *App, parent: ui.Id, id_text: []const u8, label: []const u8, selected: bool, x: u32, y: u32, width: u32) !void {
        const id: ui.Id = .{ .value = id_text };
        try self.ui_tree.addInteractiveText(.{
            .id = id,
            .parent = parent,
            .role = "option",
            .label = label,
            .selected = selected,
            .action = agents_activate_action,
            .bounds = .{ .x = x, .y = y, .width = width, .height = 1 },
        }, .{
            .id = id,
            .label = label,
            .action = agents_activate_action,
            .normal = if (selected) .{ .foreground = .strong, .background = .selection } else .{ .foreground = .foreground },
            .hovered = if (selected)
                .{ .foreground = .strong, .background = .selection, .underline = .accent }
            else
                .{ .foreground = .strong, .underline = .accent },
            .focused = .{ .foreground = .on_accent, .background = .accent },
        });
    }

    fn addManagerText(self: *App, parent: ui.Id, id_text: []const u8, role: []const u8, text: []const u8, style: ui.TextStyle, bounds: ui.Rect) !void {
        const runs = [_]ui.Run{.{ .text = text, .style = style }};
        try self.ui_tree.addText(.{
            .id = .{ .value = id_text },
            .parent = parent,
            .role = role,
            .label = text,
            .bounds = bounds,
        }, .{ .runs = &runs });
    }

    fn addManagerInput(self: *App, parent: ui.Id, label: []const u8, bounds: ui.Rect) !void {
        try self.ui_tree.addInput(.{
            .id = .{ .value = "agents.input" },
            .parent = parent,
            .role = "input",
            .label = label,
            .action = agents_activate_action,
            .bounds = bounds,
        }, &self.manager_input, .{
            .text = .{ .foreground = .strong, .background = .field },
            .selection_background = .selection,
            .cursor_background = .accent,
            .cursor_foreground = .background,
        });
        try self.composePalettePreedit(parent, bounds, &self.manager_input);
    }

    /// The manager is a `Surface` panel: a heading, one `InteractiveText` row
    /// per agent with its stop, restart and message controls, an inline
    /// message `Input` under the highlighted row while one is typed, the
    /// new-agent chooser steps, a status line and a key hint. Rows are
    /// rebuilt from the registry every frame, so states and ages are live.
    fn composeManager(self: *App) !void {
        const bounds = self.managerBounds() orelse return;
        self.rebuildManagerOrder();
        self.manager_generation +%= 1;
        const dialog_id: ui.Id = .{ .value = "agents.dialog" };
        try self.ui_tree.addSurface(.{
            .id = dialog_id,
            .role = "dialog",
            .label = "Agents",
            .bounds = bounds,
        }, .{
            .rect = bounds,
            .erase_underlay = true,
            .fill = .background,
            .border = .double,
            .border_style = .{ .foreground = .border, .background = .background },
            .title = " Agents ",
            .title_style = .{ .foreground = .strong, .background = .background, .face_style = .bold },
        });
        const inner_x = bounds.x + 2;
        const inner_width = bounds.width - 4;
        const heading_y = bounds.y + 1;
        const list_top = bounds.y + 2;
        const list_end = bounds.y + bounds.height - 3;
        const muted: ui.TextStyle = .{ .foreground = .muted };

        const heading = switch (self.manager_mode) {
            .browse, .message => "  harness  workspace › tab  task  state  last",
            .new_harness => "New agent: harness",
            .new_workspace => "New agent: workspace",
            .new_prompt => "New agent: initial prompt (Enter for none)",
        };
        const control = if (self.manager_mode == .browse) "new" else "back";
        const control_width: u32 = @intCast(control.len);
        try self.addManagerText(dialog_id, "agents.heading", "heading", heading, muted, .{ .x = inner_x, .y = heading_y, .width = inner_width -| (control_width + 1), .height = 1 });
        if (self.manager_mode != .message) {
            try self.addManagerControl(dialog_id, if (self.manager_mode == .browse) "agents.new" else "agents.back", control, inner_x + inner_width - control_width, heading_y);
        }

        const available: usize = if (list_end > list_top) list_end - list_top else 0;
        switch (self.manager_mode) {
            .browse, .message => try self.composeManagerAgents(dialog_id, inner_x, inner_width, list_top, available),
            .new_harness => {
                const count = self.manager_harness_count;
                if (count == 0) {
                    try self.addManagerText(dialog_id, "agents.empty", "status", "No coding agent found here", muted, .{ .x = inner_x, .y = list_top, .width = inner_width, .height = 1 });
                }
                self.managerKeepVisible(self.manager_choice_selected, count, available);
                const end = @min(count, self.manager_scroll + available);
                for (self.manager_scroll..end, 0..) |index, slot| {
                    const id_text = try self.managerId(slot, 0, "agents.new.harness.{d}", .{index});
                    try self.addManagerChoiceRow(dialog_id, id_text, self.manager_harness_labels[index][0..self.manager_harness_label_lens[index]], index == self.manager_choice_selected, inner_x, list_top + @as(u32, @intCast(slot)), inner_width);
                }
            },
            .new_workspace => {
                const count = self.workspace_registry.count();
                self.managerKeepVisible(self.manager_choice_selected, count, available);
                const end = @min(count, self.manager_scroll + available);
                for (self.manager_scroll..end, 0..) |index, slot| {
                    const model = self.workspace_registry.at(index) orelse continue;
                    const id_text = try self.managerId(slot, 0, "agents.new.workspace.{d}", .{index});
                    try self.addManagerChoiceRow(dialog_id, id_text, model.name(), index == self.manager_choice_selected, inner_x, list_top + @as(u32, @intCast(slot)), inner_width);
                }
            },
            .new_prompt => {
                const launch = "launch";
                const field_width: u32 = inner_width -| @as(u32, launch.len + 1);
                if (field_width != 0) try self.addManagerInput(dialog_id, "Initial prompt", .{ .x = inner_x, .y = list_top, .width = field_width, .height = 1 });
                try self.addManagerControl(dialog_id, "agents.new.launch", launch, inner_x + inner_width - @as(u32, launch.len), list_top);
            },
        }

        const status_bounds: ui.Rect = .{ .x = inner_x, .y = bounds.y + bounds.height - 3, .width = inner_width, .height = 1 };
        if (self.manager_status_len != 0) {
            try self.addManagerText(dialog_id, "agents.status", "status", self.managerStatus(), .{ .foreground = .attention }, status_bounds);
        }
        const hint = switch (self.manager_mode) {
            .browse => manager_hint,
            .message => "Enter send  Esc cancel",
            .new_harness, .new_workspace => "Enter choose  Esc back",
            .new_prompt => "Enter launch  Esc back",
        };
        try self.addManagerText(dialog_id, "agents.hint", "status", hint, muted, .{ .x = inner_x, .y = bounds.y + bounds.height - 2, .width = inner_width, .height = 1 });
    }

    fn composeManagerAgents(self: *App, dialog_id: ui.Id, inner_x: u32, inner_width: u32, list_top: u32, available: usize) !void {
        const muted: ui.TextStyle = .{ .foreground = .muted };
        if (self.manager_count == 0) {
            try self.addManagerText(dialog_id, "agents.empty", "status", "No agents  n new", muted, .{ .x = inner_x, .y = list_top, .width = inner_width, .height = 1 });
            return;
        }
        const extra: usize = if (self.manager_mode == .message) 1 else 0;
        const list_rows = available -| extra;
        const selected_index = if (self.manager_selected) |id| self.managerIndexOf(id) orelse 0 else 0;
        self.manager_selected_index = selected_index;
        self.managerKeepVisible(selected_index, self.manager_count, list_rows);
        const end = @min(self.manager_count, self.manager_scroll + list_rows);
        const now = Io.Clock.awake.now(self.io).nanoseconds;
        // `stop restart message`, right-aligned.
        const controls_width: u32 = 20;
        const label_width = inner_width -| (controls_width + 1);
        var y = list_top;
        for (self.manager_scroll..end, 0..) |index, slot| {
            const id = self.manager_order[index];
            const record = self.agents.registry.get(id) orelse continue;
            const is_selected = index == selected_index;
            const raw_id = @intFromEnum(id);
            const workspace_name = if (self.workspace_registry.byKey(record.workspace)) |model| model.name() else "?";
            var age_buffer: [16]u8 = undefined;
            const label = app_agents.formatManagerRow(&self.manager_labels[slot], .{
                .glyph = app_agents.stateGlyph(record.state),
                .harness = self.agents.displayName(record),
                .workspace = workspace_name,
                .tab = self.sessionTabName(record.workspace, record.session) orelse "(closed)",
                .task = if (self.agents.runnerForAgent(id)) |runner| runner.taskId() else null,
                .state = app_agents.managerStateWord(record),
                .age = formatAge(&age_buffer, self.agents.lastActivity(id) orelse now, now),
            });
            const row_text = try self.managerId(slot, 0, "agents.row.{d}", .{raw_id});
            const row_id: ui.Id = .{ .value = row_text };
            const attention = record.state == .waiting_permission or record.state == .waiting_input or record.state == .errored;
            try self.ui_tree.addInteractiveText(.{
                .id = row_id,
                .parent = dialog_id,
                .role = "agent",
                .label = label,
                .selected = is_selected,
                .action = agents_activate_action,
                .bounds = .{ .x = inner_x, .y = y, .width = label_width, .height = 1 },
            }, .{
                .id = row_id,
                .label = label,
                .action = agents_activate_action,
                .normal = if (is_selected)
                    .{ .foreground = .strong, .background = .selection }
                else if (record.hasExited())
                    .{ .foreground = .muted }
                else if (attention)
                    .{ .foreground = .attention }
                else
                    .{ .foreground = .foreground },
                .hovered = if (is_selected)
                    .{ .foreground = .strong, .background = .selection, .underline = .accent }
                else
                    .{ .foreground = .strong, .underline = .accent },
                .focused = .{ .foreground = .on_accent, .background = .accent },
            });
            const controls_x = inner_x + inner_width - controls_width;
            if (!record.hasExited()) {
                try self.addManagerControl(dialog_id, try self.managerId(slot, 1, "agents.row.{d}.stop", .{raw_id}), "stop", controls_x, y);
            }
            if (self.agents.restartable(id)) {
                try self.addManagerControl(dialog_id, try self.managerId(slot, 2, "agents.row.{d}.restart", .{raw_id}), "restart", controls_x + 5, y);
            }
            if (!record.hasExited()) {
                try self.addManagerControl(dialog_id, try self.managerId(slot, 3, "agents.row.{d}.message", .{raw_id}), "message", controls_x + 13, y);
            }
            y += 1;
            if (is_selected and self.manager_mode == .message) {
                const send = "send";
                const prefix = "› ";
                try self.addManagerText(dialog_id, "agents.input.prompt", "status", prefix, muted, .{ .x = inner_x, .y = y, .width = 2, .height = 1 });
                const field_width: u32 = inner_width -| @as(u32, send.len + 3);
                if (field_width != 0) try self.addManagerInput(dialog_id, "Message", .{ .x = inner_x + 2, .y = y, .width = field_width, .height = 1 });
                try self.addManagerControl(dialog_id, "agents.send", send, inner_x + inner_width - @as(u32, send.len), y);
                y += 1;
            }
        }
    }

    fn openManager(self: *App) !void {
        if (self.managerVisible() or self.promptsVisible() or self.notificationsVisible() or self.contextMenuVisible() or self.paletteVisible() or
            self.settingsVisible() or self.closeModalActive() or self.rename_tab_id != null or self.ui_pointer_owned or
            self.sidebar_dragging or self.dragged_divider_id != null or self.dragged_tab_id != null) return;
        const canvas = self.ui_canvas.bounds();
        if (canvas.width < 30 or canvas.height < 8) return;
        if (self.search_visible) try self.closeSearch();
        self.composition.cancel();
        _ = takeCommittedText(&self.pending_committed_text);
        try self.window.stopTextInput();
        self.manager_visible = true;
        self.manager_mode = .browse;
        self.manager_scroll = 0;
        self.manager_status_len = 0;
        clearPaletteInput(&self.manager_input);
        // Open on the agent a notification or `agent.focus` chose last, or
        // the presented session's agent.
        self.manager_selected = self.agents.selected_agent orelse
            if (self.agents.agentForSession(self.activePresentation().key, self.presentedSessionId())) |record| record.id else null;
        self.manager_selected_index = 0;
        self.ui_tree.clearFocus();
        try self.composeUi();
        try self.syncTextInput();
        self.invalidateUi();
    }

    fn closeManager(self: *App) !void {
        if (!self.managerVisible()) return;
        self.composition.cancel();
        _ = takeCommittedText(&self.pending_committed_text);
        self.manager_visible = false;
        self.manager_mode = .browse;
        self.manager_status_len = 0;
        clearPaletteInput(&self.manager_input);
        self.ui_tree.clearFocus();
        try self.composeUi();
        try self.syncTextInput();
        self.invalidateUi();
    }

    /// Back to the agent list from a message or a chooser step.
    fn managerBack(self: *App) !void {
        self.composition.cancel();
        self.manager_mode = .browse;
        self.manager_scroll = 0;
        clearPaletteInput(&self.manager_input);
        self.ui_tree.clearFocus();
        try self.refreshActiveUi();
        try self.syncTextInput();
    }

    fn managerFocusInput(self: *App) !void {
        clearPaletteInput(&self.manager_input);
        self.ui_tree.clearFocus();
        try self.composeUi();
        if (self.ui_tree.focus(.{ .value = "agents.input" })) try self.composeUi();
        try self.syncTextInput();
        self.invalidateUi();
    }

    const ManagerMove = enum { previous, next, first, last };

    fn moveManagerSelection(self: *App, move: ManagerMove) !void {
        self.manager_status_len = 0;
        switch (self.manager_mode) {
            .browse => {
                self.rebuildManagerOrder();
                const count = self.manager_count;
                if (count == 0) return self.refreshActiveUi();
                const current = if (self.manager_selected) |id| self.managerIndexOf(id) orelse 0 else 0;
                const target = movedIndex(current, count, move);
                self.manager_selected = self.manager_order[target];
                self.manager_selected_index = target;
            },
            .new_harness, .new_workspace => {
                const count = if (self.manager_mode == .new_harness) self.manager_harness_count else self.workspace_registry.count();
                if (count == 0) return self.refreshActiveUi();
                self.manager_choice_selected = movedIndex(@min(self.manager_choice_selected, count - 1), count, move);
            },
            .message, .new_prompt => return,
        }
        try self.refreshActiveUi();
    }

    fn movedIndex(current: usize, count: usize, move: ManagerMove) usize {
        return switch (move) {
            .first => 0,
            .last => count - 1,
            .next => (current + 1) % count,
            .previous => (current + count - 1) % count,
        };
    }

    fn selectedManagerAgent(self: *App) ?agent.AgentId {
        self.rebuildManagerOrder();
        return self.manager_selected;
    }

    /// Focus: close the manager and show the agent's workspace, tab and pane
    /// (its structured view, when that is what the tab presents).
    fn managerFocus(self: *App, id: agent.AgentId) !void {
        const record = self.agents.registry.get(id) orelse return;
        const key = record.workspace;
        const session_id = record.session;
        try self.closeManager();
        try self.focusSession(key, session_id);
        self.agents.selected_agent = id;
    }

    /// Hang up an owned agent's PTY; the exit arrives like any other and
    /// settles its state. A human's own process is never ended.
    fn hangUpAgent(self: *App, record: *const agent.Agent) void {
        const model = self.workspace_registry.byKey(record.workspace) orelse return;
        const live = model.sessionById(record.session) orelse return;
        const child = live.child() orelse return;
        child.kill(.hangup) catch |err| switch (err) {
            error.Closed => {},
            else => log.warn("could not stop the agent: {s}", .{@errorName(err)}),
        };
    }

    fn managerStop(self: *App, id: agent.AgentId) !void {
        self.manager_selected = id;
        const record = self.agents.registry.get(id) orelse return;
        const name = self.agents.displayName(record);
        if (record.ownership == .observed) {
            self.setManagerStatus("{s} runs in your terminal: stop it there", .{name});
        } else if (record.hasExited()) {
            self.setManagerStatus("{s} has exited", .{name});
        } else {
            self.hangUpAgent(record);
            self.setManagerStatus("stopping {s}", .{name});
        }
        try self.refreshActiveUi();
    }

    /// Restart an exited (or failed) owned agent in its own tab: the same
    /// harness, cwd and initial prompt under a new agent id, its row
    /// replacing the old one.
    fn managerRestart(self: *App, id: agent.AgentId) !void {
        self.manager_selected = id;
        const record = self.agents.registry.get(id) orelse return;
        // Static: it outlives the record a restart replaces.
        const name = self.agents.displayName(record);
        switch (try self.relaunchAgent(id)) {
            .restarted => |runner| {
                self.manager_selected = runner.agent_id;
                self.setManagerStatus("restarted {s}", .{name});
            },
            .refused => |reason| self.setManagerStatus("{s}: {s}", .{ name, reason }),
        }
        try self.refreshActiveUi();
    }

    const RelaunchOutcome = union(enum) {
        restarted: *app_agents.Runner,
        /// Why not, as a short phrase.
        refused: []const u8,
    };

    /// The restart TASK-58's manager and TASK-59's prompts view share:
    /// replace an exited (or failed) owned agent's runner and spawn the same
    /// launch again into its own session.
    fn relaunchAgent(self: *App, id: agent.AgentId) !RelaunchOutcome {
        if (!self.agents.restartable(id)) return .{ .refused = "only an exited agent Conduit started can restart" };
        const record = self.agents.registry.get(id) orelse return .{ .refused = "it is gone" };
        const key = record.workspace;
        const session_id = record.session;
        const model = self.workspace_registry.byKey(key) orelse return .{ .refused = "its workspace is gone" };
        const presentation = self.presentationByKey(key) orelse return .{ .refused = "its workspace is gone" };
        const live = model.sessionById(session_id) orelse return .{ .refused = "its tab is gone" };
        if (live.child()) |child| if (child.state() == .running) return .{ .refused = "still running: stop it first" };
        if (presentation.load != null or presentation.closing) return .{ .refused = "restart deferred: a start is in progress" };
        var request = self.agents.relaunchRequest(id) orelse return .{ .refused = "it has no launch to repeat" };
        request.probe_env = self.agent_spec.env;
        request.home = self.home_dir;
        request.claude_config_dir = self.claude_config_dir;
        request.codex_home = self.codex_home;
        const runner = self.agents.replaceRunner(id, request, .{
            .workspace = key,
            .session = session_id,
            .session_kind = .agent_terminal,
            .scratchpad = model.scratchpadId(),
        }) catch |err| return .{ .refused = @errorName(err) };
        const cwd = self.allocator.dupe(u8, runner.cwd) catch {
            self.agents.spawnFinished(runner, false);
            return .{ .refused = "out of memory" };
        };
        self.startAgentChildIn(presentation, model, session_id, cwd, runner, live.child() != null);
        self.rebuildAgentChoices();
        return .{ .restarted = runner };
    }

    fn managerMessage(self: *App, id: agent.AgentId) !void {
        self.manager_selected = id;
        const record = self.agents.registry.get(id) orelse return;
        const name = self.agents.displayName(record);
        if (record.hasExited()) {
            self.setManagerStatus("{s} has exited", .{name});
            return self.refreshActiveUi();
        }
        if (!record.capabilities.send_input) {
            self.setManagerStatus("message unsupported: {s} takes input only in its terminal", .{name});
            return self.refreshActiveUi();
        }
        self.manager_status_len = 0;
        self.manager_mode = .message;
        try self.managerFocusInput();
    }

    /// Send the typed message to the highlighted agent through its runner's
    /// worker queue, then return to the list.
    fn sendManagerMessage(self: *App) !void {
        const id = self.manager_selected orelse return self.managerBack();
        const text = self.manager_input.text();
        if (text.len == 0) return self.managerBack();
        const record = self.agents.registry.get(id) orelse return self.managerBack();
        const name = self.agents.displayName(record);
        const runner = self.agents.runnerForAgent(id) orelse {
            self.setManagerStatus("{s} takes no messages", .{name});
            return self.managerBack();
        };
        if (runner.sendMessage(text)) {
            self.setManagerStatus("sent to {s}", .{name});
        } else |err| switch (err) {
            error.QueueFull => self.setManagerStatus("{s} is busy: try again", .{name}),
            error.MessageTooLong => self.setManagerStatus("message too long", .{}),
        }
        try self.managerBack();
    }

    /// The new-agent flow's first step: the harnesses `agent.launch` offers.
    fn managerNew(self: *App) !void {
        self.ensureAgentDetection();
        const key = self.workspace_registry.activeKey() orelse return;
        const choices = self.agents.launchChoices(key);
        self.setAgentLaunchChoices();
        var count: usize = 0;
        for (choices) |choice| {
            if (count == self.manager_harness.len) break;
            const parsed = app_agents.Choice.parse(choice.value) orelse continue;
            self.manager_harness[count] = parsed;
            const len = @min(choice.label.len, self.manager_harness_labels[count].len);
            @memcpy(self.manager_harness_labels[count][0..len], choice.label[0..len]);
            self.manager_harness_label_lens[count] = len;
            count += 1;
        }
        self.manager_harness_count = count;
        if (count == 0) {
            self.setManagerStatus("no coding agent found here", .{});
            return self.refreshActiveUi();
        }
        self.manager_status_len = 0;
        self.manager_mode = .new_harness;
        self.manager_choice_selected = 0;
        self.manager_scroll = 0;
        self.ui_tree.clearFocus();
        try self.refreshActiveUi();
    }

    fn managerPickHarness(self: *App, index: usize) !void {
        if (index >= self.manager_harness_count) return;
        self.manager_new_choice = self.manager_harness[index];
        self.manager_mode = .new_workspace;
        self.manager_scroll = 0;
        const active = self.workspace_registry.activeKey();
        self.manager_choice_selected = 0;
        if (active) |key| self.manager_choice_selected = self.workspaceRank(key) orelse 0;
        try self.refreshActiveUi();
    }

    fn managerPickWorkspace(self: *App, index: usize) !void {
        const key = self.workspace_registry.keyAt(index) orelse return;
        self.manager_new_workspace = key;
        self.manager_mode = .new_prompt;
        try self.managerFocusInput();
    }

    /// Launch the chosen harness into a new tab of the chosen workspace,
    /// through `agent.launch`'s own path, and highlight its new row.
    fn launchFromManager(self: *App) !void {
        const choice = self.manager_new_choice orelse return self.managerBack();
        const key = self.manager_new_workspace orelse return self.managerBack();
        if (choice == .fake and !self.agents.fake_enabled) return self.managerBack();
        if (self.workspace_registry.activeKey() != key) {
            if (!try self.activateWorkspaceKey(key, false)) {
                self.setManagerStatus("launch deferred: the workspace could not be shown", .{});
                return self.managerBack();
            }
        }
        const typed = self.manager_input.text();
        const prompt: ?[]const u8 = if (typed.len == 0) null else typed;
        const before = self.agents.registry.next_ordinal;
        try self.launchAgent(choice, prompt);
        self.manager_new_choice = null;
        self.manager_new_workspace = null;
        if (self.agents.registry.next_ordinal != before) {
            const id = agent.AgentId.fromOrdinal(before);
            self.manager_selected = id;
            if (self.agents.registry.get(id)) |record| self.setManagerStatus("launched {s}", .{self.agents.displayName(record)});
        } else if (self.workspace_status) |status| {
            self.setManagerStatus("{s}", .{status});
        }
        try self.managerBack();
    }

    /// Every key while the manager is open. A press is the manager's (no
    /// binding and no terminal beneath sees it); a release or repeat only
    /// settles the binding state a press before it opened left behind.
    fn onManagerKey(self: *App, key: platform.KeyEvent) !void {
        var scratch: inputmod.TextScratch = .{};
        const translated = translateAppKey(&self.composition, &scratch, key);
        if (key.action != .press) {
            _ = inputmod.resolve(&self.binding_state, key, translated, self.bindings);
            return;
        }
        const identity = uiKeyIdentity(key) orelse return;
        const plain = !key.mods.ctrl and !key.mods.alt and !key.mods.super;
        switch (self.manager_mode) {
            .message, .new_prompt => {
                if (plain) switch (key.key) {
                    .enter => {
                        _ = self.ui_key_state.claim(identity, .none);
                        if (self.manager_mode == .message) try self.sendManagerMessage() else try self.launchFromManager();
                        return;
                    },
                    .escape => {
                        _ = self.ui_key_state.claim(identity, .none);
                        return self.managerBack();
                    },
                    .tab, .up, .down => {
                        _ = self.ui_key_state.claim(identity, .none);
                        return;
                    },
                    else => {},
                };
                if (try self.routeFocusedUiKey(key, translated)) return;
                _ = self.ui_key_state.claim(identity, .none);
            },
            .new_harness, .new_workspace => {
                _ = self.ui_key_state.claim(identity, .none);
                if (!plain) return;
                switch (key.key) {
                    .escape => try self.managerBack(),
                    .up => try self.moveManagerSelection(.previous),
                    .down => try self.moveManagerSelection(.next),
                    .tab => try self.moveManagerSelection(if (key.mods.shift) .previous else .next),
                    .home => try self.moveManagerSelection(.first),
                    .end => try self.moveManagerSelection(.last),
                    .enter => if (self.manager_mode == .new_harness)
                        try self.managerPickHarness(self.manager_choice_selected)
                    else
                        try self.managerPickWorkspace(self.manager_choice_selected),
                    else => {},
                }
            },
            .browse => {
                _ = self.ui_key_state.claim(identity, .none);
                if (!plain) return;
                switch (key.key) {
                    .escape => try self.closeManager(),
                    .up => try self.moveManagerSelection(.previous),
                    .down => try self.moveManagerSelection(.next),
                    .tab => try self.moveManagerSelection(if (key.mods.shift) .previous else .next),
                    .home => try self.moveManagerSelection(.first),
                    .end => try self.moveManagerSelection(.last),
                    .enter => if (self.selectedManagerAgent()) |id| try self.managerFocus(id),
                    else => {
                        if (key.mods.shift) return;
                        const codepoint = if (key.unshifted_codepoint != 0) key.unshifted_codepoint else key.codepoint;
                        switch (codepoint) {
                            'n' => try self.managerNew(),
                            's', 'r', 'm' => {
                                const id = self.selectedManagerAgent() orelse return;
                                switch (codepoint) {
                                    's' => try self.managerStop(id),
                                    'r' => try self.managerRestart(id),
                                    else => {
                                        try self.managerMessage(id);
                                        // SDL echoes `m` as text next; the new
                                        // field must not start with it.
                                        if (self.manager_mode == .message) self.key_text_echo.recordKeyText(key, "m");
                                    },
                                }
                            },
                            else => {},
                        }
                    },
                }
            },
        }
    }

    /// What a manager element id names.
    const ManagerTarget = union(enum) {
        row: agent.AgentId,
        stop: agent.AgentId,
        restart: agent.AgentId,
        message: agent.AgentId,
        new,
        back,
        send,
        launch,
        harness: usize,
        workspace: usize,
    };

    fn managerTarget(id: []const u8) ?ManagerTarget {
        if (std.mem.eql(u8, id, "agents.new")) return .new;
        if (std.mem.eql(u8, id, "agents.back")) return .back;
        if (std.mem.eql(u8, id, "agents.send")) return .send;
        if (std.mem.eql(u8, id, "agents.new.launch")) return .launch;
        if (paletteSemanticIndex(id, "agents.new.harness.")) |index| return .{ .harness = index };
        if (paletteSemanticIndex(id, "agents.new.workspace.")) |index| return .{ .workspace = index };
        const prefix = "agents.row.";
        if (!std.mem.startsWith(u8, id, prefix)) return null;
        const rest = id[prefix.len..];
        const dot = std.mem.indexOfScalar(u8, rest, '.');
        const raw = std.fmt.parseUnsigned(u64, rest[0 .. dot orelse rest.len], 10) catch return null;
        if (raw == 0) return null;
        const agent_id: agent.AgentId = @enumFromInt(raw);
        const part = if (dot) |at| rest[at + 1 ..] else return .{ .row = agent_id };
        if (std.mem.eql(u8, part, "stop")) return .{ .stop = agent_id };
        if (std.mem.eql(u8, part, "restart")) return .{ .restart = agent_id };
        if (std.mem.eql(u8, part, "message")) return .{ .message = agent_id };
        return null;
    }

    /// A click on (or the semantic activation of) one manager element.
    fn activateManagerElement(self: *App, id: []const u8) !void {
        if (!self.managerVisible()) return;
        const target = managerTarget(id) orelse return;
        // A click anywhere but the field being typed in ends the typing.
        const typing = self.manager_mode == .message or self.manager_mode == .new_prompt;
        switch (target) {
            .send => if (self.manager_mode == .message) return self.sendManagerMessage(),
            .launch => if (self.manager_mode == .new_prompt) return self.launchFromManager(),
            .back => return self.managerBack(),
            .harness => |index| if (self.manager_mode == .new_harness) return self.managerPickHarness(index),
            .workspace => |index| if (self.manager_mode == .new_workspace) return self.managerPickWorkspace(index),
            else => {},
        }
        if (typing) try self.managerBack();
        switch (target) {
            .row => |agent_id| try self.managerFocus(agent_id),
            .stop => |agent_id| try self.managerStop(agent_id),
            .restart => |agent_id| try self.managerRestart(agent_id),
            .message => |agent_id| try self.managerMessage(agent_id),
            .new => try self.managerNew(),
            else => {},
        }
    }

    /// The manager is modal like the palette: pointer gestures inside it
    /// highlight and activate its rows and controls, a press outside closes
    /// it, and every gesture is owned through release.
    fn handleManagerUiEvent(self: *App, event: platform.Event) !bool {
        const tree = self.activeUiTree();
        switch (event) {
            .mouse_motion => |motion| {
                const point = devicePointerPoint(motion.x, motion.y, self.window.state.scale);
                const before = uiInteractionState(tree);
                tree.pointerMoved(point);
                if (!std.meta.eql(before, uiInteractionState(tree))) try self.refreshActiveUi();
                return true;
            },
            .mouse_button => |button| {
                const point = devicePointerPoint(button.x, button.y, self.window.state.scale);
                switch (button.action) {
                    .press => {
                        self.manager_pointer_owned = true;
                        const bounds = self.managerBounds();
                        if (bounds == null or !self.pointInCellRect(point, bounds.?)) {
                            try self.closeManager();
                            return true;
                        }
                        if (button.button != .left) return true;
                        const before = uiInteractionState(tree);
                        tree.pointerPressed(point);
                        if (!std.meta.eql(before, uiInteractionState(tree))) try self.refreshActiveUi();
                        return true;
                    },
                    .repeat => return true,
                    .release => {
                        if (!self.manager_pointer_owned) return true;
                        self.manager_pointer_owned = false;
                        if (button.button != .left) return true;
                        const before = uiInteractionState(tree);
                        const activation = tree.pointerReleased(point);
                        if (!std.meta.eql(before, uiInteractionState(tree))) try self.refreshActiveUi();
                        const requested = activation orelse return true;
                        if (std.mem.eql(u8, requested.id.value, "agents.input")) return true;
                        var id_storage: [manager_id_capacity]u8 = undefined;
                        if (requested.id.value.len > id_storage.len) return true;
                        @memcpy(id_storage[0..requested.id.value.len], requested.id.value);
                        try self.activateManagerElement(id_storage[0..requested.id.value.len]);
                        return true;
                    },
                }
            },
            .wheel => return true,
            .key => return false,
            // Text and composition reach only the inline field; with no field
            // they are swallowed rather than typed into the terminal beneath.
            .text_input, .text_editing, .candidates => return !(self.manager_mode == .message or self.manager_mode == .new_prompt),
            else => return false,
        }
    }

    fn agentsOpenAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        try self.openManager();
    }

    fn agentsActivateAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const origin = invocation.origin orelse return;
        var id_storage: [manager_id_capacity]u8 = undefined;
        if (origin.value.len > id_storage.len) return;
        @memcpy(id_storage[0..origin.value.len], origin.value);
        try self.activateManagerElement(id_storage[0..origin.value.len]);
    }

    // The prompts view (TASK-59) ----------------------------------------------

    fn promptsVisible(self: *const App) bool {
        return self.prompts_visible;
    }

    /// The agent the prompts view is about when no element names one: the
    /// presented pane's agent, the one the view showed last, the one a
    /// notification or `agent.focus` chose, then the first agent.
    fn defaultPromptsAgent(self: *App) ?agent.AgentId {
        if (self.presentedAgentRunner()) |runner| if (runner.agent_id) |id| return id;
        if (self.prompts_agent) |id| if (self.agents.registry.get(id) != null) return id;
        if (self.agents.selected_agent) |id| if (self.agents.registry.get(id) != null) return id;
        const all = self.agents.registry.all();
        return if (all.len != 0) all[0].id else null;
    }

    fn promptsStatus(self: *const App) []const u8 {
        return self.prompts_status_storage[0..self.prompts_status_len];
    }

    fn setPromptsStatus(self: *App, comptime format: []const u8, args: anytype) void {
        var writer: std.Io.Writer = .fixed(&self.prompts_status_storage);
        writer.print(format, args) catch {
            // A status cut by the fixed buffer is still its start.
        };
        var len = writer.end;
        while (len != 0 and !std.unicode.utf8ValidateSlice(self.prompts_status_storage[0..len])) len -= 1;
        self.prompts_status_len = len;
    }

    fn promptsItems(self: *const App) []const agent_prompts.Item {
        const list = &(self.prompts_list orelse return &.{});
        return list.items.items;
    }

    /// Where the agent's instructions are looked for: its session's tracked
    /// cwd, else the cwd it was launched in, else the workspace's.
    fn promptsCwd(self: *App, record: *const agent.Agent) ?[]const u8 {
        const model = self.workspace_registry.byKey(record.workspace) orelse return null;
        if (model.sessionById(record.session)) |live| if (live.workingDirectory()) |cwd| return cwd;
        if (self.agents.runnerForAgent(record.id)) |runner| return runner.cwd;
        return model.workingDirectory();
    }

    /// Start (or queue) a discovery of the agent's instruction files on a
    /// worker, through its workspace's ExecutionContext. A discovery still
    /// running is never joined here: the next one is queued behind it.
    fn refreshPrompts(self: *App) void {
        if (self.prompts_job != null) {
            self.prompts_refresh_pending = true;
            return;
        }
        const id = self.prompts_agent orelse return;
        const record = self.agents.registry.get(id) orelse return;
        const model = self.workspace_registry.byKey(record.workspace) orelse return;
        if (self.presentationByKey(record.workspace)) |presentation| {
            if (presentation.remote) |connection| if (!connection.ready()) {
                self.setPromptsStatus("the workspace is not connected", .{});
                return;
            };
        }
        const cwd = self.promptsCwd(record) orelse return;
        const remote_context = model.contextKind().isRemote();
        self.prompts_job = agent_prompts.Job.start(self.allocator, self.io, .{
            .context = model.contextRef(),
            .profile = agent.instructionProfile(record.harness),
            .cwd = cwd,
            .home = if (remote_context) null else self.home_dir,
            .resolve_home = remote_context,
        }) catch |err| {
            log.warn("the instruction files could not be listed: {s}", .{@errorName(err)});
            self.setPromptsStatus("the instruction files could not be listed", .{});
            return;
        };
    }

    /// Take a finished discovery: its files, then the agent's prompts from
    /// its runner (the launch prompt and the human's messages in its log).
    fn takePromptsDiscovery(self: *App) void {
        const job = self.prompts_job orelse return;
        if (!job.finished()) return;
        var list = job.take();
        job.destroy();
        self.prompts_job = null;
        if (self.prompts_agent) |id| {
            if (self.agents.registry.get(id)) |record| {
                const runner = self.agents.runnerForAgent(id);
                var sent: [agent_prompts.max_items][]const u8 = undefined;
                var sent_count: usize = 0;
                if (runner) |owner| {
                    const event_log = &owner.view.log;
                    for (0..event_log.count()) |index| {
                        const entry = event_log.at(index);
                        if (entry.event != .message or entry.event.message.role != .user) continue;
                        if (sent_count == sent.len) break;
                        sent[sent_count] = entry.event.message.text;
                        sent_count += 1;
                    }
                }
                agent_prompts.addPrompts(&list, agent.instructionProfile(record.harness), if (runner) |owner| owner.prompt else null, sent[0..sent_count]) catch |err| {
                    log.warn("the agent's prompts were not listed: {s}", .{@errorName(err)});
                };
            }
        }
        if (self.prompts_list) |*old| old.deinit();
        self.prompts_list = list;
        const count = self.promptsItems().len;
        if (self.prompts_selected >= count) self.prompts_selected = count -| 1;
        if (self.prompts_refresh_pending) {
            self.prompts_refresh_pending = false;
            self.refreshPrompts();
        }
    }

    /// Owner-thread service: a finished discovery, an editor that exited
    /// (its file is read again), and a restart waiting for the agent to
    /// stop. Returns whether the view changed.
    fn pollPrompts(self: *App) bool {
        var changed = false;
        if (self.prompts_job) |job| if (job.finished()) {
            self.takePromptsDiscovery();
            changed = true;
        };
        if (self.prompts_editor) |editor| {
            const ended = ended: {
                const model = self.workspace_registry.byKey(editor.key) orelse break :ended true;
                const live = model.sessionById(editor.session) orelse break :ended true;
                const child = live.child() orelse break :ended false;
                break :ended child.state() != .running;
            };
            if (ended) {
                self.prompts_editor = null;
                self.setPromptsStatus("the editor closed: the list was read again", .{});
                self.refreshPrompts();
                changed = true;
            }
        }
        if (self.prompts_restart) |id| {
            if (self.agents.registry.get(id) == null) {
                self.prompts_restart = null;
            } else if (self.agents.restartable(id)) {
                self.prompts_restart = null;
                self.restartFromPrompts(id) catch |err| log.warn("the agent was not restarted: {s}", .{@errorName(err)});
                changed = true;
            }
        }
        return changed;
    }

    fn promptsListRows(self: *const App) usize {
        return @max(self.promptsItems().len, 1);
    }

    fn promptsBounds(self: *const App) ?ui.Rect {
        if (!self.prompts_visible) return null;
        const canvas = self.ui_canvas.bounds();
        if (canvas.width < 40 or canvas.height < 12) return null;
        const width = @min(canvas.width - 2, @as(u32, 100));
        const list: u32 = @intCast(@min(self.promptsListRows(), prompts_visible_capacity));
        // Two borders, the heading, three preview rows, the apply row, the
        // status line and the hint.
        const height = @min(list + 9, canvas.height - 2);
        return .{
            .x = (canvas.width - width) / 2,
            .y = (canvas.height - height) / 2,
            .width = width,
            .height = height,
        };
    }

    /// The id of one prompts element, in this frame's storage (two
    /// generations, like the manager's, so an id's bytes never change under
    /// the tree).
    fn promptsId(self: *App, slot: usize, comptime format: []const u8, args: anytype) ![]const u8 {
        const generation = self.prompts_generation % 2;
        return std.fmt.bufPrint(&self.prompts_ids[generation][slot], format, args);
    }

    fn addPromptsControl(self: *App, parent: ui.Id, id_text: []const u8, label: []const u8, x: u32, y: u32) !void {
        const id: ui.Id = .{ .value = id_text };
        try self.ui_tree.addInteractiveText(.{
            .id = id,
            .parent = parent,
            .role = "button",
            .label = label,
            .action = agent_prompts_activate_action,
            .bounds = .{ .x = x, .y = y, .width = agent_view.displayCells(label), .height = 1 },
        }, .{
            .id = id,
            .label = label,
            .action = agent_prompts_activate_action,
            .normal = .{ .foreground = .accent },
            .hovered = .{ .foreground = .strong, .underline = .accent },
            .focused = .{ .foreground = .on_accent, .background = .accent },
        });
    }

    /// The view is a `Surface` panel: a heading naming the agent, one
    /// `InteractiveText` row per item (its name, size and whether it is
    /// editable or why not), a preview of the highlighted item, the apply
    /// row, a status line and a key hint.
    fn composePrompts(self: *App) !void {
        const bounds = self.promptsBounds() orelse return;
        const id = self.prompts_agent orelse return;
        const number = @intFromEnum(id);
        self.prompts_generation +%= 1;
        const record = self.agents.registry.get(id);
        const dialog_id: ui.Id = .{ .value = try self.promptsId(0, "agent.prompts.{d}", .{number}) };
        try self.ui_tree.addSurface(.{
            .id = dialog_id,
            .role = "dialog",
            .label = "Prompts and instructions",
            .bounds = bounds,
        }, .{
            .rect = bounds,
            .erase_underlay = true,
            .fill = .background,
            .border = .double,
            .border_style = .{ .foreground = .border, .background = .background },
            .title = " Prompts and instructions ",
            .title_style = .{ .foreground = .strong, .background = .background, .face_style = .bold },
        });
        const inner_x = bounds.x + 2;
        const inner_width = bounds.width - 4;
        const muted: ui.TextStyle = .{ .foreground = .muted };

        const heading = if (record) |found| blk: {
            const cwd = self.promptsCwd(found) orelse "?";
            var writer: std.Io.Writer = .fixed(&self.prompts_heading);
            writer.print("{s} {s} #{d}  {s}", .{ app_agents.stateGlyph(found.state), self.agents.displayName(found), number, cwd }) catch {};
            var len = writer.end;
            while (len != 0 and !std.unicode.utf8ValidateSlice(self.prompts_heading[0..len])) len -= 1;
            break :blk self.prompts_heading[0..len];
        } else "the agent is gone";
        const refresh_label = "refresh";
        try self.addManagerText(dialog_id, try self.promptsId(1, "agent.prompts.{d}.heading", .{number}), "heading", heading, muted, .{ .x = inner_x, .y = bounds.y + 1, .width = inner_width -| @as(u32, refresh_label.len + 1), .height = 1 });
        try self.addPromptsControl(dialog_id, try self.promptsId(2, "agent.prompts.{d}.refresh", .{number}), refresh_label, inner_x + inner_width - @as(u32, refresh_label.len), bounds.y + 1);

        const list_top = bounds.y + 2;
        const footer_rows: u32 = 7;
        const available: usize = if (bounds.height > footer_rows + 2) bounds.height - footer_rows - 2 else 0;
        const items = self.promptsItems();
        if (items.len == 0) {
            const empty = if (self.prompts_job != null)
                "looking for instruction files…"
            else if (self.prompts_list) |list| list.problem orelse "nothing to show" else "nothing to show";
            try self.addManagerText(dialog_id, try self.promptsId(3, "agent.prompts.{d}.empty", .{number}), "status", empty, muted, .{ .x = inner_x, .y = list_top, .width = inner_width, .height = 1 });
        }
        if (self.prompts_selected < self.prompts_scroll) self.prompts_scroll = self.prompts_selected;
        if (available != 0 and self.prompts_selected >= self.prompts_scroll + available) self.prompts_scroll = self.prompts_selected + 1 - available;
        const end = @min(items.len, self.prompts_scroll + available);
        for (self.prompts_scroll..end, 0..) |index, slot| {
            const item = &items[index];
            const label = agent_prompts.formatRow(&self.prompts_labels[slot], item, inner_width);
            const row_id: ui.Id = .{ .value = try self.promptsId(prompts_fixed_slots + slot, "agent.prompts.{d}.item.{d}", .{ number, index }) };
            const selected = index == self.prompts_selected;
            try self.ui_tree.addInteractiveText(.{
                .id = row_id,
                .parent = dialog_id,
                .role = if (item.kind.isFile()) "file" else "prompt",
                .label = label,
                .selected = selected,
                .action = agent_prompts_activate_action,
                .bounds = .{ .x = inner_x, .y = list_top + @as(u32, @intCast(slot)), .width = inner_width, .height = 1 },
            }, .{
                .id = row_id,
                .label = label,
                .action = agent_prompts_activate_action,
                .normal = if (selected)
                    .{ .foreground = .strong, .background = .selection }
                else if (item.editable())
                    .{ .foreground = .foreground }
                else
                    .{ .foreground = .muted },
                .hovered = if (selected)
                    .{ .foreground = .strong, .background = .selection, .underline = .accent }
                else
                    .{ .foreground = .strong, .underline = .accent },
                .focused = .{ .foreground = .on_accent, .background = .accent },
            });
        }

        // The preview: a file's full path and what Enter does, or a
        // prompt's text wrapped over the three rows.
        const preview_top = bounds.y + bounds.height - footer_rows;
        var preview_lines: [3][]const u8 = .{ "", "", "" };
        if (self.prompts_selected < items.len) {
            const item = &items[self.prompts_selected];
            if (item.kind.isFile()) {
                preview_lines[0] = item.value;
                preview_lines[1] = if (item.reason == .read_only_host)
                    "the context cannot read it"
                else if (item.editable())
                    (if (item.exists) "Enter opens it in vi in a new tab" else "Enter creates it in vi in a new tab")
                else
                    "Enter views it read-only in vi; the harness owns this file";
            } else if (item.kind == .system_prompt) {
                preview_lines[0] = "the harness keeps its system prompt to itself";
            } else {
                var rest: []const u8 = item.value;
                for (&preview_lines) |*line| {
                    if (rest.len == 0) break;
                    const cut = agent_view.byteAtCell(rest, inner_width);
                    if (cut == 0) break;
                    const piece = rest[0..cut];
                    const newline = std.mem.indexOfScalar(u8, piece, '\n');
                    line.* = if (newline) |at| piece[0..at] else piece;
                    rest = rest[if (newline) |at| at + 1 else cut..];
                }
            }
        }
        // Copied: the list they point into may be replaced before the tree
        // lets go of this frame.
        for (&preview_lines, &self.prompts_preview) |*line, *storage| {
            const kept = agent.truncateUtf8(line.*, storage.len);
            @memcpy(storage[0..kept.len], kept);
            line.* = storage[0..kept.len];
        }
        for (preview_lines, 0..) |line, row| {
            if (line.len == 0) continue;
            try self.addManagerText(dialog_id, try self.promptsId(4 + row, "agent.prompts.{d}.preview.{d}", .{ number, row }), "status", line, muted, .{ .x = inner_x, .y = preview_top + @as(u32, @intCast(row)), .width = inner_width, .height = 1 });
        }

        // How an edit reaches the agent: a restart where the harness reads
        // its instructions at session start, otherwise the next session.
        const apply_y = preview_top + 3;
        const apply_id = try self.promptsId(7, "agent.prompts.{d}.apply", .{number});
        const restart_applies = if (record) |found| agent.instructionProfile(found.harness).apply == .restart and found.ownership == .owned else false;
        if (restart_applies) {
            try self.addPromptsControl(dialog_id, apply_id, prompts_apply_label, inner_x, apply_y);
        } else {
            try self.addManagerText(dialog_id, apply_id, "status", "edits take effect on the next session", muted, .{ .x = inner_x, .y = apply_y, .width = inner_width, .height = 1 });
        }
        if (self.prompts_status_len != 0) {
            try self.addManagerText(dialog_id, try self.promptsId(8, "agent.prompts.{d}.status", .{number}), "status", self.promptsStatus(), .{ .foreground = .attention }, .{ .x = inner_x, .y = apply_y + 1, .width = inner_width, .height = 1 });
        }
        try self.addManagerText(dialog_id, try self.promptsId(9, "agent.prompts.{d}.hint", .{number}), "status", if (restart_applies) prompts_hint_restart else prompts_hint, muted, .{ .x = inner_x, .y = apply_y + 2, .width = inner_width, .height = 1 });
    }

    fn openPrompts(self: *App, id: agent.AgentId) !void {
        // No `ui_pointer_owned` guard: the agent view's prompts row opens
        // the view from that very click's release.
        if (self.promptsVisible() or self.managerVisible() or self.notificationsVisible() or self.contextMenuVisible() or self.paletteVisible() or
            self.settingsVisible() or self.closeModalActive() or self.rename_tab_id != null or
            self.sidebar_dragging or self.dragged_divider_id != null or self.dragged_tab_id != null) return;
        if (self.agents.registry.get(id) == null) return;
        const canvas = self.ui_canvas.bounds();
        if (canvas.width < 40 or canvas.height < 12) return;
        if (self.search_visible) try self.closeSearch();
        self.composition.cancel();
        _ = takeCommittedText(&self.pending_committed_text);
        try self.window.stopTextInput();
        if (self.prompts_agent != id) {
            if (self.prompts_list) |*old| old.deinit();
            self.prompts_list = null;
            self.prompts_selected = 0;
        }
        self.prompts_agent = id;
        self.prompts_visible = true;
        self.prompts_scroll = 0;
        self.prompts_status_len = 0;
        self.refreshPrompts();
        self.ui_tree.clearFocus();
        try self.composeUi();
        try self.syncTextInput();
        self.invalidateUi();
    }

    fn closePrompts(self: *App) !void {
        if (!self.promptsVisible()) return;
        self.composition.cancel();
        _ = takeCommittedText(&self.pending_committed_text);
        self.prompts_visible = false;
        self.ui_tree.clearFocus();
        try self.composeUi();
        try self.syncTextInput();
        self.invalidateUi();
    }

    const PromptsMove = enum { previous, next, first, last };

    fn movePromptsSelection(self: *App, move: PromptsMove) !void {
        const count = self.promptsItems().len;
        if (count == 0) return self.refreshActiveUi();
        self.prompts_status_len = 0;
        const current = @min(self.prompts_selected, count - 1);
        self.prompts_selected = switch (move) {
            .first => 0,
            .last => count - 1,
            .next => (current + 1) % count,
            .previous => (current + count - 1) % count,
        };
        try self.refreshActiveUi();
    }

    /// Enter or a click on an item: a file opens in `vi` in a new tab of the
    /// agent's workspace, through its ExecutionContext (so an SSH
    /// workspace's file is edited on its host), read-only (`vi -R`) when the
    /// harness owns it. A prompt or the system prompt only says why it
    /// cannot be edited. Nothing in an item's text runs.
    fn activatePromptsItem(self: *App, index: usize) !void {
        const items = self.promptsItems();
        if (index >= items.len) return;
        self.prompts_selected = index;
        const item = items[index];
        if (!item.kind.isFile()) {
            const reason: agent_prompts.Reason = item.reason orelse .sent;
            self.setPromptsStatus("read-only: {s}", .{reason.text()});
            return self.refreshActiveUi();
        }
        if (item.reason == .read_only_host) {
            self.setPromptsStatus("read-only on this host: it cannot be read here", .{});
            return self.refreshActiveUi();
        }
        const id = self.prompts_agent orelse return;
        const record = self.agents.registry.get(id) orelse return;
        const key = record.workspace;
        var path_storage: [file_reference_path_max_bytes]u8 = undefined;
        if (item.value.len > path_storage.len) return;
        @memcpy(path_storage[0..item.value.len], item.value);
        const path = path_storage[0..item.value.len];
        const read_only = !item.editable();
        const cwd_text = self.promptsCwd(record) orelse return;
        var cwd_storage: [file_reference_path_max_bytes]u8 = undefined;
        if (cwd_text.len > cwd_storage.len) return;
        @memcpy(cwd_storage[0..cwd_text.len], cwd_text);
        try self.closePrompts();
        if (self.workspace_registry.activeKey() != key) {
            if (!try self.activateWorkspaceKey(key, false)) {
                self.setWorkspaceStatus("the agent's workspace could not be shown");
                return;
            }
        }
        if (self.activePresentation().load != null) {
            self.setWorkspaceStatus("editor deferred: a start is in progress");
            return;
        }
        if (self.remoteNotReady()) return;
        const argv = try buildInstructionEditorArgv(self.allocator, path, read_only);
        const cwd = self.allocator.dupe(u8, cwd_storage[0..cwd_text.len]) catch |err| {
            freeEntries(self.allocator, argv);
            return err;
        };
        if (!try self.openEditorTab(std.fs.path.basenamePosix(path), cwd, argv)) return;
        const model = self.activeWorkspace();
        const tab_id = model.activeTabId() orelse return;
        if (model.focusedPaneSessionId(tab_id)) |session_id| self.prompts_editor = .{ .key = key, .session = session_id };
        self.setPromptsStatus("{s} {s} in a new tab", .{ if (read_only) "viewing" else "editing", std.fs.path.basenamePosix(path) });
    }

    /// Apply: restart the agent so its harness reads the edited files at its
    /// new session start, through the manager's restart (same harness, cwd,
    /// prompt and task, a new agent id). A running agent is stopped first and
    /// restarted once its exit arrives.
    fn applyPrompts(self: *App) !void {
        const id = self.prompts_agent orelse return;
        const record = self.agents.registry.get(id) orelse return;
        const name = self.agents.displayName(record);
        if (agent.instructionProfile(record.harness).apply != .restart) {
            self.setPromptsStatus("{s} reads its instructions at session start: edits take effect on the next session", .{name});
            return self.refreshActiveUi();
        }
        if (record.ownership != .owned) {
            self.setPromptsStatus("{s} runs in your terminal: restart it there", .{name});
            return self.refreshActiveUi();
        }
        if (self.agents.restartable(id)) return self.restartFromPrompts(id);
        if (record.hasExited()) {
            self.setPromptsStatus("{s} cannot restart yet", .{name});
            return self.refreshActiveUi();
        }
        self.prompts_restart = id;
        self.hangUpAgent(record);
        self.setPromptsStatus("stopping {s} to restart it with the updated instructions", .{name});
        try self.refreshActiveUi();
    }

    fn restartFromPrompts(self: *App, id: agent.AgentId) !void {
        const record = self.agents.registry.get(id) orelse return;
        // A static name: it outlives the record the restart replaces.
        const name = self.agents.displayName(record);
        switch (try self.relaunchAgent(id)) {
            .restarted => |runner| {
                if (self.prompts_agent == id) self.prompts_agent = runner.agent_id;
                self.setPromptsStatus("restarted {s} with the updated instructions", .{name});
                self.refreshPrompts();
            },
            .refused => |reason| self.setPromptsStatus("{s} did not restart: {s}", .{ name, reason }),
        }
        if (self.promptsVisible()) try self.refreshActiveUi() else self.invalidateUi();
    }

    /// Every key while the prompts view is open: the view's own, nothing
    /// else's (modal like the manager).
    fn onPromptsKey(self: *App, key: platform.KeyEvent) !void {
        var scratch: inputmod.TextScratch = .{};
        const translated = translateAppKey(&self.composition, &scratch, key);
        if (key.action != .press) {
            _ = inputmod.resolve(&self.binding_state, key, translated, self.bindings);
            return;
        }
        const identity = uiKeyIdentity(key) orelse return;
        _ = self.ui_key_state.claim(identity, .none);
        const plain = !key.mods.ctrl and !key.mods.alt and !key.mods.super;
        if (!plain) return;
        switch (key.key) {
            .escape => try self.closePrompts(),
            .up => try self.movePromptsSelection(.previous),
            .down => try self.movePromptsSelection(.next),
            .tab => try self.movePromptsSelection(if (key.mods.shift) .previous else .next),
            .home => try self.movePromptsSelection(.first),
            .end => try self.movePromptsSelection(.last),
            .enter => try self.activatePromptsItem(self.prompts_selected),
            else => {
                if (key.mods.shift) return;
                const codepoint = if (key.unshifted_codepoint != 0) key.unshifted_codepoint else key.codepoint;
                switch (codepoint) {
                    'a' => try self.applyPrompts(),
                    'r' => {
                        self.prompts_status_len = 0;
                        self.refreshPrompts();
                        try self.refreshActiveUi();
                    },
                    else => {},
                }
            },
        }
    }

    const PromptsTarget = union(enum) { item: usize, apply, refresh };

    fn promptsTarget(self: *const App, id: []const u8) ?PromptsTarget {
        const agent_id = self.prompts_agent orelse return null;
        var prefix_buffer: [prompts_id_capacity]u8 = undefined;
        const prefix = std.fmt.bufPrint(&prefix_buffer, "agent.prompts.{d}.", .{@intFromEnum(agent_id)}) catch return null;
        if (!std.mem.startsWith(u8, id, prefix)) return null;
        const rest = id[prefix.len..];
        if (std.mem.eql(u8, rest, "apply")) return .apply;
        if (std.mem.eql(u8, rest, "refresh")) return .refresh;
        if (paletteSemanticIndex(rest, "item.")) |index| return .{ .item = index };
        return null;
    }

    fn activatePromptsElement(self: *App, id: []const u8) !void {
        if (!self.promptsVisible()) return;
        const target = self.promptsTarget(id) orelse return;
        switch (target) {
            .item => |index| try self.activatePromptsItem(index),
            .apply => try self.applyPrompts(),
            .refresh => {
                self.prompts_status_len = 0;
                self.refreshPrompts();
                try self.refreshActiveUi();
            },
        }
    }

    /// Modal like the manager: pointer gestures inside it highlight and
    /// activate its rows and controls, a press outside closes it, and every
    /// gesture is owned through release.
    fn handlePromptsUiEvent(self: *App, event: platform.Event) !bool {
        const tree = self.activeUiTree();
        switch (event) {
            .mouse_motion => |motion| {
                const point = devicePointerPoint(motion.x, motion.y, self.window.state.scale);
                const before = uiInteractionState(tree);
                tree.pointerMoved(point);
                if (!std.meta.eql(before, uiInteractionState(tree))) try self.refreshActiveUi();
                return true;
            },
            .mouse_button => |button| {
                const point = devicePointerPoint(button.x, button.y, self.window.state.scale);
                switch (button.action) {
                    .press => {
                        self.prompts_pointer_owned = true;
                        const bounds = self.promptsBounds();
                        if (bounds == null or !self.pointInCellRect(point, bounds.?)) {
                            try self.closePrompts();
                            return true;
                        }
                        if (button.button != .left) return true;
                        const before = uiInteractionState(tree);
                        tree.pointerPressed(point);
                        if (!std.meta.eql(before, uiInteractionState(tree))) try self.refreshActiveUi();
                        return true;
                    },
                    .repeat => return true,
                    .release => {
                        if (!self.prompts_pointer_owned) return true;
                        self.prompts_pointer_owned = false;
                        if (button.button != .left) return true;
                        const before = uiInteractionState(tree);
                        const activation = tree.pointerReleased(point);
                        if (!std.meta.eql(before, uiInteractionState(tree))) try self.refreshActiveUi();
                        const requested = activation orelse return true;
                        var id_storage: [prompts_id_capacity]u8 = undefined;
                        if (requested.id.value.len > id_storage.len) return true;
                        @memcpy(id_storage[0..requested.id.value.len], requested.id.value);
                        try self.activatePromptsElement(id_storage[0..requested.id.value.len]);
                        return true;
                    },
                }
            },
            .wheel => return true,
            .key => return false,
            // No field: text and composition reach nobody.
            .text_input, .text_editing, .candidates => return true,
            else => return false,
        }
    }

    /// `agent.prompts`: from the agent view's prompts row (whose id names
    /// the agent), the palette or a binding (the presented agent, else the
    /// last one shown).
    fn agentPromptsAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        var chosen: ?agent.AgentId = null;
        if (invocation.origin) |origin| {
            const prefix = "agent.view.";
            if (std.mem.startsWith(u8, origin.value, prefix)) {
                const rest = origin.value[prefix.len..];
                const dot = std.mem.indexOfScalar(u8, rest, '.') orelse rest.len;
                const raw = std.fmt.parseUnsigned(u64, rest[0..dot], 10) catch 0;
                if (raw != 0) chosen = @enumFromInt(raw);
            }
        }
        const id = chosen orelse self.defaultPromptsAgent() orelse {
            self.setWorkspaceStatus("no agent to show prompts for");
            try self.refreshActiveUi();
            return;
        };
        try self.openPrompts(id);
    }

    fn agentPromptsActivateAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const origin = invocation.origin orelse return;
        var id_storage: [prompts_id_capacity]u8 = undefined;
        if (origin.value.len > id_storage.len) return;
        @memcpy(id_storage[0..origin.value.len], origin.value);
        try self.activatePromptsElement(id_storage[0..origin.value.len]);
    }

    // The backlog view (TASK-63, TASK-64) -------------------------------------

    /// The active workspace's panel, when its view is open.
    fn shownBacklog(self: *App) ?*backlog_view.Panel {
        if (self.workspace_registry.count() == 0) return null;
        const panel = self.activePresentation().backlog orelse return null;
        return if (panel.open) panel else null;
    }

    fn backlogShown(self: *const App) bool {
        if (self.workspace_registry.count() == 0) return false;
        const panel = self.activePresentationConst().backlog orelse return false;
        return panel.open;
    }

    /// Whether the loop should wake on `backlog_tick_ms` to look for changed
    /// files or a finished write.
    fn backlogNeedsTick(self: *const App) bool {
        for (self.workspace_presentations.items) |presentation| {
            const panel = presentation.backlog orelse continue;
            if (panel.open or panel.busy()) return true;
        }
        return false;
    }

    /// Poll every open view's files and every write in flight; true when the
    /// active workspace's view changed.
    fn pollBacklog(self: *App) bool {
        const active = self.workspace_registry.activeKey();
        var changed = false;
        for (self.workspace_presentations.items) |presentation| {
            const panel = presentation.backlog orelse continue;
            if (!panel.open and !panel.busy()) continue;
            const panel_changed = panel.poll(self.backlog_program) catch |err| {
                log.warn("the backlog could not be refreshed: {s}", .{@errorName(err)});
                continue;
            };
            if (panel_changed and active != null and presentation.key == active.?) changed = true;
        }
        return changed;
    }

    /// The worker's wake: post an event so a blocked loop collects the write.
    fn backlogWake(context: ?*anyopaque) void {
        const self: *App = @ptrCast(@alignCast(context.?));
        self.window.postDriverWake() catch |err| {
            log.debug("could not wake the event loop for a backlog write: {s}", .{@errorName(err)});
        };
    }

    /// `<dir>/backlog` for the active session's tracked cwd, else the
    /// workspace's directory, else (an unnamed Local workspace) this
    /// process's own directory.
    fn backlogRoot(self: *App, buffer: []u8) ?[]const u8 {
        const dir = self.activeLive().workingDirectory() orelse self.activeWorkspace().workingDirectory();
        if (dir.len != 0) return backlog.Project.rootFor(buffer, dir) catch null;
        const cwd = std.process.currentPathAlloc(self.io, self.allocator) catch return null;
        defer self.allocator.free(cwd);
        return backlog.Project.rootFor(buffer, cwd) catch null;
    }

    fn openBacklog(self: *App) !void {
        if (self.workspace_registry.count() == 0 or self.backlogShown()) return;
        if (self.closeModalActive() or self.rename_tab_id != null or self.ui_pointer_owned or self.sidebar_dragging or
            self.dragged_divider_id != null or self.dragged_tab_id != null) return;
        const presentation = self.activePresentation();
        const model = self.activeWorkspace();
        const panel = presentation.backlog orelse created: {
            const created = try self.allocator.create(backlog_view.Panel);
            created.* = backlog_view.Panel.init(self.allocator, self.io, .{ .context = self, .wake_fn = backlogWake });
            presentation.backlog = created;
            break :created created;
        };
        if (self.search_visible) try self.closeSearch();
        self.composition.cancel();
        _ = takeCommittedText(&self.pending_committed_text);
        panel.open = true;
        panel.detail = null;
        panel.message_len = 0;
        panel.state.follow = true;
        self.backlog_hover_armed = false;
        if (model.contextKind() != .local) {
            panel.unload();
            panel.problem = .remote;
        } else {
            var root_buffer: [Dir.max_path_bytes]u8 = undefined;
            if (self.backlogRoot(&root_buffer)) |root| {
                try panel.load(model.contextRef(), root);
            } else {
                panel.unload();
                panel.problem = .unreadable;
            }
        }
        // The detail's start-agent chooser lists what detection found.
        self.ensureAgentDetection();
        self.ui_tree.clearFocus();
        try self.composeUi();
        try self.syncTextInput();
        self.invalidateUi();
    }

    fn closeBacklog(self: *App) !void {
        const panel = self.shownBacklog() orelse return;
        panel.open = false;
        panel.detail = null;
        panel.unload();
        self.ui_tree.clearFocus();
        try self.composeUi();
        try self.syncTextInput();
        self.invalidateUi();
    }

    fn backlogOpenAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        if (self.backlogShown()) return self.closeBacklog();
        try self.openBacklog();
    }

    fn backlogActivateAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const origin = invocation.origin orelse return;
        var id_storage: [backlog_id_capacity]u8 = undefined;
        if (origin.value.len > id_storage.len) return;
        @memcpy(id_storage[0..origin.value.len], origin.value);
        try self.activateBacklogElement(id_storage[0..origin.value.len]);
    }

    /// The pane area the view covers: every visible pane of the active tab.
    fn backlogBounds(self: *const App) ?ui.Rect {
        if (!self.backlogShown()) return null;
        var left: u32 = std.math.maxInt(u32);
        var top: u32 = std.math.maxInt(u32);
        var right: u32 = 0;
        var bottom: u32 = 0;
        for (self.pane_layouts[0..self.pane_layout_count]) |layout| {
            if (layout.pane_id == connection_pane_id) continue;
            left = @min(left, layout.rect.col);
            top = @min(top, layout.rect.row);
            right = @max(right, @as(u32, layout.rect.col) + layout.rect.cols);
            bottom = @max(bottom, @as(u32, layout.rect.row) + layout.rect.rows);
        }
        if (right <= left or bottom <= top) return null;
        if (right - left < 24 or bottom - top < 8) return null;
        return .{ .x = left, .y = top, .width = right - left, .height = bottom - top };
    }

    /// The task detail, centred over the view.
    fn backlogDetailBounds(view: ui.Rect) ?ui.Rect {
        if (view.width < 24 or view.height < 10) return null;
        const width = @min(view.width - 2, @as(u32, 78));
        return .{ .x = view.x + (view.width - width) / 2, .y = view.y + 1, .width = width, .height = view.height - 2 };
    }

    /// What one agent working on a task shows, and its state's tag for the
    /// semantic-only `.agent.<state>` element.
    const BacklogAgent = struct { badge: backlog_view.AgentBadge, tag: []const u8 };

    /// The agent started on task `task_id` of the project in `project_dir`:
    /// a live one before an exited one, then the newest. Matching the
    /// project directory keeps two projects' `TASK-1` apart.
    fn backlogAgent(self: *App, project_dir: []const u8, task_id: []const u8) ?BacklogAgent {
        var best: ?*const agent.Agent = null;
        for (self.agents.runners.items) |runner| {
            if (runner.closing) continue;
            const id = runner.agent_id orelse continue;
            const task = runner.taskId() orelse continue;
            if (!std.ascii.eqlIgnoreCase(task, task_id) or !std.mem.eql(u8, runner.cwd, project_dir)) continue;
            const record = self.agents.registry.get(id) orelse continue;
            if (best) |current| {
                const better = (current.hasExited() and !record.hasExited()) or
                    (current.hasExited() == record.hasExited() and @intFromEnum(record.id) > @intFromEnum(current.id));
                if (!better) continue;
            }
            best = record;
        }
        const record = best orelse return null;
        return .{
            .badge = .{
                .glyph = app_agents.stateGlyph(record.state),
                .harness = self.agents.displayName(record),
                .state = app_agents.managerStateWord(record),
            },
            .tag = if (record.hasExited()) "exited" else @tagName(record.state),
        };
    }

    fn addBacklogText(self: *App, parent: ui.Id, id_text: []const u8, role: []const u8, text: []const u8, style: ui.TextStyle, bounds: ui.Rect) !void {
        const runs = [_]ui.Run{.{ .text = text, .style = style }};
        try self.ui_tree.addText(.{
            .id = .{ .value = id_text },
            .parent = parent,
            .role = role,
            .label = text,
            .bounds = bounds,
        }, .{ .runs = &runs });
    }

    /// One clickable row or control of the view. Hover shows only once the
    /// pointer has moved over the view.
    fn addBacklogInteractive(self: *App, parent: ui.Id, id_text: []const u8, role: []const u8, label: []const u8, selected: bool, normal: ui.TextStyle, bounds: ui.Rect) !void {
        const id: ui.Id = .{ .value = id_text };
        const highlighted: ui.TextStyle = .{ .foreground = .strong, .background = .selection };
        const resting = if (selected) highlighted else normal;
        var hovered = resting;
        if (self.backlog_hover_armed) hovered.underline = .accent;
        if (self.backlog_hover_armed and !selected) hovered.foreground = .strong;
        try self.ui_tree.addInteractiveText(.{
            .id = id,
            .parent = parent,
            .role = role,
            .label = label,
            .selected = selected,
            .action = backlog_activate_action,
            .bounds = bounds,
        }, .{
            .id = id,
            .label = label,
            .action = backlog_activate_action,
            .normal = resting,
            .hovered = hovered,
            .focused = .{ .foreground = .on_accent, .background = .accent },
        });
    }

    /// The view: a `Surface` over the pane area with the mode and close
    /// controls, the board (a column per status) or the ordinal list, a
    /// message line, a key hint, and the open task's detail above them.
    /// Every id and label is copied into this frame's arena.
    fn composeBacklog(self: *App) !void {
        self.backlog_frame +%= 1;
        const frame = &self.backlog_frames[self.backlog_frame];
        _ = frame.reset(.retain_capacity);
        const bounds = self.backlogBounds() orelse return;
        const panel = self.shownBacklog() orelse return;
        const arena = frame.allocator();
        const view_id: ui.Id = .{ .value = "backlog.view" };
        const name = if (panel.project) |*project| project.config().project_name else "";
        const title = if (name.len != 0)
            try std.fmt.allocPrint(arena, " Backlog · {s} ", .{try backlog_view.oneLine(arena, name)})
        else
            " Backlog ";
        try self.ui_tree.addSurface(.{
            .id = view_id,
            .role = "backlog",
            .label = "Backlog",
            .bounds = bounds,
        }, .{
            .rect = bounds,
            .erase_underlay = true,
            .fill = .background,
            .border = .single,
            .border_style = .{ .foreground = .border, .background = .background },
            .title = title,
            .title_style = .{ .foreground = .strong, .background = .background, .face_style = .bold },
        });
        const x0 = bounds.x + 1;
        const width = bounds.width - 2;
        const y0 = bounds.y + 1;
        const height = bounds.height - 2;
        const muted: ui.TextStyle = .{ .foreground = .muted };
        const control: ui.TextStyle = .{ .foreground = .accent };
        try self.addBacklogInteractive(view_id, "backlog.mode.board", "mode", "board", panel.state.mode == .board, control, .{ .x = x0, .y = y0, .width = 5, .height = 1 });
        try self.addBacklogInteractive(view_id, "backlog.mode.list", "mode", "list", panel.state.mode == .list, control, .{ .x = x0 + 6, .y = y0, .width = 4, .height = 1 });
        try self.addBacklogInteractive(view_id, "backlog.close", "button", "close", false, muted, .{ .x = x0 + width - 5, .y = y0, .width = 5, .height = 1 });
        if (panel.project != null and width > 30) {
            const count = try std.fmt.allocPrint(arena, "{d} task{s}", .{ panel.board.list.len, if (panel.board.list.len == 1) "" else "s" });
            try self.addBacklogText(view_id, "backlog.summary", "status", count, muted, .{ .x = x0 + 12, .y = y0, .width = @min(@as(u32, @intCast(count.len)), width -| 18), .height = 1 });
        }

        const content_top = y0 + 1;
        const content_rows = height -| 3;
        if (panel.project == null) {
            const problem = if (panel.problem) |found| found.text() else "no backlog/ here";
            try self.addBacklogText(view_id, "backlog.empty", "status", problem, muted, .{ .x = x0, .y = content_top + 1, .width = width, .height = 1 });
        } else if (panel.board.isEmpty()) {
            try self.addBacklogText(view_id, "backlog.empty", "status", "no tasks in backlog/tasks", muted, .{ .x = x0, .y = content_top + 1, .width = width, .height = 1 });
        } else switch (panel.state.mode) {
            .board => try self.composeBacklogBoard(panel, view_id, arena, x0, width, content_top, content_rows),
            .list => try self.composeBacklogList(panel, view_id, arena, x0, width, content_top, content_rows),
        }
        if (panel.detail == null) {
            if (panel.message()) |text| {
                try self.addBacklogText(view_id, "backlog.message", "status", text, if (panel.message_failed) .{ .foreground = .attention } else muted, .{ .x = x0, .y = y0 + height - 2, .width = width, .height = 1 });
            }
        }
        try self.addBacklogText(view_id, "backlog.hint", "status", backlog_hint, muted, .{ .x = x0, .y = y0 + height - 1, .width = width, .height = 1 });
        if (panel.detail != null) try self.composeBacklogDetail(panel, bounds, arena);
    }

    /// A card's id, or null for a task whose id is not one (the parser keeps
    /// any id a file names; only a task id may become an element id).
    fn backlogCardId(arena: Allocator, task_id: []const u8, suffix: []const u8) !?[]const u8 {
        if (!backlog.isTaskId(task_id)) return null;
        return try std.fmt.allocPrint(arena, "backlog.task.{s}{s}", .{ task_id, suffix });
    }

    fn composeBacklogCardExtras(self: *App, panel: *backlog_view.Panel, arena: Allocator, parent: ui.Id, card: *const backlog_view.Card, meta_bounds: ?ui.Rect, x: u32, y: u32) !?BacklogAgent {
        const dir = panel.projectDirectory() orelse "";
        const linked = self.backlogAgent(dir, card.task.id);
        if (meta_bounds) |row| {
            const buffer = try arena.alloc(u8, card.meta.len + 160);
            const meta = backlog_view.metaWithBadge(buffer, card.meta, if (linked) |found| found.badge else null);
            if (meta.len != 0) {
                const meta_id = (try backlogCardId(arena, card.task.id, ".meta")) orelse return linked;
                try self.addBacklogText(parent, meta_id, "meta", meta, .{ .foreground = .muted, .small = true }, row);
            }
        }
        if (linked) |found| {
            const state_id = (try backlogCardId(arena, card.task.id, try std.fmt.allocPrint(arena, ".agent.{s}", .{found.tag}))) orelse return linked;
            // Semantic only: the row painted over it shows the glyph.
            try self.ui_tree.addText(.{
                .id = .{ .value = state_id },
                .parent = parent,
                .role = "agent_state",
                .label = found.badge.harness,
                .bounds = .{ .x = x, .y = y, .width = 1, .height = 1 },
            }, .{ .runs = &.{} });
        }
        return linked;
    }

    fn composeBacklogBoard(self: *App, panel: *backlog_view.Panel, view_id: ui.Id, arena: Allocator, x0: u32, width: u32, top: u32, rows: u32) !void {
        const board = panel.board;
        const columns: u32 = @intCast(board.columns.len);
        if (columns == 0 or rows < 3) return;
        const gap: u32 = 1;
        const column_width = @max((width -| gap * (columns - 1)) / columns, 1);
        const slots: usize = @max((rows - 1) / 2, 1);
        self.backlog_layout = .{ .x0 = x0, .column_width = column_width, .gap = gap, .columns = columns, .page = slots };
        const selected_id = panel.state.selected();
        var budget = backlog_card_capacity;
        for (board.columns, 0..) |column, column_index| {
            const x = x0 + @as(u32, @intCast(column_index)) * (column_width + gap);
            const heading = try std.fmt.allocPrint(arena, "{s} ({d})", .{ try backlog_view.oneLine(arena, column.title), column.cards.len });
            try self.addBacklogText(view_id, try std.fmt.allocPrint(arena, "backlog.column.{d}", .{column_index}), "column", heading, .{ .foreground = .strong, .face_style = .bold, .underline = .border }, .{ .x = x, .y = top, .width = column_width, .height = 1 });
            const scroll = &panel.state.scroll[@min(column_index, backlog_view.max_columns - 1)];
            if (panel.state.follow and selected_id != null and panel.state.selected_column == column_index) {
                backlog_view.keepVisible(scroll, panel.state.selected_row, column.cards.len, slots);
            }
            scroll.* = @min(scroll.*, column.cards.len -| slots);
            const end = @min(column.cards.len, scroll.* + slots);
            for (column.cards[scroll.*..end], 0..) |*card, slot| {
                if (budget == 0) return;
                budget -= 1;
                const y = top + 1 + @as(u32, @intCast(slot)) * 2;
                const selected = selected_id != null and std.ascii.eqlIgnoreCase(selected_id.?, card.task.id);
                if (try backlogCardId(arena, card.task.id, "")) |id_text| {
                    try self.addBacklogInteractive(view_id, id_text, "task", card.label, selected, .{ .foreground = .foreground }, .{ .x = x, .y = y, .width = column_width, .height = 1 });
                } else {
                    try self.addBacklogText(view_id, try std.fmt.allocPrint(arena, "backlog.card.{d}.{d}", .{ column_index, slot }), "task", card.label, .{ .foreground = .muted }, .{ .x = x, .y = y, .width = column_width, .height = 1 });
                }
                _ = try self.composeBacklogCardExtras(panel, arena, view_id, card, .{ .x = x, .y = y + 1, .width = column_width, .height = 1 }, x, y + 1);
                // Semantic only: which column the card is in, so a driver
                // can wait for a move by id.
                if (try backlogCardId(arena, card.task.id, try std.fmt.allocPrint(arena, ".column.{d}", .{column_index}))) |column_id| {
                    try self.ui_tree.addText(.{
                        .id = .{ .value = column_id },
                        .parent = view_id,
                        .role = "column_state",
                        .label = column.title,
                        .bounds = .{ .x = x, .y = y, .width = 1, .height = 1 },
                    }, .{ .runs = &.{} });
                }
            }
        }
    }

    fn composeBacklogList(self: *App, panel: *backlog_view.Panel, view_id: ui.Id, arena: Allocator, x0: u32, width: u32, top: u32, rows: u32) !void {
        const list = panel.board.list;
        if (rows < 2) return;
        const visible: usize = @min(rows - 1, backlog_card_capacity);
        self.backlog_layout = .{ .x0 = x0, .column_width = width, .gap = 0, .columns = 1, .page = visible };
        const status_width: u32 = @min(24, width / 3);
        const label_width = width -| (status_width + 1);
        try self.addBacklogText(view_id, "backlog.list.heading", "column", "Tasks by ordinal", .{ .foreground = .strong, .face_style = .bold, .underline = .border }, .{ .x = x0, .y = top, .width = width, .height = 1 });
        const selected_id = panel.state.selected();
        if (panel.state.follow) {
            if (selected_id) |id| if (panel.board.listIndex(id)) |index| backlog_view.keepVisible(&panel.state.list_scroll, index, list.len, visible);
        }
        panel.state.list_scroll = @min(panel.state.list_scroll, list.len -| visible);
        const end = @min(list.len, panel.state.list_scroll + visible);
        for (list[panel.state.list_scroll..end], 0..) |*card, slot| {
            const y = top + 1 + @as(u32, @intCast(slot));
            const selected = selected_id != null and std.ascii.eqlIgnoreCase(selected_id.?, card.task.id);
            const id_text = (try backlogCardId(arena, card.task.id, "")) orelse continue;
            try self.addBacklogInteractive(view_id, id_text, "task", card.label, selected, .{ .foreground = .foreground }, .{ .x = x0, .y = y, .width = label_width, .height = 1 });
            const linked = try self.composeBacklogCardExtras(panel, arena, view_id, card, null, x0 + label_width + 1, y);
            const status = try backlog_view.oneLine(arena, card.task.status);
            const word = if (linked) |found| try std.fmt.allocPrint(arena, "{s} {s}", .{ found.badge.glyph, status }) else status;
            const status_id = (try backlogCardId(arena, card.task.id, ".status")) orelse continue;
            try self.addBacklogText(view_id, status_id, "status", word, .{ .foreground = .muted }, .{ .x = x0 + label_width + 1, .y = y, .width = status_width, .height = 1 });
        }
    }

    /// The element id a detail row's target is registered under.
    fn backlogDetailTargetId(arena: Allocator, detail_id: []const u8, target: backlog_view.Target) ![]const u8 {
        return switch (target) {
            .none => unreachable, // Only actionable rows are asked for.
            .status => std.fmt.allocPrint(arena, "{s}.status", .{detail_id}),
            .criterion => |criterion| std.fmt.allocPrint(arena, "{s}.ac.{d}", .{ detail_id, criterion.index }),
        };
    }

    /// The task detail: a modal `Surface` over the view with the task's
    /// wrapped rows, its controls (status, each criterion, start agent, open
    /// in vi), the write's message line and a hint; or, while choosing, the
    /// harnesses an agent can start with.
    fn composeBacklogDetail(self: *App, panel: *backlog_view.Panel, view: ui.Rect, arena: Allocator) !void {
        const bounds = backlogDetailBounds(view) orelse return;
        const detail = if (panel.detail) |*open| open else return;
        const project = if (panel.project) |*loaded| loaded else return;
        const task = project.findTask(detail.id()) orelse {
            // The task went (its file was removed): nothing to detail.
            panel.detail = null;
            return;
        };
        const detail_text = try std.fmt.allocPrint(arena, "backlog.detail.{s}", .{detail.id()});
        const detail_id: ui.Id = .{ .value = detail_text };
        try self.ui_tree.addSurface(.{
            .id = detail_id,
            .parent = .{ .value = "backlog.view" },
            .role = "dialog",
            .label = try backlog_view.oneLine(arena, task.title),
            .bounds = bounds,
        }, .{
            .rect = bounds,
            .erase_underlay = true,
            .fill = .background,
            .border = .double,
            .border_style = .{ .foreground = .border, .background = .background },
            .title = try std.fmt.allocPrint(arena, " {s} ", .{detail.id()}),
            .title_style = .{ .foreground = .strong, .background = .background, .face_style = .bold },
        });
        const muted: ui.TextStyle = .{ .foreground = .muted };
        try self.addBacklogInteractive(detail_id, try std.fmt.allocPrint(arena, "{s}.close", .{detail_text}), "button", "close", false, muted, .{ .x = bounds.x + bounds.width - 8, .y = bounds.y, .width = 5, .height = 1 });
        const inner_x = bounds.x + 2;
        const inner_width = bounds.width - 4;
        const top = bounds.y + 1;
        const list_rows: usize = bounds.height -| 5;
        const actions_y = bounds.y + bounds.height - 4;
        const message_y = bounds.y + bounds.height - 3;
        const hint_y = bounds.y + bounds.height - 2;

        if (detail.choosing) {
            const heading = try std.fmt.allocPrint(arena, "Start an agent on {s}: choose a harness", .{detail.id()});
            try self.addBacklogText(detail_id, try std.fmt.allocPrint(arena, "{s}.chooser", .{detail_text}), "heading", heading, .{ .foreground = .strong, .face_style = .bold }, .{ .x = inner_x, .y = top, .width = inner_width -| 6, .height = 1 });
            try self.addBacklogInteractive(detail_id, try std.fmt.allocPrint(arena, "{s}.back", .{detail_text}), "button", "back", false, muted, .{ .x = inner_x + inner_width - 4, .y = top, .width = 4, .height = 1 });
            const count = self.backlog_harness_count;
            detail.choice = @min(detail.choice, count -| 1);
            for (0..@min(count, list_rows -| 1)) |index| {
                const label = self.backlog_harness_labels[index][0..self.backlog_harness_label_lens[index]];
                try self.addBacklogInteractive(detail_id, try std.fmt.allocPrint(arena, "{s}.harness.{d}", .{ detail_text, index }), "option", label, index == detail.choice, .{ .foreground = .foreground }, .{ .x = inner_x, .y = top + 2 + @as(u32, @intCast(index)), .width = inner_width, .height = 1 });
            }
            try self.addBacklogText(detail_id, "backlog.detail-hint", "status", backlog_chooser_hint, muted, .{ .x = inner_x, .y = hint_y, .width = inner_width, .height = 1 });
            if (panel.message()) |text| try self.addBacklogText(detail_id, "backlog.message", "status", text, if (panel.message_failed) .{ .foreground = .attention } else muted, .{ .x = inner_x, .y = message_y, .width = inner_width, .height = 1 });
            return;
        }

        const milestone_title = if (task.milestone) |key| if (project.findMilestone(key)) |found| found.title else null else null;
        const linked = self.backlogAgent(panel.projectDirectory() orelse "", task.id);
        const rows = try backlog_view.detailRows(arena, task, milestone_title, inner_width, if (linked) |found| found.badge else null);
        var actionable: usize = 0;
        for (rows) |row| actionable += @intFromBool(row.actionable());
        detail.cursor = @min(detail.cursor, actionable -| 1);
        var cursor_row: usize = 0;
        var seen: usize = 0;
        for (rows, 0..) |row, index| {
            if (!row.actionable()) continue;
            if (seen == detail.cursor) cursor_row = index;
            seen += 1;
        }
        if (detail.follow) backlog_view.keepVisible(&detail.scroll, cursor_row, rows.len, list_rows);
        detail.scroll = @min(detail.scroll, rows.len -| list_rows);
        self.backlog_detail_page = list_rows;
        var action_index: usize = 0;
        for (rows[0..detail.scroll]) |row| action_index += @intFromBool(row.actionable());
        const end = @min(rows.len, detail.scroll + @min(list_rows, backlog_detail_row_capacity));
        for (rows[detail.scroll..end], 0..) |row, slot| {
            const y = top + @as(u32, @intCast(slot));
            const row_bounds: ui.Rect = .{ .x = inner_x, .y = y, .width = inner_width, .height = 1 };
            if (row.actionable()) {
                const is_cursor = action_index == detail.cursor;
                action_index += 1;
                const role = switch (row.target) {
                    .criterion => "criterion",
                    else => "button",
                };
                try self.addBacklogInteractive(detail_id, try backlogDetailTargetId(arena, detail_text, row.target), role, row.text, is_cursor, .{ .foreground = .foreground }, row_bounds);
                continue;
            }
            if (row.kind == .blank) continue;
            const style: ui.TextStyle = switch (row.kind) {
                .title => .{ .foreground = .strong, .face_style = .bold },
                .heading => .{ .foreground = .accent, .face_style = .bold },
                .field => .{ .foreground = .foreground },
                else => .{ .foreground = .foreground },
            };
            try self.addBacklogText(detail_id, try std.fmt.allocPrint(arena, "{s}.row.{d}", .{ detail_text, detail.scroll + slot }), @tagName(row.kind), row.text, style, row_bounds);
        }
        // The two actions stay put below the rows, whatever the scroll.
        const start_label = "▶ start agent";
        const raw_label = "▶ open in vi";
        try self.addBacklogInteractive(detail_id, try std.fmt.allocPrint(arena, "{s}.agent", .{detail_text}), "button", start_label, false, .{ .foreground = .accent }, .{ .x = inner_x, .y = actions_y, .width = 13, .height = 1 });
        try self.addBacklogInteractive(detail_id, try std.fmt.allocPrint(arena, "{s}.raw", .{detail_text}), "button", raw_label, false, .{ .foreground = .accent }, .{ .x = inner_x + 16, .y = actions_y, .width = 12, .height = 1 });
        if (panel.message()) |text| {
            try self.addBacklogText(detail_id, "backlog.message", "status", text, if (panel.message_failed) .{ .foreground = .attention } else muted, .{ .x = inner_x, .y = message_y, .width = inner_width, .height = 1 });
        }
        try self.addBacklogText(detail_id, "backlog.detail-hint", "status", backlog_detail_hint, muted, .{ .x = inner_x, .y = hint_y, .width = inner_width, .height = 1 });
    }

    /// The actionable target under the detail's keyboard cursor.
    fn backlogCursorTarget(panel: *backlog_view.Panel) !?backlog_view.Target {
        const detail = if (panel.detail) |*open| open else return null;
        const project = if (panel.project) |*loaded| loaded else return null;
        const task = project.findTask(detail.id()) orelse return null;
        var arena_state: std.heap.ArenaAllocator = .init(panel.allocator);
        defer arena_state.deinit();
        // Targets do not depend on the width: only a row's first line has one.
        const rows = try backlog_view.detailRows(arena_state.allocator(), task, null, 80, null);
        var seen: usize = 0;
        var last: ?backlog_view.Target = null;
        for (rows) |row| {
            if (!row.actionable()) continue;
            last = row.target;
            if (seen == detail.cursor) return row.target;
            seen += 1;
        }
        return last;
    }

    /// The panel's task with id `id`.
    fn backlogTask(panel: *backlog_view.Panel, id: []const u8) ?*const backlog.Task {
        const project = if (panel.project) |*loaded| loaded else return null;
        return project.findTask(id);
    }

    fn backlogOpenDetail(self: *App, panel: *backlog_view.Panel, id: []const u8) !void {
        if (!backlog.isTaskId(id) or backlogTask(panel, id) == null) return;
        panel.state.select(id);
        if (panel.board.locate(id)) |cursor| {
            panel.state.selected_column = cursor.column;
            panel.state.selected_row = cursor.row;
        }
        panel.detail = backlog_view.Detail.of(id);
        panel.message_len = 0;
        self.ui_tree.clearFocus();
        try self.refreshActiveUi();
    }

    /// Ask the CLI to move the task to the next configured status.
    fn backlogCycleStatus(self: *App, panel: *backlog_view.Panel, id: []const u8) !void {
        const project = if (panel.project) |*loaded| loaded else return;
        const task = project.findTask(id) orelse return;
        const next = backlog_view.nextStatus(project.config(), task.status) orelse return;
        const request = backlog_view.CliRequest.status(task.id, next) orelse return;
        panel.enqueue(request, self.backlog_program) catch panel.setMessage(true, "backlog is busy: try again", .{});
        try self.refreshActiveUi();
    }

    /// Ask the CLI to flip acceptance criterion `index`.
    fn backlogToggleCriterion(self: *App, panel: *backlog_view.Panel, id: []const u8, index: u32) !void {
        const task = backlogTask(panel, id) orelse return;
        for (task.acceptance_criteria) |criterion| {
            if (criterion.index != index) continue;
            const request = backlog_view.CliRequest.criterion(task.id, index, !criterion.checked) orelse return;
            panel.enqueue(request, self.backlog_program) catch panel.setMessage(true, "backlog is busy: try again", .{});
            break;
        }
        try self.refreshActiveUi();
    }

    /// The start-agent chooser: the harnesses `agent.launch` offers here.
    fn backlogOpenChooser(self: *App, panel: *backlog_view.Panel) !void {
        const detail = if (panel.detail) |*open| open else return;
        self.ensureAgentDetection();
        const key = self.workspace_registry.activeKey() orelse return;
        const choices = self.agents.launchChoices(key);
        self.setAgentLaunchChoices();
        var count: usize = 0;
        for (choices) |choice| {
            if (count == self.backlog_harness.len) break;
            const parsed = app_agents.Choice.parse(choice.value) orelse continue;
            self.backlog_harness[count] = parsed;
            const len = @min(choice.label.len, self.backlog_harness_labels[count].len);
            @memcpy(self.backlog_harness_labels[count][0..len], choice.label[0..len]);
            self.backlog_harness_label_lens[count] = len;
            count += 1;
        }
        self.backlog_harness_count = count;
        if (count == 0) {
            panel.setMessage(true, "no coding agent found here", .{});
        } else {
            detail.choosing = true;
            detail.choice = 0;
            panel.message_len = 0;
        }
        self.ui_tree.clearFocus();
        try self.refreshActiveUi();
    }

    /// Start harness `index` on the detailed task through `agent.launch`'s
    /// own path, in the project directory, with the task as the initial
    /// prompt (TASK-64). The new agent's tab opens beneath the view.
    fn backlogLaunchAgent(self: *App, panel: *backlog_view.Panel, index: usize) !void {
        const detail = if (panel.detail) |*open| open else return;
        if (index >= self.backlog_harness_count) return;
        const choice = self.backlog_harness[index];
        if (choice == .fake and !self.agents.fake_enabled) return;
        const task = backlogTask(panel, detail.id()) orelse return;
        const dir = panel.projectDirectory() orelse return;
        var id_buffer: [backlog_view.max_id_bytes]u8 = undefined;
        if (task.id.len > id_buffer.len or !backlog.isTaskId(task.id)) return;
        @memcpy(id_buffer[0..task.id.len], task.id);
        const task_id = id_buffer[0..task.id.len];
        var dir_buffer: [Dir.max_path_bytes]u8 = undefined;
        if (dir.len > dir_buffer.len) return;
        @memcpy(dir_buffer[0..dir.len], dir);
        const prompt_buffer = try self.allocator.alloc(u8, backlog.max_task_prompt_bytes);
        defer self.allocator.free(prompt_buffer);
        const prompt = backlog.taskPrompt(prompt_buffer, task);
        detail.choosing = false;
        const before = self.agents.registry.next_ordinal;
        try self.launchAgentWith(choice, prompt, .{ .cwd = dir_buffer[0..dir.len], .task_id = task_id });
        if (self.agents.registry.next_ordinal != before) {
            if (self.agents.registry.get(agent.AgentId.fromOrdinal(before))) |record| {
                panel.setMessage(false, "started {s} on {s}", .{ self.agents.displayName(record), task_id });
            }
        } else if (self.workspace_status) |status| {
            panel.setMessage(true, "{s}", .{status});
        }
        try self.refreshActiveUi();
    }

    /// Open the task's markdown in `vi` in a new tab, through the workspace
    /// ExecutionContext as a file reference does, and close the view.
    fn backlogOpenRaw(self: *App, panel: *backlog_view.Panel) !void {
        const detail = if (panel.detail) |*open| open else return;
        const task = backlogTask(panel, detail.id()) orelse return;
        const dir = panel.projectDirectory() orelse return;
        const cwd = try self.allocator.dupe(u8, dir);
        var cwd_owned = true;
        defer if (cwd_owned) self.allocator.free(cwd);
        const argv = buildFileReferenceArgv(self.allocator, task.path, null, cwd) catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory,
            error.UnsafePath, error.PathTooLong => {
                panel.setMessage(true, "the task file cannot be opened", .{});
                return self.refreshActiveUi();
            },
        };
        cwd_owned = false;
        // The label borrows the project; the view closes only afterwards.
        if (!try self.openEditorTab(fileReferenceLabel(task.path), cwd, argv)) return;
        try self.closeBacklog();
    }

    /// A click on (or the semantic activation of) one of the view's
    /// elements. The id names what to do; no task text ever does.
    fn activateBacklogElement(self: *App, id: []const u8) !void {
        const panel = self.shownBacklog() orelse return;
        const element = backlog_view.parseElement(id) orelse return;
        switch (element) {
            .mode => |mode| {
                panel.state.mode = mode;
                panel.state.follow = true;
                try self.refreshActiveUi();
            },
            .close => try self.closeBacklog(),
            .task => |task_id| try self.backlogOpenDetail(panel, task_id),
            .detail => |target| {
                const detail = if (panel.detail) |*open| open else return;
                if (!std.ascii.eqlIgnoreCase(detail.id(), target.id)) return;
                switch (target.part) {
                    .close => {
                        panel.detail = null;
                        try self.refreshActiveUi();
                    },
                    .back => {
                        detail.choosing = false;
                        try self.refreshActiveUi();
                    },
                    .status => if (!detail.choosing) try self.backlogCycleStatus(panel, target.id),
                    .criterion => |index| if (!detail.choosing) try self.backlogToggleCriterion(panel, target.id, index),
                    .agent => if (!detail.choosing) try self.backlogOpenChooser(panel),
                    .raw => if (!detail.choosing) try self.backlogOpenRaw(panel),
                    .harness => |index| if (detail.choosing) try self.backlogLaunchAgent(panel, index),
                }
            },
        }
    }

    /// Plain keys while the view is shown and nothing above it takes them;
    /// chords still reach their bindings.
    fn routeBacklogKey(self: *App, key: platform.KeyEvent) !bool {
        if (self.paletteVisible() or self.contextMenuVisible() or self.notificationsVisible() or self.closeModalActive() or
            self.scratchpadVisible() or self.search_visible) return false;
        const panel = self.shownBacklog() orelse return false;
        if (self.activeUiTree().focusedInput() != null) return false;
        if (key.action != .press) return false;
        if (key.mods.ctrl or key.mods.alt or key.mods.super) return false;
        const identity = uiKeyIdentity(key) orelse return false;
        // A key the view does not use goes on to the bindings (F2, Shift+F10);
        // the terminal beneath never sees it (`onKey`).
        if (!try self.backlogKey(panel, key)) return false;
        _ = self.ui_key_state.claim(identity, .none);
        return true;
    }

    fn backlogKey(self: *App, panel: *backlog_view.Panel, key: platform.KeyEvent) !bool {
        const letter: u21 = if (key.mods.shift) 0 else if (key.unshifted_codepoint != 0) key.unshifted_codepoint else key.codepoint;
        if (panel.detail) |*detail| {
            if (detail.choosing) {
                const last = self.backlog_harness_count -| 1;
                switch (key.key) {
                    .escape => detail.choosing = false,
                    .up => detail.choice -|= 1,
                    .down => detail.choice = @min(detail.choice + 1, last),
                    .home => detail.choice = 0,
                    .end => detail.choice = last,
                    .enter => {
                        try self.backlogLaunchAgent(panel, detail.choice);
                        return true;
                    },
                    else => return false,
                }
                try self.refreshActiveUi();
                return true;
            }
            const page = @max(self.backlog_detail_page, 2) - 1;
            switch (key.key) {
                .escape => panel.detail = null,
                .up => detail.cursor -|= 1,
                .down => detail.cursor +|= 1,
                .tab => detail.cursor = if (key.mods.shift) detail.cursor -| 1 else detail.cursor +| 1,
                .home => detail.cursor = 0,
                .end => detail.cursor = std.math.maxInt(usize),
                .page_up => detail.cursor -|= page,
                .page_down => detail.cursor +|= page,
                .enter => return self.backlogActivateCursor(panel),
                else => switch (letter) {
                    ' ' => return self.backlogActivateCursor(panel),
                    's' => {
                        var id_buffer: [backlog_view.max_id_bytes]u8 = undefined;
                        const id = copyId(&id_buffer, detail.id());
                        try self.backlogCycleStatus(panel, id);
                        return true;
                    },
                    'a' => {
                        try self.backlogOpenChooser(panel);
                        return true;
                    },
                    'v' => {
                        try self.backlogOpenRaw(panel);
                        return true;
                    },
                    else => return false,
                },
            }
            detail.follow = true;
            try self.refreshActiveUi();
            return true;
        }
        const motion: ?backlog_view.Motion = switch (key.key) {
            .left => .left,
            .right => .right,
            .up => .up,
            .down => .down,
            .home => .first,
            .end => .last,
            .page_up => .page_up,
            .page_down => .page_down,
            else => null,
        };
        if (motion) |one| {
            panel.state.move(panel.board, one, self.backlog_layout.page);
            try self.refreshActiveUi();
            return true;
        }
        switch (key.key) {
            .escape => {
                try self.closeBacklog();
                return true;
            },
            .enter => {
                const selected = panel.state.selected() orelse return true;
                var id_buffer: [backlog_view.max_id_bytes]u8 = undefined;
                try self.backlogOpenDetail(panel, copyId(&id_buffer, selected));
                return true;
            },
            else => {},
        }
        switch (letter) {
            'l', 'b' => {
                panel.state.mode = if (letter == 'l') .list else .board;
                panel.state.follow = true;
                try self.refreshActiveUi();
                return true;
            },
            else => return false,
        }
    }

    fn copyId(buffer: []u8, id: []const u8) []const u8 {
        const len = @min(buffer.len, id.len);
        @memcpy(buffer[0..len], id[0..len]);
        return buffer[0..len];
    }

    /// Enter or Space in the detail: what the cursor row does.
    fn backlogActivateCursor(self: *App, panel: *backlog_view.Panel) !bool {
        const target = (try backlogCursorTarget(panel)) orelse return true;
        const detail = if (panel.detail) |*open| open else return true;
        var id_buffer: [backlog_view.max_id_bytes]u8 = undefined;
        const id = copyId(&id_buffer, detail.id());
        switch (target) {
            .none => {},
            .status => try self.backlogCycleStatus(panel, id),
            .criterion => |criterion| try self.backlogToggleCriterion(panel, id, criterion.index),
        }
        return true;
    }

    /// Pointer events over the view: hover once the pointer moved, a press
    /// and release on a card, row or control activates it, a press outside
    /// an open detail closes the detail, the wheel scrolls, and text typed
    /// over the view reaches nobody. Null leaves the event to the ordinary
    /// routes (the sidebar, outside the view).
    fn handleBacklogUiEvent(self: *App, event: platform.Event) !?bool {
        const view = self.backlogBounds() orelse return null;
        const panel = self.shownBacklog() orelse return null;
        const tree = self.activeUiTree();
        switch (event) {
            .mouse_motion => |motion| {
                const point = devicePointerPoint(motion.x, motion.y, self.window.state.scale);
                if (!self.pointInCellRect(point, view) and !self.backlog_pointer_owned) return null;
                const was_armed = self.backlog_hover_armed;
                self.backlog_hover_armed = true;
                const before = uiInteractionState(tree);
                tree.pointerMoved(point);
                if (!was_armed or !std.meta.eql(before, uiInteractionState(tree))) try self.refreshActiveUi();
                return true;
            },
            .mouse_button => |button| {
                const point = devicePointerPoint(button.x, button.y, self.window.state.scale);
                switch (button.action) {
                    .press => {
                        if (!self.pointInCellRect(point, view)) return null;
                        self.backlog_pointer_owned = true;
                        if (panel.detail != null) {
                            const detail_bounds = backlogDetailBounds(view);
                            if (detail_bounds == null or !self.pointInCellRect(point, detail_bounds.?)) {
                                panel.detail = null;
                                try self.refreshActiveUi();
                                return true;
                            }
                        }
                        if (button.button != .left) return true;
                        const before = uiInteractionState(tree);
                        tree.pointerPressed(point);
                        if (!std.meta.eql(before, uiInteractionState(tree))) try self.refreshActiveUi();
                        return true;
                    },
                    .repeat => return if (self.backlog_pointer_owned) true else null,
                    .release => {
                        if (!self.backlog_pointer_owned) return null;
                        self.backlog_pointer_owned = false;
                        if (button.button != .left) return true;
                        const before = uiInteractionState(tree);
                        const activation = tree.pointerReleased(point);
                        if (!std.meta.eql(before, uiInteractionState(tree))) try self.refreshActiveUi();
                        const requested = activation orelse return true;
                        if (!std.mem.startsWith(u8, requested.id.value, "backlog.")) return true;
                        var id_storage: [backlog_id_capacity]u8 = undefined;
                        if (requested.id.value.len > id_storage.len) return true;
                        @memcpy(id_storage[0..requested.id.value.len], requested.id.value);
                        try self.activateBacklogElement(id_storage[0..requested.id.value.len]);
                        return true;
                    },
                }
            },
            .wheel => |wheel| {
                const point = devicePointerPoint(wheel.x, wheel.y, self.window.state.scale);
                if (!self.pointInCellRect(point, view)) return null;
                if (wheel.dy == 0) return true;
                var up = wheel.dy > 0;
                if (wheel.flipped) up = !up;
                if (panel.detail) |*detail| {
                    detail.follow = false;
                    detail.scroll = if (up) detail.scroll -| 3 else detail.scroll + 3;
                } else switch (panel.state.mode) {
                    .list => {
                        panel.state.follow = false;
                        panel.state.list_scroll = if (up) panel.state.list_scroll -| 3 else panel.state.list_scroll + 3;
                    },
                    .board => {
                        const layout = self.backlog_layout;
                        const cell_width = self.fonts.metrics().cell.width_px;
                        const col: u32 = if (point.x <= 0) 0 else @as(u32, @intCast(point.x)) / @max(cell_width, 1);
                        if (col < layout.x0) return true;
                        const column = @min((col - layout.x0) / @max(layout.column_width + layout.gap, 1), backlog_view.max_columns - 1);
                        panel.state.follow = false;
                        const scroll = &panel.state.scroll[column];
                        scroll.* = if (up) scroll.* -| 1 else scroll.* + 1;
                    },
                }
                try self.refreshActiveUi();
                return true;
            },
            .text_input, .text_editing, .candidates => {
                if (tree.focusedInput() != null) return null;
                return true;
            },
            else => return null,
        }
    }

    fn paletteBounds(self: *const App) ?ui.Rect {
        if (!self.paletteVisible()) return null;
        const canvas = self.ui_canvas.bounds();
        if (canvas.width < 20 or canvas.height < 5) return null;
        // Two border and two padding columns around the widest row.
        const width = @min(canvas.width - 4, @max(@as(u32, 40), self.palette_content_width +| 4));
        const wanted_height: u32 = switch (self.palette_step) {
            .closed => return null,
            .commands => @intCast(@min(self.palette_model.results().len, palette_visible_rows) + 4),
            .input => 5,
            .choices => |step| blk: {
                const definition = self.actions.definitions()[step.definition_index];
                const values = switch (definition.palette.?.argument) {
                    .choices => |choice_argument| choice_argument.values,
                    else => return null,
                };
                // The font picker adds its `palette.preview` line.
                const preview_rows: usize = if (step.definition_index == self.font_pick_index) 1 else 0;
                if (self.choiceStepFiltered(step.definition_index)) {
                    // A filter field, and at least one row for "no match".
                    break :blk @intCast(@max(@min(self.choice_filter_len, palette_visible_rows), 1) + 5);
                }
                break :blk @intCast(@min(values.len, palette_visible_rows) + 4 + preview_rows);
            },
        };
        const height = @min(wanted_height, canvas.height - 2);
        if (width < 16 or height < 4) return null;
        return .{
            .x = (canvas.width - width) / 2,
            .y = (canvas.height - height) / 2,
            .width = width,
            .height = height,
        };
    }

    fn paletteResultStart(self: *const App, visible_count: usize) usize {
        const selected = self.palette_model.selectedResultIndex() orelse return 0;
        if (selected < visible_count) return 0;
        return selected - visible_count + 1;
    }

    fn composePalettePreedit(
        self: *App,
        parent: ui.Id,
        field_bounds: ui.Rect,
        field: *const ui.Input,
    ) !void {
        const text = self.composition.preedit();
        if (text.len == 0 or !std.unicode.utf8ValidateSlice(text) or field_bounds.width == 0) return;
        const prefix_cells = preeditCellWidth(field.text()[0..field.cursorByte()]) orelse 0;
        const start_x = field_bounds.x + @min(prefix_cells, field_bounds.width - 1);
        const normal: ui.TextStyle = .{ .foreground = .foreground, .underline = .accent };
        const selected: ui.TextStyle = .{
            .foreground = .strong,
            .background = .selection,
            .underline = .accent,
        };
        const selection = self.composition.selection();
        const start = @min(@as(usize, selection.start), text.len);
        const end = @min(start +| @as(usize, selection.length), text.len);
        var runs: [3]ui.Run = undefined;
        var run_count: usize = 0;
        if (selection.length != 0 and utf8Boundary(text, start) and utf8Boundary(text, end)) {
            if (start != 0) {
                runs[run_count] = .{ .text = text[0..start], .style = normal };
                run_count += 1;
            }
            runs[run_count] = .{ .text = text[start..end], .style = selected };
            run_count += 1;
            if (end != text.len) {
                runs[run_count] = .{ .text = text[end..], .style = normal };
                run_count += 1;
            }
        } else {
            runs[0] = .{ .text = text, .style = normal };
            run_count = 1;
        }
        try self.ui_tree.addText(.{
            .id = .{ .value = "palette.preedit" },
            .parent = parent,
            .role = "preedit",
            .label = text,
            .bounds = .{
                .x = start_x,
                .y = field_bounds.y,
                .width = field_bounds.right() - start_x,
                .height = 1,
            },
        }, .{ .runs = runs[0..run_count] });
    }

    fn composePalette(self: *App) !void {
        const bounds = self.paletteBounds() orelse return;
        const dialog_id: ui.Id = .{ .value = "palette.dialog" };
        try self.ui_tree.addSurface(.{
            .id = dialog_id,
            .role = "dialog",
            .label = "Command palette",
            .bounds = bounds,
        }, .{
            .rect = bounds,
            .erase_underlay = true,
            .fill = .background,
            .border = .double,
            .border_style = .{ .foreground = .border, .background = .background },
            .title = " Command palette ",
            .title_style = .{ .foreground = .strong, .background = .background, .face_style = .bold },
        });

        const inner_x = bounds.x + 2;
        const inner_width = bounds.width - 4;
        switch (self.palette_step) {
            .closed => {},
            .commands => {
                const field_bounds: ui.Rect = .{
                    .x = inner_x,
                    .y = bounds.y + 1,
                    .width = inner_width,
                    .height = 1,
                };
                try self.ui_tree.addInput(.{
                    .id = .{ .value = "palette.query" },
                    .parent = dialog_id,
                    .role = "input",
                    .label = "Filter commands",
                    .action = palette_activate_action,
                    .bounds = field_bounds,
                }, &self.palette_query, .{
                    .text = .{ .foreground = .strong, .background = .field },
                    .selection_background = .selection,
                    .cursor_background = .accent,
                    .cursor_foreground = .background,
                });
                try self.composePalettePreedit(dialog_id, field_bounds, &self.palette_query);

                const visible_count = @min(self.palette_model.results().len, palette_visible_rows);
                if (visible_count == 0) {
                    const runs = [_]ui.Run{.{
                        .text = "No matching commands",
                        .style = .{ .foreground = .muted },
                    }};
                    try self.ui_tree.addText(.{
                        .id = .{ .value = "palette.empty" },
                        .parent = dialog_id,
                        .role = "status",
                        .label = "No matching commands",
                        .bounds = .{ .x = inner_x, .y = bounds.y + 2, .width = inner_width, .height = 1 },
                    }, .{ .runs = &runs });
                    return;
                }

                const start = self.paletteResultStart(visible_count);
                const selected = self.palette_model.selectedDefinitionIndex();
                for (self.palette_model.results()[start .. start + visible_count], 0..) |definition_index, row| {
                    if (definition_index >= self.palette_row_ids.len) continue;
                    const definition = &self.actions.definitions()[definition_index];
                    const id_text = try std.fmt.bufPrint(
                        &self.palette_row_ids[definition_index],
                        "palette.action.{d}",
                        .{definition_index},
                    );
                    var chord_storage: [96]u8 = undefined;
                    const chords = palette_mod.formatActionBindings(
                        &chord_storage,
                        definition.name,
                        self.bindings,
                        self.binding_profile,
                    );
                    const label = if (chords.text.len == 0)
                        try std.fmt.bufPrint(&self.palette_row_labels[definition_index], "{s}", .{definition.label})
                    else
                        try std.fmt.bufPrint(
                            &self.palette_row_labels[definition_index],
                            "{s}  {s}{s}",
                            .{ definition.label, chords.text, if (chords.truncated) " …" else "" },
                        );
                    const is_selected = selected != null and selected.? == definition_index;
                    const id: ui.Id = .{ .value = id_text };
                    try self.ui_tree.addInteractiveText(.{
                        .id = id,
                        .parent = dialog_id,
                        .role = "command",
                        .label = label,
                        .selected = is_selected,
                        .action = palette_activate_action,
                        .bounds = .{
                            .x = inner_x,
                            .y = bounds.y + 2 + @as(u32, @intCast(row)),
                            .width = inner_width,
                            .height = 1,
                        },
                    }, .{
                        .id = id,
                        .label = label,
                        .action = palette_activate_action,
                        .normal = if (is_selected)
                            .{ .foreground = .strong, .background = .selection }
                        else
                            .{ .foreground = .foreground },
                        .hovered = .{ .foreground = .strong, .underline = .accent },
                        .focused = .{ .foreground = .on_accent, .background = .accent },
                    });
                }
            },
            .input => |definition_index| {
                const definition = &self.actions.definitions()[definition_index];
                const palette_argument_meta = switch (definition.palette.?.argument) {
                    .input => |value| value,
                    else => return,
                };
                const runs = [_]ui.Run{.{
                    .text = palette_argument_meta.prompt,
                    .style = .{ .foreground = .strong },
                }};
                try self.ui_tree.addText(.{
                    .id = .{ .value = "palette.prompt" },
                    .parent = dialog_id,
                    .role = "prompt",
                    .label = palette_argument_meta.prompt,
                    .bounds = .{ .x = inner_x, .y = bounds.y + 1, .width = inner_width, .height = 1 },
                }, .{ .runs = &runs });
                const field_bounds: ui.Rect = .{
                    .x = inner_x,
                    .y = bounds.y + 2,
                    .width = inner_width,
                    .height = 1,
                };
                try self.ui_tree.addInput(.{
                    .id = .{ .value = "palette.argument" },
                    .parent = dialog_id,
                    .role = "input",
                    .label = palette_argument_meta.prompt,
                    .action = palette_activate_action,
                    .bounds = field_bounds,
                }, &self.palette_argument, .{
                    .text = .{ .foreground = .strong, .background = .field },
                    .selection_background = .selection,
                    .cursor_background = .accent,
                    .cursor_foreground = .background,
                });
                try self.composePalettePreedit(dialog_id, field_bounds, &self.palette_argument);
            },
            .choices => |step| {
                const definition = &self.actions.definitions()[step.definition_index];
                const palette_argument_meta = switch (definition.palette.?.argument) {
                    .choices => |value| value,
                    else => return,
                };
                const runs = [_]ui.Run{.{
                    .text = palette_argument_meta.prompt,
                    .style = .{ .foreground = .strong },
                }};
                try self.ui_tree.addText(.{
                    .id = .{ .value = "palette.prompt" },
                    .parent = dialog_id,
                    .role = "prompt",
                    .label = palette_argument_meta.prompt,
                    .bounds = .{ .x = inner_x, .y = bounds.y + 1, .width = inner_width, .height = 1 },
                }, .{ .runs = &runs });
                if (self.choiceStepFiltered(step.definition_index)) {
                    try self.composeFilteredChoices(dialog_id, bounds, step.definition_index, step.selected, palette_argument_meta.values);
                    return;
                }
                const visible_count = @min(palette_argument_meta.values.len, palette_visible_rows);
                const start = if (step.selected < visible_count) 0 else step.selected - visible_count + 1;
                for (palette_argument_meta.values[start .. start + visible_count], 0..) |choice, row| {
                    const choice_index = start + row;
                    // Ids are stored per visible row: only those rows are
                    // in the tree, however long the list is.
                    if (row >= self.palette_choice_ids.len) break;
                    const id_text = try std.fmt.bufPrint(
                        &self.palette_choice_ids[row],
                        "palette.choice.{d}.{d}",
                        .{ step.definition_index, choice_index },
                    );
                    const is_selected = choice_index == step.selected;
                    const id: ui.Id = .{ .value = id_text };
                    try self.ui_tree.addInteractiveText(.{
                        .id = id,
                        .parent = dialog_id,
                        .role = "choice",
                        .label = choice.label,
                        .selected = is_selected,
                        .action = palette_activate_action,
                        .bounds = .{
                            .x = inner_x,
                            .y = bounds.y + 2 + @as(u32, @intCast(row)),
                            .width = inner_width,
                            .height = 1,
                        },
                    }, .{
                        .id = id,
                        .label = choice.label,
                        .action = palette_activate_action,
                        .normal = if (is_selected)
                            .{ .foreground = .strong, .background = .selection }
                        else
                            .{ .foreground = .foreground },
                        .hovered = .{ .foreground = .strong, .underline = .accent },
                        .focused = .{ .foreground = .on_accent, .background = .accent },
                    });
                }
                // The font picker names the family the window is drawn with
                // once the highlighted one has loaded, so a person (and the
                // test driver) can tell a preview from a load in progress.
                const preview_y = bounds.y + 2 + @as(u32, @intCast(visible_count));
                if (step.definition_index == self.font_pick_index and preview_y + 1 < bounds.y + bounds.height) {
                    if (self.fontPreviewLine()) |line| {
                        const preview_runs = [_]ui.Run{.{
                            .text = line,
                            .style = .{ .foreground = .muted },
                        }};
                        try self.ui_tree.addText(.{
                            .id = .{ .value = "palette.preview" },
                            .parent = dialog_id,
                            .role = "status",
                            .label = line,
                            .bounds = .{ .x = inner_x, .y = preview_y, .width = inner_width, .height = 1 },
                        }, .{ .runs = &preview_runs });
                    }
                }
            },
        }
    }

    /// A filtered choice step (the connection manager): the filter field
    /// under the prompt, then the matching rows, best first. Row ids keep
    /// each choice's own index, so a click names the same choice whatever
    /// the filter shows.
    fn composeFilteredChoices(
        self: *App,
        dialog_id: ui.Id,
        bounds: ui.Rect,
        definition_index: usize,
        selected: usize,
        values: []const inputmod.PaletteChoice,
    ) !void {
        const inner_x = bounds.x + 2;
        const inner_width = bounds.width - 4;
        const field_bounds: ui.Rect = .{ .x = inner_x, .y = bounds.y + 2, .width = inner_width, .height = 1 };
        try self.ui_tree.addInput(.{
            .id = .{ .value = "palette.filter" },
            .parent = dialog_id,
            .role = "input",
            .label = "Filter",
            .action = palette_activate_action,
            .bounds = field_bounds,
        }, &self.palette_argument, .{
            .text = .{ .foreground = .strong, .background = .field },
            .selection_background = .selection,
            .cursor_background = .accent,
            .cursor_foreground = .background,
        });
        try self.composePalettePreedit(dialog_id, field_bounds, &self.palette_argument);
        if (self.choice_filter_len == 0) {
            const empty_runs = [_]ui.Run{.{ .text = "No match", .style = .{ .foreground = .muted } }};
            try self.ui_tree.addText(.{
                .id = .{ .value = "palette.empty" },
                .parent = dialog_id,
                .role = "status",
                .label = "No match",
                .bounds = .{ .x = inner_x, .y = bounds.y + 3, .width = inner_width, .height = 1 },
            }, .{ .runs = &empty_runs });
            return;
        }
        const room: usize = if (bounds.height > 5) bounds.height - 5 else 1;
        const visible_count = @min(@min(self.choice_filter_len, palette_visible_rows), room);
        const position = self.choiceFilterPosition(selected) orelse 0;
        const start = if (position < visible_count) 0 else position - visible_count + 1;
        for (self.choice_filter[start .. start + visible_count], 0..) |choice_index, row| {
            if (row >= self.palette_choice_ids.len or choice_index >= values.len) break;
            const choice = values[choice_index];
            const id_text = try std.fmt.bufPrint(
                &self.palette_choice_ids[row],
                "palette.choice.{d}.{d}",
                .{ definition_index, choice_index },
            );
            const is_selected = choice_index == selected;
            const id: ui.Id = .{ .value = id_text };
            try self.ui_tree.addInteractiveText(.{
                .id = id,
                .parent = dialog_id,
                .role = "choice",
                .label = choice.label,
                .selected = is_selected,
                .action = palette_activate_action,
                .bounds = .{
                    .x = inner_x,
                    .y = bounds.y + 3 + @as(u32, @intCast(row)),
                    .width = inner_width,
                    .height = 1,
                },
            }, .{
                .id = id,
                .label = choice.label,
                .action = palette_activate_action,
                .normal = if (is_selected)
                    .{ .foreground = .strong, .background = .selection }
                else
                    .{ .foreground = .foreground },
                .hovered = .{ .foreground = .strong, .underline = .accent },
                .focused = .{ .foreground = .on_accent, .background = .accent },
            });
        }
    }

    fn presentedSessionId(self: *const App) session.SessionId {
        if (self.scratchpadVisible()) return self.activeWorkspaceConst().scratchpadId();
        if (self.connectionVisible()) return self.activeRemote().?.connection_id;
        return self.activePresentationConst().active_session_id;
    }

    fn presentedLive(self: *App) *session.Session {
        if (self.scratchpadVisible()) return self.scratchpadLive() orelse self.activeLive();
        if (self.connectionVisible()) {
            return self.activeWorkspace().sessionById(self.activeRemote().?.connection_id) orelse self.activeLive();
        }
        return self.activeLive();
    }

    fn presentedLiveConst(self: *const App) *const session.Session {
        if (self.scratchpadVisible()) return self.scratchpadLiveConst() orelse self.activeLiveConst();
        if (self.connectionVisible()) {
            return @constCast(self.activeWorkspaceConst()).sessionById(self.activeRemote().?.connection_id) orelse self.activeLiveConst();
        }
        return self.activeLiveConst();
    }

    fn presentedCellRect(self: *const App) ?ui.Rect {
        if (self.scratchpadVisible()) return self.scratchpadInnerRect();
        if (self.focusedPaneLayout()) |layout| return .{
            .x = layout.rect.col,
            .y = layout.rect.row,
            .width = layout.rect.cols,
            .height = layout.rect.rows,
        };
        return null;
    }

    fn sidebarOriginColumns(self: *const App) u16 {
        const bounds = self.ui_canvas.bounds();
        return sidebarColumns(@intCast(bounds.width), self.sidebar_width_cols, self.sidebar_visible);
    }

    fn uiGeometry(self: *const App) ui.Geometry {
        const cell = self.fonts.metrics().cell;
        return .{
            .cell_width = cell.width_px,
            .cell_height = cell.height_px,
            .surface_bounds = .{
                .x = 0,
                .y = 0,
                .width = self.size.width,
                .height = self.size.height,
            },
            .pixel_scale = self.window.state.scale.factor,
        };
    }

    /// Start native text input once the terminal has a cursor, and keep the
    /// input method's candidate window anchored to that cursor.
    ///
    /// Font metrics are device pixels while SDL's input rectangle is logical
    /// pixels. A valid selection start has the same grapheme measurement as
    /// the rendered preedit, so the candidate window follows that caret; an
    /// invalid external offset safely falls back to the leading edge.
    fn syncTextInput(self: *App) !void {
        const physical = self.fonts.metrics().cell;
        const scale = self.window.state.scale;
        if (self.activeUiTree().focusedInput()) |field| {
            const element = self.activeUiTree().focusedElement() orelse return;
            if (element.bounds.x < 0 or element.bounds.y < 0) return;
            const field_col: u32 = @intCast(@divFloor(element.bounds.x, @as(i32, @intCast(physical.width_px))));
            const field_row: u32 = @intCast(@divFloor(element.bounds.y, @as(i32, @intCast(physical.height_px))));
            const field_cols = @max(@as(u32, 1), element.bounds.width / physical.width_px);
            const text_prefix = field.text()[0..field.cursorByte()];
            const text_cells = preeditCellWidth(text_prefix) orelse 0;
            const selection = self.composition.selection();
            const preedit_prefix_len = @min(@as(usize, selection.start), selection.text.len);
            const preedit_cells = if (utf8Boundary(selection.text, preedit_prefix_len))
                preeditCellWidth(selection.text[0..preedit_prefix_len]) orelse 0
            else
                0;
            try self.window.startTextInput();
            try self.window.pointTextInputAt(
                field_col + @min(text_cells +| preedit_cells, field_cols - 1),
                field_row,
                .{
                    .width = logicalPixels(physical.width_px, scale),
                    .height = logicalPixels(physical.height_px, scale),
                },
                0,
            );
            return;
        }

        const presented = self.presentedLive();
        const cursor = presented.terminal().cursor().position orelse return;
        const grid = presented.terminal().gridSize();
        const rect = self.presentedCellRect() orelse return;
        const selection = self.composition.selection();
        const prefix_len = @min(@as(usize, selection.start), selection.text.len);
        const caret_cells = if (utf8Boundary(selection.text, prefix_len))
            preeditCellWidth(selection.text[0..prefix_len]) orelse 0
        else
            0;
        const caret_col = @min(
            @as(u32, cursor.col) +| caret_cells,
            @as(u32, grid.cols - 1),
        ) + rect.x;
        const caret_row = @as(u32, cursor.row) + rect.y;

        try self.window.startTextInput();
        try self.window.pointTextInputAt(
            caret_col,
            caret_row,
            .{
                .width = logicalPixels(physical.width_px, scale),
                .height = logicalPixels(physical.height_px, scale),
            },
            0,
        );
    }

    fn sameTerminalHyperlink(a: ?term.Hyperlink, b: ?term.Hyperlink) bool {
        if (a == null or b == null) return a == null and b == null;
        return switch (a.?) {
            .invalid_utf8 => switch (b.?) {
                .invalid_utf8 => true,
                .uri => false,
            },
            .uri => |left| switch (b.?) {
                .invalid_utf8 => false,
                .uri => |right| std.mem.eql(u8, left, right),
            },
        };
    }

    fn terminalHyperlinkUri(value: term.Hyperlink) []const u8 {
        return switch (value) {
            .uri => |uri| uri,
            // The detector treats every supplied range as authoritative even
            // when this deliberately non-URL target cannot be emitted.
            .invalid_utf8 => "",
        };
    }

    fn appendTerminalLinkScalar(self: *App, length: *usize, codepoint: u21) bool {
        var encoded: [4]u8 = undefined;
        const count = std.unicode.utf8Encode(codepoint, &encoded) catch return false;
        if (count > self.terminal_link_row.len - length.*) return false;
        @memcpy(self.terminal_link_row[length.* .. length.* + count], encoded[0..count]);
        length.* += count;
        return true;
    }

    fn appendTerminalLinkCell(self: *App, length: *usize, cell: term.Cell) bool {
        if (cell.wide_tail) return true;
        if (cell.codepoint == 0) {
            if (length.* == self.terminal_link_row.len) return false;
            self.terminal_link_row[length.*] = ' ';
            length.* += 1;
        } else if (!self.appendTerminalLinkScalar(length, cell.codepoint)) return false;
        for (cell.grapheme) |codepoint| {
            if (!self.appendTerminalLinkScalar(length, codepoint)) return false;
        }
        return true;
    }

    fn terminalLinkCellByteLen(cell: term.Cell) ?usize {
        if (cell.wide_tail) return 0;
        var length: usize = if (cell.codepoint == 0) 1 else 0;
        if (cell.codepoint != 0) {
            var encoded: [4]u8 = undefined;
            length = std.unicode.utf8Encode(cell.codepoint, &encoded) catch return null;
        }
        for (cell.grapheme) |codepoint| {
            var encoded: [4]u8 = undefined;
            length += std.unicode.utf8Encode(codepoint, &encoded) catch return null;
        }
        return length;
    }

    fn terminalLinkCellBounds(
        terminal: *const term.Terminal,
        row: u16,
        span: link.Span,
    ) ?TerminalLinkCellBounds {
        var byte_offset: usize = 0;
        var start_col: ?u16 = null;
        var col: u16 = 0;
        while (col < terminal.gridSize().cols) : (col += 1) {
            const cell = terminal.cell(.{ .col = col, .row = row }) orelse return null;
            if (cell.wide_tail) continue;
            const byte_len = terminalLinkCellByteLen(cell) orelse return null;
            const next_offset = byte_offset + byte_len;
            if (span.start == byte_offset) start_col = col;
            if ((span.start > byte_offset and span.start < next_offset) or
                (span.end > byte_offset and span.end < next_offset)) return null;
            if (span.end == next_offset) {
                const first = start_col orelse return null;
                const cell_width: u32 = if (cell.wide) 2 else 1;
                const end_col = @as(u32, col) + cell_width;
                if (end_col <= @as(u32, first) or end_col > std.math.maxInt(u16)) return null;
                return .{ .col = first, .width = @intCast(end_col - @as(u32, first)) };
            }
            byte_offset = next_offset;
        }
        return null;
    }

    fn copyTerminalLinkText(self: *App, text: []const u8) ?[]const u8 {
        if (text.len > self.terminal_link_text.len - self.terminal_link_text_len) return null;
        const start = self.terminal_link_text_len;
        const end = start + text.len;
        @memcpy(self.terminal_link_text[start..end], text);
        self.terminal_link_text_len = end;
        return self.terminal_link_text[start..end];
    }

    fn appendTerminalLinkRange(
        self: *App,
        count: *usize,
        overflow: *bool,
        start: usize,
        end: usize,
        hyperlink: term.Hyperlink,
    ) void {
        if (start >= end or overflow.*) return;
        if (count.* == self.terminal_link_ranges.len) {
            overflow.* = true;
            return;
        }
        self.terminal_link_ranges[count.*] = .{
            .span = .{ .start = start, .end = end },
            .uri = terminalHyperlinkUri(hyperlink),
        };
        count.* += 1;
    }

    fn composeTerminalLinkRow(
        self: *App,
        terminal: *const term.Terminal,
        session_id: session.SessionId,
        parent: ui.Id,
        terminal_rect: ui.Rect,
        row: u16,
    ) !void {
        if (self.terminal_link_target_count == self.terminal_link_targets.len) return;

        var row_len: usize = 0;
        var range_count: usize = 0;
        var range_overflow = false;
        var active_hyperlink: ?term.Hyperlink = null;
        var active_start: usize = 0;
        var col: u16 = 0;
        while (col < terminal.gridSize().cols) : (col += 1) {
            const position = term.Position{ .col = col, .row = row };
            const cell = terminal.cell(position) orelse return;
            if (cell.wide_tail) continue;
            const hyperlink = terminal.hyperlink(position);
            if (!sameTerminalHyperlink(active_hyperlink, hyperlink)) {
                if (active_hyperlink) |previous| {
                    self.appendTerminalLinkRange(
                        &range_count,
                        &range_overflow,
                        active_start,
                        row_len,
                        previous,
                    );
                }
                active_hyperlink = hyperlink;
                active_start = row_len;
            }
            if (!self.appendTerminalLinkCell(&row_len, cell)) return;
        }
        if (active_hyperlink) |previous| {
            self.appendTerminalLinkRange(
                &range_count,
                &range_overflow,
                active_start,
                row_len,
                previous,
            );
        }
        if (row_len == 0) return;
        if (range_overflow) {
            self.terminal_link_ranges[0] = .{
                .span = .{ .start = 0, .end = row_len },
                .uri = "",
            };
            range_count = 1;
        }

        const detected = link.detectRow(
            self.terminal_link_row[0..row_len],
            self.terminal_link_ranges[0..range_count],
            &self.terminal_link_matches,
            .{},
        ) catch return;
        for (detected.matches) |match| {
            const kind: TerminalLinkTargetKind = switch (match.target) {
                .url => .url,
                .file => .file,
            };
            const target_text = switch (match.target) {
                .url => |value| value,
                .file => |file| file.path,
            };
            const line: ?u32 = switch (match.target) {
                .url => null,
                .file => |file| file.line,
            };
            const column: ?u32 = switch (match.target) {
                .url => null,
                .file => |file| file.column,
            };
            if (self.terminal_link_target_count == self.terminal_link_targets.len) return;
            const bounds = terminalLinkCellBounds(terminal, row, match.span) orelse continue;
            if (match.text.len + target_text.len > self.terminal_link_text.len - self.terminal_link_text_len) return;
            const copied_label = self.copyTerminalLinkText(match.text) orelse return;
            const copied_url = self.copyTerminalLinkText(target_text) orelse return;
            const target_index = self.terminal_link_target_count;
            const fingerprint = terminalLinkFingerprint(kind, copied_url, line, column);
            const fingerprint_hex = std.fmt.bytesToHex(fingerprint, .lower);
            const semantic = std.fmt.bufPrint(
                &self.terminal_link_ids[self.terminal_link_id_generation][target_index],
                "workspace.{d}.session.{d}.terminal-link.{d}.{d}.{s}.{d}",
                .{
                    @intFromEnum(self.activePresentation().key),
                    @intFromEnum(session_id),
                    row,
                    bounds.col,
                    fingerprint_hex[0..],
                    copied_url.len,
                },
            ) catch return;
            const id: ui.Id = .{ .value = semantic };
            self.terminal_link_targets[target_index] = .{
                .id = semantic,
                .kind = kind,
                .target = copied_url,
                .line = line,
                .column = column,
                .session_id = session_id,
            };
            self.terminal_link_target_count += 1;
            try self.ui_tree.addInteractiveText(.{
                .id = id,
                .parent = parent,
                .role = "terminal_link",
                .label = copied_label,
                .action = terminal_open_link_action,
                .bounds = .{
                    .x = terminal_rect.x + @as(u32, bounds.col),
                    .y = terminal_rect.y + @as(u32, row),
                    .width = @as(u32, bounds.width),
                    .height = 1,
                },
            }, .{
                .id = id,
                .label = copied_label,
                .action = terminal_open_link_action,
                .paint = .decorations_only,
                .normal = .{},
                .hovered = if (self.terminal_link_modifier) .{ .underline = .accent } else .{},
                .focused = .{ .underline = .accent },
            });
        }
    }

    fn composeTerminalLinks(
        self: *App,
        terminal: *const term.Terminal,
        session_id: session.SessionId,
        parent: ui.Id,
        terminal_rect: ui.Rect,
    ) !void {
        var row: u16 = 0;
        while (row < terminal.gridSize().rows) : (row += 1) {
            try self.composeTerminalLinkRow(terminal, session_id, parent, terminal_rect, row);
            if (self.terminal_link_target_count == self.terminal_link_targets.len) return;
        }
    }

    fn terminalLinkTarget(self: *const App, id: []const u8) ?TerminalLinkTarget {
        for (self.terminal_link_targets[0..self.terminal_link_target_count]) |target| {
            if (std.mem.eql(u8, target.id, id)) return target;
        }
        return null;
    }

    fn searchBarLayout(self: *const App) ?SearchBarLayout {
        if (!self.search_visible) return null;
        return calculateSearchBarLayout(self.ui_canvas.bounds());
    }

    fn searchStatusText(self: *App) []const u8 {
        const text = if (self.search_failure) |failure|
            std.fmt.bufPrint(&self.search_control_label, "{s}", .{failure}) catch "search error"
        else if (self.search_query.text().len == 0)
            std.fmt.bufPrint(&self.search_control_label, "type to search", .{}) catch "search"
        else if (searchVisibleProgress(self.search_progress, self.search_page_scan != null) == .running)
            std.fmt.bufPrint(&self.search_control_label, "{d}{s} searching...", .{
                self.search_match_count,
                if (self.search_truncated) "+" else "",
            }) catch "searching..."
        else if (self.search_progress == .scratch_exhausted)
            std.fmt.bufPrint(&self.search_control_label, "search storage exhausted", .{}) catch "search error"
        else if (self.search_match_count == 0)
            std.fmt.bufPrint(&self.search_control_label, "no matches", .{}) catch "none"
        else
            std.fmt.bufPrint(&self.search_control_label, "{d}/{d}{s}", .{
                self.search_active_index + 1,
                self.search_match_count,
                if (self.search_truncated) "+" else "",
            }) catch "matches";
        return text;
    }

    fn composeSearchHighlights(self: *App) !void {
        if (!self.search_visible or self.search_match_count == 0) return;
        // A view's matches are its own rows', registered with the view.
        if (self.search_view != null) return;
        const rect = self.presentedCellRect() orelse return;
        const terminal = self.presentedLive().terminalConst();
        const viewport = terminal.viewport();
        if (viewport.view_rows == 0) return;
        const top = viewport.history_rows - viewport.offset;
        const bottom = top + viewport.view_rows - 1;
        const cols = terminal.gridSize().cols;
        if (cols == 0) return;

        var semantic_index: usize = 0;
        for (self.search_pages[self.search_page_slot][0..self.search_match_count], 0..) |located, match_index| {
            const match = located.match;
            const first_row: usize = match.first.row;
            const last_row: usize = match.last.row;
            if (first_row > last_row or last_row < top or first_row > bottom) continue;
            var row = @max(first_row, top);
            const final_row = @min(last_row, bottom);
            while (row <= final_row and semantic_index < self.search_highlight_ids[0].len) : (row += 1) {
                const first_col: u16 = if (row == first_row) match.first.col else 0;
                const last_col: u16 = if (row == last_row) match.last.col else cols - 1;
                if (first_col >= cols or last_col < first_col) continue;
                const clipped_last = @min(last_col, cols - 1);
                const id_text = try std.fmt.bufPrint(
                    &self.search_highlight_ids[self.search_highlight_id_generation][semantic_index],
                    "search.match.{d}.{d}",
                    .{ match_index, row },
                );
                semantic_index += 1;
                const id: ui.Id = .{ .value = id_text };
                const active = match_index == self.search_active_index;
                const bounds: ui.Rect = .{
                    .x = rect.x + @as(u32, first_col),
                    .y = rect.y + @as(u32, @intCast(row - top)),
                    .width = @as(u32, clipped_last - first_col) + 1,
                    .height = 1,
                };
                try self.ui_tree.addInteractiveText(.{
                    .id = id,
                    .role = "search_match",
                    .label = "Search match",
                    .selected = active,
                    .action = search_activate_match_action,
                    .bounds = bounds,
                }, .{
                    .id = id,
                    .label = "Search match",
                    .action = search_activate_match_action,
                    .paint = .decorations_only,
                    .normal = if (active)
                        .{ .underline = .accent, .overline = .accent }
                    else
                        .{ .underline = .attention },
                    .hovered = .{ .underline = .strong, .overline = .strong },
                    .focused = .{ .underline = .accent, .overline = .accent },
                });
            }
        }
    }

    fn composeSearchBar(self: *App) !void {
        const layout = self.searchBarLayout() orelse return;
        const bounds = layout.bounds;
        const dialog_id: ui.Id = .{ .value = "search.dialog" };
        try self.ui_tree.addSurface(.{
            .id = dialog_id,
            .role = "dialog",
            .label = if (self.search_view != null) "Find in agent view" else "Find in scrollback",
            .bounds = bounds,
        }, .{
            .rect = bounds,
            .fill = .background,
            .border = if (layout.bordered) .single else .none,
            .border_style = .{ .foreground = .border, .background = .background },
            .title = if (!layout.bordered) null else if (self.search_view != null) " Find in agent view " else " Find in scrollback ",
            .title_style = .{ .foreground = .strong, .background = .background, .face_style = .bold },
        });

        const query_bounds = layout.query;
        try self.ui_tree.addInput(.{
            .id = .{ .value = "search.query" },
            .parent = dialog_id,
            .role = "input",
            .label = "Search query",
            .action = search_next_action,
            .bounds = query_bounds,
        }, &self.search_query, .{
            .text = .{ .foreground = .strong, .background = .field },
            .selection_background = .selection,
            .cursor_background = .accent,
            .cursor_foreground = .background,
        });
        try self.composePalettePreedit(dialog_id, query_bounds, &self.search_query);

        const detail_bounds = layout.detail orelse return;
        const status = self.searchStatusText();
        const SearchControl = struct {
            id: []const u8,
            label: []const u8,
            action: []const u8,
            width: u32,
        };
        const full_controls = [_]SearchControl{
            .{ .id = "search.previous", .label = "prev", .action = search_previous_action, .width = 4 },
            .{ .id = "search.next", .label = "next", .action = search_next_action, .width = 4 },
            .{ .id = "search.case", .label = if (self.search_case == .sensitive) "case:Aa" else "case:aa", .action = search_case_action, .width = 7 },
            .{ .id = "search.regex", .label = if (self.search_mode == .literal) "regex:off" else "regex:on", .action = search_regex_action, .width = 9 },
            .{ .id = "search.close", .label = "close", .action = search_close_action, .width = 5 },
        };
        const navigation_controls = [_]SearchControl{
            .{ .id = "search.previous", .label = "prev", .action = search_previous_action, .width = 4 },
            .{ .id = "search.next", .label = "next", .action = search_next_action, .width = 4 },
            .{ .id = "search.close", .label = "close", .action = search_close_action, .width = 5 },
        };
        const glyph_controls = [_]SearchControl{
            .{ .id = "search.previous", .label = "‹ previous", .action = search_previous_action, .width = 1 },
            .{ .id = "search.next", .label = "› next", .action = search_next_action, .width = 1 },
            .{ .id = "search.close", .label = "× close", .action = search_close_action, .width = 1 },
        };
        const no_controls = [_]SearchControl{};
        const controls: []const SearchControl = if (detail_bounds.width >= 35)
            &full_controls
        else if (detail_bounds.width >= 17)
            &navigation_controls
        else if (detail_bounds.width >= 7)
            &glyph_controls
        else
            &no_controls;

        var controls_width: u32 = 0;
        for (controls, 0..) |control, index| {
            controls_width += control.width;
            if (index != 0) controls_width += 1;
        }
        const status_width = detail_bounds.width -| controls_width -| @intFromBool(controls.len != 0);
        const runs = [_]ui.Run{.{
            .text = status,
            .style = .{ .foreground = if (self.search_failure == null) .muted else .attention },
        }};
        try self.ui_tree.addText(.{
            .id = .{ .value = "search.status" },
            .parent = dialog_id,
            .role = "status",
            .label = status,
            .bounds = .{ .x = detail_bounds.x, .y = detail_bounds.y, .width = status_width, .height = 1 },
        }, .{ .runs = &runs });

        var control_x = detail_bounds.right() - controls_width;
        for (controls) |control| {
            const id: ui.Id = .{ .value = control.id };
            try self.ui_tree.addInteractiveText(.{
                .id = id,
                .parent = dialog_id,
                .role = "search_control",
                .label = control.label,
                .action = control.action,
                .bounds = .{ .x = control_x, .y = detail_bounds.y, .width = control.width, .height = 1 },
            }, .{
                .id = id,
                .label = control.label,
                .action = control.action,
                .normal = .{ .foreground = .muted, .background = .background },
                .hovered = .{ .foreground = .strong, .underline = .accent, .background = .background },
                .focused = .{ .foreground = .on_accent, .background = .accent },
            });
            control_x += control.width + 1;
        }
    }

    /// Rebuild the production sidebar and input-method frame, then derive the
    /// full-canvas overlay from that one semantic tree. Every non-identity
    /// slice is borrowed only until `drawOverlay` returns in this frame.
    /// Rebuild the semantic frame, then let the theme picker's preview follow
    /// whatever the new frame highlights.
    fn composeUi(self: *App) !void {
        try self.composeUiTree();
        self.syncThemePreview();
        if (self.syncFontPreview()) try self.composeUiTree();
    }

    fn composeUiTree(self: *App) !void {
        try self.ui_tree.beginFrame(self.uiGeometry());
        self.terminal_link_id_generation = (self.terminal_link_id_generation + 1) % self.terminal_link_ids.len;
        self.search_highlight_id_generation = (self.search_highlight_id_generation + 1) % self.search_highlight_ids.len;
        self.agent_view_generation = 1 - self.agent_view_generation;
        self.agent_view_used[self.agent_view_generation] = 0;
        self.terminal_link_target_count = 0;
        self.terminal_link_text_len = 0;
        const canvas_bounds = self.ui_canvas.bounds();
        const origin = self.sidebarOriginColumns();
        if (origin != 0) {
            const sidebar_bounds: ui.Rect = .{
                .x = 0,
                .y = 0,
                .width = origin,
                .height = canvas_bounds.height,
            };
            try self.ui_tree.addSurface(.{
                .id = .{ .value = "sidebar" },
                .role = "sidebar",
                .label = "Workspaces and tabs",
                .bounds = sidebar_bounds,
            }, .{
                .rect = sidebar_bounds,
                .fill = .background,
                .border = .single,
                .border_style = .{ .foreground = .muted },
            });

            const content_width: u32 = if (origin > 2) origin - 2 else 0;
            if (content_width != 0 and canvas_bounds.height > 2) {
                // Palette hint and version, plus the transient status line
                // above them while one is shown.
                const config_error = self.configErrorText();
                const footer_rows: u32 = 3 + @as(u32, if (self.workspace_status != null) 1 else 0) +
                    @as(u32, if (config_error != null) 1 else 0);
                const list_limit = canvas_bounds.height -| (footer_rows + 1);
                const active_key = self.workspace_registry.activeKey();
                const geometry = self.uiGeometry();
                var workspace_storage_index: usize = 0;
                var tab_storage_index: usize = 0;
                var agent_state_slot: usize = 0;
                self.agent_state_id_generation = (self.agent_state_id_generation + 1) % self.agent_state_ids.len;
                var remote_state_slot: usize = 0;
                self.remote_state_id_generation = (self.remote_state_id_generation + 1) % self.remote_state_ids.len;
                var row: u32 = 1;
                var workspace_index: usize = 0;
                // Every workspace after the first listed one sits a few
                // logical pixels lower than the cell grid (TASK-77,
                // decision "Sidebar workspace gap via sub-cell row
                // offsets"); its rows must still end above the footer.
                var group_index: u32 = 0;
                var row_limit = list_limit;
                var group_offset_px: i32 = 0;
                while (row < row_limit and workspace_index < self.workspace_registry.count()) : (workspace_index += 1) {
                    const key = self.workspace_registry.keyAt(workspace_index) orelse continue;
                    const presentation = self.presentationByKey(key) orelse continue;
                    if (presentation.closing or workspace_storage_index >= self.workspace_semantic_storage.len) continue;
                    const model = self.workspace_registry.byKey(key) orelse continue;
                    group_offset_px = sidebarGroupOffsetPx(group_index);
                    row_limit = sidebarRowLimit(list_limit, geometry.offsetPx(group_offset_px), geometry.cell_height);
                    if (row >= row_limit) break;
                    group_index += 1;
                    const semantic = try workspaceSemanticId(&self.workspace_semantic_storage[workspace_storage_index], key);
                    const workspace_slot = workspace_storage_index;
                    workspace_storage_index += 1;
                    const workspace_id: ui.Id = .{ .value = semantic };
                    const selected = active_key != null and active_key.? == key;
                    // An SSH workspace's connection state leads its row
                    // (TASK-43): a glyph unless connected, and always a
                    // semantic `connection_state` element naming the state.
                    var workspace_label = model.name();
                    if (presentation.remote) |remote_record| {
                        const glyph = remote.stateGlyph(remote_record.state);
                        if (glyph.len != 0) {
                            workspace_label = std.fmt.bufPrint(&self.remote_workspace_labels[workspace_slot], "{s} {s}", .{ glyph, model.name() }) catch model.name();
                        }
                        if (remote_state_slot < sidebar_element_capacity) {
                            const state_id = try std.fmt.bufPrint(&self.remote_state_ids[self.remote_state_id_generation][remote_state_slot], "{s}.ssh.{s}", .{ semantic, @tagName(remote_record.state) });
                            remote_state_slot += 1;
                            try self.ui_tree.addText(.{
                                .id = .{ .value = state_id },
                                .parent = .{ .value = "sidebar" },
                                .role = "connection_state",
                                .label = @tagName(remote_record.state),
                                .bounds = .{ .x = 1, .y = row, .width = 1, .height = 1 },
                                .offset_px = group_offset_px,
                            }, .{ .runs = &.{} });
                        }
                    }
                    // The most urgent agent state in the workspace leads its
                    // row (TASK-56); the glyph element's id carries the state.
                    if (self.agents.workspaceState(key)) |state| {
                        workspace_label = std.fmt.bufPrint(&self.agent_workspace_labels[workspace_slot], "{s} {s}", .{ app_agents.stateGlyph(state), workspace_label }) catch workspace_label;
                        if (agent_state_slot < sidebar_element_capacity) {
                            const state_id = try std.fmt.bufPrint(&self.agent_state_ids[self.agent_state_id_generation][agent_state_slot], "{s}.agent.{s}", .{ semantic, @tagName(state) });
                            agent_state_slot += 1;
                            // Semantic only: the row painted over it shows
                            // the glyph, so it takes none of the frame's runs.
                            try self.ui_tree.addText(.{
                                .id = .{ .value = state_id },
                                .parent = .{ .value = "sidebar" },
                                .role = "agent_state",
                                .label = @tagName(state),
                                .bounds = .{ .x = 1, .y = row, .width = 1, .height = 1 },
                                .offset_px = group_offset_px,
                            }, .{ .runs = &.{} });
                        }
                    }
                    try self.ui_tree.addInteractiveText(.{
                        .id = workspace_id,
                        .parent = .{ .value = "sidebar" },
                        .role = "workspace",
                        .label = workspace_label,
                        .selected = selected,
                        .action = workspace_activate_action,
                        .bounds = .{ .x = 1, .y = row, .width = content_width, .height = 1 },
                        .offset_px = group_offset_px,
                    }, .{
                        .id = workspace_id,
                        .label = workspace_label,
                        .action = workspace_activate_action,
                        .normal = if (selected)
                            .{ .foreground = .accent, .background = .selection }
                        else
                            .{ .foreground = .accent },
                        .hovered = .{ .foreground = .strong, .underline = .accent },
                        .focused = .{ .foreground = .strong, .background = .selection },
                    });
                    row += 1;
                    if (!selected) continue;

                    var tab_index: usize = 0;
                    while (row < row_limit and tab_storage_index < self.tab_semantic_storage.len) : (row += 1) {
                        const tab = model.tabAt(tab_index) orelse break;
                        tab_index += 1;
                        const storage_index = tab_storage_index;
                        const tab_semantic = try tabSemanticId(&self.tab_semantic_storage[storage_index], key, tab.id());
                        tab_storage_index += 1;
                        const id: ui.Id = .{ .value = tab_semantic };
                        var renaming = false;
                        // The branch row's parent: the tab, or the rename
                        // input standing in for it, so the id stays a child
                        // of a registered element either way.
                        var branch_parent = id;
                        if (self.rename_tab_id) |rename_id| {
                            if (rename_id == tab.id()) {
                                if (self.rename_input) |*field| {
                                    renaming = true;
                                    const rename_semantic = try tabRenameSemanticId(&self.tab_rename_semantic_storage, key);
                                    branch_parent = .{ .value = rename_semantic };
                                    try self.ui_tree.addInput(.{
                                        .id = .{ .value = rename_semantic },
                                        .parent = workspace_id,
                                        .role = "input",
                                        .label = "Tab name",
                                        .action = tab_rename_commit_action,
                                        .bounds = .{ .x = 2, .y = row, .width = content_width - 1, .height = 1 },
                                        .offset_px = group_offset_px,
                                    }, field, .{
                                        .text = .{ .foreground = .strong, .background = .field },
                                        .selection_background = .selection,
                                        .cursor_background = .accent,
                                        .cursor_foreground = .background,
                                    });
                                }
                            }
                        }
                        if (!renaming) {
                            const tab_selected = model.activeTabId() == tab.id();
                            // An agent's tab leads with its state glyph in
                            // place of TASK-29's `* `/`! ` marks (TASK-56).
                            var tab_label = tab.displayLabel();
                            const agent_session = model.focusedPaneSessionId(tab.id()) orelse tab.sessionId();
                            const tab_agent = self.agents.agentForSession(key, agent_session) orelse self.agents.agentForSession(key, tab.sessionId());
                            if (tab_agent) |record| {
                                tab_label = std.fmt.bufPrint(&self.agent_tab_labels[storage_index], "{s} {s}", .{ app_agents.stateGlyph(record.state), tab.name() }) catch tab.displayLabel();
                                if (agent_state_slot < sidebar_element_capacity) {
                                    const state_id = try std.fmt.bufPrint(&self.agent_state_ids[self.agent_state_id_generation][agent_state_slot], "{s}.agent.{s}", .{ tab_semantic, @tagName(record.state) });
                                    agent_state_slot += 1;
                                    try self.ui_tree.addText(.{
                                        .id = .{ .value = state_id },
                                        .parent = workspace_id,
                                        .role = "agent_state",
                                        .label = @tagName(record.state),
                                        .bounds = .{ .x = 2, .y = row, .width = 1, .height = 1 },
                                        .offset_px = group_offset_px,
                                    }, .{ .runs = &.{} });
                                }
                            } else if (self.controlStatusFor(key, tab.id())) |mark| {
                                // A harness's `tab.status` (TASK-60).
                                tab_label = controlTabLabel(&self.agent_tab_labels[storage_index], tab.displayLabel(), tab.name(), mark);
                            }
                            try self.ui_tree.addInteractiveText(.{
                                .id = id,
                                .parent = workspace_id,
                                .role = "tab",
                                .label = tab_label,
                                .selected = tab_selected,
                                .action = tab_activate_action,
                                .bounds = .{ .x = 2, .y = row, .width = content_width - 1, .height = 1 },
                                .offset_px = group_offset_px,
                            }, .{
                                .id = id,
                                .label = tab_label,
                                .action = tab_activate_action,
                                .normal = if (tab_selected)
                                    .{ .foreground = .strong, .background = .selection }
                                else
                                    .{ .foreground = .foreground },
                                .hovered = .{ .foreground = .strong, .underline = .accent },
                                .focused = .{ .foreground = .strong, .background = .selection },
                            });
                        }

                        // The tab's branch, when its focused session's cwd is
                        // in a work tree (TASK-76): a second, non-interactive
                        // row in the small muted face. A tab outside a
                        // repository has no such row, so the list reclaims it.
                        const session_id = model.focusedPaneSessionId(tab.id()) orelse continue;
                        const head = self.gitHead(key, session_id) orelse continue;
                        if (row + 1 >= row_limit or content_width < 3) continue;
                        row += 1;
                        const branch_semantic = try tabBranchSemanticId(&self.tab_branch_semantic_storage[storage_index], key, tab.id());
                        // The semantic label is the whole name; the painted
                        // run ends in an ellipsis when the row clips it.
                        const branch_runs = [_]ui.Run{.{
                            .text = ellipsizeToCells(&self.tab_branch_label_storage[storage_index], head.text(), content_width - 2),
                            .style = .{ .foreground = .muted, .small = true },
                        }};
                        try self.ui_tree.addText(.{
                            .id = .{ .value = branch_semantic },
                            .parent = branch_parent,
                            .role = "branch",
                            .label = head.text(),
                            .bounds = .{ .x = 3, .y = row, .width = content_width - 2, .height = 1 },
                            .offset_px = group_offset_px,
                        }, .{ .runs = &branch_runs });
                    }
                }

                if (canvas_bounds.height > footer_rows + 1) {
                    // A settings problem stays visible until the file is
                    // fixed; it sits above the transient status line and
                    // clips at the sidebar edge rather than wrapping.
                    if (config_error) |message| {
                        const error_runs = [_]ui.Run{.{
                            .text = message,
                            .style = .{ .foreground = .danger },
                        }};
                        try self.ui_tree.addText(.{
                            .id = .{ .value = "config.error" },
                            .parent = .{ .value = "sidebar" },
                            .role = "config_error",
                            .label = message,
                            .bounds = .{ .x = 1, .y = canvas_bounds.height - footer_rows, .width = content_width, .height = 1 },
                        }, .{ .runs = &error_runs });
                    }
                    if (self.workspace_status) |status| {
                        const runs = [_]ui.Run{.{
                            .text = status,
                            .style = .{ .foreground = .attention },
                        }};
                        try self.ui_tree.addText(.{
                            .id = .{ .value = "workspace.status" },
                            .parent = .{ .value = "sidebar" },
                            .role = "status",
                            .label = status,
                            .bounds = .{ .x = 1, .y = canvas_bounds.height - 4, .width = content_width, .height = 1 },
                        }, .{ .runs = &runs });
                    }

                    // The footer is the mouse path to every sidebar command:
                    // the palette lists each one with its chord, so one hint
                    // replaces a stack of per-action controls.
                    var chord_storage: [96]u8 = undefined;
                    const chords = palette_mod.formatActionBindings(
                        &chord_storage,
                        palette_open_action,
                        self.bindings,
                        self.binding_profile,
                    );
                    const hint_label = if (chords.text.len == 0)
                        "Palette"
                    else
                        try std.fmt.bufPrint(&self.sidebar_palette_label_storage, "Palette  {s}", .{chords.text});
                    const hint_id: ui.Id = .{ .value = "sidebar.palette" };
                    try self.ui_tree.addInteractiveText(.{
                        .id = hint_id,
                        .parent = .{ .value = "sidebar" },
                        .role = "palette_hint",
                        .label = hint_label,
                        .action = palette_open_action,
                        .bounds = centeredFooterRow(hint_label, content_width, canvas_bounds.height - 3),
                    }, .{
                        .id = hint_id,
                        .label = hint_label,
                        .action = palette_open_action,
                        .normal = .{ .foreground = .muted },
                        .hovered = .{ .foreground = .strong, .underline = .accent },
                        .focused = .{ .foreground = .on_accent, .background = .accent },
                    });

                    const version_label = "v" ++ version;
                    const version_runs = [_]ui.Run{.{
                        .text = version_label,
                        .style = .{ .foreground = .muted },
                    }};
                    try self.ui_tree.addText(.{
                        .id = .{ .value = "sidebar.version" },
                        .parent = .{ .value = "sidebar" },
                        .role = "version",
                        .label = version_label,
                        .bounds = centeredFooterRow(version_label, content_width, canvas_bounds.height - 2),
                    }, .{ .runs = &version_runs });
                }
            }

            const divider_id: ui.Id = .{ .value = "sidebar.divider" };
            try self.ui_tree.addInteractiveText(.{
                .id = divider_id,
                .parent = .{ .value = "sidebar" },
                .role = "separator",
                .label = "",
                .action = sidebar_resize_action,
                .bounds = .{ .x = origin - 1, .y = 0, .width = 1, .height = canvas_bounds.height },
            }, .{
                .id = divider_id,
                .label = "",
                .action = sidebar_resize_action,
            });
            if (origin >= 3 and canvas_bounds.height != 0) {
                const collapse_id: ui.Id = .{ .value = "sidebar.collapse" };
                try self.ui_tree.addInteractiveText(.{
                    .id = collapse_id,
                    .parent = .{ .value = "sidebar" },
                    .role = "sidebar_toggle",
                    .label = "‹",
                    .action = sidebar_toggle_action,
                    .bounds = .{ .x = origin - 2, .y = 0, .width = 1, .height = 1 },
                }, .{
                    .id = collapse_id,
                    .label = "‹",
                    .action = sidebar_toggle_action,
                    .normal = .{ .foreground = .accent },
                    .hovered = .{ .foreground = .strong, .background = .selection },
                    .focused = .{ .foreground = .strong, .background = .selection },
                });
            }
        }

        for (self.pane_layouts[0..self.pane_layout_count], 0..) |layout, index| {
            if (layout.pane_id == connection_pane_id) {
                try self.composeConnectionView(layout);
                continue;
            }
            const semantic_id = try paneSemanticId(
                &self.pane_semantic_storage[index],
                self.activePresentation().key,
                layout.pane_id,
            );
            const id: ui.Id = .{ .value = semantic_id };
            const bounds: ui.Rect = .{
                .x = layout.rect.col,
                .y = layout.rect.row,
                .width = layout.rect.cols,
                .height = layout.rect.rows,
            };
            try self.ui_tree.addInteractiveText(.{
                .id = id,
                .role = "pane",
                .label = "",
                .selected = layout.focused,
                .action = pane_activate_action,
                .bounds = bounds,
            }, .{
                .id = id,
                .label = "",
                .action = pane_activate_action,
            });
            if (self.agentViewForSession(layout.session_id)) |runner| {
                try self.composeAgentView(layout, runner, id);
                continue;
            }
            if (self.activeWorkspace().sessionById(layout.session_id)) |live| {
                try self.composeTerminalLinks(
                    live.terminalConst(),
                    layout.session_id,
                    id,
                    bounds,
                );
            }
        }
        for (self.divider_layouts[0..self.divider_layout_count], 0..) |divider, index| {
            const semantic_id = try dividerSemanticId(
                &self.divider_semantic_storage[index],
                self.activePresentation().key,
                divider.divider_id,
            );
            const visual_id = try dividerVisualSemanticId(
                &self.divider_visual_storage[index],
                self.activePresentation().key,
                divider.divider_id,
            );
            const bounds: ui.Rect = .{
                .x = divider.rect.col,
                .y = divider.rect.row,
                .width = divider.rect.cols,
                .height = divider.rect.rows,
            };
            try self.ui_tree.addSurface(.{
                .id = .{ .value = visual_id },
                .role = "presentation",
                .label = "Pane divider",
                .bounds = bounds,
            }, .{ .rect = bounds, .fill = .muted });
            const id: ui.Id = .{ .value = semantic_id };
            try self.ui_tree.addInteractiveText(.{
                .id = id,
                .role = "separator",
                .label = if (divider.split == .right) "│" else "─",
                .action = pane_resize_action,
                .bounds = bounds,
            }, .{
                .id = id,
                .label = if (divider.split == .right) "│" else "─",
                .action = pane_resize_action,
                .normal = .{ .foreground = .muted },
                .hovered = .{ .foreground = .strong, .background = .selection },
                .focused = .{ .foreground = .strong, .background = .selection },
            });
        }

        try self.composeBacklog();

        if (self.scratchpadBounds()) |scratchpad_bounds| {
            const scratchpad_id: ui.Id = .{ .value = try scratchpadSemanticId(
                &self.scratchpad_semantic_storage[0],
                self.activePresentation().key,
                "",
            ) };
            try self.ui_tree.addSurface(.{
                .id = scratchpad_id,
                .role = "dialog",
                .label = "Scratchpad",
                .bounds = scratchpad_bounds,
            }, .{
                .rect = scratchpad_bounds,
                // The retained terminal supplies the opaque interior. Keeping
                // this transparent lets the terminal and semantic chrome stay
                // separate renderers on the shared surface. Erasing only the
                // earlier UI layer prevents sidebar glyphs from being painted
                // back over the terminal after its grid has drawn.
                .erase_underlay = true,
                .fill = null,
                .border = .single,
                .border_style = .{ .foreground = .border, .background = .background },
                .title = " Scratchpad ",
                .title_style = .{ .foreground = .strong, .background = .background, .face_style = .bold },
            });
            if (self.scratchpadInnerRect()) |inner| {
                const terminal_id: ui.Id = .{ .value = try scratchpadSemanticId(
                    &self.scratchpad_semantic_storage[1],
                    self.activePresentation().key,
                    "terminal",
                ) };
                try self.ui_tree.addSurface(.{
                    .id = terminal_id,
                    .parent = scratchpad_id,
                    .role = "terminal",
                    .label = "Scratchpad terminal",
                    .bounds = inner,
                }, .{ .rect = inner, .fill = null });
                if (self.scratchpadLive()) |scratchpad| {
                    try self.composeTerminalLinks(
                        scratchpad.terminalConst(),
                        self.activeWorkspace().scratchpadId(),
                        terminal_id,
                        inner,
                    );
                }
            }
            if (scratchpad_bounds.width >= 24) {
                const restart_id: ui.Id = .{ .value = try scratchpadSemanticId(
                    &self.scratchpad_semantic_storage[2],
                    self.activePresentation().key,
                    "restart",
                ) };
                try self.ui_tree.addInteractiveText(.{
                    .id = restart_id,
                    .parent = scratchpad_id,
                    .role = "action",
                    .label = "restart",
                    .action = scratchpad_restart_action,
                    .bounds = .{
                        .x = scratchpad_bounds.right() - 16,
                        .y = scratchpad_bounds.y,
                        .width = 7,
                        .height = 1,
                    },
                }, .{
                    .id = restart_id,
                    .label = "restart",
                    .action = scratchpad_restart_action,
                    .normal = .{ .foreground = .muted, .background = .background },
                    .hovered = .{ .foreground = .strong, .background = .selection },
                    .focused = .{ .foreground = .on_accent, .background = .accent },
                });
                const hide_id: ui.Id = .{ .value = try scratchpadSemanticId(
                    &self.scratchpad_semantic_storage[3],
                    self.activePresentation().key,
                    "hide",
                ) };
                try self.ui_tree.addInteractiveText(.{
                    .id = hide_id,
                    .parent = scratchpad_id,
                    .role = "action",
                    .label = "hide",
                    .action = scratchpad_hide_action,
                    .bounds = .{
                        .x = scratchpad_bounds.right() - 7,
                        .y = scratchpad_bounds.y,
                        .width = 4,
                        .height = 1,
                    },
                }, .{
                    .id = hide_id,
                    .label = "hide",
                    .action = scratchpad_hide_action,
                    .normal = .{ .foreground = .muted, .background = .background },
                    .hovered = .{ .foreground = .strong, .background = .selection },
                    .focused = .{ .foreground = .on_accent, .background = .accent },
                });
            }
        }

        try self.composeSearchHighlights();
        try self.composeSearchBar();

        const text = self.composition.preedit();
        if (!self.paletteVisible() and !self.settingsVisible() and !self.managerVisible() and !self.promptsVisible() and !self.search_visible and self.presentedAgentView() == null and
            !self.backlogShown() and text.len != 0 and std.unicode.utf8ValidateSlice(text))
        {
            if (self.presentedLive().terminal().cursor().position) |cursor| {
                if (self.presentedCellRect()) |presented_rect| {
                    const presented_right = presented_rect.right();
                    const presented_bottom = presented_rect.bottom();
                    const preedit_col = @as(u32, cursor.col) + presented_rect.x;
                    const preedit_row = @as(u32, cursor.row) + presented_rect.y;
                    if (preedit_col < presented_right and preedit_row < presented_bottom) {
                        const normal: ui.TextStyle = .{
                            .foreground = .foreground,
                            .underline = .accent,
                        };
                        const selected: ui.TextStyle = .{
                            .foreground = .strong,
                            .background = .selection,
                            .underline = .accent,
                        };
                        const selection = self.composition.selection();
                        const start = @min(@as(usize, selection.start), text.len);
                        const end = @min(start +| @as(usize, selection.length), text.len);
                        var runs_buffer: [3]ui.Run = undefined;
                        var run_count: usize = 0;
                        if (selection.length != 0 and utf8Boundary(text, start) and utf8Boundary(text, end)) {
                            if (start != 0) {
                                runs_buffer[run_count] = .{ .text = text[0..start], .style = normal };
                                run_count += 1;
                            }
                            runs_buffer[run_count] = .{ .text = text[start..end], .style = selected };
                            run_count += 1;
                            if (end != text.len) {
                                runs_buffer[run_count] = .{ .text = text[end..], .style = normal };
                                run_count += 1;
                            }
                        } else {
                            runs_buffer[0] = .{ .text = text, .style = normal };
                            run_count = 1;
                        }

                        try self.ui_tree.addText(.{
                            .id = .{ .value = "ime.preedit" },
                            .role = "preedit",
                            .label = text,
                            .bounds = .{
                                .x = preedit_col,
                                .y = preedit_row,
                                .width = presented_right - preedit_col,
                                .height = 1,
                            },
                        }, .{ .runs = runs_buffer[0..run_count] });
                    }
                }
            }
        }
        if (origin == 0 and self.sidebar_enabled and canvas_bounds.width != 0 and canvas_bounds.height != 0) {
            // The hidden-sidebar affordance deliberately overlaps the active
            // pane's first cell. Registering it after pane content makes only
            // that one-cell chrome win painter order and semantic hit testing;
            // every other pane-body press keeps its terminal routing behavior.
            const reveal_id: ui.Id = .{ .value = "sidebar.reveal" };
            try self.ui_tree.addInteractiveText(.{
                .id = reveal_id,
                .role = "sidebar_toggle",
                .label = "›",
                .action = sidebar_toggle_action,
                .bounds = .{ .x = 0, .y = 0, .width = 1, .height = 1 },
            }, .{
                .id = reveal_id,
                .label = "›",
                .action = sidebar_toggle_action,
                .normal = .{ .foreground = .accent },
                .hovered = .{ .foreground = .strong, .background = .selection },
                .focused = .{ .foreground = .strong, .background = .selection },
            });
        }
        if (self.paletteVisible()) try self.composePalette();
        if (self.settingsVisible()) try self.composeSettings();
        if (self.contextMenuVisible()) try self.composeContextMenu();
        if (self.notificationsVisible()) try self.composeNotifications();
        if (self.managerVisible()) try self.composeManager();
        if (self.promptsVisible()) try self.composePrompts();
        if (self.closeModalActive()) {
            const modal_width = @min(canvas_bounds.width, @as(u32, 42));
            const modal_height = @min(canvas_bounds.height, @as(u32, 7));
            if (modal_width >= 12 and modal_height >= 5) {
                const modal_bounds: ui.Rect = .{
                    .x = (canvas_bounds.width - modal_width) / 2,
                    .y = (canvas_bounds.height - modal_height) / 2,
                    .width = modal_width,
                    .height = modal_height,
                };
                const closing_pane = self.pending_close_pane != null;
                const closing_workspace = self.pending_close_workspace != null;
                const modal_id: ui.Id = .{ .value = if (closing_workspace) "workspace-close.dialog" else "tab-close.dialog" };
                const question = if (closing_workspace)
                    "Close workspace and all sessions?"
                else if (closing_pane)
                    "Close running pane?"
                else
                    "Close running tab?";
                try self.ui_tree.addSurface(.{
                    .id = modal_id,
                    .role = "dialog",
                    .label = question,
                    .bounds = modal_bounds,
                }, .{
                    .rect = modal_bounds,
                    .fill = .background,
                    .border = .double,
                    .border_style = .{ .foreground = .attention },
                    .title = if (closing_workspace) " Close workspace? " else if (closing_pane) " Close pane? " else " Close tab? ",
                    .title_style = .{ .foreground = .attention, .face_style = .bold },
                });
                const message_runs = [_]ui.Run{.{
                    .text = if (closing_workspace) "All workspace sessions will stop." else "A process is still running.",
                    .style = .{ .foreground = .strong },
                }};
                try self.ui_tree.addText(.{
                    .id = .{ .value = if (closing_workspace) "workspace-close.message" else "tab-close.message" },
                    .parent = modal_id,
                    .role = "text",
                    .label = if (closing_workspace) "All workspace sessions will stop." else "A process is still running.",
                    .bounds = .{ .x = modal_bounds.x + 2, .y = modal_bounds.y + 2, .width = modal_bounds.width - 4, .height = 1 },
                }, .{ .runs = &message_runs });
                const choices = [_]struct { id: []const u8, label: []const u8, action: []const u8, x: u32 }{
                    .{
                        .id = if (closing_workspace) "workspace-close.cancel" else "tab-close.cancel",
                        .label = "cancel",
                        .action = if (closing_workspace) workspace_close_cancel_action else tab_close_cancel_action,
                        .x = modal_bounds.x + 2,
                    },
                    .{
                        .id = if (closing_workspace) "workspace-close.confirm" else "tab-close.confirm",
                        .label = "close",
                        .action = if (closing_workspace) workspace_close_confirm_action else tab_close_confirm_action,
                        .x = modal_bounds.right() -| 9,
                    },
                };
                for (choices) |choice| {
                    const choice_id: ui.Id = .{ .value = choice.id };
                    try self.ui_tree.addInteractiveText(.{
                        .id = choice_id,
                        .parent = modal_id,
                        .role = "action",
                        .label = choice.label,
                        .action = choice.action,
                        .bounds = .{ .x = choice.x, .y = modal_bounds.bottom() - 2, .width = 7, .height = 1 },
                    }, .{
                        .id = choice_id,
                        .label = choice.label,
                        .action = choice.action,
                        .normal = .{ .foreground = .strong },
                        .hovered = .{ .foreground = .attention, .underline = .accent },
                        .focused = .{ .foreground = .on_accent, .background = .accent },
                    });
                }
            }
        }
        try self.ui_tree.endFrame();
        try self.ui_tree.render(&self.ui_canvas);
        // Assistive technology reads the same tree the frame was drawn from.
        self.publishAccessibility();
    }

    /// Make the readback buffer big enough for the current surface.
    ///
    /// The new buffer is allocated before the old one is freed, so a failed
    /// allocation leaves the app with the buffer it already had rather than
    /// with a freed one. A buffer only ever grows: a screenshot must not
    /// allocate, and a window that shrinks does not make its buffer wrong.
    fn growReadback(self: *App) !void {
        const needed = render.readbackLen(self.size);
        if (render.captureFits(self.size, self.readback.len)) return;
        const grown = try self.allocator.alloc(u8, needed);
        self.allocator.free(self.readback);
        self.readback = grown;
    }

    /// Move bytes between the child and the terminal.
    ///
    /// Neither direction waits: the read side is another thread's queue and the
    /// write side is the terminal's own answers, both copied into buffers the
    /// app already owns. That is what lets the loop's single blocking wait
    /// inside SDL stay the only wait a frame has. Returns how many output
    /// bytes this one pass fed into terminals across every workspace, which
    /// is what `drainChildren` loops on.
    fn pumpChild(self: *App) !usize {
        var drained: usize = 0;
        const pass = self.input[0..@min(self.input.len, pty_pass_capacity)];
        const presented = self.presentedLive();
        if (presented.child() != null) {
            const got = presented.drainChildOutput(pass);
            drained += got;
            const presented_key = self.activePresentation().key;
            const presented_id = self.presentedSessionId();
            if (got != 0) {
                self.noteSearchTerminalChange(self.presentedSessionId());
                if (self.trace) |trace| try trace.received.appendSlice(self.allocator, pass[0..got]);
                self.noteAgentOutput(presented_key, presented_id);
            }
            for (presented.terminal().takeEvents()) |event| {
                self.noteGitEvent(presented_key, presented_id, event);
                self.noteAgentTerminalEvent(presented_key, presented_id, event);
                self.noteTerminalEvent(presented, event);
            }
            try self.flushToChild();
        }

        // A view is not a scheduler. Every hidden session in every workspace
        // still receives PTY output and sends terminal protocol replies.
        const active_key = self.workspace_registry.activeKey() orelse unreachable;
        for (self.workspace_presentations.items) |presentation| {
            const model = self.workspace_registry.byKey(presentation.key) orelse continue;
            var event_context: WorkspaceEventContext = .{
                .app = self,
                .key = presentation.key,
            };
            const hidden = if (presentation.key == active_key)
                model.pumpExcept(
                    self.presentedSessionId(),
                    pass,
                    self.output,
                    .{ .ptr = &event_context, .on_events = noteWorkspaceEvents },
                )
            else
                model.pump(
                    pass,
                    self.output,
                    .{ .ptr = &event_context, .on_events = noteWorkspaceEvents },
                );
            drained +|= hidden.bytes_drained;
            if (hidden.first_error) |err| log.warn(
                "a hidden session could not write a terminal response: {s}",
                .{@errorName(err)},
            );
        }
        return drained;
    }

    /// Drain child output in a bounded loop of pumps, independently of drawing.
    ///
    /// One pump moves one buffer per session, a few KiB from a real PTY; a
    /// flood drained once per frame costs a whole frame per chunk. This keeps
    /// pumping while passes still find bytes, until `DrainBudget.per_wake`
    /// says the wake has spent its bytes or its time slice, so input, the
    /// test driver and the frame decision still run between slices. Nothing
    /// here blocks or allocates: each pass is the nonblocking `pumpChild`.
    fn drainChildren(self: *App, io: Io) !usize {
        const budget = workspace.DrainBudget.per_wake;
        const started = Io.Clock.awake.now(io).nanoseconds;
        var total: usize = 0;
        while (true) {
            const got = try self.pumpChild();
            total +|= got;
            const elapsed = Io.Clock.awake.now(io).nanoseconds - started;
            const elapsed_ns: u64 = if (elapsed <= 0) 0 else @intCast(@min(elapsed, std.math.maxInt(u64)));
            if (!budget.allowsAnotherPass(got, total, elapsed_ns)) return total;
        }
    }

    /// Whether any session in any workspace has output or replies waiting.
    fn outputReadable(self: *App) bool {
        for (self.workspace_presentations.items) |presentation| {
            const model = self.workspace_registry.byKey(presentation.key) orelse continue;
            if (model.needsPump()) return true;
        }
        return false;
    }

    /// Deliver events produced while the workspace services a hidden session.
    fn noteWorkspaceEvents(
        ptr: *anyopaque,
        id: session.SessionId,
        events: []const term.Event,
    ) void {
        const event_context: *WorkspaceEventContext = @ptrCast(@alignCast(ptr));
        const self = event_context.app;
        const model = self.workspace_registry.byKey(event_context.key) orelse return;
        const live = model.sessionById(id) orelse return;
        var attention_changed = model.noteBackgroundActivity(id, false);
        self.noteAgentOutput(event_context.key, id);
        for (events) |event| {
            switch (event) {
                .bell => attention_changed = model.noteBackgroundActivity(id, true) or attention_changed,
                else => {},
            }
            self.noteGitEvent(event_context.key, id, event);
            self.noteAgentTerminalEvent(event_context.key, id, event);
            self.noteTerminalEvent(live, event);
        }
        if (attention_changed) self.invalidateUi();
    }

    /// The terminal events that can change which branch a session is on:
    /// a new cwd, a prompt start (a command such as a checkout has finished)
    /// and a reset that forgot the cwd.
    fn noteGitEvent(self: *App, key: workspace.WorkspaceKey, id: session.SessionId, event: term.Event) void {
        switch (event) {
            .working_directory, .reset => self.markGitStale(key, id),
            .prompt => |mark| if (mark.kind == .prompt_start) self.markGitStale(key, id),
            else => {},
        }
    }

    /// Owe a branch refresh for one session, starting to track it if needed.
    fn markGitStale(self: *App, key: workspace.WorkspaceKey, id: session.SessionId) void {
        for (self.git_tracks.items) |*track| {
            if (track.key == key and track.session_id == id) {
                track.stale = true;
                return;
            }
        }
        self.git_tracks.append(self.allocator, .{ .key = key, .session_id = id }) catch |err| {
            log.warn("could not track a session's git branch: {s}", .{@errorName(err)});
        };
    }

    /// The branch to show for one session, when its cwd is in a work tree.
    fn gitHead(self: *const App, key: workspace.WorkspaceKey, id: session.SessionId) ?*const git.Head {
        for (self.git_tracks.items) |*track| {
            if (track.key == key and track.session_id == id) return if (track.found) &track.repo.head else null;
        }
        return null;
    }

    /// Stop tracking every session of one workspace (or of all, for null),
    /// joining lookups that borrow its context. Called before teardown.
    fn dropGitTracks(self: *App, key: ?workspace.WorkspaceKey) void {
        var index: usize = 0;
        while (index < self.git_tracks.items.len) {
            const track = &self.git_tracks.items[index];
            if (key != null and track.key != key.?) {
                index += 1;
                continue;
            }
            track.release();
            _ = self.git_tracks.swapRemove(index);
        }
    }

    /// Advance branch tracking: finish lookups, read watches, start owed
    /// refreshes and forget sessions that are gone. Returns whether a shown
    /// branch changed. Runs on the loop's poll, never per frame, and does no
    /// IO itself beyond a non-blocking watch poll and, for a Local context,
    /// creating a watch.
    fn pollGit(self: *App) bool {
        var changed = false;
        var index: usize = 0;
        while (index < self.git_tracks.items.len) {
            const track = &self.git_tracks.items[index];
            const model = self.workspace_registry.byKey(track.key);
            const live = if (model) |owner| owner.sessionById(track.session_id) else null;
            if (live == null) {
                if (track.found) changed = true;
                track.release();
                _ = self.git_tracks.swapRemove(index);
                continue;
            }
            index += 1;
            const ctx = model.?.contextRef();
            if (track.lookup) |job| {
                if (job.finished()) {
                    track.lookup = null;
                    var next: git.Repo = .{ .head = .{ .kind = .branch } };
                    const found = job.finish(&next);
                    const same_dir = found and track.found and std.mem.eql(u8, next.gitDir(), track.repo.gitDir());
                    if (found != track.found or (found and !next.head.eql(&track.repo.head))) changed = true;
                    if (!same_dir) {
                        if (track.watch) |*watch_handle| watch_handle.deinit();
                        track.watch = null;
                    }
                    track.found = found;
                    if (found) track.repo = next;
                    // Only a Local watch is created here: a remote context's
                    // watch may block on its connection, and the owner
                    // thread must not. Remote branches refresh on cwd and
                    // prompt events alone.
                    if (found and track.watch == null and ctx.kind() == .local) {
                        track.watch = ctx.watch(self.allocator, self.io, track.repo.gitDir()) catch |err| watch: {
                            log.debug("the git directory cannot be watched: {s}", .{@errorName(err)});
                            break :watch null;
                        };
                    }
                }
            }
            if (track.watch) |watch_handle| {
                if (watch_handle.pollChanges()) track.stale = true;
            }
            if (!track.stale or track.lookup != null) continue;
            track.stale = false;
            const cwd = live.?.workingDirectory() orelse {
                if (track.found) changed = true;
                track.found = false;
                if (track.watch) |*watch_handle| watch_handle.deinit();
                track.watch = null;
                continue;
            };
            track.lookup = git.Lookup.start(self.allocator, ctx, self.io, cwd) catch |err| lookup: {
                log.warn("could not start a git branch lookup: {s}", .{@errorName(err)});
                break :lookup null;
            };
        }
        return changed;
    }

    /// Say what one terminal event was, by metadata only.
    fn noteTerminalEvent(self: *App, live: *session.Session, event: term.Event) void {
        switch (event) {
            // A title is a program's idea of what the user is working on, so it
            // is untrusted text and stays at debug.
            .title => |text| log.debug("program set the title to {s}", .{text}),
            .bell => log.debug("program rang the bell", .{}),
            // A program asked for the clipboard and policy said `.ask`. M1 has no
            // prompt to answer it with, so the request is refused (the terminal
            // already replied) and only its metadata is logged — never contents.
            // Answering it needs a user gesture (CONDUIT.md §11), which is why
            // nothing here acts on it.
            .permission_request => |req| {
                if (live == self.activeLive()) {
                    if (self.trace) |trace| trace.last_permission = req;
                }
                if (req.byte_count) |count| log.info(
                    "program asked to {s} the {s} clipboard ({d} byte(s)); policy is ask and there is no prompt yet, so it was refused",
                    .{ @tagName(req.operation), @tagName(req.location), count },
                ) else log.info(
                    "program asked to {s} the {s} clipboard; policy is ask and there is no prompt yet, so it was refused",
                    .{ @tagName(req.operation), @tagName(req.location) },
                );
            },
            // The working directory a shell reported, after `term` validated it.
            // It is display data, never an action, and a path a user is in is
            // personal, so it stays at debug (CONDUIT.md §11).
            .working_directory => if (live.workingDirectory()) |dir|
                log.debug("the shell reported its working directory: {s}", .{dir})
            else
                log.debug("the shell cleared its working directory", .{}),
            .prompt => |mark| if (mark.exit_code) |code|
                log.debug("shell prompt mark {s}, exit {d}", .{ @tagName(mark.kind), code })
            else
                log.debug("shell prompt mark {s}", .{@tagName(mark.kind)}),
            .reset => log.debug("the program reset the terminal; working directory and prompt marks forgotten", .{}),
            // Display text from the program; TASK-56 shows it, never logs it.
            .notification => |n| log.debug("program asked for a notification ({d}+{d} byte(s))", .{ n.title.len, n.body.len }),
        }
    }

    /// Write everything the child is owed, from the one place that writes to it.
    ///
    /// One place and one order: the terminal's own answers first, then encoded
    /// key or mouse bytes, committed text, and finally a paste. A second write
    /// site would be two writers to one pipe, and interleaved escape sequences
    /// are a bug the program cannot reproduce. Called after every handled
    /// event as well as every frame, so borrowed committed text is consumed
    /// before the next platform event can invalidate it.
    fn flushToChild(self: *App) !void {
        const presented = self.presentedLive();
        if (presented.child() == null) {
            // Preserve the existing key/mouse and paste staging semantics while
            // a startup worker has not attached the child yet. Committed text
            // borrows the platform event and cannot outlive this call.
            _ = takeCommittedText(&self.pending_committed_text);
            return;
        }
        try self.stageChildInput();

        // The integration checks trace ordinary one-pass replies. A retained
        // reply may span two internal buffers, so only copy trace bytes when
        // the terminal queue was the complete debt before this call.
        const terminal_pending = presented.terminal().pendingResponses();
        const fresh_only = presented.pendingResponseBytes() == terminal_pending;
        const replies = try presented.flushChildResponses(self.output);
        if (fresh_only and replies.written != 0) {
            if (self.trace) |trace| {
                std.debug.assert(replies.written <= self.output.len);
                try trace.sent.appendSlice(self.allocator, self.output[0..replies.written]);
            }
        }
        if (replies.hasPending()) return;
        try self.flushStagedChildInput();
    }

    /// Copy every ephemeral or separately owned input source into one ordered
    /// queue before another platform event can invalidate committed text.
    fn stageChildInput(self: *App) !void {
        const committed = self.pending_committed_text;
        const paste_bytes = self.pending_paste orelse &.{};
        const staged = std.math.add(usize, self.child_input.len, committed.len) catch return error.OutOfMemory;
        const additional = std.math.add(usize, staged, paste_bytes.len) catch return error.OutOfMemory;
        try self.pending_child_bytes.ensureUnusedCapacity(self.allocator, additional);

        self.pending_child_bytes.appendSliceAssumeCapacity(self.child_input.slice());
        self.pending_child_bytes.appendSliceAssumeCapacity(committed);
        self.pending_child_bytes.appendSliceAssumeCapacity(paste_bytes);
        self.child_input.len = 0;
        _ = takeCommittedText(&self.pending_committed_text);
        if (self.pending_paste) |bytes| {
            self.pending_paste = null;
            self.allocator.free(bytes);
        }
    }

    /// Offer queued user bytes in order, retaining a short or zero-write tail.
    ///
    /// The child's input buffer is full when the program is not reading. The
    /// next frame retries the remainder without blocking the render thread.
    fn flushStagedChildInput(self: *App) !void {
        const child = self.presentedLive().child() orelse return;
        while (self.pending_child_offset < self.pending_child_bytes.items.len) {
            const pending = self.pending_child_bytes.items[self.pending_child_offset..];
            const took = try child.write(pending);
            if (took > pending.len) return error.SystemError;
            if (took == 0) {
                log.warn("the child took no input; {d} bytes are still owed", .{pending.len});
                return;
            }
            if (self.trace) |trace| try trace.sent.appendSlice(self.allocator, pending[0..took]);
            self.pending_child_offset += took;
        }
        self.pending_child_bytes.clearRetainingCapacity();
        self.pending_child_offset = 0;
    }

    /// Act on one wheel event, and say what happened to the log.
    ///
    /// Two possible owners, decided by the terminal rather than here: on the
    /// primary screen the viewport moves and the frame has to be redrawn, and on
    /// the alternate screen the bytes belong to the program and go out with the
    /// next `pumpChild`. Nothing is written to the child from in here, so the
    /// one write site stays the one.
    fn onWheel(self: *App, wheel: platform.Wheel) !void {
        const presented = self.presentedLive();
        const cell = self.fonts.metrics().cell;
        const origin_px = self.terminalOriginPixels();
        const origin_y_px = self.terminalOriginYPixels();
        const geometry = self.pointerGeometry();
        var terminal_wheel = wheel;
        terminal_wheel.x = clippedPaneCoordinate(
            terminal_wheel.x * self.window.state.scale.factor - @as(f32, @floatFromInt(origin_px)),
            geometry.surface_width_px,
        );
        terminal_wheel.y = clippedPaneCoordinate(
            terminal_wheel.y * self.window.state.scale.factor - @as(f32, @floatFromInt(origin_y_px)),
            geometry.surface_height_px,
        );
        const outcome = presented.terminal().scrollByWheel(
            .{
                .dy = terminal_wheel.dy,
                .precise = terminal_wheel.precise,
                .flipped = terminal_wheel.flipped,
            },
            .{
                .x = terminal_wheel.x,
                .y = terminal_wheel.y,
                .surface_width_px = geometry.surface_width_px,
                .surface_height_px = geometry.surface_height_px,
                .cell_width_px = cell.width_px,
                .cell_height_px = cell.height_px,
            },
            &self.child_input,
        );
        switch (outcome) {
            .viewport => |rows| {
                if (rows == 0) return;
                log.info("wheel: the viewport moved {d} rows, {d} above the bottom", .{
                    rows,
                    presented.terminal().viewport().offset,
                });
                self.scheduler.invalidate();
            },
            .forwarded => |sent| log.info("wheel: the program owns this one; {d} byte(s) as {s}", .{
                sent.bytes,
                @tagName(sent.reason),
            }),
        }
    }

    /// The surface and cell geometry every pointer event is measured against.
    ///
    /// Built per event rather than cached: the surface and the face both move,
    /// and a cached copy that disagreed with either would put a mouse report at
    /// a cell the pointer is not over. Six numbers per event is not a cost.
    fn terminalOriginPixels(self: *const App) u32 {
        const col = if (self.presentedCellRect()) |rect| rect.x else self.sidebarOriginColumns();
        return @as(u32, col) * self.fonts.metrics().cell.width_px;
    }

    fn terminalOriginYPixels(self: *const App) u32 {
        const row = if (self.presentedCellRect()) |rect| rect.y else 0;
        return @as(u32, row) * self.fonts.metrics().cell.height_px;
    }

    fn pointerGeometry(self: *const App) inputmod.PointerGeometry {
        const cell = self.fonts.metrics().cell;
        const rect = self.presentedCellRect();
        return .{
            .surface_width_px = if (rect) |value| value.width * cell.width_px else self.size.width -| self.terminalOriginPixels(),
            .surface_height_px = if (rect) |value| value.height * cell.height_px else self.size.height,
            .cell_width_px = cell.width_px,
            .cell_height_px = cell.height_px,
        };
    }

    fn clippedPaneCoordinate(value: f32, extent: u32) f32 {
        if (extent == 0) return 0;
        return @min(@max(value, 0), @as(f32, @floatFromInt(extent - 1)));
    }

    /// Act on one pointer button event, and say what happened to the log.
    ///
    /// The ownership decision is the terminal's, not this function's: whether a
    /// click is a mouse report or the start of a selection depends on the modes
    /// the running program has set and on whether Shift is held
    /// (`term.pointerOwner`). Bytes for a child go to `child_input` and are
    /// written by `pumpChild`, so one write site stays the one.
    fn onPointerButton(self: *App, button: platform.PointerButton) !void {
        switch (button.action) {
            .press => self.terminal_pointer_presses +|= 1,
            .repeat => {},
            .release => self.terminal_pointer_presses -|= 1,
        }
        const presented = self.presentedLive();
        const geometry = self.pointerGeometry();
        var terminal_button = button;
        terminal_button.x = clippedPaneCoordinate(
            terminal_button.x * self.window.state.scale.factor - @as(f32, @floatFromInt(self.terminalOriginPixels())),
            geometry.surface_width_px,
        );
        terminal_button.y = clippedPaneCoordinate(
            terminal_button.y * self.window.state.scale.factor - @as(f32, @floatFromInt(self.terminalOriginYPixels())),
            geometry.surface_height_px,
        );
        const event = inputmod.pointerButton(&geometry, terminal_button);
        self.last_pointer = event.pointer;
        // A middle press the user owns is a paste of the primary selection, on
        // the platforms that have one. It is the user's gesture, so it is not
        // also a mouse report; a program that captured the mouse still gets
        // its middle click, because then the press is the program's.
        if (inputmod.primaryPaste(
            button,
            presented.terminal().pointerOwner(event.mods),
            platform.primary_selection_supported,
        )) {
            self.paste(.primary);
            return;
        }
        const outcome = presented.terminal().pointerEvent(
            event,
            clickStamp(self.io),
            &self.child_input,
        );
        switch (outcome) {
            .ignored => log.debug("pointer button {s} {s}: nothing owns it", .{
                @tagName(button.action),
                @tagName(button.button),
            }),
            .selection => self.scheduler.invalidate(),
            .reported => |sent| log.info("pointer button {s} {s}: {d} byte(s) to the program", .{
                @tagName(button.action),
                @tagName(button.button),
                sent,
            }),
        }
    }

    /// Route one raw transition exactly once: shipped bindings first, then a
    /// focused semantic element, then the terminal with the resolver's exact
    /// translated press. BindingState keeps ownership through modifier-order
    /// changes, so an action fires once and its repeats/releases stay owned.
    fn onKey(self: *App, key: platform.KeyEvent) !void {
        // A UI-owned gesture keeps its release even when its press changed
        // which overlay is visible. In particular, closing the palette over
        // the scratchpad must not let the scratchpad's Escape fast path steal
        // the matching release and strand an ownership record.
        if (try self.routeOwnedUiKey(key)) return;
        // The settings view owns every key press before any binding sees it,
        // so a chord being captured never runs its current action. A release
        // of a key the terminal saw pressed still reaches the terminal.
        if (self.settingsVisible()) {
            const terminal_owned = if (uiKeyIdentity(key)) |identity| self.terminal_key_state.indexOf(identity) != null else false;
            if (key.action == .press or !terminal_owned) return self.onSettingsKey(key);
        }
        // The agent manager owns every key press the same way (TASK-58).
        if (self.managerVisible()) {
            const terminal_owned = if (uiKeyIdentity(key)) |identity| self.terminal_key_state.indexOf(identity) != null else false;
            if (key.action == .press or !terminal_owned) return self.onManagerKey(key);
        }
        // And the prompts view (TASK-59).
        if (self.promptsVisible()) {
            const terminal_owned = if (uiKeyIdentity(key)) |identity| self.terminal_key_state.indexOf(identity) != null else false;
            if (key.action == .press or !terminal_owned) return self.onPromptsKey(key);
        }
        if (try self.routeSearchKey(key)) return;
        if (try self.routeBacklogKey(key)) return;
        if (!self.paletteVisible() and self.scratchpad_escape_owned and key.key == .escape) {
            if (key.key == .escape and key.action == .release) self.scratchpad_escape_owned = false;
            return;
        }
        if (!self.paletteVisible() and !self.closeModalActive() and self.scratchpadVisible() and key.key == .escape and
            !key.mods.ctrl and !key.mods.alt and !key.mods.shift and !key.mods.super)
        {
            if (key.action == .press) {
                self.scratchpad_escape_owned = true;
                try self.setScratchpadPresentation(.hidden);
            }
            return;
        }
        // A restored SSH workspace waits for the person (TASK-65): Enter over
        // its connection view starts the connection, as `reconnect` does.
        if (key.key == .enter and !key.mods.ctrl and !key.mods.alt and !key.mods.shift and !key.mods.super and
            !self.paletteVisible() and !self.closeModalActive() and !self.scratchpadVisible() and
            !self.contextMenuVisible() and !self.notificationsVisible() and self.savedSessionWaiting())
        {
            if (key.action == .press) try self.dispatchAction(remote_reconnect_action, .{ .source = .keybinding });
            return;
        }
        var scratch: inputmod.TextScratch = .{};
        const translated = translateAppKey(&self.composition, &scratch, key);
        const modal = self.closeModalActive();
        switch (inputmod.resolve(&self.binding_state, key, translated, self.bindings)) {
            .action => |request| {
                if (modal or self.contextMenuVisible() or self.notificationsVisible()) return;
                if (self.search_visible) {
                    const input_clipboard = self.activeUiTree().focusedInput() != null and
                        (std.mem.eql(u8, request.action, clipboard_copy_action) or
                            std.mem.eql(u8, request.action, clipboard_paste_action));
                    if (!std.mem.eql(u8, request.action, palette_open_action) and !input_clipboard) return;
                }
                if (self.paletteVisible()) {
                    const input_clipboard = self.activeUiTree().focusedInput() != null and
                        (std.mem.eql(u8, request.action, clipboard_copy_action) or
                            std.mem.eql(u8, request.action, clipboard_paste_action));
                    if (!std.mem.eql(u8, request.action, palette_open_action) and !input_clipboard) return;
                }
                if (self.scratchpadVisible() and
                    !std.mem.eql(u8, request.action, scratchpad_toggle_50_action) and
                    !std.mem.eql(u8, request.action, scratchpad_toggle_90_action) and
                    !std.mem.eql(u8, request.action, scratchpad_restart_action) and
                    !std.mem.eql(u8, request.action, scratchpad_hide_action) and
                    !std.mem.eql(u8, request.action, palette_open_action) and
                    !std.mem.eql(u8, request.action, clipboard_copy_action) and
                    !std.mem.eql(u8, request.action, clipboard_paste_action)) return;
                var invocation = request.invocation;
                if (self.activeUiTree().focusedElement()) |element| invocation.origin = element.id;
                try self.dispatchAction(request.action, invocation);
            },
            .consumed => {},
            .terminal => |press| {
                if (!self.paletteVisible() and !self.search_visible and !self.contextMenuVisible() and
                    !self.notificationsVisible() and !modal and try self.routeAgentViewKey(key)) return;
                if (try self.routeFocusedUiKey(key, translated)) return;
                if (self.paletteVisible() or self.search_visible or self.contextMenuVisible() or self.notificationsVisible()) return;
                // The view covers the panes: their terminals get no keys.
                if (self.backlogShown() and !self.scratchpadVisible()) return;
                const presented = self.presentedLive();
                switch (inputmod.clipboardKey(key, .{
                    .has_selection = presented.terminal().hasSelection(),
                })) {
                    .copy => try self.dispatchAction(clipboard_copy_action, .{ .source = .keybinding }),
                    .copy_and_deselect => {
                        try self.dispatchAction(clipboard_copy_action, .{ .source = .keybinding });
                        presented.terminal().clearSelection();
                        self.scheduler.invalidate();
                    },
                    .paste => try self.dispatchAction(clipboard_paste_action, .{ .source = .keybinding }),
                    .swallow => {},
                    .terminal => {
                        self.trackTerminalKeyTransition(key);
                        self.terminal_key_route_count += 1;
                        if (key.action != .release) {
                            presented.terminal().userInput();
                            self.agents.observe(self.activePresentation().key, self.presentedSessionId(), .user_input, Io.Clock.awake.now(self.io).nanoseconds);
                        }
                        var encoded: term.EncodedKey = .{};
                        presented.terminal().setMacosOptionAsAlt(self.window.optionAsAlt() != .none);
                        presented.terminal().encodeKey(press, &encoded);
                        self.stageForChild(encoded.slice());
                        if (encoded.slice().len != 0) self.key_text_echo.recordTerminalPress(key, translated);
                    },
                }
            },
        }
    }

    fn routeSearchKey(self: *App, raw: platform.KeyEvent) !bool {
        if (self.paletteVisible() or self.contextMenuVisible() or self.notificationsVisible()) return false;
        const action = searchKeyAction(self.binding_profile, self.search_visible, raw) orelse return false;
        const identity = uiKeyIdentity(raw) orelse return true;
        if (raw.action != .press) return true;
        if (!self.ui_key_state.claim(identity, .none)) return true;
        try self.dispatchAction(action, .{ .source = .keybinding });
        return true;
    }

    fn trackTerminalKeyTransition(self: *App, key: platform.KeyEvent) void {
        const identity = uiKeyIdentity(key) orelse return;
        switch (key.action) {
            .press => _ = self.terminal_key_state.claim(identity, .none),
            .repeat => {},
            .release => if (self.terminal_key_state.indexOf(identity)) |index|
                self.terminal_key_state.release(index),
        }
    }

    fn dispatchAction(self: *App, name: []const u8, invocation: inputmod.Invocation) !void {
        // A search owns tracked page pins in the presented terminal. Any
        // unrelated command may switch or destroy that session, so release
        // the search before invoking it. Clipboard actions are edits of the
        // focused search Input and keep the search open.
        if (self.search_visible and !isSearchAction(name)) try self.closeSearch();
        try self.actions.invoke(self, name, invocation);
        if (std.mem.eql(u8, name, palette_activate_action)) return;
        _ = self.palette_model.noteUsed(name);
        self.action_dispatch_count += 1;
        self.last_dispatched_action = name;
    }

    fn terminalOpenLinkAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const origin = invocation.origin orelse return;
        const target = self.terminalLinkTarget(origin.value) orelse return;
        switch (target.kind) {
            .url => self.url_opener.open(self.allocator, target.target) catch |err| {
                log.warn("terminal URL open failed for {d} byte(s): {s}", .{ target.target.len, @errorName(err) });
                return;
            },
            .file => if (!try self.openFileReferenceTab(target)) return,
        }
        self.ui_tree.clearFocus();
        try self.refreshActiveUi();
    }

    /// Open one detected file reference in a new tab of the active workspace
    /// (decision-5): snapshot the source session's tracked cwd, build the
    /// shell-free editor argv, create the tab and spawn through the workspace
    /// `ExecutionContext`. Returns false when nothing changed. `target`
    /// borrows link storage that UI composition reuses, so every borrowed byte
    /// is copied before anything here can recompose.
    fn openFileReferenceTab(self: *App, target: TerminalLinkTarget) !bool {
        var path_storage: [link.default_max_target_bytes]u8 = undefined;
        if (target.target.len > path_storage.len) return false;
        @memcpy(path_storage[0..target.target.len], target.target);
        const path = path_storage[0..target.target.len];
        const line = target.line;
        const source_id = target.session_id;

        if (self.activePresentation().load != null) {
            log.debug("file reference ignored while another load is in flight", .{});
            return false;
        }
        if (self.remoteNotReady()) return false;
        const source = self.activeWorkspace().sessionById(source_id) orelse return false;
        const inherited = source.workingDirectory() orelse self.activeWorkspace().workingDirectory();
        const cwd = try self.allocator.dupe(u8, inherited);
        var cwd_owned = true;
        defer if (cwd_owned) self.allocator.free(cwd);
        const argv = buildFileReferenceArgv(self.allocator, path, line, cwd) catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory,
            error.UnsafePath, error.PathTooLong => {
                log.debug("file reference of {d} byte(s) was not opened: {s}", .{ path.len, @errorName(err) });
                return false;
            },
        };
        cwd_owned = false;
        return self.openEditorTab(fileReferenceLabel(path), cwd, argv);
    }

    /// Create a tab named `label` in the active workspace and start `argv` in
    /// it through the workspace `ExecutionContext`, exactly as a file
    /// reference does. Takes ownership of `cwd` and `argv` on every path.
    /// Returns false when nothing changed.
    fn openEditorTab(self: *App, label: []const u8, cwd: []u8, argv: [][]const u8) !bool {
        var cwd_owned = true;
        defer if (cwd_owned) self.allocator.free(cwd);
        var argv_owned = true;
        defer if (argv_owned) freeEntries(self.allocator, argv);
        if (!try self.prepareToLeaveActiveSession()) return false;

        try self.activePresentation().pane_renderers.ensureUnusedCapacity(self.allocator, 1);
        const expected_session = session.SessionId.fromOrdinal(@intCast(self.activeWorkspace().registeredSessionCount()));
        var pane_renderer = try self.newPaneRenderer(expected_session);
        var renderer_owned = true;
        errdefer if (renderer_owned) pane_renderer.deinit();
        const created = try self.activeWorkspace().createTab(label, self.activeLive().terminal().gridSize());
        pane_renderer.session_id = created.session_id;
        self.activePresentation().pane_renderers.appendAssumeCapacity(pane_renderer);
        renderer_owned = false;
        try self.adoptActiveTab();
        self.editor_spawn_observer.observe(argv, cwd);
        cwd_owned = false;
        argv_owned = false;
        self.startTabChildWith(created.session_id, cwd, argv);
        return true;
    }

    /// Start watching the settings file. A watcher that cannot start costs hot
    /// reload, not the run: `config.reload` still applies edits.
    fn startConfigWatcher(self: *App) void {
        const path = self.config_path orelse return;
        self.config_watcher = config.Watcher.start(self.allocator, self.io, path, self, configWake) catch |err| blk: {
            log.warn("the config file is not watched ({s}); use Reload config after editing it", .{@errorName(err)});
            break :blk null;
        };
    }

    /// The watcher thread's wake: post an event so a blocked loop iterates and
    /// `poll` sees the change. `window` is set once at startup and
    /// `SDL_PushEvent` is thread-safe; nothing else is touched here.
    fn configWake(context: *anyopaque) void {
        const self: *App = @ptrCast(@alignCast(context));
        self.window.postDriverWake() catch |err| {
            config.log.warn("could not wake the event loop for a config change: {s}", .{@errorName(err)});
        };
    }

    /// The visible error line, or null when the settings applied cleanly.
    fn configErrorText(self: *const App) ?[]const u8 {
        if (self.config_error_len == 0) return null;
        return self.config_error_storage[0..self.config_error_len];
    }

    /// Recompute the visible error line from the parse diagnostics and the
    /// asynchronous font result: the lowest line wins, file-wide first.
    fn refreshConfigError(self: *App) void {
        var best = self.config_current.firstDiagnostic();
        for ([_]?config.Diagnostic{ self.font_diagnostic, self.theme_diagnostic }) |extra| {
            const diagnostic = extra orelse continue;
            if (best == null or diagnostic.line < best.?.line) best = diagnostic;
        }
        const diagnostic = best orelse {
            self.config_error_len = 0;
            return;
        };
        var writer: std.Io.Writer = .fixed(&self.config_error_storage);
        if (diagnostic.line == 0) {
            writer.print("config: {s}", .{diagnostic.message}) catch {};
        } else {
            writer.print("config:{d}: {s}", .{ diagnostic.line, diagnostic.message }) catch {};
        }
        var len = writer.end;
        // A message cut by the fixed buffer still has to be UTF-8.
        while (len != 0 and !std.unicode.utf8ValidateSlice(self.config_error_storage[0..len])) len -= 1;
        self.config_error_len = len;
    }

    /// Read the settings file again and apply it. Main thread only.
    ///
    /// A bad line keeps that key's previous value; an unreadable file keeps
    /// every previous value; a missing file returns to the built-in layer.
    fn reloadConfig(self: *App) void {
        const path = self.config_path orelse return;
        var next = config.load(self.io, self.allocator, path, &self.config_current) catch |err| {
            log.warn("the config file could not be reloaded: {s}", .{@errorName(err)});
            return;
        };
        // A `keybind` naming a profile validates against the new profiles.
        // The list borrows nothing from the config, so `next` may replace
        // `config_current` afterwards.
        self.rebuildProfileChoices(next.settings.shell_profiles);
        const table = buildConfiguredBindings(self.allocator, &self.actions, self.binding_profile, &next, &self.binding_table) catch |err| {
            log.warn("the configured keybindings could not be rebuilt: {s}", .{@errorName(err)});
            next.deinit();
            return;
        };
        self.binding_table.deinit();
        self.binding_table = table;
        self.bindings = self.binding_table.bindings;
        self.config_current.deinit();
        self.config_current = next;
        self.config_reload_count += 1;
        logConfigDiagnostics(path, &self.config_current);
        self.applyConfigSettings() catch |err| {
            log.warn("the reloaded settings could not be fully applied: {s}", .{@errorName(err)});
        };
        self.refreshConfigError();
        self.refreshActiveUi() catch |err| log.warn("the UI could not be rebuilt after a config reload: {s}", .{@errorName(err)});
        log.info("config reloaded ({d} problem(s))", .{self.config_current.diagnostics.items.len + self.config_current.dropped_diagnostics});
    }

    /// Push `config_current`'s values into the running app: right click,
    /// scratchpad heights and, when the font request changed, a new face.
    fn applyConfigSettings(self: *App) !void {
        const settings = self.config_current.settings;
        self.right_click = config.Layer.resolve(config.RightClick, config.RightClick.built_in, settings.right_click, self.session_right_click);
        self.window.setOptionAsAlt(platformOptionAsAlt(settings.macos_option_as_alt));

        const sizes_changed = settings.scratchpad_size != self.scratchpad_percent_small or
            settings.scratchpad_large_size != self.scratchpad_percent_large;
        self.scratchpad_percent_small = settings.scratchpad_size;
        self.scratchpad_percent_large = settings.scratchpad_large_size;
        if (sizes_changed and self.scratchpadVisible()) try self.syncGrid();

        // A font command writes its key and commits the same value first, so
        // the reload its own write causes finds nothing to change here.
        const values = fontValuesFrom(self.session_font_family, settings);
        self.family_from_file = self.session_font_family == null and settings.font_family != null;
        const face_changed = !values.sameFace(self.font_settings.values);
        if (face_changed or values.ligatures != self.font_settings.values.ligatures) {
            try self.commitFontValues(values);
            if (face_changed) {
                self.font_diagnostic = null;
                log.info("the font settings changed; re-loading the face at {d:.1} points", .{values.points});
            }
        } else {
            // A line may have moved within the file.
            self.refreshFontDiagnostic();
        }
        self.reloadThemes(true);
        // Notification switches apply to the next notification; entries
        // already in the list stay.
        self.agents.settings = settings.notifications;
    }

    /// Make `values` the committed font settings: toggle ligatures in place
    /// and rebuild the face only when something else changed.
    fn commitFontValues(self: *App, values: FontValues) !void {
        const next = try FontSettings.init(self.allocator, values);
        const ligatures_changed = next.values.ligatures != self.font_settings.values.ligatures;
        self.font_settings.deinit();
        self.font_settings = next;
        if (ligatures_changed) self.applyLigatures();
        self.requestFontReload();
    }

    /// Shape with the committed ligature setting from the next frame. Every
    /// grid caches shaped rows, so each is invalidated, in every workspace.
    fn applyLigatures(self: *App) void {
        self.fonts.setLigatures(self.font_settings.values.ligatures);
        for (self.workspace_presentations.items) |presentation| {
            for (presentation.pane_renderers.items) |*record| record.grid.invalidate();
            presentation.scratchpad_grid.invalidate();
        }
        self.overlay_grid.invalidate();
        self.scheduler.invalidate();
        self.needs_present = true;
        self.invalidateUi();
    }

    /// The family to draw: the font picker's highlighted family while it
    /// previews, else the committed one.
    fn drawnFamily(self: *const App) []const u8 {
        if (self.font_preview_choice) |index| {
            if (index < self.font_choices.count) return familyForChoice(self.font_choices.choices[index].value);
        }
        return self.font_settings.values.family;
    }

    /// The face key the screen should be drawing at this scale.
    fn wantedFontKey(self: *const App) u64 {
        var values = self.font_settings.values;
        values.family = self.drawnFamily();
        return values.faceKey(self.font_scale);
    }

    /// Whether the face on screen is the one wanted, with nothing in flight.
    fn fontSettled(self: *const App) bool {
        return self.font_load == null and !self.font_reload_pending and self.font_loaded_key == self.wantedFontKey();
    }

    /// Report a configured family or fallback that is not installed, against
    /// the line that names it. Only meaningful once the drawn face is the
    /// committed one; while a load or a preview is pending the last report
    /// stands, and a face that failed to build keeps its own report.
    fn refreshFontDiagnostic(self: *App) void {
        if (self.font_load != null or self.font_preview_choice != null) return;
        const lines = &self.config_current.lines;
        if (self.font_loaded_key != self.wantedFontKey()) {
            if (self.font_diagnostic) |*diagnostic| diagnostic.line = @max(lines.get(.font_family), lines.get(.font_size));
            return;
        }
        const values = self.font_settings.values;
        self.font_diagnostic = if (self.family_from_file and values.family.len != 0 and self.fonts.isFallback())
            .{ .line = lines.get(.font_family), .message = missing_family_message }
        else if (missingFallback(&self.fonts, values.fallbacks))
            .{ .line = lines.get(.font_fallbacks), .message = missing_fallback_message }
        else
            null;
    }

    /// The user theme directory for this run, or null when the run has no
    /// settings file (and so no directory beside it).
    fn themesDirectoryPath(self: *const App, buffer: []u8) ?[]const u8 {
        const path = self.config_path orelse return null;
        return config.themesDirectory(buffer, path);
    }

    /// The name of the committed theme: a bundled id or a user file name.
    fn activeThemeName(self: *const App) []const u8 {
        return self.theme_name_storage[0..self.theme_name_len];
    }

    /// The highlighted choice while the theme picker is open, else null.
    fn themePickerSelection(self: *const App) ?usize {
        return switch (self.palette_step) {
            .choices => |step| if (step.definition_index == self.theme_pick_index) step.selected else null,
            else => null,
        };
    }

    /// Relist the themes (when `rescan`) and re-resolve the `theme` setting.
    /// Runs at startup, on every config reload and when the desktop's
    /// light/dark preference changes. Theme files are only re-read here: a
    /// file edited in the themes directory applies on the next config reload.
    fn reloadThemes(self: *App, rescan: bool) void {
        // The picker's rows are catalog indices; relisting under an open
        // picker would move them, so it closes (reverting any preview) first.
        if (self.themePickerSelection() != null) self.closePalette(true) catch |err| {
            log.warn("the theme picker could not be closed for a reload: {s}", .{@errorName(err)});
        };
        if (rescan) {
            var buffer: [path_capacity]u8 = undefined;
            self.theme_catalog.rebuild(self.io, self.allocator, self.themesDirectoryPath(&buffer), self.activeThemeName());
        }
        self.resolveTheme();
        self.theme_catalog.order(self.activeThemeName());
        self.setThemeChoices();
    }

    /// Point the `theme.pick` registry entry at the catalog's current list.
    /// `App` owns the registry's storage, so replacing the borrowed slice in
    /// place is the registry's own contract (borrowed for the entry's life).
    fn setThemeChoices(self: *App) void {
        self.action_definitions[self.theme_pick_index].palette = themePickCommand(self.theme_catalog);
    }

    fn themePickCommand(catalog: *const ThemeCatalog) inputmod.PaletteCommand {
        return .{ .argument = .{ .choices = .{
            .name = "theme",
            .prompt = "Theme",
            .values = catalog.choiceSlice(),
        } } };
    }

    /// Resolve `theme` from the current settings and the desktop preference
    /// and commit it. A value that names nothing is reported and the previous
    /// theme stays, as every other rejected setting does.
    fn resolveTheme(self: *App) void {
        self.theme_diagnostic = null;
        const line = self.config_current.lines.get(.theme);
        const selection = theme.parseSelection(self.config_current.settings.theme) catch {
            self.setThemeDiagnostic(line, "theme: expected auto:<dark>,<light>", .{});
            return;
        };
        const preference: ?theme.Kind = switch (platform.systemTheme()) {
            .light => .light,
            .dark => .dark,
            .unknown => null,
        };
        const name = selection.name(preference) orelse {
            // A file silent about the theme keeps the one restored from the
            // last session (TASK-65); otherwise Conduit's default.
            if (self.persistence.restoredTheme()) |restored| {
                if (self.theme_catalog.find(restored)) |index| {
                    self.adoptThemeEntry(index, line);
                    return;
                }
            }
            self.commitTheme(theme.default_id, default_palette);
            return;
        };
        const index = self.theme_catalog.find(name) orelse {
            self.setThemeDiagnostic(line, "theme: no bundled or user theme named `{s}`", .{name});
            return;
        };
        self.adoptThemeEntry(index, line);
    }

    /// Commit catalog entry `index`, reporting a problem its file had.
    fn adoptThemeEntry(self: *App, index: usize, line: u32) void {
        const entry = &self.theme_catalog.entries[index];
        self.theme_diagnostic = null;
        if (entry.problem) |problem| {
            if (problem.line == 0) {
                self.setThemeDiagnostic(line, "theme: {s}: {s}", .{ entry.value, problem.message });
            } else {
                self.setThemeDiagnostic(line, "theme: {s}:{d}: {s}", .{ entry.value, problem.line, problem.message });
            }
        }
        self.commitTheme(entry.value, entry.palette);
    }

    fn setThemeDiagnostic(self: *App, line: u32, comptime format: []const u8, args: anytype) void {
        var writer: std.Io.Writer = .fixed(&self.theme_diagnostic_storage);
        writer.print(format, args) catch {
            // A message cut by the fixed buffer is still the message's start.
        };
        var len = writer.end;
        while (len != 0 and !std.unicode.utf8ValidateSlice(self.theme_diagnostic_storage[0..len])) len -= 1;
        self.theme_diagnostic = .{ .line = line, .message = self.theme_diagnostic_storage[0..len] };
    }

    /// Make `palette` the committed theme named `name`, and show it unless
    /// the picker is previewing another.
    fn commitTheme(self: *App, name: []const u8, palette: theme.Palette) void {
        const len = @min(name.len, self.theme_name_storage.len);
        if (!std.mem.eql(u8, name[0..len], self.activeThemeName())) theme.log.info("theme: {s}", .{name[0..len]});
        std.mem.copyForwards(u8, self.theme_name_storage[0..len], name[0..len]);
        self.theme_name_len = len;
        self.theme_palette = palette;
        if (self.themePickerSelection() == null and !palette.eql(self.palette)) self.applyPalette(palette);
    }

    /// Draw everything with `palette` from the next frame: every pane, every
    /// workspace's scratchpad, the overlay and the cleared surface.
    fn applyPalette(self: *App, palette: theme.Palette) void {
        self.palette = palette;
        const colors = gridColors(palette);
        self.background = colors.background;
        for (self.workspace_presentations.items) |presentation| {
            for (presentation.pane_renderers.items) |*record| record.grid.setColors(colors);
            presentation.scratchpad_grid.setColors(colors);
        }
        self.overlay_grid.setColors(colors);
        self.needs_present = true;
        self.invalidateUi();
    }

    /// Keep the window showing what the picker highlights: the most recently
    /// moved-to choice, by keyboard or by hover, or the committed theme once
    /// the picker is gone. Called after every UI composition.
    fn syncThemePreview(self: *App) void {
        var wanted = self.theme_palette;
        if (self.themePickerSelection()) |selected| {
            var hovered: ?usize = null;
            for (self.ui_tree.elements()) |element| {
                if (!element.state.hovered) continue;
                hovered = paletteChoiceSemanticIndex(element.id.value, self.theme_pick_index);
            }
            if (self.theme_seen_selected == null or self.theme_seen_selected.? != selected) {
                self.theme_preview_choice = selected;
            } else if (hovered) |index| {
                if (self.theme_seen_hover == null or self.theme_seen_hover.? != index) self.theme_preview_choice = index;
            }
            self.theme_seen_selected = selected;
            self.theme_seen_hover = hovered;
            if (self.theme_preview_choice < self.theme_catalog.count) {
                wanted = self.theme_catalog.entries[self.theme_preview_choice].palette;
            }
        } else {
            self.theme_seen_selected = null;
            self.theme_seen_hover = null;
        }
        if (!wanted.eql(self.palette)) self.applyPalette(wanted);
    }

    fn themePickAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const value = argument(invocation, "theme") orelse return;
        const index = self.theme_catalog.find(value) orelse {
            self.setWorkspaceStatus("No such theme");
            return;
        };
        // The value is borrowed from the catalog, which `order` reshuffles.
        var name_buffer: [theme_name_capacity]u8 = undefined;
        const entry_value = self.theme_catalog.entries[index].value;
        const name = name_buffer[0..@min(entry_value.len, name_buffer.len)];
        @memcpy(name, entry_value[0..name.len]);
        self.adoptThemeEntry(index, self.config_current.lines.get(.theme));
        self.theme_catalog.order(name);
        self.setThemeChoices();
        if (self.config_path) |path| {
            config.writeDocumentValue(self.io, self.allocator, path, .theme, name) catch |err| {
                log.warn("the chosen theme could not be saved to the config file: {s}", .{@errorName(err)});
                self.setWorkspaceStatus("Theme applied; config file not updated");
            };
        }
        self.refreshConfigError();
        try self.refreshActiveUi();
    }

    /// The highlighted choice while the font picker is open, else null.
    fn fontPickerSelection(self: *const App) ?usize {
        return switch (self.palette_step) {
            .choices => |step| if (step.definition_index == self.font_pick_index) step.selected else null,
            else => null,
        };
    }

    /// Point the `font.pick` registry entry at the current family list.
    fn setFontChoices(self: *App) void {
        self.action_definitions[self.font_pick_index].palette = fontPickCommand(self.font_choices);
    }

    fn fontPickCommand(choices: *const FontChoices) inputmod.PaletteCommand {
        return .{ .argument = .{ .choices = .{
            .name = "family",
            .prompt = "Font family",
            .values = choices.slice(),
        } } };
    }

    /// Relist the installed families from the drawn face's catalog. Only while
    /// the palette is closed: an open picker's rows are indices into the list.
    fn rebuildFontChoices(self: *App) void {
        if (self.paletteVisible()) return;
        self.font_choices.rebuild(self.allocator, &self.fonts.catalog, self.font_settings.values.family);
        self.setFontChoices();
    }

    /// Keep the face following what the font picker highlights, by keyboard
    /// or by hover, and return to the committed family once the picker
    /// closes without a choice. Called after every UI composition; returns
    /// whether the wanted face changed, so the frame can be composed again
    /// with the preview line hidden until that face lands.
    fn syncFontPreview(self: *App) bool {
        const before = self.font_preview_choice;
        if (self.fontPickerSelection()) |selected| {
            var hovered: ?usize = null;
            for (self.ui_tree.elements()) |element| {
                if (!element.state.hovered) continue;
                hovered = paletteChoiceSemanticIndex(element.id.value, self.font_pick_index);
            }
            if (self.font_seen_selected == null or self.font_seen_selected.? != selected) {
                self.font_preview_choice = selected;
            } else if (hovered) |index| {
                if (self.font_hover_moved and (self.font_seen_hover == null or self.font_seen_hover.? != index)) self.font_preview_choice = index;
            }
            self.font_seen_selected = selected;
            if (self.font_hover_moved) self.font_seen_hover = hovered;
            self.font_hover_moved = false;
        } else {
            self.font_seen_selected = null;
            self.font_seen_hover = null;
            self.font_hover_moved = false;
            // A committing choice keeps its preview: the action adopts it.
            if (!self.font_pick_committing) self.font_preview_choice = null;
        }
        if (std.meta.eql(before, self.font_preview_choice)) return false;
        self.requestFontReload();
        return true;
    }

    /// The `palette.preview` line: which family the window is drawn with,
    /// once the highlighted family has landed. Null while it is loading.
    fn fontPreviewLine(self: *App) ?[]const u8 {
        if (!self.fontSettled()) return null;
        return std.fmt.bufPrint(&self.font_preview_label, "Showing {s}{s}", .{
            self.fonts.familyName(),
            if (self.fonts.isFallback()) " (bundled)" else "",
        }) catch self.font_preview_label[0..];
    }

    /// Commit a font command's change, save its key and redraw. The live
    /// state changes first, so the reload the write causes is a no-op.
    fn commitFontCommand(self: *App, values: FontValues, key: config.Key, value: []const u8) !void {
        try self.commitFontValues(values);
        if (self.config_path) |path| {
            config.writeDocumentValue(self.io, self.allocator, path, key, value) catch |err| {
                log.warn("the font setting could not be saved to the config file: {s}", .{@errorName(err)});
                self.setWorkspaceStatus("Font applied; config file not updated");
            };
        } else {
            log.info("no settings file for this run; the font change is not saved", .{});
        }
        self.refreshFontDiagnostic();
        self.refreshConfigError();
        try self.refreshActiveUi();
    }

    fn fontPickAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        defer self.font_pick_committing = false;
        const value = argument(invocation, "family") orelse return;
        const requested = familyForChoice(value);
        // Any installed family can be named (a keybinding may), not only a
        // listed one; the bundled face is the empty family.
        if (requested.len != 0 and (!usableFontFamilyName(requested) or self.fonts.catalog.findFamily(requested) == null)) {
            self.setWorkspaceStatus("No such font family");
            return;
        }
        var family_buffer: [font_family_capacity]u8 = undefined;
        const family = family_buffer[0..requested.len];
        @memcpy(family, requested);
        // The preview, if any, is adopted: the committed family is now it.
        self.font_preview_choice = null;
        var values = self.font_settings.values;
        values.family = configuredFamily(self.session_font_family, family);
        self.family_from_file = self.session_font_family == null;
        if (self.session_font_family != null) self.setWorkspaceStatus("Saved; --font overrides it for this run");
        try self.commitFontCommand(values, .font_family, family);
        self.rebuildFontChoices();
    }

    fn stepFontSize(self: *App, points: f32) !void {
        var values = self.font_settings.values;
        values.points = points;
        var buffer: [16]u8 = undefined;
        const text = try std.fmt.bufPrint(&buffer, "{d}", .{points});
        try self.commitFontCommand(values, .font_size, text);
    }

    fn fontSizeIncreaseAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        try self.stepFontSize(config.stepFontPoints(self.font_settings.values.points, .increase));
    }

    fn fontSizeDecreaseAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        try self.stepFontSize(config.stepFontPoints(self.font_settings.values.points, .decrease));
    }

    /// Back to the built-in size, written as `font.size = 14` so the file and
    /// the window agree rather than the file still naming the old size.
    fn fontSizeResetAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        try self.stepFontSize(config.default_font_points);
    }

    fn fontLigaturesToggleAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        var values = self.font_settings.values;
        values.ligatures = !values.ligatures;
        try self.commitFontCommand(values, .font_ligatures, if (values.ligatures) "true" else "false");
        self.setWorkspaceStatus(if (values.ligatures) "Ligatures on" else "Ligatures off");
    }

    fn fontSymbolsToggleAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        var values = self.font_settings.values;
        values.builtin_symbols = !values.builtin_symbols;
        try self.commitFontCommand(values, .font_nerd_symbols, if (values.builtin_symbols) "true" else "false");
        self.setWorkspaceStatus(if (values.builtin_symbols) "Built-in symbols on" else "Built-in symbols off");
    }

    /// Set `font.fallbacks` from a comma-separated list, or clear it with
    /// `none`. Names are written as typed (trimmed); one that is not
    /// installed is skipped by the font manager and reported in the sidebar.
    fn fontFallbacksAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const text = argument(invocation, "families") orelse return;
        var names: [config.max_font_fallbacks][]const u8 = undefined;
        const families: []const []const u8 = if (std.ascii.eqlIgnoreCase(std.mem.trim(u8, text, " \t"), "none"))
            &.{}
        else
            config.splitFallbacks(text, &names) catch {
                self.setWorkspaceStatus("At most 8 fallback families");
                try self.refreshActiveUi();
                return;
            };
        for (families) |family| {
            if (std.mem.indexOfScalar(u8, family, '"') != null) {
                self.setWorkspaceStatus("A family name cannot contain a quote");
                try self.refreshActiveUi();
                return;
            }
        }
        var buffer: [config.max_string_bytes]u8 = undefined;
        const value = config.formatFallbacks(&buffer, families) catch {
            self.setWorkspaceStatus("Fallback list is too long");
            try self.refreshActiveUi();
            return;
        };
        var values = self.font_settings.values;
        values.fallbacks = families;
        try self.commitFontCommand(values, .font_fallbacks, value);
    }

    fn configOpenAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        if (!try self.openConfigFile()) return;
        self.ui_tree.clearFocus();
        try self.refreshActiveUi();
    }

    fn configReloadAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        if (self.config_path == null) {
            self.setWorkspaceStatus("No config file for this run");
            return;
        }
        self.reloadConfig();
    }

    /// Open the settings file in a new editor tab, creating it from the
    /// documented defaults first when it does not exist. The editor is the
    /// file-reference editor (`vi -- <path>`), spawned through the workspace
    /// `ExecutionContext`. Returns false when nothing changed.
    fn openConfigFile(self: *App) !bool {
        const path = self.config_path orelse {
            self.setWorkspaceStatus("No config file for this run");
            return false;
        };
        if (self.activePresentation().load != null) {
            log.debug("config open ignored while another load is in flight", .{});
            return false;
        }
        ensureConfigFile(self.io, path) catch |err| {
            log.warn("the config file could not be created: {s}", .{@errorName(err)});
            self.setWorkspaceStatus("Config file could not be created");
            return false;
        };
        const inherited = self.activeLive().workingDirectory() orelse self.activeWorkspace().workingDirectory();
        const cwd = try self.allocator.dupe(u8, inherited);
        var cwd_owned = true;
        defer if (cwd_owned) self.allocator.free(cwd);
        const argv = buildFileReferenceArgv(self.allocator, path, null, cwd) catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory,
            error.UnsafePath, error.PathTooLong => {
                log.warn("the config path cannot be passed to the editor: {s}", .{@errorName(err)});
                return false;
            },
        };
        cwd_owned = false;
        return self.openEditorTab("config", cwd, argv);
    }

    fn clipboardCopyAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        if (self.activeUiTree().focusedInput()) |field| {
            const selected = field.selection();
            if (selected.isEmpty()) return;
            const text = field.text()[selected.start..selected.end];
            platform.setClipboardText(self.allocator, text) catch |err| {
                log.warn("copy of {d} focused-input byte(s) failed: {s}", .{ text.len, @errorName(err) });
                return;
            };
            log.info("copied {d} byte(s) from focused input to the clipboard", .{text.len});
            return;
        }
        if (self.presentedAgentView()) |runner| return self.copyAgentViewSelection(runner);
        if (!self.presentedLive().terminal().hasSelection()) return;
        const copied = self.copySelectionTo(.standard) catch |err| {
            log.warn("terminal selection copy failed: {s}", .{@errorName(err)});
            return;
        };
        log.info("copied {d} byte(s) to the clipboard", .{copied});
    }

    fn clipboardPasteAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        if (self.activeUiTree().focusedInput()) |field| {
            const text = platform.getClipboardText(self.allocator) catch |err| {
                log.warn("focused-input clipboard read failed: {s}", .{@errorName(err)});
                return;
            };
            defer self.allocator.free(text);
            field.paste(text) catch |err| {
                log.warn("paste of {d} byte(s) into focused input rejected: {s}", .{ text.len, @errorName(err) });
                return;
            };
            if (field == &self.palette_query and self.palette_step == .commands) {
                self.palette_model.refresh(field.text());
            }
            if (field == &self.palette_argument and self.choiceFilterActive()) self.refreshChoiceFilter();
            if (field == &self.search_query and self.search_visible) self.restartSearch();
            try self.refreshActiveUi();
            return;
        }
        // The view shows no terminal to paste into; the raw terminal takes
        // pastes once the view is toggled off.
        if (self.presentedAgentView() != null) return;
        self.paste(.standard);
    }

    fn sidebarToggleAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        if (!self.sidebar_enabled) return;
        self.sidebar_visible = !self.sidebar_visible;
        self.sidebar_dragging = false;
        try self.syncGrid();
        try self.composeUi();
        self.invalidateUi();
    }

    fn sidebarNarrowAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        if (!self.sidebar_enabled or !self.sidebar_visible) return;
        self.sidebar_width_cols -|= sidebar_resize_step;
        self.sidebar_width_cols = @max(self.sidebar_width_cols, sidebar_min_width);
        try self.syncGrid();
        try self.composeUi();
        self.invalidateUi();
    }

    fn sidebarWidenAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        if (!self.sidebar_enabled or !self.sidebar_visible) return;
        self.sidebar_width_cols +|= sidebar_resize_step;
        self.sidebar_width_cols = @min(self.sidebar_width_cols, sidebar_max_width);
        try self.syncGrid();
        try self.composeUi();
        self.invalidateUi();
    }

    fn setWorkspaceStatus(self: *App, message: []const u8) void {
        self.workspace_status = message;
        self.invalidateUi();
    }

    fn openWorkspaceActionInput(self: *App, action_name: []const u8) !void {
        if (self.paletteVisible() or self.closeModalActive() or self.rename_tab_id != null or
            self.terminal_key_state.len != 0 or self.terminal_pointer_presses != 0 or
            self.ui_pointer_owned or self.palette_pointer_owned or
            self.scratchpad_ui_pointer_owned or self.scratchpad_terminal_pointer_owned or
            self.sidebar_dragging or self.dragged_divider_id != null or self.dragged_tab_id != null)
        {
            return;
        }
        var definition_index: ?usize = null;
        for (self.actions.definitions(), 0..) |definition, index| {
            if (std.mem.eql(u8, definition.name, action_name)) {
                definition_index = index;
                break;
            }
        }
        self.composition.cancel();
        _ = takeCommittedText(&self.pending_committed_text);
        try self.window.stopTextInput();
        clearPaletteInput(&self.palette_argument);
        self.palette_step = .commands;
        try self.beginPaletteArgument(definition_index orelse return);
    }

    fn normalizedWorkspaceDirectory(text: []const u8) []const u8 {
        const trimmed = std.mem.trim(u8, text, std.ascii.whitespace[0..]);
        var end = trimmed.len;
        while (end > 1 and (trimmed[end - 1] == '/' or trimmed[end - 1] == '\\')) {
            if (end == 3 and trimmed[1] == ':') break;
            end -= 1;
        }
        return trimmed[0..end];
    }

    fn workspaceBaseName(directory: []const u8) []const u8 {
        if (std.mem.eql(u8, directory, "/")) return directory;
        var start = directory.len;
        while (start != 0) {
            const byte = directory[start - 1];
            if (byte == '/' or byte == '\\') break;
            start -= 1;
        }
        return if (start == directory.len) directory else directory[start..];
    }

    fn uniqueWorkspaceName(self: *App, base: []const u8) ![]u8 {
        if (self.workspace_registry.keyForName(base) == null) return self.allocator.dupe(u8, base);
        var suffix: usize = 2;
        while (true) : (suffix += 1) {
            const candidate = try std.fmt.allocPrint(self.allocator, "{s} ({d})", .{ base, suffix });
            if (self.workspace_registry.keyForName(candidate) == null) return candidate;
            self.allocator.free(candidate);
        }
    }

    fn workspaceForDirectory(self: *App, directory: []const u8) ?workspace.WorkspaceKey {
        var index: usize = 0;
        while (index < self.workspace_registry.count()) : (index += 1) {
            const key = self.workspace_registry.keyAt(index) orelse continue;
            const presentation = self.presentationByKey(key) orelse continue;
            if (presentation.closing) continue;
            const model = self.workspace_registry.byKey(key) orelse continue;
            // A remote directory is not this machine's, whatever its name.
            if (model.contextKind() != .local) continue;
            if (std.mem.eql(
                u8,
                normalizedWorkspaceDirectory(model.workingDirectory()),
                directory,
            )) return key;
        }
        return null;
    }

    fn createWorkspacePresentation(
        self: *App,
        directory: []const u8,
        name: []const u8,
    ) !*WorkspacePresentation {
        const grid_size = self.activeLive().terminal().gridSize();
        var candidate = try workspace.Workspace.initLocal(
            self.io,
            self.allocator,
            name,
            directory,
            grid_size,
        );
        var candidate_owned = true;
        errdefer if (candidate_owned) candidate.deinit() catch |err| log.warn(
            "could not release a refused workspace: {s}",
            .{@errorName(err)},
        );
        const session_id = try candidate.createSession(.human_terminal, grid_size);
        _ = try candidate.registerTab("Terminal 1", session_id);
        const live = candidate.sessionById(session_id) orelse return error.SessionNotFound;
        live.terminal().setClipboardAccess(.{
            .read_fn = readNativeClipboard,
            .write_fn = writeNativeClipboard,
        });

        var pane_renderer = try self.newPaneRenderer(session_id);
        var pane_renderer_owned = true;
        errdefer if (pane_renderer_owned) pane_renderer.deinit();
        var pane_renderers: std.ArrayList(PaneRenderer) = .empty;
        errdefer pane_renderers.deinit(self.allocator);
        try pane_renderers.ensureUnusedCapacity(self.allocator, 1);
        pane_renderers.appendAssumeCapacity(pane_renderer);
        pane_renderer_owned = false;
        errdefer pane_renderers.items[0].deinit();

        var scratchpad_grid = try render.Grid.init(self.allocator, gridColors(self.palette));
        var scratchpad_grid_owned = true;
        errdefer if (scratchpad_grid_owned) scratchpad_grid.deinit();
        try scratchpad_grid.attachAtlas(self.fonts.atlasPixels(), self.atlas);

        try self.workspace_presentations.ensureUnusedCapacity(self.allocator, 1);
        const presentation = try self.allocator.create(WorkspacePresentation);
        errdefer self.allocator.destroy(presentation);
        const key = try self.workspace_registry.insert(&candidate);
        candidate_owned = false;
        presentation.* = .{
            .key = key,
            .active_session_id = session_id,
            .pane_renderers = pane_renderers,
            .scratchpad_grid = scratchpad_grid,
        };
        scratchpad_grid_owned = false;
        self.workspace_presentations.appendAssumeCapacity(presentation);
        return presentation;
    }

    fn workspaceTransitionBlocked(self: *const App) bool {
        const owns_only_activation_key = self.ui_key_state.len == 1 and switch (self.ui_key_state.storage[0].identity) {
            .named => |key| key == .enter,
            .character => false,
        };
        return self.terminal_key_state.len != 0 or
            (self.ui_key_state.len != 0 and !owns_only_activation_key) or
            self.terminal_pointer_presses != 0 or
            self.ui_pointer_owned or self.palette_pointer_owned or self.sidebar_dragging or
            self.dragged_divider_id != null or self.dragged_tab_id != null or
            self.scratchpad_ui_pointer_owned or self.scratchpad_terminal_pointer_owned or
            self.scratchpad_escape_owned or self.rename_tab_id != null;
    }

    fn activeWorkspaceClosing(self: *const App) bool {
        return self.workspace_registry.count() != 0 and self.activePresentationConst().closing;
    }

    fn prepareWorkspaceTransition(self: *App) !bool {
        if (self.workspaceTransitionBlocked()) {
            self.setWorkspaceStatus("workspace switch deferred: input owned");
            return false;
        }
        if (!try self.prepareToLeaveActiveSession()) {
            self.setWorkspaceStatus("workspace switch deferred: input pending");
            return false;
        }
        return true;
    }

    fn focusWorkspaceRow(self: *App, key: workspace.WorkspaceKey) !void {
        if (!self.sidebar_visible) return;
        var storage: [workspace_semantic_capacity]u8 = undefined;
        const semantic = try workspaceSemanticId(&storage, key);
        if (self.ui_tree.focus(.{ .value = semantic })) try self.refreshActiveUi();
    }

    fn commitWorkspaceActivation(self: *App, key: workspace.WorkspaceKey, focus_row: bool) !void {
        const presentation = self.presentationByKey(key) orelse return;
        if (presentation.closing) return;
        try self.workspace_registry.activate(key);
        self.composition.cancel();
        _ = takeCommittedText(&self.pending_committed_text);
        try self.window.stopTextInput();
        self.ui_tree.clearFocus();
        self.exit_logged = false;
        for (presentation.pane_renderers.items) |*pane_renderer| pane_renderer.grid.invalidate();
        presentation.scratchpad_grid.invalidate();
        self.overlay_grid.invalidateCanvasOverlay();
        self.needs_present = true;
        try self.syncGrid();
        try self.composeUi();
        if (focus_row and !self.scratchpadVisible()) try self.focusWorkspaceRow(key);
        try self.syncTextInput();
        self.workspace_status = null;
        self.invalidateUi();
    }

    fn activateWorkspaceKey(self: *App, key: workspace.WorkspaceKey, focus_row: bool) !bool {
        const presentation = self.presentationByKey(key) orelse return false;
        if (presentation.closing or self.workspace_registry.byKey(key) == null) return false;
        if (self.closeModalActive() or self.paletteVisible()) return false;
        if (self.workspace_registry.activeKey()) |active_key| {
            if (active_key == key) {
                self.workspace_status = null;
                if (focus_row) try self.focusWorkspaceRow(key) else try self.refreshActiveUi();
                return true;
            }
        }
        if (!try self.prepareWorkspaceTransition()) return false;
        try self.commitWorkspaceActivation(key, focus_row);
        return true;
    }

    fn adjacentWorkspaceKey(self: *App, key: workspace.WorkspaceKey, next: bool) ?workspace.WorkspaceKey {
        const count = self.workspace_registry.count();
        if (count < 2) return null;
        var index: usize = 0;
        while (index < count) : (index += 1) {
            const candidate = self.workspace_registry.keyAt(index) orelse continue;
            if (candidate == key) break;
        }
        if (index == count) return null;
        var step: usize = 1;
        while (step < count) : (step += 1) {
            const candidate_index = if (next)
                (index + step) % count
            else
                (index + count - (step % count)) % count;
            const candidate = self.workspace_registry.keyAt(candidate_index) orelse continue;
            const presentation = self.presentationByKey(candidate) orelse continue;
            if (!presentation.closing) return candidate;
        }
        return null;
    }

    fn moveWorkspaceFocus(self: *App, next: bool) !void {
        const focused = self.ui_tree.focusedElement() orelse return;
        const current = workspaceKeyForSemantic(focused.id.value) orelse return;
        const target = self.adjacentWorkspaceKey(current, next) orelse return;
        try self.focusWorkspaceRow(target);
    }

    fn sidebarFocusAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        if (!self.sidebar_enabled) return;
        if (!self.sidebar_visible) {
            self.sidebar_visible = true;
            self.sidebar_dragging = false;
            try self.syncGrid();
        }
        try self.composeUi();
        try self.focusWorkspaceRow(self.activePresentation().key);
    }

    fn workspaceActivateAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const origin = invocation.origin orelse return;
        const key = workspaceKeyForSemantic(origin.value) orelse return;
        _ = try self.activateWorkspaceKey(key, true);
    }

    fn workspaceCreateAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const supplied = argument(invocation, "directory") orelse {
            try self.openWorkspaceActionInput(workspace_create_action);
            return;
        };
        const directory = normalizedWorkspaceDirectory(supplied);
        if (directory.len == 0) {
            self.setWorkspaceStatus("workspace directory is empty");
            return;
        }
        if (self.workspaceForDirectory(directory)) |existing| {
            _ = try self.activateWorkspaceKey(existing, false);
            return;
        }
        if (self.closeModalActive() or self.paletteVisible() or !try self.prepareWorkspaceTransition()) return;
        const base = std.mem.trim(u8, workspaceBaseName(directory), std.ascii.whitespace[0..]);
        if (base.len == 0) {
            self.setWorkspaceStatus("workspace name is empty");
            return;
        }
        const name = try self.uniqueWorkspaceName(base);
        defer self.allocator.free(name);
        const presentation = try self.createWorkspacePresentation(directory, name);
        self.startPresentationChild(presentation, presentation.active_session_id, .{
            .argv = self.scratchpad_spec.argv,
            .env = self.scratchpad_spec.env,
        });
        self.startScratchpadFor(presentation, false);
        try self.commitWorkspaceActivation(presentation.key, false);
    }

    fn workspaceRenameAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const supplied = argument(invocation, "name") orelse {
            try self.openWorkspaceActionInput(workspace_rename_action);
            return;
        };
        const name = std.mem.trim(u8, supplied, std.ascii.whitespace[0..]);
        if (name.len == 0) {
            self.setWorkspaceStatus("workspace name is empty");
            return;
        }
        self.workspace_registry.rename(self.activePresentation().key, name) catch |err| switch (err) {
            error.EmptyName => {
                self.setWorkspaceStatus("workspace name is empty");
                return;
            },
            error.DuplicateName => {
                self.setWorkspaceStatus("workspace name already exists");
                return;
            },
            error.UnknownWorkspace => {
                self.setWorkspaceStatus("workspace no longer exists");
                return;
            },
            else => return err,
        };
        self.workspace_status = null;
        try self.refreshActiveUi();
    }

    fn workspaceSwitchAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const supplied = argument(invocation, "name") orelse {
            try self.openWorkspaceActionInput(workspace_switch_action);
            return;
        };
        const name = std.mem.trim(u8, supplied, std.ascii.whitespace[0..]);
        if (name.len == 0) {
            self.setWorkspaceStatus("workspace name is empty");
            return;
        }
        const key = self.workspace_registry.keyForName(name) orelse {
            self.setWorkspaceStatus("workspace not found");
            return;
        };
        _ = try self.activateWorkspaceKey(key, false);
    }

    fn workspaceCloseAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        if (self.closeModalActive()) return;
        self.pending_close_workspace = self.activePresentation().key;
        try self.composeUi();
        if (self.ui_tree.focus(.{ .value = "workspace-close.cancel" })) try self.refreshActiveUi();
    }

    fn workspaceCloseCancelAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        const key = self.pending_close_workspace orelse return;
        self.pending_close_workspace = null;
        try self.composeUi();
        if (!self.scratchpadVisible()) try self.focusWorkspaceRow(key);
        self.invalidateUi();
    }

    fn finalizeClosingPresentations(self: *App) bool {
        var changed = false;
        var index: usize = 0;
        while (index < self.workspace_presentations.items.len) {
            const presentation = self.workspace_presentations.items[index];
            if (!presentation.closing or presentation.load != null or presentation.scratchpad_load != null) {
                index += 1;
                continue;
            }
            // Branch lookups, harness detection and a prompts discovery
            // borrow this workspace's context; its agents and notifications
            // go with it.
            self.dropGitTracks(presentation.key);
            if (self.prompts_job) |job| {
                job.destroy();
                self.prompts_job = null;
            }
            self.agents.removeWorkspace(presentation.key);
            // Its token expires with it; a request still queued is refused.
            self.revokeControl(presentation);
            // Joins the host probe that borrows the context; the context's
            // own teardown then hangs the master up without waiting.
            self.releaseRemote(presentation);
            // Joins a backlog write that borrows the context.
            releaseBacklog(self.allocator, presentation);
            const result = self.workspace_registry.remove(presentation.key) catch {
                log.err("a closing workspace disappeared before teardown", .{});
                index += 1;
                continue;
            };
            if (result.teardown_error) |err| log.warn(
                "a workspace closed but a child could not be signalled cleanly: {s}",
                .{@errorName(err)},
            );
            for (presentation.pane_renderers.items) |*pane_renderer| pane_renderer.deinit();
            presentation.pane_renderers.deinit(self.allocator);
            presentation.scratchpad_grid.deinit();
            presentation.releaseRestoreQueue(self.allocator);
            self.allocator.destroy(presentation);
            _ = self.workspace_presentations.orderedRemove(index);
            changed = true;
            if (result.active_key == null) self.requested_shutdown = true;
        }
        return changed;
    }

    fn workspaceCloseConfirmAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        const key = self.pending_close_workspace orelse return;
        const presentation = self.presentationByKey(key) orelse {
            self.pending_close_workspace = null;
            return;
        };
        if (!try self.prepareWorkspaceTransition()) return;
        const successor = self.adjacentWorkspaceKey(key, true);
        self.pending_close_workspace = null;
        self.ui_tree.clearFocus();
        if (successor) |next| try self.commitWorkspaceActivation(next, true);
        presentation.closing = true;
        _ = self.finalizeClosingPresentations();
        if (!self.requested_shutdown) {
            try self.composeUi();
            self.invalidateUi();
        }
    }

    fn tabActivateAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const origin = invocation.origin orelse return;
        const id = self.tabIdForSemantic(origin.value) orelse return;
        _ = try self.activateTab(id);
    }

    fn workspaceKeyForSemantic(semantic_id: []const u8) ?workspace.WorkspaceKey {
        const prefix = "workspace.";
        if (!std.mem.startsWith(u8, semantic_id, prefix)) return null;
        const encoded = semantic_id[prefix.len..];
        if (encoded.len == 0 or std.mem.indexOfScalar(u8, encoded, '.') != null) return null;
        const value = std.fmt.parseUnsigned(u64, encoded, 10) catch return null;
        if (value == 0) return null;
        return @enumFromInt(value);
    }

    fn workspaceEntityForSemantic(semantic_id: []const u8, kind: []const u8) ?WorkspaceSemanticTarget {
        const prefix = "workspace.";
        if (!std.mem.startsWith(u8, semantic_id, prefix)) return null;
        const suffix = semantic_id[prefix.len..];
        const key_end = std.mem.indexOfScalar(u8, suffix, '.') orelse return null;
        const key_value = std.fmt.parseUnsigned(u64, suffix[0..key_end], 10) catch return null;
        if (key_value == 0) return null;
        const entity = suffix[key_end + 1 ..];
        if (!std.mem.startsWith(u8, entity, kind) or entity.len <= kind.len or entity[kind.len] != '.') return null;
        const ordinal = std.fmt.parseUnsigned(u32, entity[kind.len + 1 ..], 10) catch return null;
        if (ordinal == 0) return null;
        return .{ .key = @enumFromInt(key_value), .ordinal = ordinal };
    }

    fn tabIdForSemantic(self: *const App, semantic_id: []const u8) ?workspace.TabId {
        const target = workspaceEntityForSemantic(semantic_id, "tab") orelse return null;
        const active_key = self.workspace_registry.activeKey() orelse return null;
        if (target.key != active_key) return null;
        const id: workspace.TabId = @enumFromInt(target.ordinal);
        if (self.activeWorkspaceConst().tab(id) == null) return null;
        return id;
    }

    fn focusTabRow(self: *App, id: workspace.TabId) !void {
        var storage: [workspace_semantic_capacity]u8 = undefined;
        const semantic = try tabSemanticId(&storage, self.activePresentation().key, id);
        _ = self.ui_tree.focus(.{ .value = semantic });
    }

    fn activeTabRenameSemantic(self: *App, storage: []u8) ![]const u8 {
        return tabRenameSemanticId(storage, self.activePresentation().key);
    }

    fn targetTab(self: *const App, invocation: inputmod.Invocation) ?workspace.TabId {
        if (invocation.source == .mouse) {
            // A pointer acts on the tab row it was pressed on, never on
            // whichever tab happens to be active.
            const origin = invocation.origin orelse return null;
            if (!std.mem.startsWith(u8, origin.value, "workspace.")) return null;
            return self.tabIdForSemantic(origin.value);
        }
        return self.activeWorkspaceConst().activeTabId();
    }

    fn hasPendingTerminalInput(self: *const App) bool {
        const presented = self.presentedLiveConst();
        return (TerminalInputDebt{
            .encoded = self.child_input.len,
            .staged = self.pending_child_bytes.items.len,
            .committed = self.pending_committed_text.len,
            .paste = self.pending_paste != null,
            .responses = presented.pendingResponseBytes(),
        }).remains();
    }

    fn closeModalActive(self: *const App) bool {
        return self.pending_close_workspace != null or self.pending_close_tab_id != null or self.pending_close_pane != null;
    }

    fn prepareToLeaveActiveSession(self: *App) !bool {
        try self.flushToChild();
        if (!self.hasPendingTerminalInput()) return true;
        log.warn("session change deferred while input or terminal responses are pending", .{});
        return false;
    }

    fn adoptFocusedPane(self: *App) !void {
        const tab_id = self.activeWorkspace().activeTabId() orelse return error.SessionNotFound;
        const session_id = self.activeWorkspace().focusedPaneSessionId(tab_id) orelse return error.SessionNotFound;
        const live = self.activeWorkspace().sessionById(session_id) orelse return error.SessionNotFound;
        _ = self.rendererForSession(session_id) orelse return error.SessionNotFound;
        self.activePresentation().active_session_id = session_id;
        live.terminal().setClipboardAccess(.{
            .read_fn = readNativeClipboard,
            .write_fn = writeNativeClipboard,
        });
        self.exit_logged = false;
        try self.syncGrid();
        try self.syncTextInput();
        try self.composeUi();
        self.invalidateUi();
    }

    fn adoptActiveTab(self: *App) !void {
        try self.adoptFocusedPane();
    }

    fn activateTab(self: *App, id: workspace.TabId) !bool {
        _ = self.activeWorkspace().tab(id) orelse return false;
        // The person looked at it: a harness's attention mark is answered,
        // like a bell's (TASK-60).
        self.clearControlAttention(self.activePresentation().key, id);
        if (self.activeWorkspace().focusedPaneSessionId(id) == self.activePresentation().active_session_id) {
            try self.activeWorkspace().activateTab(id);
            try self.refreshActiveUi();
            return true;
        }
        if (!try self.prepareToLeaveActiveSession()) return false;
        try self.activeWorkspace().activateTab(id);
        try self.adoptActiveTab();
        return true;
    }

    fn tabNewAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        try self.openTab(null, self.defaultProfile());
    }

    /// Create and select a tab named `label` (else `Terminal <n>`) running
    /// `profile`, or the app's default child when `profile` is null.
    fn openTab(self: *App, label: ?[]const u8, profile: ?ResolvedProfile) !void {
        if (self.activePresentation().load != null) {
            log.warn("new tab deferred while another load is in flight", .{});
            return;
        }
        if (self.remoteNotReady()) return;
        if (!try self.prepareToLeaveActiveSession()) return;

        // The profile's process is built before anything changes, so a
        // failure leaves no empty tab behind.
        var profile_spec: ?ChildSpec = if (profile) |chosen| try self.profileSpec(chosen) else null;
        defer if (profile_spec) |*spec| spec.deinit();
        const cwd = try self.newTerminalCwd(profile);
        errdefer self.allocator.free(cwd);
        try self.activePresentation().pane_renderers.ensureUnusedCapacity(self.allocator, 1);
        const expected_session = session.SessionId.fromOrdinal(@intCast(self.activeWorkspace().registeredSessionCount()));
        var pane_renderer = try self.newPaneRenderer(expected_session);
        var renderer_owned = true;
        errdefer if (renderer_owned) pane_renderer.deinit();
        var name_buffer: [32]u8 = undefined;
        const name = label orelse try std.fmt.bufPrint(
            &name_buffer,
            "Terminal {d}",
            .{self.activeWorkspace().registeredSessionCount()},
        );
        const created = try self.activeWorkspace().createTab(name, self.activeLive().terminal().gridSize());
        pane_renderer.session_id = created.session_id;
        self.activePresentation().pane_renderers.appendAssumeCapacity(pane_renderer);
        renderer_owned = false;
        try self.adoptActiveTab();
        self.startProfileChild(created.session_id, cwd, &profile_spec);
    }

    /// Start a new tab's or pane's child: `spec`'s process when a profile
    /// chose one (its argv and environment move to the job, leaving `spec`
    /// empty), else the app's default. Takes ownership of `cwd`.
    fn startProfileChild(self: *App, session_id: session.SessionId, cwd: []u8, spec: *?ChildSpec) void {
        const chosen = if (spec.*) |*value| value else return self.startTabChild(session_id, cwd);
        self.profile_spawn_observer.observe(chosen.argv, cwd);
        const argv = chosen.argv;
        const env = chosen.env;
        chosen.argv = &.{};
        chosen.env = &.{};
        self.startTabChildProcess(session_id, cwd, argv, env);
    }

    fn sessionNeedsCloseConfirmation(live: *session.Session) bool {
        const child = live.child() orelse return false;
        if (child.state() != .running) return false;
        return !(live.hasSeenPromptMarks() and live.cursorIsAtPrompt());
    }

    fn tabNeedsCloseConfirmation(self: *App, tab_id: workspace.TabId) bool {
        var ordinal: usize = 0;
        while (ordinal < self.activeWorkspace().registeredSessionCount()) : (ordinal += 1) {
            const session_id = session.SessionId.fromOrdinal(@intCast(ordinal));
            const location = self.activeWorkspace().paneForSession(session_id) orelse continue;
            if (location.tab_id != tab_id) continue;
            const live = self.activeWorkspace().sessionById(session_id) orelse continue;
            if (sessionNeedsCloseConfirmation(live)) return true;
        }
        return false;
    }

    fn tabCloseAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const id = self.targetTab(invocation) orelse return;
        _ = self.activeWorkspace().tab(id) orelse return;
        if (!self.tabNeedsCloseConfirmation(id)) return self.closeTab(id);

        self.pending_close_pane = null;
        self.pending_close_tab_id = id;
        try self.composeUi();
        if (self.ui_tree.focus(.{ .value = "tab-close.cancel" })) try self.refreshActiveUi();
    }

    fn tabCloseConfirmAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        if (self.pending_close_pane) |target| {
            // Keep the modal and its bounded focus trap intact until every byte
            // already owed to the pane being closed has actually reached it.
            if (!try self.prepareToLeaveActiveSession()) return;
            self.pending_close_pane = null;
            self.pending_close_tab_id = null;
            // The modal's focused confirmation choice must not remain the
            // keyboard owner after its protected pane is gone. In particular,
            // the next Enter belongs to the newly focused terminal.
            self.ui_tree.clearFocus();
            try self.closePane(target.tab_id, target.pane_id);
            return;
        }
        const tab_id = self.pending_close_tab_id orelse return;
        if (self.activeWorkspace().activeTabId() == tab_id and
            self.activeWorkspace().tabCount() > 1 and
            !try self.prepareToLeaveActiveSession()) return;
        self.pending_close_tab_id = null;
        self.ui_tree.clearFocus();
        try self.closeTab(tab_id);
    }

    fn tabCloseCancelAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        const tab_id = self.pending_close_tab_id;
        const pane_target = self.pending_close_pane;
        if (tab_id == null and pane_target == null) return;
        self.pending_close_tab_id = null;
        self.pending_close_pane = null;
        try self.composeUi();
        if (tab_id) |id| {
            if (!self.scratchpadVisible() and self.activeWorkspace().tab(id) != null) try self.focusTabRow(id);
        }
        if (pane_target != null or self.scratchpadVisible()) self.ui_tree.clearFocus();
        try self.refreshActiveUi();
    }

    fn closeTab(self: *App, id: workspace.TabId) !void {
        if (self.activeWorkspace().tabCount() == 1) {
            // Closing the final tab follows the common terminal convention:
            // leave the app and let normal reverse-order teardown stop it.
            self.requested_shutdown = true;
            return;
        }
        const was_active = self.activeWorkspace().activeTabId() == id;
        if (was_active and !try self.prepareToLeaveActiveSession()) return;
        self.activeWorkspace().closeTab(id) catch |err| {
            log.warn("the tab closed but its child could not be signalled cleanly: {s}", .{@errorName(err)});
        };
        self.discardClosedPaneRenderers();
        if (was_active) {
            try self.adoptActiveTab();
        } else {
            try self.composeUi();
            self.invalidateUi();
        }
    }

    fn tabRenameAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const id = self.targetTab(invocation) orelse return;
        const tab = self.activeWorkspace().tab(id) orelse return;
        if (self.rename_input) |*field| field.deinit();
        self.rename_input = try ui.Input.init(self.allocator, tab_name_capacity, tab.name());
        self.rename_tab_id = id;
        try self.composeUi();
        var storage: [workspace_semantic_capacity]u8 = undefined;
        if (self.ui_tree.focus(.{ .value = try self.activeTabRenameSemantic(&storage) })) try self.refreshActiveUi();
    }

    fn tabRenameCommitAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        const id = self.rename_tab_id orelse return;
        const field = if (self.rename_input) |*value| value else return;
        const name = std.mem.trim(u8, field.text(), std.ascii.whitespace[0..]);
        if (name.len == 0) {
            log.warn("an empty tab name was not saved", .{});
            return;
        }
        try self.activeWorkspace().renameTab(id, name);
        field.deinit();
        self.rename_input = null;
        self.rename_tab_id = null;
        try self.composeUi();
        if (self.activeWorkspace().tab(id) != null) try self.focusTabRow(id);
        try self.refreshActiveUi();
    }

    fn tabRenameCancelAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        const id = self.rename_tab_id orelse return;
        if (self.rename_input) |*field| field.deinit();
        self.rename_input = null;
        self.rename_tab_id = null;
        try self.composeUi();
        if (self.activeWorkspace().tab(id) != null) try self.focusTabRow(id);
        try self.refreshActiveUi();
    }

    fn tabPreviousAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        const count = self.activeWorkspace().tabCount();
        if (count < 2) return;
        const active = self.activeWorkspace().activeTabId() orelse return;
        const index = self.activeWorkspace().tabIndex(active) orelse return;
        const target = self.activeWorkspace().tabAt(if (index == 0) count - 1 else index - 1) orelse return;
        _ = try self.activateTab(target.id());
    }

    fn tabNextAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        const count = self.activeWorkspace().tabCount();
        if (count < 2) return;
        const active = self.activeWorkspace().activeTabId() orelse return;
        const index = self.activeWorkspace().tabIndex(active) orelse return;
        const target = self.activeWorkspace().tabAt((index + 1) % count) orelse return;
        _ = try self.activateTab(target.id());
    }

    fn argument(invocation: inputmod.Invocation, name: []const u8) ?[]const u8 {
        for (invocation.arguments) |item| if (std.mem.eql(u8, item.name, name)) return item.value;
        return null;
    }

    fn tabGotoAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const text = argument(invocation, "index") orelse return;
        const one_based = std.fmt.parseUnsigned(usize, text, 10) catch return;
        if (one_based == 0) return;
        const tab = self.activeWorkspace().tabAt(one_based - 1) orelse return;
        _ = try self.activateTab(tab.id());
    }

    fn tabMoveAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const id = self.targetTab(invocation) orelse return;
        const index = self.activeWorkspace().tabIndex(id) orelse return;
        const direction = argument(invocation, "direction") orelse return;
        const final_index = if (std.mem.eql(u8, direction, "up"))
            index -| 1
        else if (std.mem.eql(u8, direction, "down"))
            @min(index +| 1, self.activeWorkspace().tabCount() - 1)
        else
            return;
        try self.activeWorkspace().moveTab(id, final_index);
        try self.refreshActiveUi();
    }

    fn tabReorderAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const source = invocation.origin orelse return;
        const source_id = self.tabIdForSemantic(source.value) orelse return;
        const target_id = self.tabIdForSemantic(argument(invocation, "target") orelse return) orelse return;
        const final_index = self.activeWorkspace().tabIndex(target_id) orelse return;
        try self.activeWorkspace().moveTab(source_id, final_index);
        try self.refreshActiveUi();
    }

    fn sidebarResizeAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = context;
        _ = invocation;
        // Drag motion owns resizing; release still resolves through the action
        // registry so the divider obeys the same semantic interaction path.
    }

    fn paneIdForSemantic(self: *const App, semantic_id: []const u8) ?workspace.PaneId {
        const target = workspaceEntityForSemantic(semantic_id, "pane") orelse return null;
        const active_key = self.workspace_registry.activeKey() orelse return null;
        if (target.key != active_key) return null;
        const id: workspace.PaneId = @enumFromInt(target.ordinal);
        const tab_id = self.activeWorkspaceConst().activeTabId() orelse return null;
        if (self.activeWorkspaceConst().paneSessionId(tab_id, id) == null) return null;
        return id;
    }

    fn dividerIdForSemantic(self: *const App, semantic_id: []const u8) ?workspace.DividerId {
        const target = workspaceEntityForSemantic(semantic_id, "divider") orelse return null;
        const active_key = self.workspace_registry.activeKey() orelse return null;
        if (target.key != active_key) return null;
        const id: workspace.DividerId = @enumFromInt(target.ordinal);
        for (self.divider_layouts[0..self.divider_layout_count]) |divider| {
            if (divider.divider_id == id) return id;
        }
        return null;
    }

    fn paneDirection(text: []const u8) ?workspace.PaneDirection {
        if (std.mem.eql(u8, text, "left")) return .left;
        if (std.mem.eql(u8, text, "right")) return .right;
        if (std.mem.eql(u8, text, "up")) return .up;
        if (std.mem.eql(u8, text, "down")) return .down;
        return null;
    }

    fn panePressRoutesToTerminal(clicked: workspace.PaneId, focused_after: ?workspace.PaneId) bool {
        return focused_after != null and focused_after.? == clicked;
    }

    fn paneMotionOwnedByUi(
        existing_gesture: bool,
        pane_under_pointer: ?workspace.PaneId,
        focused: ?workspace.PaneId,
        buttons: platform.ButtonsHeld,
    ) bool {
        if (existing_gesture) return true;
        const pane_id = pane_under_pointer orelse return false;
        return pane_id != focused and !buttons.left and !buttons.middle and !buttons.right;
    }

    fn paneActivateAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const origin = invocation.origin orelse return;
        const pane_id = self.paneIdForSemantic(origin.value) orelse return;
        const tab_id = self.activeWorkspace().activeTabId() orelse return;
        if (self.activeWorkspace().focusedPaneId(tab_id) == pane_id) return;
        if (!try self.prepareToLeaveActiveSession()) return;
        try self.activeWorkspace().focusPane(tab_id, pane_id);
        try self.adoptFocusedPane();
    }

    fn paneSplitAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const split_text = argument(invocation, "direction") orelse return;
        const split: workspace.PaneSplit = if (std.mem.eql(u8, split_text, "right"))
            .right
        else if (std.mem.eql(u8, split_text, "down"))
            .down
        else
            return;
        try self.splitFocusedPane(split, self.defaultProfile());
    }

    /// Split the focused pane towards `split` with a new terminal running
    /// `profile`, or the app's default child when `profile` is null.
    fn splitFocusedPane(self: *App, split: workspace.PaneSplit, profile: ?ResolvedProfile) !void {
        if (self.activePresentation().load != null) {
            log.warn("pane split deferred while another load is in flight", .{});
            return;
        }
        if (self.remoteNotReady()) return;
        if (!try self.prepareToLeaveActiveSession()) return;
        const tab_id = self.activeWorkspace().activeTabId() orelse return;
        const tab = self.activeWorkspace().tab(tab_id) orelse return;
        if (tab.paneCount() >= pane_ui_capacity) {
            log.warn("pane split refused because the semantic frame is full", .{});
            return;
        }
        const focused_pane = self.activeWorkspace().focusedPaneId(tab_id) orelse return;
        const bounds = self.terminalCellBounds() orelse return;
        var profile_spec: ?ChildSpec = if (profile) |chosen| try self.profileSpec(chosen) else null;
        defer if (profile_spec) |*spec| spec.deinit();
        const cwd = try self.newTerminalCwd(profile);
        errdefer self.allocator.free(cwd);
        try self.activePresentation().pane_renderers.ensureUnusedCapacity(self.allocator, 1);
        const expected_session = session.SessionId.fromOrdinal(@intCast(self.activeWorkspace().registeredSessionCount()));
        var pane_renderer = try self.newPaneRenderer(expected_session);
        var renderer_owned = true;
        errdefer if (renderer_owned) pane_renderer.deinit();
        const created = self.activeWorkspace().createPaneSession(
            tab_id,
            focused_pane,
            .human_terminal,
            self.activeLive().terminal().gridSize(),
            split,
            bounds,
        ) catch |err| {
            if (err == error.InvalidGeometry) return;
            return err;
        };
        pane_renderer.session_id = created.session_id;
        self.activePresentation().pane_renderers.appendAssumeCapacity(pane_renderer);
        renderer_owned = false;
        try self.adoptFocusedPane();
        self.startProfileChild(created.session_id, cwd, &profile_spec);
    }

    fn paneFocusAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const direction = paneDirection(argument(invocation, "direction") orelse return) orelse return;
        const tab_id = self.activeWorkspace().activeTabId() orelse return;
        const bounds = self.terminalCellBounds() orelse return;
        if (!try self.prepareToLeaveActiveSession()) return;
        const moved = self.activeWorkspace().focusPaneDirection(tab_id, direction, bounds) catch |err| switch (err) {
            error.InvalidGeometry => return,
            else => return err,
        };
        if (!moved) return;
        try self.adoptFocusedPane();
    }

    fn paneResizeAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        const tab_id = self.activeWorkspace().activeTabId() orelse return;
        const bounds = self.terminalCellBounds() orelse return;
        var changed = false;
        if (argument(invocation, "divider")) |divider_text| {
            const value = std.fmt.parseUnsigned(u32, divider_text, 10) catch return;
            if (value == 0) return;
            const delta = std.fmt.parseInt(i32, argument(invocation, "delta") orelse return, 10) catch return;
            changed = self.activeWorkspace().resizeDivider(tab_id, @enumFromInt(value), delta, bounds) catch |err| switch (err) {
                error.InvalidGeometry, error.UnknownDivider => return,
                else => return err,
            };
        } else {
            const direction = paneDirection(argument(invocation, "direction") orelse return) orelse return;
            const pane_id = self.activeWorkspace().focusedPaneId(tab_id) orelse return;
            changed = self.activeWorkspace().resizePaneEdge(tab_id, pane_id, direction, 1, bounds) catch |err| switch (err) {
                error.InvalidGeometry, error.UnknownDivider => return,
                else => return err,
            };
        }
        if (!changed) return;
        try self.syncGrid();
        try self.composeUi();
        self.invalidateUi();
    }

    fn paneZoomAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        const tab_id = self.activeWorkspace().activeTabId() orelse return;
        _ = try self.activeWorkspace().togglePaneZoom(tab_id);
        try self.syncGrid();
        try self.composeUi();
        self.invalidateUi();
    }

    fn paneCloseAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        const tab_id = self.activeWorkspace().activeTabId() orelse return;
        const tab = self.activeWorkspace().tab(tab_id) orelse return;
        if (tab.paneCount() == 1) {
            try tabCloseAction(self, .{ .source = .palette });
            return;
        }
        const pane_id = self.activeWorkspace().focusedPaneId(tab_id) orelse return;
        const session_id = self.activeWorkspace().paneSessionId(tab_id, pane_id) orelse return;
        const target = self.activeWorkspace().sessionById(session_id) orelse return;
        if (!sessionNeedsCloseConfirmation(target)) {
            if (!try self.prepareToLeaveActiveSession()) return;
            // A sidebar click focused this control before invoking it. Once an
            // idle pane closes directly, keyboard input belongs to the adopted
            // sibling terminal rather than to the still-present close control.
            self.ui_tree.clearFocus();
            return self.closePane(tab_id, pane_id);
        }
        self.pending_close_tab_id = null;
        self.pending_close_pane = .{ .tab_id = tab_id, .pane_id = pane_id };
        try self.composeUi();
        if (self.ui_tree.focus(.{ .value = "tab-close.cancel" })) try self.refreshActiveUi();
    }

    fn closePane(self: *App, tab_id: workspace.TabId, pane_id: workspace.PaneId) !void {
        const result = self.activeWorkspace().closePane(tab_id, pane_id) catch |err| {
            self.discardClosedPaneRenderers();
            if (self.activeWorkspace().paneSessionId(tab_id, pane_id) == null) {
                try self.adoptFocusedPane();
                log.warn("the pane closed but its child could not be signalled cleanly: {s}", .{@errorName(err)});
                return;
            }
            return err;
        };
        switch (result) {
            .pane_closed => {
                self.discardClosedPaneRenderers();
                try self.adoptFocusedPane();
            },
            .close_tab => try self.closeTab(tab_id),
        }
    }

    fn setScratchpadPresentation(self: *App, requested: ScratchpadPresentation) !void {
        if (self.closeModalActive()) return;
        const next: ScratchpadPresentation = if (requested == self.activePresentation().scratchpad_presentation)
            .hidden
        else
            requested;
        const changes_session = (self.activePresentation().scratchpad_presentation == .hidden) != (next == .hidden);
        if (changes_session and !try self.prepareToLeaveActiveSession()) return;

        self.composition.cancel();
        _ = takeCommittedText(&self.pending_committed_text);
        try self.window.stopTextInput();
        self.ui_tree.clearFocus();
        self.ui_pointer_owned = false;
        self.activePresentation().scratchpad_presentation = next;
        try self.syncGrid();
        try self.syncTextInput();
        try self.composeUi();
        self.invalidateUi();
    }

    fn scratchpadToggle50Action(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        try self.setScratchpadPresentation(.fifty);
    }

    fn scratchpadToggle90Action(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        try self.setScratchpadPresentation(.ninety);
    }

    fn scratchpadHideAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        if (!try self.scratchpadActionTargetsActive(invocation, "hide")) return;
        if (!self.scratchpadVisible()) return;
        try self.setScratchpadPresentation(.hidden);
    }

    fn scratchpadRestartAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        if (!try self.scratchpadActionTargetsActive(invocation, "restart")) return;
        if (self.activePresentation().scratchpad_load != null) return;
        if (self.remoteNotReady()) return;
        if (self.scratchpadVisible() and !try self.prepareToLeaveActiveSession()) return;
        self.composition.cancel();
        _ = takeCommittedText(&self.pending_committed_text);
        // A pointer activation focuses the restart text. Leaving that focus in
        // place would make the next Enter activate restart again instead of
        // reaching the fresh shell.
        self.ui_tree.clearFocus();
        try self.refreshActiveUi();
        const replacement = if (self.scratchpadLive()) |scratchpad| scratchpad.child() != null else false;
        self.startScratchpad(replacement);
    }

    fn scratchpadActionTargetsActive(
        self: *const App,
        invocation: inputmod.Invocation,
        suffix: []const u8,
    ) !bool {
        if (invocation.source != .mouse) return true;
        const origin = invocation.origin orelse return false;
        var storage: [workspace_semantic_capacity]u8 = undefined;
        const expected = try scratchpadSemanticId(&storage, self.activePresentationConst().key, suffix);
        return std.mem.eql(u8, origin.value, expected);
    }

    fn clearPaletteInput(field: *ui.Input) void {
        field.selectAll();
        field.backspace();
    }

    fn paletteSemanticIndex(id: []const u8, prefix: []const u8) ?usize {
        if (!std.mem.startsWith(u8, id, prefix)) return null;
        return std.fmt.parseUnsigned(usize, id[prefix.len..], 10) catch null;
    }

    fn paletteChoiceSemanticIndex(id: []const u8, definition_index: usize) ?usize {
        const prefix = "palette.choice.";
        if (!std.mem.startsWith(u8, id, prefix)) return null;
        const suffix = id[prefix.len..];
        const separator = std.mem.indexOfScalar(u8, suffix, '.') orelse return null;
        const encoded_definition = std.fmt.parseUnsigned(usize, suffix[0..separator], 10) catch return null;
        if (encoded_definition != definition_index) return null;
        return std.fmt.parseUnsigned(usize, suffix[separator + 1 ..], 10) catch null;
    }

    fn isSearchAction(name: []const u8) bool {
        return std.mem.startsWith(u8, name, "search.") or
            std.mem.eql(u8, name, clipboard_copy_action) or
            std.mem.eql(u8, name, clipboard_paste_action);
    }

    fn stopSearchEngine(self: *App) void {
        if (self.search_engine_live) self.search_engine.deinit();
        self.search_engine_live = false;
        self.search_session_id = null;
        self.search_page_slot = 0;
        self.search_page_scan = null;
        self.search_match_count = 0;
        self.search_active_index = 0;
        self.search_progress = .complete;
        self.search_truncated = false;
        self.search_needs_sync = false;
        self.search_restart_on_sync = false;
        self.search_follow_pending = false;
        self.search_view = null;
    }

    fn startSearchPage(
        self: *App,
        cursor: term.SearchCursor,
        activation: SearchPageActivation,
        allow_wrap: bool,
        preserve_current: bool,
    ) void {
        const slot = if (preserve_current) 1 - self.search_page_slot else self.search_page_slot;
        self.search_page_scan = .{
            .cursor = cursor,
            .slot = slot,
            .activation = activation,
            .allow_wrap = allow_wrap,
        };
        if (!preserve_current) {
            self.search_match_count = 0;
            self.search_active_index = 0;
        }
    }

    fn startInitialSearchPage(self: *App) bool {
        const cursor = self.search_engine.startCursor(
            self.presentedLive().terminal(),
            .older,
        ) catch |err| {
            self.stopSearchEngine();
            self.search_failure = @errorName(err);
            return false;
        };
        self.startSearchPage(cursor, .first, false, false);
        return true;
    }

    fn restartSearch(self: *App) void {
        self.stopSearchEngine();
        self.search_failure = null;
        if (!self.search_visible) return;
        if (self.presentedAgentView()) |runner| {
            self.search_active_index = 0;
            self.findAgentViewMatches(runner, true);
            return;
        }
        if (self.search_query.text().len == 0) return;

        const live = self.presentedLive();
        (switch (self.search_mode) {
            .literal => self.search_engine.init(
                live.terminal(),
                self.search_query.text(),
                self.search_case,
                &self.search_scratch,
            ),
            .regex => self.search_engine.initRegex(
                live.terminal(),
                self.search_query.text(),
                self.search_case,
                &self.search_scratch,
            ),
        }) catch |err| {
            self.search_failure = searchFailureText(err);
            return;
        };
        self.search_engine_live = true;
        self.search_session_id = self.presentedSessionId();
        self.search_progress = .running;
        self.search_follow_pending = true;
        _ = self.startInitialSearchPage();
    }

    fn noteSearchTerminalChange(self: *App, id: session.SessionId) void {
        if (!self.search_engine_live or self.search_session_id != id) return;
        self.search_needs_sync = true;
        self.search_restart_on_sync = self.search_progress == .scratch_exhausted;
        self.search_page_scan = null;
        self.search_match_count = 0;
        self.search_active_index = 0;
        self.search_progress = .running;
        self.search_truncated = false;
        self.search_follow_pending = true;
    }

    fn revealActiveSearchMatch(self: *App) bool {
        if (self.search_match_count == 0 or self.search_active_index >= self.search_match_count) return false;
        const live = self.presentedLive();
        const moved = live.terminal().revealSearchMatch(
            self.search_pages[self.search_page_slot][self.search_active_index].match,
        ) catch |err| switch (err) {
            error.StaleSearchMatch => {
                self.noteSearchTerminalChange(self.presentedSessionId());
                return false;
            },
            error.NotOwned => {
                self.search_failure = @errorName(err);
                return false;
            },
        };
        return moved;
    }

    fn finishSearchPage(self: *App, state: SearchPageScan) void {
        if (state.cursor.direction == .newer) {
            std.mem.reverse(term.LocatedSearchMatch, self.search_pages[state.slot][0..state.count]);
        }
        self.search_page_slot = state.slot;
        self.search_match_count = state.count;
        self.search_active_index = switch (state.activation) {
            .first => 0,
            .last => state.count - 1,
        };
        self.search_page_scan = null;
        self.search_truncated = state.count == search_match_capacity or state.wrapped;
        self.search_follow_pending = true;
    }

    fn wrapSearchPage(self: *App, state: SearchPageScan) bool {
        const cursor = self.search_engine.startCursor(
            self.presentedLive().terminal(),
            state.cursor.direction,
        ) catch |err| {
            self.stopSearchEngine();
            self.search_failure = @errorName(err);
            return false;
        };
        var wrapped = state;
        wrapped.cursor = cursor;
        wrapped.count = 0;
        wrapped.wrapped = true;
        self.search_page_scan = wrapped;
        return true;
    }

    fn searchNeedsWork(self: *const App) bool {
        return searchWorkPending(
            self.search_visible,
            self.search_engine_live,
            self.search_needs_sync,
            self.search_progress,
            self.search_page_scan != null,
        );
    }

    /// Run a bounded number of page ticks from the event-loop poll, never from
    /// composition or rendering. Returns whether semantic or viewport state
    /// changed and therefore a frame is owed.
    fn advanceSearch(self: *App) bool {
        if (!self.search_visible or !self.search_engine_live) return false;
        if (self.search_session_id != self.presentedSessionId()) {
            self.stopSearchEngine();
            self.search_failure = "terminal changed";
            return true;
        }

        if (self.search_needs_sync) {
            if (self.search_restart_on_sync) {
                self.restartSearch();
                return true;
            }
            self.search_engine.sync(self.presentedLive().terminal(), true) catch |err| {
                if (err == error.SearchScratchExhausted) {
                    self.restartSearch();
                } else {
                    self.stopSearchEngine();
                    self.search_failure = searchFailureText(err);
                }
                return true;
            };
            self.search_needs_sync = false;
            self.search_restart_on_sync = false;
            self.search_resync_count +%= 1;
            if (!self.startInitialSearchPage()) return true;
        }

        const before_count = self.search_match_count;
        const before_progress = self.search_progress;
        const before_slot = self.search_page_slot;
        const before_active = self.search_active_index;
        if (self.search_progress == .running) {
            self.search_progress = self.search_engine.step(search_tick_budget) catch |err| {
                self.stopSearchEngine();
                self.search_failure = searchFailureText(err);
                return true;
            };
        }

        if (self.search_page_scan) |pending| {
            var state = pending;
            const scan = self.search_engine.scan(
                self.presentedLive().terminal(),
                &state.cursor,
                search_candidate_budget,
                self.search_pages[state.slot][state.count..],
            ) catch |err| {
                self.stopSearchEngine();
                self.search_failure = searchFailureText(err);
                return true;
            };
            state.count += scan.items.len;
            self.search_progress = scan.progress;
            self.search_page_scan = state;
            if (state.slot == self.search_page_slot) self.search_match_count = state.count;

            switch (scan.stop) {
                .budget => {},
                .output_full => self.finishSearchPage(state),
                .scratch_exhausted => {
                    if (state.count != 0) self.finishSearchPage(state) else self.search_page_scan = null;
                    self.search_progress = .scratch_exhausted;
                },
                .current_boundary => {
                    if (self.search_progress == .running) {
                        // Keep the raw cursor at today's boundary. Older
                        // candidates append beyond it as engine ticks land.
                    } else if (state.count != 0) {
                        self.finishSearchPage(state);
                    } else if (state.allow_wrap and !state.wrapped) {
                        if (!self.wrapSearchPage(state)) return true;
                    } else {
                        self.search_page_scan = null;
                    }
                },
            }
        }

        var changed = before_count != self.search_match_count or
            before_progress != self.search_progress or
            before_slot != self.search_page_slot or
            before_active != self.search_active_index;
        if (self.search_follow_pending and self.search_match_count != 0) {
            changed = self.revealActiveSearchMatch() or changed;
            self.search_follow_pending = false;
        } else if (self.search_progress == .complete) {
            self.search_follow_pending = false;
        }
        return changed;
    }

    fn openSearch(self: *App) !void {
        if (self.closeModalActive() or self.rename_tab_id != null) return;
        self.composition.cancel();
        _ = takeCommittedText(&self.pending_committed_text);
        self.search_visible = true;
        self.ui_tree.clearFocus();
        self.restartSearch();
        try self.composeUi();
        if (self.ui_tree.focus(.{ .value = "search.query" })) try self.composeUi();
        try self.syncTextInput();
        self.invalidateUi();
    }

    fn closeSearch(self: *App) !void {
        if (!self.search_visible) return;
        self.composition.cancel();
        _ = takeCommittedText(&self.pending_committed_text);
        self.stopSearchEngine();
        self.search_visible = false;
        self.search_pointer_owned = false;
        self.ui_tree.clearFocus();
        try self.composeUi();
        try self.syncTextInput();
        self.invalidateUi();
    }

    fn moveSearchSelection(self: *App, next: bool) !void {
        if (!self.search_visible or self.search_match_count == 0) return;
        if (self.search_view) |id| {
            const count = self.search_match_count;
            self.search_active_index = if (next) (self.search_active_index + 1) % count else (self.search_active_index + count - 1) % count;
            if (self.agents.runnerForAgent(id)) |runner| self.revealAgentViewMatch(runner);
            try self.composeUi();
            if (self.ui_tree.focus(.{ .value = "search.query" })) try self.composeUi();
            self.invalidateUi();
            return;
        }
        if (self.search_page_scan != null) return;

        if (next and self.search_active_index + 1 < self.search_match_count) {
            self.search_active_index += 1;
            _ = self.revealActiveSearchMatch();
        } else if (!next and self.search_active_index != 0) {
            self.search_active_index -= 1;
            _ = self.revealActiveSearchMatch();
        } else {
            const anchor = self.search_pages[self.search_page_slot][self.search_active_index];
            const direction: term.SearchDirection = if (next) .older else .newer;
            const cursor = self.search_engine.cursorAfter(
                self.presentedLive().terminal(),
                anchor,
                direction,
            ) catch |err| {
                self.stopSearchEngine();
                self.search_failure = @errorName(err);
                return;
            };
            self.startSearchPage(cursor, if (next) .first else .last, true, true);
        }
        try self.composeUi();
        if (self.ui_tree.focus(.{ .value = "search.query" })) try self.composeUi();
        self.invalidateUi();
    }

    fn searchMatchSemanticIndex(id: []const u8) ?usize {
        const prefix = "search.match.";
        if (!std.mem.startsWith(u8, id, prefix)) return null;
        const suffix = id[prefix.len..];
        const separator = std.mem.indexOfScalar(u8, suffix, '.') orelse return null;
        return std.fmt.parseUnsigned(usize, suffix[0..separator], 10) catch null;
    }

    // -----------------------------------------------------------------
    // The settings view (TASK-41)
    // -----------------------------------------------------------------

    fn settingsVisible(self: *const App) bool {
        return self.settings_visible;
    }

    /// Whether `definition` gets a Keys row: the palette itself and every
    /// palette command that takes no argument. A command with an argument is
    /// bound in the file as `<chord>=<action>:<argument>`.
    fn settingsBindable(definition: *const inputmod.ActionDefinition) bool {
        if (std.mem.eql(u8, definition.name, palette_open_action)) return true;
        const command = definition.palette orelse return false;
        return command.argument == .none;
    }

    /// Rebuild the row list from the fixed groups and the registry. The same
    /// registry yields the same rows and ids on every opening.
    fn buildSettingsRows(self: *App) void {
        var count: usize = 0;
        const rows = &self.settings_rows;
        rows[count] = .{ .heading = .{ .id = "settings.heading.appearance", .label = "Appearance" } };
        count += 1;
        for (settings_appearance_fields) |field| {
            rows[count] = .{ .field = field };
            count += 1;
        }
        rows[count] = .{ .heading = .{ .id = "settings.heading.fonts", .label = "Fonts" } };
        count += 1;
        for (settings_font_fields) |field| {
            rows[count] = .{ .field = field };
            count += 1;
        }
        rows[count] = .{ .heading = .{ .id = "settings.heading.keys", .label = "Keys" } };
        count += 1;
        const reserved = 6 + settings_scratchpad_fields.len + settings_mouse_fields.len + settings_agents_fields.len +
            settings_shell_fields.len + config.max_shell_profiles;
        for (self.actions.definitions(), 0..) |*definition, definition_index| {
            if (!settingsBindable(definition)) continue;
            if (count + reserved >= rows.len) break;
            const id = std.fmt.bufPrint(&self.settings_row_ids[count], "settings.row.keybind.{s}", .{definition.name}) catch continue;
            rows[count] = .{ .keybind = .{ .definition = definition_index, .id = id } };
            count += 1;
        }
        rows[count] = .{ .heading = .{ .id = "settings.heading.scratchpad", .label = "Scratchpad" } };
        count += 1;
        for (settings_scratchpad_fields) |field| {
            rows[count] = .{ .field = field };
            count += 1;
        }
        rows[count] = .{ .heading = .{ .id = "settings.heading.mouse", .label = "Mouse" } };
        count += 1;
        for (settings_mouse_fields) |field| {
            rows[count] = .{ .field = field };
            count += 1;
        }
        rows[count] = .{ .heading = .{ .id = "settings.heading.agents", .label = "Agents" } };
        count += 1;
        for (settings_agents_fields) |field| {
            rows[count] = .{ .field = field };
            count += 1;
        }
        rows[count] = .{ .heading = .{ .id = "settings.heading.shells", .label = "Shells" } };
        count += 1;
        for (settings_shell_fields) |field| {
            rows[count] = .{ .field = field };
            count += 1;
        }
        for (self.config_current.settings.shell_profiles, 0..) |profile, index| {
            if (count + 1 >= rows.len) break;
            const id = std.fmt.bufPrint(&self.settings_row_ids[count], "settings.row.profile.{s}", .{profile.name}) catch continue;
            rows[count] = .{ .profile = .{ .index = index, .id = id } };
            count += 1;
        }
        rows[count] = .raw;
        count += 1;
        self.settings_row_count = count;
    }

    fn settingsRowId(self: *const App, index: usize) []const u8 {
        return switch (self.settings_rows[index]) {
            .heading => |heading| heading.id,
            .field => |field| field.id,
            .keybind => |keybind| keybind.id,
            .profile => |profile| profile.id,
            .raw => "settings.raw",
        };
    }

    fn settingsRowIndex(self: *const App, id: []const u8) ?usize {
        for (0..self.settings_row_count) |index| {
            if (std.mem.eql(u8, self.settingsRowId(index), id)) return index;
        }
        return null;
    }

    fn settingsSelectedField(self: *const App) ?SettingsField {
        if (self.settings_selected >= self.settings_row_count) return null;
        return switch (self.settings_rows[self.settings_selected]) {
            .field => |field| field,
            else => null,
        };
    }

    fn settingsSelectedKeybind(self: *const App) ?*const inputmod.ActionDefinition {
        if (self.settings_selected >= self.settings_row_count) return null;
        return switch (self.settings_rows[self.settings_selected]) {
            .keybind => |keybind| &self.actions.definitions()[keybind.definition],
            else => null,
        };
    }

    /// What a setting row shows as its value: the value in effect, through
    /// every layer, so the row agrees with the window.
    fn settingsValueText(self: *const App, key: config.Key, buffer: []u8) []const u8 {
        const values = self.font_settings.values;
        return switch (key) {
            .theme => self.activeThemeName(),
            .font_family => if (values.family.len == 0) bundled_font_label else values.family,
            .font_bold => if (values.bold.len == 0) "(derived)" else values.bold,
            .font_italic => if (values.italic.len == 0) "(derived)" else values.italic,
            .font_bold_italic => if (values.bold_italic.len == 0) "(derived)" else values.bold_italic,
            .font_size => std.fmt.bufPrint(buffer, "{d}", .{values.points}) catch "",
            .font_ligatures => if (values.ligatures) "true" else "false",
            .font_nerd_symbols => if (values.builtin_symbols) "true" else "false",
            .font_fallbacks => if (values.fallbacks.len == 0) "(none)" else config.formatFallbacks(buffer, values.fallbacks) catch "…",
            .scratchpad_size => std.fmt.bufPrint(buffer, "{d}%", .{self.scratchpad_percent_small}) catch "",
            .scratchpad_large_size => std.fmt.bufPrint(buffer, "{d}%", .{self.scratchpad_percent_large}) catch "",
            .mouse_right_click => self.right_click.text(),
            .macos_option_as_alt => self.config_current.settings.macos_option_as_alt.text(),
            .notifications_enabled,
            .notifications_os,
            .notifications_permission,
            .notifications_input,
            .notifications_done,
            .notifications_error,
            .notifications_terminal,
            .notifications_claude_code,
            .notifications_codex,
            .notifications_pi,
            .notifications_opencode,
            => if (self.config_current.settings.notifications.get(key) orelse true) "true" else "false",
            // Repeating and recorded keys have no row: the connection
            // manager edits them (TASK-44). `control.enabled` applies at
            // startup only, so it is a file setting without a row (TASK-60),
            // as are `restore.enabled` and `accessibility.enabled`.
            .shell => if (self.config_current.settings.shell.len == 0) "(default)" else self.config_current.settings.shell,
            .remote_profile, .remote_recent, .control_enabled, .restore_enabled, .accessibility_enabled, .profile, .keybind => "",
            // TASK-79 phase two gives it a settings row.
            .editor_command => if (self.config_current.settings.editor_command.len == 0) "(codium)" else self.config_current.settings.editor_command,
        };
    }

    /// The text the inline Input starts with: the value as the file would
    /// spell it, empty where the row shows a derived or absent value.
    fn settingsEditText(self: *const App, key: config.Key, buffer: []u8) []const u8 {
        const values = self.font_settings.values;
        return switch (key) {
            .font_bold => values.bold,
            .font_italic => values.italic,
            .font_bold_italic => values.bold_italic,
            .font_fallbacks => config.formatFallbacks(buffer, values.fallbacks) catch "",
            .font_size => std.fmt.bufPrint(buffer, "{d}", .{values.points}) catch "",
            .scratchpad_size => std.fmt.bufPrint(buffer, "{d}", .{self.scratchpad_percent_small}) catch "",
            .scratchpad_large_size => std.fmt.bufPrint(buffer, "{d}", .{self.scratchpad_percent_large}) catch "",
            .shell => self.config_current.settings.shell,
            else => self.settingsValueText(key, buffer),
        };
    }

    /// Whether the settings file sets the row: `config` records the line each
    /// value came from, and 0 is the built-in layer.
    fn settingsFromFile(self: *const App, row: SettingsRow) bool {
        return switch (row) {
            .field => |field| self.config_current.lines.get(field.key) != 0,
            .keybind => |keybind| file: {
                const name = self.actions.definitions()[keybind.definition].name;
                for (self.config_current.keybinds.items) |line| {
                    if (line.action) |action| if (std.mem.eql(u8, action, name)) break :file true;
                }
                break :file false;
            },
            .profile => true,
            else => false,
        };
    }

    /// A profile row's value: the command it runs, `-l` when it is a login
    /// shell, and `…` when it also sets variables or a directory.
    fn settingsProfileValue(self: *const App, index: usize, buffer: []u8) []const u8 {
        const profiles = self.config_current.settings.shell_profiles;
        if (index >= profiles.len) return "";
        const profile = profiles[index];
        var writer: std.Io.Writer = .fixed(buffer);
        for (profile.argv, 0..) |arg, position| {
            if (position != 0) writer.writeByte(' ') catch break;
            writer.writeAll(arg) catch break;
            if (position == 0 and profile.login) {
                if (loginFlag(arg, builtin.os.tag)) |flag| writer.print(" {s}", .{flag}) catch break;
            }
        }
        if (profile.env.len != 0 or profile.cwd != null) writer.writeAll(" …") catch {};
        var len = writer.end;
        while (len != 0 and !std.unicode.utf8ValidateSlice(buffer[0..len])) len -= 1;
        return buffer[0..len];
    }

    /// `<name>  <value> ·`: the value right-aligned to `width` cells, then a
    /// two-cell source column that holds `·` when the settings file sets it.
    fn settingsRowLabel(self: *const App, index: usize, width: u32, storage: []u8) []const u8 {
        const row = self.settings_rows[index];
        var value_buffer: [config.max_string_bytes]u8 = undefined;
        const selected = index == self.settings_selected;
        const name: []const u8, const value: []const u8 = switch (row) {
            .heading => |heading| .{ heading.label, "" },
            .raw => .{ settings_raw_label, "" },
            .field => |field| .{ field.key.name(), self.settingsValueText(field.key, &value_buffer) },
            .profile => |profile| .{
                if (profile.index < self.config_current.settings.shell_profiles.len) self.config_current.settings.shell_profiles[profile.index].name else "",
                self.settingsProfileValue(profile.index, &value_buffer),
            },
            .keybind => |keybind| blk: {
                const definition = &self.actions.definitions()[keybind.definition];
                if (selected and self.settings_mode == .capture) break :blk .{ definition.label, settings_capture_text };
                if (selected and self.settings_mode == .conflict) {
                    if (self.settings_pending_chord) |chord| {
                        break :blk .{ definition.label, inputmod.formatChordSpelling(&value_buffer, chord) catch "" };
                    }
                }
                const chords = palette_mod.formatActionBindings(&value_buffer, definition.name, self.bindings, self.binding_profile);
                break :blk .{ definition.label, if (chords.text.len == 0) "unbound" else chords.text };
            },
        };
        const marker = if (self.settingsFromFile(row)) " ·" else "  ";
        var writer: std.Io.Writer = .fixed(storage);
        writer.writeAll(name) catch return writer.buffered();
        if (value.len != 0) {
            const used = labelCellWidth(name) +| labelCellWidth(value) +| 2;
            const padding = if (width > used + 2) width - used else 2;
            writer.splatByteAll(' ', padding) catch return writer.buffered();
            writer.writeAll(value) catch return writer.buffered();
            writer.writeAll(marker) catch return writer.buffered();
        }
        var len = writer.end;
        while (len != 0 and !std.unicode.utf8ValidateSlice(storage[0..len])) len -= 1;
        return storage[0..len];
    }

    /// The widest row the dialog shows, with room for a long value, so the
    /// dialog keeps one width while values change under it.
    fn settingsContentWidth(self: *const App) u32 {
        var widest = @max(labelCellWidth(" Settings "), labelCellWidth(settings_hint));
        for (self.settings_rows[0..self.settings_row_count]) |row| {
            const cells: u32 = switch (row) {
                .heading => |heading| labelCellWidth(heading.label),
                .raw => labelCellWidth(settings_raw_label),
                // A long command clips rather than widening the dialog.
                .profile => @as(u32, 16) + 2 + settings_value_cells + 2,
                .field => |field| labelCellWidth(field.key.name()) + 2 + settings_value_cells + 2,
                .keybind => |keybind| cells: {
                    const definition = &self.actions.definitions()[keybind.definition];
                    var chord_buffer: [96]u8 = undefined;
                    const chords = palette_mod.formatActionBindings(&chord_buffer, definition.name, self.bindings, self.binding_profile);
                    break :cells labelCellWidth(definition.label) + 2 + @max(labelCellWidth(chords.text), labelCellWidth(settings_capture_text)) + 2;
                },
            };
            widest = @max(widest, cells);
        }
        return widest;
    }

    fn settingsBounds(self: *const App) ?ui.Rect {
        if (!self.settings_visible) return null;
        const canvas = self.ui_canvas.bounds();
        if (canvas.width < 20 or canvas.height < 6) return null;
        const width = @min(canvas.width - 4, @max(@as(u32, 48), self.settings_content_width +| 4));
        // Two borders and the status line around the list.
        const wanted: u32 = @intCast(@min(self.settings_row_count, settings_visible_capacity) + 3);
        const height = @min(wanted, canvas.height - 2);
        if (width < 16 or height < 4) return null;
        return .{
            .x = (canvas.width - width) / 2,
            .y = (canvas.height - height) / 2,
            .width = width,
            .height = height,
        };
    }

    /// Scroll so the highlighted row, and the heading right above it, show.
    fn settingsKeepVisible(self: *App, list_rows: usize) void {
        if (list_rows == 0) return;
        const selected = self.settings_selected;
        var top = selected;
        if (top > 0 and self.settings_rows[top - 1] == .heading) top -= 1;
        if (top < self.settings_scroll) self.settings_scroll = top;
        if (selected >= self.settings_scroll + list_rows) self.settings_scroll = selected + 1 - list_rows;
        const last_start = self.settings_row_count -| list_rows;
        if (self.settings_scroll > last_start) self.settings_scroll = last_start;
    }

    fn composeSettings(self: *App) !void {
        const bounds = self.settingsBounds() orelse return;
        const dialog_id: ui.Id = .{ .value = "settings.dialog" };
        try self.ui_tree.addSurface(.{
            .id = dialog_id,
            .role = "dialog",
            .label = "Settings",
            .bounds = bounds,
        }, .{
            .rect = bounds,
            .erase_underlay = true,
            .fill = .background,
            .border = .double,
            .border_style = .{ .foreground = .border, .background = .background },
            .title = " Settings ",
            .title_style = .{ .foreground = .strong, .background = .background, .face_style = .bold },
        });

        const inner_x = bounds.x + 2;
        const inner_width = bounds.width - 4;
        const list_rows: usize = @min(bounds.height - 3, settings_visible_capacity);
        self.settingsKeepVisible(list_rows);
        const end = @min(self.settings_row_count, self.settings_scroll + list_rows);
        for (self.settings_scroll..end, 0..) |index, slot| {
            const y = bounds.y + 1 + @as(u32, @intCast(slot));
            const id: ui.Id = .{ .value = self.settingsRowId(index) };
            switch (self.settings_rows[index]) {
                .heading => |heading| {
                    const runs = [_]ui.Run{.{ .text = heading.label, .style = .{ .foreground = .muted } }};
                    try self.ui_tree.addText(.{
                        .id = id,
                        .parent = dialog_id,
                        .role = "heading",
                        .label = heading.label,
                        .bounds = .{ .x = inner_x, .y = y, .width = inner_width, .height = 1 },
                    }, .{ .runs = &runs });
                },
                else => {
                    const is_selected = index == self.settings_selected;
                    const editing = is_selected and self.settings_mode == .edit;
                    const full = self.settingsRowLabel(index, inner_width, &self.settings_row_labels[slot]);
                    const name = switch (self.settings_rows[index]) {
                        .field => |field| field.key.name(),
                        else => full,
                    };
                    const label = if (editing) name else full;
                    const name_width = @min(inner_width, labelCellWidth(name) + 2);
                    const row_width = if (editing) name_width else inner_width;
                    try self.ui_tree.addInteractiveText(.{
                        .id = id,
                        .parent = dialog_id,
                        .role = "setting",
                        .label = label,
                        .selected = is_selected,
                        .action = settings_activate_action,
                        .bounds = .{ .x = inner_x, .y = y, .width = row_width, .height = 1 },
                    }, .{
                        .id = id,
                        .label = label,
                        .action = settings_activate_action,
                        .normal = if (is_selected)
                            .{ .foreground = .strong, .background = .selection }
                        else
                            .{ .foreground = .foreground },
                        // The highlight stays visible under a resting pointer.
                        .hovered = if (is_selected)
                            .{ .foreground = .strong, .background = .selection, .underline = .accent }
                        else
                            .{ .foreground = .strong, .underline = .accent },
                        .focused = .{ .foreground = .on_accent, .background = .accent },
                    });
                    if (editing and inner_width > name_width) {
                        const field_bounds: ui.Rect = .{
                            .x = inner_x + name_width,
                            .y = y,
                            .width = inner_width - name_width,
                            .height = 1,
                        };
                        try self.ui_tree.addInput(.{
                            .id = .{ .value = "settings.input" },
                            .parent = dialog_id,
                            .role = "input",
                            .label = name,
                            .action = settings_activate_action,
                            .bounds = field_bounds,
                        }, &self.settings_input, .{
                            .text = .{ .foreground = .strong, .background = .field },
                            .selection_background = .selection,
                            .cursor_background = .accent,
                            .cursor_foreground = .background,
                        });
                        try self.composePalettePreedit(dialog_id, field_bounds, &self.settings_input);
                    }
                },
            }
        }

        const status_bounds: ui.Rect = .{ .x = inner_x, .y = bounds.y + bounds.height - 2, .width = inner_width, .height = 1 };
        if (self.settingsErrorText()) |message| {
            const runs = [_]ui.Run{.{ .text = message, .style = .{ .foreground = .danger } }};
            try self.ui_tree.addText(.{
                .id = .{ .value = "settings.error" },
                .parent = dialog_id,
                .role = "error",
                .label = message,
                .bounds = status_bounds,
            }, .{ .runs = &runs });
        } else {
            const hint = switch (self.settings_mode) {
                .browse => settings_hint,
                .edit => "Enter save  Esc cancel",
                .capture => "Esc cancel  Backspace unbind",
                .conflict => "Enter take it  Esc keep",
            };
            const runs = [_]ui.Run{.{ .text = hint, .style = .{ .foreground = .muted } }};
            try self.ui_tree.addText(.{
                .id = .{ .value = "settings.hint" },
                .parent = dialog_id,
                .role = "status",
                .label = hint,
                .bounds = status_bounds,
            }, .{ .runs = &runs });
        }
    }

    fn settingsErrorText(self: *const App) ?[]const u8 {
        if (self.settings_error_len == 0) return null;
        return self.settings_error_storage[0..self.settings_error_len];
    }

    fn setSettingsError(self: *App, comptime format: []const u8, args: anytype) void {
        var writer: std.Io.Writer = .fixed(&self.settings_error_storage);
        writer.print(format, args) catch {
            // A message cut by the fixed buffer is still the message's start.
        };
        var len = writer.end;
        while (len != 0 and !std.unicode.utf8ValidateSlice(self.settings_error_storage[0..len])) len -= 1;
        self.settings_error_len = len;
    }

    fn openSettings(self: *App) !void {
        if (self.settingsVisible() or self.paletteVisible() or self.contextMenuVisible() or self.managerVisible() or self.promptsVisible() or
            self.closeModalActive() or self.rename_tab_id != null or self.sidebar_dragging or
            self.dragged_divider_id != null or self.dragged_tab_id != null) return;
        const canvas = self.ui_canvas.bounds();
        if (canvas.width < 20 or canvas.height < 6) return;
        self.composition.cancel();
        _ = takeCommittedText(&self.pending_committed_text);
        try self.window.stopTextInput();
        self.buildSettingsRows();
        self.settings_selected = 1;
        self.settings_scroll = 0;
        self.settings_mode = .browse;
        self.settings_pending_chord = null;
        self.settings_error_len = 0;
        clearPaletteInput(&self.settings_input);
        self.settings_content_width = self.settingsContentWidth();
        self.settings_visible = true;
        self.ui_tree.clearFocus();
        try self.composeUi();
        try self.syncTextInput();
        self.invalidateUi();
    }

    fn closeSettings(self: *App) !void {
        if (!self.settingsVisible()) return;
        self.composition.cancel();
        _ = takeCommittedText(&self.pending_committed_text);
        self.settings_visible = false;
        self.settings_mode = .browse;
        self.settings_pending_chord = null;
        self.settings_error_len = 0;
        clearPaletteInput(&self.settings_input);
        self.ui_tree.clearFocus();
        try self.composeUi();
        try self.syncTextInput();
        self.invalidateUi();
    }

    const SettingsMove = enum { previous, next, first, last };

    /// Move the highlight to the next row that is not a heading, wrapping.
    fn moveSettingsSelection(self: *App, move: SettingsMove) !void {
        const count = self.settings_row_count;
        if (count == 0) return;
        const forward = move == .next or move == .first;
        var index: usize = switch (move) {
            .first => 0,
            .last => count - 1,
            .next => (self.settings_selected + 1) % count,
            .previous => (self.settings_selected + count - 1) % count,
        };
        for (0..count) |_| {
            if (self.settings_rows[index] != .heading) break;
            index = if (forward) (index + 1) % count else (index + count - 1) % count;
        }
        self.settings_selected = index;
        self.settings_error_len = 0;
        try self.refreshActiveUi();
    }

    /// Enter on, or a click of, row `index`: edit it the way its type says.
    fn activateSettingsRow(self: *App, index: usize, source: inputmod.InvocationSource) !void {
        if (index >= self.settings_row_count) return;
        const row = self.settings_rows[index];
        if (row == .heading) return;
        if (self.settings_mode == .edit and index == self.settings_selected) {
            // A click on the row being edited keeps the edit.
            if (self.ui_tree.focus(.{ .value = "settings.input" })) try self.refreshActiveUi();
            return;
        }
        self.settings_mode = .browse;
        self.settings_pending_chord = null;
        self.settings_error_len = 0;
        self.settings_selected = index;
        self.ui_tree.clearFocus();
        switch (row) {
            .heading => {},
            // A profile is several lines in the file, edited there.
            .raw, .profile => {
                try self.closeSettings();
                try self.dispatchAction(config_open_action, .{ .source = source });
                return;
            },
            .keybind => self.settings_mode = .capture,
            .field => |field| switch (field.edit) {
                .toggle, .cycle => {
                    try self.stepSettingsRow(true);
                    return;
                },
                .choose => {
                    const chooser = if (field.key == .theme) self.theme_pick_index else self.font_pick_index;
                    try self.closeSettings();
                    try self.showPalette();
                    if (self.paletteVisible()) try self.beginPaletteArgument(chooser);
                    return;
                },
                .number, .text => {
                    try self.beginSettingsEdit(field.key);
                    return;
                },
            },
        }
        try self.refreshActiveUi();
        try self.syncTextInput();
    }

    fn beginSettingsEdit(self: *App, key: config.Key) !void {
        clearPaletteInput(&self.settings_input);
        var buffer: [config.max_string_bytes]u8 = undefined;
        self.settings_input.insert(self.settingsEditText(key, &buffer)) catch |err| {
            log.warn("the current {s} value could not be edited: {s}", .{ key.name(), @errorName(err) });
        };
        self.settings_mode = .edit;
        self.ui_tree.clearFocus();
        try self.composeUi();
        if (self.ui_tree.focus(.{ .value = "settings.input" })) try self.composeUi();
        try self.syncTextInput();
        self.invalidateUi();
    }

    fn cancelSettingsEdit(self: *App) !void {
        self.composition.cancel();
        self.settings_mode = .browse;
        self.settings_pending_chord = null;
        self.settings_error_len = 0;
        clearPaletteInput(&self.settings_input);
        self.ui_tree.clearFocus();
        try self.refreshActiveUi();
        try self.syncTextInput();
    }

    fn commitSettingsEdit(self: *App) !void {
        const field = self.settingsSelectedField() orelse return self.cancelSettingsEdit();
        var buffer: [config.max_string_bytes]u8 = undefined;
        const typed = std.mem.trim(u8, self.settings_input.text(), " \t");
        const value = buffer[0..@min(typed.len, buffer.len)];
        @memcpy(value, typed[0..value.len]);
        if (try self.commitSettingValue(field.key, value)) {
            try self.cancelSettingsEdit();
        } else {
            try self.refreshActiveUi();
        }
    }

    /// Validate `value` exactly as a file line would be, write it and apply it
    /// through the reload path every other settings change takes. A rejected
    /// value leaves the file and the setting as they were and says why.
    fn commitSettingValue(self: *App, key: config.Key, value: []const u8) !bool {
        if (config.checkValue(key, value)) |message| {
            self.setSettingsError("{s}: {s}", .{ key.name(), message });
            return false;
        }
        const path = self.config_path orelse {
            self.setSettingsError("no settings file for this run", .{});
            return false;
        };
        config.writeDocumentValue(self.io, self.allocator, path, key, value) catch |err| {
            log.warn("the {s} setting could not be saved to the config file: {s}", .{ key.name(), @errorName(err) });
            self.setSettingsError("the settings file could not be written", .{});
            return false;
        };
        self.settings_error_len = 0;
        // The watcher sees this write as well; its reload then finds nothing
        // left to change, so nothing is applied or built twice.
        self.reloadConfig();
        return true;
    }

    /// Left/Right, or Enter on a toggle: flip a bool, swap a two-value enum,
    /// or step a number by one within its bounds.
    fn stepSettingsRow(self: *App, forward: bool) !void {
        const field = self.settingsSelectedField() orelse return;
        var buffer: [16]u8 = undefined;
        const value: []const u8 = switch (field.key) {
            .font_ligatures => if (self.font_settings.values.ligatures) "false" else "true",
            .font_nerd_symbols => if (self.font_settings.values.builtin_symbols) "false" else "true",
            .mouse_right_click => switch (self.config_current.settings.right_click orelse config.RightClick.built_in) {
                .menu => config.RightClick.paste.text(),
                .paste => config.RightClick.menu.text(),
            },
            .notifications_enabled,
            .notifications_os,
            .notifications_permission,
            .notifications_input,
            .notifications_done,
            .notifications_error,
            .notifications_terminal,
            .notifications_claude_code,
            .notifications_codex,
            .notifications_pi,
            .notifications_opencode,
            => if (self.config_current.settings.notifications.get(field.key) orelse true) "false" else "true",
            .font_size => size: {
                const points = self.font_settings.values.points;
                const next = config.stepFontPoints(points, if (forward) .increase else .decrease);
                if (next == points) return;
                break :size try std.fmt.bufPrint(&buffer, "{d}", .{next});
            },
            .scratchpad_size, .scratchpad_large_size => percent: {
                const current: u8 = if (field.key == .scratchpad_size) self.scratchpad_percent_small else self.scratchpad_percent_large;
                const next = if (forward)
                    @min(config.max_scratchpad_percent, current + 1)
                else
                    @max(config.min_scratchpad_percent, current - 1);
                if (next == current) return;
                break :percent try std.fmt.bufPrint(&buffer, "{d}", .{next});
            },
            else => return,
        };
        _ = try self.commitSettingValue(field.key, value);
        try self.refreshActiveUi();
    }

    /// A chord that would type into the terminal or break its basic editing
    /// keys if bound: refused, with the reason in `settings.error`.
    fn settingsChordRefused(chord: inputmod.Chord) bool {
        if (inputmod.chordTypesText(chord)) return true;
        if (chord.modifiers.isCommand()) return false;
        return switch (chord.key) {
            .named => |named| named == .enter or named == .tab or named == .backspace or named == .escape,
            .character => true,
        };
    }

    /// The next real key press while capturing: Escape cancels, Backspace
    /// unbinds the command, a chord another command holds asks first, and
    /// anything else is written at once.
    fn captureSettingsChord(self: *App, key: platform.KeyEvent, chord: inputmod.Chord) !void {
        const bare = !key.mods.ctrl and !key.mods.alt and !key.mods.super and !key.mods.shift;
        if (bare and key.key == .escape) {
            self.settings_mode = .browse;
            self.settings_error_len = 0;
            return self.refreshActiveUi();
        }
        if (bare and key.key == .backspace) return self.commitSettingsKeybind(null);
        if (settingsChordRefused(chord)) {
            self.setSettingsError("a bare key types text; add Ctrl, Alt or Super", .{});
            return self.refreshActiveUi();
        }
        const definition = self.settingsSelectedKeybind() orelse return;
        if (inputmod.findBinding(self.bindings, chord)) |bound| {
            if (!std.mem.eql(u8, bound.action, definition.name)) {
                const other = if (self.actions.lookup(bound.action)) |found| found.label else bound.action;
                self.settings_pending_chord = chord;
                self.settings_mode = .conflict;
                if (bound.arguments.len != 0) {
                    self.setSettingsError("conflict: {s} ({s})", .{ other, bound.arguments[0].value });
                } else {
                    self.setSettingsError("conflict: {s}", .{other});
                }
                return self.refreshActiveUi();
            }
        }
        try self.commitSettingsKeybind(chord);
    }

    /// Bind the highlighted command to `chord` alone (or to nothing): its own
    /// keybind lines are replaced, and each shipped chord it still holds is
    /// unbound, so the command ends with exactly the chord chosen. Taking a
    /// chord from another command is the file's normal rule: a later line
    /// for a chord replaces whatever it was bound to.
    fn commitSettingsKeybind(self: *App, chord: ?inputmod.Chord) !void {
        const definition = self.settingsSelectedKeybind() orelse return;
        self.settings_mode = .browse;
        self.settings_pending_chord = null;
        const path = self.config_path orelse {
            self.setSettingsError("no settings file for this run", .{});
            return self.refreshActiveUi();
        };
        var unbind_storage: [8][64]u8 = undefined;
        var unbind: [8][]const u8 = undefined;
        var unbind_count: usize = 0;
        for (inputmod.defaultBindings(self.binding_profile)) |binding| {
            if (!std.mem.eql(u8, binding.action, definition.name) or binding.arguments.len != 0) continue;
            if (chord) |wanted| if (inputmod.chordEql(binding.chord, wanted)) continue;
            const live = inputmod.findBinding(self.bindings, binding.chord) orelse continue;
            if (!std.mem.eql(u8, live.action, definition.name)) continue;
            if (unbind_count == unbind.len) break;
            unbind[unbind_count] = inputmod.formatChordSpelling(&unbind_storage[unbind_count], binding.chord) catch continue;
            unbind_count += 1;
        }
        var chord_storage: [64]u8 = undefined;
        const spelled: ?[]const u8 = if (chord) |wanted| try inputmod.formatChordSpelling(&chord_storage, wanted) else null;
        config.writeActionKeybinds(self.io, self.allocator, path, definition.name, unbind[0..unbind_count], spelled) catch |err| {
            log.warn("the keybinding could not be saved to the config file: {s}", .{@errorName(err)});
            self.setSettingsError("the settings file could not be written", .{});
            return self.refreshActiveUi();
        };
        self.settings_error_len = 0;
        self.reloadConfig();
        try self.refreshActiveUi();
    }

    /// Every key while the view is open. A press is the view's (the terminal
    /// and every binding beneath it never see it); a release or repeat only
    /// settles the binding state a press before the view opened left behind.
    fn onSettingsKey(self: *App, key: platform.KeyEvent) !void {
        var scratch: inputmod.TextScratch = .{};
        const translated = translateAppKey(&self.composition, &scratch, key);
        if (key.action != .press) {
            _ = inputmod.resolve(&self.binding_state, key, translated, self.bindings);
            return;
        }
        const identity = uiKeyIdentity(key) orelse return;
        const plain = !key.mods.ctrl and !key.mods.alt and !key.mods.super;
        switch (self.settings_mode) {
            .capture => {
                // A modifier pressed on its own is not a chord yet.
                const chord = inputmod.chordOf(key) orelse return;
                _ = self.ui_key_state.claim(identity, .none);
                try self.captureSettingsChord(key, chord);
            },
            .conflict => {
                _ = self.ui_key_state.claim(identity, .none);
                if (!plain or key.mods.shift) return;
                switch (key.key) {
                    .enter => try self.commitSettingsKeybind(self.settings_pending_chord),
                    .escape => {
                        self.settings_mode = .browse;
                        self.settings_pending_chord = null;
                        self.settings_error_len = 0;
                        try self.refreshActiveUi();
                    },
                    else => {},
                }
            },
            .edit => {
                if (plain) switch (key.key) {
                    .enter => {
                        _ = self.ui_key_state.claim(identity, .none);
                        return self.commitSettingsEdit();
                    },
                    .escape => {
                        _ = self.ui_key_state.claim(identity, .none);
                        return self.cancelSettingsEdit();
                    },
                    .tab, .up, .down => {
                        _ = self.ui_key_state.claim(identity, .none);
                        return;
                    },
                    else => {},
                };
                if (try self.routeFocusedUiKey(key, translated)) return;
                _ = self.ui_key_state.claim(identity, .none);
            },
            .browse => {
                _ = self.ui_key_state.claim(identity, .none);
                if (!plain) return;
                switch (key.key) {
                    .escape => try self.closeSettings(),
                    .up => try self.moveSettingsSelection(.previous),
                    .down => try self.moveSettingsSelection(.next),
                    .tab => try self.moveSettingsSelection(if (key.mods.shift) .previous else .next),
                    .home => try self.moveSettingsSelection(.first),
                    .end => try self.moveSettingsSelection(.last),
                    .enter => try self.activateSettingsRow(self.settings_selected, .keybinding),
                    .left => try self.stepSettingsRow(false),
                    .right => try self.stepSettingsRow(true),
                    else => {},
                }
            },
        }
    }

    /// The settings view is modal like the palette: pointer gestures inside
    /// it highlight and activate its rows, a press outside closes it, and
    /// every gesture is owned through release so nothing beneath fires.
    fn handleSettingsUiEvent(self: *App, event: platform.Event) !bool {
        const tree = self.activeUiTree();
        switch (event) {
            .mouse_motion => |motion| {
                const point = devicePointerPoint(motion.x, motion.y, self.window.state.scale);
                const before = uiInteractionState(tree);
                tree.pointerMoved(point);
                if (!std.meta.eql(before, uiInteractionState(tree))) try self.refreshActiveUi();
                return true;
            },
            .mouse_button => |button| {
                const point = devicePointerPoint(button.x, button.y, self.window.state.scale);
                switch (button.action) {
                    .press => {
                        self.settings_pointer_owned = true;
                        const bounds = self.settingsBounds();
                        if (bounds == null or !self.pointInCellRect(point, bounds.?)) {
                            try self.closeSettings();
                            return true;
                        }
                        if (button.button != .left) return true;
                        // Pressing anywhere but the field being edited ends the edit.
                        if (self.settings_mode == .edit) {
                            const on_field = if (tree.hitTest(point)) |hit| std.mem.eql(u8, hit.id.value, "settings.input") else false;
                            if (!on_field) try self.cancelSettingsEdit();
                        }
                        const before = uiInteractionState(tree);
                        tree.pointerPressed(point);
                        if (!std.meta.eql(before, uiInteractionState(tree))) try self.refreshActiveUi();
                        return true;
                    },
                    .repeat => return true,
                    .release => {
                        if (!self.settings_pointer_owned) return true;
                        self.settings_pointer_owned = false;
                        if (button.button != .left) return true;
                        const before = uiInteractionState(tree);
                        const activation = tree.pointerReleased(point);
                        if (!std.meta.eql(before, uiInteractionState(tree))) try self.refreshActiveUi();
                        const requested = activation orelse return true;
                        if (std.mem.eql(u8, requested.id.value, "settings.input")) return true;
                        if (std.mem.eql(u8, requested.action, settings_activate_action)) {
                            try self.dispatchAction(settings_activate_action, .{ .source = .mouse, .origin = requested.id });
                        }
                        return true;
                    },
                }
            },
            .wheel => return true,
            .key => return false,
            // Text and composition reach only the inline field; with no field
            // they are swallowed rather than typed into the terminal beneath.
            .text_input, .text_editing, .candidates => return self.settings_mode != .edit,
            else => return false,
        }
    }

    fn settingsOpenAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        _ = invocation;
        const self: *App = @ptrCast(@alignCast(context));
        try self.openSettings();
    }

    fn settingsActivateAction(context: *anyopaque, invocation: inputmod.Invocation) anyerror!void {
        const self: *App = @ptrCast(@alignCast(context));
        if (!self.settingsVisible()) return;
        const origin = invocation.origin orelse return;
        const index = self.settingsRowIndex(origin.value) orelse return;
        try self.activateSettingsRow(index, invocation.source);
    }

    fn openPalette(self: *App) !void {
        if (self.paletteVisible() or self.settingsVisible() or self.notificationsVisible() or self.managerVisible() or self.promptsVisible() or self.closeModalActive() or self.rename_tab_id != null or
            self.ui_key_state.len != 0 or self.terminal_key_state.len != 0 or
            self.ui_pointer_owned or self.scratchpad_ui_pointer_owned or
            self.scratchpad_terminal_pointer_owned or self.terminal_pointer_presses != 0 or
            self.scratchpad_escape_owned) return;
        try self.showPalette();
    }

    /// Show the palette's command step. Callers have checked that nothing
    /// else owns the screen or an in-flight gesture the palette would take.
    fn showPalette(self: *App) !void {
        const canvas = self.ui_canvas.bounds();
        if (canvas.width < 20 or canvas.height < 5) return;
        self.composition.cancel();
        _ = takeCommittedText(&self.pending_committed_text);
        try self.window.stopTextInput();
        clearPaletteInput(&self.palette_query);
        clearPaletteInput(&self.palette_argument);
        self.palette_model.refresh("");
        self.palette_model.selectFirst();
        // Installed families can change between openings (a font installed
        // or a reload's rescan); the list is fixed while the palette is open.
        self.rebuildFontChoices();
        // The same for detected harnesses and live agents (TASK-56). Checks
        // that never probed keep their fixed list.
        if (!self.agents.fake_enabled) self.ensureAgentDetection() else self.ensureRemoteAgentSetup();
        self.setAgentLaunchChoices();
        self.rebuildAgentChoices();
        // Hosts, profiles and recent destinations can change between
        // openings (TASK-44); the list is fixed while the palette is open.
        self.rebuildRemoteChoices();
        // Profiles depend on the active workspace's context and the file.
        self.rebuildProfileChoices(self.config_current.settings.shell_profiles);
        self.palette_content_width = self.paletteContentWidth();
        self.palette_step = .commands;
        self.ui_tree.clearFocus();
        try self.composeUi();
        if (self.ui_tree.focus(.{ .value = "palette.query" })) try self.composeUi();
        try self.syncTextInput();
        self.invalidateUi();
    }

    /// The widest text any palette step can show: every command row as
    /// `composePalette` formats it, every choice, every prompt and the title.
    fn paletteContentWidth(self: *const App) u32 {
        var widest = labelCellWidth(" Command palette ");
        for (self.actions.definitions()) |definition| {
            const command = definition.palette orelse continue;
            var chord_storage: [96]u8 = undefined;
            const chords = palette_mod.formatActionBindings(
                &chord_storage,
                definition.name,
                self.bindings,
                self.binding_profile,
            );
            var row = labelCellWidth(definition.label);
            if (chords.text.len != 0) {
                row +|= 2 + labelCellWidth(chords.text);
                if (chords.truncated) row +|= labelCellWidth(" …");
            }
            widest = @max(widest, row);
            switch (command.argument) {
                .none => {},
                .input => |argument_meta| widest = @max(widest, labelCellWidth(argument_meta.prompt)),
                .choices => |argument_meta| {
                    widest = @max(widest, labelCellWidth(argument_meta.prompt));
                    for (argument_meta.values) |choice| widest = @max(widest, labelCellWidth(choice.label));
                },
            }
        }
        return widest;
    }

    fn closePalette(self: *App, clear_inputs: bool) !void {
        if (!self.paletteVisible()) return;
        self.composition.cancel();
        _ = takeCommittedText(&self.pending_committed_text);
        self.palette_step = .closed;
        self.ui_tree.clearFocus();
        if (clear_inputs) {
            clearPaletteInput(&self.palette_query);
            clearPaletteInput(&self.palette_argument);
            self.palette_model.refresh("");
        }
        try self.composeUi();
        try self.syncTextInput();
        self.invalidateUi();
    }

    fn beginPaletteArgument(self: *App, definition_index: usize) !void {
        const definitions = self.actions.definitions();
        if (definition_index >= definitions.len) return;
        const command = definitions[definition_index].palette orelse return;
        switch (command.argument) {
            .none => try self.runPaletteAction(definition_index, null),
            .input => {
                self.composition.cancel();
                clearPaletteInput(&self.palette_argument);
                self.palette_step = .{ .input = definition_index };
                self.ui_tree.clearFocus();
                try self.composeUi();
                if (self.ui_tree.focus(.{ .value = "palette.argument" })) try self.composeUi();
                try self.syncTextInput();
                self.invalidateUi();
            },
            .choices => |choice_argument| {
                if (choice_argument.values.len == 0) return;
                self.composition.cancel();
                try self.window.stopTextInput();
                self.palette_step = .{ .choices = .{
                    .definition_index = definition_index,
                    .selected = 0,
                } };
                self.ui_tree.clearFocus();
                if (self.choiceStepFiltered(definition_index)) {
                    // Typing filters the list (TASK-44 AC1): the field is
                    // focused, and arrows and Enter still drive the rows.
                    clearPaletteInput(&self.palette_argument);
                    self.refreshChoiceFilter();
                    try self.composeUi();
                    if (self.ui_tree.focus(.{ .value = "palette.filter" })) try self.composeUi();
                    try self.syncTextInput();
                } else {
                    try self.composeUi();
                }
                self.invalidateUi();
            },
        }
    }

    fn runPaletteAction(self: *App, definition_index: usize, value: ?[]const u8) !void {
        const definitions = self.actions.definitions();
        if (definition_index >= definitions.len) return;
        const definition = &definitions[definition_index];
        const command = definition.palette orelse return;
        var arguments: [1]inputmod.Argument = undefined;
        var invocation_arguments: []const inputmod.Argument = &.{};
        switch (command.argument) {
            .none => if (value != null) return,
            .input => |input_argument| {
                const supplied = std.mem.trim(u8, value orelse return, std.ascii.whitespace[0..]);
                // An agent's initial prompt is optional: Enter on an empty
                // field launches without one (TASK-56).
                if (supplied.len == 0 and definition_index != self.agent_prompt_index) return;
                if (supplied.len != 0) {
                    arguments[0] = .{ .name = input_argument.name, .value = supplied };
                    invocation_arguments = arguments[0..1];
                }
            },
            .choices => |choice_argument| {
                const supplied = value orelse return;
                arguments[0] = .{ .name = choice_argument.name, .value = supplied };
                invocation_arguments = arguments[0..1];
            },
        }

        // Choosing a font keeps its preview through the close below; the
        // action adopts it, and if it does not, the preview reverts here.
        const committing_font = definition_index == self.font_pick_index;
        if (committing_font) self.font_pick_committing = true;
        defer if (committing_font) {
            self.font_pick_committing = false;
            if (self.syncFontPreview()) self.invalidateUi();
        };

        // Keep Input bytes alive through invocation, but remove the modal
        // before a command composes its own UI (for example Rename tab).
        try self.closePalette(false);
        try self.dispatchAction(definition.name, .{
            .source = .palette,
            .arguments = invocation_arguments,
        });
        clearPaletteInput(&self.palette_query);
        clearPaletteInput(&self.palette_argument);
        self.palette_model.refresh("");
    }

    fn activatePalette(self: *App, origin: ?ui.Id) !void {
        switch (self.palette_step) {
            .closed => {},
            .commands => {
                const definition_index = if (origin) |id|
                    paletteSemanticIndex(id.value, "palette.action.") orelse
                        self.palette_model.selectedDefinitionIndex() orelse return
                else
                    self.palette_model.selectedDefinitionIndex() orelse return;
                try self.beginPaletteArgument(definition_index);
            },
            .input => |definition_index| {
                try self.runPaletteAction(definition_index, self.palette_argument.text());
            },
            .choices => |step| {
                const definition = &self.actions.definitions()[step.definition_index];
                const values = switch (definition.palette.?.argument) {
                    .choices => |choice_argument| choice_argument.values,
                    else => return,
                };
                const choice_index = if (origin) |id|
                    paletteChoiceSemanticIndex(id.value, step.definition_index) orelse step.selected
                else
                    step.selected;
                if (choice_index >= values.len) return;
                if (self.choiceStepFiltered(step.definition_index) and self.choiceFilterPosition(choice_index) == null) return;
                try self.runPaletteAction(step.definition_index, values[choice_index].value);
            },
        }
    }

    fn movePaletteSelection(self: *App, next: bool) !void {
        switch (self.palette_step) {
            .commands => {
                if (next) self.palette_model.selectNext() else self.palette_model.selectPrevious();
                try self.refreshActiveUi();
            },
            .choices => |step| {
                const definition = &self.actions.definitions()[step.definition_index];
                const values = switch (definition.palette.?.argument) {
                    .choices => |choice_argument| choice_argument.values,
                    else => return,
                };
                if (values.len == 0) return;
                const selected = if (self.choiceStepFiltered(step.definition_index)) filtered: {
                    const count = self.choice_filter_len;
                    if (count == 0) return;
                    const position = self.choiceFilterPosition(step.selected) orelse 0;
                    const moved = if (next) (position + 1) % count else if (position == 0) count - 1 else position - 1;
                    break :filtered self.choice_filter[moved];
                } else if (next)
                    (step.selected + 1) % values.len
                else if (step.selected == 0)
                    values.len - 1
                else
                    step.selected - 1;
                self.palette_step = .{ .choices = .{
                    .definition_index = step.definition_index,
                    .selected = selected,
                } };
                try self.refreshActiveUi();
            },
            .closed, .input => {},
        }
    }

