/// The pane id the connection view's layout carries. No pane has it: pane
/// ids are monotonic from one and a workspace never makes four billion.
const connection_pane_id: workspace.PaneId = @enumFromInt(std.math.maxInt(u32));

/// The files one `Include` glob names in its directory, bounded and sorted
/// as OpenSSH's own glob expansion is.
const IncludeMatches = struct {
    pattern: []const u8,
    names: [remote.max_include_files][256]u8 = undefined,
    lens: [remote.max_include_files]usize = undefined,
    count: usize = 0,

    fn at(self: *const IncludeMatches, index: usize) []const u8 {
        return self.names[index][0..self.lens[index]];
    }

    fn add(self: *IncludeMatches, name: []const u8) void {
        if (self.count == remote.max_include_files or name.len > self.names[0].len) return;
        @memcpy(self.names[self.count][0..name.len], name);
        self.lens[self.count] = name.len;
        self.count += 1;
    }

    fn visit(context: *anyopaque, entry: workspace.DirEntry) bool {
        const self: *IncludeMatches = @ptrCast(@alignCast(context));
        if (entry.kind == .directory) return true;
        if (remote.globMatch(self.pattern, entry.name)) self.add(entry.name);
        return self.count < remote.max_include_files;
    }

    fn sort(self: *IncludeMatches) void {
        var index: usize = 1;
        while (index < self.count) : (index += 1) {
            var at_index = index;
            while (at_index != 0 and std.mem.order(u8, self.at(at_index), self.at(at_index - 1)) == .lt) : (at_index -= 1) {
                std.mem.swap([256]u8, &self.names[at_index], &self.names[at_index - 1]);
                std.mem.swap(usize, &self.lens[at_index], &self.lens[at_index - 1]);
            }
        }
    }
};

/// `text` cut to at most `cells` codepoints, the last one replaced by `…`
/// when anything was cut. Each codepoint is counted as one cell; a wider one
/// is still clipped safely by `ui.Text`. `text` must be valid UTF-8 no longer
/// than `buffer.len - 3`, which `git.validName` guarantees for branch names.
fn ellipsizeToCells(buffer: []u8, text: []const u8, cells: u32) []const u8 {
    if (cells == 0) return "";
    var view = (std.unicode.Utf8View.init(text) catch return text).iterator();
    var count: u32 = 0;
    var keep_end: usize = 0;
    while (view.nextCodepointSlice()) |_| {
        count += 1;
        if (count < cells) keep_end = view.i;
        if (count > cells) {
            if (keep_end + 3 > buffer.len) return text;
            @memcpy(buffer[0..keep_end], text[0..keep_end]);
            @memcpy(buffer[keep_end .. keep_end + 3], "…");
            return buffer[0 .. keep_end + 3];
        }
    }
    return text;
}

test "agent view rows paint their prefix, body and selection as separate runs" {
    const first: agent_view.Row = .{ .kind = .message, .seq = 1, .text = "fake › hello world", .prefix_len = "fake › ".len, .prefix_tone = .assistant, .tone = .normal };
    const continuation: agent_view.Row = .{ .kind = .message, .seq = 1, .text = "       again", .prefix_len = 7, .prefix_tone = .normal, .tone = .normal };
    var runs: [4]ui.Run = undefined;
    const plain = App.agentViewRuns(&first, null, 0, &runs);
    try std.testing.expectEqual(@as(usize, 2), plain.len);
    try std.testing.expectEqualStrings("fake › ", plain[0].text);
    try std.testing.expectEqual(theme.Role.green, plain[0].style.foreground);
    try std.testing.expect(plain[1].style.background == null);

    // Selected from cell 9 of row 0 through cell 9 of row 1.
    const selection: agent_view.Selection = .{ .anchor = .{ .row = 0, .col = 9 }, .caret = .{ .row = 1, .col = 9 } };
    const head = App.agentViewRuns(&first, selection, 0, &runs);
    try std.testing.expectEqual(@as(usize, 3), head.len);
    try std.testing.expectEqualStrings("he", head[1].text);
    try std.testing.expectEqualStrings("llo world", head[2].text);
    try std.testing.expectEqual(@as(?theme.Role, .selection), head[2].style.background);
    var more: [4]ui.Run = undefined;
    const tail = App.agentViewRuns(&continuation, selection, 1, &more);
    try std.testing.expectEqual(@as(usize, 3), tail.len);
    try std.testing.expectEqual(@as(?theme.Role, .selection), tail[0].style.background);
    try std.testing.expectEqual(@as(?theme.Role, .selection), tail[1].style.background);
    try std.testing.expectEqualStrings("ag", tail[1].text);
    try std.testing.expect(tail[2].style.background == null);
}

test "branch labels are ellipsized to the row's cells" {
    var buffer: [git.max_name_bytes + 3]u8 = undefined;
    try std.testing.expectEqualStrings("main", ellipsizeToCells(&buffer, "main", 4));
    try std.testing.expectEqualStrings("mai…", ellipsizeToCells(&buffer, "mainline", 4));
    try std.testing.expectEqualStrings("fé…", ellipsizeToCells(&buffer, "féature", 3));
    try std.testing.expectEqualStrings("", ellipsizeToCells(&buffer, "x", 0));
    try std.testing.expectEqualStrings("…", ellipsizeToCells(&buffer, "xy", 1));
}

