fn dragPaneDivider(
    self: *App,
    io: Io,
    out: *Writer,
    divider: workspace.DividerLayout,
    cells: i32,
) !bool {
    var id_buffer: [pane_semantic_capacity]u8 = undefined;
    const id = try dividerSemanticId(&id_buffer, self.activePresentation().key, divider.divider_id);
    const element = self.ui_tree.byId(.{ .value = id }) orelse return false;
    const start = elementCenter(element, self.window.state.scale);
    const cell = self.fonts.metrics().cell;
    const scale = self.window.state.scale.factor;
    var finish_x = start.x;
    var finish_y = start.y;
    switch (divider.split) {
        .right => finish_x += @as(f32, @floatFromInt(cells * @as(i32, @intCast(cell.width_px)))) / scale,
        .down => finish_y += @as(f32, @floatFromInt(cells * @as(i32, @intCast(cell.height_px)))) / scale,
    }
    return try postButton(self, io, out, .{ .button = .left, .action = .press, .x = start.x, .y = start.y }) and
        try postMotion(self, io, out, .{ .buttons = .{ .left = true }, .x = finish_x, .y = finish_y }) and
        try postButton(self, io, out, .{ .button = .left, .action = .release, .x = finish_x, .y = finish_y });
}

/// Exercise TASK-30 through production bindings, semantic hit testing, the
/// real workspace model, PTYs and the pane compositor.
fn panesTest(self: *App, io: Io, out: *Writer) !u8 {
    var failures: usize = 0;
    try self.drawFrame();
    panesCheck(out, &failures, try waitForPanes(self, io, out, .{ .focused_text = "PANE-PWD:" }), "the first real pane child became ready", .{});
    panesCheck(out, &failures, try waitForPanes(self, io, out, .{ .cwd = "/tmp" }), "the source pane reported tracked cwd /tmp", .{});

    const tab_id = self.activeWorkspace().activeTabId() orelse return error.SessionNotFound;
    const root_pane = self.activeWorkspace().focusedPaneId(tab_id) orelse return error.SessionNotFound;
    const root_session = self.activeWorkspace().focusedPaneSessionId(tab_id) orelse return error.SessionNotFound;
    const split_right_mods: platform.Mods = switch (self.binding_profile) {
        .macos => .{ .super = true },
        .linux_windows => .{ .ctrl = true, .shift = true },
    };
    panesCheck(out, &failures, try postKey(self, io, out, if (self.binding_profile == .macos) 'd' else 'e', split_right_mods), "the split-right binding travelled through SDL", .{});
    const right_pane = self.activeWorkspace().focusedPaneId(tab_id) orelse return error.SessionNotFound;
    const right_session = self.activeWorkspace().focusedPaneSessionId(tab_id) orelse return error.SessionNotFound;
    panesCheck(out, &failures, right_pane != root_pane and right_session != root_session and
        try waitForPanes(self, io, out, .{ .focused_text = "PANE-PWD:/tmp" }), "split right kept stable ids and spawned in the actual inherited cwd /tmp", .{});

    const split_down_mods: platform.Mods = switch (self.binding_profile) {
        .macos => .{ .shift = true, .super = true },
        .linux_windows => .{ .ctrl = true, .shift = true },
    };
    panesCheck(out, &failures, try postKey(self, io, out, if (self.binding_profile == .macos) 'd' else 'o', split_down_mods), "the split-down binding created a nested pane", .{});
    const lower_pane = self.activeWorkspace().focusedPaneId(tab_id) orelse return error.SessionNotFound;
    const lower_session = self.activeWorkspace().focusedPaneSessionId(tab_id) orelse return error.SessionNotFound;
    panesCheck(out, &failures, lower_pane != root_pane and lower_pane != right_pane and
        lower_session != root_session and lower_session != right_session and
        self.activeWorkspace().tab(tab_id).?.paneCount() == 3 and
        try waitForPanes(self, io, out, .{ .focused_text = "PANE-PWD:/tmp" }), "nested layout retained three distinct pane/session identities", .{});

    var root_id_buffer: [pane_semantic_capacity]u8 = undefined;
    const root_id = try paneSemanticId(&root_id_buffer, self.activePresentation().key, root_pane);
    var trace: ClipboardTrace = .{};
    defer trace.deinit(self.allocator);
    self.trace = &trace;
    defer self.trace = null;
    const sent_before_click = trace.sent.items.len;
    panesCheck(out, &failures, try clickTabsElement(self, io, out, root_id) and
        self.activeWorkspace().focusedPaneId(tab_id) == root_pane and
        trace.sent.items.len > sent_before_click, "clicking an inactive pane focused it and delivered the same press to terminal mouse reporting", .{});

    const focus_mods: platform.Mods = switch (self.binding_profile) {
        .macos => .{ .alt = true, .super = true },
        .linux_windows => .{ .alt = true },
    };
    panesCheck(out, &failures, try postNamedKey(self, io, out, .right, focus_mods) and
        self.activeWorkspace().focusedPaneId(tab_id) != root_pane, "directional keyboard focus crossed to the right branch", .{});

    try self.drawFrame();
    if (self.divider_layout_count == 0) return error.InvalidGeometry;
    const divider = self.divider_layouts[0];
    const divider_before = divider.rect;
    const size_before_drag = self.activeLive().terminal().gridSize();
    panesCheck(out, &failures, try dragPaneDivider(self, io, out, divider, 1), "the semantic one-cell divider accepted a real pointer drag", .{});
    const divider_after = self.divider_layouts[0].rect;
    const size_after_drag = self.activeLive().terminal().gridSize();
    panesCheck(out, &failures, !std.meta.eql(divider_before, divider_after) and
        !std.meta.eql(size_before_drag, size_after_drag), "divider drag changed layout and the focused PTY size", .{});

    const resize_mods: platform.Mods = switch (self.binding_profile) {
        .macos => .{ .ctrl = true, .super = true },
        .linux_windows => .{ .ctrl = true, .alt = true },
    };
    const size_before_key = self.activeLive().terminal().gridSize();
    panesCheck(out, &failures, try postNamedKey(self, io, out, .left, resize_mods), "the keyboard resize binding travelled through SDL", .{});
    panesCheck(out, &failures, !std.meta.eql(size_before_key, self.activeLive().terminal().gridSize()), "keyboard resize changed the focused PTY geometry", .{});

    const hidden_session = self.activePresentation().active_session_id;
    try self.window.postTextInput("hidden");
    _ = try pumpUntil(self, io, out, .text_input, self_test_event_budget_ms);
    _ = try postNamedKey(self, io, out, .enter, .{});
    _ = try clickTabsElement(self, io, out, root_id);
    const zoom_mods: platform.Mods = switch (self.binding_profile) {
        .macos => .{ .shift = true, .super = true },
        .linux_windows => .{ .ctrl = true, .shift = true },
    };
    panesCheck(out, &failures, try postNamedKey(self, io, out, .enter, zoom_mods) and
        self.activeWorkspace().tab(tab_id).?.zoomedPaneId() == root_pane and
        self.activeWorkspace().tab(tab_id).?.paneCount() == 3, "zoom filled the tab without replacing sessions", .{});
    panesCheck(out, &failures, try waitForPanes(self, io, out, .{ .session_text = .{ .id = hidden_session, .text = "PANE-ECHO:hidden" } }), "a pane hidden by zoom continued pumping output", .{});
    panesCheck(out, &failures, try postNamedKey(self, io, out, .enter, zoom_mods) and
        self.activeWorkspace().tab(tab_id).?.zoomedPaneId() == null and
        self.activeWorkspace().paneSessionId(tab_id, lower_pane) == lower_session, "unzoom restored the same nested sessions", .{});
    panesCheck(out, &failures, try clickPaletteCommand(self, io, out, pane_zoom_action, null) and
        self.activeWorkspace().tab(tab_id).?.zoomedPaneId() == root_pane and
        self.activeWorkspace().tab(tab_id).?.paneCount() == 3, "the clickable sidebar zoomed the focused pane through the named action", .{});
    panesCheck(out, &failures, try clickPaletteCommand(self, io, out, pane_zoom_action, null) and
        self.activeWorkspace().tab(tab_id).?.zoomedPaneId() == null and
        self.activeWorkspace().paneSessionId(tab_id, lower_pane) == lower_session, "the clickable sidebar unzoomed without replacing sessions", .{});

    var lower_id_buffer: [pane_semantic_capacity]u8 = undefined;
    const lower_id = try paneSemanticId(&lower_id_buffer, self.activePresentation().key, lower_pane);
    const zoom_element = self.ui_tree.byId(.{ .value = "sidebar.palette" }) orelse return error.ElementNotFound;
    const lower_element = self.ui_tree.byId(.{ .value = lower_id }) orelse return error.ElementNotFound;
    const zoom_point = elementCenter(zoom_element, self.window.state.scale);
    const lower_point = elementCenter(lower_element, self.window.state.scale);
    const sent_before_ui_drag = trace.sent.items.len;
    const pressed_zoom = try postButton(self, io, out, .{ .button = .left, .action = .press, .x = zoom_point.x, .y = zoom_point.y });
    const dragged_over_inactive_pane = try postMotion(self, io, out, .{ .buttons = .{ .left = true }, .x = lower_point.x, .y = lower_point.y });
    const released_over_inactive_pane = try postButton(self, io, out, .{ .button = .left, .action = .release, .x = lower_point.x, .y = lower_point.y });
    panesCheck(out, &failures, pressed_zoom and dragged_over_inactive_pane and released_over_inactive_pane and
        trace.sent.items.len == sent_before_ui_drag and
        self.activeWorkspace().focusedPaneId(tab_id) == root_pane and !self.paletteVisible() and
        self.activeWorkspace().tab(tab_id).?.zoomedPaneId() == null, "a sidebar-owned press kept drag motion and release out of the inactive terminal", .{});

    _ = try clickTabsElement(self, io, out, lower_id);
    try self.window.postTextInput("busy-pane");
    _ = try pumpUntil(self, io, out, .text_input, self_test_event_budget_ms);
    _ = try postNamedKey(self, io, out, .enter, .{});
    panesCheck(out, &failures, try waitForPanes(self, io, out, .{ .session_text = .{ .id = lower_session, .text = "busy-pane" } }), "the close fixture entered a shell-marked foreground phase", .{});
    const close_mods: platform.Mods = switch (self.binding_profile) {
        .macos => .{ .shift = true, .super = true },
        .linux_windows => .{ .ctrl = true, .shift = true },
    };
    panesCheck(out, &failures, try postKey(self, io, out, 'x', close_mods) and
        try waitForPanes(self, io, out, .{ .element = "tab-close.dialog" }) and
        self.pending_close_pane != null, "the pane-close binding opened the shared confirmation modal", .{});
    _ = try postNamedKey(self, io, out, .escape, .{});
    panesCheck(out, &failures, self.pending_close_pane == null and
        self.activeWorkspace().paneSessionId(tab_id, lower_pane) == lower_session, "Escape cancelled the keyboard-requested close without changing the tree", .{});
    panesCheck(out, &failures, try clickPaletteCommand(self, io, out, pane_close_action, null) and
        try waitForPanes(self, io, out, .{ .element = "tab-close.dialog" }) and
        self.pending_close_pane != null, "closing a running pane opened the shared confirmation modal", .{});
    const routes_before_modal = self.terminal_key_route_count;
    try self.window.postTextInput("LEAK");
    _ = try pumpUntil(self, io, out, .text_input, self_test_event_budget_ms);
    _ = try postKey(self, io, out, 'x', .{});
    panesCheck(out, &failures, self.terminal_key_route_count == routes_before_modal and self.pending_committed_text.len == 0, "the pane-close modal isolated committed and key input", .{});
    const panes_before_modal_click = self.activeWorkspace().tab(tab_id).?.paneCount();
    _ = try clickTabsElement(self, io, out, "sidebar.palette");
    panesCheck(out, &failures, self.activeWorkspace().tab(tab_id).?.paneCount() == panes_before_modal_click and
        !self.paletteVisible() and self.pending_close_pane != null, "the pane-close modal isolated pointer input", .{});
    const viewport_before_modal_wheel = self.activeLive().terminal().viewport().offset;
    _ = try postWheelEvent(self, io, out, 3);
    panesCheck(out, &failures, self.activeLive().terminal().viewport().offset == viewport_before_modal_wheel, "the pane-close modal isolated wheel input", .{});
    _ = try postNamedKey(self, io, out, .escape, .{});
    panesCheck(out, &failures, self.pending_close_pane == null and self.activeWorkspace().paneSessionId(tab_id, lower_pane) == lower_session, "Escape cancelled pane close without changing the tree", .{});

    _ = try clickPaletteCommand(self, io, out, pane_close_action, null);
    _ = try postNamedKey(self, io, out, .tab, .{});
    _ = try postNamedKey(self, io, out, .enter, .{});
    panesCheck(out, &failures, self.activeWorkspace().paneSessionId(tab_id, lower_pane) == null and
        self.activeWorkspace().tab(tab_id).?.paneCount() == 2 and self.activePresentation().pane_renderers.items.len == 2, "confirmation closed the pane, renderer and session and rebalanced its sibling", .{});

    panesCheck(out, &failures, try clickPaletteCommand(self, io, out, pane_close_action, null) and
        self.activeWorkspace().tab(tab_id).?.paneCount() == 1 and
        self.activeWorkspace().focusedPaneSessionId(tab_id) == root_session and
        self.activePresentation().active_session_id == root_session and self.ui_tree.focusedElement() == null and
        self.ui_key_state.len == 0, "closing the idle sibling directly rebalanced to one terminal-owned final leaf", .{});
    try self.window.postTextInput("final-busy");
    _ = try pumpUntil(self, io, out, .text_input, self_test_event_budget_ms);
    _ = try postNamedKey(self, io, out, .enter, .{});
    panesCheck(out, &failures, try waitForPanes(self, io, out, .{ .session_text = .{ .id = root_session, .text = "final-busy" } }), "the final pane entered a foreground phase before close", .{});
    _ = try clickPaletteCommand(self, io, out, pane_close_action, null);
    panesCheck(out, &failures, self.pending_close_tab_id == tab_id and self.pending_close_pane == null, "closing the final pane delegated to the tab close policy", .{});
    _ = try postNamedKey(self, io, out, .escape, .{});
    panesCheck(out, &failures, self.activeWorkspace().tab(tab_id).?.paneCount() == 1 and !self.requested_shutdown, "cancelling final-pane close left the tab usable", .{});

    const mouse_split = try clickPaletteCommand(self, io, out, pane_split_action, 0);
    const final_right_session = self.activeWorkspace().focusedPaneSessionId(tab_id) orelse return error.SessionNotFound;
    panesCheck(out, &failures, mouse_split and
        final_right_session != root_session and
        self.activeWorkspace().tab(tab_id).?.paneCount() == 2 and
        try waitForPanes(self, io, out, .{ .session_text = .{ .id = final_right_session, .text = "PANE-PWD:/tmp" } }), "the clickable sidebar split right through the named action", .{});
    _ = try postKey(self, io, out, if (self.binding_profile == .macos) 'd' else 'o', split_down_mods);
    const final_lower_session = self.activeWorkspace().focusedPaneSessionId(tab_id) orelse return error.SessionNotFound;
    _ = try waitForPanes(self, io, out, .{ .session_text = .{ .id = final_lower_session, .text = "PANE-PWD:/tmp" } });
    try self.drawFrame();
    panesCheck(out, &failures, self.pane_layout_count == 3 and self.divider_layout_count == 2, "the final frame contains three panes and two one-cell dividers", .{});
    _ = try self.capture();
    out.print("panes-test: {d} failure(s)\n", .{failures}) catch {};
    out.flush() catch {};
    return if (failures == 0) 0 else 1;
}

const scratchpad_test_budget_ms: i64 = 5000;

const ScratchpadWait = union(enum) {
    child,
    prompt,
    replacement: *anyopaque,
    text: []const u8,
    element: []const u8,
};

fn scratchpadWaitMet(self: *App, condition: ScratchpadWait) !bool {
    const scratchpad = self.scratchpadLive() orelse return false;
    return switch (condition) {
        .child => scratchpad.child() != null,
        .prompt => prompt: {
            try scratchpad.terminal().refresh(self.allocator);
            const has_prompt = scratchpad.terminal().visibleTextContains("$") or
                scratchpad.terminal().visibleTextContains("#");
            break :prompt scratchpad.child() != null and has_prompt and
                !self.activeWorkspace().needsPump();
        },
        .replacement => |old_ptr| if (scratchpad.child()) |child| child.ptr != old_ptr else false,
        .text => |text| text_found: {
            try scratchpad.terminal().refresh(self.allocator);
            break :text_found scratchpad.terminal().visibleTextContains(text);
        },
        .element => |id| self.ui_tree.byId(.{ .value = id }) != null,
    };
}

fn waitForScratchpad(self: *App, io: Io, out: *Writer, condition: ScratchpadWait) !bool {
    const deadline = Io.Clock.real.now(io).nanoseconds + scratchpad_test_budget_ms * std.time.ns_per_ms;
    while (true) {
        if (try scratchpadWaitMet(self, condition)) return true;
        const event = self.window.pump(@min(eventWaitBudget(io, deadline, false), idle_tick_ms));
        if (event) |one| {
            describeEvent(out, one) catch {};
            if (!try self.handle(one)) return false;
        }
        if (self.poll()) self.scheduler.invalidate();
        if (self.scheduler.shouldDraw()) try self.drawFrame();
        if (Io.Clock.real.now(io).nanoseconds >= deadline) return try scratchpadWaitMet(self, condition);
    }
}

fn scratchpadCheck(out: *Writer, failures: *usize, ok: bool, comptime format: []const u8, args: anytype) void {
    out.print("scratchpad-test: {s} " ++ format ++ "\n", .{if (ok) "ok  " else "FAIL"} ++ args) catch {};
    if (!ok) failures.* += 1;
}

fn postScratchpadText(self: *App, io: Io, out: *Writer, text: [:0]const u8) !bool {
    try self.window.postTextInput(text);
    return pumpUntil(self, io, out, .text_input, self_test_event_budget_ms);
}

fn scratchpadChord(self: *App, io: Io, out: *Writer, ninety: bool) !bool {
    const mods: platform.Mods = switch (self.binding_profile) {
        .macos => .{ .shift = ninety, .super = true },
        .linux_windows => .{ .ctrl = true, .shift = ninety },
    };
    return postKey(self, io, out, '`', mods);
}

/// Exercise the real workspace scratchpad through its shipped keys, semantic
/// controls, SDL input path, retained terminal renderer and PTY replacement.
fn scratchpadTest(self: *App, io: Io, out: *Writer) !u8 {
    var failures: usize = 0;
    scratchpadCheck(out, &failures, try waitForScratchpad(self, io, out, .child), "the hidden workspace scratchpad started its interactive shell", .{});
    const scratchpad = self.scratchpadLive() orelse return 1;
    const original_child = scratchpad.child() orelse return 1;
    const workspace_key = self.activePresentation().key;
    var scratchpad_id_buffer: [workspace_semantic_capacity]u8 = undefined;
    const scratchpad_semantic = try scratchpadSemanticId(&scratchpad_id_buffer, workspace_key, "");
    var scratchpad_terminal_id_buffer: [workspace_semantic_capacity]u8 = undefined;
    const scratchpad_terminal_semantic = try scratchpadSemanticId(&scratchpad_terminal_id_buffer, workspace_key, "terminal");
    var scratchpad_restart_id_buffer: [workspace_semantic_capacity]u8 = undefined;
    const scratchpad_restart_semantic = try scratchpadSemanticId(&scratchpad_restart_id_buffer, workspace_key, "restart");
    var scratchpad_hide_id_buffer: [workspace_semantic_capacity]u8 = undefined;
    const scratchpad_hide_semantic = try scratchpadSemanticId(&scratchpad_hide_id_buffer, workspace_key, "hide");

    scratchpadCheck(out, &failures, try scratchpadChord(self, io, out, false) and
        self.activePresentation().scratchpad_presentation == .fifty and
        try waitForScratchpad(self, io, out, .{ .element = scratchpad_terminal_semantic }), "the 50 percent binding presented the semantic scratchpad terminal", .{});
    const half_inner = self.scratchpadInnerRect() orelse return 1;
    scratchpadCheck(out, &failures, @as(u32, scratchpad.terminal().gridSize().rows) == half_inner.height and
        @as(u32, scratchpad.terminal().gridSize().cols) == half_inner.width, "the 50 percent dock resized the same PTY to its bordered inner rectangle", .{});

    _ = try postScratchpadText(self, io, out, "stty -echo");
    _ = try postNamedKey(self, io, out, .enter, .{});
    _ = try postScratchpadText(self, io, out, "printf 'SCRATCH-ONE\\n'; scratch_state=kept; read scratch_hold; printf 'SCRATCH-HOLD:%s\\n' \"$scratch_hold\"");
    _ = try postNamedKey(self, io, out, .enter, .{});
    scratchpadCheck(out, &failures, try waitForScratchpad(self, io, out, .{ .text = "SCRATCH-ONE" }), "a foreground program produced output in the scratchpad", .{});

    scratchpadCheck(out, &failures, try scratchpadChord(self, io, out, false) and
        self.activePresentation().scratchpad_presentation == .hidden and
        self.ui_tree.byId(.{ .value = scratchpad_semantic }) == null, "repeating the 50 percent binding hid the view without terminating it", .{});
    scratchpadCheck(out, &failures, try scratchpadChord(self, io, out, true) and
        self.activePresentation().scratchpad_presentation == .ninety and
        self.scratchpadLive().?.child().?.ptr == original_child.ptr and
        try waitForScratchpad(self, io, out, .{ .text = "SCRATCH-ONE" }), "the 90 percent binding restored the same process and retained output", .{});
    const ninety_inner = self.scratchpadInnerRect() orelse return 1;
    scratchpadCheck(out, &failures, ninety_inner.height > half_inner.height and
        @as(u32, scratchpad.terminal().gridSize().rows) == ninety_inner.height, "the second binding expanded the retained scratchpad to about 90 percent", .{});

    _ = try postScratchpadText(self, io, out, "resumed");
    _ = try postNamedKey(self, io, out, .enter, .{});
    scratchpadCheck(out, &failures, try waitForScratchpad(self, io, out, .{ .text = "SCRATCH-HOLD:resumed" }), "the foreground read survived hide and resumed with its state intact", .{});
    _ = try postScratchpadText(self, io, out, "printf 'SCRATCH-STATE:%s\\n' \"$scratch_state\"");
    _ = try postNamedKey(self, io, out, .enter, .{});
    scratchpadCheck(out, &failures, try waitForScratchpad(self, io, out, .{ .text = "SCRATCH-STATE:kept" }), "shell state remained alive across both presentations", .{});
    try self.activeLive().terminal().refresh(self.allocator);
    scratchpadCheck(out, &failures, !self.activeLive().terminal().visibleTextContains("resumed"), "committed text and Enter reached only the presented scratchpad", .{});

    _ = try postNamedKey(self, io, out, .escape, .{});
    scratchpadCheck(out, &failures, self.activePresentation().scratchpad_presentation == .hidden, "Escape hid the scratchpad without stopping its child", .{});
    _ = try scratchpadChord(self, io, out, true);
    const sidebar_before = self.sidebar_visible;
    const dispatch_before = self.action_dispatch_count;
    const sidebar_mods: platform.Mods = switch (self.binding_profile) {
        .macos => .{ .shift = true, .super = true },
        .linux_windows => .{ .ctrl = true, .shift = true },
    };
    _ = try postKey(self, io, out, 'b', sidebar_mods);
    scratchpadCheck(out, &failures, self.sidebar_visible == sidebar_before and
        self.action_dispatch_count == dispatch_before, "visible scratchpad modal routing blocked underlying key actions", .{});
    const active_before = self.activePresentation().active_session_id;
    var active_tab_semantic_buffer: [workspace_semantic_capacity]u8 = undefined;
    const active_tab_semantic = try tabSemanticId(
        &active_tab_semantic_buffer,
        workspace_key,
        self.activeWorkspace().activeTabId().?,
    );
    _ = try clickTabsElement(self, io, out, active_tab_semantic);
    scratchpadCheck(out, &failures, self.activePresentation().active_session_id == active_before, "pointer input outside the dock terminal could not activate underlying workspace UI", .{});

    scratchpadCheck(out, &failures, try paletteChord(self, io, out) and self.paletteVisible(), "the command palette opened over the visible scratchpad", .{});
    _ = try postNamedKey(self, io, out, .escape, .{});
    scratchpadCheck(out, &failures, !self.paletteVisible() and self.scratchpadVisible() and
        self.ui_key_state.len == 0, "palette Escape kept its release ownership without hiding the scratchpad", .{});
    scratchpadCheck(out, &failures, try paletteChord(self, io, out) and self.paletteVisible(), "the palette reopened immediately after its Escape gesture completed", .{});
    _ = try postNamedKey(self, io, out, .escape, .{});

    scratchpadCheck(out, &failures, try clickTabsElement(self, io, out, scratchpad_restart_semantic), "the clickable restart control dispatched through the semantic tree", .{});
    scratchpadCheck(out, &failures, try waitForScratchpad(self, io, out, .{ .replacement = original_child.ptr }), "restart atomically replaced the scratchpad child", .{});
    const restarted = self.scratchpadLive() orelse return 1;
    try restarted.terminal().refresh(self.allocator);
    scratchpadCheck(out, &failures, !restarted.terminal().visibleTextContains("SCRATCH-ONE"), "restart installed a fresh terminal instead of retaining old output", .{});
    _ = try postScratchpadText(self, io, out, "stty -echo");
    _ = try postNamedKey(self, io, out, .enter, .{});
    _ = try postScratchpadText(self, io, out, "printf 'SCRATCH-FRESH\\n'");
    _ = try postNamedKey(self, io, out, .enter, .{});
    scratchpadCheck(out, &failures, try waitForScratchpad(self, io, out, .{ .text = "SCRATCH-FRESH" }), "the fresh shell accepted terminal input after restart", .{});

    scratchpadCheck(out, &failures, try clickTabsElement(self, io, out, scratchpad_hide_semantic) and
        self.activePresentation().scratchpad_presentation == .hidden, "the clickable hide control removed only the presentation", .{});
    _ = try scratchpadChord(self, io, out, true);
    try self.drawFrame();
    _ = try self.capture();
    const final_overlay = self.overlayView();
    const final_inner = self.scratchpadInnerRect() orelse return 1;
    var underlay_paint_leaked = false;
    for (final_overlay.cells) |cell| {
        if (cell.position.col >= final_inner.x and cell.position.col < final_inner.right() and
            cell.position.row >= final_inner.y and cell.position.row < final_inner.bottom())
        {
            underlay_paint_leaked = true;
            break;
        }
    }
    scratchpadCheck(out, &failures, self.ui_tree.byId(.{ .value = scratchpad_semantic }) != null and
        self.ui_tree.byId(.{ .value = scratchpad_restart_semantic }) != null and
        self.ui_tree.byId(.{ .value = scratchpad_hide_semantic }) != null, "the final captured frame contains the 90 percent dock and both mouse controls", .{});
    scratchpadCheck(out, &failures, !underlay_paint_leaked, "the transparent dock masks all underlying UI paint without covering terminal output", .{});

    out.print("scratchpad-test: {d} failure(s)\n", .{failures}) catch {};
    out.flush() catch {};
    return if (failures == 0) 0 else 1;
}

fn paletteCheck(out: *Writer, failures: *usize, ok: bool, comptime format: []const u8, args: anytype) void {
    out.print("palette-test: {s} " ++ format ++ "\n", .{if (ok) "ok  " else "FAIL"} ++ args) catch {};
    if (!ok) failures.* += 1;
}

/// The deterministic peer behind every terminal created by `--palette-test`.
/// Its OSC 7 cwd makes New tab and Split pane exercise the real inherited-cwd
/// spawn path, while the exact line echo exposes any modal input leakage.
const palette_test_script =
    "stty -echo; " ++
    "printf '\\033]7;file://localhost/tmp\\007PALETTE-READY:%s\\r\\n' \"$PWD\"; " ++
    "while IFS= read -r line; do printf 'PALETTE-ECHO:%s\\r\\n' \"$line\"; done";

fn paletteChord(self: *App, io: Io, out: *Writer) !bool {
    const mods: platform.Mods = switch (self.binding_profile) {
        .macos => .{ .shift = true, .super = true },
        .linux_windows => .{ .ctrl = true, .shift = true },
    };
    return postKey(self, io, out, 'p', mods);
}

fn definitionIndex(self: *const App, action_name: []const u8) ?usize {
    for (self.actions.definitions(), 0..) |definition, index| {
        if (std.mem.eql(u8, definition.name, action_name)) return index;
    }
    return null;
}

fn paletteContainsDefinition(self: *const App, action_name: []const u8) bool {
    for (self.palette_model.results()) |index| {
        if (std.mem.eql(u8, self.actions.definitions()[index].name, action_name)) return true;
    }
    return false;
}

fn postPaletteText(self: *App, io: Io, out: *Writer, text: [:0]const u8) !bool {
    try self.window.postTextInput(text);
    return pumpUntil(self, io, out, .text_input, self_test_event_budget_ms);
}

/// Exercise TASK-31 through the production keybinding resolver, semantic tree,
/// action registry, workspace model and real SDL keyboard/mouse event path.
fn paletteTest(self: *App, io: Io, out: *Writer) !u8 {
    var failures: usize = 0;
    try self.drawFrame();
    paletteCheck(out, &failures, try waitForPanes(self, io, out, .{ .focused_text = "PALETTE-READY:" }), "the first real palette-test child became ready", .{});

    paletteCheck(out, &failures, try paletteChord(self, io, out), "the shipped palette chord travelled through SDL", .{});
    const dialog = self.ui_tree.byId(.{ .value = "palette.dialog" });
    const query = self.ui_tree.byId(.{ .value = "palette.query" });
    const centered = if (dialog) |element|
        @abs((element.bounds.x * 2 + @as(i32, @intCast(element.bounds.width))) - @as(i32, @intCast(self.size.width))) <=
            @as(i32, @intCast(self.fonts.metrics().cell.width_px)) and
            @abs((element.bounds.y * 2 + @as(i32, @intCast(element.bounds.height))) - @as(i32, @intCast(self.size.height))) <=
                @as(i32, @intCast(self.fonts.metrics().cell.height_px))
    else
        false;
    paletteCheck(out, &failures, self.paletteVisible() and dialog != null and centered and
        query != null and query.?.state.focused, "the centered semantic dialog opened with its filter focused", .{});
    paletteCheck(out, &failures, paletteContainsDefinition(self, tab_new_action) and
        paletteContainsDefinition(self, pane_split_action) and paletteContainsDefinition(self, settings_open_action) and
        self.actions.lookup("theme.select") == null and
        paletteContainsDefinition(self, remote_connect_action) and
        self.actions.lookup("font.select") == null and self.actions.lookup("workspace.reconnect") == null, "New tab, Split pane, Settings and Remote: connect are present while unshipped commands are absent", .{});

    paletteCheck(out, &failures, try postPaletteText(self, io, out, "newtab"), "fuzzy query text travelled through SDL", .{});
    const selected_new = self.palette_model.selectedDefinition();
    const new_definition_index = definitionIndex(self, tab_new_action) orelse return 1;
    var new_id_storage: [palette_semantic_capacity]u8 = undefined;
    const new_id = try std.fmt.bufPrint(&new_id_storage, "palette.action.{d}", .{new_definition_index});
    const new_row = self.ui_tree.byId(.{ .value = new_id });
    const expected_chord = if (self.binding_profile == .macos) "Cmd+T" else "Ctrl+Shift+T";
    // "newtab" also matches New tab with profile (TASK-46); the exact
    // command ranks first and is selected.
    paletteCheck(out, &failures, std.mem.eql(u8, self.palette_query.text(), "newtab") and
        self.palette_model.results().len == 2 and selected_new != null and
        std.mem.eql(u8, selected_new.?.name, tab_new_action) and new_row != null and
        std.mem.indexOf(u8, new_row.?.label, expected_chord) != null, "fuzzy filtering selected New tab and displayed its bound key", .{});

    const tabs_before_keyboard = self.activeWorkspace().tabCount();
    paletteCheck(out, &failures, try postNamedKey(self, io, out, .enter, .{}) and
        !self.paletteVisible() and self.activeWorkspace().tabCount() == tabs_before_keyboard + 1 and
        std.mem.eql(u8, self.last_dispatched_action orelse "", tab_new_action), "Enter ran the selected command and created a tab", .{});
    const keyboard_tab = self.activeWorkspace().activeTabId() orelse return error.SessionNotFound;
    const keyboard_session = self.activeWorkspace().focusedPaneSessionId(keyboard_tab) orelse return error.SessionNotFound;
    paletteCheck(out, &failures, try waitForPanes(self, io, out, .{ .session_text = .{
        .id = keyboard_session,
        .text = "PALETTE-READY:/tmp",
    } }), "the palette-created tab attached its inherited-cwd PTY before the next command", .{});

    _ = try paletteChord(self, io, out);
    const mru = self.palette_model.selectedDefinition();
    paletteCheck(out, &failures, mru != null and std.mem.eql(u8, mru.?.name, tab_new_action), "reopening with an empty query ranked the last command first", .{});
    _ = try postNamedKey(self, io, out, .escape, .{});
    paletteCheck(out, &failures, !self.paletteVisible() and self.ui_tree.byId(.{ .value = "palette.dialog" }) == null, "Escape closed the palette", .{});

    _ = try paletteChord(self, io, out);
    _ = try postPaletteText(self, io, out, "splitpane");
    _ = try postNamedKey(self, io, out, .enter, .{});
    const active_tab = self.activeWorkspace().activeTabId() orelse return 1;
    const panes_before_choice = self.activeWorkspace().tab(active_tab).?.paneCount();
    const split_definition_index = definitionIndex(self, pane_split_action) orelse return 1;
    var right_choice_storage: [palette_semantic_capacity]u8 = undefined;
    var down_choice_storage: [palette_semantic_capacity]u8 = undefined;
    const right_choice_id = try std.fmt.bufPrint(&right_choice_storage, "palette.choice.{d}.0", .{split_definition_index});
    const down_choice_id = try std.fmt.bufPrint(&down_choice_storage, "palette.choice.{d}.1", .{split_definition_index});
    paletteCheck(out, &failures, self.palette_step == .choices and
        self.ui_tree.byId(.{ .value = right_choice_id }) != null and
        self.ui_tree.byId(.{ .value = down_choice_id }) != null, "Split pane opened its nested direction choices", .{});
    paletteCheck(out, &failures, try clickTabsElement(self, io, out, down_choice_id) and
        !self.paletteVisible() and self.activeWorkspace().tab(active_tab).?.paneCount() == panes_before_choice + 1 and
        std.mem.eql(u8, self.last_dispatched_action orelse "", pane_split_action), "clicking Down dispatched the nested argument and split the pane", .{});
    const split_session = self.activeWorkspace().focusedPaneSessionId(active_tab) orelse return error.SessionNotFound;
    paletteCheck(out, &failures, try waitForPanes(self, io, out, .{ .session_text = .{
        .id = split_session,
        .text = "PALETTE-READY:/tmp",
    } }), "the palette-created pane attached its inherited-cwd PTY before the next command", .{});

    _ = try paletteChord(self, io, out);
    _ = try postPaletteText(self, io, out, "gototab");
    _ = try postNamedKey(self, io, out, .enter, .{});
    paletteCheck(out, &failures, self.palette_step == .input and
        self.ui_tree.byId(.{ .value = "palette.argument" }) != null and
        self.ui_tree.focusedElement() != null and
        std.mem.eql(u8, self.ui_tree.focusedElement().?.id.value, "palette.argument"), "Go to tab opened and focused its free-text argument", .{});
    _ = try postPaletteText(self, io, out, "1");
    _ = try postNamedKey(self, io, out, .enter, .{});
    const first_tab = self.activeWorkspace().tabAt(0) orelse return 1;
    paletteCheck(out, &failures, !self.paletteVisible() and self.activeWorkspace().activeTabId() == first_tab.id(), "the collected tab number reached the action handler", .{});

    _ = try paletteChord(self, io, out);
    const tabs_before_isolation = self.activeWorkspace().tabCount();
    const terminal_routes_before = self.terminal_key_route_count;
    const new_tab_mods: platform.Mods = switch (self.binding_profile) {
        .macos => .{ .super = true },
        .linux_windows => .{ .ctrl = true, .shift = true },
    };
    _ = try postKey(self, io, out, 't', new_tab_mods);
    paletteCheck(out, &failures, self.paletteVisible() and
        self.activeWorkspace().tabCount() == tabs_before_isolation and
        self.terminal_key_route_count == terminal_routes_before, "the modal palette blocked an underlying action binding and terminal route", .{});

    const outside = cellPosition(self, 0, 0);
    _ = try postButton(self, io, out, .{ .button = .left, .action = .press, .x = outside.x, .y = outside.y });
    _ = try postButton(self, io, out, .{ .button = .left, .action = .release, .x = outside.x, .y = outside.y });
    paletteCheck(out, &failures, !self.paletteVisible() and !self.palette_pointer_owned, "an outside click closed the palette and owned the matching release", .{});

    _ = try paletteChord(self, io, out);
    _ = try postPaletteText(self, io, out, "newtab");
    const tabs_before_mouse = self.activeWorkspace().tabCount();
    paletteCheck(out, &failures, try clickTabsElement(self, io, out, new_id) and
        self.activeWorkspace().tabCount() == tabs_before_mouse + 1 and !self.paletteVisible(), "clicking a fuzzy result ran the command through its semantic row", .{});
    const mouse_tab = self.activeWorkspace().activeTabId() orelse return error.SessionNotFound;
    const mouse_session = self.activeWorkspace().focusedPaneSessionId(mouse_tab) orelse return error.SessionNotFound;
    paletteCheck(out, &failures, try waitForPanes(self, io, out, .{ .session_text = .{
        .id = mouse_session,
        .text = "PALETTE-READY:/tmp",
    } }), "the mouse-created tab attached its real PTY before further palette input", .{});

    _ = try paletteChord(self, io, out);
    _ = try postPaletteText(self, io, out, "splitpane");
    _ = try postNamedKey(self, io, out, .enter, .{});
    const routes_before_choice_text = self.terminal_key_route_count;
    _ = try postPaletteText(self, io, out, "LEAK");
    paletteCheck(out, &failures, self.palette_step == .choices and
        self.terminal_key_route_count == routes_before_choice_text and self.pending_committed_text.len == 0, "committed text in a choice step could not leak to the terminal", .{});

    _ = try postNamedKey(self, io, out, .escape, .{});
    try self.window.postTextInput("terminal-probe");
    const probe_text_delivered = try pumpUntil(self, io, out, .text_input, self_test_event_budget_ms);
    const probe_enter_delivered = try postNamedKey(self, io, out, .enter, .{});
    const probe_echoed = try waitForPanes(self, io, out, .{ .session_text = .{
        .id = mouse_session,
        .text = "PALETTE-ECHO:terminal-probe",
    } });
    const isolated_live = self.activeWorkspace().sessionById(mouse_session) orelse return error.SessionNotFound;
    try isolated_live.terminal().refresh(self.allocator);
    paletteCheck(out, &failures, !self.paletteVisible() and probe_text_delivered and probe_enter_delivered and probe_echoed and
        !isolated_live.terminal().visibleTextContains("PALETTE-ECHO:splitpane") and
        !isolated_live.terminal().visibleTextContains("PALETTE-ECHO:LEAK"), "query and choice text stayed out of the PTY, then ordinary terminal input completed an exact round trip", .{});

    _ = try paletteChord(self, io, out);
    _ = try postPaletteText(self, io, out, "splitpane");
    _ = try postNamedKey(self, io, out, .enter, .{});
    try self.drawFrame();
    _ = try self.capture();
    paletteCheck(out, &failures, self.ui_tree.byId(.{ .value = "palette.dialog" }) != null and
        self.ui_tree.byId(.{ .value = right_choice_id }) != null, "the final captured frame contains the centered palette and nested choices", .{});

    out.print("palette-test: {d} failure(s)\n", .{failures}) catch {};
    out.flush() catch {};
    return if (failures == 0) 0 else 1;
}

/// The initial terminal peer for `--workspaces-test`. Workspaces created by
/// the scenario deliberately use the independent interactive-shell spec;
/// splits in either workspace use this fixed line-oriented peer.
const workspaces_test_script =
    "stty -echo; " ++
    "printf 'WORKSPACE-PTY-READY:%s\\r\\n' \"$PWD\"; " ++
    "while IFS= read -r line; do printf 'WORKSPACE-ECHO:%s\\r\\n' \"$line\"; done";

const workspaces_test_budget_ms: i64 = 8000;

const WorkspacesWait = union(enum) {
    count: usize,
    active: workspace.WorkspaceKey,
    session_child: struct { key: workspace.WorkspaceKey, id: session.SessionId },
    scratchpad_child: workspace.WorkspaceKey,
    session_text: struct { key: workspace.WorkspaceKey, id: session.SessionId, text: []const u8 },
    scratchpad_text: struct { key: workspace.WorkspaceKey, text: []const u8 },
    settled: workspace.WorkspaceKey,
    removed: workspace.WorkspaceKey,
};

fn workspacesWaitMet(self: *App, condition: WorkspacesWait) !bool {
    return switch (condition) {
        .count => |count| self.workspace_registry.count() == count,
        .active => |key| if (self.workspace_registry.activeKey()) |active| active == key else false,
        .session_child => |wanted| child: {
            const model = self.workspace_registry.byKey(wanted.key) orelse break :child false;
            const live = model.sessionById(wanted.id) orelse break :child false;
            break :child live.child() != null;
        },
        .scratchpad_child => |key| child: {
            const model = self.workspace_registry.byKey(key) orelse break :child false;
            const live = model.sessionById(model.scratchpadId()) orelse break :child false;
            break :child live.child() != null;
        },
        .session_text => |wanted| found: {
            const model = self.workspace_registry.byKey(wanted.key) orelse break :found false;
            const live = model.sessionById(wanted.id) orelse break :found false;
            try live.terminal().refresh(self.allocator);
            break :found live.terminal().visibleTextContains(wanted.text);
        },
        .scratchpad_text => |wanted| found: {
            const model = self.workspace_registry.byKey(wanted.key) orelse break :found false;
            const live = model.sessionById(model.scratchpadId()) orelse break :found false;
            try live.terminal().refresh(self.allocator);
            break :found live.terminal().visibleTextContains(wanted.text);
        },
        .settled => |key| settled: {
            const model = self.workspace_registry.byKey(key) orelse break :settled false;
            const presentation = self.presentationByKey(key) orelse break :settled false;
            break :settled presentation.load == null and presentation.scratchpad_load == null and
                !model.needsPump();
        },
        .removed => |key| self.workspace_registry.byKey(key) == null and self.presentationByKey(key) == null,
    };
}

fn waitForWorkspaces(self: *App, io: Io, out: *Writer, condition: WorkspacesWait) !bool {
    const deadline = Io.Clock.real.now(io).nanoseconds + workspaces_test_budget_ms * std.time.ns_per_ms;
    var observed_settled = false;
    while (true) {
        const met = try workspacesWaitMet(self, condition);
        switch (condition) {
            .settled => {
                // A running PTY may become readable just after one nonblocking
                // readiness check. Require a second quiet observation after a
                // normal event-loop wait/service pass before teardown.
                if (met and observed_settled) return true;
                observed_settled = met;
            },
            else => if (met) return true,
        }
        const event = self.window.pump(@min(self.waitBudget(io, deadline), 50));
        if (event) |one| {
            describeEvent(out, one) catch {};
            if (!try self.handle(one)) return false;
        }
        if (self.poll()) self.scheduler.invalidate();
        if (self.scheduler.shouldDraw()) try self.drawFrame();
        if (Io.Clock.real.now(io).nanoseconds >= deadline) {
            const final_met = try workspacesWaitMet(self, condition);
            return switch (condition) {
                .settled => final_met and observed_settled,
                else => final_met,
            };
        }
    }
}

fn workspacesCheck(out: *Writer, failures: *usize, ok: bool, comptime format: []const u8, args: anytype) void {
    out.print("workspaces-test: {s} " ++ format ++ "\n", .{if (ok) "ok  " else "FAIL"} ++ args) catch {};
    if (!ok) failures.* += 1;
}

fn postWorkspaceTerminalText(self: *App, io: Io, out: *Writer, text: [:0]const u8) !bool {
    try self.window.postTextInput(text);
    return pumpUntil(self, io, out, .text_input, self_test_event_budget_ms);
}

fn openWorkspacePaletteCommand(
    self: *App,
    io: Io,
    out: *Writer,
    query: [:0]const u8,
    action_name: []const u8,
) !bool {
    if (!try paletteChord(self, io, out)) return false;
    if (!try postPaletteText(self, io, out, query)) return false;
    const selected = self.palette_model.selectedDefinition() orelse return false;
    if (!std.mem.eql(u8, selected.name, action_name)) return false;
    return postNamedKey(self, io, out, .enter, .{});
}

fn workspacesScreenshotPath(io: Io, buffer: []u8) ![]const u8 {
    var id_buffer: [path_capacity]u8 = undefined;
    const id = try generateRunId(io, &id_buffer);
    return std.fmt.bufPrint(
        buffer,
        "{s}{c}workspaces-test-{s}.png",
        .{ fallback_log_dir, std.fs.path.sep, id },
    );
}

/// Exercise TASK-33 through the real action registry, semantic tree, SDL
/// queue, ExecutionContext workers, PTYs and per-workspace render state.
fn workspacesTest(self: *App, io: Io, out: *Writer) !u8 {
    var failures: usize = 0;
    try self.drawFrame();

    const first_key = self.workspace_registry.activeKey() orelse return 1;
    const first_session = self.activePresentation().active_session_id;
    workspacesCheck(out, &failures, try waitForWorkspaces(self, io, out, .{ .session_child = .{
        .key = first_key,
        .id = first_session,
    } }) and try waitForWorkspaces(self, io, out, .{ .scratchpad_child = first_key }) and
        try waitForWorkspaces(self, io, out, .{ .session_text = .{
            .key = first_key,
            .id = first_session,
            .text = "WORKSPACE-PTY-READY:",
        } }), "the initial workspace started independent terminal and scratchpad PTYs", .{});
    const first_model = self.workspace_registry.byKey(first_key) orelse return 1;
    const first_terminal_child = (first_model.sessionById(first_session) orelse return 1).child() orelse return 1;
    const first_scratch_child = (first_model.sessionById(first_model.scratchpadId()) orelse return 1).child() orelse return 1;

    _ = try postWorkspaceTerminalText(self, io, out, "alpha");
    _ = try postNamedKey(self, io, out, .enter, .{});
    workspacesCheck(out, &failures, try waitForWorkspaces(self, io, out, .{ .session_text = .{
        .key = first_key,
        .id = first_session,
        .text = "WORKSPACE-ECHO:alpha",
    } }), "terminal input completed a real round trip in the first workspace", .{});

    _ = try scratchpadChord(self, io, out, false);
    _ = try postScratchpadText(self, io, out, "stty -echo; ws_scratch=alpha; printf 'WORKSPACE-SCRATCH-A:%s\\n' \"$ws_scratch\"");
    _ = try postNamedKey(self, io, out, .enter, .{});
    workspacesCheck(out, &failures, self.activePresentation().scratchpad_presentation == .fifty and
        try waitForWorkspaces(self, io, out, .{ .scratchpad_text = .{
            .key = first_key,
            .text = "WORKSPACE-SCRATCH-A:alpha",
        } }), "the first scratchpad retained shell state in its 50 percent layout", .{});

    const create_opened = try openWorkspacePaletteCommand(self, io, out, "createworkspace", workspace_create_action);
    workspacesCheck(out, &failures, create_opened and self.palette_step == .input, "the palette opened Create workspace's directory input over the scratchpad", .{});
    if (!create_opened) return 1;
    _ = try postPaletteText(self, io, out, "/tmp");
    _ = try postNamedKey(self, io, out, .enter, .{});
    const second_key = self.workspace_registry.activeKey() orelse return 1;
    workspacesCheck(out, &failures, second_key != first_key and
        try waitForWorkspaces(self, io, out, .{ .count = 2 }) and
        self.activePresentation().scratchpad_presentation == .hidden, "palette creation added and activated one distinct /tmp workspace", .{});
    if (second_key == first_key) return 1;

    const second_session = self.activePresentation().active_session_id;
    workspacesCheck(out, &failures, try waitForWorkspaces(self, io, out, .{ .session_child = .{
        .key = second_key,
        .id = second_session,
    } }) and try waitForWorkspaces(self, io, out, .{ .scratchpad_child = second_key }), "the new workspace asynchronously started its terminal and reserved scratchpad", .{});
    _ = try postWorkspaceTerminalText(self, io, out, "stty -echo; printf 'WORKSPACE-SECOND-READY\\n'");
    _ = try postNamedKey(self, io, out, .enter, .{});
    workspacesCheck(out, &failures, try waitForWorkspaces(self, io, out, .{ .session_text = .{
        .key = second_key,
        .id = second_session,
        .text = "WORKSPACE-SECOND-READY",
    } }), "the created workspace terminal accepted input through its independent shell", .{});

    workspacesCheck(out, &failures, try clickPaletteCommand(self, io, out, pane_split_action, 0), "the sidebar created a persistent pane layout in the second workspace", .{});
    const second_tab_id = self.activeWorkspace().activeTabId() orelse return 1;
    const split_pane = self.activeWorkspace().focusedPaneId(second_tab_id) orelse return 1;
    const split_session = self.activePresentation().active_session_id;
    workspacesCheck(out, &failures, split_session != second_session and
        try waitForWorkspaces(self, io, out, .{ .session_child = .{
            .key = second_key,
            .id = split_session,
        } }) and try waitForWorkspaces(self, io, out, .{ .session_text = .{
        .key = second_key,
        .id = split_session,
        .text = "WORKSPACE-PTY-READY:/tmp",
    } }), "the split attached a second real PTY in the workspace cwd", .{});
    const split_child = (self.activeWorkspace().sessionById(split_session) orelse return 1).child() orelse return 1;
    var split_pane_id_buffer: [pane_semantic_capacity]u8 = undefined;
    const split_pane_id = try paneSemanticId(&split_pane_id_buffer, second_key, split_pane);
    const split_terminal_focused = try clickTabsElement(self, io, out, split_pane_id);
    _ = try postWorkspaceTerminalText(self, io, out, "beta");
    _ = try postNamedKey(self, io, out, .enter, .{});
    workspacesCheck(out, &failures, split_terminal_focused and self.ui_tree.focusedElement() == null and
        try waitForWorkspaces(self, io, out, .{ .session_text = .{
            .key = second_key,
            .id = split_session,
            .text = "WORKSPACE-ECHO:beta",
        } }), "the focused pane kept an independently addressable terminal session", .{});

    _ = try scratchpadChord(self, io, out, true);
    _ = try postScratchpadText(self, io, out, "stty -echo; ws_scratch=beta; printf 'WORKSPACE-SCRATCH-B:%s\\n' \"$ws_scratch\"");
    _ = try postNamedKey(self, io, out, .enter, .{});
    workspacesCheck(out, &failures, self.activePresentation().scratchpad_presentation == .ninety and
        try waitForWorkspaces(self, io, out, .{ .scratchpad_text = .{
            .key = second_key,
            .text = "WORKSPACE-SCRATCH-B:beta",
        } }), "the second workspace retained different scratch state in its 90 percent layout", .{});
    const second_model = self.workspace_registry.byKey(second_key) orelse return 1;
    const second_scratch_child = (second_model.sessionById(second_model.scratchpadId()) orelse return 1).child() orelse return 1;
    workspacesCheck(out, &failures, first_scratch_child.ptr != second_scratch_child.ptr, "the two scratchpads own different PTY processes", .{});

    const switch_opened = try openWorkspacePaletteCommand(self, io, out, "switchworkspace", workspace_switch_action);
    workspacesCheck(out, &failures, switch_opened and self.palette_step == .input, "the palette opened Switch workspace's exact-name input", .{});
    if (!switch_opened) return 1;
    _ = try postPaletteText(self, io, out, "default");
    _ = try postNamedKey(self, io, out, .enter, .{});
    workspacesCheck(out, &failures, try waitForWorkspaces(self, io, out, .{ .active = first_key }) and
        self.activePresentation().scratchpad_presentation == .fifty and
        (self.activeWorkspace().sessionById(first_session) orelse return 1).child().?.ptr == first_terminal_child.ptr and
        (self.scratchpadLive() orelse return 1).child().?.ptr == first_scratch_child.ptr and
        try waitForWorkspaces(self, io, out, .{ .scratchpad_text = .{
            .key = first_key,
            .text = "WORKSPACE-SCRATCH-A:alpha",
        } }), "palette switching restored the first terminal and its same 50 percent scratchpad", .{});

    _ = try scratchpadChord(self, io, out, false);
    const duplicate_opened = try clickPaletteCommand(self, io, out, workspace_create_action, null);
    workspacesCheck(out, &failures, duplicate_opened and self.palette_step == .input, "the clickable sidebar Create workspace control opened its input", .{});
    if (!duplicate_opened) return 1;
    _ = try postPaletteText(self, io, out, "/tmp/");
    _ = try postNamedKey(self, io, out, .enter, .{});
    workspacesCheck(out, &failures, try waitForWorkspaces(self, io, out, .{ .active = second_key }) and
        self.workspace_registry.count() == 2 and self.activePresentation().scratchpad_presentation == .ninety and
        self.activeWorkspace().tab(second_tab_id).?.paneCount() == 2 and
        self.activeWorkspace().focusedPaneId(second_tab_id) == split_pane and
        self.activePresentation().active_session_id == split_session and
        (self.activeLive().child() orelse return 1).ptr == split_child.ptr, "creating an already-open cwd activated it without duplication and restored its pane layout", .{});
    _ = try scratchpadChord(self, io, out, true);

    const rename_opened = try clickPaletteCommand(self, io, out, workspace_rename_action, null);
    workspacesCheck(out, &failures, rename_opened and self.palette_step == .input, "the clickable sidebar Rename workspace control opened its input", .{});
    if (!rename_opened) return 1;
    _ = try postPaletteText(self, io, out, "secondary");
    _ = try postNamedKey(self, io, out, .enter, .{});
    workspacesCheck(out, &failures, self.workspace_registry.keyForName("secondary") == second_key, "sidebar rename committed the trimmed unique display name", .{});

    const palette_rename_opened = try openWorkspacePaletteCommand(self, io, out, "renameworkspace", workspace_rename_action);
    workspacesCheck(out, &failures, palette_rename_opened and self.palette_step == .input, "the palette exposed the same Rename workspace action", .{});
    if (!palette_rename_opened) return 1;
    _ = try postPaletteText(self, io, out, "renamed");
    _ = try postNamedKey(self, io, out, .enter, .{});
    workspacesCheck(out, &failures, self.workspace_registry.keyForName("renamed") == second_key, "palette rename updated the same stable workspace key", .{});

    const sidebar_switch_opened = try clickPaletteCommand(self, io, out, workspace_switch_action, null);
    workspacesCheck(out, &failures, sidebar_switch_opened and self.palette_step == .input, "the clickable sidebar Switch workspace control opened its input", .{});
    if (!sidebar_switch_opened) return 1;
    _ = try postPaletteText(self, io, out, "default");
    _ = try postNamedKey(self, io, out, .enter, .{});
    workspacesCheck(out, &failures, try waitForWorkspaces(self, io, out, .{ .active = first_key }), "the sidebar switch control selected an exact workspace name", .{});

    var second_workspace_id_buffer: [workspace_semantic_capacity]u8 = undefined;
    const second_workspace_id = try workspaceSemanticId(&second_workspace_id_buffer, second_key);
    var first_workspace_id_buffer: [workspace_semantic_capacity]u8 = undefined;
    const first_workspace_id = try workspaceSemanticId(&first_workspace_id_buffer, first_key);
    workspacesCheck(out, &failures, try clickTabsElement(self, io, out, second_workspace_id) and
        self.workspace_registry.activeKey().? == second_key, "clicking the namespaced workspace row switched immediately", .{});

    const sidebar_focus_mods: platform.Mods = switch (self.binding_profile) {
        .macos => .{ .shift = true, .super = true },
        .linux_windows => .{ .ctrl = true, .shift = true },
    };
    _ = try postNamedKey(self, io, out, .down, sidebar_focus_mods);
    _ = try postNamedKey(self, io, out, .up, .{});
    _ = try postNamedKey(self, io, out, .enter, .{});
    workspacesCheck(out, &failures, self.workspace_registry.activeKey().? == first_key, "sidebar focus, Up and Enter switched by keyboard", .{});
    _ = try postNamedKey(self, io, out, .down, sidebar_focus_mods);
    _ = try postNamedKey(self, io, out, .down, .{});
    _ = try postNamedKey(self, io, out, .enter, .{});
    workspacesCheck(out, &failures, self.workspace_registry.activeKey().? == second_key and
        self.activeWorkspace().tab(second_tab_id).?.paneCount() == 2 and
        self.activeWorkspace().focusedPaneId(second_tab_id) == split_pane, "Down and Enter returned to the same focused two-pane layout", .{});

    // TASK-77: the second workspace's rows sit a scaled 5 logical pixels
    // below the cell grid; its tabs keep their ordinary spacing.
    try self.drawFrame();
    const geometry = self.uiGeometry();
    const gap_px = geometry.offsetPx(sidebar_workspace_gap_px);
    const row_px: i32 = @intCast(self.fonts.metrics().cell.height_px);
    var gap_tab_storage: [workspace_semantic_capacity]u8 = undefined;
    const gap_tab_id = try tabSemanticId(&gap_tab_storage, second_key, second_tab_id);
    const first_row = self.ui_tree.byId(.{ .value = first_workspace_id });
    const second_row = self.ui_tree.byId(.{ .value = second_workspace_id });
    const gap_tab_row = self.ui_tree.byId(.{ .value = gap_tab_id });
    workspacesCheck(out, &failures, gap_px > 0 and first_row != null and second_row != null and gap_tab_row != null and
        first_row.?.bounds.y == row_px and
        second_row.?.bounds.y == first_row.?.bounds.y + row_px + gap_px and
        @mod(second_row.?.bounds.y, row_px) == gap_px and
        gap_tab_row.?.bounds.y == second_row.?.bounds.y + row_px, "semantic bounds put a {d} px gap above the second workspace and none between its rows", .{gap_px});
    // A press in the gap lands on no row.
    const scale = self.window.state.scale.factor;
    const gap_x = @as(f32, @floatFromInt(second_row.?.bounds.x + 2)) / scale;
    const gap_y = @as(f32, @floatFromInt(second_row.?.bounds.y - 1)) / scale;
    _ = try postButton(self, io, out, .{ .button = .left, .action = .press, .x = gap_x, .y = gap_y });
    _ = try postButton(self, io, out, .{ .button = .left, .action = .release, .x = gap_x, .y = gap_y });
    workspacesCheck(out, &failures, self.workspace_registry.activeKey().? == second_key and
        self.ui_tree.focusedElement() == null, "a real click in the gap activated nothing", .{});

    const gap_create_mods: platform.Mods = switch (self.binding_profile) {
        .macos => .{ .super = true },
        .linux_windows => .{ .ctrl = true, .shift = true },
    };
    _ = try postKey(self, io, out, 't', gap_create_mods);
    const gap_new_tab = self.activeWorkspace().activeTabId() orelse return 1;
    const gap_new_session = self.activePresentation().active_session_id;
    workspacesCheck(out, &failures, try waitForWorkspaces(self, io, out, .{ .session_text = .{
        .key = second_key,
        .id = gap_new_session,
        .text = "WORKSPACE-PTY-READY:",
    } }), "the extra tab in the shifted workspace started its real PTY", .{});
    var gap_new_storage: [workspace_semantic_capacity]u8 = undefined;
    const gap_new_id = try tabSemanticId(&gap_new_storage, second_key, gap_new_tab);
    try self.drawFrame();
    const gap_new_row = self.ui_tree.byId(.{ .value = gap_new_id });
    workspacesCheck(out, &failures, gap_new_tab != second_tab_id and gap_new_row != null and
        gap_new_row.?.bounds.y == (self.ui_tree.byId(.{ .value = gap_tab_id }) orelse return 1).bounds.y + row_px, "a new tab in the shifted workspace kept ordinary tab spacing", .{});
    workspacesCheck(out, &failures, try dragTabs(self, io, out, gap_new_id, gap_tab_id) and
        self.activeWorkspace().tabAt(0).?.id() == gap_new_tab, "a real pointer drag reordered shifted tab rows", .{});
    try self.drawFrame();
    // The lowest device pixels of the original tab's row belong to the next
    // grid row without the shift, so this press proves hit testing shifted.
    const original_row = self.ui_tree.byId(.{ .value = gap_tab_id }) orelse return 1;
    const bottom_x = @as(f32, @floatFromInt(original_row.bounds.x + 4)) / scale;
    const bottom_y = @as(f32, @floatFromInt(original_row.bounds.y + @as(i32, @intCast(original_row.bounds.height)) - 2)) / scale;
    _ = try postButton(self, io, out, .{ .button = .left, .action = .press, .x = bottom_x, .y = bottom_y });
    _ = try postButton(self, io, out, .{ .button = .left, .action = .release, .x = bottom_x, .y = bottom_y });
    workspacesCheck(out, &failures, self.activeWorkspace().activeTabId() == second_tab_id and
        self.activePresentation().active_session_id == split_session, "a click at the bottom edge of a shifted tab selected that tab", .{});
    // Keyboard focus walks the shifted rows like any others: the focus chord
    // enters on the shifted workspace row, and Tab moves through its tabs.
    _ = try postNamedKey(self, io, out, .down, sidebar_focus_mods);
    const focused_after_entry = self.ui_tree.focusedElement();
    workspacesCheck(out, &failures, focused_after_entry != null and std.mem.eql(u8, focused_after_entry.?.id.value, second_workspace_id), "sidebar focus entered on the shifted workspace row", .{});
    _ = try postNamedKey(self, io, out, .tab, .{});
    _ = try postNamedKey(self, io, out, .enter, .{});
    workspacesCheck(out, &failures, self.activeWorkspace().activeTabId() == gap_new_tab, "Tab and Enter selected the first shifted tab", .{});
    _ = try postNamedKey(self, io, out, .down, sidebar_focus_mods);
    _ = try postNamedKey(self, io, out, .tab, .{});
    _ = try postNamedKey(self, io, out, .tab, .{});
    _ = try postNamedKey(self, io, out, .enter, .{});
    workspacesCheck(out, &failures, self.activeWorkspace().activeTabId() == second_tab_id and
        self.activePresentation().active_session_id == split_session, "Tab, Tab and Enter returned to the original shifted tab", .{});
    // Close the extra tab again so the rest of the check sees the layout it
    // built: activate it, close it, and confirm the running child's close.
    workspacesCheck(out, &failures, try clickTabsElement(self, io, out, gap_new_id) and
        self.activeWorkspace().activeTabId() == gap_new_tab, "clicking the shifted extra tab selected it", .{});
    _ = try postKey(self, io, out, 'w', gap_create_mods);
    try self.drawFrame();
    workspacesCheck(out, &failures, try clickTabsElement(self, io, out, "tab-close.confirm") and
        try waitForWorkspaces(self, io, out, .{ .active = second_key }) and
        self.activeWorkspace().tab(gap_new_tab) == null and
        self.activeWorkspace().sessionById(gap_new_session) == null and
        self.activeWorkspace().activeTabId() == second_tab_id and
        self.activePresentation().active_session_id == split_session, "confirming close removed the extra tab and its session and restored the two-pane tab", .{});

    _ = try scratchpadChord(self, io, out, true);
    workspacesCheck(out, &failures, self.activePresentation().scratchpad_presentation == .ninety and
        try waitForWorkspaces(self, io, out, .{ .scratchpad_text = .{
            .key = second_key,
            .text = "WORKSPACE-SCRATCH-B:beta",
        } }), "the renamed workspace still presented its original 90 percent scratchpad", .{});
    const close_opened = try openWorkspacePaletteCommand(self, io, out, "closeworkspace", workspace_close_action);
    workspacesCheck(out, &failures, close_opened and self.pending_close_workspace == second_key and
        self.ui_tree.byId(.{ .value = "workspace-close.dialog" }) != null, "the palette opened the workspace-level close confirmation", .{});
    if (!close_opened) return 1;

    try self.drawFrame();
    var second_scratchpad_id_buffer: [workspace_semantic_capacity]u8 = undefined;
    const second_scratchpad_id = try scratchpadSemanticId(&second_scratchpad_id_buffer, second_key, "");
    workspacesCheck(out, &failures, self.ui_tree.byId(.{ .value = first_workspace_id }) != null and
        self.ui_tree.byId(.{ .value = second_workspace_id }) != null and
        self.ui_tree.byId(.{ .value = second_scratchpad_id }) != null and
        self.ui_tree.byId(.{ .value = "workspace-close.dialog" }) != null, "the semantic checkpoint contains both workspace rows, the active scratchpad and close modal", .{});
    const screenshot_pixels = try self.allocator.dupe(u8, try self.capture());
    defer self.allocator.free(screenshot_pixels);
    var screenshot_path_buffer: [path_capacity]u8 = undefined;
    const screenshot_path = try workspacesScreenshotPath(io, &screenshot_path_buffer);

    _ = try postNamedKey(self, io, out, .escape, .{});
    workspacesCheck(out, &failures, self.pending_close_workspace == null and self.scratchpadVisible(), "Escape cancelled palette close without hiding the scratchpad", .{});
    _ = try postScratchpadText(self, io, out, "printf 'WORKSPACE-SCRATCH-B-CLOSE:%s\\n' \"$ws_scratch\"");
    _ = try postNamedKey(self, io, out, .enter, .{});
    workspacesCheck(out, &failures, try waitForWorkspaces(self, io, out, .{ .scratchpad_text = .{
        .key = second_key,
        .text = "WORKSPACE-SCRATCH-B-CLOSE:beta",
    } }), "the second scratchpad drained its final output before close", .{});
    _ = try scratchpadChord(self, io, out, true);
    _ = try postWorkspaceTerminalText(self, io, out, "closing");
    _ = try postNamedKey(self, io, out, .enter, .{});
    workspacesCheck(out, &failures, try waitForWorkspaces(self, io, out, .{ .session_text = .{
        .key = second_key,
        .id = split_session,
        .text = "WORKSPACE-ECHO:closing",
    } }) and try waitForWorkspaces(self, io, out, .{ .settled = second_key }), "all terminal and scratchpad output was quiescent before teardown", .{});
    // Session ids are never reused, so the TASK-77 extra tab closed above
    // keeps its released record: four records, three of them live.
    workspacesCheck(out, &failures, second_model.registeredSessionCount() == 4 and
        second_model.sessionById(gap_new_session) == null and second_model.hasAttachedChild(), "the close target still owned two terminals and one scratchpad PTY", .{});

    _ = try clickPaletteCommand(self, io, out, workspace_close_action, null);
    workspacesCheck(out, &failures, self.pending_close_workspace == second_key, "the clickable sidebar Close workspace control opened confirmation", .{});
    _ = try clickTabsElement(self, io, out, "workspace-close.cancel");
    workspacesCheck(out, &failures, self.pending_close_workspace == null and self.workspace_registry.byKey(second_key) != null, "pointer cancel retained every workspace process", .{});
    _ = try clickPaletteCommand(self, io, out, workspace_close_action, null);
    _ = try clickTabsElement(self, io, out, "workspace-close.confirm");
    workspacesCheck(out, &failures, try waitForWorkspaces(self, io, out, .{ .removed = second_key }) and
        self.workspace_registry.count() == 1 and self.workspace_registry.activeKey().? == first_key and
        self.ui_tree.byId(.{ .value = second_workspace_id }) == null, "pointer confirmation terminated and removed all three PTY sessions, then selected the neighbour", .{});

    const first_tab_id = first_model.activeTabId() orelse return 1;
    const first_pane = first_model.focusedPaneId(first_tab_id) orelse return 1;
    var first_pane_id_buffer: [pane_semantic_capacity]u8 = undefined;
    const first_pane_id = try paneSemanticId(&first_pane_id_buffer, first_key, first_pane);
    const first_terminal_focused = try clickTabsElement(self, io, out, first_pane_id);
    _ = try postWorkspaceTerminalText(self, io, out, "after-close");
    _ = try postNamedKey(self, io, out, .enter, .{});
    workspacesCheck(out, &failures, first_terminal_focused and self.ui_tree.focusedElement() == null and
        try waitForWorkspaces(self, io, out, .{ .session_text = .{
            .key = first_key,
            .id = first_session,
            .text = "WORKSPACE-ECHO:after-close",
        } }) and (self.activeLive().child() orelse return 1).ptr == first_terminal_child.ptr, "closing the neighbour left the first terminal process and input route intact", .{});
    _ = try scratchpadChord(self, io, out, false);
    _ = try postScratchpadText(self, io, out, "printf 'WORKSPACE-SCRATCH-A-FINAL:%s\\n' \"$ws_scratch\"");
    _ = try postNamedKey(self, io, out, .enter, .{});
    workspacesCheck(out, &failures, try waitForWorkspaces(self, io, out, .{ .scratchpad_text = .{
        .key = first_key,
        .text = "WORKSPACE-SCRATCH-A-FINAL:alpha",
    } }) and (self.scratchpadLive() orelse return 1).child().?.ptr == first_scratch_child.ptr, "the surviving workspace kept its independent scratch shell state", .{});

    try writePngOffThread(self.allocator, io, screenshot_path, screenshot_pixels, self.size);
    out.print("workspaces-test: screenshot {s}\n", .{screenshot_path}) catch {};
    out.print("workspaces-test: {d} failure(s)\n", .{failures}) catch {};
    out.flush() catch {};
    return if (failures == 0) 0 else 1;
}

const links_test_lexical_url = "https://lexical.test/path";
const links_test_osc_url = "https://osc-target.test/open";
/// The tracked cwd the child claims with OSC 7. It must exist locally because
/// the real editor spawn uses it, and the relative reference resolves there.
const links_test_cwd = "/tmp";
const links_test_relative_file = "./conduit-notes.txt:3";
const links_test_absolute_file = "/tmp/conduit-abs.txt";
const links_test_script =
    "stty -echo; " ++
    "printf '\x1b[2J\x1b[H\x1b]7;file://localhost" ++ links_test_cwd ++ "\x07plain " ++ links_test_lexical_url ++ "\r\n" ++
    "\x1b]8;;" ++ links_test_osc_url ++ "\x07OSC-LABEL\x1b]8;;\x07\r\n" ++
    "\x1b]8;;https://bad.\xff\x07https://masked.test\x1b]8;;\x07\r\n" ++
    "open " ++ links_test_relative_file ++ " or " ++ links_test_absolute_file ++ "\r\n" ++
    "\x1b[?1006;1000h'; " ++
    "while :; do sleep 60; done";

/// Records every editor spawn the app produced, with argv entries joined by a
/// single space; the fixture's paths contain none, so the join is exact.
const EditorSpawnTrace = struct {
    argv_bytes: [file_reference_path_max_bytes + 64]u8 = undefined,
    argv_len: usize = 0,
    argv_count: usize = 0,
    cwd_bytes: [file_reference_path_max_bytes]u8 = undefined,
    cwd_len: usize = 0,
    calls: usize = 0,

    fn argv(self: *const EditorSpawnTrace) []const u8 {
        return self.argv_bytes[0..self.argv_len];
    }

    fn cwd(self: *const EditorSpawnTrace) []const u8 {
        return self.cwd_bytes[0..self.cwd_len];
    }
};

fn recordEditorSpawn(context: ?*anyopaque, argv: []const []const u8, cwd: []const u8) void {
    const trace: *EditorSpawnTrace = @ptrCast(@alignCast(context orelse return));
    trace.calls += 1;
    trace.argv_count = argv.len;
    var writer = std.Io.Writer.fixed(&trace.argv_bytes);
    for (argv, 0..) |entry, index| {
        if (index != 0) writer.writeByte(' ') catch break;
        writer.writeAll(entry) catch break;
    }
    trace.argv_len = writer.end;
    trace.cwd_len = @min(cwd.len, trace.cwd_bytes.len);
    @memcpy(trace.cwd_bytes[0..trace.cwd_len], cwd[0..trace.cwd_len]);
}

const UrlOpenTrace = struct {
    bytes: [link.default_max_target_bytes]u8 = undefined,
    len: usize = 0,
    calls: usize = 0,

    fn value(self: *const UrlOpenTrace) []const u8 {
        return self.bytes[0..self.len];
    }
};

const TerminalLinkTestPoint = struct {
    x: f32,
    y: f32,
};

fn recordOpenedUrl(context: ?*anyopaque, _: Allocator, url: []const u8) !void {
    const trace: *UrlOpenTrace = @ptrCast(@alignCast(context orelse return error.MissingTrace));
    if (url.len > trace.bytes.len) return error.UrlTooLong;
    @memcpy(trace.bytes[0..url.len], url);
    trace.len = url.len;
    trace.calls += 1;
}

fn terminalLinkByLabel(self: *const App, label: []const u8) ?*const ui.Element {
    for (self.ui_tree.elements()) |*element| {
        if (std.mem.eql(u8, element.role, "terminal_link") and
            std.mem.eql(u8, element.label, label)) return element;
    }
    return null;
}

fn terminalLinkPoint(self: *const App, element: *const ui.Element) ?TerminalLinkTestPoint {
    if (element.bounds.isEmpty() or element.bounds.x < 0 or element.bounds.y < 0) return null;
    const scale = self.window.state.scale.factor;
    return .{
        .x = (@as(f32, @floatFromInt(element.bounds.x)) +
            @as(f32, @floatFromInt(element.bounds.width)) / 2) / scale,
        .y = (@as(f32, @floatFromInt(element.bounds.y)) +
            @as(f32, @floatFromInt(element.bounds.height)) / 2) / scale,
    };
}

fn waitForTerminalLinks(self: *App, io: Io, out: *Writer) !bool {
    const deadline = Io.Clock.real.now(io).nanoseconds + 5000 * std.time.ns_per_ms;
    while (true) {
        if (self.scheduler.shouldDraw()) try self.drawFrame();
        if (terminalLinkByLabel(self, links_test_lexical_url) != null and
            terminalLinkByLabel(self, "OSC-LABEL") != null and
            terminalLinkByLabel(self, links_test_relative_file) != null and
            terminalLinkByLabel(self, links_test_absolute_file) != null) return true;
        const event = self.window.pump(@min(self.waitBudget(io, deadline), 50));
        if (event) |one| {
            describeEvent(out, one) catch {};
            if (!try self.handle(one)) return false;
        }
        if (self.poll()) self.scheduler.invalidate();
        if (Io.Clock.real.now(io).nanoseconds >= deadline) return false;
    }
}

/// Pump real events and worker results until the active terminal shows
/// `needle`, so an asynchronously spawned editor proves itself on screen.
fn waitForActiveTerminalText(self: *App, io: Io, out: *Writer, needle: []const u8) !bool {
    const deadline = Io.Clock.real.now(io).nanoseconds + 5000 * std.time.ns_per_ms;
    while (true) {
        if (self.scheduler.shouldDraw()) try self.drawFrame();
        if (self.activeLive().terminal().visibleTextContains(needle)) return true;
        const event = self.window.pump(@min(self.waitBudget(io, deadline), 50));
        if (event) |one| {
            describeEvent(out, one) catch {};
            if (!try self.handle(one)) return false;
        }
        if (self.poll()) self.scheduler.invalidate();
        if (Io.Clock.real.now(io).nanoseconds >= deadline) return false;
    }
}

fn linkTestCheck(out: *Writer, failures: *usize, ok: bool, comptime format: []const u8, args: anytype) void {
    out.print("links-test: {s} " ++ format ++ "\n", .{if (ok) "ok  " else "FAIL"} ++ args) catch {};
    if (!ok) failures.* += 1;
}

fn postTerminalLinkClick(
    self: *App,
    io: Io,
    out: *Writer,
    point: TerminalLinkTestPoint,
    mods: platform.Mods,
) !bool {
    try self.window.postPointerButton(.{ .button = .left, .action = .press, .mods = mods, .x = point.x, .y = point.y });
    try self.window.postPointerButton(.{ .button = .left, .action = .release, .mods = mods, .x = point.x, .y = point.y });
    if (!try pumpUntil(self, io, out, .pointer_button, self_test_event_budget_ms)) return false;
    return pumpUntil(self, io, out, .pointer_button, self_test_event_budget_ms);
}

/// Drive production link composition and routing through SDL while replacing
/// only the final desktop handoff with an in-process recorder.
fn linksTest(self: *App, io: Io, out: *Writer) !u8 {
    var failures: usize = 0;
    var child_trace: ClipboardTrace = .{};
    defer child_trace.deinit(self.allocator);
    self.trace = &child_trace;
    defer self.trace = null;
    var opener_trace: UrlOpenTrace = .{};
    self.url_opener = .{ .context = &opener_trace, .open_fn = recordOpenedUrl };
    defer self.url_opener = .{};
    var editor_trace: EditorSpawnTrace = .{};
    self.editor_spawn_observer = .{ .context = &editor_trace, .observe_fn = recordEditorSpawn };
    defer self.editor_spawn_observer = .{};

    const ready = try waitForTerminalLinks(self, io, out);
    linkTestCheck(out, &failures, ready, "lexical and OSC 8 links reached the semantic tree", .{});
    if (!ready) return 1;
    linkTestCheck(out, &failures, terminalLinkByLabel(self, "https://masked.test") == null, "invalid UTF-8 OSC 8 metadata masked its URL-looking label", .{});

    const lexical = terminalLinkByLabel(self, links_test_lexical_url) orelse return 1;
    const lexical_point = terminalLinkPoint(self, lexical) orelse return 1;
    const sent_before_plain = child_trace.sent.items.len;
    const plain_delivered = try postTerminalLinkClick(self, io, out, lexical_point, .{});
    linkTestCheck(out, &failures, plain_delivered and child_trace.sent.items.len > sent_before_plain and
        opener_trace.calls == 0, "plain click remained a DEC mouse gesture and did not open the link", .{});

    const native_mods: platform.Mods = switch (self.binding_profile) {
        .macos => .{ .super = true },
        .linux_windows => .{ .ctrl = true },
    };
    try self.window.postPointerMotion(.{ .mods = native_mods, .x = lexical_point.x, .y = lexical_point.y });
    const hover_delivered = try pumpUntil(self, io, out, .pointer_motion, self_test_event_budget_ms);
    if (self.scheduler.shouldDraw()) try self.drawFrame();
    const hovered = terminalLinkByLabel(self, links_test_lexical_url);
    const underline_visible = if (hovered) |element| blk: {
        const cell = self.fonts.metrics().cell;
        const col: u32 = @intCast(@divFloor(element.bounds.x, @as(i32, @intCast(cell.width_px))));
        const row: u32 = @intCast(@divFloor(element.bounds.y, @as(i32, @intCast(cell.height_px))));
        const painted = overlayCellAt(self.overlayView(), .{ .col = col, .row = row });
        break :blk painted != null and painted.?.underline != null;
    } else false;
    linkTestCheck(out, &failures, hover_delivered and underline_visible, "native-modifier hover painted a decoration-only underline", .{});

    const sent_before_lexical = child_trace.sent.items.len;
    const lexical_opened = try postTerminalLinkClick(self, io, out, lexical_point, native_mods);
    linkTestCheck(out, &failures, lexical_opened and opener_trace.calls == 1 and
        std.mem.eql(u8, opener_trace.value(), links_test_lexical_url) and
        child_trace.sent.items.len == sent_before_lexical, "modified lexical URL click opened the exact target without a DEC report", .{});

    const osc = terminalLinkByLabel(self, "OSC-LABEL") orelse return 1;
    const osc_point = terminalLinkPoint(self, osc) orelse return 1;
    const sent_before_osc = child_trace.sent.items.len;
    const osc_opened = try postTerminalLinkClick(self, io, out, osc_point, native_mods);
    linkTestCheck(out, &failures, osc_opened and opener_trace.calls == 2 and
        std.mem.eql(u8, opener_trace.value(), links_test_osc_url) and
        child_trace.sent.items.len == sent_before_osc, "OSC 8 label opened its explicit target instead of its visible text", .{});

    // File references (decision-5): stable ids, plain-click isolation, then a
    // modified click that opens the resolved path in a new tab through vi.
    const relative = terminalLinkByLabel(self, links_test_relative_file) orelse return 1;
    var relative_id_storage: [terminal_link_semantic_capacity]u8 = undefined;
    @memcpy(relative_id_storage[0..relative.id.value.len], relative.id.value);
    const relative_id = relative_id_storage[0..relative.id.value.len];
    const relative_fingerprint = std.fmt.bytesToHex(terminalLinkFingerprint(.file, "./conduit-notes.txt", 3, null), .lower);
    const absolute_fingerprint = std.fmt.bytesToHex(terminalLinkFingerprint(.file, links_test_absolute_file, null, null), .lower);
    const absolute = terminalLinkByLabel(self, links_test_absolute_file) orelse return 1;
    linkTestCheck(out, &failures, std.mem.indexOf(u8, relative_id, &relative_fingerprint) != null and
        std.mem.indexOf(u8, absolute.id.value, &absolute_fingerprint) != null and
        std.mem.indexOf(u8, relative_id, ".terminal-link.3.") != null, "file references carry domain-separated path/line/column ids", .{});
    try self.composeUi();
    const recomposed = terminalLinkByLabel(self, links_test_relative_file) orelse return 1;
    linkTestCheck(out, &failures, std.mem.eql(u8, recomposed.id.value, relative_id), "file reference ids are stable across frames", .{});

    const relative_point = terminalLinkPoint(self, recomposed) orelse return 1;
    const tabs_before = self.activeWorkspace().tabCount();
    const sent_before_file_plain = child_trace.sent.items.len;
    const file_plain_delivered = try postTerminalLinkClick(self, io, out, relative_point, .{});
    linkTestCheck(out, &failures, file_plain_delivered and child_trace.sent.items.len > sent_before_file_plain and
        editor_trace.calls == 0 and self.activeWorkspace().tabCount() == tabs_before, "plain click on a file reference stayed a DEC mouse gesture and opened no tab", .{});

    const sent_before_file = child_trace.sent.items.len;
    const file_opened = try postTerminalLinkClick(self, io, out, relative_point, native_mods);
    const expected_relative_argv = "vi +3 -- " ++ links_test_cwd ++ "/conduit-notes.txt";
    linkTestCheck(out, &failures, file_opened and editor_trace.calls == 1 and editor_trace.argv_count == 4 and
        std.mem.eql(u8, editor_trace.argv(), expected_relative_argv) and
        std.mem.eql(u8, editor_trace.cwd(), links_test_cwd) and
        child_trace.sent.items.len == sent_before_file, "modified click spawned exactly `{s}` in the tracked cwd", .{expected_relative_argv});
    // This fixture disables the sidebar to keep link geometry fixed, so the
    // sidebar row itself is proven by the scripted `terminal-file-reference`
    // scenario; here the workspace model carries the selected, labelled tab.
    const new_tab_active = self.activeWorkspace().tabCount() == tabs_before + 1 and
        self.activeWorkspace().activeTabId() != null and
        std.mem.eql(u8, self.activeWorkspace().tab(self.activeWorkspace().activeTabId().?).?.name(), "conduit-notes.txt");
    linkTestCheck(out, &failures, new_tab_active, "the new tab is selected and labelled with the file name", .{});
    // vim reports the exact path it was given in its status line, which only
    // the new active tab can show; the first tab never printed that spelling.
    const editor_drew = try waitForActiveTerminalText(self, io, out, links_test_cwd ++ "/conduit-notes.txt");
    linkTestCheck(out, &failures, editor_drew, "the real editor child drew the resolved path in the new tab", .{});

    const switched_back = switch (self.binding_profile) {
        .macos => try postKey(self, io, out, '[', .{ .super = true, .shift = true }),
        .linux_windows => try postNamedKey(self, io, out, .page_up, .{ .ctrl = true }),
    };
    const links_back = switched_back and try waitForTerminalLinks(self, io, out);
    linkTestCheck(out, &failures, links_back, "the keyboard tab chord returned to the source terminal and its links", .{});
    if (!links_back) return 1;
    const absolute_again = terminalLinkByLabel(self, links_test_absolute_file) orelse return 1;
    const absolute_point = terminalLinkPoint(self, absolute_again) orelse return 1;
    const absolute_opened = try postTerminalLinkClick(self, io, out, absolute_point, native_mods);
    const expected_absolute_argv = "vi -- " ++ links_test_absolute_file;
    linkTestCheck(out, &failures, absolute_opened and editor_trace.calls == 2 and editor_trace.argv_count == 3 and
        std.mem.eql(u8, editor_trace.argv(), expected_absolute_argv) and
        std.mem.eql(u8, editor_trace.cwd(), links_test_cwd) and
        self.activeWorkspace().tabCount() == tabs_before + 2, "an absolute reference without a line spawned exactly `{s}`", .{expected_absolute_argv});
    const absolute_drew = try waitForActiveTerminalText(self, io, out, links_test_absolute_file);
    linkTestCheck(out, &failures, absolute_drew, "the second editor tab drew its absolute path", .{});

    try self.drawFrame();
    _ = try self.capture();
    out.print("links-test: {d} failure(s)\n", .{failures}) catch {};
    out.flush() catch {};
    return if (failures == 0) 0 else 1;
}

/// A deterministic scrollback fixture: mixed-case visible matches, one match
/// older than the viewport, and a child that remains attached while search is
/// driven through SDL.
const search_test_script =
    "stty -echo; " ++
    "i=0; while [ \"$i\" -lt 140 ]; do printf 'pagehit-%03d\\r\\n' \"$i\"; i=$((i+1)); done; " ++
    "printf 'Needle OLD\\r\\n'; " ++
    "i=0; while [ \"$i\" -lt 48 ]; do printf 'fill-%02d\\r\\n' \"$i\"; i=$((i+1)); done; " ++
    "printf 'Needle NEW\\r\\nneedle exact\\r\\nSEARCH-READY\\r\\n'; " ++
    "while IFS= read -r line; do " ++
    "if [ \"$line\" = stream ]; then " ++
    "i=0; while [ \"$i\" -lt 512 ]; do printf 'noise-%04d\\r\\n' \"$i\"; i=$((i+1)); done; " ++
    "printf 'needle OUTPUT\\r\\n'; " ++
    "elif [ \"$line\" = regexstream ]; then " ++
    "i=0; while [ \"$i\" -lt 512 ]; do printf 'regex-noise-%03d\\r\\n' \"$i\"; i=$((i+1)); done; " ++
    "printf 'pagehit-140\\r\\n'; " ++
    "else printf 'SEARCH-ECHO:%s\\r\\n' \"$line\"; fi; done";

const search_test_budget_ms: i64 = 7500;

const SearchWait = union(enum) {
    terminal_text: []const u8,
    complete: usize,
    element: []const u8,
    active_candidate: usize,
    page_scan,
    settled,
};

fn searchWaitMet(self: *App, condition: SearchWait) bool {
    return switch (condition) {
        .terminal_text => |text| self.activeLive().terminal().visibleTextContains(text),
        .complete => |minimum| self.search_visible and self.search_failure == null and
            searchVisibleProgress(self.search_progress, self.search_page_scan != null) == .complete and
            self.search_match_count >= minimum,
        .element => |id| self.ui_tree.byId(.{ .value = id }) != null,
        .active_candidate => |candidate| self.search_page_scan == null and
            self.search_match_count != 0 and
            self.search_pages[self.search_page_slot][self.search_active_index].candidate_index == candidate,
        .page_scan => self.search_engine_live and self.search_progress == .complete and
            self.search_page_scan != null,
        .settled => self.search_engine_live and self.search_page_scan == null,
    };
}

fn waitForSearch(self: *App, io: Io, out: *Writer, condition: SearchWait) !bool {
    const deadline = Io.Clock.real.now(io).nanoseconds + search_test_budget_ms * std.time.ns_per_ms;
    while (true) {
        if (searchWaitMet(self, condition)) return true;
        const event = self.window.pump(if (self.searchNeedsWork())
            0
        else
            @min(self.waitBudget(io, deadline), 50));
        if (event) |one| {
            describeEvent(out, one) catch {};
            if (!try self.handle(one)) return false;
        }
        if (self.poll()) self.scheduler.invalidate();
        if (self.scheduler.shouldDraw()) try self.drawFrame();
        if (Io.Clock.real.now(io).nanoseconds >= deadline) return searchWaitMet(self, condition);
    }
}

fn searchCheck(out: *Writer, failures: *usize, ok: bool, comptime format: []const u8, args: anytype) void {
    out.print("search-test: {s} " ++ format ++ "\n", .{if (ok) "ok  " else "FAIL"} ++ args) catch {};
    if (!ok) failures.* += 1;
}

fn searchHighlightCount(self: *const App) usize {
    var count: usize = 0;
    for (self.ui_tree.elements()) |element| {
        if (std.mem.eql(u8, element.role, "search_match")) count += 1;
    }
    return count;
}

fn activeSearchHighlightVisible(self: *const App) bool {
    for (self.ui_tree.elements()) |element| {
        if (std.mem.eql(u8, element.role, "search_match") and element.state.selected) return true;
    }
    return false;
}

fn searchStatusContains(self: *const App, text: []const u8) bool {
    const status = self.ui_tree.byId(.{ .value = "search.status" }) orelse return false;
    return std.mem.indexOf(u8, status.label, text) != null;
}

fn clickSearchElement(self: *App, io: Io, out: *Writer, id: []const u8) !bool {
    const element = self.ui_tree.byId(.{ .value = id }) orelse return false;
    const point = elementCenter(element, self.window.state.scale);
    if (!try postButton(self, io, out, .{
        .button = .left,
        .action = .press,
        .x = point.x,
        .y = point.y,
    })) return false;
    return postButton(self, io, out, .{
        .button = .left,
        .action = .release,
        .x = point.x,
        .y = point.y,
    });
}

fn firstVisibleSearchMatchId(self: *const App) ?[]const u8 {
    for (self.ui_tree.elements()) |element| {
        if (std.mem.eql(u8, element.role, "search_match")) return element.id.value;
    }
    return null;
}

/// Exercise TASK-36 through the production action registry, semantic tree,
/// SDL keyboard/text path, full terminal scrollback and shared renderer.
fn searchTest(self: *App, io: Io, out: *Writer) !u8 {
    var failures: usize = 0;
    try self.drawFrame();
    searchCheck(out, &failures, try waitForSearch(self, io, out, .{ .terminal_text = "SEARCH-READY" }), "the real PTY produced the visible fixture", .{});

    const open_mods: platform.Mods = switch (self.binding_profile) {
        .macos => .{ .super = true },
        .linux_windows => .{ .ctrl = true, .shift = true },
    };
    searchCheck(out, &failures, try postKey(self, io, out, 'f', open_mods) and
        try waitForSearch(self, io, out, .{ .element = "search.query" }), "the search keybinding opened the semantic Input", .{});
    searchCheck(out, &failures, self.ui_tree.focusedElement() != null and
        std.mem.eql(u8, self.ui_tree.focusedElement().?.id.value, "search.query"), "the inline query owns text focus", .{});

    try self.window.postTextInput("needle");
    searchCheck(out, &failures, try pumpUntil(self, io, out, .text_input, self_test_event_budget_ms), "query text travelled through SDL", .{});
    searchCheck(out, &failures, try waitForSearch(self, io, out, .{ .complete = 3 }) and
        self.search_match_count == 3, "incremental search found visible and retained off-screen matches", .{});
    searchCheck(out, &failures, searchHighlightCount(self) != 0 and activeSearchHighlightVisible(self), "visible matches and the active match have semantic decorations", .{});

    _ = try postNamedKey(self, io, out, .enter, .{});
    _ = try postNamedKey(self, io, out, .enter, .{});
    const old_offset = self.presentedLive().terminal().viewport().offset;
    searchCheck(out, &failures, self.search_active_index == 2 and old_offset != 0 and
        activeSearchHighlightVisible(self), "Next wrapped through ordered results and followed the off-screen match", .{});
    _ = try postNamedKey(self, io, out, .enter, .{ .shift = true });
    searchCheck(out, &failures, self.search_active_index == 1 and
        self.presentedLive().terminal().viewport().offset < old_offset, "Shift+Enter selected the previous match and followed it toward newer output", .{});

    _ = try postKey(self, io, out, 'c', .{ .alt = true });
    searchCheck(out, &failures, try waitForSearch(self, io, out, .{ .complete = 1 }) and
        self.search_case == .sensitive and self.search_match_count == 1, "the case-toggle keybinding reran an exact-case search", .{});

    const select_all_mods: platform.Mods = switch (self.binding_profile) {
        .macos => .{ .super = true },
        .linux_windows => .{ .ctrl = true },
    };
    _ = try postKey(self, io, out, 'a', select_all_mods);
    try self.window.postTextInput("Needle (OLD|NEW)");
    _ = try pumpUntil(self, io, out, .text_input, self_test_event_budget_ms);
    _ = try postKey(self, io, out, 'r', .{ .alt = true });
    searchCheck(out, &failures, try waitForSearch(self, io, out, .page_scan) and
        searchStatusContains(self, "searching"), "regex page materialization remains visibly running after engine preparation", .{});
    const partial_active = self.search_active_index;
    _ = try postNamedKey(self, io, out, .enter, .{});
    searchCheck(out, &failures, self.search_page_scan != null and
        self.search_active_index == partial_active, "navigation stays gated until the regex page reaches a real boundary", .{});
    searchCheck(out, &failures, try waitForSearch(self, io, out, .{ .complete = 2 }) and
        self.search_mode == .regex and self.search_match_count == 2, "the regex keybinding matched alternation across retained scrollback", .{});

    _ = try postKey(self, io, out, 'a', select_all_mods);
    try self.window.postTextInput("(");
    _ = try pumpUntil(self, io, out, .text_input, self_test_event_budget_ms);
    searchCheck(out, &failures, self.search_mode == .regex and
        !self.search_engine_live and self.search_match_count == 0 and
        std.mem.eql(u8, self.search_failure orelse "", "invalid regex"), "a malformed pattern is visible and non-fatal", .{});

    _ = try postKey(self, io, out, 'a', select_all_mods);
    try self.window.postTextInput("needle");
    _ = try pumpUntil(self, io, out, .text_input, self_test_event_budget_ms);
    searchCheck(out, &failures, try waitForSearch(self, io, out, .{ .complete = 1 }), "a valid regex recovered after the malformed pattern", .{});

    _ = try postKey(self, io, out, 'a', select_all_mods);
    try self.window.postTextInput("pagehit");
    _ = try pumpUntil(self, io, out, .text_input, self_test_event_budget_ms);
    searchCheck(out, &failures, try waitForSearch(self, io, out, .{ .complete = search_match_capacity }) and
        self.search_mode == .regex and self.search_match_count == search_match_capacity, "regex retained a bounded first page from more than 128 matches", .{});
    const regex_newest_row = self.search_pages[self.search_page_slot][self.search_active_index].match.first.row;
    _ = try postNamedKey(self, io, out, .enter, .{ .shift = true });
    const regex_wrapped_oldest = try waitForSearch(self, io, out, .settled) and
        self.search_pages[self.search_page_slot][self.search_active_index].match.first.row < regex_newest_row;
    searchCheck(out, &failures, regex_wrapped_oldest, "regex Previous wrapped from the newest match to the oldest", .{});
    _ = try postNamedKey(self, io, out, .enter, .{});
    searchCheck(out, &failures, try waitForSearch(self, io, out, .settled) and
        self.search_pages[self.search_page_slot][self.search_active_index].match.first.row == regex_newest_row, "regex Next wrapped from the oldest match to the newest", .{});
    for (0..search_match_capacity) |_| _ = try postNamedKey(self, io, out, .enter, .{});
    searchCheck(out, &failures, try waitForSearch(self, io, out, .settled) and
        self.search_match_count < search_match_capacity and
        self.search_pages[self.search_page_slot][self.search_active_index].match.first.row < regex_newest_row, "regex Next crossed the bounded page boundary without rescanning the prefix", .{});
    const regex_second_page_row = self.search_pages[self.search_page_slot][self.search_active_index].match.first.row;
    _ = try postNamedKey(self, io, out, .enter, .{ .shift = true });
    searchCheck(out, &failures, try waitForSearch(self, io, out, .settled) and
        self.search_match_count == search_match_capacity and
        self.search_pages[self.search_page_slot][self.search_active_index].match.first.row > regex_second_page_row, "regex Previous crossed back from the adjacent page in canonical order", .{});

    searchCheck(out, &failures, try clickSearchElement(self, io, out, "search.close") and
        !self.search_visible, "regex search closed before driving new PTY output", .{});
    try self.window.postTextInput("regexstream");
    _ = try pumpUntil(self, io, out, .text_input, self_test_event_budget_ms);
    _ = try postNamedKey(self, io, out, .enter, .{});
    const regex_resync_before = self.search_resync_count;
    _ = try postKey(self, io, out, 'f', open_mods);
    searchCheck(out, &failures, try waitForSearch(self, io, out, .{ .complete = search_match_capacity }) and
        self.search_mode == .regex and self.search_resync_count > regex_resync_before, "real PTY output invalidated and resynchronized the active regex query", .{});

    const original_size = self.window.state.logical;
    const logical_cell = platform.LogicalSize{
        .width = logicalPixels(self.fonts.metrics().cell.width_px, self.window.state.scale),
        .height = logicalPixels(self.fonts.metrics().cell.height_px, self.window.state.scale),
    };
    const compact_size = platform.LogicalSize{
        .width = logical_cell.width *| 20,
        .height = logical_cell.height *| 3,
    };
    const resize_resync_before = self.search_resync_count;
    try self.window.setLogicalSize(compact_size);
    const compact_resized = try pumpUntil(self, io, out, .{ .resize = compact_size }, self_test_event_budget_ms);
    const compact_ready = compact_resized and
        try waitForSearch(self, io, out, .{ .complete = search_match_capacity });
    const compact_layout = self.searchBarLayout();
    const compact_query = self.ui_tree.byId(.{ .value = "search.query" });
    searchCheck(out, &failures, compact_ready and self.search_resync_count > resize_resync_before and
        compact_layout != null and !compact_layout.?.bordered and
        compact_layout.?.query.width != 0 and compact_layout.?.query.height != 0 and
        compact_query != null and !compact_query.?.bounds.isEmpty(), "regex resize invalidation kept a usable compact semantic Input on a sub-42x4 canvas", .{});
    try self.window.setLogicalSize(original_size);
    const restored_size = try pumpUntil(self, io, out, .{ .resize = original_size }, self_test_event_budget_ms);
    searchCheck(out, &failures, restored_size and
        try waitForSearch(self, io, out, .{ .complete = search_match_capacity }), "the regex query resynchronized again after restoring the window", .{});

    _ = try postKey(self, io, out, 'a', select_all_mods);
    try self.window.postTextInput("needle");
    _ = try pumpUntil(self, io, out, .text_input, self_test_event_budget_ms);
    // `needle OUTPUT` is only printed by the later stream step, so a
    // case-sensitive query sees exactly `needle exact` at this point.
    searchCheck(out, &failures, self.search_mode == .regex and self.search_case == .sensitive and
        try waitForSearch(self, io, out, .{ .complete = 1 }), "regex search remained usable after PTY output and resize invalidation", .{});
    searchCheck(out, &failures, try clickSearchElement(self, io, out, "search.regex") and
        self.search_mode == .literal and try waitForSearch(self, io, out, .{ .complete = 1 }), "the clickable regex control dispatched the same toggle", .{});
    searchCheck(out, &failures, try clickSearchElement(self, io, out, "search.case") and
        self.search_case == .ascii_insensitive and try waitForSearch(self, io, out, .{ .complete = 3 }), "the clickable case control reran ASCII-insensitive search", .{});

    // Close by mouse, produce output through real SDL keyboard input and the
    // real PTY peer, then reopen before drawing. The first draw drains the
    // multi-chunk response while a search generation is live, proving the
    // invalidation/resync path without direct terminal.feed or sleeps.
    searchCheck(out, &failures, try clickSearchElement(self, io, out, "search.close") and
        !self.search_visible, "the clickable close control dismissed search", .{});
    try self.window.postTextInput("stream");
    _ = try pumpUntil(self, io, out, .text_input, self_test_event_budget_ms);
    _ = try postNamedKey(self, io, out, .enter, .{});
    const resync_before = self.search_resync_count;
    _ = try postKey(self, io, out, 'f', open_mods);
    searchCheck(out, &failures, try waitForSearch(self, io, out, .{ .complete = 4 }) and
        self.search_match_count == 4 and self.search_resync_count > resync_before, "real user input drove PTY output through bounded generation resync", .{});

    searchCheck(out, &failures, try clickSearchElement(self, io, out, "search.next") and
        self.search_active_index == 1, "the clickable next control dispatched navigation", .{});
    searchCheck(out, &failures, try clickSearchElement(self, io, out, "search.previous") and
        self.search_active_index == 0, "the clickable previous control dispatched navigation", .{});
    _ = try clickSearchElement(self, io, out, "search.next");
    const match_id = firstVisibleSearchMatchId(self);
    const match_index = if (match_id) |id| App.searchMatchSemanticIndex(id) else null;
    const activated = if (match_id) |id| try clickSearchElement(self, io, out, id) else false;
    const activated_exact_match = if (match_index) |index|
        activated and self.search_active_index == index
    else
        false;
    searchCheck(out, &failures, activated_exact_match, "a clickable visible highlight activated its exact match", .{});

    _ = try postNamedKey(self, io, out, .escape, .{});
    searchCheck(out, &failures, !self.search_visible, "Escape closed search without reaching the terminal", .{});
    _ = try paletteChord(self, io, out);
    try self.window.postTextInput("terminalsearch");
    _ = try pumpUntil(self, io, out, .text_input, self_test_event_budget_ms);
    _ = try postNamedKey(self, io, out, .enter, .{});
    searchCheck(out, &failures, try waitForSearch(self, io, out, .{ .element = "search.dialog" }) and
        self.search_visible, "the command palette opened the same named search action", .{});
    searchCheck(out, &failures, try waitForSearch(self, io, out, .{ .complete = 4 }) and
        self.search_case == .ascii_insensitive and self.search_match_count == 4, "the palette-opened search retained and reran its query", .{});
    _ = try postKey(self, io, out, 'a', select_all_mods);
    try self.window.postTextInput("pagehit");
    _ = try pumpUntil(self, io, out, .text_input, self_test_event_budget_ms);
    searchCheck(out, &failures, try waitForSearch(self, io, out, .{ .complete = search_match_capacity }) and
        self.search_match_count == search_match_capacity, "a bounded first page retained 128 of more than 128 matches", .{});

    _ = try postNamedKey(self, io, out, .enter, .{ .shift = true });
    searchCheck(out, &failures, try waitForSearch(self, io, out, .{ .active_candidate = 140 }), "Previous from the newest match wrapped to the oldest match", .{});
    _ = try postNamedKey(self, io, out, .enter, .{});
    searchCheck(out, &failures, try waitForSearch(self, io, out, .{ .active_candidate = 0 }), "Next from the oldest match wrapped to the newest match", .{});
    for (0..search_match_capacity) |_| _ = try postNamedKey(self, io, out, .enter, .{});
    searchCheck(out, &failures, try waitForSearch(self, io, out, .{ .active_candidate = search_match_capacity }), "Next crossed the bounded page boundary without rescanning the prefix", .{});
    _ = try postNamedKey(self, io, out, .enter, .{ .shift = true });
    searchCheck(out, &failures, try waitForSearch(self, io, out, .{ .active_candidate = search_match_capacity - 1 }), "Previous crossed back from the adjacent page in canonical order", .{});

    while (self.search_active_index + 1 < self.search_match_count) {
        _ = try postNamedKey(self, io, out, .enter, .{});
    }
    try self.drawFrame();
    _ = try self.capture();
    searchCheck(out, &failures, self.presentedLive().terminal().viewport().offset != 0 and
        self.ui_tree.byId(.{ .value = "search.dialog" }) != null and
        activeSearchHighlightVisible(self), "the captured frame is ready with the bar and active off-screen match", .{});

    out.print("search-test: {d} failure(s)\n", .{failures}) catch {};
    out.flush() catch {};
    return if (failures == 0) 0 else 1;
}

const menu_test_url = "https://menu.test/open";
/// A deterministic real PTY peer for `--menu-test`: a visible URL for the
/// `open link` row, a readiness marker, then a line reader that enables and
/// disables SGR mouse reporting on request so DEC capture is the program's
/// own choice rather than a mode set by hand.
const menu_test_script =
    "stty -echo; " ++
    "printf '\x1b[2J\x1b[Hmenu " ++ menu_test_url ++ "\r\nMENU-READY\r\n'; " ++
    "while IFS= read -r line; do " ++
    "if [ \"$line\" = capture ]; then printf '\x1b[?1006;1000hCAPTURED\r\n'; " ++
    "else printf 'MENU-ECHO:%s\r\n' \"$line\"; fi; done";

const menu_test_budget_ms: i64 = 5000;

const MenuWait = union(enum) {
    terminal_text: []const u8,
    element: []const u8,
    element_absent: []const u8,
    link: []const u8,
    sent_contains: []const u8,
    mouse_tracking: term.MouseTracking,
};

fn menuWaitMet(self: *App, condition: MenuWait) bool {
    return switch (condition) {
        .terminal_text => |text| self.activeLive().terminal().visibleTextContains(text),
        .element => |id| self.ui_tree.byId(.{ .value = id }) != null,
        .element_absent => |id| self.ui_tree.byId(.{ .value = id }) == null,
        .link => |label| terminalLinkByLabel(self, label) != null,
        .sent_contains => |bytes| if (self.trace) |trace| std.mem.indexOf(u8, trace.sent.items, bytes) != null else false,
        .mouse_tracking => |mode| self.presentedLive().terminal().mouseTracking() == mode,
    };
}

fn waitForMenu(self: *App, io: Io, out: *Writer, condition: MenuWait) !bool {
    const deadline = Io.Clock.real.now(io).nanoseconds + menu_test_budget_ms * std.time.ns_per_ms;
    while (true) {
        if (self.scheduler.shouldDraw()) try self.drawFrame();
        if (menuWaitMet(self, condition)) return true;
        const event = self.window.pump(@min(self.waitBudget(io, deadline), 50));
        if (event) |one| {
            describeEvent(out, one) catch {};
            if (!try self.handle(one)) return false;
        }
        if (self.poll()) self.scheduler.invalidate();
        if (Io.Clock.real.now(io).nanoseconds >= deadline) {
            if (self.scheduler.shouldDraw()) try self.drawFrame();
            return menuWaitMet(self, condition);
        }
    }
}

fn menuCheck(out: *Writer, failures: *usize, ok: bool, comptime format: []const u8, args: anytype) void {
    out.print("menu-test: {s} " ++ format ++ "\n", .{if (ok) "ok  " else "FAIL"} ++ args) catch {};
    if (!ok) failures.* += 1;
}

fn postRightClick(self: *App, io: Io, out: *Writer, x: f32, y: f32, mods: platform.Mods) !bool {
    if (!try postButton(self, io, out, .{ .button = .right, .action = .press, .mods = mods, .x = x, .y = y })) return false;
    return postButton(self, io, out, .{ .button = .right, .action = .release, .mods = mods, .x = x, .y = y });
}

fn postLeftClick(self: *App, io: Io, out: *Writer, x: f32, y: f32) !bool {
    if (!try postButton(self, io, out, .{ .button = .left, .action = .press, .x = x, .y = y })) return false;
    return postButton(self, io, out, .{ .button = .left, .action = .release, .x = x, .y = y });
}

fn focusedMenuRow(self: *const App) []const u8 {
    const focused = self.ui_tree.focusedElement() orelse return "";
    return focused.id.value;
}

/// The ids the menu shows, in row order, as one comparable string.
fn menuRowIds(self: *const App, buffer: []u8) []const u8 {
    var writer = std.Io.Writer.fixed(buffer);
    for (self.ui_tree.elements()) |element| {
        if (!std.mem.eql(u8, element.role, "menu_item")) continue;
        writer.writeAll(element.id.value) catch break;
        writer.writeByte(' ') catch break;
    }
    return buffer[0..writer.end];
}

/// Exercise TASK-35 through the production pointer and key routing: the menu
/// opens at the pointer with context-appropriate rows, is keyboard navigable
/// and modal, its rows dispatch completed actions, the paste alternative
/// replaces it, and DEC mouse capture keeps a plain right click the program's.
fn menuTest(self: *App, io: Io, out: *Writer) !u8 {
    var failures: usize = 0;
    var child_trace: ClipboardTrace = .{};
    defer child_trace.deinit(self.allocator);
    self.trace = &child_trace;
    defer self.trace = null;
    var opener_trace: UrlOpenTrace = .{};
    self.url_opener = .{ .context = &opener_trace, .open_fn = recordOpenedUrl };
    defer self.url_opener = .{};

    try self.drawFrame();
    menuCheck(out, &failures, try waitForMenu(self, io, out, .{ .terminal_text = "MENU-READY" }) and
        try waitForMenu(self, io, out, .{ .link = menu_test_url }), "the real PTY produced the fixture and its link reached the semantic tree", .{});
    menuCheck(out, &failures, self.right_click == .menu, "the right-click setting resolved to the built-in menu default", .{});

    // 1. Right click on a plain cell: the menu at that cell, no copy or link.
    const anchor_col: u16 = 10;
    const anchor_row: u16 = 5;
    const anchor = cellPosition(self, anchor_col, anchor_row);
    var sent_mark = child_trace.sent.items.len;
    menuCheck(out, &failures, try postRightClick(self, io, out, anchor.x, anchor.y, .{}) and
        try waitForMenu(self, io, out, .{ .element = "context-menu" }), "a right click over the focused terminal opened the context menu", .{});
    var rows_buffer: [256]u8 = undefined;
    menuCheck(out, &failures, std.mem.eql(u8, menuRowIds(self, &rows_buffer), "context-menu.paste context-menu.split-right context-menu.split-down context-menu.search "), "without a selection or link the rows are paste, split right, split down and search", .{});
    const menu_element = self.ui_tree.byId(.{ .value = "context-menu" });
    const cell = self.fonts.metrics().cell;
    menuCheck(out, &failures, menu_element != null and
        menu_element.?.bounds.x == @as(i32, @intCast(@as(u32, anchor_col) * cell.width_px)) and
        menu_element.?.bounds.y == @as(i32, @intCast(@as(u32, anchor_row) * cell.height_px)), "the panel's top-left corner sits on the pointer cell", .{});
    menuCheck(out, &failures, std.mem.eql(u8, focusedMenuRow(self), "context-menu.paste"), "the first row is highlighted when the menu opens", .{});
    menuCheck(out, &failures, child_trace.sent.items.len == sent_mark, "the opening right click sent the program nothing", .{});

    // 2. Keyboard navigation, modal swallowing, Enter on search.
    _ = try postNamedKey(self, io, out, .down, .{});
    const after_down = std.mem.eql(u8, focusedMenuRow(self), "context-menu.split-right");
    _ = try postNamedKey(self, io, out, .down, .{});
    _ = try postNamedKey(self, io, out, .down, .{});
    const after_three = std.mem.eql(u8, focusedMenuRow(self), "context-menu.search");
    _ = try postNamedKey(self, io, out, .down, .{});
    const wrapped = std.mem.eql(u8, focusedMenuRow(self), "context-menu.paste");
    _ = try postNamedKey(self, io, out, .up, .{});
    const wrapped_back = std.mem.eql(u8, focusedMenuRow(self), "context-menu.search");
    _ = try postNamedKey(self, io, out, .tab, .{ .shift = true });
    const shift_tab = std.mem.eql(u8, focusedMenuRow(self), "context-menu.split-down");
    _ = try postNamedKey(self, io, out, .tab, .{});
    const tab = std.mem.eql(u8, focusedMenuRow(self), "context-menu.search");
    menuCheck(out, &failures, after_down and after_three and wrapped and wrapped_back and shift_tab and tab, "Down, Up, Tab and Shift+Tab move the highlighted row with wrap-around", .{});
    _ = try postKey(self, io, out, 'x', .{});
    menuCheck(out, &failures, child_trace.sent.items.len == sent_mark and self.contextMenuVisible(), "an unrelated key is swallowed by the modal menu instead of reaching the terminal", .{});
    _ = try postNamedKey(self, io, out, .enter, .{});
    menuCheck(out, &failures, try waitForMenu(self, io, out, .{ .element = "search.query" }) and
        self.search_visible and !self.contextMenuVisible(), "Enter on the search row dispatched search.open and closed the menu", .{});
    menuCheck(out, &failures, child_trace.sent.items.len == sent_mark, "the navigation keys and Enter sent the program nothing", .{});
    _ = try postNamedKey(self, io, out, .escape, .{});
    menuCheck(out, &failures, !self.search_visible, "Escape closed the search the menu opened", .{});

    // 3. Escape closes the menu; an outside click closes it without a tail.
    menuCheck(out, &failures, try postRightClick(self, io, out, anchor.x, anchor.y, .{}) and
        try waitForMenu(self, io, out, .{ .element = "context-menu" }), "the menu reopened for the Escape check", .{});
    _ = try postNamedKey(self, io, out, .escape, .{});
    menuCheck(out, &failures, !self.contextMenuVisible() and self.ui_tree.byId(.{ .value = "context-menu" }) == null, "Escape closed the menu", .{});
    menuCheck(out, &failures, try postRightClick(self, io, out, anchor.x, anchor.y, .{}) and
        try waitForMenu(self, io, out, .{ .element = "context-menu" }), "the menu reopened for the outside-click check", .{});
    const outside = cellPosition(self, 2, 1);
    _ = try postLeftClick(self, io, out, outside.x, outside.y);
    menuCheck(out, &failures, !self.contextMenuVisible() and child_trace.sent.items.len == sent_mark and
        !self.presentedLive().terminal().hasSelection(), "a click outside closed the menu and neither press nor release reached the terminal", .{});

    // 4. A selection adds the copy row, and the row copies the selection.
    menuCheck(out, &failures, try dragAcross(self, io, out, 0, 0, 4) and self.presentedLive().terminal().hasSelection(), "a real drag selected the first word", .{});
    menuCheck(out, &failures, try postRightClick(self, io, out, anchor.x, anchor.y, .{}) and
        try waitForMenu(self, io, out, .{ .element = "context-menu.copy" }), "with a selection the menu offers a copy row", .{});
    menuCheck(out, &failures, std.mem.eql(u8, focusedMenuRow(self), "context-menu.copy") and
        self.ui_tree.byId(.{ .value = "context-menu.open-link" }) == null, "copy is the first highlighted row and no link row appears off a link", .{});
    const dispatches_before_copy = self.action_dispatch_count;
    menuCheck(out, &failures, try clickSearchElement(self, io, out, "context-menu.copy") and !self.contextMenuVisible() and
        self.action_dispatch_count == dispatches_before_copy + 1 and
        std.mem.eql(u8, self.last_dispatched_action orelse "", clipboard_copy_action), "clicking the copy row dispatched clipboard.copy once and closed the menu", .{});
    const copied = try clipboardNow(self);
    defer self.allocator.free(copied);
    menuCheck(out, &failures, std.mem.eql(u8, copied, "menu"), "the clipboard holds the selected word", .{});
    _ = try postLeftClick(self, io, out, outside.x, outside.y);
    menuCheck(out, &failures, !self.presentedLive().terminal().hasSelection(), "a plain click cleared the selection again", .{});

    // 5. Over a link the menu offers open link, dispatching the ctrl-click seam.
    const link_element = terminalLinkByLabel(self, menu_test_url) orelse return 1;
    const link_point = terminalLinkPoint(self, link_element) orelse return 1;
    menuCheck(out, &failures, try postRightClick(self, io, out, link_point.x, link_point.y, .{}) and
        try waitForMenu(self, io, out, .{ .element = "context-menu.open-link" }), "over a link the menu offers an open link row", .{});
    menuCheck(out, &failures, std.mem.eql(u8, menuRowIds(self, &rows_buffer), "context-menu.paste context-menu.open-link context-menu.split-right context-menu.split-down context-menu.search "), "the link row sits between paste and the split rows", .{});
    _ = try postNamedKey(self, io, out, .down, .{});
    _ = try postNamedKey(self, io, out, .enter, .{});
    menuCheck(out, &failures, !self.contextMenuVisible() and opener_trace.calls == 1 and
        std.mem.eql(u8, opener_trace.value(), menu_test_url), "Enter on open link opened the exact URL through the opener seam", .{});
    const native_mods: platform.Mods = switch (self.binding_profile) {
        .macos => .{ .super = true },
        .linux_windows => .{ .ctrl = true },
    };
    _ = try postTerminalLinkClick(self, io, out, link_point, native_mods);
    menuCheck(out, &failures, opener_trace.calls == 2 and std.mem.eql(u8, opener_trace.value(), menu_test_url), "a modified click on the same link reaches the same seam with the same target", .{});

    // 6. The keyboard chord opens the menu at the terminal cursor.
    const cursor = self.presentedLive().terminal().cursor().position orelse term.Position{ .col = 0, .row = 0 };
    _ = try postNamedKey(self, io, out, .f10, .{ .shift = true });
    const keyboard_menu = self.ui_tree.byId(.{ .value = "context-menu" });
    menuCheck(out, &failures, self.contextMenuVisible() and keyboard_menu != null and
        keyboard_menu.?.bounds.x == @as(i32, @intCast(@as(u32, cursor.col) * cell.width_px)) and
        keyboard_menu.?.bounds.y == @as(i32, @intCast(@as(u32, cursor.row) * cell.height_px)), "Shift+F10 opened the menu at the terminal cursor cell", .{});
    menuCheck(out, &failures, paletteContainsDefinition(self, terminal_context_menu_action), "the context menu action is a palette-visible command", .{});
    _ = try postNamedKey(self, io, out, .escape, .{});
    menuCheck(out, &failures, !self.contextMenuVisible() and child_trace.sent.items.len == sent_mark, "Escape closed the keyboard-opened menu without terminal leakage", .{});

    // 7. The session layer can make a right click paste instead. The flag
    //    sets this at startup; the check flips the resolved value in place.
    try platform.setClipboardText(self.allocator, "menu-paste");
    self.right_click = .paste;
    const dispatches_before_paste = self.action_dispatch_count;
    menuCheck(out, &failures, try postRightClick(self, io, out, anchor.x, anchor.y, .{}) and
        try waitForMenu(self, io, out, .{ .sent_contains = "menu-paste" }) and !self.contextMenuVisible() and
        self.action_dispatch_count == dispatches_before_paste + 1 and
        std.mem.eql(u8, self.last_dispatched_action orelse "", clipboard_paste_action), "with mouse.right_click=paste a right click pasted the clipboard through clipboard.paste", .{});
    menuCheck(out, &failures, std.mem.eql(u8, child_trace.sent.items[sent_mark..], "menu-paste"), "the paste is exactly the clipboard text, unbracketed because the program did not ask", .{});
    self.right_click = .menu;
    // Finish the pasted line so the program's line reader echoes it back and
    // starts the next request from an empty line.
    _ = try postNamedKey(self, io, out, .enter, .{});
    menuCheck(out, &failures, try waitForMenu(self, io, out, .{ .terminal_text = "MENU-ECHO:menu-paste" }), "the program read the pasted text as its input line", .{});
    sent_mark = child_trace.sent.items.len;

    // 8. DEC mouse capture: plain right click is the program's, Shift's is ours.
    try self.window.postTextInput("capture");
    _ = try pumpUntil(self, io, out, .text_input, self_test_event_budget_ms);
    _ = try postNamedKey(self, io, out, .enter, .{});
    menuCheck(out, &failures, try waitForMenu(self, io, out, .{ .terminal_text = "CAPTURED" }) and
        try waitForMenu(self, io, out, .{ .mouse_tracking = .press }), "the program enabled SGR mouse reporting on request", .{});
    sent_mark = child_trace.sent.items.len;
    _ = try postRightClick(self, io, out, anchor.x, anchor.y, .{});
    var report: [64]u8 = undefined;
    const want_report = try std.fmt.bufPrint(&report, "\x1b[<2;{d};{d}M\x1b[<2;{d};{d}m", .{ anchor_col + 1, anchor_row + 1, anchor_col + 1, anchor_row + 1 });
    menuCheck(out, &failures, !self.contextMenuVisible() and
        std.mem.eql(u8, child_trace.sent.items[sent_mark..], want_report), "under mouse capture a plain right click became the program's SGR press and release", .{});
    sent_mark = child_trace.sent.items.len;
    menuCheck(out, &failures, try postRightClick(self, io, out, anchor.x, anchor.y, .{ .shift = true }) and
        try waitForMenu(self, io, out, .{ .element = "context-menu" }) and child_trace.sent.items.len == sent_mark, "Shift+right click bypassed the capture and opened the menu without a report", .{});
    _ = try postLeftClick(self, io, out, outside.x, outside.y);
    menuCheck(out, &failures, !self.contextMenuVisible() and child_trace.sent.items.len == sent_mark, "the closing outside click was not reported to the capturing program", .{});

    // 9. Leave the fullest menu on screen for the captured frame. The program
    //    still owns the mouse, so the selection drag holds Shift too.
    const drag_from = cellPosition(self, 0, 0);
    const drag_to = cellPosition(self, 4, 0);
    const shift: platform.Mods = .{ .shift = true };
    const shift_drag = try postButton(self, io, out, .{ .button = .left, .action = .press, .mods = shift, .x = drag_from.x, .y = drag_from.y }) and
        try postMotion(self, io, out, .{ .buttons = .{ .left = true }, .mods = shift, .x = drag_to.x, .y = drag_to.y }) and
        try postButton(self, io, out, .{ .button = .left, .action = .release, .mods = shift, .x = drag_to.x, .y = drag_to.y });
    menuCheck(out, &failures, shift_drag and self.presentedLive().terminal().hasSelection() and
        child_trace.sent.items.len == sent_mark, "a Shift drag selected under capture without a report", .{});
    menuCheck(out, &failures, try postRightClick(self, io, out, link_point.x, link_point.y, .{ .shift = true }) and
        try waitForMenu(self, io, out, .{ .element = "context-menu.copy" }) and
        self.ui_tree.byId(.{ .value = "context-menu.open-link" }) != null, "the final menu shows every row", .{});
    try self.drawFrame();
    _ = try self.capture();

    out.print("menu-test: {d} failure(s)\n", .{failures}) catch {};
    out.flush() catch {};
    return if (failures == 0) 0 else 1;
}

/// The deterministic peer behind `--config-test`'s terminals: a line echo, so
/// a chord that is no longer bound demonstrably reaches the terminal route.
const config_test_script =
    "stty -echo; " ++
    "printf 'CONFIG-READY\\r\\n'; " ++
    "while IFS= read -r line; do printf 'CONFIG-ECHO:%s\\r\\n' \"$line\"; done";

const config_test_budget_ms: i64 = 8000;

/// The settings `--config-test` starts with: the palette moved from its
/// shipped chord to Ctrl+Alt+P and a 30 percent scratchpad.
const config_test_initial =
    "# --config-test initial settings\n" ++
    "keybind = ctrl+shift+p=unbind\n" ++
    "keybind = ctrl+alt+p=palette.open\n" ++
    "scratchpad.size = 30\n";

/// Line 3 is malformed; line 4 is valid and must still apply; line 5 names an
/// action the registry does not have.
const config_test_malformed =
    "keybind = ctrl+shift+p=unbind\n" ++
    "keybind = ctrl+alt+p=palette.open\n" ++
    "scratchpad.size = banana\n" ++
    "scratchpad.large_size = 70\n" ++
    "keybind = ctrl+alt+k=no.such.action\n";

/// The repaired file, saved the way many editors save: a sibling written and
/// renamed over the original.
const config_test_fixed =
    "keybind = ctrl+shift+p=unbind\n" ++
    "keybind = ctrl+alt+o=palette.open\n" ++
    "scratchpad.size = 40\n" ++
    "scratchpad.large_size = 70\n" ++
    "font.size = 18\n";

/// A private absolute path for `--config-test`'s settings file, under the
/// platform temporary directory, so the user's real file is never read.

// --agent-test (TASK-56) -------------------------------------------------------

/// The first tab of `--agent-test`: a readiness marker, an echo, and on the
/// line `later` a background job that waits for the check's trigger file and
/// then rings a bell and asks for an OSC 777 notification, so both arrive
/// while the tab is in the background.
const agent_test_script =
    "printf 'AGENT-TEST-READY\\r\\n'; " ++
    "while IFS= read -r line; do " ++
    "if [ \"$line\" = later ]; then " ++
    "( while [ ! -e \"$" ++ agent_test_trigger_env ++ "\" ]; do sleep 0.05; done; " ++
    "printf '\\033]777;notify;Build;background finished\\033\\\\'; printf '\\007' ) & " ++
    "printf 'ARMED\\r\\n'; " ++
    // `fake` starts the scripted fake by hand, as a person starts a harness:
    // a foreground job of its own (job control), named
    // `conduit-fake-agent` (TASK-56 observed agents).
    "elif [ \"$line\" = fake ]; then " ++
    "set -m; sh \"${" ++ agent_test_trigger_env ++ "%/*}/conduit-fake-agent\"; set +m; printf 'FAKE-BACK\\r\\n'; " ++
    "else printf 'ECHO:%s\\r\\n' \"$line\"; fi; done";

/// The fake harness a person starts by hand in `--agent-test`'s first tab:
/// it says it is ready, waits for one line and leaves.
const observed_fake_script =
    "printf 'OBSERVED-FAKE-READY\\r\\n'\n" ++
    "IFS= read -r line\n" ++
    "printf 'OBSERVED-FAKE-BYE\\r\\n'\n";

const agent_test_initial_config = "# --agent-test\n";
const agent_test_budget_ms: i64 = 8000;

fn agentTestDir(io: Io, env: EnvSource, buffer: []u8) ![]const u8 {
    const base = firstEnv(env, temp_dir_vars[0..]) orelse "/tmp";
    const root = if (base.len != 0 and base[0] == '/') base else "/tmp";
    var id_buffer: [path_capacity]u8 = undefined;
    const id = try generateRunId(io, &id_buffer);
    return std.fmt.bufPrint(buffer, "{s}/conduit-agent-test-{s}", .{ root, id });
}

fn removeAgentTestDir(io: Io, dir: []const u8) void {
    if (std.mem.indexOf(u8, dir, "conduit-agent-test-") == null) return;
    Dir.cwd().deleteTree(io, dir) catch |err| {
        log.warn("could not remove the agent-test directory: {s}", .{@errorName(err)});
    };
}

// ---------------------------------------------------------------------------
// --restore-test (TASK-65)
// ---------------------------------------------------------------------------

/// The restore check's terminal peer: it reports its directory through OSC 7
/// (so the tracked cwd is the one saved), changes directory on `cd <dir>`,
/// answers `pwd`, and echoes anything else, all through real PTY input.
/// Directories are printed as `RA:`/`RP:` and their last component cut to
/// twelve bytes, so an answer fits on one row of a narrow pane.
const restore_test_script =
    "stty -echo; " ++
    "r() { b=${PWD##*/}; printf '\\033]7;file://localhost%s\\007RA:%.12s\\r\\n' \"$PWD\" \"$b\"; }; r; " ++
    "while IFS= read -r line; do case \"$line\" in " ++
    "'cd '*) cd \"${line#cd }\" && r;; " ++
    "pwd) b=${PWD##*/}; printf 'RP:%.12s.\\r\\n' \"$b\";; " ++
    "*) printf 'RE:%s\\r\\n' \"$line\";; " ++
    "esac; done";

/// What the restore script prints for `dir`: its last component, cut to
/// twelve bytes, after `prefix`.
fn restoreMarker(buffer: []u8, prefix: []const u8, dir: []const u8) ![]const u8 {
    const base = std.fs.path.basenamePosix(dir);
    return std.fmt.bufPrint(buffer, "{s}{s}", .{ prefix, base[0..@min(base.len, 12)] });
}

/// Printed by a shell in the first run; the saved state must not contain it.
const restore_test_secret = "RESTORE-SECRET-OUTPUT-7f3a";

fn restoreCheck(out: *Writer, failures: *usize, ok: bool, comptime format: []const u8, args: anytype) void {
    out.print("restore-test: {s} " ++ format ++ "\n", .{if (ok) "ok  " else "FAIL"} ++ args) catch {};
    out.flush() catch {};
    if (!ok) failures.* += 1;
}

fn restoreTestDir(io: Io, buffer: []u8) ![]const u8 {
    var id_buffer: [path_capacity]u8 = undefined;
    const id = try generateRunId(io, &id_buffer);
    // Short, so the control socket under it fits `sockaddr_un`.
    return std.fmt.bufPrint(buffer, "/tmp/conduit-restore-{s}", .{id[id.len - 6 ..]});
}

fn removeRestoreTestDir(io: Io, dir: []const u8) void {
    if (std.mem.indexOf(u8, dir, "conduit-restore-") == null) return;
    Dir.cwd().deleteTree(io, dir) catch |err| {
        log.warn("could not remove the restore-test directory: {s}", .{@errorName(err)});
    };
}

/// One pane element's geometry and whether it has focus.
const RestorePane = struct { bounds: ui.Bounds, focused: bool };

/// The active workspace's pane elements, in registration order.
fn restorePanes(self: *App, buffer: []RestorePane) []RestorePane {
    var count: usize = 0;
    const key = self.workspace_registry.activeKey() orelse return buffer[0..0];
    var prefix_buffer: [workspace_semantic_capacity]u8 = undefined;
    const prefix = std.fmt.bufPrint(&prefix_buffer, "workspace.{d}.pane.", .{@intFromEnum(key)}) catch return buffer[0..0];
    for (self.ui_tree.elements()) |element| {
        if (!std.mem.startsWith(u8, element.id.value, prefix)) continue;
        if (!std.mem.eql(u8, element.role, "pane")) continue;
        if (count == buffer.len) break;
        buffer[count] = .{ .bounds = element.bounds, .focused = element.state.selected };
        count += 1;
    }
    return buffer[0..count];
}

fn samePanes(a: []const RestorePane, b: []const RestorePane) bool {
    if (a.len != b.len) return false;
    for (a) |pane| {
        const found = for (b) |other| {
            if (std.meta.eql(pane.bounds, other.bounds) and pane.focused == other.focused) break true;
        } else false;
        if (!found) return false;
    }
    return true;
}

/// The id of the active workspace's pane element whose bounds are `bounds`.
fn restorePaneId(self: *App, bounds: ui.Bounds) ?[]const u8 {
    const key = self.workspace_registry.activeKey() orelse return null;
    var prefix_buffer: [workspace_semantic_capacity]u8 = undefined;
    const prefix = std.fmt.bufPrint(&prefix_buffer, "workspace.{d}.pane.", .{@intFromEnum(key)}) catch return null;
    for (self.ui_tree.elements()) |element| {
        if (!std.mem.startsWith(u8, element.id.value, prefix) or !std.mem.eql(u8, element.role, "pane")) continue;
        if (std.meta.eql(element.bounds, bounds)) return element.id.value;
    }
    return null;
}

/// The sidebar row of the workspace whose label ends with `name`.
fn restoreWorkspaceRow(self: *App, name: []const u8, buffer: []u8) ?[]const u8 {
    var index: usize = 0;
    while (index < self.workspace_registry.count()) : (index += 1) {
        const key = self.workspace_registry.keyAt(index) orelse continue;
        const id = workspaceSemanticId(buffer, key) catch return null;
        const element = self.ui_tree.byId(.{ .value = id }) orelse continue;
        if (std.mem.endsWith(u8, element.label, name)) return id;
    }
    return null;
}

/// How many workspace rows the sidebar shows.
fn restoreWorkspaceRows(self: *App) usize {
    var rows: usize = 0;
    for (self.ui_tree.elements()) |element| {
        const rest = if (std.mem.startsWith(u8, element.id.value, "workspace.")) element.id.value["workspace.".len..] else continue;
        _ = std.fmt.parseUnsigned(u32, rest, 10) catch continue;
        rows += 1;
    }
    return rows;
}

fn restoreStatus(self: *App) []const u8 {
    const element = self.ui_tree.byId(.{ .value = "workspace.status" }) orelse return "";
    return element.label;
}

/// Ask the focused restored shell for its directory through real input and
/// wait for the answer.
fn restorePwd(self: *App, io: Io, out: *Writer, expected: []const u8) !bool {
    if (!try sshType(self, io, out, "pwd", .{})) return false;
    var wanted_buffer: [path_capacity]u8 = undefined;
    const marker = try restoreMarker(&wanted_buffer, "RP:", expected);
    // The trailing dot ends the answer, so `sub` never matches `subway`.
    wanted_buffer[marker.len] = '.';
    return waitForSsh(self, io, out, .{ .presented_text = wanted_buffer[0 .. marker.len + 1] });
}

/// Wait until every restored shell of every workspace has started.
fn restoreSettled(self: *App, io: Io, out: *Writer) !bool {
    const deadline = Io.Clock.real.now(io).nanoseconds + ssh_test_budget_ms * std.time.ns_per_ms;
    while (true) {
        var pending = false;
        for (self.workspace_presentations.items) |presentation| {
            if (presentation.remote != null) continue;
            if (presentation.restore_queue.items.len != 0 or presentation.load != null or presentation.scratchpad_load != null) pending = true;
        }
        if (!pending) return true;
        if (Io.Clock.real.now(io).nanoseconds >= deadline) return false;
        const event = self.window.pump(@min(self.waitBudget(io, deadline), 50));
        if (event) |one| {
            describeEvent(out, one) catch {};
            if (!try self.handle(one)) return false;
        }
        if (self.outputReadable()) {
            if (try self.drainChildren(io) != 0) self.scheduler.invalidate();
        }
        if (self.poll()) self.scheduler.invalidate();
        if (self.scheduler.shouldDraw()) try self.drawFrame();
    }
}

/// Drop whatever the previous app left in SDL's queue, so the next one starts
/// from a quiet window as a relaunch would.
fn restoreDrainEvents(window: *platform.Window) void {
    while (window.pump(0)) |_| {}
}

fn restoreQuarantined(io: Io, state_dir: []const u8, buffer: []u8) ?[]const u8 {
    var dir = Dir.cwd().openDir(io, state_dir, .{ .iterate = true }) catch return null;
    defer dir.close(io);
    var iterator = dir.iterate();
    while (iterator.next(io) catch return null) |entry| {
        if (!std.mem.startsWith(u8, entry.name, "state.json.corrupt-")) continue;
        return std.fmt.bufPrint(buffer, "{s}/{s}", .{ state_dir, entry.name }) catch null;
    }
    return null;
}

/// TASK-65 end to end: one run builds a layout through real input and quits
/// through the normal path; a second app on the same window restores it;
/// a corrupt file and a newer version then each start clean.
fn restoreTest(init: std.process.Init, env: EnvSource, window: *platform.Window, base_options: Options, out: *Writer) !u8 {
    const io = init.io;
    const gpa = init.gpa;
    var failures: usize = 0;

    var dir_buffer: [path_capacity]u8 = undefined;
    const dir = try restoreTestDir(io, &dir_buffer);
    defer removeRestoreTestDir(io, dir);
    var paths: [8][path_capacity]u8 = undefined;
    const dir_a = try std.fmt.bufPrint(&paths[0], "{s}/ws-a", .{dir});
    const dir_sub = try std.fmt.bufPrint(&paths[1], "{s}/ws-a/sub", .{dir});
    const dir_gone = try std.fmt.bufPrint(&paths[2], "{s}/ws-a/gone", .{dir});
    const dir_b = try std.fmt.bufPrint(&paths[3], "{s}/ws-b", .{dir});
    const state_dir = try std.fmt.bufPrint(&paths[4], "{s}/state/conduit", .{dir});
    const state_path = try std.fmt.bufPrint(&paths[5], "{s}/state.json", .{state_dir});
    const ssh_config = try std.fmt.bufPrint(&paths[6], "{s}/home/.ssh/config", .{dir});
    for ([_][]const u8{ dir_sub, dir_gone, dir_b, state_dir }) |path| try Dir.cwd().createDirPath(io, path);
    // The SSH control sockets live in a private run directory of the check.
    var run_buffer: [path_capacity]u8 = undefined;
    _ = try Dir.cwd().createDirPathStatus(io, try std.fmt.bufPrint(&run_buffer, "{s}/run", .{dir}), privateArtifactPermissions(true));
    try Dir.cwd().createDirPath(io, std.fs.path.dirnamePosix(ssh_config).?);
    // A host alias whose port refuses at once: the first run's connection
    // fails without any prompt, and nothing outside this directory is read.
    try Dir.cwd().writeFile(io, .{ .sub_path = ssh_config, .data = "Host restore-box\n  HostName 127.0.0.1\n  Port 9\n  User restore\n  BatchMode yes\n" });
    const process_cwd = try std.process.currentPathAlloc(io, gpa);
    defer gpa.free(process_cwd);

    var options = base_options;
    options.run.state_path = state_path;
    options.run.ssh_test_dir = dir;

    // ---- The first run: build a layout through real input, then quit. ----
    var saved_panes_storage: [8]RestorePane = undefined;
    var saved_panes: []RestorePane = saved_panes_storage[0..0];
    var theme_buffer: [theme_name_capacity]u8 = undefined;
    var theme_name: []const u8 = "";
    {
        const self = try App.init(io, env, gpa, window, options);
        var destroyed = false;
        defer if (!destroyed) self.destroy();
        try self.syncTextInput();
        try self.drawFrame();
        restoreCheck(out, &failures, self.workspace_registry.count() == 1 and self.persistence.path != null, "a first run with no state file starts clean and persists to the private state file", .{});
        restoreCheck(out, &failures, try waitForSsh(self, io, out, .{ .presented_text = "RA:" }), "the first tab's shell started", .{});
        _ = try sshType(self, io, out, "cd {s}", .{dir_a});
        _ = try sshType(self, io, out, "{s}", .{restore_test_secret});
        var echo_buffer: [128]u8 = undefined;
        restoreCheck(out, &failures, try waitForSsh(self, io, out, .{ .presented_text = try std.fmt.bufPrint(&echo_buffer, "RE:{s}", .{restore_test_secret}) }), "the shell moved to ws-a and printed terminal content", .{});

        // Split right by mouse through the palette, then down by keyboard.
        restoreCheck(out, &failures, try clickPaletteCommand(self, io, out, pane_split_action, 0), "Split pane right was clicked in the palette", .{});
        var at_buffer: [path_capacity]u8 = undefined;
        restoreCheck(out, &failures, try waitForSsh(self, io, out, .{ .presented_text = try restoreMarker(&at_buffer, "RA:", dir_a) }), "the right pane started in the tracked ws-a", .{});
        _ = try sshType(self, io, out, "cd {s}", .{dir_sub});
        restoreCheck(out, &failures, try waitForSsh(self, io, out, .{ .presented_text = try restoreMarker(&at_buffer, "RA:", dir_sub) }), "the right pane moved to ws-a/sub", .{});
        const split_mods: platform.Mods = switch (self.binding_profile) {
            .macos => .{ .super = true, .shift = true },
            .linux_windows => .{ .ctrl = true, .shift = true },
        };
        _ = try postKey(self, io, out, if (self.binding_profile == .macos) 'd' else 'o', split_mods);
        restoreCheck(out, &failures, try waitForSsh(self, io, out, .{ .presented_text = try restoreMarker(&at_buffer, "RA:", dir_sub) }), "a nested split down started in ws-a/sub", .{});
        _ = try sshType(self, io, out, "cd {s}", .{dir_gone});
        restoreCheck(out, &failures, try waitForSsh(self, io, out, .{ .presented_text = try restoreMarker(&at_buffer, "RA:", dir_gone) }), "the bottom pane moved to a directory the relaunch will not find", .{});
        // Move the outer divider two cells left from the keyboard.
        const resize_mods: platform.Mods = switch (self.binding_profile) {
            .macos => .{ .super = true, .ctrl = true },
            .linux_windows => .{ .ctrl = true, .alt = true },
        };
        _ = try postNamedKey(self, io, out, .left, resize_mods);
        _ = try postNamedKey(self, io, out, .left, resize_mods);
        // Rename the tab with F2.
        _ = try postNamedKey(self, io, out, .f2, .{});
        _ = try postKey(self, io, out, 'a', if (self.binding_profile == .macos) .{ .super = true } else .{ .ctrl = true });
        _ = try postPaletteText(self, io, out, "build");
        _ = try postNamedKey(self, io, out, .enter, .{});
        const first_key = self.workspace_registry.activeKey().?;
        var tab_buffer: [workspace_semantic_capacity]u8 = undefined;
        const tab_row = try tabSemanticId(&tab_buffer, first_key, self.activeWorkspace().activeTabId().?);
        restoreCheck(out, &failures, if (self.ui_tree.byId(.{ .value = tab_row })) |row| std.mem.eql(u8, std.mem.trimStart(u8, row.label, " *!"), "build") else false, "F2 renamed the tab to build", .{});
        // Focus the top right pane by clicking it, and remember the layout.
        try self.drawFrame();
        var panes_buffer: [8]RestorePane = undefined;
        const before_focus = restorePanes(self, &panes_buffer);
        restoreCheck(out, &failures, before_focus.len == 3, "the tab holds three panes ({d})", .{before_focus.len});
        var left_x: i32 = std.math.maxInt(i32);
        for (before_focus) |pane| left_x = @min(left_x, pane.bounds.x);
        var top_right: ?ui.Bounds = null;
        for (before_focus) |pane| {
            if (pane.bounds.x == left_x) continue;
            if (top_right == null or pane.bounds.y < top_right.?.y or (pane.bounds.y == top_right.?.y and pane.bounds.x > top_right.?.x)) top_right = pane.bounds;
        }
        if (top_right) |bounds| if (restorePaneId(self, bounds)) |id| {
            var id_copy: [pane_semantic_capacity]u8 = undefined;
            @memcpy(id_copy[0..id.len], id);
            _ = try clickTabsElement(self, io, out, id_copy[0..id.len]);
        };
        try self.drawFrame();
        const focused_panes = restorePanes(self, &panes_buffer);
        @memcpy(saved_panes_storage[0..focused_panes.len], focused_panes);
        saved_panes = saved_panes_storage[0..focused_panes.len];
        const focus_ok = for (focused_panes) |pane| {
            if (pane.focused) break top_right != null and std.meta.eql(pane.bounds, top_right.?);
        } else false;
        restoreCheck(out, &failures, focus_ok, "a click focused the top right pane", .{});
        // Zoom it, then open a second tab and come back to the first.
        _ = try postNamedKey(self, io, out, .enter, if (self.binding_profile == .macos) .{ .super = true, .shift = true } else .{ .ctrl = true, .shift = true });
        try self.drawFrame();
        restoreCheck(out, &failures, restorePanes(self, &panes_buffer).len == 1, "the zoom chord filled the tab with the focused pane", .{});
        _ = try postKey(self, io, out, 't', if (self.binding_profile == .macos) .{ .super = true } else .{ .ctrl = true, .shift = true });
        restoreCheck(out, &failures, try waitForSsh(self, io, out, .{ .presented_text = try restoreMarker(&at_buffer, "RA:", dir_sub) }), "a second tab started in the focused pane's directory", .{});
        _ = try postKey(self, io, out, '1', if (self.binding_profile == .macos) .{ .super = true } else .{ .alt = true });
        restoreCheck(out, &failures, self.ui_tree.byId(.{ .value = tab_row }) != null and self.ui_tree.byId(.{ .value = tab_row }).?.state.selected, "the first tab is selected again", .{});

        // A second workspace in ws-b from the palette.
        _ = try openWorkspacePaletteCommand(self, io, out, "createworkspace", workspace_create_action);
        var dir_b_z: [path_capacity:0]u8 = undefined;
        _ = try postPaletteText(self, io, out, try std.fmt.bufPrintZ(&dir_b_z, "{s}", .{dir_b}));
        _ = try postNamedKey(self, io, out, .enter, .{});
        restoreCheck(out, &failures, try waitForWorkspaces(self, io, out, .{ .count = 2 }), "Create workspace opened ws-b", .{});

        // A theme from the picker: the second one listed.
        _ = try paletteChord(self, io, out);
        _ = try postPaletteText(self, io, out, "Theme: choose");
        _ = try postNamedKey(self, io, out, .enter, .{});
        _ = try postNamedKey(self, io, out, .down, .{});
        _ = try postNamedKey(self, io, out, .enter, .{});
        const chosen = self.activeThemeName();
        @memcpy(theme_buffer[0..chosen.len], chosen);
        theme_name = theme_buffer[0..chosen.len];
        restoreCheck(out, &failures, !self.paletteVisible() and !std.mem.eql(u8, theme_name, theme.default_id), "the theme picker applied {s}", .{theme_name});

        // An SSH workspace whose connection the first run tries and fails.
        if (ssh.supported) {
            _ = try openRemoteConnect(self, io, out);
            _ = try postPaletteText(self, io, out, "restore-box");
            _ = try postNamedKey(self, io, out, .enter, .{});
            restoreCheck(out, &failures, try waitForWorkspaces(self, io, out, .{ .count = 3 }) and self.activePresentation().remote != null, "Remote: connect opened the restore-box SSH workspace", .{});
        }

        // Back to the first workspace, then quit through the normal path.
        var row_buffer: [workspace_semantic_capacity]u8 = undefined;
        _ = try clickTabsElement(self, io, out, try workspaceSemanticId(&row_buffer, first_key));
        restoreCheck(out, &failures, self.workspace_registry.activeKey() == first_key, "clicking the first workspace's row selected it", .{});
        try self.window.postCloseRequest();
        try self.run(io, runDeadline(io, 5000));
        destroyed = true;
        self.destroy();
    }

    // ---- The file the first run left. ----
    {
        const buffer = try gpa.alloc(u8, state_mod.load_buffer_bytes);
        defer gpa.free(buffer);
        const bytes = Dir.cwd().readFile(io, state_path, buffer) catch &.{};
        var diagnostic: state_mod.Diagnostic = .{};
        if (state_mod.decode(gpa, bytes, &diagnostic)) |decoded_value| {
            var decoded = decoded_value;
            defer decoded.deinit();
            const snapshot = decoded.snapshot;
            restoreCheck(out, &failures, snapshot.version == 1 and snapshot.workspaces.len == (if (ssh.supported) @as(usize, 3) else 2), "quitting saved a version {d} state file with {d} workspaces", .{ snapshot.version, snapshot.workspaces.len });
            restoreCheck(out, &failures, snapshot.window != null and snapshot.window.?.width == 640 and snapshot.window.?.height == 360 and
                snapshot.theme != null and std.mem.eql(u8, snapshot.theme.?, theme_name), "it holds the 640x360 window and the chosen theme", .{});
            if (snapshot.workspaces.len != 0) {
                const first = snapshot.workspaces[0];
                const first_tab: ?state_mod.TabState = if (first.tabs.len != 0) first.tabs[0] else null;
                restoreCheck(out, &failures, first.tabs.len == 2 and first.active_tab != null and first.active_tab.? == 0 and
                    first_tab != null and first_tab.?.zoomed and first_tab.?.panes.leafCount() == 3 and
                    first_tab.?.name != null and std.mem.eql(u8, first_tab.?.name.?, "build"), "the first workspace's two tabs, names, zoom and three panes were saved ({d} tabs, active {?d}, zoomed {}, {d} panes, name {?s})", .{
                    first.tabs.len,
                    first.active_tab,
                    if (first_tab) |tab| tab.zoomed else false,
                    if (first_tab) |tab| tab.panes.leafCount() else 0,
                    if (first_tab) |tab| tab.name else null,
                });
            }
        } else |err| restoreCheck(out, &failures, false, "the state file decodes ({s}: {s})", .{ @errorName(err), diagnostic.message() });
        restoreCheck(out, &failures, std.mem.indexOf(u8, bytes, restore_test_secret) == null and std.mem.indexOf(u8, bytes, "RE:") == null and
            std.mem.indexOf(u8, bytes, "RA:") == null, "no terminal text reached the state file ({d} bytes)", .{bytes.len});
    }
    // The bottom pane's directory goes away between the runs.
    try Dir.cwd().deleteTree(io, dir_gone);
    restoreDrainEvents(window);

    // ---- The relaunch: everything comes back. ----
    {
        const self = try App.init(io, env, gpa, window, options);
        defer self.destroy();
        try self.syncTextInput();
        try self.drawFrame();
        restoreCheck(out, &failures, try restoreSettled(self, io, out), "every restored local shell started", .{});
        try self.drawFrame();
        var row_buffers: [3][workspace_semantic_capacity]u8 = undefined;
        const default_row = restoreWorkspaceRow(self, "default", &row_buffers[0]);
        const b_row = restoreWorkspaceRow(self, "ws-b", &row_buffers[1]);
        const ssh_row = restoreWorkspaceRow(self, "restore-box", &row_buffers[2]);
        restoreCheck(out, &failures, restoreWorkspaceRows(self) == (if (ssh.supported) @as(usize, 3) else 2) and default_row != null and b_row != null and
            (ssh_row != null or !ssh.supported), "the sidebar lists the restored default, ws-b and restore-box workspaces", .{});
        restoreCheck(out, &failures, if (default_row) |id| if (self.ui_tree.byId(.{ .value = id })) |row| row.state.selected else false else false, "the first workspace is selected again", .{});
        var status_buffer: [path_capacity * 2]u8 = undefined;
        const moved = try std.fmt.bufPrint(&status_buffer, "restore: {s} is gone; started in {s}", .{ dir_gone, process_cwd });
        restoreCheck(out, &failures, std.mem.eql(u8, restoreStatus(self), moved), "the status line names the missing directory and the fallback ({s})", .{restoreStatus(self)});
        var tab_count: usize = 0;
        var build_selected = false;
        const key = self.workspace_registry.activeKey().?;
        var tab_prefix_buffer: [workspace_semantic_capacity]u8 = undefined;
        const tab_prefix = try std.fmt.bufPrint(&tab_prefix_buffer, "workspace.{d}.tab.", .{@intFromEnum(key)});
        for (self.ui_tree.elements()) |element| {
            if (!std.mem.startsWith(u8, element.id.value, tab_prefix)) continue;
            _ = std.fmt.parseUnsigned(u32, element.id.value[tab_prefix.len..], 10) catch continue;
            tab_count += 1;
            if (std.mem.eql(u8, element.label, "  build") and element.state.selected) build_selected = true;
        }
        restoreCheck(out, &failures, tab_count == 2 and build_selected, "both tabs came back with the renamed build tab selected ({d})", .{tab_count});
        var panes_buffer: [8]RestorePane = undefined;
        const zoomed = restorePanes(self, &panes_buffer);
        restoreCheck(out, &failures, zoomed.len == 1 and zoomed[0].focused, "the tab is still zoomed on its focused pane", .{});
        _ = try postNamedKey(self, io, out, .enter, if (self.binding_profile == .macos) .{ .super = true, .shift = true } else .{ .ctrl = true, .shift = true });
        try self.drawFrame();
        const restored_panes = restorePanes(self, &panes_buffer);
        restoreCheck(out, &failures, samePanes(saved_panes, restored_panes), "unzoomed, the three panes have the saved bounds, divider ratios and focus", .{});
        restoreCheck(out, &failures, std.mem.eql(u8, self.activeThemeName(), theme_name), "the {s} theme is drawn again", .{theme_name});

        // Every shell started where it was: asked through real input.
        var expected: [3][]const u8 = undefined;
        var left_x: i32 = std.math.maxInt(i32);
        for (restored_panes) |pane| left_x = @min(left_x, pane.bounds.x);
        for (restored_panes, 0..) |pane, index| {
            if (index >= expected.len) break;
            expected[index] = if (pane.bounds.x == left_x) dir_a else if (pane.focused) dir_sub else process_cwd;
        }
        var cwd_ok = restored_panes.len == 3;
        for (restored_panes[0..@min(restored_panes.len, 3)], 0..) |pane, index| {
            const id = restorePaneId(self, pane.bounds) orelse {
                cwd_ok = false;
                continue;
            };
            var id_copy: [pane_semantic_capacity]u8 = undefined;
            @memcpy(id_copy[0..id.len], id);
            if (!try clickTabsElement(self, io, out, id_copy[0..id.len])) cwd_ok = false;
            if (!try restorePwd(self, io, out, expected[index])) cwd_ok = false;
        }
        restoreCheck(out, &failures, cwd_ok, "each pane's shell answers pwd with its saved directory (or the fallback)", .{});
        try self.drawFrame();
        var shot_buffer: [path_capacity]u8 = undefined;
        var id_buffer: [path_capacity]u8 = undefined;
        const shot = try std.fmt.bufPrint(&shot_buffer, "{s}{c}restore-test-{s}.png", .{ fallback_log_dir, std.fs.path.sep, try generateRunId(io, &id_buffer) });
        try writePngOffThread(gpa, io, shot, try self.capture(), self.size);
        out.print("restore-test: screenshot {s}\n", .{shot}) catch {};

        _ = try postKey(self, io, out, '2', if (self.binding_profile == .macos) .{ .super = true } else .{ .alt = true });
        restoreCheck(out, &failures, try restorePwd(self, io, out, dir_sub), "the second tab's shell is in ws-a/sub", .{});
        if (b_row) |id| {
            _ = try clickTabsElement(self, io, out, id);
            try self.drawFrame();
            // The row click focused the sidebar; a click on the pane gives
            // the keyboard to its shell.
            var b_panes_buffer: [8]RestorePane = undefined;
            const b_panes = restorePanes(self, &b_panes_buffer);
            if (b_panes.len == 1) if (restorePaneId(self, b_panes[0].bounds)) |pane_id| {
                var id_copy: [pane_semantic_capacity]u8 = undefined;
                @memcpy(id_copy[0..pane_id.len], pane_id);
                _ = try clickTabsElement(self, io, out, id_copy[0..pane_id.len]);
            };
            restoreCheck(out, &failures, b_panes.len == 1 and try restorePwd(self, io, out, dir_b), "ws-b's shell is in ws-b", .{});
        }
        _ = try paletteChord(self, io, out);
        _ = try postPaletteText(self, io, out, "Theme: choose");
        _ = try postNamedKey(self, io, out, .enter, .{});
        var first_choice: []const u8 = "";
        for (self.ui_tree.elements()) |element| {
            if (!std.mem.startsWith(u8, element.id.value, "palette.choice.") or !std.mem.endsWith(u8, element.id.value, ".0")) continue;
            first_choice = element.label;
        }
        restoreCheck(out, &failures, theme.sameName(first_choice, theme_name), "the theme picker lists the restored theme first ({s})", .{first_choice});
        _ = try postNamedKey(self, io, out, .escape, .{});

        if (ssh.supported) if (ssh_row) |id| {
            _ = try clickTabsElement(self, io, out, id);
            try self.drawFrame();
            const ssh_key = self.workspace_registry.activeKey().?;
            var ids: [3][workspace_semantic_capacity]u8 = undefined;
            const header = try connectionSemanticId(&ids[0], ssh_key, "");
            const reconnect = try connectionSemanticId(&ids[1], ssh_key, "reconnect");
            const disconnected = try std.fmt.bufPrint(&ids[2], "workspace.{d}.ssh.disconnected", .{@intFromEnum(ssh_key)});
            const header_label = if (self.ui_tree.byId(.{ .value = header })) |element| element.label else "";
            restoreCheck(out, &failures, std.mem.eql(u8, header_label, "ssh restore-box ─ saved session; press Enter or click reconnect to connect"), "the SSH workspace shows its saved-session view ({s})", .{header_label});
            restoreCheck(out, &failures, self.ui_tree.byId(.{ .value = reconnect }) != null and self.ui_tree.byId(.{ .value = disconnected }) != null and
                self.activePresentation().remote.?.context.state() == .disconnected, "with a clickable reconnect control and no connection attempted", .{});
            var ssh_shot_buffer: [path_capacity]u8 = undefined;
            const ssh_shot = try std.fmt.bufPrint(&ssh_shot_buffer, "{s}{c}restore-test-ssh-{s}.png", .{ fallback_log_dir, std.fs.path.sep, try generateRunId(io, &id_buffer) });
            try writePngOffThread(gpa, io, ssh_shot, try self.capture(), self.size);
            out.print("restore-test: screenshot {s}\n", .{ssh_shot}) catch {};
        };
        const logical = self.window.logicalSize();
        restoreCheck(out, &failures, logical != null and logical.?.width == 640 and logical.?.height == 360, "the window kept its saved 640x360 size", .{});
    }

    // ---- A corrupt file and a newer one each start clean. ----
    const cases = [_]struct { name: []const u8, bytes: []const u8 }{
        .{ .name = "a corrupt file", .bytes = "{\"version\": 1, \"workspaces\": [" },
        .{ .name = "a newer version", .bytes = "{\"version\": 2, \"workspaces\": []}\n" },
    };
    for (cases) |case| {
        restoreDrainEvents(window);
        try Dir.cwd().writeFile(io, .{ .sub_path = state_path, .data = case.bytes });
        // Each case's quarantined copy is told apart by its contents.
        var stale_buffer: [path_capacity]u8 = undefined;
        if (restoreQuarantined(io, state_dir, &stale_buffer)) |stale| Dir.cwd().deleteFile(io, stale) catch {};
        const self = try App.init(io, env, gpa, window, options);
        defer self.destroy();
        try self.drawFrame();
        restoreCheck(out, &failures, restoreWorkspaceRows(self) == 1 and restoreWorkspaceRow(self, "default", &stale_buffer) != null, "{s}: a clean start with the one default workspace", .{case.name});
        restoreCheck(out, &failures, std.mem.eql(u8, restoreStatus(self), restore_unreadable_status), "{s}: the status line says so ({s})", .{ case.name, restoreStatus(self) });
        var quarantine_buffer: [path_capacity]u8 = undefined;
        var content_buffer: [256]u8 = undefined;
        const quarantined = restoreQuarantined(io, state_dir, &quarantine_buffer);
        const content: []const u8 = if (quarantined) |path| Dir.cwd().readFile(io, path, &content_buffer) catch "" else "";
        restoreCheck(out, &failures, quarantined != null and std.mem.eql(u8, content, case.bytes), "{s}: the file was moved aside as state.json.corrupt-<time>", .{case.name});
    }

    out.print("restore-test: {d} failure(s)\n", .{failures}) catch {};
    out.flush() catch {};
    return if (failures == 0) 0 else 1;
}

// ---------------------------------------------------------------------------
// --a11y-test (TASK-68)
// ---------------------------------------------------------------------------

fn a11yCheck(out: *Writer, failures: *usize, ok: bool, comptime format: []const u8, args: anytype) void {
    out.print("a11y-test: {s} " ++ format ++ "\n", .{if (ok) "ok  " else "FAIL"} ++ args) catch {};
    out.flush() catch {};
    if (!ok) failures.* += 1;
}

/// One loop iteration: an event, the loop's own polling and a frame.
fn a11yStep(self: *App, io: Io, out: *Writer) !void {
    if (self.window.pump(20)) |event| {
        describeEvent(out, event) catch {};
        _ = try self.handle(event);
    }
    if (self.outputReadable()) {
        if (try self.drainChildren(io) != 0) self.scheduler.invalidate();
    }
    if (self.poll()) self.scheduler.invalidate();
    if (self.scheduler.shouldDraw()) try self.drawFrame();
}

/// Walk the bridge's tree over the bus until `id` appears, running the app's
/// loop in between so it can publish.
fn a11yFind(self: *App, io: Io, out: *Writer, client: *accessibility.check.Client, id: []const u8) !?accessibility.check.Client.Found {
    const deadline = Io.Clock.real.now(io).nanoseconds + 5000 * std.time.ns_per_ms;
    while (true) {
        // The tree may change under a walk (a row goes between two calls);
        // that walk is simply tried again on the next frame.
        if (client.find(id) catch null) |found| return found;
        if (Io.Clock.real.now(io).nanoseconds >= deadline) return null;
        try a11yStep(self, io, out);
    }
}

fn a11yRole(role: accessibility.atspi.Role) u32 {
    return @intFromEnum(role);
}

/// TASK-68 in the running app: the live semantic tree reaches an assistive
/// technology over AT-SPI, and its actions come back as real input.
fn a11yTest(
    self: *App,
    io: Io,
    gpa: Allocator,
    out: *Writer,
    bus: *accessibility.check.PrivateBus,
    registry: *accessibility.check.FakeRegistry,
) !u8 {
    var failures: usize = 0;
    try self.drawFrame();
    const bridge = self.a11y orelse {
        a11yCheck(out, &failures, false, "the app started an accessibility bridge", .{});
        return 1;
    };
    a11yCheck(out, &failures, registry.waitEmbedded(5000), "the bridge found the accessibility bus and embedded itself in the registry", .{});
    const deadline = Io.Clock.real.now(io).nanoseconds + 5000 * std.time.ns_per_ms;
    while (bridge.currentStatus() == .starting and Io.Clock.real.now(io).nanoseconds < deadline) try a11yStep(self, io, out);
    a11yCheck(out, &failures, bridge.currentStatus() == .connected, "the bridge is serving", .{});

    var client: accessibility.check.Client = .{
        .io = io,
        .conn = try accessibility.dbus.Connection.open(gpa, bus.address(), 256 * 1024, 64 * 1024),
        .app = registry.embeddedName(),
    };
    defer client.conn.close();
    try client.connect();

    // The sidebar: the workspace row, its tab and the palette hint.
    const key = self.workspace_registry.activeKey() orelse return 1;
    var ids: [2][workspace_semantic_capacity]u8 = undefined;
    const workspace_row = try workspaceSemanticId(&ids[0], key);
    const tab_row = try tabSemanticId(&ids[1], key, self.activeWorkspace().activeTabId() orelse return 1);
    const expectations = [_]struct { id: []const u8, role: accessibility.atspi.Role }{
        .{ .id = "sidebar", .role = .panel },
        .{ .id = workspace_row, .role = .tree_item },
        .{ .id = tab_row, .role = .page_tab },
        .{ .id = "sidebar.palette", .role = .push_button },
    };
    for (expectations) |expected| {
        const found = try a11yFind(self, io, out, &client, expected.id);
        const label = if (self.ui_tree.byId(.{ .value = expected.id })) |element| element.label else "";
        a11yCheck(out, &failures, found != null and found.?.role == a11yRole(expected.role) and std.mem.eql(u8, found.?.name(), label), "{s} is a {s} named '{s}'", .{ expected.id, expected.role.name(), label });
    }

    // The palette, opened by its chord.
    _ = try paletteChord(self, io, out);
    const dialog = try a11yFind(self, io, out, &client, "palette.dialog");
    a11yCheck(out, &failures, dialog != null and dialog.?.role == a11yRole(.dialog), "the opened palette is a dialog", .{});
    const query = try a11yFind(self, io, out, &client, "palette.query");
    a11yCheck(out, &failures, query != null and query.?.role == a11yRole(.entry), "its query field is an entry", .{});
    _ = try postPaletteText(self, io, out, "Settings");
    const settings_index = definitionIndex(self, settings_open_action) orelse return 1;
    var row_buffer: [palette_semantic_capacity]u8 = undefined;
    const row_id = try std.fmt.bufPrint(&row_buffer, "palette.action.{d}", .{settings_index});
    const row = try a11yFind(self, io, out, &client, row_id);
    const row_label = if (self.ui_tree.byId(.{ .value = row_id })) |element| element.label else "";
    a11yCheck(out, &failures, row != null and row.?.role == a11yRole(.list_item) and std.mem.eql(u8, row.?.name(), row_label), "the Settings command is a list item named '{s}'", .{row_label});

    // DoAction on that row runs the command through a real click.
    if (row) |found| {
        a11yCheck(out, &failures, try client.doAction(found.path.slice()), "DoAction on the palette row was accepted", .{});
        const settings = try a11yFind(self, io, out, &client, "settings.dialog");
        a11yCheck(out, &failures, settings != null and settings.?.role == a11yRole(.dialog) and self.settingsVisible() and !self.paletteVisible(), "it ran Settings: the settings dialog opened and the palette closed", .{});
    }

    // The settings rows mirror the tree: headings and settings.
    var heading_seen = false;
    var rows_checked: usize = 0;
    var rows_ok = true;
    var focus_target: [settings_semantic_capacity]u8 = undefined;
    var focus_target_len: usize = 0;
    var row_ids: [6][settings_semantic_capacity]u8 = undefined;
    var row_id_lens: [6]usize = undefined;
    var row_count: usize = 0;
    for (self.ui_tree.elements()) |element| {
        const is_row = std.mem.startsWith(u8, element.id.value, "settings.row.") or std.mem.startsWith(u8, element.id.value, "settings.heading.");
        if (!is_row or row_count == row_ids.len) continue;
        if (element.id.value.len > settings_semantic_capacity) continue;
        @memcpy(row_ids[row_count][0..element.id.value.len], element.id.value);
        row_id_lens[row_count] = element.id.value.len;
        row_count += 1;
    }
    for (row_ids[0..row_count], row_id_lens[0..row_count]) |*storage, len| {
        const id = storage[0..len];
        const element = self.ui_tree.byId(.{ .value = id }) orelse continue;
        const found = try a11yFind(self, io, out, &client, id) orelse {
            rows_ok = false;
            continue;
        };
        rows_checked += 1;
        if (!std.mem.eql(u8, found.name(), element.label)) rows_ok = false;
        if (std.mem.eql(u8, element.role, "heading")) {
            heading_seen = true;
            if (found.role != a11yRole(.heading)) rows_ok = false;
        } else if (focus_target_len == 0 and element.primitive.isInteractive() and !element.state.focused) {
            @memcpy(focus_target[0..len], id);
            focus_target_len = len;
        }
    }
    a11yCheck(out, &failures, rows_checked >= 3 and rows_ok and heading_seen, "{d} settings rows, headings included, carry the tree's roles and labels", .{rows_checked});

    // GrabFocus moves the tree's keyboard focus.
    if (focus_target_len != 0) {
        const target = focus_target[0..focus_target_len];
        const found = try a11yFind(self, io, out, &client, target);
        const accepted = if (found) |value| try client.grabFocus(value.path.slice()) else false;
        const focus_deadline = Io.Clock.real.now(io).nanoseconds + 5000 * std.time.ns_per_ms;
        while (Io.Clock.real.now(io).nanoseconds < focus_deadline) {
            if (self.ui_tree.focusedElement()) |focused| if (std.mem.eql(u8, focused.id.value, target)) break;
            try a11yStep(self, io, out);
        }
        const focused_now = if (self.ui_tree.focusedElement()) |focused| std.mem.eql(u8, focused.id.value, target) else false;
        a11yCheck(out, &failures, accepted and focused_now, "GrabFocus on {s} moved keyboard focus there", .{target});
    }
    _ = try postNamedKey(self, io, out, .escape, .{});

    out.print("a11y-test: {d} failure(s)\n", .{failures}) catch {};
    out.flush() catch {};
    return if (failures == 0) 0 else 1;
}

// ---------------------------------------------------------------------------
// --ssh-test (TASK-43 part two, TASK-44, TASK-45)
// ---------------------------------------------------------------------------

const ssh_test_budget_ms: i64 = 30_000;
/// The throwaway sshd image `src/ssh.zig`'s integration test builds from
/// `test/fixtures/ssh`.
const ssh_test_image = "conduit-ssh-test:latest";
/// The prompt hook appended to the container user's `.bashrc`. The fixture
/// has no Conduit remote shell integration (decision-8's install is not
/// built yet), so this stands in for it: the OSC 7 report a shell with
/// integration sends, naming the remote host.
const ssh_test_osc7_hook =
    "PROMPT_COMMAND='printf \"\\033]7;file://%s%s\\007\" \"$HOSTNAME\" \"$PWD\"'\n";

/// `--ssh-test`'s private directory: under `/tmp` rather than `$TMPDIR`
/// because the control socket below it must fit `sockaddr_un`.
fn sshTestDir(io: Io, buffer: []u8) ![]const u8 {
    var id_buffer: [path_capacity]u8 = undefined;
    const id = try generateRunId(io, &id_buffer);
    return std.fmt.bufPrint(buffer, "/tmp/conduit-ssh-test-{s}", .{id});
}

fn removeSshTestDir(io: Io, dir: []const u8) void {
    if (std.mem.indexOf(u8, dir, "conduit-ssh-test-") == null) return;
    Dir.cwd().deleteTree(io, dir) catch |err| {
        log.warn("could not remove the ssh-test directory: {s}", .{@errorName(err)});
    };
}

fn sshCheck(out: *Writer, failures: *usize, ok: bool, comptime format: []const u8, args: anytype) void {
    out.print("ssh-test: {s} " ++ format ++ "\n", .{if (ok) "ok  " else "FAIL"} ++ args) catch {};
    out.flush() catch {};
    if (!ok) failures.* += 1;
}

/// Run one local helper (docker, ssh-keygen) to completion.
fn sshHost(self: *App, io: Io, argv: []const []const u8, timeout_ms: u32) !workspace.RunResult {
    return workspace.runLocalProcess(self.allocator, io, .{
        .argv = argv,
        .cwd = "",
        .timeout_ms = timeout_ms,
        .max_output = 4 * 1024 * 1024,
    });
}

/// Run a helper and say whether it succeeded, releasing its output.
fn sshHostOk(self: *App, io: Io, argv: []const []const u8, timeout_ms: u32) bool {
    var result = sshHost(self, io, argv, timeout_ms) catch return false;
    defer result.deinit(self.allocator);
    return result.succeeded();
}

const SshWait = union(enum) {
    presented_text: []const u8,
    session_text: struct { key: workspace.WorkspaceKey, id: session.SessionId, text: []const u8 },
    element: []const u8,
    element_absent: []const u8,
    cwd: struct { key: workspace.WorkspaceKey, id: session.SessionId, cwd: []const u8 },
    /// A new running child behind `id` whose shell reported `cwd`.
    replaced: struct { key: workspace.WorkspaceKey, id: session.SessionId, old: *anyopaque, cwd: []const u8 },
    ended: struct { key: workspace.WorkspaceKey, id: session.SessionId },
    child: struct { key: workspace.WorkspaceKey, id: session.SessionId },
    /// The agent runtime resolved `key`'s remote sink root (TASK-61).
    remote_sink_root: workspace.WorkspaceKey,
    /// A file on `key`'s remote host, read through its context, says `text`.
    remote_file: struct { key: workspace.WorkspaceKey, path: []const u8, text: []const u8 },
    /// Workspace `key` has an agent notification whose body contains `text`.
    agent_entry: struct { key: workspace.WorkspaceKey, text: []const u8 },
};

fn sshSession(self: *App, key: workspace.WorkspaceKey, id: session.SessionId) ?*session.Session {
    const model = self.workspace_registry.byKey(key) orelse return null;
    return model.sessionById(id);
}

fn sshWaitMet(self: *App, condition: SshWait) !bool {
    switch (condition) {
        .presented_text => |text| {
            const live = self.presentedLive();
            try live.terminal().refresh(self.allocator);
            return live.terminal().visibleTextContains(text);
        },
        .session_text => |wanted| {
            const live = sshSession(self, wanted.key, wanted.id) orelse return false;
            try live.terminal().refresh(self.allocator);
            return live.terminal().visibleTextContains(wanted.text);
        },
        .element => |id| return self.ui_tree.byId(.{ .value = id }) != null,
        .element_absent => |id| return self.ui_tree.byId(.{ .value = id }) == null,
        .cwd => |wanted| {
            const live = sshSession(self, wanted.key, wanted.id) orelse return false;
            const actual = live.workingDirectory() orelse return false;
            return std.mem.eql(u8, actual, wanted.cwd);
        },
        .replaced => |wanted| {
            const live = sshSession(self, wanted.key, wanted.id) orelse return false;
            const child = live.child() orelse return false;
            if (child.ptr == wanted.old or child.state() != .running) return false;
            const actual = live.workingDirectory() orelse return false;
            return std.mem.eql(u8, actual, wanted.cwd);
        },
        .ended => |wanted| {
            const live = sshSession(self, wanted.key, wanted.id) orelse return false;
            const child = live.child() orelse return false;
            return child.state() == .exited and !live.needsPump();
        },
        .child => |wanted| {
            const live = sshSession(self, wanted.key, wanted.id) orelse return false;
            return live.child() != null;
        },
        .remote_sink_root => |key| return self.agents.remoteSinkRootFor(key) != null,
        .remote_file => |wanted| {
            const model = self.workspace_registry.byKey(wanted.key) orelse return false;
            var buffer: [256]u8 = undefined;
            const got = model.contextRef().readFile(self.io, wanted.path, &buffer) catch return false;
            return std.mem.eql(u8, got, wanted.text);
        },
        .agent_entry => |wanted| {
            for (0..self.agents.notifications.count()) |index| {
                const entry = self.agents.notifications.newest(index) orelse break;
                if (entry.workspace == wanted.key and entry.agent != null and std.mem.indexOf(u8, entry.body(), wanted.text) != null) return true;
            }
            return false;
        },
    }
}

fn waitForSsh(self: *App, io: Io, out: *Writer, condition: SshWait) !bool {
    const deadline = Io.Clock.real.now(io).nanoseconds + ssh_test_budget_ms * std.time.ns_per_ms;
    while (true) {
        if (try sshWaitMet(self, condition)) return true;
        const event = self.window.pump(@min(self.waitBudget(io, deadline), 50));
        if (event) |one| {
            describeEvent(out, one) catch {};
            if (!try self.handle(one)) return false;
        }
        if (self.outputReadable()) {
            if (try self.drainChildren(io) != 0) self.scheduler.invalidate();
        }
        if (self.poll()) self.scheduler.invalidate();
        if (self.scheduler.shouldDraw()) try self.drawFrame();
        if (Io.Clock.real.now(io).nanoseconds >= deadline) return try sshWaitMet(self, condition);
    }
}

/// Type one line into whatever terminal is presented, through SDL.
fn sshType(self: *App, io: Io, out: *Writer, comptime format: []const u8, args: anytype) !bool {
    var buffer: [512]u8 = undefined;
    const text = try std.fmt.bufPrintZ(&buffer, format, args);
    try self.window.postTextInput(text);
    if (!try pumpUntil(self, io, out, .text_input, self_test_event_budget_ms)) return false;
    return postNamedKey(self, io, out, .enter, .{});
}

/// Write the current frame beside `--screenshot` as `<stem>-<name>.png`.
fn sshScreenshot(self: *App, io: Io, out: *Writer, name: []const u8) !void {
    const base = self.screenshot orelse return;
    try self.drawFrame();
    const pixels = try self.capture();
    var path_buffer: [path_capacity]u8 = undefined;
    const stem = if (std.mem.endsWith(u8, base, ".png")) base[0 .. base.len - 4] else base;
    const path = try std.fmt.bufPrint(&path_buffer, "{s}-{s}.png", .{ stem, name });
    try writePngOffThread(self.allocator, io, path, pixels, self.size);
    out.print("ssh-test: screenshot {s}\n", .{path}) catch {};
}

fn choiceIndexByValue(self: *const App, value: []const u8) ?usize {
    for (self.remote_choices[0..self.remote_choice_count], 0..) |choice, index| {
        if (std.mem.eql(u8, choice.value, value)) return index;
    }
    return null;
}

fn choiceRowId(buffer: []u8, definition_index: usize, choice_index: usize) ![]const u8 {
    return std.fmt.bufPrint(buffer, "palette.choice.{d}.{d}", .{ definition_index, choice_index });
}

/// Open `Remote: connect` from the palette: its chord, a query, then Enter
/// or a click on the command's row.
fn openRemoteConnect(self: *App, io: Io, out: *Writer) !bool {
    if (!try paletteChord(self, io, out)) return false;
    if (!try postPaletteText(self, io, out, "remote connect")) return false;
    const selected = self.palette_model.selectedDefinition() orelse return false;
    if (std.mem.eql(u8, selected.name, remote_connect_action)) {
        if (!try postNamedKey(self, io, out, .enter, .{})) return false;
    } else {
        // The palette keeps a still-matching recent command selected
        // (`Remote: reconnect` matches too), so take the row by mouse.
        var row_buffer: [palette_semantic_capacity]u8 = undefined;
        const row = try std.fmt.bufPrint(&row_buffer, "palette.action.{d}", .{self.remote_connect_index});
        if (!try clickTabsElement(self, io, out, row)) return false;
    }
    return switch (self.palette_step) {
        .choices => |step| step.definition_index == self.remote_connect_index,
        else => false,
    };
}

/// One `docker exec` in the test container; whether it exited 0.
fn sshContainerOk(self: *App, io: Io, container: []const u8, argv: []const []const u8) bool {
    var full: [12][]const u8 = undefined;
    if (argv.len + 3 > full.len) return false;
    full[0] = "docker";
    full[1] = "exec";
    full[2] = container;
    @memcpy(full[3..][0..argv.len], argv);
    return sshHostOk(self, io, full[0 .. argv.len + 3], 30_000);
}

/// `--ssh-test`'s TASK-61 part: the fake agent (whose remote mode stages
/// its script as a launch file in the remote sink) launched through
/// `agent.launch` in the connected SSH workspace `key`.
fn sshAgentChecks(
    self: *App,
    io: Io,
    out: *Writer,
    failures: *usize,
    key: workspace.WorkspaceKey,
    row_id: []const u8,
    container: []const u8,
    remote_name: []const u8,
) !void {
    const model = self.workspace_registry.byKey(key) orelse return error.TestUnexpectedResult;
    sshCheck(out, failures, self.workspace_registry.activeKey() == key, "the first SSH workspace is shown again", .{});
    // Opening the palette resolves the remote sink root on a worker (this
    // check offers only the fake, so no harness is probed).
    _ = try paletteChord(self, io, out);
    sshCheck(out, failures, try waitForSsh(self, io, out, .{ .remote_sink_root = key }), "the remote state directory was resolved through the connection", .{});
    var root_buffer: [path_capacity]u8 = undefined;
    const remote_root = try std.fmt.bufPrint(&root_buffer, "{s}", .{self.agents.remoteSinkRootFor(key) orelse ""});
    sshCheck(out, failures, std.mem.startsWith(u8, remote_root, "/home/conduit/.local/state/conduit/agents/"), "the remote sink root is under the remote user's state directory ({s})", .{remote_root});
    _ = try postPaletteText(self, io, out, "Agent: launch");
    _ = try postNamedKey(self, io, out, .enter, .{});
    _ = try postNamedKey(self, io, out, .enter, .{});
    const prompt_step = self.palette_step == .input and self.palette_step.input == self.agent_prompt_index;
    _ = try postNamedKey(self, io, out, .enter, .{});
    const agent_tab = model.activeTabId() orelse return error.TestUnexpectedResult;
    const agent_session = model.focusedPaneSessionId(agent_tab) orelse return error.TestUnexpectedResult;
    var tab_buffer: [workspace_semantic_capacity]u8 = undefined;
    const tab_row = try tabSemanticId(&tab_buffer, key, agent_tab);
    var glyph_buffers: [3][workspace_semantic_capacity + 32]u8 = undefined;
    const idle_glyph = try std.fmt.bufPrint(&glyph_buffers[0], "{s}.agent.idle", .{tab_row});
    sshCheck(out, failures, prompt_step and model.sessionKind(agent_session) == .agent_terminal and
        try waitForSsh(self, io, out, .{ .element = idle_glyph }), "Agent: launch from the palette started the fake agent in a new agent tab", .{});

    // AC1: the process runs in the container, from a script the launch
    // staged in the remote sink; nothing of the sink exists on this machine.
    var host_buffer: [128]u8 = undefined;
    const host_marker = try std.fmt.bufPrint(&host_buffer, "FAKE-AGENT-HOST:{s}", .{remote_name});
    sshCheck(out, failures, try waitForSsh(self, io, out, .{ .session_text = .{ .key = key, .id = agent_session, .text = host_marker } }), "the agent's process runs on the remote host ({s})", .{remote_name});
    const runner = self.agents.runnerForSession(key, agent_session) orelse {
        sshCheck(out, failures, false, "the agent has a runner", .{});
        return;
    };
    var sink_buffer: [path_capacity]u8 = undefined;
    const sink_dir = try std.fmt.bufPrint(&sink_buffer, "{s}", .{runner.sink_dir});
    var script_buffer: [path_capacity]u8 = undefined;
    const script_path = try std.fmt.bufPrint(&script_buffer, "{s}/{s}", .{ sink_dir, app_agents.fake_remote_script_name });
    const script_copy = try self.allocator.alloc(u8, app_agents.fake_remote_script.len + 1);
    defer self.allocator.free(script_copy);
    const staged = model.contextRef().readFile(io, script_path, script_copy) catch "";
    const local_absent = if (Dir.cwd().statFile(io, sink_dir, .{})) |_| false else |_| true;
    sshCheck(out, failures, std.mem.startsWith(u8, sink_dir, remote_root) and std.mem.eql(u8, staged, app_agents.fake_remote_script) and
        sshContainerOk(self, io, container, &.{ "test", "-d", sink_dir }) and local_absent, "the sink and its launch file were written on the remote host, and no local sink exists", .{});

    // AC2: steps the remote script appends to the remote sink drive the
    // sidebar glyphs and raise a notification.
    _ = try sshType(self, io, out, "one", .{});
    const working_glyph = try std.fmt.bufPrint(&glyph_buffers[1], "{s}.agent.working", .{tab_row});
    sshCheck(out, failures, try waitForSsh(self, io, out, .{ .element = working_glyph }), "a remote step turned the tab's glyph to working", .{});
    _ = try sshType(self, io, out, "two", .{});
    const waiting_glyph = try std.fmt.bufPrint(&glyph_buffers[2], "{s}.agent.waiting_permission", .{tab_row});
    var workspace_glyph_buffer: [workspace_semantic_capacity + 32]u8 = undefined;
    const workspace_glyph = try std.fmt.bufPrint(&workspace_glyph_buffer, "{s}.agent.waiting_permission", .{row_id});
    sshCheck(out, failures, try waitForSsh(self, io, out, .{ .element = waiting_glyph }) and
        try waitForSsh(self, io, out, .{ .element = workspace_glyph }), "the next remote step showed waiting for permission on the tab and the workspace", .{});
    sshCheck(out, failures, try waitForSsh(self, io, out, .{ .agent_entry = .{ .key = key, .text = "Run: make test" } }), "the remote agent's permission wait was listed as a notification", .{});

    // AC3: the structured view shows the remote events, and an answer
    // clicked there reaches the decision file on the remote host.
    const agent_number = @intFromEnum(runner.agent_id orelse return error.TestUnexpectedResult);
    var view_ids: [3][agent_view_id_capacity]u8 = undefined;
    const view_id = try std.fmt.bufPrint(&view_ids[0], "agent.view.{d}", .{agent_number});
    const allow_id = try std.fmt.bufPrint(&view_ids[1], "agent.view.{d}.perm.fake-1.allow", .{agent_number});
    const outcome_id = try std.fmt.bufPrint(&view_ids[2], "agent.view.{d}.perm.fake-1.outcome", .{agent_number});
    _ = try viewChordKey(self, io, out, 'a');
    sshCheck(out, failures, try waitForSsh(self, io, out, .{ .element = view_id }) and
        try waitForSsh(self, io, out, .{ .element = allow_id }), "the agent view shows the remote agent's permission request with its decisions", .{});
    try sshScreenshot(self, io, out, "agent-view");
    _ = try clickTabsElement(self, io, out, allow_id);
    var decision_buffer: [path_capacity]u8 = undefined;
    const decision_path = try std.fmt.bufPrint(&decision_buffer, "{s}/decisions/fake-1", .{sink_dir});
    sshCheck(out, failures, try waitForSsh(self, io, out, .{ .element = outcome_id }) and
        try waitForSsh(self, io, out, .{ .remote_file = .{ .key = key, .path = decision_path, .text = "allow" } }), "the answer clicked in the view was written to the remote decision file", .{});
    _ = try viewChordKey(self, io, out, 'a');

    // Closing the workspace removes this run's remote sinks with it.
    sshCheck(out, failures, sshContainerOk(self, io, container, &.{ "test", "-d", remote_root }), "the run's remote sink root exists while the workspace is open", .{});
    _ = try clickPaletteCommand(self, io, out, workspace_close_action, null);
    _ = try clickTabsElement(self, io, out, "workspace-close.confirm");
    sshCheck(out, failures, try waitForSsh(self, io, out, .{ .element_absent = row_id }) and self.workspace_registry.byKey(key) == null, "the SSH workspace closed", .{});
    sshCheck(out, failures, !sshContainerOk(self, io, container, &.{ "test", "-e", remote_root }) and
        !sshContainerOk(self, io, container, &.{ "test", "-e", sink_dir }), "closing it removed the remote sink root and the agent's sink", .{});
}

fn sshTest(self: *App, io: Io, out: *Writer) !u8 {
    var failures: usize = 0;
    const run_dir = self.ssh_runtime_owned orelse return 1;
    const dir = std.fs.path.dirnamePosix(run_dir) orelse return 1;

    // Docker and the fixture image are prerequisites, as for the ssh.zig
    // integration test: without them the check is skipped, not failed.
    const docker_ready = sshHostOk(self, io, &.{ "docker", "info" }, 30_000) and
        sshHostOk(self, io, &.{ "docker", "build", "-q", "-t", ssh_test_image, "test/fixtures/ssh" }, 900_000);
    if (!docker_ready) {
        out.print("ssh-test: skipped: docker or the test/fixtures/ssh image is unavailable (run from the repository root)\n", .{}) catch {};
        out.flush() catch {};
        return 0;
    }

    var paths: [8][path_capacity]u8 = undefined;
    const ssh_dir = try std.fmt.bufPrint(&paths[0], "{s}/home/.ssh", .{dir});
    const include_dir = try std.fmt.bufPrint(&paths[1], "{s}/conf.d", .{ssh_dir});
    const key_path = try std.fmt.bufPrint(&paths[2], "{s}/id_ed25519", .{ssh_dir});
    const config_path = self.ssh_config_override orelse return 1;
    const hook_path = try std.fmt.bufPrint(&paths[3], "{s}/osc7.sh", .{dir});
    try Dir.cwd().createDirPath(io, include_dir);
    try Dir.cwd().createDirPath(io, run_dir);

    // A throwaway key with a throwaway passphrase, so the master must show
    // OpenSSH's own passphrase prompt. Never the user's ~/.ssh or agent.
    var id_buffer: [path_capacity]u8 = undefined;
    const run_id = try generateRunId(io, &id_buffer);
    var passphrase_buffer: [96]u8 = undefined;
    const passphrase = try std.fmt.bufPrint(&passphrase_buffer, "conduit-pass-{s}", .{run_id});
    sshCheck(out, &failures, sshHostOk(self, io, &.{ "ssh-keygen", "-q", "-t", "ed25519", "-N", passphrase, "-C", "conduit-ssh-test", "-f", key_path }, 30_000), "a throwaway passphrase key was generated", .{});

    var name_buffer: [path_capacity]u8 = undefined;
    const container = try std.fmt.bufPrint(&name_buffer, "conduit-ssh-app-test-{s}", .{run_id});
    var mount_buffer: [path_capacity]u8 = undefined;
    const mount = try std.fmt.bufPrint(&mount_buffer, "{s}.pub:/conduit-key.pub:ro", .{key_path});
    const started = sshHostOk(self, io, &.{ "docker", "run", "-d", "--name", container, "-p", "127.0.0.1::22", "-v", mount, ssh_test_image }, 120_000);
    defer {
        var removed = sshHost(self, io, &.{ "docker", "rm", "-f", container }, 60_000) catch null;
        if (removed) |*result| result.deinit(self.allocator);
    }
    sshCheck(out, &failures, started, "the sshd container started", .{});
    if (!started) return 1;

    var port_result = try sshHost(self, io, &.{ "docker", "port", container, "22/tcp" }, 30_000);
    defer port_result.deinit(self.allocator);
    const first_line = std.mem.sliceTo(port_result.stdout, '\n');
    const colon = std.mem.lastIndexOfScalar(u8, first_line, ':') orelse return 1;
    const port = std.fmt.parseInt(u16, std.mem.trim(u8, first_line[colon + 1 ..], " \r"), 10) catch return 1;
    {
        const deadline = Io.Clock.real.now(io).nanoseconds + 30 * std.time.ns_per_s;
        while (true) {
            var logs = try sshHost(self, io, &.{ "docker", "logs", container }, 30_000);
            defer logs.deinit(self.allocator);
            if (std.mem.indexOf(u8, logs.stderr, "Server listening") != null or
                std.mem.indexOf(u8, logs.stdout, "Server listening") != null) break;
            if (Io.Clock.real.now(io).nanoseconds > deadline) {
                sshCheck(out, &failures, false, "sshd started listening", .{});
                return 1;
            }
        }
    }
    var host_result = try sshHost(self, io, &.{ "docker", "exec", container, "uname", "-n" }, 30_000);
    defer host_result.deinit(self.allocator);
    const remote_name = std.mem.trim(u8, host_result.stdout, " \r\n");

    try Dir.cwd().writeFile(io, .{ .sub_path = hook_path, .data = ssh_test_osc7_hook });
    var copy_target: [path_capacity]u8 = undefined;
    const hook_target = try std.fmt.bufPrint(&copy_target, "{s}:/tmp/conduit-osc7.sh", .{container});
    sshCheck(out, &failures, sshHostOk(self, io, &.{ "docker", "cp", hook_path, hook_target }, 30_000) and
        sshHostOk(self, io, &.{ "docker", "exec", container, "sh", "-c", "cat /tmp/conduit-osc7.sh >> /home/conduit/.bashrc" }, 30_000), "the remote shell reports its cwd with OSC 7 (a stand-in for remote shell integration)", .{});

    // A private client configuration: the alias, an Include, the identity,
    // a private known_hosts with OpenSSH's default `ask` policy, no agent.
    var config_text: [4096]u8 = undefined;
    const config_body = try std.fmt.bufPrint(&config_text,
        \\Host conduit-test-host
        \\  HostName 127.0.0.1
        \\  Port {d}
        \\  User conduit
        \\Include {s}/*
        \\Host *
        \\  IdentityFile {s}
        \\  IdentitiesOnly yes
        \\  IdentityAgent none
        \\  UserKnownHostsFile {s}/known_hosts
        \\  GlobalKnownHostsFile /dev/null
        \\  StrictHostKeyChecking ask
        \\  UpdateHostKeys no
        \\
    , .{ port, include_dir, key_path, dir });
    try Dir.cwd().writeFile(io, .{ .sub_path = config_path, .data = config_body });
    var include_file: [path_capacity]u8 = undefined;
    try Dir.cwd().writeFile(io, .{
        .sub_path = try std.fmt.bufPrint(&include_file, "{s}/extra.conf", .{include_dir}),
        .data = "Host conduit-included\n  HostName 127.0.0.1\n",
    });

    try self.drawFrame();
    const local_key = self.activePresentation().key;

    // TASK-44 AC1: the palette lists ssh-config hosts (Include followed)
    // and the address row, and typing filters them fuzzily.
    sshCheck(out, &failures, try openRemoteConnect(self, io, out) and
        self.ui_tree.byId(.{ .value = "palette.filter" }) != null and
        self.ui_tree.focusedElement() != null and
        std.mem.eql(u8, self.ui_tree.focusedElement().?.id.value, "palette.filter"), "Remote: connect opened its host list with the filter focused", .{});
    const alias_index = choiceIndexByValue(self, "host:conduit-test-host");
    const included_index = choiceIndexByValue(self, "host:conduit-included");
    const address_index = choiceIndexByValue(self, "address");
    var row_ids: [3][palette_semantic_capacity]u8 = undefined;
    const alias_row = if (alias_index) |index| try choiceRowId(&row_ids[0], self.remote_connect_index, index) else "";
    const included_row = if (included_index) |index| try choiceRowId(&row_ids[1], self.remote_connect_index, index) else "";
    sshCheck(out, &failures, alias_index != null and included_index != null and address_index != null and
        self.ui_tree.byId(.{ .value = alias_row }) != null and
        self.ui_tree.byId(.{ .value = included_row }) != null, "the list shows the config alias, the included host and the user@host row", .{});
    _ = try postPaletteText(self, io, out, "conduit-test");
    const filtered_selected = switch (self.palette_step) {
        .choices => |step| step.selected,
        else => std.math.maxInt(usize),
    };
    sshCheck(out, &failures, alias_index != null and filtered_selected == alias_index.? and
        self.ui_tree.byId(.{ .value = alias_row }) != null and
        self.ui_tree.byId(.{ .value = included_row }) == null, "typing filtered the list fuzzily to the alias", .{});

    // TASK-44 AC3 and TASK-43 AC3: connecting creates the SSH workspace in
    // the sidebar, and OpenSSH's own host-key prompt is in its connection
    // terminal, answered by typing.
    _ = try postNamedKey(self, io, out, .enter, .{});
    const key = self.workspace_registry.activeKey() orelse return 1;
    var ids: [8][workspace_semantic_capacity]u8 = undefined;
    const row_id = try workspaceSemanticId(&ids[0], key);
    const connection_header = try connectionSemanticId(&ids[1], key, "");
    const connected_id = try std.fmt.bufPrint(&ids[2], "{s}.ssh.connected", .{row_id});
    const lost_id = try std.fmt.bufPrint(&ids[3], "{s}.ssh.lost", .{row_id});
    const reconnect_id = try connectionSemanticId(&ids[4], key, "reconnect");
    sshCheck(out, &failures, key != local_key and self.presentationByKey(key).?.remote != null and
        self.workspace_registry.count() == 2, "connecting created and switched to an SSH workspace", .{});
    sshCheck(out, &failures, try waitForSsh(self, io, out, .{ .presented_text = "(yes/no" }) and
        self.ui_tree.byId(.{ .value = connection_header }) != null, "the connection view shows OpenSSH's host-key prompt", .{});
    const row_label = if (self.ui_tree.byId(.{ .value = row_id })) |element| element.label else "";
    sshCheck(out, &failures, std.mem.startsWith(u8, row_label, "↕ conduit-test-host"), "the sidebar row shows the connecting glyph ({s})", .{row_label});
    try sshScreenshot(self, io, out, "prompt");
    _ = try sshType(self, io, out, "yes", .{});
    sshCheck(out, &failures, try waitForSsh(self, io, out, .{ .presented_text = "Enter passphrase" }), "the passphrase prompt followed in the same terminal", .{});
    _ = try sshType(self, io, out, "{s}", .{passphrase});
    sshCheck(out, &failures, try waitForSsh(self, io, out, .{ .element = connected_id }) and
        try waitForSsh(self, io, out, .{ .element_absent = connection_header }), "the workspace reached connected and the connection view stepped aside", .{});
    const model = self.workspace_registry.byKey(key) orelse return 1;
    const record = self.presentationByKey(key).?.remote.?;
    if (model.sessionById(record.connection_id)) |connection| {
        try connection.terminal().refresh(self.allocator);
        sshCheck(out, &failures, !connection.terminal().visibleTextContains(passphrase), "the passphrase was never echoed", .{});
    }

    // TASK-43 AC1: the first tab is a remote shell.
    const first_tab = model.activeTabId() orelse return 1;
    const first_session = model.focusedPaneSessionId(first_tab) orelse return 1;
    sshCheck(out, &failures, try waitForSsh(self, io, out, .{ .session_text = .{ .key = key, .id = first_session, .text = "conduit@" } }), "the first tab started the remote login shell", .{});
    _ = try sshType(self, io, out, "printf 'R%sE:%s\\n' EMOT \"$(uname -n)\"", .{});
    var marker_buffer: [128]u8 = undefined;
    const remote_marker = try std.fmt.bufPrint(&marker_buffer, "REMOTE:{s}", .{remote_name});
    sshCheck(out, &failures, try waitForSsh(self, io, out, .{ .session_text = .{ .key = key, .id = first_session, .text = remote_marker } }), "the first tab runs on the remote host ({s})", .{remote_name});
    _ = try sshType(self, io, out, "cd /home/conduit/project/sub", .{});
    sshCheck(out, &failures, try waitForSsh(self, io, out, .{ .cwd = .{ .key = key, .id = first_session, .cwd = "/home/conduit/project/sub" } }), "the remote shell's OSC 7 naming the remote host became the tab's cwd", .{});

    // TASK-45 AC2 and TASK-43 AC1: a split (keyboard) starts in the
    // originating session's remote cwd over the same connection.
    const split_mods: platform.Mods = switch (self.binding_profile) {
        .macos => .{ .super = true },
        .linux_windows => .{ .ctrl = true, .shift = true },
    };
    _ = try postKey(self, io, out, if (self.binding_profile == .macos) 'd' else 'e', split_mods);
    const split_session = model.focusedPaneSessionId(first_tab) orelse return 1;
    sshCheck(out, &failures, split_session != first_session and
        try waitForSsh(self, io, out, .{ .session_text = .{ .key = key, .id = split_session, .text = "conduit@" } }), "split right started a second remote shell", .{});
    // The pane is narrow, so its first prompt's OSC 7 is the evidence
    // rather than a printed path that would wrap.
    sshCheck(out, &failures, try waitForSsh(self, io, out, .{ .cwd = .{ .key = key, .id = split_session, .cwd = "/home/conduit/project/sub" } }), "the split pane started in the originating pane's remote cwd", .{});
    _ = try sshType(self, io, out, "cd /tmp", .{});
    _ = try waitForSsh(self, io, out, .{ .cwd = .{ .key = key, .id = split_session, .cwd = "/tmp" } });

    // A new tab by mouse, from the split pane's cwd.
    const tab_new_index = definitionIndex(self, tab_new_action) orelse return 1;
    var tab_new_row: [palette_semantic_capacity]u8 = undefined;
    _ = try clickTabsElement(self, io, out, "sidebar.palette");
    _ = try postPaletteText(self, io, out, "newtab");
    _ = try clickTabsElement(self, io, out, try std.fmt.bufPrint(&tab_new_row, "palette.action.{d}", .{tab_new_index}));
    const new_tab = model.activeTabId() orelse return 1;
    const tab_session = model.focusedPaneSessionId(new_tab) orelse return 1;
    sshCheck(out, &failures, new_tab != first_tab and
        try waitForSsh(self, io, out, .{ .session_text = .{ .key = key, .id = tab_session, .text = "conduit@" } }), "a palette-clicked new tab started a remote shell", .{});
    _ = try sshType(self, io, out, "printf 'P%sD:%s\\n' W \"$PWD\"", .{});
    sshCheck(out, &failures, try waitForSsh(self, io, out, .{ .session_text = .{ .key = key, .id = tab_session, .text = "PWD:/tmp" } }), "the new tab started in the originating session's remote cwd", .{});

    // TASK-45 AC1 and AC3: the scratchpad is remote and survives hide/show.
    const scratchpad_id = model.scratchpadId();
    _ = try scratchpadChord(self, io, out, false);
    sshCheck(out, &failures, self.activePresentation().scratchpad_presentation == .fifty and
        try waitForSsh(self, io, out, .{ .session_text = .{ .key = key, .id = scratchpad_id, .text = "conduit@" } }), "the scratchpad shows a remote shell started when the workspace connected", .{});
    _ = try sshType(self, io, out, "printf 'R%sE:%s\\n' EMOT \"$(uname -n)\"", .{});
    sshCheck(out, &failures, try waitForSsh(self, io, out, .{ .session_text = .{ .key = key, .id = scratchpad_id, .text = remote_marker } }), "the scratchpad runs on the remote host", .{});
    _ = try sshType(self, io, out, "cd /home/conduit/project", .{});
    _ = try waitForSsh(self, io, out, .{ .cwd = .{ .key = key, .id = scratchpad_id, .cwd = "/home/conduit/project" } });
    const scratchpad_child = (model.sessionById(scratchpad_id) orelse return 1).child() orelse return 1;
    _ = try scratchpadChord(self, io, out, false);
    const hidden = self.activePresentation().scratchpad_presentation == .hidden;
    _ = try scratchpadChord(self, io, out, false);
    const shown_again = model.sessionById(scratchpad_id).?.child().?.ptr == scratchpad_child.ptr;
    sshCheck(out, &failures, hidden and shown_again and
        try waitForSsh(self, io, out, .{ .session_text = .{ .key = key, .id = scratchpad_id, .text = remote_marker } }), "the remote scratchpad kept its process and output across hide and show", .{});
    _ = try scratchpadChord(self, io, out, false);

    var tab_row_buffer: [workspace_semantic_capacity]u8 = undefined;
    _ = try clickTabsElement(self, io, out, try tabSemanticId(&tab_row_buffer, key, first_tab));
    try sshScreenshot(self, io, out, "connected");

    // TASK-43 AC4: losing the connection (sshd's per-connection processes
    // killed; the listener stays, standing in for a server coming back) is
    // shown in the sidebar and the connection view.
    const first_child = (model.sessionById(first_session) orelse return 1).child() orelse return 1;
    const split_child = (model.sessionById(split_session) orelse return 1).child() orelse return 1;
    const tab_child = (model.sessionById(tab_session) orelse return 1).child() orelse return 1;
    const scratch_child = (model.sessionById(scratchpad_id) orelse return 1).child() orelse return 1;
    _ = sshHostOk(self, io, &.{ "docker", "exec", container, "pkill", "-KILL", "-f", "sshd: conduit" }, 30_000);
    sshCheck(out, &failures, try waitForSsh(self, io, out, .{ .element = lost_id }) and
        try waitForSsh(self, io, out, .{ .element = reconnect_id }), "the loss was detected and the connection view offers reconnect", .{});
    const lost_label = if (self.ui_tree.byId(.{ .value = row_id })) |element| element.label else "";
    const header_label = if (self.ui_tree.byId(.{ .value = connection_header })) |element| element.label else "";
    sshCheck(out, &failures, std.mem.startsWith(u8, lost_label, "⚠ ") and
        std.mem.indexOf(u8, header_label, "connection lost") != null, "the sidebar shows the lost glyph and the view names the loss", .{});
    for ([_]session.SessionId{ first_session, split_session, tab_session, scratchpad_id }) |id| {
        sshCheck(out, &failures, try waitForSsh(self, io, out, .{ .ended = .{ .key = key, .id = id } }), "session {d} ended with the connection", .{@intFromEnum(id)});
    }
    try sshScreenshot(self, io, out, "lost");

    // Reconnect by mouse; the new master prompts again in the same view, and
    // every session comes back under its id in its last remote cwd.
    sshCheck(out, &failures, try clickTabsElement(self, io, out, reconnect_id) and
        try waitForSsh(self, io, out, .{ .presented_text = "Enter passphrase" }), "reconnect started a new master showing the passphrase prompt", .{});
    _ = try sshType(self, io, out, "{s}", .{passphrase});
    sshCheck(out, &failures, try waitForSsh(self, io, out, .{ .element = connected_id }), "the workspace reconnected", .{});
    sshCheck(out, &failures, try waitForSsh(self, io, out, .{ .replaced = .{ .key = key, .id = first_session, .old = first_child.ptr, .cwd = "/home/conduit/project/sub" } }), "the first pane was restored under its id in its remote cwd", .{});
    sshCheck(out, &failures, try waitForSsh(self, io, out, .{ .replaced = .{ .key = key, .id = split_session, .old = split_child.ptr, .cwd = "/tmp" } }), "the split pane was restored in its remote cwd", .{});
    sshCheck(out, &failures, try waitForSsh(self, io, out, .{ .replaced = .{ .key = key, .id = tab_session, .old = tab_child.ptr, .cwd = "/tmp" } }), "the second tab was restored in its remote cwd", .{});
    sshCheck(out, &failures, try waitForSsh(self, io, out, .{ .replaced = .{ .key = key, .id = scratchpad_id, .old = scratch_child.ptr, .cwd = "/home/conduit/project" } }), "the scratchpad was restored in its remote cwd", .{});

    // TASK-44 AC2: an ad hoc user@host connection, saved as a profile.
    sshCheck(out, &failures, try openRemoteConnect(self, io, out), "Remote: connect reopened", .{});
    _ = try postPaletteText(self, io, out, "enter user");
    // The list grew a recent row since it was first read, so look again.
    const address_now = choiceIndexByValue(self, "address");
    const address_selected = switch (self.palette_step) {
        .choices => |step| address_now != null and step.selected == address_now.?,
        else => false,
    };
    _ = try postNamedKey(self, io, out, .enter, .{});
    const address_step = switch (self.palette_step) {
        .input => |definition_index| definition_index == self.remote_address_index,
        else => false,
    };
    sshCheck(out, &failures, address_selected and address_step, "the user@host row asked for a destination", .{});
    _ = try sshType(self, io, out, "conduit@127.0.0.1:{d}", .{port});
    const adhoc_key = self.workspace_registry.activeKey() orelse return 1;
    const save_step = switch (self.palette_step) {
        .choices => |step| step.definition_index == self.remote_save_index,
        else => false,
    };
    sshCheck(out, &failures, adhoc_key != key and self.presentationByKey(adhoc_key).?.remote != null and save_step, "the ad hoc destination opened a workspace and offered to save it", .{});
    var save_row: [palette_semantic_capacity]u8 = undefined;
    _ = try clickTabsElement(self, io, out, try choiceRowId(&save_row, self.remote_save_index, 0));
    const settings_buffer = try self.allocator.alloc(u8, config.max_file_bytes);
    defer self.allocator.free(settings_buffer);
    const settings_text = self.local_files.borrow().readFile(io, self.config_path orelse "", settings_buffer) catch "";
    var profile_line: [256]u8 = undefined;
    const expected_profile = try std.fmt.bufPrint(&profile_line, "remote.profile = 127.0.0.1 = conduit@127.0.0.1:{d}", .{port});
    sshCheck(out, &failures, std.mem.indexOf(u8, settings_text, expected_profile) != null and
        std.mem.indexOf(u8, settings_text, "remote.recent = conduit@127.0.0.1:") != null and
        std.mem.indexOf(u8, settings_text, ",conduit-test-host") != null, "the profile and both recent destinations were written to the settings file", .{});
    sshCheck(out, &failures, try waitForSsh(self, io, out, .{ .presented_text = "Enter passphrase" }), "the ad hoc workspace prompted in its own connection view", .{});
    _ = try sshType(self, io, out, "{s}", .{passphrase});
    var adhoc_ids: [2][workspace_semantic_capacity]u8 = undefined;
    const adhoc_row = try workspaceSemanticId(&adhoc_ids[0], adhoc_key);
    const adhoc_connected = try std.fmt.bufPrint(&adhoc_ids[1], "{s}.ssh.connected", .{adhoc_row});
    sshCheck(out, &failures, try waitForSsh(self, io, out, .{ .element = adhoc_connected }), "the ad hoc workspace connected", .{});

    // The saved profile is listed next time.
    sshCheck(out, &failures, try openRemoteConnect(self, io, out), "Remote: connect reopened after saving", .{});
    _ = try postPaletteText(self, io, out, "127");
    const profile_index = choiceIndexByValue(self, "profile:127.0.0.1");
    var profile_row: [palette_semantic_capacity]u8 = undefined;
    sshCheck(out, &failures, profile_index != null and self.choiceFilterPosition(profile_index.?) != null and
        self.ui_tree.byId(.{ .value = try choiceRowId(&profile_row, self.remote_connect_index, profile_index orelse 0) }) != null, "the saved profile is listed and found by the filter", .{});
    _ = try postNamedKey(self, io, out, .escape, .{});

    // TASK-61: an agent launched in the first SSH workspace runs on the
    // remote host, its sink and launch files are written there, its status,
    // notifications and structured view follow its remote events, a
    // permission answered in the view reaches the remote decision file, and
    // closing the workspace removes the remote sinks.
    _ = try clickTabsElement(self, io, out, row_id);
    _ = try waitForSsh(self, io, out, .{ .element_absent = "palette.dialog" });
    try sshAgentChecks(self, io, out, &failures, key, row_id, container, remote_name);

    // The final frame: whatever the remaining workspace shows.
    try self.drawFrame();
    _ = try self.capture();

    out.print("ssh-test: {d} failure(s)\n", .{failures}) catch {};
    out.flush() catch {};
    return if (failures == 0) 0 else 1;
}

const AgentWait = union(enum) {
    terminal_text: []const u8,
    element: []const u8,
    element_absent: []const u8,
    entries: usize,
    entry_body: []const u8,
    os_calls: usize,
    reloads: usize,
    active_tab: workspace.TabId,
    active_workspace: workspace.WorkspaceKey,
    /// An element `id` whose label contains `text` (TASK-57).
    label: struct { id: []const u8, text: []const u8 },
    /// Some element whose id starts with `prefix` and whose label contains `text`.
    role_label: struct { prefix: []const u8, text: []const u8 },
    /// The fake adapter of `agent` recorded `text` through `sendInput`
    /// (TASK-58).
    fake_input: struct { agent: agent.AgentId, text: []const u8 },
    /// The session's child is a running process (a restart's new child).
    child_running: struct { key: workspace.WorkspaceKey, session: session.SessionId },
    /// The session's tracked cwd is `cwd` (TASK-59).
    session_cwd: struct { key: workspace.WorkspaceKey, session: session.SessionId, cwd: []const u8 },
    /// The prompts view lists the file at `path` with `size` bytes.
    prompts_item_size: struct { path: []const u8, size: u64 },
    /// The editor the prompts view opened has exited.
    prompts_editor_closed,
    /// The prompts view follows a new agent in place of `old` (a restart).
    prompts_agent_replaced: agent.AgentId,
};

const AgentOsTrace = struct {
    calls: usize = 0,

    fn record(context: ?*anyopaque, title: []const u8, body: []const u8) void {
        _ = title;
        _ = body;
        const self: *AgentOsTrace = @ptrCast(@alignCast(context.?));
        self.calls += 1;
    }
};

fn agentWaitMet(self: *App, trace: *const AgentOsTrace, condition: AgentWait) bool {
    return switch (condition) {
        .terminal_text => |text| self.activeLive().terminal().visibleTextContains(text),
        .element => |id| self.ui_tree.byId(.{ .value = id }) != null,
        .element_absent => |id| self.ui_tree.byId(.{ .value = id }) == null,
        .entries => |count| self.agents.notifications.count() >= count,
        .entry_body => |text| agentEntryIndex(self, text) != null,
        .os_calls => |count| trace.calls >= count,
        .reloads => |count| self.config_reload_count >= count,
        .active_tab => |id| self.activeWorkspace().activeTabId() == id,
        .active_workspace => |key| self.workspace_registry.activeKey() == key,
        .label => |want| if (self.ui_tree.byId(.{ .value = want.id })) |element| std.mem.indexOf(u8, element.label, want.text) != null else false,
        .role_label => |want| viewElement(self, want.prefix, want.text) != null,
        .fake_input => |want| fake: {
            const runner = self.agents.runnerForAgent(want.agent) orelse break :fake false;
            if (runner.backend != .fake) break :fake false;
            break :fake std.mem.indexOf(u8, runner.backend.fake.input(), want.text) != null;
        },
        .child_running => |want| running: {
            const model = self.workspace_registry.byKey(want.key) orelse break :running false;
            const live = model.sessionById(want.session) orelse break :running false;
            const child = live.child() orelse break :running false;
            break :running child.state() == .running;
        },
        .session_cwd => |want| cwd: {
            const model = self.workspace_registry.byKey(want.key) orelse break :cwd false;
            const live = model.sessionById(want.session) orelse break :cwd false;
            const actual = live.workingDirectory() orelse break :cwd false;
            break :cwd std.mem.eql(u8, actual, want.cwd);
        },
        .prompts_item_size => |want| promptsItemSize(self, want.path) == want.size and self.prompts_job == null,
        .prompts_editor_closed => self.prompts_editor == null,
        .prompts_agent_replaced => |old| if (self.prompts_agent) |current| current != old else false,
    };
}

/// The newest-first row index of the entry whose body contains `text`.
fn agentEntryIndex(self: *const App, text: []const u8) ?usize {
    for (0..self.agents.notifications.count()) |index| {
        const entry = self.agents.notifications.newest(index) orelse break;
        if (std.mem.indexOf(u8, entry.body(), text) != null) return index;
    }
    return null;
}

fn waitForAgent(self: *App, io: Io, out: *Writer, trace: *const AgentOsTrace, condition: AgentWait) !bool {
    const deadline = Io.Clock.real.now(io).nanoseconds + agent_test_budget_ms * std.time.ns_per_ms;
    while (true) {
        if (self.scheduler.shouldDraw()) try self.drawFrame();
        if (agentWaitMet(self, trace, condition)) return true;
        const event = self.window.pump(@min(self.waitBudget(io, deadline), 50));
        if (event) |one| {
            describeEvent(out, one) catch {};
            if (!try self.handle(one)) return false;
        }
        if (self.poll()) self.scheduler.invalidate();
        if (Io.Clock.real.now(io).nanoseconds >= deadline) {
            if (self.scheduler.shouldDraw()) try self.drawFrame();
            return agentWaitMet(self, trace, condition);
        }
    }
}

fn agentCheck(out: *Writer, failures: *usize, ok: bool, comptime format: []const u8, args: anytype) void {
    out.print("agent-test: {s} " ++ format ++ "\n", .{if (ok) "ok  " else "FAIL"} ++ args) catch {};
    if (!ok) failures.* += 1;
}

fn agentTypeLine(self: *App, io: Io, out: *Writer, text: [:0]const u8) !bool {
    if (text.len != 0) {
        try self.window.postTextInput(text);
        if (!try pumpUntil(self, io, out, .text_input, self_test_event_budget_ms)) return false;
    }
    return postNamedKey(self, io, out, .enter, .{});
}

fn notificationsChordKey(self: *App, io: Io, out: *Writer) !bool {
    const mods: platform.Mods = switch (self.binding_profile) {
        .macos => .{ .shift = true, .super = true },
        .linux_windows => .{ .ctrl = true, .shift = true },
    };
    return postKey(self, io, out, 'n', mods);
}

/// The palette's choice row that offers `value` for `action_name`.
fn agentChoiceIndex(self: *const App, action_name: []const u8, value: []const u8) ?usize {
    const index = definitionIndex(self, action_name) orelse return null;
    const command = self.actions.definitions()[index].palette orelse return null;
    const values = switch (command.argument) {
        .choices => |choices| choices.values,
        else => return null,
    };
    for (values, 0..) |choice, choice_index| {
        if (std.mem.eql(u8, choice.value, value)) return choice_index;
    }
    return null;
}

/// Launch the fake agent through the palette by mouse: the hint, the
/// command row, the fake's choice row, then Enter on the empty prompt.
fn launchFakeAgentByMouse(self: *App, io: Io, out: *Writer) !bool {
    self.setAgentLaunchChoices();
    const choice = agentChoiceIndex(self, agent_launch_action, app_agents.fake_choice_value) orelse return false;
    if (!try clickPaletteCommand(self, io, out, agent_launch_action, choice)) return false;
    if (!(self.palette_step == .input and self.palette_step.input == self.agent_prompt_index)) return false;
    return postNamedKey(self, io, out, .enter, .{});
}

/// Exercise TASK-56 through real PTYs and SDL events: the fake agent's live
/// glyphs, the notification list by chord, palette, Enter and click, a
/// hot-reloaded switch, a background tab's OSC 777 and bell, and the OS seam.
fn agentTest(self: *App, io: Io, out: *Writer) !u8 {
    var failures: usize = 0;
    var os_trace: AgentOsTrace = .{};
    self.agents.notifier = .{ .context = &os_trace, .notify_fn = AgentOsTrace.record };
    defer self.agents.notifier = .{ .notify_fn = App.discardOsNotification };
    self.focus_override = true;
    defer self.focus_override = null;
    const trigger_dir = self.agentTestDir() orelse return 1;

    try self.drawFrame();
    const first_key = self.workspace_registry.activeKey() orelse return 1;
    const first_model = self.activeWorkspace();
    const first_tab = first_model.activeTabId() orelse return 1;
    agentCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .terminal_text = "AGENT-TEST-READY" }), "the first tab's real PTY peer became ready", .{});
    _ = try agentTypeLine(self, io, out, "later");
    agentCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .terminal_text = "ARMED" }), "the first tab armed its background notification", .{});

    // The palette offers the fake (and only detected harnesses), never the
    // scratchpad; a launch makes an agent tab with an idle glyph.
    self.setAgentLaunchChoices();
    const launch_command = self.actions.definitions()[self.agent_launch_index].palette.?.argument.choices;
    var scratch_offered = false;
    for (launch_command.values) |choice| {
        if (std.mem.indexOf(u8, choice.value, "scratch") != null or std.mem.indexOf(u8, choice.label, "Scratch") != null) scratch_offered = true;
    }
    agentCheck(out, &failures, agentChoiceIndex(self, agent_launch_action, app_agents.fake_choice_value) != null and !scratch_offered, "Agent: launch offers the fake harness and nothing that names the scratchpad", .{});
    agentCheck(out, &failures, try launchFakeAgentByMouse(self, io, out), "Agent: launch ran by mouse through the palette hint, the command row, the fake's choice and an empty prompt", .{});
    agentCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .element = "workspace.1.tab.2.agent.idle" }) and
        try waitForAgent(self, io, out, &os_trace, .{ .terminal_text = "FAKE-AGENT-READY" }), "the agent tab shows the idle glyph and its real process is running", .{});
    const agent_tab = first_model.activeTabId() orelse return 1;
    const agent_session = first_model.focusedPaneSessionId(agent_tab) orelse return 1;
    agentCheck(out, &failures, first_model.sessionKind(agent_session) == .agent_terminal and agent_tab != first_tab, "the agent runs in a new agent_terminal session and tab", .{});

    // Each typed line releases one step of the scripted adapter.
    _ = try agentTypeLine(self, io, out, "one");
    agentCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .element = "workspace.1.tab.2.agent.working" }) and
        try waitForAgent(self, io, out, &os_trace, .{ .element = "workspace.1.agent.working" }), "working: the tab and workspace glyphs changed live", .{});
    _ = try agentTypeLine(self, io, out, "two");
    agentCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .element = "workspace.1.tab.2.agent.waiting_permission" }) and
        try waitForAgent(self, io, out, &os_trace, .{ .element = "workspace.1.agent.waiting_permission" }) and
        try waitForAgent(self, io, out, &os_trace, .{ .entry_body = "Run: make test" }), "waiting for permission: glyphs changed and a permission notification was listed", .{});
    agentCheck(out, &failures, os_trace.calls == 0, "a focused window raised no OS notification", .{});

    self.focus_override = false;
    _ = try agentTypeLine(self, io, out, "three");
    agentCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .element = "workspace.1.tab.2.agent.done" }) and
        try waitForAgent(self, io, out, &os_trace, .{ .os_calls = 1 }), "done: the glyph changed and an unfocused window raised one OS notification", .{});

    // The background tab's OSC 777 and bell become terminal notifications.
    var trigger_buffer: [path_capacity]u8 = undefined;
    const trigger = try std.fmt.bufPrint(&trigger_buffer, "{s}/trigger", .{trigger_dir});
    try Dir.cwd().writeFile(io, .{ .sub_path = trigger, .data = "go" });
    agentCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .entry_body = "background finished" }) and
        try waitForAgent(self, io, out, &os_trace, .{ .entry_body = "rang the bell" }), "a background tab's OSC 777 and bell were listed as terminal notifications", .{});
    agentCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .os_calls = 3 }), "both reached the OS seam while unfocused", .{});

    _ = try agentTypeLine(self, io, out, "four");
    agentCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .element = "workspace.1.tab.2.agent.errored" }) and
        try waitForAgent(self, io, out, &os_trace, .{ .element = "workspace.1.agent.errored" }), "errored: the glyphs changed", .{});

    // A second agent (idle) does not lower the workspace's most urgent glyph.
    agentCheck(out, &failures, try launchFakeAgentByMouse(self, io, out) and
        try waitForAgent(self, io, out, &os_trace, .{ .element = "workspace.1.tab.3.agent.idle" }) and
        self.ui_tree.byId(.{ .value = "workspace.1.agent.errored" }) != null, "with an idle second agent the workspace keeps the errored glyph", .{});

    // Agent choices list live agents and never the scratchpad.
    self.rebuildAgentChoices();
    var scratchpad_choice = false;
    for (self.agent_choices[0..self.agent_choice_count]) |choice| {
        const raw = std.fmt.parseInt(u64, choice.value, 10) catch continue;
        const record = self.agents.registry.get(@enumFromInt(raw)) orelse continue;
        if (record.session == first_model.scratchpadId()) scratchpad_choice = true;
    }
    agentCheck(out, &failures, self.agent_choice_count == 2 and !scratchpad_choice, "Agent: stop and Agent: focus list the two agents and never the scratchpad", .{});

    // A hot-reloaded switch suppresses that kind of entry.
    const path = self.config_path orelse return 1;
    const reloads = self.config_reload_count;
    try writeConfigTestFile(io, path, "notifications.permission = false\n");
    agentCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .reloads = reloads + 1 }) and
        !self.agents.settings.permission, "the settings file's notifications.permission = false applied by hot reload", .{});
    const entries_before = self.agents.notifications.count();
    const os_before = os_trace.calls;
    // Back to the first agent's tab by its sidebar row, then its next step.
    var tab_id_buffer: [workspace_semantic_capacity]u8 = undefined;
    _ = try clickTabsElement(self, io, out, try tabSemanticId(&tab_id_buffer, first_key, agent_tab));
    // The click focused the sidebar row; a click in the pane gives the
    // keyboard back to the terminal, as a person would.
    var pane_id_buffer: [pane_semantic_capacity]u8 = undefined;
    _ = try clickTabsElement(self, io, out, try paneSemanticId(&pane_id_buffer, first_key, first_model.focusedPaneId(agent_tab) orelse return 1));
    _ = try agentTypeLine(self, io, out, "five");
    const fifth_glyph = try waitForAgent(self, io, out, &os_trace, .{ .element = "workspace.1.tab.2.agent.waiting_permission" });
    agentCheck(out, &failures, fifth_glyph and self.agents.notifications.count() == entries_before and os_trace.calls == os_before, "a new permission wait changed the glyph but listed and raised nothing (glyph {}, entries {d}->{d}, os {d}->{d})", .{ fifth_glyph, entries_before, self.agents.notifications.count(), os_before, os_trace.calls });

    // The settings view's Agents group edits the same switch by keyboard.
    _ = try settingsChord(self, io, out);
    const settings_reloads = self.config_reload_count;
    const settings_open = try waitForAgent(self, io, out, &os_trace, .{ .element = "settings.dialog" });
    const row_selected = try selectSettingsRow(self, io, out, "settings.row.notifications.permission");
    _ = try postNamedKey(self, io, out, .enter, .{});
    agentCheck(out, &failures, settings_open and row_selected and
        try waitForAgent(self, io, out, &os_trace, .{ .reloads = settings_reloads + 1 }) and self.agents.settings.permission and
        std.mem.indexOf(u8, settingsLabel(self, "settings.row.notifications.permission"), "true") != null, "the settings view's Agents row turned notifications.permission back on", .{});
    _ = try postNamedKey(self, io, out, .escape, .{});
    agentCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .element_absent = "settings.dialog" }), "Escape closed the settings view", .{});

    // The list by chord; Enter focuses the newest entry's tab.
    _ = try clickTabsElement(self, io, out, try tabSemanticId(&tab_id_buffer, first_key, first_tab));
    agentCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .active_tab = first_tab }), "the first tab is active again", .{});
    _ = try notificationsChordKey(self, io, out);
    agentCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .element = "notifications" }) and
        self.ui_tree.byId(.{ .value = "notification.4" }) != null and
        std.mem.eql(u8, focusedMenuRow(self), "notification.0"), "the chord opened the list with every entry and the newest focused", .{});
    try self.drawFrame();
    const screenshot_pixels = try self.allocator.dupe(u8, try self.capture());
    defer self.allocator.free(screenshot_pixels);
    // A key the list does not use stays in the modal.
    const sent_before = first_model.sessionById(self.presentedSessionId()).?.pendingResponseBytes();
    _ = try postKey(self, io, out, 'x', .{});
    agentCheck(out, &failures, self.notificationsVisible() and first_model.sessionById(self.presentedSessionId()).?.pendingResponseBytes() == sent_before, "an unrelated key stayed inside the modal list", .{});
    _ = try postNamedKey(self, io, out, .enter, .{});
    agentCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .active_tab = agent_tab }) and !self.notificationsVisible() and
        self.agents.selected_agent != null, "Enter on the newest (error) entry focused the agent's tab and selected the agent", .{});

    // A second workspace; a click on the OSC entry returns to workspace 1's
    // first tab.
    _ = try runPaletteCommandByKeyboard(self, io, out, "Create workspace");
    _ = try agentTypeLine(self, io, out, "/tmp");
    const second_ok = try waitForAgent(self, io, out, &os_trace, .{ .element = "workspace.2" });
    const second_key = self.workspace_registry.activeKey() orelse return 1;
    agentCheck(out, &failures, second_ok and second_key != first_key, "a second workspace is active", .{});
    agentCheck(out, &failures, try clickPaletteCommand(self, io, out, notifications_open_action, null) and
        try waitForAgent(self, io, out, &os_trace, .{ .element = "notifications" }), "the palette opened the list by mouse", .{});
    const osc_row = agentEntryIndex(self, "background finished") orelse return 1;
    var row_buffer: [palette_semantic_capacity]u8 = undefined;
    _ = try clickTabsElement(self, io, out, try std.fmt.bufPrint(&row_buffer, "notification.{d}", .{osc_row}));
    agentCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .active_workspace = first_key }) and
        try waitForAgent(self, io, out, &os_trace, .{ .active_tab = first_tab }) and !self.notificationsVisible(), "a click on the OSC 777 entry focused workspace 1 and the tab that sent it", .{});

    // Escape closes; clear empties the list.
    _ = try notificationsChordKey(self, io, out);
    _ = try waitForAgent(self, io, out, &os_trace, .{ .element = "notifications" });
    _ = try postNamedKey(self, io, out, .escape, .{});
    agentCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .element_absent = "notifications" }), "Escape closed the list", .{});
    _ = try runPaletteCommandByKeyboard(self, io, out, "Notifications: clear");
    agentCheck(out, &failures, self.agents.notifications.count() == 0, "Notifications: clear emptied the list", .{});

    // A harness started by hand in the human's own terminal is detected from
    // the PTY's foreground process and observed on that tab (TASK-56,
    // TASK-78), and ends when it leaves the foreground.
    var fake_path_buffer: [path_capacity]u8 = undefined;
    const fake_path = try std.fmt.bufPrint(&fake_path_buffer, "{s}/{s}", .{ trigger_dir, agent.fake_command_name });
    try Dir.cwd().writeFile(io, .{ .sub_path = fake_path, .data = observed_fake_script });
    const first_session = first_model.focusedPaneSessionId(first_tab) orelse return 1;
    agentCheck(out, &failures, !self.agents.hasAgent(first_key, first_session) and first_model.sessionKind(first_session) == .human_terminal, "the first tab is a human terminal without an agent", .{});
    _ = try agentTypeLine(self, io, out, "fake");
    agentCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .terminal_text = "OBSERVED-FAKE-READY" }), "the hand-started conduit-fake-agent is running in the first tab", .{});
    const observed_glyph = try waitForAgent(self, io, out, &os_trace, .{ .role_label = .{ .prefix = "workspace.1.tab.1.agent.", .text = "" } });
    const observed = self.agents.agentForSession(first_key, first_session);
    agentCheck(out, &failures, observed_glyph and observed != null and observed.?.ownership == .observed and
        std.mem.eql(u8, self.agents.displayName(observed.?), "Fake agent"), "it was detected and attached as an observed agent with a glyph on the human tab", .{});
    _ = try agentTypeLine(self, io, out, "bye");
    agentCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .terminal_text = "FAKE-BACK" }) and
        try waitForAgent(self, io, out, &os_trace, .{ .element = "workspace.1.tab.1.agent.done" }) and
        !self.agents.hasAgent(first_key, first_session), "it ended when the script exited: the tab shows done and the session has no live agent", .{});

    var screenshot_path_buffer: [path_capacity]u8 = undefined;
    var id_buffer: [path_capacity]u8 = undefined;
    const screenshot_path = try std.fmt.bufPrint(&screenshot_path_buffer, "{s}{c}agent-test-{s}.png", .{ fallback_log_dir, std.fs.path.sep, try generateRunId(io, &id_buffer) });
    try writePngOffThread(self.allocator, io, screenshot_path, screenshot_pixels, self.size);
    out.print("agent-test: screenshot {s}\n", .{screenshot_path}) catch {};
    out.print("agent-test: {d} failure(s)\n", .{failures}) catch {};
    out.flush() catch {};
    return if (failures == 0) 0 else 1;
}

// --agent-manager-test (TASK-58) -----------------------------------------------

fn managerCheck(out: *Writer, failures: *usize, ok: bool, comptime format: []const u8, args: anytype) void {
    out.print("agent-manager-test: {s} " ++ format ++ "\n", .{if (ok) "ok  " else "FAIL"} ++ args) catch {};
    if (!ok) failures.* += 1;
}

fn agentsManagerChordKey(self: *App, io: Io, out: *Writer) !bool {
    const mods: platform.Mods = switch (self.binding_profile) {
        .macos => .{ .shift = true, .super = true },
        .linux_windows => .{ .ctrl = true, .shift = true },
    };
    return postKey(self, io, out, 'g', mods);
}

/// The id of agent `id`'s manager row (or one of its controls).
fn managerRowId(buffer: []u8, id: agent.AgentId, control: ?[]const u8) []const u8 {
    if (control) |name| return std.fmt.bufPrint(buffer, "agents.row.{d}.{s}", .{ @intFromEnum(id), name }) catch "";
    return std.fmt.bufPrint(buffer, "agents.row.{d}", .{@intFromEnum(id)}) catch "";
}

fn managerRowSelected(self: *App, id: agent.AgentId) bool {
    var buffer: [manager_id_capacity]u8 = undefined;
    const element = self.ui_tree.byId(.{ .value = managerRowId(&buffer, id, null) }) orelse return false;
    return element.state.selected;
}

fn managerRowY(self: *App, id: agent.AgentId) ?i32 {
    var buffer: [manager_id_capacity]u8 = undefined;
    const element = self.ui_tree.byId(.{ .value = managerRowId(&buffer, id, null) }) orelse return null;
    return element.bounds.y;
}

/// The agent of the presented session, once it is registered.
fn presentedAgentId(self: *App) ?agent.AgentId {
    const record = self.agents.agentForSession(self.activePresentation().key, self.presentedSessionId()) orelse return null;
    return record.id;
}

/// Exercise TASK-58 through real PTYs and SDL events: two workspaces with a
/// fake agent each, the manager by chord and by palette, live rows, focus by
/// Enter and by click, a message by keyboard, stop, restart and a new agent
/// spawned by mouse through the chooser rows, modal isolation and Escape.
fn agentManagerTest(self: *App, io: Io, out: *Writer) !u8 {
    var failures: usize = 0;
    var os_trace: AgentOsTrace = .{};
    self.focus_override = true;
    defer self.focus_override = null;

    try self.drawFrame();
    const first_key = self.workspace_registry.activeKey() orelse return 1;
    const first_model = self.activeWorkspace();
    const first_tab = first_model.activeTabId() orelse return 1;
    managerCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .terminal_text = "AGENT-TEST-READY" }), "the first tab's real PTY peer became ready", .{});

    // Agent one in workspace 1, stepped to working.
    managerCheck(out, &failures, try launchFakeAgentByMouse(self, io, out) and
        try waitForAgent(self, io, out, &os_trace, .{ .terminal_text = "FAKE-AGENT-READY" }), "the first fake agent launched in workspace 1", .{});
    const first_agent = presentedAgentId(self) orelse return 1;
    const first_agent_tab = first_model.activeTabId() orelse return 1;
    _ = try agentTypeLine(self, io, out, "one");
    managerCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .element = "workspace.1.tab.2.agent.working" }), "the first agent is working", .{});

    // A second workspace with agent two, idle.
    _ = try runPaletteCommandByKeyboard(self, io, out, "Create workspace");
    _ = try agentTypeLine(self, io, out, "/tmp");
    managerCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .element = "workspace.2" }) and
        self.workspace_registry.activeKey() != first_key, "a second workspace is active", .{});
    const second_key = self.workspace_registry.activeKey() orelse return 1;
    const second_model = self.activeWorkspace();
    // Its first tab is a plain shell, started on a worker; output it
    // computes proves it runs.
    _ = try waitForAgent(self, io, out, &os_trace, .{ .child_running = .{ .key = second_key, .session = self.activePresentation().active_session_id } });
    _ = try agentTypeLine(self, io, out, "printf 'W2-%s\\n' READY");
    managerCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .terminal_text = "W2-READY" }), "workspace 2's first tab's shell is running", .{});
    managerCheck(out, &failures, try launchFakeAgentByMouse(self, io, out) and
        try waitForAgent(self, io, out, &os_trace, .{ .terminal_text = "FAKE-AGENT-READY" }), "the second fake agent launched in workspace 2", .{});
    const second_agent = presentedAgentId(self) orelse return 1;
    const second_agent_tab = second_model.activeTabId() orelse return 1;
    const second_session = second_model.focusedPaneSessionId(second_agent_tab) orelse return 1;

    // The manager by chord: both agents, workspace 1 first, live state.
    var row_buffer: [manager_id_capacity]u8 = undefined;
    var control_buffer: [manager_id_capacity]u8 = undefined;
    _ = try agentsManagerChordKey(self, io, out);
    const opened = try waitForAgent(self, io, out, &os_trace, .{ .element = "agents.dialog" });
    const first_row = managerRowId(&row_buffer, first_agent, null);
    managerCheck(out, &failures, opened and try waitForAgent(self, io, out, &os_trace, .{ .label = .{ .id = first_row, .text = "Fake agent" } }) and
        try waitForAgent(self, io, out, &os_trace, .{ .label = .{ .id = first_row, .text = "working" } }), "the chord opened the manager with agent one working", .{});
    var first_label_buffer: [tab_name_capacity + 8]u8 = undefined;
    const first_location = std.fmt.bufPrint(&first_label_buffer, "{s} › ", .{first_model.name()}) catch "";
    managerCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .label = .{ .id = first_row, .text = first_location } }) and
        try waitForAgent(self, io, out, &os_trace, .{ .label = .{ .id = first_row, .text = "  –  " } }), "agent one's row names its workspace and tab and leaves the task slot empty", .{});
    const second_row = managerRowId(&control_buffer, second_agent, null);
    var second_label_buffer: [tab_name_capacity + 8]u8 = undefined;
    const second_location = std.fmt.bufPrint(&second_label_buffer, "{s} › ", .{second_model.name()}) catch "";
    managerCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .label = .{ .id = second_row, .text = "idle" } }) and
        try waitForAgent(self, io, out, &os_trace, .{ .label = .{ .id = second_row, .text = second_location } }), "agent two's row is idle in workspace 2", .{});
    const first_y = managerRowY(self, first_agent);
    const second_y = managerRowY(self, second_agent);
    managerCheck(out, &failures, first_y != null and second_y != null and first_y.? < second_y.?, "rows follow sidebar order: workspace 1's agent first", .{});
    var scratch_listed = false;
    for (self.manager_order[0..self.manager_count]) |id| {
        const record = self.agents.registry.get(id) orelse continue;
        const model = self.workspace_registry.byKey(record.workspace) orelse continue;
        if (record.session == model.scratchpadId()) scratch_listed = true;
    }
    managerCheck(out, &failures, self.manager_count == 2 and !scratch_listed, "the manager lists two agents and never a scratchpad", .{});
    managerCheck(out, &failures, managerRowSelected(self, second_agent), "the presented agent is highlighted on open", .{});

    // A transition while the manager is open: agent two's process takes a
    // step (the fake's script counts the bytes its shell appends).
    const second_runner = self.agents.runnerForAgent(second_agent) orelse return 1;
    var steps_buffer: [path_capacity]u8 = undefined;
    const steps_path = try std.fmt.bufPrint(&steps_buffer, "{s}/steps", .{second_runner.sink_dir});
    try Dir.cwd().writeFile(io, .{ .sub_path = steps_path, .data = "x" });
    managerCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .label = .{ .id = second_row, .text = "working" } }), "agent two's row changed to working while the manager was open", .{});

    // Modal isolation: an unused key and a bound chord do nothing beneath.
    const presented = second_model.sessionById(self.presentedSessionId()) orelse return 1;
    const sent_before = presented.pendingResponseBytes();
    const routes_before = self.terminal_key_route_count;
    const tabs_before = second_model.tabCount();
    _ = try postKey(self, io, out, 'x', .{});
    _ = try postKey(self, io, out, 't', switch (self.binding_profile) {
        .macos => .{ .super = true },
        .linux_windows => .{ .ctrl = true, .shift = true },
    });
    managerCheck(out, &failures, self.managerVisible() and presented.pendingResponseBytes() == sent_before and
        self.terminal_key_route_count == routes_before and second_model.tabCount() == tabs_before, "an unused key and the new-tab chord stayed inside the manager", .{});

    // Keyboard highlight: Home, End.
    _ = try postNamedKey(self, io, out, .home, .{});
    managerCheck(out, &failures, managerRowSelected(self, first_agent), "Home highlighted agent one", .{});
    _ = try postNamedKey(self, io, out, .end, .{});
    managerCheck(out, &failures, managerRowSelected(self, second_agent), "End highlighted agent two", .{});

    // A message by keyboard, without leaving the manager.
    _ = try postKey(self, io, out, 'm', .{});
    const field = self.ui_tree.byId(.{ .value = "agents.input" });
    managerCheck(out, &failures, field != null and field.?.state.focused, "m opened the focused message field under agent two", .{});
    _ = try agentTypeLine(self, io, out, "hello agent");
    managerCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .fake_input = .{ .agent = second_agent, .text = "hello agent" } }) and
        self.managerVisible() and self.ui_tree.byId(.{ .value = "agents.input" }) == null and
        try waitForAgent(self, io, out, &os_trace, .{ .label = .{ .id = "agents.status", .text = "sent to Fake agent" } }), "Enter sent the message through the worker to the adapter and the manager stayed open", .{});

    // Stop by key: the row shows exited and offers restart.
    _ = try postKey(self, io, out, 's', .{});
    managerCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .label = .{ .id = second_row, .text = "exited" } }) and
        try waitForAgent(self, io, out, &os_trace, .{ .element = managerRowId(&row_buffer, second_agent, "restart") }), "s stopped agent two: its row shows exited and a restart control", .{});

    // Restart by key: a new agent id bound to the same tab replaces the row.
    _ = try postKey(self, io, out, 'r', .{});
    const restarted = second_model.paneForSession(second_session) != null and self.agents.registry.findBySession(second_key, second_session) != null;
    const third_agent = self.agents.registry.findBySession(second_key, second_session) orelse second_agent;
    const third_row = managerRowId(&row_buffer, third_agent, null);
    managerCheck(out, &failures, restarted and third_agent != second_agent and
        try waitForAgent(self, io, out, &os_trace, .{ .element_absent = second_row }) and
        try waitForAgent(self, io, out, &os_trace, .{ .label = .{ .id = third_row, .text = "idle" } }) and
        second_model.paneForSession(second_session).?.tab_id == second_agent_tab, "r restarted agent two as agent {d} in the same tab", .{@intFromEnum(third_agent)});
    managerCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .child_running = .{ .key = second_key, .session = second_session } }) and
        try waitForAgent(self, io, out, &os_trace, .{ .terminal_text = "FAKE-AGENT-READY" }) and
        try waitForAgent(self, io, out, &os_trace, .{ .label = .{ .id = third_row, .text = second_location } }), "the restarted agent's new process is running in workspace 2", .{});

    // Focus by Enter: agent one's workspace and tab.
    _ = try postNamedKey(self, io, out, .home, .{});
    _ = try postNamedKey(self, io, out, .enter, .{});
    managerCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .active_workspace = first_key }) and
        try waitForAgent(self, io, out, &os_trace, .{ .active_tab = first_agent_tab }) and !self.managerVisible(), "Enter focused agent one: workspace 1 and its tab", .{});

    // The manager from the palette by mouse; a click on agent three's row.
    managerCheck(out, &failures, try clickPaletteCommand(self, io, out, agents_open_action, null) and
        try waitForAgent(self, io, out, &os_trace, .{ .element = "agents.dialog" }), "the palette opened the manager by mouse", .{});
    _ = try clickTabsElement(self, io, out, third_row);
    managerCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .active_workspace = second_key }) and
        try waitForAgent(self, io, out, &os_trace, .{ .active_tab = second_agent_tab }) and !self.managerVisible(), "a click on agent {d}'s row focused workspace 2 and its tab", .{@intFromEnum(third_agent)});

    // A new agent by mouse: new, the fake's row, workspace 1, launch.
    _ = try agentsManagerChordKey(self, io, out);
    _ = try waitForAgent(self, io, out, &os_trace, .{ .element = "agents.dialog" });
    _ = try clickTabsElement(self, io, out, "agents.new");
    managerCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .label = .{ .id = "agents.new.harness.0", .text = app_agents.fake_choice_label } }), "new listed the fake harness first", .{});
    _ = try clickTabsElement(self, io, out, "agents.new.harness.0");
    managerCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .label = .{ .id = "agents.new.workspace.0", .text = first_model.name() } }) and
        self.ui_tree.byId(.{ .value = "agents.new.workspace.1" }) != null, "the workspace step lists both open workspaces", .{});
    _ = try clickTabsElement(self, io, out, "agents.new.workspace.0");
    managerCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .element = "agents.input" }) and
        try waitForAgent(self, io, out, &os_trace, .{ .element = "agents.new.launch" }), "the prompt step shows its field and launch control", .{});
    const tabs_in_first = first_model.tabCount();
    const before_ordinal = self.agents.registry.next_ordinal;
    _ = try clickTabsElement(self, io, out, "agents.new.launch");
    const fourth_agent = agent.AgentId.fromOrdinal(before_ordinal);
    const fourth_row = managerRowId(&row_buffer, fourth_agent, null);
    managerCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .label = .{ .id = fourth_row, .text = first_location } }) and
        first_model.tabCount() == tabs_in_first + 1 and self.workspace_registry.activeKey() == first_key and self.managerVisible() and
        managerRowSelected(self, fourth_agent), "launch spawned agent {d} into a new tab of workspace 1 and its row appeared highlighted", .{@intFromEnum(fourth_agent)});
    managerCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .terminal_text = "FAKE-AGENT-READY" }), "the new agent's real process is running", .{});
    managerCheck(out, &failures, self.manager_count == 3, "three agents are listed", .{});

    try self.drawFrame();
    const screenshot_pixels = try self.allocator.dupe(u8, try self.capture());
    defer self.allocator.free(screenshot_pixels);

    // Escape closes; the first tab is still where it was.
    _ = try postNamedKey(self, io, out, .escape, .{});
    managerCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .element_absent = "agents.dialog" }) and
        first_model.tab(first_tab) != null, "Escape closed the manager", .{});

    var screenshot_path_buffer: [path_capacity]u8 = undefined;
    var id_buffer: [path_capacity]u8 = undefined;
    const screenshot_path = try std.fmt.bufPrint(&screenshot_path_buffer, "{s}{c}agent-manager-test-{s}.png", .{ fallback_log_dir, std.fs.path.sep, try generateRunId(io, &id_buffer) });
    try writePngOffThread(self.allocator, io, screenshot_path, screenshot_pixels, self.size);
    out.print("agent-manager-test: screenshot {s}\n", .{screenshot_path}) catch {};
    out.print("agent-manager-test: {d} failure(s)\n", .{failures}) catch {};
    out.flush() catch {};
    return if (failures == 0) 0 else 1;
}

// --agent-prompts-test (TASK-59) -------------------------------------------------

fn promptsCheck(out: *Writer, failures: *usize, ok: bool, comptime format: []const u8, args: anytype) void {
    out.print("agent-prompts-test: {s} " ++ format ++ "\n", .{if (ok) "ok  " else "FAIL"} ++ args) catch {};
    out.flush() catch {};
    if (!ok) failures.* += 1;
}

/// The first tab of `--agent-prompts-test` claims the fixture project as
/// its cwd with OSC 7 (beside the agent-test trigger), then runs
/// `--agent-test`'s loop, so an agent launched from it starts there.
const agent_prompts_test_script =
    "d=$(dirname \"$" ++ agent_test_trigger_env ++ "\")/project; " ++
    "printf '\\033]7;file://localhost%s\\007' \"$d\"; " ++ agent_test_script;

const prompts_test_prompt = "TASK-9: tidy the project rules";

/// The row of the open prompts view whose label contains `text`.
fn promptsRow(self: *const App, text: []const u8) ?*const ui.Element {
    const id = self.prompts_agent orelse return null;
    var prefix_buffer: [prompts_id_capacity]u8 = undefined;
    const prefix = std.fmt.bufPrint(&prefix_buffer, "agent.prompts.{d}.item.", .{@intFromEnum(id)}) catch return null;
    return viewElement(self, prefix, text);
}

/// The listed size of the file item at `path`.
fn promptsItemSize(self: *const App, path: []const u8) ?u64 {
    const list = &(self.prompts_list orelse return null);
    const item = list.fileAt(path) orelse return null;
    return item.size;
}

/// Exercise TASK-59 through real PTYs and SDL events: the fake agent
/// (impersonating Claude Code) launched with a prompt in a fixture project,
/// its prompts view opened from the palette and from the agent view's row,
/// every row's editability and reason, an editable file opened in vi in a
/// new tab and saved, the row refreshed when the editor exits, a harness-owned
/// file opened read-only, "restart with updated instructions" restarting the
/// agent with its task, and modal isolation.
fn agentPromptsTest(self: *App, io: Io, out: *Writer) !u8 {
    var failures: usize = 0;
    var os_trace: AgentOsTrace = .{};
    self.agents.notifier = .{ .context = &os_trace, .notify_fn = AgentOsTrace.record };
    defer self.agents.notifier = .{ .notify_fn = App.discardOsNotification };
    var editor_trace: EditorSpawnTrace = .{};
    self.editor_spawn_observer = .{ .context = &editor_trace, .observe_fn = recordEditorSpawn };
    defer self.editor_spawn_observer = .{};
    const test_dir = self.agentTestDir() orelse return 1;

    // The fixture: a project with Claude Code's files and an AGENTS.md
    // Claude Code does not read, and a private home with a user file.
    var paths: [8][path_capacity]u8 = undefined;
    const project = try std.fmt.bufPrint(&paths[0], "{s}/project", .{test_dir});
    const home = try std.fmt.bufPrint(&paths[1], "{s}/home", .{test_dir});
    const claude_md = try std.fmt.bufPrint(&paths[2], "{s}/CLAUDE.md", .{project});
    const reviewer = try std.fmt.bufPrint(&paths[3], "{s}/.claude/agents/reviewer.md", .{project});
    const settings = try std.fmt.bufPrint(&paths[4], "{s}/.claude/settings.json", .{project});
    const agents_md = try std.fmt.bufPrint(&paths[5], "{s}/AGENTS.md", .{project});
    const user_md = try std.fmt.bufPrint(&paths[6], "{s}/.claude/CLAUDE.md", .{home});
    try Dir.cwd().createDirPath(io, std.fs.path.dirnamePosix(reviewer).?);
    try Dir.cwd().createDirPath(io, std.fs.path.dirnamePosix(user_md).?);
    const claude_text = "# Project rules\n\nBe brief.\n";
    try Dir.cwd().writeFile(io, .{ .sub_path = claude_md, .data = claude_text });
    try Dir.cwd().writeFile(io, .{ .sub_path = reviewer, .data = "---\nname: reviewer\n---\nReview every diff.\n" });
    try Dir.cwd().writeFile(io, .{ .sub_path = settings, .data = "{}\n" });
    try Dir.cwd().writeFile(io, .{ .sub_path = agents_md, .data = "# Codex rules\n" });
    try Dir.cwd().writeFile(io, .{ .sub_path = user_md, .data = "# Mine\n" });
    // The user-level files are looked for in the check's own home, never the
    // person's.
    const saved_home = self.home_dir;
    self.home_dir = home;
    defer self.home_dir = saved_home;

    try self.drawFrame();
    const model = self.activeWorkspace();
    const key = self.workspace_registry.activeKey() orelse return 1;
    const first_tab = model.activeTabId() orelse return 1;
    const first_session = model.focusedPaneSessionId(first_tab) orelse return 1;
    promptsCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .terminal_text = "AGENT-TEST-READY" }), "the first tab's real PTY peer became ready", .{});
    const cwd_ok = try waitForAgent(self, io, out, &os_trace, .{ .session_cwd = .{ .key = key, .session = first_session, .cwd = project } });
    promptsCheck(out, &failures, cwd_ok, "the first tab's OSC 7 made the fixture project its cwd", .{});

    // The fake agent, launched by keyboard through the palette with a prompt.
    _ = try paletteChord(self, io, out);
    _ = try postPaletteText(self, io, out, "Agent: launch");
    _ = try postNamedKey(self, io, out, .enter, .{});
    _ = try postNamedKey(self, io, out, .enter, .{});
    _ = try postPaletteText(self, io, out, prompts_test_prompt);
    _ = try postNamedKey(self, io, out, .enter, .{});
    promptsCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .element = "workspace.1.tab.2.agent.idle" }) and
        try waitForAgent(self, io, out, &os_trace, .{ .terminal_text = "FAKE-AGENT-READY" }), "the fake agent launched with a prompt in its own tab", .{});
    const agent_tab = model.activeTabId() orelse return 1;
    const agent_session = model.focusedPaneSessionId(agent_tab) orelse return 1;
    const first_runner = self.agents.runnerForSession(key, agent_session) orelse return 1;
    const first_agent = first_runner.agent_id orelse return 1;
    promptsCheck(out, &failures, std.mem.eql(u8, first_runner.cwd, project) and
        std.mem.eql(u8, first_runner.prompt orelse "", prompts_test_prompt), "it started in the fixture project with the typed prompt", .{});
    _ = try agentTypeLine(self, io, out, "go");
    promptsCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .element = "workspace.1.tab.2.agent.done" }), "one step released the human's message and the end of the turn", .{});

    // AC1 by palette: every row says what it is and whether it can change.
    _ = try paletteChord(self, io, out);
    _ = try postPaletteText(self, io, out, "Agent: prompts");
    _ = try postNamedKey(self, io, out, .enter, .{});
    var dialog_buffer: [prompts_id_capacity]u8 = undefined;
    const dialog_id = try std.fmt.bufPrint(&dialog_buffer, "agent.prompts.{d}", .{@intFromEnum(first_agent)});
    promptsCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .element = dialog_id }) and
        try waitForAgent(self, io, out, &os_trace, .{ .role_label = .{ .prefix = "agent.prompts.", .text = "CLAUDE.md" } }), "Agent: prompts and instructions opened {s} from the palette", .{dialog_id});
    const expected_rows = [_]struct { name: []const u8, tail: []const u8 }{
        .{ .name = "▤ CLAUDE.md", .tail = "  editable" },
        .{ .name = "▤ ~/.claude/CLAUDE.md", .tail = "  editable" },
        .{ .name = "◆ .claude/agents/reviewer.md", .tail = "  editable" },
        .{ .name = "⚙ .claude/settings.json", .tail = "read-only · harness-owned" },
        .{ .name = "· system prompt", .tail = "read-only · not exposed by this harness" },
        .{ .name = "launch › " ++ prompts_test_prompt, .tail = "read-only · sent" },
        .{ .name = "you › " ++ app_agents.fake_prompts_message, .tail = "read-only · sent" },
    };
    for (expected_rows) |row| {
        const element = promptsRow(self, row.name);
        promptsCheck(out, &failures, element != null and std.mem.endsWith(u8, element.?.label, row.tail), "a row '{s}' ending '{s}'", .{ row.name, row.tail });
    }
    promptsCheck(out, &failures, promptsRow(self, "AGENTS.md") == null, "AGENTS.md, which Claude Code does not read, is not listed", .{});
    var apply_buffer: [prompts_id_capacity]u8 = undefined;
    const apply_id = try std.fmt.bufPrint(&apply_buffer, "agent.prompts.{d}.apply", .{@intFromEnum(first_agent)});
    promptsCheck(out, &failures, if (self.ui_tree.byId(.{ .value = apply_id })) |element|
        std.mem.eql(u8, element.label, prompts_apply_label) and element.primitive.isInteractive()
    else
        false, "Claude Code offers '{s}' as its apply action", .{prompts_apply_label});
    try self.drawFrame();
    const screenshot_pixels = try self.allocator.dupe(u8, try self.capture());
    defer self.allocator.free(screenshot_pixels);

    // Modal isolation: an unused key and the new-tab chord do nothing beneath.
    const presented = model.sessionById(self.presentedSessionId()) orelse return 1;
    const sent_before = presented.pendingResponseBytes();
    const routes_before = self.terminal_key_route_count;
    const tabs_before = model.tabCount();
    _ = try postKey(self, io, out, 'x', .{});
    _ = try postKey(self, io, out, 't', switch (self.binding_profile) {
        .macos => .{ .super = true },
        .linux_windows => .{ .ctrl = true, .shift = true },
    });
    promptsCheck(out, &failures, self.promptsVisible() and presented.pendingResponseBytes() == sent_before and
        self.terminal_key_route_count == routes_before and model.tabCount() == tabs_before, "an unused key and the new-tab chord stayed inside the view", .{});
    _ = try postNamedKey(self, io, out, .escape, .{});
    promptsCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .element_absent = dialog_id }), "Escape closed the view", .{});

    // AC1 from the agent view: its prompts row, clicked.
    _ = try viewChordKey(self, io, out, 'a');
    var row_buffer: [agent_view_id_capacity]u8 = undefined;
    const prompts_row = try std.fmt.bufPrint(&row_buffer, "agent.view.{d}.prompts", .{@intFromEnum(first_agent)});
    promptsCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .label = .{ .id = prompts_row, .text = agent_view.prompts_row_label } }), "the agent view leads with its prompts row", .{});
    _ = try clickTabsElement(self, io, out, prompts_row);
    promptsCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .element = dialog_id }) and
        try waitForAgent(self, io, out, &os_trace, .{ .role_label = .{ .prefix = "agent.prompts.", .text = "CLAUDE.md" } }), "a click on the row opened the same view", .{});

    // AC2: Enter on CLAUDE.md opens vi on it in a new tab; an edit saved
    // there is the row's new size once the editor exits.
    _ = try postNamedKey(self, io, out, .home, .{});
    const tabs_before_edit = model.tabCount();
    _ = try postNamedKey(self, io, out, .enter, .{});
    var argv_buffer: [path_capacity + 16]u8 = undefined;
    const expected_argv = try std.fmt.bufPrint(&argv_buffer, "vi -- {s}", .{claude_md});
    promptsCheck(out, &failures, !self.promptsVisible() and editor_trace.calls == 1 and std.mem.eql(u8, editor_trace.argv(), expected_argv) and
        model.tabCount() == tabs_before_edit + 1, "Enter opened '{s}' in a new tab through the workspace context", .{editor_trace.argv()});
    promptsCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .terminal_text = "Be brief." }), "vi shows the file", .{});
    _ = try agentTypeKeys(self, io, out, "Go");
    _ = try agentTypeKeys(self, io, out, "Edited in Conduit.");
    _ = try postNamedKey(self, io, out, .escape, .{});
    _ = try agentTypeKeys(self, io, out, ":wq");
    _ = try postNamedKey(self, io, out, .enter, .{});
    const edited_size = claude_text.len + "Edited in Conduit.\n".len;
    promptsCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .prompts_item_size = .{ .path = claude_md, .size = edited_size } }), "the editor's exit re-read the list: CLAUDE.md is now {d} bytes", .{edited_size});
    var read_buffer: [256]u8 = undefined;
    const saved = Dir.cwd().readFile(io, claude_md, &read_buffer) catch "";
    promptsCheck(out, &failures, std.mem.endsWith(u8, saved, "Be brief.\nEdited in Conduit.\n"), "the file holds the edit", .{});

    // Reopen by palette: the row shows the new size.
    _ = try clickTabsElement(self, io, out, "workspace.1.tab.2");
    _ = try waitForAgent(self, io, out, &os_trace, .{ .active_tab = agent_tab });
    _ = try paletteChord(self, io, out);
    _ = try postPaletteText(self, io, out, "Agent: prompts");
    _ = try postNamedKey(self, io, out, .enter, .{});
    var size_buffer: [24]u8 = undefined;
    var size_text_buffer: [48]u8 = undefined;
    const size_text = try std.fmt.bufPrint(&size_text_buffer, "{s}  editable", .{agent_prompts.formatSize(&size_buffer, edited_size)});
    promptsCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .element = dialog_id }) and
        try waitForAgent(self, io, out, &os_trace, .{ .role_label = .{ .prefix = "agent.prompts.", .text = size_text } }), "the reopened view lists CLAUDE.md at '{s}'", .{size_text});

    // AC3: the harness-owned settings file opens read-only (`vi -R`).
    const settings_row = promptsRow(self, "⚙ .claude/settings.json");
    var settings_id: [prompts_id_capacity]u8 = undefined;
    const settings_id_text = if (settings_row) |element| try std.fmt.bufPrint(&settings_id, "{s}", .{element.id.value}) else "";
    _ = try clickTabsElement(self, io, out, settings_id_text);
    var view_argv_buffer: [path_capacity + 16]u8 = undefined;
    const view_argv = try std.fmt.bufPrint(&view_argv_buffer, "vi -R -- {s}", .{settings});
    promptsCheck(out, &failures, editor_trace.calls == 2 and std.mem.eql(u8, editor_trace.argv(), view_argv), "a click on the settings row viewed it read-only: '{s}'", .{editor_trace.argv()});
    promptsCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .terminal_text = "{}" }), "vi shows the settings file", .{});
    _ = try agentTypeKeys(self, io, out, ":q");
    _ = try postNamedKey(self, io, out, .enter, .{});
    _ = try waitForAgent(self, io, out, &os_trace, .{ .prompts_editor_closed = {} });

    // Apply, by mouse: the running agent is stopped and restarted under a
    // new id in its own tab, with the same task prompt.
    _ = try clickTabsElement(self, io, out, "workspace.1.tab.2");
    _ = try waitForAgent(self, io, out, &os_trace, .{ .active_tab = agent_tab });
    _ = try paletteChord(self, io, out);
    _ = try postPaletteText(self, io, out, "Agent: prompts");
    _ = try postNamedKey(self, io, out, .enter, .{});
    _ = try waitForAgent(self, io, out, &os_trace, .{ .element = apply_id });
    _ = try clickTabsElement(self, io, out, apply_id);
    promptsCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .prompts_agent_replaced = first_agent }) and
        try waitForAgent(self, io, out, &os_trace, .{ .child_running = .{ .key = key, .session = agent_session } }), "'{s}' restarted the agent under a new id in its own tab", .{prompts_apply_label});
    const restarted = self.agents.runnerForSession(key, agent_session);
    promptsCheck(out, &failures, if (restarted) |runner|
        runner.agent_id != first_agent and std.mem.eql(u8, runner.prompt orelse "", prompts_test_prompt) and std.mem.eql(u8, runner.cwd, project)
    else
        false, "the restarted agent keeps its task prompt and project", .{});
    promptsCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .terminal_text = "FAKE-AGENT-READY" }), "the restarted agent's process is running", .{});
    _ = try postNamedKey(self, io, out, .escape, .{});
    promptsCheck(out, &failures, !self.promptsVisible(), "Escape closed the view again", .{});

    var screenshot_path_buffer: [path_capacity]u8 = undefined;
    var id_buffer: [path_capacity]u8 = undefined;
    const screenshot_path = try std.fmt.bufPrint(&screenshot_path_buffer, "{s}{c}agent-prompts-test-{s}.png", .{ fallback_log_dir, std.fs.path.sep, try generateRunId(io, &id_buffer) });
    try writePngOffThread(self.allocator, io, screenshot_path, screenshot_pixels, self.size);
    out.print("agent-prompts-test: screenshot {s}\n", .{screenshot_path}) catch {};
    out.print("agent-prompts-test: {d} failure(s)\n", .{failures}) catch {};
    out.flush() catch {};
    return if (failures == 0) 0 else 1;
}

/// Type `text` into whatever has keyboard focus, through SDL, without a
/// trailing Enter.
fn agentTypeKeys(self: *App, io: Io, out: *Writer, text: [:0]const u8) !bool {
    try self.window.postTextInput(text);
    return pumpUntil(self, io, out, .text_input, self_test_event_budget_ms);
}

// --backlog-test (TASK-63, TASK-64) ----------------------------------------------

fn backlogCheck(out: *Writer, failures: *usize, ok: bool, comptime format: []const u8, args: anytype) void {
    out.print("backlog-test: {s} " ++ format ++ "\n", .{if (ok) "ok  " else "FAIL"} ++ args) catch {};
    if (!ok) failures.* += 1;
}

/// A stand-in for the `backlog` CLI that edits the fixture's markdown the way
/// the real one does for the three writes the view makes, records each call,
/// and fails with a message on stderr while a `fail` file sits beside it. The
/// real CLI is never run by the check.
const backlog_fake_cli =
    \\#!/bin/sh
    \\bin=$(dirname "$0")
    \\printf '%s\n' "$*" >> "$bin/calls"
    \\if [ -e "$bin/fail" ]; then echo "Error: simulated failure for $3" >&2; exit 1; fi
    \\[ "$1" = task ] && [ "$2" = edit ] || { echo "unsupported command" >&2; exit 2; }
    \\id=$(printf '%s' "$3" | tr 'A-Z' 'a-z')
    \\file=$(ls backlog/tasks/"$id - "*.md 2>/dev/null | head -n 1)
    \\[ -n "$file" ] || { echo "Error: Task $3 not found." >&2; exit 1; }
    \\case "$4" in
    \\  --status=*) sed -i "s/^status: .*/status: ${4#--status=}/" "$file" ;;
    \\  --check-ac=*) n=${4#--check-ac=}; sed -i "s/^- \[ \] #$n /- [x] #$n /" "$file" ;;
    \\  --uncheck-ac=*) n=${4#--uncheck-ac=}; sed -i "s/^- \[x\] #$n /- [ ] #$n /" "$file" ;;
    \\  *) echo "unsupported option $4" >&2; exit 2 ;;
    \\esac
    \\echo "Updated task $3"
    \\
;

const BacklogWait = union(enum) {
    terminal_text: []const u8,
    element: []const u8,
    element_absent: []const u8,
    /// An element `id` whose label contains `text`.
    label: struct { id: []const u8, text: []const u8 },
    /// Some element whose id starts with `prefix` and whose label contains `text`.
    prefix_label: struct { prefix: []const u8, text: []const u8 },
    /// The file at `path` contains `text`.
    file: struct { path: []const u8, text: []const u8 },
    /// No backlog write is running or queued.
    idle,
};

fn backlogWaitMet(self: *App, condition: BacklogWait) bool {
    return switch (condition) {
        .terminal_text => |text| self.activeLive().terminal().visibleTextContains(text),
        .element => |id| self.ui_tree.byId(.{ .value = id }) != null,
        .element_absent => |id| self.ui_tree.byId(.{ .value = id }) == null,
        .label => |want| if (self.ui_tree.byId(.{ .value = want.id })) |element| std.mem.indexOf(u8, element.label, want.text) != null else false,
        .prefix_label => |want| viewElement(self, want.prefix, want.text) != null,
        .file => |want| file: {
            var buffer: [16 * 1024]u8 = undefined;
            const text = Dir.cwd().readFile(self.io, want.path, &buffer) catch break :file false;
            break :file std.mem.indexOf(u8, text, want.text) != null;
        },
        .idle => idle: {
            const panel = self.activePresentation().backlog orelse break :idle true;
            break :idle !panel.busy();
        },
    };
}

fn waitForBacklog(self: *App, io: Io, out: *Writer, condition: BacklogWait) !bool {
    const deadline = Io.Clock.real.now(io).nanoseconds + agent_test_budget_ms * std.time.ns_per_ms;
    while (true) {
        if (self.scheduler.shouldDraw()) try self.drawFrame();
        if (backlogWaitMet(self, condition)) return true;
        const event = self.window.pump(@min(self.waitBudget(io, deadline), 50));
        if (event) |one| {
            describeEvent(out, one) catch {};
            if (!try self.handle(one)) return false;
        }
        if (self.poll()) self.scheduler.invalidate();
        if (Io.Clock.real.now(io).nanoseconds >= deadline) {
            if (self.scheduler.shouldDraw()) try self.drawFrame();
            return backlogWaitMet(self, condition);
        }
    }
}

fn backlogChordKey(self: *App, io: Io, out: *Writer) !bool {
    const mods: platform.Mods = switch (self.binding_profile) {
        .macos => .{ .shift = true, .super = true },
        .linux_windows => .{ .ctrl = true, .shift = true },
    };
    return postKey(self, io, out, 'k', mods);
}

/// Post one wheel notch (`notches` < 0 scrolls down) over element `id`.
fn backlogWheel(self: *App, io: Io, out: *Writer, id: []const u8, notches: f32) !bool {
    const element = self.ui_tree.byId(.{ .value = id }) orelse return false;
    const point = elementCenter(element, self.window.state.scale);
    try self.window.postWheel(.{ .dy = notches, .x = point.x, .y = point.y });
    return pumpUntil(self, io, out, .wheel, self_test_event_budget_ms);
}

fn backlogSelected(self: *App, id: []const u8) bool {
    const element = self.ui_tree.byId(.{ .value = id }) orelse return false;
    return element.state.selected;
}

/// Whether element `id` starts in the same column as element `column`.
fn backlogInColumn(self: *App, id: []const u8, column: []const u8) bool {
    const card = self.ui_tree.byId(.{ .value = id }) orelse return false;
    const heading = self.ui_tree.byId(.{ .value = column }) orelse return false;
    return card.bounds.x == heading.bounds.x;
}

fn backlogScreenshot(self: *App, io: Io, out: *Writer, name: []const u8) !void {
    try self.drawFrame();
    const pixels = try self.allocator.dupe(u8, try self.capture());
    defer self.allocator.free(pixels);
    var path_buffer: [path_capacity]u8 = undefined;
    var id_buffer: [path_capacity]u8 = undefined;
    const path = try std.fmt.bufPrint(&path_buffer, "{s}{c}backlog-test-{s}-{s}.png", .{ fallback_log_dir, std.fs.path.sep, name, try generateRunId(io, &id_buffer) });
    try writePngOffThread(self.allocator, io, path, pixels, self.size);
    out.print("backlog-test: screenshot {s} {s}\n", .{ name, path }) catch {};
}

/// Exercise TASK-63 and TASK-64 through real PTYs, SDL events and a fake
/// `backlog` CLI: the fixture project in a second workspace's directory, the
/// view by chord and by palette, board and list by key and by click, the
/// detail by Enter and by click, criteria and status written through the CLI
/// and read back through the watch, a CLI failure in the message line, an
/// external edit, and a fake agent started on a task whose card, detail and
/// manager row then name it.
fn backlogTest(self: *App, io: Io, out: *Writer) !u8 {
    var failures: usize = 0;
    var os_trace: AgentOsTrace = .{};
    self.agents.notifier = .{ .context = &os_trace, .notify_fn = AgentOsTrace.record };
    defer self.agents.notifier = .{ .notify_fn = App.discardOsNotification };
    self.focus_override = true;
    defer self.focus_override = null;
    defer self.backlog_program = "backlog";

    try self.drawFrame();
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .terminal_text = "AGENT-TEST-READY" }), "the first tab's real PTY peer became ready", .{});
    const dir = self.agentTestDir() orelse return 1;

    // The fixture project, copied into a private project directory.
    var project_buffer: [path_capacity:0]u8 = undefined;
    const project_dir = try std.fmt.bufPrintZ(&project_buffer, "{s}/project", .{dir});
    var root_buffer: [path_capacity]u8 = undefined;
    const root = try std.fmt.bufPrint(&root_buffer, "{s}/backlog", .{project_dir});
    _ = try Dir.cwd().createDirPathStatus(io, project_dir, .default_dir);
    var copy = workspace.runLocalProcess(self.allocator, io, .{ .argv = &.{ "cp", "-R", "test/fixtures/backlog/valid", root }, .cwd = "" }) catch |err| {
        out.print("backlog-test: FAIL could not copy the fixture: {s}\n", .{@errorName(err)}) catch {};
        return 1;
    };
    const copied = copy.succeeded();
    copy.deinit(self.allocator);
    backlogCheck(out, &failures, copied, "the valid fixture was copied into the project directory (run from the repository root)", .{});
    if (!copied) return 1;

    // The fake CLI, which the view runs instead of `backlog`.
    var bin_buffer: [path_capacity]u8 = undefined;
    const bin = try std.fmt.bufPrint(&bin_buffer, "{s}/bin", .{dir});
    _ = try Dir.cwd().createDirPathStatus(io, bin, .default_dir);
    var program_buffer: [path_capacity]u8 = undefined;
    const program = try std.fmt.bufPrint(&program_buffer, "{s}/backlog", .{bin});
    try Dir.cwd().writeFile(io, .{ .sub_path = program, .data = backlog_fake_cli, .flags = .{ .permissions = if (builtin.os.tag == .windows) .default_file else .fromMode(0o700) } });
    var fail_buffer: [path_capacity]u8 = undefined;
    const fail_path = try std.fmt.bufPrint(&fail_buffer, "{s}/fail", .{bin});
    self.backlog_program = program;
    var task_one_buffer: [path_capacity]u8 = undefined;
    const task_one = try std.fmt.bufPrint(&task_one_buffer, "{s}/tasks/task-1 - First-task.md", .{root});
    var task_two_buffer: [path_capacity]u8 = undefined;
    const task_two = try std.fmt.bufPrint(&task_two_buffer, "{s}/tasks/task-2 - A-long-folded-title.md", .{root});

    // A workspace in the project directory, created from the palette.
    const first_key = self.workspace_registry.activeKey() orelse return 1;
    _ = try runPaletteCommandByKeyboard(self, io, out, "Create workspace");
    _ = try agentTypeLine(self, io, out, project_dir);
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .element = "workspace.2" }) and
        self.workspace_registry.activeKey() != first_key and
        std.mem.eql(u8, self.activeWorkspace().workingDirectory(), project_dir), "a second workspace opened in the project directory", .{});
    const project_key = self.workspace_registry.activeKey() orelse return 1;

    // The view by chord: a column per configured status, cards in them.
    const routes_before = self.terminal_key_route_count;
    _ = try backlogChordKey(self, io, out);
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .element = "backlog.view" }) and
        try waitForBacklog(self, io, out, .{ .label = .{ .id = "backlog.task.TASK-1", .text = "TASK-1 First task: parse the model" } }), "the chord opened the view on the workspace's backlog", .{});
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .label = .{ .id = "backlog.column.0", .text = "To Do (1)" } }) and
        try waitForBacklog(self, io, out, .{ .label = .{ .id = "backlog.column.1", .text = "In Progress (1)" } }) and
        try waitForBacklog(self, io, out, .{ .label = .{ .id = "backlog.column.2", .text = "Review (1)" } }) and
        try waitForBacklog(self, io, out, .{ .label = .{ .id = "backlog.column.3", .text = "Done (0)" } }), "the board has the four configured status columns", .{});
    backlogCheck(out, &failures, backlogInColumn(self, "backlog.task.TASK-1", "backlog.column.0") and
        backlogInColumn(self, "backlog.task.TASK-2", "backlog.column.1") and
        backlogInColumn(self, "backlog.task.TASK-2.1", "backlog.column.2") and
        self.ui_tree.byId(.{ .value = "backlog.task.TASK-3" }) == null and self.ui_tree.byId(.{ .value = "backlog.task.DRAFT-1" }) == null, "each active task sits in its status column; completed and draft tasks are not cards", .{});
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .label = .{ .id = "backlog.task.TASK-1.meta", .text = "#backlog #architecture  @codex @claude" } }) and
        try waitForBacklog(self, io, out, .{ .label = .{ .id = "backlog.task.TASK-2", .text = "folded across two lines" } }), "cards show labels, assignees and folded titles", .{});
    backlogCheck(out, &failures, backlogSelected(self, "backlog.task.TASK-1"), "the first card is selected on open", .{});

    // Keys stay in the view: an unused key reaches no terminal.
    _ = try postKey(self, io, out, 'x', .{});
    backlogCheck(out, &failures, self.terminal_key_route_count == routes_before and self.backlogShown(), "an unused key did not reach the terminal beneath", .{});

    // Arrows across columns.
    _ = try postNamedKey(self, io, out, .right, .{});
    backlogCheck(out, &failures, backlogSelected(self, "backlog.task.TASK-2"), "Right selected the In Progress card", .{});
    _ = try postNamedKey(self, io, out, .right, .{});
    _ = try postNamedKey(self, io, out, .right, .{});
    backlogCheck(out, &failures, backlogSelected(self, "backlog.task.TASK-2.1"), "Right stopped at the last non-empty column", .{});
    _ = try postNamedKey(self, io, out, .home, .{});
    _ = try postNamedKey(self, io, out, .left, .{});
    _ = try postNamedKey(self, io, out, .left, .{});
    backlogCheck(out, &failures, backlogSelected(self, "backlog.task.TASK-1"), "Left returned to the To Do card", .{});

    // List mode by key and by click; board again by key and by click.
    _ = try postKey(self, io, out, 'l', .{});
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .element = "backlog.list.heading" }) and
        try waitForBacklog(self, io, out, .{ .label = .{ .id = "backlog.task.TASK-2.status", .text = "In Progress" } }) and
        backlogSelected(self, "backlog.mode.list"), "l showed the ordinal list with status words", .{});
    const list_first = self.ui_tree.byId(.{ .value = "backlog.task.TASK-1" });
    const list_middle = self.ui_tree.byId(.{ .value = "backlog.task.TASK-2" });
    const list_last = self.ui_tree.byId(.{ .value = "backlog.task.TASK-2.1" });
    backlogCheck(out, &failures, list_first != null and list_middle != null and list_last != null and
        list_first.?.bounds.y < list_middle.?.bounds.y and list_middle.?.bounds.y < list_last.?.bounds.y, "the list is in ordinal order", .{});
    _ = try postKey(self, io, out, 'b', .{});
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .element = "backlog.column.3" }), "b showed the board again", .{});
    _ = try clickTabsElement(self, io, out, "backlog.mode.list");
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .element = "backlog.list.heading" }), "a click on list showed the list", .{});
    _ = try clickTabsElement(self, io, out, "backlog.mode.board");
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .element = "backlog.column.0" }) and
        try waitForBacklog(self, io, out, .{ .element_absent = "backlog.list.heading" }), "a click on board showed the board", .{});

    // The detail by Enter.
    _ = try postNamedKey(self, io, out, .enter, .{});
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .element = "backlog.detail.TASK-1" }) and
        try waitForBacklog(self, io, out, .{ .label = .{ .id = "backlog.detail.TASK-1.status", .text = "To Do" } }) and
        backlogSelected(self, "backlog.detail.TASK-1.status"), "Enter opened TASK-1's detail with the cursor on its status", .{});
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .prefix_label = .{ .prefix = "backlog.detail.TASK-1.row.", .text = "Read the project into a typed model." } }) and
        try waitForBacklog(self, io, out, .{ .prefix_label = .{ .prefix = "backlog.detail.TASK-1.row.", .text = "M1 - First" } }) and
        try waitForBacklog(self, io, out, .{ .prefix_label = .{ .prefix = "backlog.detail.TASK-1.row.", .text = "TASK-2, TASK-3" } }) and
        try waitForBacklog(self, io, out, .{ .element = "backlog.detail.TASK-1.agent" }) and
        try waitForBacklog(self, io, out, .{ .element = "backlog.detail.TASK-1.raw" }), "the detail shows description, milestone, dependencies and its two actions", .{});
    // End scrolls to the last criterion; the wheel shows the notes below.
    _ = try postNamedKey(self, io, out, .end, .{});
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .label = .{ .id = "backlog.detail.TASK-1.ac.1", .text = "[ ] #1 Tasks are parsed" } }) and
        try waitForBacklog(self, io, out, .{ .label = .{ .id = "backlog.detail.TASK-1.ac.2", .text = "[x] #2 Statuses are parsed" } }) and
        backlogSelected(self, "backlog.detail.TASK-1.ac.3"), "End scrolled to the criteria with the cursor on the last", .{});
    _ = try backlogWheel(self, io, out, "backlog.detail.TASK-1", -1);
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .prefix_label = .{ .prefix = "backlog.detail.TASK-1.row.", .text = "Notes go here." } }), "the wheel scrolled the detail to its notes", .{});
    _ = try postNamedKey(self, io, out, .home, .{});

    // A criterion checked by keyboard, through the CLI and back through the watch.
    _ = try postNamedKey(self, io, out, .down, .{});
    backlogCheck(out, &failures, backlogSelected(self, "backlog.detail.TASK-1.ac.1"), "Down moved the detail cursor to criterion #1", .{});
    _ = try postNamedKey(self, io, out, .enter, .{});
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .file = .{ .path = task_one, .text = "- [x] #1 Tasks are parsed" } }) and
        try waitForBacklog(self, io, out, .{ .label = .{ .id = "backlog.detail.TASK-1.ac.1", .text = "[x] #1" } }) and
        try waitForBacklog(self, io, out, .{ .label = .{ .id = "backlog.message", .text = "TASK-1 #1 checked" } }), "Enter checked #1: the CLI wrote the file and the view reloaded it", .{});
    // And by click, both ways.
    _ = try postNamedKey(self, io, out, .end, .{});
    _ = try clickTabsElement(self, io, out, "backlog.detail.TASK-1.ac.3");
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .file = .{ .path = task_one, .text = "- [x] #3 Criteria keep their numbers" } }) and
        try waitForBacklog(self, io, out, .{ .label = .{ .id = "backlog.detail.TASK-1.ac.3", .text = "[x] #3" } }), "a click checked #3", .{});
    _ = try waitForBacklog(self, io, out, .idle);
    _ = try clickTabsElement(self, io, out, "backlog.detail.TASK-1.ac.1");
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .file = .{ .path = task_one, .text = "- [ ] #1 Tasks are parsed" } }) and
        try waitForBacklog(self, io, out, .{ .label = .{ .id = "backlog.detail.TASK-1.ac.1", .text = "[ ] #1" } }), "a second click unchecked #1", .{});
    _ = try waitForBacklog(self, io, out, .idle);

    // The status: s, then a click on the status row (Home scrolls it back).
    _ = try postNamedKey(self, io, out, .home, .{});
    _ = try postKey(self, io, out, 's', .{});
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .file = .{ .path = task_one, .text = "status: In Progress" } }) and
        try waitForBacklog(self, io, out, .{ .label = .{ .id = "backlog.detail.TASK-1.status", .text = "In Progress" } }), "s moved TASK-1 to In Progress", .{});
    _ = try waitForBacklog(self, io, out, .idle);
    _ = try clickTabsElement(self, io, out, "backlog.detail.TASK-1.status");
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .file = .{ .path = task_one, .text = "status: Review" } }) and
        try waitForBacklog(self, io, out, .{ .label = .{ .id = "backlog.detail.TASK-1.status", .text = "Review" } }), "a click on the status moved TASK-1 to Review", .{});
    _ = try waitForBacklog(self, io, out, .idle);

    // A failing CLI is reported in the detail and changes nothing.
    try Dir.cwd().writeFile(io, .{ .sub_path = fail_path, .data = "" });
    _ = try postNamedKey(self, io, out, .end, .{});
    _ = try clickTabsElement(self, io, out, "backlog.detail.TASK-1.ac.2");
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .label = .{ .id = "backlog.message", .text = "backlog failed (1): Error: simulated failure for TASK-1" } }) and
        try waitForBacklog(self, io, out, .idle) and
        try waitForBacklog(self, io, out, .{ .file = .{ .path = task_one, .text = "- [x] #2 Statuses are parsed" } }) and
        self.backlogShown(), "a CLI failure showed its stderr in the message line and left the task alone", .{});
    try Dir.cwd().deleteFile(io, fail_path);

    // Escape closes the detail; the card moved column.
    _ = try postNamedKey(self, io, out, .escape, .{});
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .element_absent = "backlog.detail.TASK-1" }) and
        self.backlogShown() and backlogInColumn(self, "backlog.task.TASK-1", "backlog.column.2") and
        try waitForBacklog(self, io, out, .{ .label = .{ .id = "backlog.column.2", .text = "Review (2)" } }) and
        try waitForBacklog(self, io, out, .{ .element = "backlog.task.TASK-1.column.2" }) and
        try waitForBacklog(self, io, out, .{ .element_absent = "backlog.task.TASK-1.column.0" }), "Escape closed the detail and TASK-1's card is in Review", .{});

    // The detail by click, closed by its close control.
    _ = try clickTabsElement(self, io, out, "backlog.task.TASK-2");
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .element = "backlog.detail.TASK-2" }), "a click on a card opened its detail", .{});
    _ = try clickTabsElement(self, io, out, "backlog.detail.TASK-2.close");
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .element_absent = "backlog.detail.TASK-2" }), "the close control closed the detail", .{});

    // An agent started on TASK-1 from its detail (TASK-64).
    _ = try clickTabsElement(self, io, out, "backlog.task.TASK-1");
    _ = try waitForBacklog(self, io, out, .{ .element = "backlog.detail.TASK-1.agent" });
    _ = try clickTabsElement(self, io, out, "backlog.detail.TASK-1.agent");
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .label = .{ .id = "backlog.detail.TASK-1.harness.0", .text = app_agents.fake_choice_label } }), "start agent offered the fake harness first", .{});
    const before_ordinal = self.agents.registry.next_ordinal;
    _ = try clickTabsElement(self, io, out, "backlog.detail.TASK-1.harness.0");
    const started = agent.AgentId.fromOrdinal(before_ordinal);
    const runner = self.agents.runnerForAgent(started);
    backlogCheck(out, &failures, runner != null and runner.?.taskId() != null and std.mem.eql(u8, runner.?.taskId().?, "TASK-1") and
        std.mem.eql(u8, runner.?.cwd, project_dir), "the agent was started on TASK-1 in the project directory", .{});
    backlogCheck(out, &failures, runner != null and runner.?.prompt != null and
        std.mem.startsWith(u8, runner.?.prompt.?, "TASK-1: First task: parse the model\n\nRead the project into a typed model.") and
        std.mem.indexOf(u8, runner.?.prompt.?, "Acceptance criteria:\n- [ ] #1 Tasks are parsed\n- [x] #2") != null, "the agent's initial prompt is the task's id, title, description and criteria", .{});
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .terminal_text = "FAKE-AGENT-READY" }), "the fake agent's real process is running in its own tab", .{});
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .element = "backlog.task.TASK-1.agent.idle" }) and
        try waitForBacklog(self, io, out, .{ .label = .{ .id = "backlog.task.TASK-1.meta", .text = "· Fake agent idle" } }) and
        try waitForBacklog(self, io, out, .{ .prefix_label = .{ .prefix = "backlog.detail.TASK-1.row.", .text = "Agent      · Fake agent idle" } }), "the card and the detail show the agent and its state", .{});
    try backlogScreenshot(self, io, out, "detail");

    // The card follows the agent's state live.
    _ = try postNamedKey(self, io, out, .escape, .{});
    _ = try waitForBacklog(self, io, out, .{ .element_absent = "backlog.detail.TASK-1" });
    if (runner) |linked| {
        var steps_buffer: [path_capacity]u8 = undefined;
        const steps_path = try std.fmt.bufPrint(&steps_buffer, "{s}/steps", .{linked.sink_dir});
        try Dir.cwd().writeFile(io, .{ .sub_path = steps_path, .data = "x" });
    }
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .element = "backlog.task.TASK-1.agent.working" }) and
        try waitForBacklog(self, io, out, .{ .label = .{ .id = "backlog.task.TASK-1.meta", .text = "▸ Fake agent working" } }), "the card's agent badge changed to working live", .{});
    try backlogScreenshot(self, io, out, "board");

    // The agent manager names the task.
    const manager_mods: platform.Mods = switch (self.binding_profile) {
        .macos => .{ .shift = true, .super = true },
        .linux_windows => .{ .ctrl = true, .shift = true },
    };
    _ = try postKey(self, io, out, 'g', manager_mods);
    var row_buffer: [manager_id_capacity]u8 = undefined;
    const manager_row = managerRowId(&row_buffer, started, null);
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .element = "agents.dialog" }) and
        try waitForBacklog(self, io, out, .{ .label = .{ .id = manager_row, .text = "  TASK-1  " } }), "the agent manager's row shows the agent's task", .{});
    _ = try postNamedKey(self, io, out, .escape, .{});
    _ = try waitForBacklog(self, io, out, .{ .element_absent = "agents.dialog" });

    // An external edit appears without any gesture.
    var task_two_text: [4096]u8 = undefined;
    const original = try Dir.cwd().readFile(io, task_two, &task_two_text);
    const title_start = std.mem.indexOf(u8, original, "title: >-") orelse 0;
    const title_end = std.mem.indexOf(u8, original, "status:") orelse 0;
    var rewritten: std.ArrayList(u8) = .empty;
    defer rewritten.deinit(self.allocator);
    try rewritten.appendSlice(self.allocator, original[0..title_start]);
    try rewritten.appendSlice(self.allocator, "title: Renamed outside Conduit\n");
    try rewritten.appendSlice(self.allocator, original[title_end..]);
    try Dir.cwd().writeFile(io, .{ .sub_path = task_two, .data = rewritten.items });
    backlogCheck(out, &failures, title_start != 0 and title_end > title_start and
        try waitForBacklog(self, io, out, .{ .label = .{ .id = "backlog.task.TASK-2", .text = "TASK-2 Renamed outside Conduit" } }), "an external edit of TASK-2 appeared live", .{});

    // Escape closes the view; the palette opens it again; the chord closes it.
    _ = try postNamedKey(self, io, out, .escape, .{});
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .element_absent = "backlog.view" }) and !self.backlogShown(), "Escape closed the view", .{});
    backlogCheck(out, &failures, try clickPaletteCommand(self, io, out, backlog_open_action, null) and
        try waitForBacklog(self, io, out, .{ .element = "backlog.view" }) and
        try waitForBacklog(self, io, out, .{ .element = "backlog.task.TASK-1.agent.working" }), "the palette opened the view by mouse with the agent still linked", .{});
    _ = try backlogChordKey(self, io, out);
    backlogCheck(out, &failures, try waitForBacklog(self, io, out, .{ .element_absent = "backlog.view" }), "the chord closed the view", .{});

    // A workspace without a backlog says so.
    var plain_buffer: [path_capacity:0]u8 = undefined;
    const plain_dir = try std.fmt.bufPrintZ(&plain_buffer, "{s}/plain", .{dir});
    _ = try Dir.cwd().createDirPathStatus(io, plain_dir, .default_dir);
    _ = try runPaletteCommandByKeyboard(self, io, out, "Create workspace");
    _ = try agentTypeLine(self, io, out, plain_dir);
    _ = try waitForBacklog(self, io, out, .{ .element = "workspace.3" });
    _ = try backlogChordKey(self, io, out);
    backlogCheck(out, &failures, self.workspace_registry.activeKey() != project_key and self.workspace_registry.activeKey() != first_key and
        try waitForBacklog(self, io, out, .{ .label = .{ .id = "backlog.empty", .text = "no backlog/ here" } }), "a workspace without backlog/ shows the empty state", .{});
    _ = try backlogChordKey(self, io, out);
    _ = try waitForBacklog(self, io, out, .{ .element_absent = "backlog.view" });

    var calls_buffer: [path_capacity]u8 = undefined;
    const calls_path = try std.fmt.bufPrint(&calls_buffer, "{s}/calls", .{bin});
    var calls_text: [4096]u8 = undefined;
    const calls = Dir.cwd().readFile(io, calls_path, &calls_text) catch "";
    backlogCheck(out, &failures, std.mem.indexOf(u8, calls, "task edit TASK-1 --check-ac=1 --plain") != null and
        std.mem.indexOf(u8, calls, "task edit TASK-1 --uncheck-ac=1 --plain") != null and
        std.mem.indexOf(u8, calls, "task edit TASK-1 --status=In Progress --plain") != null, "the CLI was called with validated single-argument options", .{});

    out.print("backlog-test: {d} failure(s)\n", .{failures}) catch {};
    out.flush() catch {};
    return if (failures == 0) 0 else 1;
}

// --control-test (TASK-60 part two, TASK-66) -------------------------------------

/// The first tab of `--control-test`: a readiness marker, then an
/// interactive shell with a known prompt. Its environment carries the check's
/// private runtime and state directories (`ChildSpec.buildIn`) and this run's
/// control variables (`appendControlEnv`).
const control_test_script = "PS1='ctl$ '; export PS1; printf 'CONTROL-TEST-READY\\r\\n'; exec /bin/sh -i";
const control_test_budget_ms: i64 = 15_000;
/// The private SSH config `conduit ssh nowhere` resolves: a host that
/// refuses at once, so the workspace shows a failed connection quickly.
const control_test_ssh_config = "Host nowhere\n  HostName 127.0.0.1\n  Port 9\n  ConnectTimeout 2\n  BatchMode yes\n";

const ControlWait = union(enum) {
    terminal_text: []const u8,
    element: []const u8,
    element_absent: []const u8,
    label: struct { id: []const u8, text: []const u8 },
    role_label: struct { prefix: []const u8, text: []const u8 },
    file: struct { path: []const u8, text: []const u8 },
    entry_body: []const u8,
    scratchpad_text: []const u8,
};

fn fileContains(io: Io, path: []const u8, text: []const u8) bool {
    var buffer: [64 * 1024]u8 = undefined;
    const contents = Dir.cwd().readFile(io, path, &buffer) catch return false;
    return std.mem.indexOf(u8, contents, text) != null;
}

fn controlWaitMet(self: *App, io: Io, condition: ControlWait) !bool {
    return switch (condition) {
        .terminal_text => |text| text_found: {
            try self.activeLive().terminal().refresh(self.allocator);
            break :text_found self.activeLive().terminal().visibleTextContains(text);
        },
        .element => |id| self.ui_tree.byId(.{ .value = id }) != null,
        .element_absent => |id| self.ui_tree.byId(.{ .value = id }) == null,
        .label => |want| if (self.ui_tree.byId(.{ .value = want.id })) |element| std.mem.indexOf(u8, element.label, want.text) != null else false,
        .role_label => |want| viewElement(self, want.prefix, want.text) != null,
        .file => |want| fileContains(io, want.path, want.text),
        .entry_body => |text| agentEntryIndex(self, text) != null,
        .scratchpad_text => |text| scratchpad: {
            const scratchpad = self.scratchpadLive() orelse break :scratchpad false;
            try scratchpad.terminal().refresh(self.allocator);
            break :scratchpad scratchpad.terminal().visibleTextContains(text);
        },
    };
}

fn waitForControl(self: *App, io: Io, out: *Writer, condition: ControlWait) !bool {
    const deadline = Io.Clock.real.now(io).nanoseconds + control_test_budget_ms * std.time.ns_per_ms;
    while (true) {
        if (self.scheduler.shouldDraw()) try self.drawFrame();
        if (try controlWaitMet(self, io, condition)) return true;
        const event = self.window.pump(@min(self.waitBudget(io, deadline), 50));
        if (event) |one| {
            describeEvent(out, one) catch {};
            if (!try self.handle(one)) return false;
        }
        if (self.outputReadable()) _ = try self.drainChildren(io);
        if (self.poll()) self.scheduler.invalidate();
        if (Io.Clock.real.now(io).nanoseconds >= deadline) {
            if (self.scheduler.shouldDraw()) try self.drawFrame();
            return controlWaitMet(self, io, condition);
        }
    }
}

fn controlCheck(out: *Writer, failures: *usize, ok: bool, comptime format: []const u8, args: anytype) void {
    out.print("control-test: {s} " ++ format ++ "\n", .{if (ok) "ok  " else "FAIL"} ++ args) catch {};
    out.flush() catch {};
    if (!ok) failures.* += 1;
}

/// Type one shell line into the focused terminal and press Enter.
fn controlType(self: *App, io: Io, out: *Writer, comptime format: []const u8, args: anytype) !bool {
    var buffer: [4096:0]u8 = undefined;
    const line = try std.fmt.bufPrintZ(&buffer, format, args);
    return agentTypeLine(self, io, out, line);
}

/// Wait for `<dir>/<name>` to hold `text`.
fn waitForControlFile(self: *App, io: Io, out: *Writer, dir: []const u8, name: []const u8, text: []const u8) !bool {
    var path_buffer: [path_capacity]u8 = undefined;
    const path = try std.fmt.bufPrint(&path_buffer, "{s}/{s}", .{ dir, name });
    return waitForControl(self, io, out, .{ .file = .{ .path = path, .text = text } });
}

/// The milliseconds a `<name>=<status> <ms>ms` line of the instance log
/// reports, when its status is 0.
fn controlCommandMs(io: Io, path: []const u8, name: []const u8) ?u64 {
    var buffer: [8 * 1024]u8 = undefined;
    const contents = Dir.cwd().readFile(io, path, &buffer) catch return null;
    var prefix_buffer: [32]u8 = undefined;
    const prefix = std.fmt.bufPrint(&prefix_buffer, "{s}=0 ", .{name}) catch return null;
    const start = (std.mem.indexOf(u8, contents, prefix) orelse return null) + prefix.len;
    const end = std.mem.indexOfPos(u8, contents, start, "ms") orelse return null;
    return std.fmt.parseInt(u64, contents[start..end], 10) catch null;
}

fn controlTabNamed(self: *App, key: workspace.WorkspaceKey, name: []const u8) ?workspace.TabId {
    const model = self.workspace_registry.byKey(key) orelse return null;
    var index: usize = 0;
    while (model.tabAt(index)) |tab| : (index += 1) {
        if (std.mem.eql(u8, tab.name(), name)) return tab.id();
    }
    return null;
}

fn controlWorkspaceIn(self: *App, directory: []const u8) ?workspace.WorkspaceKey {
    var index: usize = 0;
    while (index < self.workspace_registry.count()) : (index += 1) {
        const key = self.workspace_registry.keyAt(index) orelse continue;
        const model = self.workspace_registry.byKey(key) orelse continue;
        if (std.mem.eql(u8, model.workingDirectory(), directory)) return key;
    }
    return null;
}

/// Click the active tab's focused pane, so typing reaches its terminal
/// rather than the sidebar row a previous click focused.
fn controlFocusTerminal(self: *App, io: Io, out: *Writer) !bool {
    const key = self.workspace_registry.activeKey() orelse return false;
    const model = self.activeWorkspace();
    const tab_id = model.activeTabId() orelse return false;
    const pane_id = model.focusedPaneId(tab_id) orelse return false;
    var buffer: [64]u8 = undefined;
    try self.drawFrame();
    return clickTabsElement(self, io, out, try paneSemanticId(&buffer, key, pane_id));
}

fn controlScreenshot(self: *App, io: Io, out: *Writer) !void {
    try self.drawFrame();
    const pixels = try self.allocator.dupe(u8, try self.capture());
    defer self.allocator.free(pixels);
    var path_buffer: [path_capacity]u8 = undefined;
    var id_buffer: [path_capacity]u8 = undefined;
    const path = try std.fmt.bufPrint(&path_buffer, "{s}{c}control-test-{s}.png", .{ fallback_log_dir, std.fs.path.sep, try generateRunId(io, &id_buffer) });
    try writePngOffThread(self.allocator, io, path, pixels, self.size);
    out.print("control-test: screenshot {s}\n", .{path}) catch {};
}

/// Exercise TASK-60 part two and TASK-66 through real PTYs, real child
/// processes and SDL events: `conduit control` from a tab's shell opens a
/// tab, splits a pane, raises a notification, marks the tab, shows the agent
/// and backlog views and delivers an agent event; the scratchpad has no
/// control variables and a stolen token naming it is refused; then `conduit
/// <dir>`, `conduit ssh`, `conduit workspace open` and `conduit agent` run as
/// separate processes against this run's private instance endpoint.
fn controlTest(self: *App, io: Io, out: *Writer) !u8 {
    var failures: usize = 0;
    var os_trace: AgentOsTrace = .{};
    self.agents.notifier = .{ .context = &os_trace, .notify_fn = AgentOsTrace.record };
    defer self.agents.notifier = .{ .notify_fn = App.discardOsNotification };
    self.focus_override = true;
    defer self.focus_override = null;
    defer self.backlog_program = "backlog";
    const dir = self.agentTestDir() orelse return 1;

    try self.drawFrame();
    controlCheck(out, &failures, try waitForControl(self, io, out, .{ .terminal_text = "CONTROL-TEST-READY" }), "the first tab's shell started", .{});
    controlCheck(out, &failures, self.control_server != null and self.instance_server != null, "the control and instance endpoints are listening", .{});
    const exe = self.self_exe orelse {
        controlCheck(out, &failures, false, "this executable's path is known", .{});
        return 1;
    };
    const endpoint = (self.control_server orelse return 1).endpointPath();
    const first_key = self.workspace_registry.activeKey() orelse return 1;
    var id_buffer: [128]u8 = undefined;

    // ping, from the first tab's shell.
    _ = try controlType(self, io, out, "'{s}' control ping > '{s}/ping' 2>&1; echo \"rc=$?\" >> '{s}/ping'", .{ exe, dir, dir });
    controlCheck(out, &failures, try waitForControlFile(self, io, out, dir, "ping", "rc=0") and
        try waitForControlFile(self, io, out, dir, "ping", "{\"pong\":true}"), "conduit control ping answered from a tab's shell", .{});

    // tab.open: a titled tab in this workspace, reported once its shell runs.
    _ = try controlType(self, io, out, "'{s}' control tab.open '{{\"title\":\"api\"}}' > '{s}/tab' 2>&1; echo \"rc=$?\" >> '{s}/tab'", .{ exe, dir, dir });
    controlCheck(out, &failures, try waitForControlFile(self, io, out, dir, "tab", "rc=0") and
        try waitForControlFile(self, io, out, dir, "tab", "\"session\":"), "tab.open replied with the new tab and session", .{});
    const api_tab = controlTabNamed(self, first_key, "api");
    controlCheck(out, &failures, api_tab != null and self.activeWorkspace().activeTabId() == api_tab, "the api tab exists in the caller's workspace and is active", .{});
    const api_id = try tabSemanticId(&id_buffer, first_key, api_tab orelse return 1);
    controlCheck(out, &failures, try waitForControl(self, io, out, .{ .label = .{ .id = api_id, .text = "api" } }), "the sidebar lists the api tab", .{});
    controlCheck(out, &failures, try waitForControl(self, io, out, .{ .terminal_text = "ctl$" }), "the api tab's shell started", .{});

    // pane.split from the api tab's shell.
    _ = try controlType(self, io, out, "'{s}' control pane.split '{{\"direction\":\"right\"}}' > '{s}/split' 2>&1; echo \"rc=$?\" >> '{s}/split'", .{ exe, dir, dir });
    controlCheck(out, &failures, try waitForControlFile(self, io, out, dir, "split", "rc=0") and
        try waitForControlFile(self, io, out, dir, "split", "\"pane\":"), "pane.split replied with the new pane", .{});
    const api_panes = if (self.activeWorkspace().tab(api_tab.?)) |tab| tab.paneCount() else 0;
    controlCheck(out, &failures, api_panes == 2, "the api tab has two panes ({d})", .{api_panes});
    controlCheck(out, &failures, try waitForControl(self, io, out, .{ .terminal_text = "ctl$" }), "the new pane's shell started", .{});

    // notify: an entry in the notification list.
    _ = try controlType(self, io, out, "'{s}' control notify '{{\"title\":\"Build\",\"body\":\"control notified\"}}' > '{s}/notify' 2>&1; echo \"rc=$?\" >> '{s}/notify'", .{ exe, dir, dir });
    controlCheck(out, &failures, try waitForControlFile(self, io, out, dir, "notify", "rc=0") and
        try waitForControl(self, io, out, .{ .entry_body = "control notified" }), "notify added a notification list entry", .{});

    // tab.status: the caller's tab shows the text with an attention mark.
    _ = try controlType(self, io, out, "'{s}' control tab.status '{{\"text\":\"busy\",\"attention\":true}}' > '{s}/status' 2>&1; echo \"rc=$?\" >> '{s}/status'", .{ exe, dir, dir });
    controlCheck(out, &failures, try waitForControlFile(self, io, out, dir, "status", "rc=0") and
        try waitForControl(self, io, out, .{ .label = .{ .id = api_id, .text = "! busy api" } }), "tab.status marked the api tab", .{});

    // A fixture backlog project and the fake CLI the view runs.
    var project_buffer: [path_capacity]u8 = undefined;
    const project_dir = try std.fmt.bufPrint(&project_buffer, "{s}/project", .{dir});
    var root_buffer: [path_capacity]u8 = undefined;
    const root = try std.fmt.bufPrint(&root_buffer, "{s}/backlog", .{project_dir});
    _ = try Dir.cwd().createDirPathStatus(io, project_dir, .default_dir);
    var copy = workspace.runLocalProcess(self.allocator, io, .{ .argv = &.{ "cp", "-R", "test/fixtures/backlog/valid", root }, .cwd = "" }) catch |err| {
        out.print("control-test: FAIL could not copy the backlog fixture: {s}\n", .{@errorName(err)}) catch {};
        return 1;
    };
    const copied = copy.succeeded();
    copy.deinit(self.allocator);
    controlCheck(out, &failures, copied, "the backlog fixture was copied (run from the repository root)", .{});
    var program_buffer: [path_capacity]u8 = undefined;
    const bin = try std.fmt.bufPrint(&program_buffer, "{s}/bin", .{dir});
    _ = try Dir.cwd().createDirPathStatus(io, bin, .default_dir);
    var fake_cli_buffer: [path_capacity]u8 = undefined;
    const fake_cli = try std.fmt.bufPrint(&fake_cli_buffer, "{s}/backlog", .{bin});
    try Dir.cwd().writeFile(io, .{ .sub_path = fake_cli, .data = backlog_fake_cli, .flags = .{ .permissions = if (builtin.os.tag == .windows) .default_file else .fromMode(0o700) } });
    self.backlog_program = fake_cli;
    var ssh_dir_buffer: [path_capacity]u8 = undefined;
    const ssh_dir = try std.fmt.bufPrint(&ssh_dir_buffer, "{s}/home/.ssh", .{dir});
    _ = try Dir.cwd().createDirPathStatus(io, ssh_dir, privateArtifactPermissions(true));
    var ssh_config_buffer: [path_capacity]u8 = undefined;
    try Dir.cwd().writeFile(io, .{ .sub_path = try std.fmt.bufPrint(&ssh_config_buffer, "{s}/config", .{ssh_dir}), .data = control_test_ssh_config, .flags = .{ .permissions = privateArtifactPermissions(false) } });
    // The SSH control sockets' private directory.
    if (self.ssh_runtime_owned) |run_dir| _ = try Dir.cwd().createDirPathStatus(io, run_dir, privateArtifactPermissions(true));

    // The single instance: four `conduit` commands as separate processes,
    // without this terminal's control variables, so each finds the private
    // instance endpoint through XDG_RUNTIME_DIR and the token file through
    // XDG_STATE_HOME. One line, so it keeps running in this shell while
    // the commands switch workspaces.
    var instance_path_buffer: [path_capacity]u8 = undefined;
    const instance_log = try std.fmt.bufPrint(&instance_path_buffer, "{s}/instance", .{dir});
    _ = try controlType(self, io, out, "(unset CONDUIT_CONTROL_ENDPOINT CONDUIT_CONTROL_TOKEN CONDUIT_CONTROL_SESSION; " ++
        "t=$(date +%s%N); '{s}' '{s}'; echo \"dir=$? $(( ($(date +%s%N)-t)/1000000 ))ms\"; " ++
        "t=$(date +%s%N); '{s}' ssh nowhere; echo \"ssh=$? $(( ($(date +%s%N)-t)/1000000 ))ms\"; " ++
        "t=$(date +%s%N); '{s}' workspace open default; echo \"workspace=$? $(( ($(date +%s%N)-t)/1000000 ))ms\"; " ++
        "t=$(date +%s%N); '{s}' agent fake; echo \"agent=$? $(( ($(date +%s%N)-t)/1000000 ))ms\"; echo done) > '{s}' 2>&1", .{ exe, project_dir, exe, exe, exe, instance_log });
    controlCheck(out, &failures, try waitForControl(self, io, out, .{ .file = .{ .path = instance_log, .text = "done" } }), "the four instance commands finished", .{});
    for ([_][]const u8{ "dir", "ssh", "workspace", "agent" }) |name| {
        const ms = controlCommandMs(io, instance_log, name);
        controlCheck(out, &failures, ms != null and ms.? < 3000, "conduit {s} exited 0 quickly ({?d} ms)", .{ name, ms });
    }
    const project_key = controlWorkspaceIn(self, project_dir);
    controlCheck(out, &failures, project_key != null, "conduit <dir> opened a workspace in that directory", .{});
    const ssh_key = self.workspace_registry.keyForName("nowhere");
    controlCheck(out, &failures, if (ssh_key) |key| (if (self.workspace_registry.byKey(key)) |model| model.contextKind() == .ssh else false) else false, "conduit ssh opened an SSH workspace", .{});
    if (ssh_key) |key| {
        var ssh_row_buffer: [64]u8 = undefined;
        var ssh_prefix_buffer: [80]u8 = undefined;
        const ssh_prefix = try std.fmt.bufPrint(&ssh_prefix_buffer, "{s}.ssh.", .{try workspaceSemanticId(&ssh_row_buffer, key)});
        const state = if (self.presentationByKey(key)) |presentation| (if (presentation.remote) |record| remote.stateWords(record.state) else "none") else "none";
        controlCheck(out, &failures, try waitForControl(self, io, out, .{ .role_label = .{ .prefix = ssh_prefix, .text = "" } }), "the SSH workspace shows its connection state ({s}) without hanging", .{state});
    }
    controlCheck(out, &failures, self.workspace_registry.activeKey() == first_key, "conduit workspace open focused the named workspace", .{});
    const agent_runner = self.agents.runnerForSession(first_key, self.activePresentation().active_session_id);
    controlCheck(out, &failures, agent_runner != null and agent_runner.?.choice == .fake, "conduit agent launched the harness in the current workspace", .{});
    const runner = agent_runner orelse return 1;
    const agent_number = @intFromEnum(runner.agent_id orelse return 1);

    // view.agent, from the api tab's shell, by the agent's id.
    _ = try clickTabsElement(self, io, out, api_id);
    _ = try controlFocusTerminal(self, io, out);
    controlCheck(out, &failures, try waitForControl(self, io, out, .{ .terminal_text = "ctl$" }), "the api tab is back in front", .{});
    _ = try controlType(self, io, out, "'{s}' control view.agent '{{\"agent_id\":\"{d}\"}}' > '{s}/view' 2>&1; echo \"rc=$?\" >> '{s}/view'", .{ exe, agent_number, dir, dir });
    var view_buffer: [64]u8 = undefined;
    const view_id = try std.fmt.bufPrint(&view_buffer, "agent.view.{d}", .{agent_number});
    controlCheck(out, &failures, try waitForControlFile(self, io, out, dir, "view", "rc=0") and
        try waitForControl(self, io, out, .{ .element = view_id }), "view.agent showed the agent's view", .{});

    // agent.event: a raw line and a hook-wrapped one reach the fake's sink.
    _ = try clickTabsElement(self, io, out, api_id);
    _ = try controlFocusTerminal(self, io, out);
    _ = try waitForControl(self, io, out, .{ .terminal_text = "ctl$" });
    const token = runner.token.text();
    _ = try controlType(self, io, out, "printf '%s' '{{\"conduit\":{{\"v\":1,\"event\":\"Stop\"}},\"payload\":{{\"probe\":\"control-event\"}}}}' | '{s}' control agent.event --agent={s} > '{s}/event' 2>&1; echo \"rc=$?\" >> '{s}/event'", .{ exe, token, dir, dir });
    controlCheck(out, &failures, try waitForControlFile(self, io, out, dir, "event", "rc=0"), "agent.event was accepted", .{});
    _ = try controlType(self, io, out, "printf '%s' '{{\"probe\":\"hook-event\"}}' | '{s}' control agent.event --agent={s} --event=Stop > '{s}/hook' 2>&1; echo \"rc=$?\" >> '{s}/hook'", .{ exe, token, dir, dir });
    controlCheck(out, &failures, try waitForControlFile(self, io, out, dir, "hook", "rc=0"), "the hook form exited 0", .{});
    var sink_buffer: [path_capacity]u8 = undefined;
    const sink_events = try std.fmt.bufPrint(&sink_buffer, "{s}/{s}", .{ runner.sink_dir, agent.pi.events_file_name });
    var hook_line_buffer: [256]u8 = undefined;
    const hook_line = try std.fmt.bufPrint(&hook_line_buffer, "{{\"conduit\":{{\"v\":1,\"event\":\"Stop\",\"token\":\"{s}\"}},\"payload\":{{\"probe\":\"hook-event\"}}}}", .{token});
    controlCheck(out, &failures, try waitForControl(self, io, out, .{ .file = .{ .path = sink_events, .text = "{\"conduit\":{\"v\":1,\"event\":\"Stop\"},\"payload\":{\"probe\":\"control-event\"}}" } }) and
        try waitForControl(self, io, out, .{ .file = .{ .path = sink_events, .text = hook_line } }), "the fake runner's sink received both event lines", .{});

    // view.backlog from the project workspace's shell.
    const project = project_key orelse return 1;
    var project_row_buffer: [64]u8 = undefined;
    _ = try clickTabsElement(self, io, out, try workspaceSemanticId(&project_row_buffer, project));
    _ = try controlFocusTerminal(self, io, out);
    controlCheck(out, &failures, try waitForControl(self, io, out, .{ .terminal_text = "$" }) and self.workspace_registry.activeKey() == project, "the project workspace's shell is in front", .{});
    _ = try controlType(self, io, out, "'{s}' control view.backlog > '{s}/backlog' 2>&1; echo \"rc=$?\" >> '{s}/backlog'", .{ exe, dir, dir });
    controlCheck(out, &failures, try waitForControl(self, io, out, .{ .element = "backlog.view" }) and
        try waitForControl(self, io, out, .{ .label = .{ .id = "backlog.task.TASK-1", .text = "TASK-1" } }) and
        try waitForControlFile(self, io, out, dir, "backlog", "rc=0"), "view.backlog opened the workspace's backlog", .{});
    _ = try backlogChordKey(self, io, out);
    _ = try waitForControl(self, io, out, .{ .element_absent = "backlog.view" });

    // The scratchpad: no control variables, and a stolen token naming it is
    // refused before anything happens.
    const project_presentation = self.presentationByKey(project) orelse return 1;
    const project_model = self.workspace_registry.byKey(project) orelse return 1;
    const project_token = (project_presentation.control_token orelse return 1).text();
    const scratchpad_id = @intFromEnum(project_model.scratchpadId());
    const tabs_before = project_model.tabCount();
    _ = try scratchpadChord(self, io, out, false);
    controlCheck(out, &failures, try waitForControl(self, io, out, .{ .scratchpad_text = "$" }), "the scratchpad's shell is up", .{});
    _ = try controlType(self, io, out, "echo \"TOKEN=[${{CONDUIT_CONTROL_TOKEN-unset}}][${{CONDUIT_CONTROL_ENDPOINT-unset}}][${{CONDUIT_CONTROL_SESSION-unset}}]\"", .{});
    controlCheck(out, &failures, try waitForControl(self, io, out, .{ .scratchpad_text = "TOKEN=[unset][unset][unset]" }), "the scratchpad has no control variables", .{});
    _ = try controlType(self, io, out, "CONDUIT_CONTROL_ENDPOINT='{s}' CONDUIT_CONTROL_TOKEN={s} CONDUIT_CONTROL_SESSION={d} '{s}' control tab.open > '{s}/stolen' 2>&1; echo \"rc=$?\" >> '{s}/stolen'", .{ endpoint, project_token, scratchpad_id, exe, dir, dir });
    controlCheck(out, &failures, try waitForControlFile(self, io, out, dir, "stolen", "rc=1") and
        try waitForControlFile(self, io, out, dir, "stolen", "ScratchpadNotAddressable") and project_model.tabCount() == tabs_before, "a stolen token naming the scratchpad was refused and opened nothing", .{});
    _ = try controlType(self, io, out, "CONDUIT_CONTROL_ENDPOINT='{s}' CONDUIT_CONTROL_TOKEN=00000000000000000000000000000000 '{s}' control ping > '{s}/bad' 2>&1; echo \"rc=$?\" >> '{s}/bad'", .{ endpoint, exe, dir, dir });
    controlCheck(out, &failures, try waitForControlFile(self, io, out, dir, "bad", "rc=1") and
        try waitForControlFile(self, io, out, dir, "bad", "Unauthorized"), "conduit control with a bad token exits non-zero", .{});
    _ = try postNamedKey(self, io, out, .escape, .{});
    _ = try waitForControl(self, io, out, .{ .element_absent = "scratchpad" });

    // The final frame: the API-opened tab, its split and its status mark.
    var first_row_buffer: [64]u8 = undefined;
    _ = try clickTabsElement(self, io, out, try workspaceSemanticId(&first_row_buffer, first_key));
    _ = try waitForControl(self, io, out, .{ .element = api_id });
    _ = try clickTabsElement(self, io, out, api_id);
    _ = try controlFocusTerminal(self, io, out);
    _ = try waitForControl(self, io, out, .{ .terminal_text = "ctl$" });
    _ = try controlType(self, io, out, "'{s}' control tab.status '{{\"text\":\"busy\",\"attention\":true}}'", .{exe});
    controlCheck(out, &failures, try waitForControl(self, io, out, .{ .label = .{ .id = api_id, .text = "! busy api" } }), "the status mark is back for the screenshot", .{});
    try controlScreenshot(self, io, out);

    out.print("control-test: {d} failure(s)\n", .{failures}) catch {};
    out.flush() catch {};
    return if (failures == 0) 0 else 1;
}

// --agent-view-test (TASK-57) --------------------------------------------------

fn viewCheck(out: *Writer, failures: *usize, ok: bool, comptime format: []const u8, args: anytype) void {
    out.print("agent-view-test: {s} " ++ format ++ "\n", .{if (ok) "ok  " else "FAIL"} ++ args) catch {};
    if (!ok) failures.* += 1;
}

/// The first element whose id starts with `prefix` and whose label contains
/// `text`.
fn viewElement(self: *const App, prefix: []const u8, text: []const u8) ?*const ui.Element {
    for (self.ui_tree.elements()) |*element| {
        if (!std.mem.startsWith(u8, element.id.value, prefix)) continue;
        if (std.mem.indexOf(u8, element.label, text) != null) return element;
    }
    return null;
}

fn viewChordKey(self: *App, io: Io, out: *Writer, codepoint: u21) !bool {
    const mods: platform.Mods = switch (self.binding_profile) {
        .macos => .{ .shift = true, .super = true },
        .linux_windows => .{ .ctrl = true, .shift = true },
    };
    return postKey(self, io, out, codepoint, mods);
}

/// Exercise TASK-57 through real PTYs and SDL events: the fake agent's
/// structured view toggled by chord and palette, scrolled by keys, both
/// permission requests answered (keyboard, then mouse) through the runner's
/// worker to the adapter, a file reference opened in vi at its line, a drag
/// selection copied and pasted into the raw terminal, a search over the
/// view's rows, and the raw terminal intact underneath.
fn agentViewTest(self: *App, io: Io, out: *Writer) !u8 {
    var failures: usize = 0;
    var os_trace: AgentOsTrace = .{};
    self.agents.notifier = .{ .context = &os_trace, .notify_fn = AgentOsTrace.record };
    defer self.agents.notifier = .{ .notify_fn = App.discardOsNotification };
    var editor_trace: EditorSpawnTrace = .{};
    self.editor_spawn_observer = .{ .context = &editor_trace, .observe_fn = recordEditorSpawn };
    defer self.editor_spawn_observer = .{};
    const test_dir = self.agentTestDir() orelse return 1;

    // The file the script's reference names, at the line it names.
    var sample_buffer: [path_capacity]u8 = undefined;
    const sample = try std.fmt.bufPrint(&sample_buffer, "{s}/{s}", .{ test_dir, app_agents.fake_view_sample_name });
    try Dir.cwd().writeFile(io, .{ .sub_path = sample, .data = "line one\nline two\nVIEW-SAMPLE-FAILING-LINE\nline four\n" });

    try self.drawFrame();
    viewCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .terminal_text = "AGENT-TEST-READY" }), "the first tab's real PTY peer became ready", .{});
    viewCheck(out, &failures, try launchFakeAgentByMouse(self, io, out) and
        try waitForAgent(self, io, out, &os_trace, .{ .element = "workspace.1.tab.2.agent.idle" }) and
        try waitForAgent(self, io, out, &os_trace, .{ .terminal_text = "FAKE-AGENT-READY" }), "the fake agent launched by mouse in its own tab", .{});
    const model = self.activeWorkspace();
    const key = self.workspace_registry.activeKey() orelse return 1;
    const agent_tab = model.activeTabId() orelse return 1;
    const agent_session = model.focusedPaneSessionId(agent_tab) orelse return 1;
    const runner = self.agents.runnerForSession(key, agent_session) orelse return 1;

    // One typed line releases the transcript up to the second request.
    _ = try agentTypeLine(self, io, out, "go");
    viewCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .element = "workspace.1.tab.2.agent.waiting_permission" }) and
        try waitForAgent(self, io, out, &os_trace, .{ .terminal_text = "FAKE-STEP 1" }), "the scripted events arrived while the raw terminal showed", .{});

    // AC5 by chord: the view replaces the terminal.
    _ = try viewChordKey(self, io, out, 'a');
    viewCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .element = "agent.view.1" }), "the chord showed the structured view agent.view.1", .{});
    try self.drawFrame();
    viewCheck(out, &failures, viewElement(self, "agent.view.1.perm.view-1.allow", "Allow once") != null and
        viewElement(self, "agent.view.1.perm.view-1.deny", "Reject") != null and
        viewElement(self, "agent.view.1.perm.view-2.allow", "Allow once") != null, "both pending requests show one control per harness decision", .{});
    const pending_pixels = try self.allocator.dupe(u8, try self.capture());
    defer self.allocator.free(pending_pixels);

    // AC1: every event kind is terminal-styled rows.
    const kinds = [_]struct { prefix: []const u8, text: []const u8, what: []const u8 }{
        .{ .prefix = "agent.view.1.row.", .text = "⚙ Bash zig build test", .what = "tool use" },
        .{ .prefix = "agent.view.1.row.", .text = "fake › One test fails", .what = "assistant message" },
        .{ .prefix = "agent.view.1.ref.", .text = app_agents.fake_view_sample_name ++ ":3", .what = "file reference" },
        .{ .prefix = "agent.view.1.row.", .text = "? Run: zig build test --summary all", .what = "permission title" },
        .{ .prefix = "agent.view.1.row.", .text = "◆ subagent explore started", .what = "subagent start" },
        .{ .prefix = "agent.view.1.row.", .text = "◇ subagent explore finished", .what = "subagent stop" },
        .{ .prefix = "agent.view.1.row.", .text = "▪ Claude: Claude needs your permission", .what = "notification" },
    };
    for (kinds) |kind| viewCheck(out, &failures, viewElement(self, kind.prefix, kind.text) != null, "a {s} row: '{s}'", .{ kind.what, kind.text });

    // Scrolling by keys: Home shows the first rows, End returns to the newest.
    _ = try postNamedKey(self, io, out, .home, .{});
    try self.drawFrame();
    viewCheck(out, &failures, viewElement(self, "agent.view.1.row.0", "· working") != null and
        viewElement(self, "agent.view.1.row.", "you › Run the tests") != null, "Home scrolled to the first rows (status, then the human's message)", .{});
    _ = try postNamedKey(self, io, out, .page_down, .{});
    _ = try postNamedKey(self, io, out, .up, .{});
    _ = try postNamedKey(self, io, out, .end, .{});
    try self.drawFrame();
    viewCheck(out, &failures, self.ui_tree.byId(.{ .value = "agent.view.1.perm.view-2.deny" }) != null and
        self.ui_tree.byId(.{ .value = "agent.view.1.row.0" }) == null, "End scrolled back to the newest rows", .{});

    // Keys and text over the view never reach the hidden terminal.
    try self.window.postTextInput("zzq");
    _ = try pumpUntil(self, io, out, .text_input, self_test_event_budget_ms);
    _ = try postKey(self, io, out, 'x', .{});

    // AC3 by keyboard: Tab to the first request's second decision, Enter.
    _ = try postNamedKey(self, io, out, .tab, .{});
    _ = try postNamedKey(self, io, out, .tab, .{});
    const focused_second = if (self.ui_tree.focusedElement()) |element| std.mem.eql(u8, element.id.value, "agent.view.1.perm.view-1.deny") else false;
    _ = try postNamedKey(self, io, out, .enter, .{});
    const rejected = try waitForAgent(self, io, out, &os_trace, .{ .label = .{ .id = "agent.view.1.perm.view-1.outcome", .text = "Reject: rejected" } });
    const fake = &runner.backend.fake;
    const keyboard_answer = fake.permissionAnswer();
    viewCheck(out, &failures, focused_second and rejected and std.mem.eql(u8, keyboard_answer.request, "view-1") and
        std.mem.eql(u8, keyboard_answer.decision, "deny") and self.ui_tree.byId(.{ .value = "agent.view.1.perm.view-1.deny" }) == null, "Tab, Tab, Enter answered view-1 with the harness's 'deny'; the adapter got it and the row shows the outcome without controls (focused {})", .{focused_second});

    // AC3 by mouse: a click on the second request's first decision.
    viewCheck(out, &failures, try clickTabsElement(self, io, out, "agent.view.1.perm.view-2.allow") and
        try waitForAgent(self, io, out, &os_trace, .{ .label = .{ .id = "agent.view.1.perm.view-2.outcome", .text = "Allow once: allowed" } }) and
        std.mem.eql(u8, fake.permissionAnswer().request, "view-2") and std.mem.eql(u8, fake.permissionAnswer().decision, "allow") and
        fake.answers == 2, "a click answered view-2 with 'allow' through the worker; two answers reached the adapter", .{});

    // AC4: drag across the two rows of the first long message and copy.
    _ = try postNamedKey(self, io, out, .home, .{});
    try self.drawFrame();
    const first_row = viewElement(self, "agent.view.1.row.", "fake › I will run") orelse {
        viewCheck(out, &failures, false, "the long message's first row is visible", .{});
        return 1;
    };
    var first_label_buffer: [512]u8 = undefined;
    const first_label = try std.fmt.bufPrint(&first_label_buffer, "{s}", .{first_row.label});
    const first_bounds = first_row.bounds;
    var second_id_buffer: [agent_view_id_capacity]u8 = undefined;
    const row_number = std.fmt.parseUnsigned(usize, first_row.id.value["agent.view.1.row.".len..], 10) catch 0;
    const second_id = try std.fmt.bufPrint(&second_id_buffer, "agent.view.1.row.{d}", .{row_number + 1});
    const second_row = self.ui_tree.byId(.{ .value = second_id }) orelse return 1;
    var second_label_buffer: [512]u8 = undefined;
    const second_label = std.mem.trimEnd(u8, try std.fmt.bufPrint(&second_label_buffer, "{s}", .{second_row.label}), " ");
    const second_bounds = second_row.bounds;
    const scale = self.window.state.scale.factor;
    const start_x = (@as(f32, @floatFromInt(first_bounds.x)) + 1) / scale;
    const start_y = (@as(f32, @floatFromInt(first_bounds.y)) + @as(f32, @floatFromInt(first_bounds.height)) / 2) / scale;
    const end_x = (@as(f32, @floatFromInt(second_bounds.x + @as(i32, @intCast(second_bounds.width)))) - 1) / scale;
    const end_y = (@as(f32, @floatFromInt(second_bounds.y)) + @as(f32, @floatFromInt(second_bounds.height)) / 2) / scale;
    const dragged = try postButton(self, io, out, .{ .button = .left, .action = .press, .x = start_x, .y = start_y }) and
        try postMotion(self, io, out, .{ .buttons = .{ .left = true }, .x = end_x, .y = end_y }) and
        try postButton(self, io, out, .{ .button = .left, .action = .release, .x = end_x, .y = end_y });
    _ = try viewChordKey(self, io, out, 'c');
    const copied = clipboardNow(self) catch try self.allocator.dupe(u8, "");
    defer self.allocator.free(copied);
    var expected_buffer: [1024]u8 = undefined;
    const expected_copy = try std.fmt.bufPrint(&expected_buffer, "{s}\n{s}", .{ first_label, second_label });
    viewCheck(out, &failures, dragged and std.mem.eql(u8, copied, expected_copy), "a drag over two rows copied them newline-joined ({d} byte(s))", .{copied.len});
    try self.drawFrame();
    const selection_pixels = try self.allocator.dupe(u8, try self.capture());
    defer self.allocator.free(selection_pixels);

    // AC4 by keyboard: Shift+Down from the top row selects the human's whole
    // message row; one line, so it can be pasted without a confirmation.
    _ = try postNamedKey(self, io, out, .escape, .{});
    _ = try postNamedKey(self, io, out, .home, .{});
    _ = try postNamedKey(self, io, out, .down, .{});
    _ = try postNamedKey(self, io, out, .down, .{});
    _ = try postNamedKey(self, io, out, .down, .{ .shift = true });
    _ = try viewChordKey(self, io, out, 'c');
    const line_copied = clipboardNow(self) catch try self.allocator.dupe(u8, "");
    defer self.allocator.free(line_copied);
    viewCheck(out, &failures, std.mem.eql(u8, line_copied, "you › Run the tests and fix whatever fails."), "Shift+Down selected one row and the copy chord copied '{s}'", .{line_copied});

    // Search the view's rows: highlight, navigate, close.
    _ = try viewChordKey(self, io, out, 'f');
    const search_open = try waitForAgent(self, io, out, &os_trace, .{ .element = "search.dialog" });
    try self.window.postTextInput("test");
    _ = try pumpUntil(self, io, out, .text_input, self_test_event_budget_ms);
    try self.drawFrame();
    const first_match = viewElement(self, "search.match.", "Search match");
    const first_status = std.mem.indexOf(u8, (self.ui_tree.byId(.{ .value = "search.status" }) orelse return 1).label, "1/") != null;
    viewCheck(out, &failures, search_open and first_match != null and first_status and self.search_view != null and
        self.search_match_count >= 3, "search over the view found {d} highlighted matches of 'test', the first active", .{self.search_match_count});
    _ = try postNamedKey(self, io, out, .enter, .{});
    try self.drawFrame();
    const second_status = std.mem.indexOf(u8, (self.ui_tree.byId(.{ .value = "search.status" }) orelse return 1).label, "2/") != null;
    viewCheck(out, &failures, second_status and self.search_active_index == 1, "Enter moved to the next match", .{});
    _ = try postNamedKey(self, io, out, .escape, .{});
    viewCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .element_absent = "search.dialog" }) and
        self.ui_tree.byId(.{ .value = "agent.view.1" }) != null, "Escape closed the search and the view stayed", .{});

    // AC2: a click on the file reference opens vi at its line in a new tab.
    const reference = viewElement(self, "agent.view.1.ref.", app_agents.fake_view_sample_name) orelse return 1;
    var reference_id_buffer: [agent_view_id_capacity]u8 = undefined;
    const reference_id = try std.fmt.bufPrint(&reference_id_buffer, "{s}", .{reference.id.value});
    var expected_argv_buffer: [path_capacity + 32]u8 = undefined;
    const expected_argv = try std.fmt.bufPrint(&expected_argv_buffer, "vi +{d} -- {s}", .{ app_agents.fake_view_sample_line, sample });
    viewCheck(out, &failures, try clickTabsElement(self, io, out, reference_id) and editor_trace.calls == 1 and
        std.mem.eql(u8, editor_trace.argv(), expected_argv), "a click on the reference spawned '{s}'", .{editor_trace.argv()});
    viewCheck(out, &failures, model.activeTabId() != agent_tab and
        try waitForAgent(self, io, out, &os_trace, .{ .terminal_text = "VIEW-SAMPLE-FAILING-LINE" }), "the new tab drew the file in vi", .{});

    // Back to the agent: its view is still shown.
    var tab_id_buffer: [workspace_semantic_capacity]u8 = undefined;
    _ = try clickTabsElement(self, io, out, try tabSemanticId(&tab_id_buffer, key, agent_tab));
    viewCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .active_tab = agent_tab }) and
        try waitForAgent(self, io, out, &os_trace, .{ .element = "agent.view.1" }), "the agent's tab still shows its view", .{});

    // AC5 by palette: back to the raw terminal, intact, with none of the
    // keys typed over the view.
    _ = try runPaletteCommandByKeyboard(self, io, out, "Agent: toggle view");
    viewCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .element_absent = "agent.view.1" }) and
        self.activeLive().terminal().visibleTextContains("FAKE-STEP 1") and
        self.activeLive().terminal().visibleTextContains("FAKE-AGENT-READY") and
        !self.activeLive().terminal().visibleTextContains("zzq") and
        !self.activeLive().terminal().visibleTextContains("FAKE-STEP 2"), "the palette toggled back to the raw terminal, intact and untouched by view keys", .{});

    // The copied row pastes into the raw terminal; Enter makes it a line
    // the fake reads, which releases the end of the turn.
    _ = try viewChordKey(self, io, out, 'v');
    const pasted = try waitForAgent(self, io, out, &os_trace, .{ .terminal_text = "Run the tests and fix whatever fails." });
    _ = try postNamedKey(self, io, out, .enter, .{});
    viewCheck(out, &failures, pasted and try waitForAgent(self, io, out, &os_trace, .{ .terminal_text = "FAKE-STEP 2" }), "the copied row arrived in the raw terminal by the paste chord", .{});

    // The view follows new events at the bottom.
    _ = try viewChordKey(self, io, out, 'a');
    viewCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .label = .{ .id = "agent.view.1", .text = "" } }) and
        try waitForAgent(self, io, out, &os_trace, .{ .role_label = .{ .prefix = "agent.view.1.row.", .text = "fake › All tests pass now." } }) and
        try waitForAgent(self, io, out, &os_trace, .{ .role_label = .{ .prefix = "agent.view.1.row.", .text = "· done" } }), "the view showed the end of the turn as it arrived", .{});
    _ = try viewChordKey(self, io, out, 'a');
    viewCheck(out, &failures, try waitForAgent(self, io, out, &os_trace, .{ .element_absent = "agent.view.1" }), "the chord toggled back to the raw terminal", .{});

    var screenshot_path_buffer: [path_capacity]u8 = undefined;
    var id_buffer: [path_capacity]u8 = undefined;
    const run_id = try generateRunId(io, &id_buffer);
    const screenshot_path = try std.fmt.bufPrint(&screenshot_path_buffer, "{s}{c}agent-view-test-{s}.png", .{ fallback_log_dir, std.fs.path.sep, run_id });
    try writePngOffThread(self.allocator, io, screenshot_path, pending_pixels, self.size);
    var selection_path_buffer: [path_capacity]u8 = undefined;
    const selection_path = try std.fmt.bufPrint(&selection_path_buffer, "{s}{c}agent-view-test-{s}-selection.png", .{ fallback_log_dir, std.fs.path.sep, run_id });
    try writePngOffThread(self.allocator, io, selection_path, selection_pixels, self.size);
    out.print("agent-view-test: screenshot {s}\n", .{screenshot_path}) catch {};
    out.print("agent-view-test: screenshot {s}\n", .{selection_path}) catch {};
    out.print("agent-view-test: {d} failure(s)\n", .{failures}) catch {};
    out.flush() catch {};
    return if (failures == 0) 0 else 1;
}

fn configTestPath(io: Io, env: EnvSource, buffer: []u8) ![]const u8 {
    const base = firstEnv(env, temp_dir_vars[0..]) orelse "/tmp";
    const root = if (base.len != 0 and base[0] == '/') base else "/tmp";
    var id_buffer: [path_capacity]u8 = undefined;
    const id = try generateRunId(io, &id_buffer);
    return std.fmt.bufPrint(buffer, "{s}/conduit-config-test-{s}/conduit/config", .{ root, id });
}

fn writeConfigTestFile(io: Io, path: []const u8, data: []const u8) !void {
    if (config.directoryOf(path)) |dir| try Dir.cwd().createDirPath(io, dir);
    try Dir.cwd().writeFile(io, .{ .sub_path = path, .data = data });
}

/// Replace the file by writing a sibling and renaming it over the original.
fn renameConfigTestFile(io: Io, path: []const u8, data: []const u8) !void {
    var buffer: [path_capacity]u8 = undefined;
    const temporary = try std.fmt.bufPrint(&buffer, "{s}.tmp", .{path});
    try Dir.cwd().writeFile(io, .{ .sub_path = temporary, .data = data });
    try Dir.cwd().rename(temporary, Dir.cwd(), path, io);
}

/// Remove `--config-test`'s private directory: two levels above the file.
fn removeConfigTestDir(io: Io, path: []const u8) void {
    const conduit_dir = config.directoryOf(path) orelse return;
    const root = config.directoryOf(conduit_dir) orelse return;
    if (std.mem.indexOf(u8, root, "conduit-config-test-") == null) return;
    Dir.cwd().deleteTree(io, root) catch |err| {
        log.warn("could not remove the config-test directory: {s}", .{@errorName(err)});
    };
}

const ConfigWait = union(enum) {
    reloads: usize,
    element: []const u8,
    no_element: []const u8,
    active_text: []const u8,
    cell_height_above: u32,
    /// No asynchronous face load is in flight.
    fonts_idle,
    /// The committed theme's palette is this one.
    theme: theme.Palette,
    /// The face on screen is the wanted one and no font worker is running.
    font_settled,
    /// Settled, and drawn with this family.
    drawn_family: []const u8,
};

fn configWaitMet(self: *App, condition: ConfigWait) !bool {
    return switch (condition) {
        .reloads => |count| self.config_reload_count >= count,
        .element => |id| self.ui_tree.byId(.{ .value = id }) != null,
        .no_element => |id| self.ui_tree.byId(.{ .value = id }) == null,
        .active_text => |text| found: {
            try self.activeLive().terminal().refresh(self.allocator);
            break :found self.activeLive().terminal().visibleTextContains(text);
        },
        .cell_height_above => |height| self.font_load == null and self.fonts.metrics().cell.height_px > height,
        .fonts_idle => self.font_load == null,
        .theme => |palette| self.theme_palette.eql(palette),
        .font_settled => self.fontSettled(),
        .drawn_family => |name| self.fontSettled() and std.mem.eql(u8, self.fonts.familyName(), name),
    };
}

fn waitForConfig(self: *App, io: Io, out: *Writer, condition: ConfigWait) !bool {
    const deadline = Io.Clock.real.now(io).nanoseconds + config_test_budget_ms * std.time.ns_per_ms;
    while (true) {
        if (try configWaitMet(self, condition)) return true;
        const event = self.window.pump(@min(eventWaitBudget(io, deadline, false), idle_tick_ms));
        if (event) |one| {
            describeEvent(out, one) catch {};
            if (!try self.handle(one)) return false;
        }
        if (self.poll()) self.scheduler.invalidate();
        if (self.scheduler.shouldDraw()) try self.drawFrame();
        if (Io.Clock.real.now(io).nanoseconds >= deadline) return try configWaitMet(self, condition);
    }
}

fn configCheck(out: *Writer, failures: *usize, ok: bool, comptime format: []const u8, args: anytype) void {
    out.print("config-test: {s} " ++ format ++ "\n", .{if (ok) "ok  " else "FAIL"} ++ args) catch {};
    if (!ok) failures.* += 1;
}

/// The scratchpad's outer height for `percent` of the current canvas, the
/// same rounding `scratchpadBounds` uses.
fn expectedScratchpadHeight(self: *const App, percent: u32) u32 {
    const canvas = self.ui_canvas.bounds();
    const wanted = (canvas.height * percent + 99) / 100;
    return @min(canvas.height, @max(@as(u32, 3), wanted));
}

fn configChord(self: *App, io: Io, out: *Writer, letter: u21) !bool {
    return postKey(self, io, out, letter, .{ .ctrl = true, .alt = true });
}

/// Exercise TASK-37 end to end: a settings file in a private directory is
/// loaded at startup, its keybindings and scratchpad size take effect through
/// real SDL keys, a malformed edit shows a specific `config.error` line while
/// every previous and still-valid value keeps working, a rename-replace save
/// repairs it without a restart, and `config.open` creates the file and opens
/// it in an editor tab by keyboard and by mouse.
fn configTest(self: *App, io: Io, out: *Writer) !u8 {
    var failures: usize = 0;
    const path_copy = self.config_path orelse {
        out.writeAll("config-test: FAIL no settings path\n") catch {};
        return 1;
    };
    var path_buffer: [path_capacity]u8 = undefined;
    @memcpy(path_buffer[0..path_copy.len], path_copy);
    const path = path_buffer[0..path_copy.len];
    var editor_trace: EditorSpawnTrace = .{};
    self.editor_spawn_observer = .{ .context = &editor_trace, .observe_fn = recordEditorSpawn };
    defer self.editor_spawn_observer = .{};

    try self.drawFrame();
    configCheck(out, &failures, try waitForPanes(self, io, out, .{ .focused_text = "CONFIG-READY" }), "the real config-test child became ready", .{});
    configCheck(out, &failures, self.config_watcher != null and self.configErrorText() == null and
        self.ui_tree.byId(.{ .value = "config.error" }) == null, "the startup file loaded cleanly and is watched", .{});

    // Configured keybinding: Ctrl+Alt+P opens the palette, the shipped chord no longer does.
    configCheck(out, &failures, try configChord(self, io, out, 'p') and self.paletteVisible(), "the configured Ctrl+Alt+P opened the palette through SDL", .{});
    _ = try postNamedKey(self, io, out, .escape, .{});
    const routes_before_unbound = self.terminal_key_route_count;
    _ = try paletteChord(self, io, out);
    configCheck(out, &failures, !self.paletteVisible() and self.terminal_key_route_count > routes_before_unbound, "the unbound shipped chord reached the terminal instead of the palette", .{});

    // Configured scratchpad size, through the shipped 50-percent binding.
    _ = try scratchpadChord(self, io, out, false);
    const small = self.scratchpadBounds();
    configCheck(out, &failures, small != null and small.?.height == expectedScratchpadHeight(self, 30), "scratchpad.size = 30 sized the small scratchpad", .{});
    _ = try scratchpadChord(self, io, out, false);
    configCheck(out, &failures, !self.scratchpadVisible(), "the small scratchpad binding hid it again", .{});

    // A malformed edit: visible, specific, and the previous value stands.
    const reloads_before_malformed = self.config_reload_count;
    try writeConfigTestFile(io, path, config_test_malformed);
    configCheck(out, &failures, try waitForConfig(self, io, out, .{ .reloads = reloads_before_malformed + 1 }) and
        try waitForConfig(self, io, out, .{ .element = "config.error" }), "the watcher applied the edit without a restart and showed config.error", .{});
    const error_element = self.ui_tree.byId(.{ .value = "config.error" });
    configCheck(out, &failures, error_element != null and std.mem.eql(u8, error_element.?.role, "config_error") and
        std.mem.startsWith(u8, error_element.?.label, "config:3: scratchpad.size:"), "config.error names line 3 and the key: '{s}'", .{if (error_element) |element| element.label else ""});
    var saw_action_line = false;
    for (self.config_current.diagnostics.items) |diagnostic| {
        if (diagnostic.line == 5 and std.mem.eql(u8, diagnostic.message, "keybind: unknown action")) saw_action_line = true;
    }
    configCheck(out, &failures, saw_action_line, "an unknown keybind action was reported on its own line", .{});
    configCheck(out, &failures, try configChord(self, io, out, 'p') and self.paletteVisible(), "the still-valid keybinding kept working with an error present", .{});
    _ = try postNamedKey(self, io, out, .escape, .{});
    _ = try scratchpadChord(self, io, out, false);
    const kept = self.scratchpadBounds();
    configCheck(out, &failures, kept != null and kept.?.height == expectedScratchpadHeight(self, 30), "the malformed scratchpad.size kept the previous 30 percent", .{});
    _ = try scratchpadChord(self, io, out, false);
    _ = try scratchpadChord(self, io, out, true);
    const large = self.scratchpadBounds();
    configCheck(out, &failures, large != null and large.?.height == expectedScratchpadHeight(self, 70), "the valid line after the error still applied scratchpad.large_size = 70", .{});
    _ = try scratchpadChord(self, io, out, true);
    try self.drawFrame();
    _ = try self.capture();

    // Repair by rename-replace: the error clears and the new values apply.
    const reloads_before_fix = self.config_reload_count;
    const cell_height_before = self.fonts.metrics().cell.height_px;
    try renameConfigTestFile(io, path, config_test_fixed);
    configCheck(out, &failures, try waitForConfig(self, io, out, .{ .reloads = reloads_before_fix + 1 }) and
        try waitForConfig(self, io, out, .{ .no_element = "config.error" }), "a rename-replace save was seen and cleared config.error", .{});
    configCheck(out, &failures, try configChord(self, io, out, 'o') and self.paletteVisible(), "the newly configured Ctrl+Alt+O opened the palette", .{});
    _ = try postNamedKey(self, io, out, .escape, .{});
    _ = try configChord(self, io, out, 'p');
    configCheck(out, &failures, !self.paletteVisible(), "the chord removed from the file no longer opens the palette", .{});
    _ = try scratchpadChord(self, io, out, false);
    const repaired = self.scratchpadBounds();
    configCheck(out, &failures, repaired != null and repaired.?.height == expectedScratchpadHeight(self, 40), "scratchpad.size = 40 applied without a restart", .{});
    _ = try scratchpadChord(self, io, out, false);
    configCheck(out, &failures, try waitForConfig(self, io, out, .{ .cell_height_above = cell_height_before }), "font.size = 18 re-created the face with taller cells ({d} -> {d} px)", .{ cell_height_before, self.fonts.metrics().cell.height_px });

    // Missing file: the built-in layer returns, including the shipped palette chord.
    const reloads_before_delete = self.config_reload_count;
    try Dir.cwd().deleteFile(io, path);
    configCheck(out, &failures, try waitForConfig(self, io, out, .{ .reloads = reloads_before_delete + 1 }) and
        self.configErrorText() == null and self.scratchpad_percent_small == 50, "deleting the file returned to the documented defaults with no error", .{});
    // The deletion also dropped `font.size`, so a face load is in flight. Let it
    // settle before spawning the editor: a grid that changes under a starting
    // child is a separate concern from whether the editor opens the file.
    configCheck(out, &failures, try waitForConfig(self, io, out, .fonts_idle), "the default face finished loading after the deletion", .{});

    // Keyboard path: the shipped Ctrl+, creates the file and opens it in an editor tab.
    const tabs_before_keyboard = self.activeWorkspace().tabCount();
    _ = try postKey(self, io, out, ',', switch (self.binding_profile) {
        .macos => .{ .super = true },
        .linux_windows => .{ .ctrl = true },
    });
    var expected_argv_buffer: [path_capacity + 16]u8 = undefined;
    const expected_argv = try std.fmt.bufPrint(&expected_argv_buffer, "vi -- {s}", .{path});
    configCheck(out, &failures, self.activeWorkspace().tabCount() == tabs_before_keyboard + 1 and
        editor_trace.calls == 1 and std.mem.eql(u8, editor_trace.argv(), expected_argv), "Ctrl+, opened an editor tab with argv '{s}'", .{editor_trace.argv()});
    var written_buffer: [config.defaults_document.len + 1]u8 = undefined;
    const written = Dir.cwd().readFile(io, path, &written_buffer) catch "";
    configCheck(out, &failures, std.mem.eql(u8, written, config.defaults_document), "config.open created the file from the documented defaults", .{});
    configCheck(out, &failures, try waitForConfig(self, io, out, .{ .active_text = "Conduit configuration" }), "the editor drew the new file in its tab", .{});

    // Mouse path: the palette row, clicked.
    _ = try paletteChord(self, io, out);
    _ = try postPaletteText(self, io, out, "open config");
    const open_index = definitionIndex(self, config_open_action) orelse return 1;
    var open_id_storage: [palette_semantic_capacity]u8 = undefined;
    const open_id = try std.fmt.bufPrint(&open_id_storage, "palette.action.{d}", .{open_index});
    const open_row = self.ui_tree.byId(.{ .value = open_id });
    configCheck(out, &failures, open_row != null and std.mem.indexOf(u8, open_row.?.label, "Open config file") != null and
        std.mem.indexOf(u8, open_row.?.label, if (self.binding_profile == .macos) "Cmd+," else "Ctrl+,") != null, "the palette lists Open config file with its chord", .{});
    const tabs_before_mouse = self.activeWorkspace().tabCount();
    configCheck(out, &failures, try clickTabsElement(self, io, out, open_id) and
        self.activeWorkspace().tabCount() == tabs_before_mouse + 1 and editor_trace.calls == 2, "clicking the palette row opened a second editor tab", .{});
    const reread = Dir.cwd().readFile(io, path, &written_buffer) catch "";
    configCheck(out, &failures, std.mem.eql(u8, reread, config.defaults_document), "opening an existing file left it untouched", .{});

    out.print("config-test: {d} failure(s)\n", .{failures}) catch {};
    out.flush() catch {};
    return if (failures == 0) 0 else 1;
}

/// The deterministic peer behind `--theme-test`'s terminals.
const theme_test_script =
    "stty -echo; " ++
    "printf 'THEME-READY\\r\\n'; " ++
    "while IFS= read -r line; do printf 'THEME-ECHO:%s\\r\\n' \"$line\"; done";

/// The settings `--theme-test` starts with: no theme, so the default.
const theme_test_initial = "# --theme-test settings\n";

/// A partial user theme in Ghostty's format, light so every chrome fallback
/// is exercised. The ANSI colours it leaves out come from conduit-dark.
const theme_test_user_file =
    "# A user theme, dropped into the themes directory\n" ++
    "background = #f4ecd8\n" ++
    "foreground = #2b2b2b\n" ++
    "cursor-color = #a03030\n" ++
    "selection-background = #d8c8a0\n" ++
    "palette = 0=#2a2a2a\n" ++
    "palette = 4=#2050a0\n" ++
    "palette = 12=#3060c0\n";
const theme_test_user_name = "Test Paper";

/// A private absolute path for `--theme-test`'s settings file.
fn themeTestPath(io: Io, env: EnvSource, buffer: []u8) ![]const u8 {
    const base = firstEnv(env, temp_dir_vars[0..]) orelse "/tmp";
    const root = if (base.len != 0 and base[0] == '/') base else "/tmp";
    var id_buffer: [path_capacity]u8 = undefined;
    const id = try generateRunId(io, &id_buffer);
    return std.fmt.bufPrint(buffer, "{s}/conduit-theme-test-{s}/conduit/config", .{ root, id });
}

/// Remove `--theme-test`'s private directory: two levels above the file.
fn removeThemeTestDir(io: Io, path: []const u8) void {
    const conduit_dir = config.directoryOf(path) orelse return;
    const root = config.directoryOf(conduit_dir) orelse return;
    if (std.mem.indexOf(u8, root, "conduit-theme-test-") == null) return;
    Dir.cwd().deleteTree(io, root) catch |err| {
        log.warn("could not remove the theme-test directory: {s}", .{@errorName(err)});
    };
}

fn themeCheck(out: *Writer, failures: *usize, ok: bool, comptime format: []const u8, args: anytype) void {
    out.print("theme-test: {s} " ++ format ++ "\n", .{if (ok) "ok  " else "FAIL"} ++ args) catch {};
    if (!ok) failures.* += 1;
}

/// A fresh frame, copied out of the app's reused readback buffer.
fn themeFrame(self: *App) ![]u8 {
    try self.drawFrame();
    return self.allocator.dupe(u8, try self.capture());
}

/// A pixel no UI covers: the bottom-right corner of the terminal area, which
/// is the cleared surface or a blank cell, both the terminal background.
fn themeTerminalPixel(self: *const App, pixels: []const u8) render.Rgba {
    return pixelAt(pixels, self.size, self.size.width - 2, self.size.height - 2);
}

fn elementPixelRect(element: *const ui.Element) render.PixelRect {
    return .{
        .x = @floatFromInt(element.bounds.x),
        .y = @floatFromInt(element.bounds.y),
        .width = @floatFromInt(element.bounds.width),
        .height = @floatFromInt(element.bounds.height),
    };
}

/// The foreground the overlay paints the first cell of `id` with.
fn themeElementForeground(self: *App, id: []const u8) ?render.Rgba {
    const element = self.ui_tree.byId(.{ .value = id }) orelse return null;
    const cell = self.fonts.metrics().cell;
    // Skip leading blank cells: a centred label starts inside its bounds.
    const label_offset: u32 = @intCast(std.mem.indexOfNone(u8, element.label, " ") orelse 0);
    const position: render.OverlayPosition = .{
        .col = @intCast(@as(u32, @intCast(element.bounds.x)) / cell.width_px + label_offset),
        .row = @intCast(@as(u32, @intCast(element.bounds.y)) / cell.height_px),
    };
    for (self.overlayView().cells) |overlay_cell| {
        if (overlay_cell.position.col == position.col and overlay_cell.position.row == position.row and
            !std.mem.eql(u8, overlay_cell.text, " ")) return overlay_cell.foreground;
    }
    var col = position.col;
    while (col < position.col + 16) : (col += 1) {
        for (self.overlayView().cells) |overlay_cell| {
            if (overlay_cell.position.col == col and overlay_cell.position.row == position.row and
                overlay_cell.text.len != 0 and !std.mem.eql(u8, overlay_cell.text, " ")) return overlay_cell.foreground;
        }
    }
    return null;
}

fn themeChoiceIndex(self: *const App, label: []const u8) ?usize {
    for (self.theme_catalog.entriesSlice(), 0..) |entry, index| {
        if (std.mem.eql(u8, entry.label, label)) return index;
    }
    return null;
}

/// Exercise TASK-38 end to end: the default theme at startup, a bundled
/// scheme from the settings file recolouring the terminal and the chrome, a
/// Ghostty-format file dropped into the themes directory and used, the
/// palette theme picker's live preview by keyboard and by hover with Escape
/// reverting it, a mouse choice saved to the settings file, an unknown name
/// reported without losing the theme, and the `auto:` pair.
fn themeTest(self: *App, io: Io, out: *Writer) !u8 {
    var failures: usize = 0;
    const path_copy = self.config_path orelse {
        out.writeAll("theme-test: FAIL no settings path\n") catch {};
        return 1;
    };
    var path_buffer: [path_capacity]u8 = undefined;
    @memcpy(path_buffer[0..path_copy.len], path_copy);
    const path = path_buffer[0..path_copy.len];
    var themes_buffer: [path_capacity]u8 = undefined;
    const themes_dir = config.themesDirectory(&themes_buffer, path) orelse return 1;

    try self.drawFrame();
    themeCheck(out, &failures, try waitForPanes(self, io, out, .{ .focused_text = "THEME-READY" }), "the real theme-test child became ready", .{});
    themeCheck(out, &failures, self.palette.eql(default_palette) and std.mem.eql(u8, self.activeThemeName(), "conduit-dark") and
        self.theme_catalog.count == theme.bundled.len, "startup drew conduit-dark and listed all {d} bundled themes", .{self.theme_catalog.count});
    const startup = try themeFrame(self);
    defer self.allocator.free(startup);
    const default_background = surfaceColor(default_palette.get(.background));
    themeCheck(out, &failures, sameColor(themeTerminalPixel(self, startup), default_background), "the terminal background is conduit-dark's", .{});
    const hint = self.ui_tree.byId(.{ .value = "sidebar.palette" }) orelse {
        out.writeAll("theme-test: FAIL no sidebar.palette hint\n") catch {};
        return 1;
    };
    const hint_rect = elementPixelRect(hint);
    const startup_hint = themeElementForeground(self, "sidebar.palette");
    themeCheck(out, &failures, startup_hint != null and sameColor(startup_hint.?, surfaceColor(default_palette.get(.muted))), "the sidebar hint is drawn in conduit-dark's muted role", .{});

    // A bundled scheme from the settings file, applied by the watcher.
    const dracula = theme.derive(theme.findBundled("dracula").?.scheme);
    const reloads_before_dracula = self.config_reload_count;
    try writeConfigTestFile(io, path, theme_test_initial ++ "theme = dracula\n");
    themeCheck(out, &failures, try waitForConfig(self, io, out, .{ .reloads = reloads_before_dracula + 1 }) and
        try waitForConfig(self, io, out, .{ .theme = dracula }) and self.palette.eql(dracula), "theme = dracula applied without a restart", .{});
    const dracula_frame = try themeFrame(self);
    defer self.allocator.free(dracula_frame);
    const dracula_pixel = themeTerminalPixel(self, dracula_frame);
    themeCheck(out, &failures, sameColor(dracula_pixel, .{ .r = 0x28, .g = 0x2a, .b = 0x36 }), "the terminal background became Dracula's #282a36 (got {d},{d},{d})", .{ dracula_pixel.r, dracula_pixel.g, dracula_pixel.b });
    const dracula_hint = themeElementForeground(self, "sidebar.palette");
    themeCheck(out, &failures, dracula_hint != null and sameColor(dracula_hint.?, surfaceColor(dracula.get(.muted))) and
        !sameColor(dracula_hint.?, startup_hint orelse default_background) and
        countDifferingPixelsInRect(startup, dracula_frame, self.size, hint_rect) > 0, "the sidebar chrome was recoloured from the theme", .{});
    const dracula_grid = gridColors(dracula);
    var grids_follow = true;
    for (self.activePresentation().pane_renderers.items) |record| grids_follow = grids_follow and std.meta.eql(record.grid.colors, dracula_grid);
    grids_follow = grids_follow and std.meta.eql(self.activePresentation().scratchpad_grid.colors, dracula_grid);
    themeCheck(out, &failures, grids_follow, "every pane grid and the scratchpad draw with the theme's 16 ANSI colours, cursor and selection", .{});

    // A Ghostty-format file dropped into the themes directory and named, in
    // another spelling, by the setting.
    try Dir.cwd().createDirPath(io, themes_dir);
    var user_path_buffer: [path_capacity]u8 = undefined;
    const user_path = try std.fmt.bufPrint(&user_path_buffer, "{s}/{s}", .{ themes_dir, theme_test_user_name });
    try Dir.cwd().writeFile(io, .{ .sub_path = user_path, .data = theme_test_user_file });
    const paper = theme.derive(theme.parseGhostty(theme_test_user_file).scheme);
    const reloads_before_user = self.config_reload_count;
    try writeConfigTestFile(io, path, theme_test_initial ++ "theme = test-paper\n");
    themeCheck(out, &failures, try waitForConfig(self, io, out, .{ .reloads = reloads_before_user + 1 }) and
        try waitForConfig(self, io, out, .{ .theme = paper }), "the dropped Ghostty file applied as theme = test-paper", .{});
    const paper_frame = try themeFrame(self);
    defer self.allocator.free(paper_frame);
    const paper_pixel = themeTerminalPixel(self, paper_frame);
    themeCheck(out, &failures, sameColor(paper_pixel, .{ .r = 0xf4, .g = 0xec, .b = 0xd8 }) and
        paper.get(.green).eql(theme.conduit_dark.ansi[2]) and paper.get(.blue).eql(theme.Color.hex(0x2050a0)), "the user file's background drew and its missing colours came from conduit-dark", .{});
    themeCheck(out, &failures, self.theme_catalog.count == theme.bundled.len + 1 and self.theme_catalog.entries[0].user and
        std.mem.eql(u8, self.theme_catalog.choices[0].label, theme_test_user_name) and self.configErrorText() == null, "the picker lists the user theme first, as the active one, with no error", .{});
    const paper_hint = themeElementForeground(self, "sidebar.palette");
    themeCheck(out, &failures, paper_hint != null and sameColor(paper_hint.?, surfaceColor(paper.get(.muted))) and
        theme.contrast(paper.get(.strong), paper.get(.background)) >= theme.text_contrast, "the light user theme derived readable chrome", .{});

    // The picker by keyboard: the highlighted theme previews live.
    _ = try paletteChord(self, io, out);
    _ = try postPaletteText(self, io, out, "theme");
    _ = try postNamedKey(self, io, out, .enter, .{});
    const pick_index = self.theme_pick_index;
    var first_id_storage: [palette_semantic_capacity]u8 = undefined;
    const first_id = try std.fmt.bufPrint(&first_id_storage, "palette.choice.{d}.0", .{pick_index});
    const first_row = self.ui_tree.byId(.{ .value = first_id });
    themeCheck(out, &failures, self.themePickerSelection() != null and first_row != null and
        std.mem.eql(u8, first_row.?.label, theme_test_user_name) and self.palette.eql(paper), "Theme: choose opened by keyboard with the active theme highlighted", .{});
    _ = try postNamedKey(self, io, out, .down, .{});
    const second = self.theme_catalog.entries[1];
    const preview_frame = try themeFrame(self);
    defer self.allocator.free(preview_frame);
    themeCheck(out, &failures, self.themePickerSelection() == 1 and self.palette.eql(second.palette) and
        self.theme_palette.eql(paper) and sameColor(themeTerminalPixel(self, preview_frame), surfaceColor(second.palette.get(.background))) and
        countDifferingPixelsInRect(paper_frame, preview_frame, self.size, hint_rect) > 0, "Down previewed '{s}' across the terminal and the chrome", .{second.label});
    _ = try postNamedKey(self, io, out, .escape, .{});
    const reverted_frame = try themeFrame(self);
    defer self.allocator.free(reverted_frame);
    themeCheck(out, &failures, !self.paletteVisible() and self.palette.eql(paper) and
        sameColor(themeTerminalPixel(self, reverted_frame), surfaceColor(paper.get(.background))), "Escape closed the picker and reverted to the committed theme", .{});

    // The picker by mouse: hover previews, a click commits and saves.
    themeCheck(out, &failures, try clickPaletteCommand(self, io, out, theme_pick_action, null) and
        self.themePickerSelection() != null, "the palette hint and the Theme: choose row opened the picker by mouse", .{});
    const target_index = themeChoiceIndex(self, "Gruvbox Light") orelse {
        out.writeAll("theme-test: FAIL Gruvbox Light is not listed\n") catch {};
        return 1;
    };
    const gruvbox_light = self.theme_catalog.entries[target_index].palette;
    var target_id_storage: [palette_semantic_capacity]u8 = undefined;
    const target_id = try std.fmt.bufPrint(&target_id_storage, "palette.choice.{d}.{d}", .{ pick_index, target_index });
    const target_row = self.ui_tree.byId(.{ .value = target_id });
    if (target_row) |row| {
        const point = elementCenter(row, self.window.state.scale);
        _ = try postMotion(self, io, out, .{ .x = point.x, .y = point.y });
    }
    const hover_frame = try themeFrame(self);
    defer self.allocator.free(hover_frame);
    themeCheck(out, &failures, target_row != null and self.palette.eql(gruvbox_light) and self.theme_palette.eql(paper) and
        sameColor(themeTerminalPixel(self, hover_frame), surfaceColor(gruvbox_light.get(.background))), "hovering Gruvbox Light previewed it live", .{});
    const reloads_before_pick = self.config_reload_count;
    themeCheck(out, &failures, try clickTabsElement(self, io, out, target_id) and !self.paletteVisible() and
        self.palette.eql(gruvbox_light) and self.theme_palette.eql(gruvbox_light) and
        std.mem.eql(u8, self.activeThemeName(), "gruvbox-light"), "clicking Gruvbox Light committed it", .{});
    themeCheck(out, &failures, try waitForConfig(self, io, out, .{ .reloads = reloads_before_pick + 1 }) and
        self.palette.eql(gruvbox_light) and self.configErrorText() == null, "the saved file reloaded to the same theme", .{});
    var file_buffer: [4096]u8 = undefined;
    const saved = Dir.cwd().readFile(io, path, &file_buffer) catch "";
    themeCheck(out, &failures, std.mem.eql(u8, saved, theme_test_initial ++ "theme = gruvbox-light\n"), "the settings file now reads theme = gruvbox-light with its comment kept", .{});
    const picked_frame = try themeFrame(self);
    defer self.allocator.free(picked_frame);
    themeCheck(out, &failures, sameColor(themeTerminalPixel(self, picked_frame), surfaceColor(gruvbox_light.get(.background))) and
        countDifferingPixelsInRect(reverted_frame, picked_frame, self.size, hint_rect) > 0, "the frame changed to Gruvbox Light", .{});

    // An unknown name is a visible error and the theme stays.
    const reloads_before_unknown = self.config_reload_count;
    try writeConfigTestFile(io, path, theme_test_initial ++ "theme = no-such-theme\n");
    themeCheck(out, &failures, try waitForConfig(self, io, out, .{ .reloads = reloads_before_unknown + 1 }) and
        try waitForConfig(self, io, out, .{ .element = "config.error" }), "an unknown theme showed config.error", .{});
    const error_element = self.ui_tree.byId(.{ .value = "config.error" });
    themeCheck(out, &failures, error_element != null and std.mem.startsWith(u8, error_element.?.label, "config:2: theme: no bundled or user theme named") and
        self.palette.eql(gruvbox_light), "config.error names the line and the theme stayed: '{s}'", .{if (error_element) |element| element.label else ""});

    // `auto:` follows the desktop preference, dark when it is unknown.
    const reloads_before_auto = self.config_reload_count;
    try writeConfigTestFile(io, path, theme_test_initial ++ "theme = auto:dracula,solarized-light\n");
    const prefers_light = platform.systemTheme() == .light;
    const auto_expected = if (prefers_light) theme.derive(theme.findBundled("solarized-light").?.scheme) else dracula;
    themeCheck(out, &failures, try waitForConfig(self, io, out, .{ .reloads = reloads_before_auto + 1 }) and
        try waitForConfig(self, io, out, .{ .theme = auto_expected }) and self.configErrorText() == null, "auto:dracula,solarized-light resolved to the {s} theme", .{if (prefers_light) "light" else "dark"});

    out.print("theme-test: {d} failure(s)\n", .{failures}) catch {};
    out.flush() catch {};
    return if (failures == 0) 0 else 1;
}

/// The deterministic peer behind `--font-test`'s terminals. Its second row is
/// a ligature run the bundled JetBrains Mono joins.
const font_test_script =
    "stty -echo; " ++
    "printf 'FONT-READY\\r\\n'; " ++
    "printf 'LIGA a => b != c -> d\\r\\n'; " ++
    "while IFS= read -r line; do printf 'FONT-ECHO:%s\\r\\n' \"$line\"; done";

/// The settings `--font-test` starts with: every font key at its default.
const font_test_initial = "# --font-test settings\n";

/// The installed family `--font-test` previews and commits. The Linux gate
/// installs `fonts-dejavu-core`, and it is monospaced with its own metrics.
const font_test_family = "DejaVu Sans Mono";

/// A private absolute path for `--font-test`'s settings file.
fn fontTestPath(io: Io, env: EnvSource, buffer: []u8) ![]const u8 {
    const base = firstEnv(env, temp_dir_vars[0..]) orelse "/tmp";
    const root = if (base.len != 0 and base[0] == '/') base else "/tmp";
    var id_buffer: [path_capacity]u8 = undefined;
    const id = try generateRunId(io, &id_buffer);
    return std.fmt.bufPrint(buffer, "{s}/conduit-font-test-{s}/conduit/config", .{ root, id });
}

/// Remove `--font-test`'s private directory: two levels above the file.
fn removeFontTestDir(io: Io, path: []const u8) void {
    const conduit_dir = config.directoryOf(path) orelse return;
    const root = config.directoryOf(conduit_dir) orelse return;
    if (std.mem.indexOf(u8, root, "conduit-font-test-") == null) return;
    Dir.cwd().deleteTree(io, root) catch |err| {
        log.warn("could not remove the font-test directory: {s}", .{@errorName(err)});
    };
}

fn fontCheck(out: *Writer, failures: *usize, ok: bool, comptime format: []const u8, args: anytype) void {
    out.print("font-test: {s} " ++ format ++ "\n", .{if (ok) "ok  " else "FAIL"} ++ args) catch {};
    if (!ok) failures.* += 1;
}

/// Whether the settings file reads exactly `expected`.
fn fontFileIs(io: Io, path: []const u8, expected: []const u8) bool {
    var buffer: [4096]u8 = undefined;
    const text = Dir.cwd().readFile(io, path, &buffer) catch return false;
    return std.mem.eql(u8, text, expected);
}

/// Open the palette by its chord, type `label` and press Enter, after checking
/// that the typed label ranked its own command first.
fn runPaletteCommandByKeyboard(self: *App, io: Io, out: *Writer, label: [:0]const u8) !bool {
    if (!try paletteChord(self, io, out)) return false;
    if (!try postPaletteText(self, io, out, label)) return false;
    const selected = self.palette_model.selectedDefinitionIndex() orelse return false;
    if (!std.mem.eql(u8, self.actions.definitions()[selected].label, label)) return false;
    return postNamedKey(self, io, out, .enter, .{});
}

/// The pixels of terminal row `row` across the pane, in the frame.
fn terminalRowRect(self: *const App, row: u16) render.PixelRect {
    const cell = self.fonts.metrics().cell;
    const x = self.sidebarOriginColumns() * cell.width_px;
    return .{
        .x = @floatFromInt(x),
        .y = @floatFromInt(@as(u32, row) * cell.height_px),
        .width = @floatFromInt(self.size.width - @min(self.size.width, x)),
        .height = @floatFromInt(cell.height_px),
    };
}

/// One font command whose own config write must not build the face twice:
/// after the watcher reloads the file it wrote, no further worker started.
fn fontReloadIsNoop(self: *App, io: Io, out: *Writer, reloads_before: usize, loads_after_command: usize) !bool {
    if (!try waitForConfig(self, io, out, .{ .reloads = reloads_before + 1 })) return false;
    if (!try waitForConfig(self, io, out, .font_settled)) return false;
    return self.font_load_count == loads_after_command and self.configErrorText() == null;
}

/// One size command's effect: the committed points, the cell height moving
/// the expected way, the file's `font.size` line and a no-op reload of it.
const FontSizeExpectation = struct {
    how: []const u8,
    points: f32,
    file: []const u8,
    height_before: u32,
    height: std.math.Order,
    reloads_before: usize,
    loads_after: usize,
};

fn checkFontSizeStep(self: *App, io: Io, out: *Writer, failures: *usize, path: []const u8, step: FontSizeExpectation) !void {
    const settled = try waitForConfig(self, io, out, .font_settled);
    const height = self.fonts.metrics().cell.height_px;
    fontCheck(out, failures, settled and self.font_settings.values.points == step.points and
        std.math.order(height, step.height_before) == step.height, "{s} set {d} points: cell height {d}px -> {d}px", .{ step.how, step.points, step.height_before, height });
    fontCheck(out, failures, fontFileIs(io, path, step.file), "the settings file reads font.size = {d} with its comment kept", .{step.points});
    fontCheck(out, failures, try fontReloadIsNoop(self, io, out, step.reloads_before, step.loads_after), "the reload of that write rebuilt nothing", .{});
}

/// Exercise TASK-40 end to end through real SDL keys and pointer events:
/// size increase, decrease and reset by chord, by the palette by keyboard and
/// by a clicked palette row, with cell-metric readback and the file after
/// each; ligatures toggled in place with frame readback; built-in symbols
/// rebuilt; fallbacks through the free-text step; and the family picker's
/// keyboard preview, Escape revert, hover preview and mouse commit.
fn fontTest(self: *App, io: Io, out: *Writer) !u8 {
    var failures: usize = 0;
    const path_copy = self.config_path orelse {
        out.writeAll("font-test: FAIL no settings path\n") catch {};
        return 1;
    };
    var path_buffer: [path_capacity]u8 = undefined;
    @memcpy(path_buffer[0..path_copy.len], path_copy);
    const path = path_buffer[0..path_copy.len];

    try self.drawFrame();
    fontCheck(out, &failures, try waitForPanes(self, io, out, .{ .focused_text = "LIGA a" }), "the real font-test child became ready", .{});
    fontCheck(out, &failures, try waitForConfig(self, io, out, .font_settled) and self.font_settings.values.points == config.default_font_points and
        self.font_settings.values.family.len == 0 and self.fonts.isFallback(), "startup drew the bundled face at the built-in 14 points", .{});

    // Size: increase, decrease and reset by chord, by palette and by mouse.
    const zoom: platform.Mods = switch (self.binding_profile) {
        .macos => .{ .super = true },
        .linux_windows => .{ .ctrl = true },
    };
    var zoom_shift = zoom;
    zoom_shift.shift = true;
    const base_height = self.fonts.metrics().cell.height_px;
    var reloads = self.config_reload_count;
    var height = self.fonts.metrics().cell.height_px;
    _ = try postKey(self, io, out, '=', zoom);
    try checkFontSizeStep(self, io, out, &failures, path, .{ .how = "the increase chord", .points = 15, .file = font_test_initial ++ "font.size = 15\n", .height_before = height, .height = .gt, .reloads_before = reloads, .loads_after = self.font_load_count });

    reloads = self.config_reload_count;
    height = self.fonts.metrics().cell.height_px;
    _ = try postKey(self, io, out, '=', zoom_shift);
    try checkFontSizeStep(self, io, out, &failures, path, .{ .how = "the increase chord with Shift (Ctrl+Plus)", .points = 16, .file = font_test_initial ++ "font.size = 16\n", .height_before = height, .height = .gt, .reloads_before = reloads, .loads_after = self.font_load_count });

    reloads = self.config_reload_count;
    height = self.fonts.metrics().cell.height_px;
    fontCheck(out, &failures, try runPaletteCommandByKeyboard(self, io, out, "Font: Decrease Size"), "Font: Decrease Size ran from the palette by keyboard", .{});
    try checkFontSizeStep(self, io, out, &failures, path, .{ .how = "the palette's Decrease Size", .points = 15, .file = font_test_initial ++ "font.size = 15\n", .height_before = height, .height = .lt, .reloads_before = reloads, .loads_after = self.font_load_count });

    reloads = self.config_reload_count;
    height = self.fonts.metrics().cell.height_px;
    _ = try postKey(self, io, out, '-', zoom);
    try checkFontSizeStep(self, io, out, &failures, path, .{ .how = "the decrease chord", .points = 14, .file = font_test_initial ++ "font.size = 14\n", .height_before = height, .height = .lt, .reloads_before = reloads, .loads_after = self.font_load_count });
    fontCheck(out, &failures, self.fonts.metrics().cell.height_px == base_height, "14 points is the startup cell height again ({d}px)", .{base_height});

    reloads = self.config_reload_count;
    height = self.fonts.metrics().cell.height_px;
    fontCheck(out, &failures, try runPaletteCommandByKeyboard(self, io, out, "Font: Increase Size"), "Font: Increase Size ran from the palette by keyboard", .{});
    try checkFontSizeStep(self, io, out, &failures, path, .{ .how = "the palette's Increase Size", .points = 15, .file = font_test_initial ++ "font.size = 15\n", .height_before = height, .height = .gt, .reloads_before = reloads, .loads_after = self.font_load_count });

    reloads = self.config_reload_count;
    height = self.fonts.metrics().cell.height_px;
    _ = try postKey(self, io, out, '0', zoom);
    try checkFontSizeStep(self, io, out, &failures, path, .{ .how = "the reset chord", .points = 14, .file = font_test_initial ++ "font.size = 14\n", .height_before = height, .height = .lt, .reloads_before = reloads, .loads_after = self.font_load_count });

    reloads = self.config_reload_count;
    height = self.fonts.metrics().cell.height_px;
    _ = try postKey(self, io, out, '=', zoom);
    try checkFontSizeStep(self, io, out, &failures, path, .{ .how = "the increase chord again", .points = 15, .file = font_test_initial ++ "font.size = 15\n", .height_before = height, .height = .gt, .reloads_before = reloads, .loads_after = self.font_load_count });
    reloads = self.config_reload_count;
    height = self.fonts.metrics().cell.height_px;
    fontCheck(out, &failures, try clickPaletteCommand(self, io, out, font_size_reset_action, null), "Font: Reset Size ran from a clicked palette row", .{});
    try checkFontSizeStep(self, io, out, &failures, path, .{ .how = "the clicked Reset Size", .points = 14, .file = font_test_initial ++ "font.size = 14\n", .height_before = height, .height = .lt, .reloads_before = reloads, .loads_after = self.font_load_count });
    fontCheck(out, &failures, self.fonts.metrics().cell.height_px == base_height, "reset restored the built-in cell height ({d}px)", .{base_height});

    // Ligatures toggle in place: no rebuild, and the `=>` row redraws.
    const ligature_row = terminalRowRect(self, 1);
    const joined = try themeFrame(self);
    defer self.allocator.free(joined);
    reloads = self.config_reload_count;
    var loads = self.font_load_count;
    fontCheck(out, &failures, try runPaletteCommandByKeyboard(self, io, out, "Font: Toggle Ligatures"), "Font: Toggle Ligatures ran from the palette by keyboard", .{});
    const plain = try themeFrame(self);
    defer self.allocator.free(plain);
    const ligature_pixels = countDifferingPixelsInRect(joined, plain, self.size, ligature_row);
    fontCheck(out, &failures, !self.font_settings.values.ligatures and !self.fonts.ligatures() and self.font_load_count == loads and
        ligature_pixels > 0, "ligatures went off without a rebuild and the `=>` row redrew ({d} pixels changed)", .{ligature_pixels});
    fontCheck(out, &failures, fontFileIs(io, path, font_test_initial ++ "font.size = 14\nfont.ligatures = false\n"), "the settings file reads font.ligatures = false", .{});
    fontCheck(out, &failures, try fontReloadIsNoop(self, io, out, reloads, loads), "the reload of that write rebuilt nothing", .{});
    reloads = self.config_reload_count;
    fontCheck(out, &failures, try runPaletteCommandByKeyboard(self, io, out, "Font: Toggle Ligatures"), "Font: Toggle Ligatures ran again", .{});
    const rejoined = try themeFrame(self);
    defer self.allocator.free(rejoined);
    fontCheck(out, &failures, self.fonts.ligatures() and countDifferingPixelsInRect(plain, rejoined, self.size, ligature_row) > 0 and
        countDifferingPixelsInRect(joined, rejoined, self.size, ligature_row) == 0 and
        fontFileIs(io, path, font_test_initial ++ "font.size = 14\nfont.ligatures = true\n"), "ligatures came back on, drew the joined row again and were saved", .{});
    fontCheck(out, &failures, try fontReloadIsNoop(self, io, out, reloads, loads), "the reload of that write rebuilt nothing", .{});

    // Built-in symbols rebuild the face without the sprites.
    reloads = self.config_reload_count;
    fontCheck(out, &failures, try runPaletteCommandByKeyboard(self, io, out, "Font: Toggle Built-in Symbols"), "Font: Toggle Built-in Symbols ran from the palette", .{});
    loads = self.font_load_count;
    fontCheck(out, &failures, try waitForConfig(self, io, out, .font_settled) and !self.fonts.builtinSymbols() and
        fontFileIs(io, path, font_test_initial ++ "font.size = 14\nfont.ligatures = true\nfont.nerd_symbols = false\n"), "the face was rebuilt without built-in symbols and font.nerd_symbols = false saved", .{});
    fontCheck(out, &failures, try fontReloadIsNoop(self, io, out, reloads, loads), "the reload of that write rebuilt nothing", .{});
    reloads = self.config_reload_count;
    fontCheck(out, &failures, try runPaletteCommandByKeyboard(self, io, out, "Font: Toggle Built-in Symbols"), "Font: Toggle Built-in Symbols ran again", .{});
    loads = self.font_load_count;
    fontCheck(out, &failures, try waitForConfig(self, io, out, .font_settled) and self.fonts.builtinSymbols() and
        try fontReloadIsNoop(self, io, out, reloads, loads), "built-in symbols came back on", .{});

    // Fallbacks through the free-text step.
    const symbols_on = font_test_initial ++ "font.size = 14\nfont.ligatures = true\nfont.nerd_symbols = true\n";
    reloads = self.config_reload_count;
    fontCheck(out, &failures, try runPaletteCommandByKeyboard(self, io, out, "Font: Configure Fallbacks") and
        self.palette_step == .input and self.ui_tree.byId(.{ .value = "palette.argument" }) != null, "Font: Configure Fallbacks asked for the families", .{});
    _ = try postPaletteText(self, io, out, font_test_family ++ " ,, Conduit Missing Family");
    _ = try postNamedKey(self, io, out, .enter, .{});
    loads = self.font_load_count;
    const fallbacks = self.font_settings.values.fallbacks;
    fontCheck(out, &failures, !self.paletteVisible() and fallbacks.len == 2 and std.mem.eql(u8, fallbacks[0], font_test_family) and
        std.mem.eql(u8, fallbacks[1], "Conduit Missing Family"), "the typed list was trimmed into two fallback families", .{});
    fontCheck(out, &failures, try waitForConfig(self, io, out, .font_settled) and self.fonts.configuredFallbackCount() == 1, "the rebuilt face opened the installed fallback and skipped the missing one", .{});
    fontCheck(out, &failures, fontFileIs(io, path, symbols_on ++ "font.fallbacks = " ++ font_test_family ++ ", Conduit Missing Family\n"), "the settings file reads the normalised font.fallbacks list", .{});
    fontCheck(out, &failures, try waitForConfig(self, io, out, .{ .reloads = reloads + 1 }) and self.font_load_count == loads and
        try waitForConfig(self, io, out, .{ .element = "config.error" }), "the reload rebuilt nothing and reported the missing family", .{});
    const fallback_error = self.ui_tree.byId(.{ .value = "config.error" });
    fontCheck(out, &failures, fallback_error != null and std.mem.eql(u8, fallback_error.?.label, "config:5: " ++ missing_fallback_message), "config.error names the fallbacks line: '{s}'", .{if (fallback_error) |element| element.label else ""});
    reloads = self.config_reload_count;
    fontCheck(out, &failures, try runPaletteCommandByKeyboard(self, io, out, "Font: Configure Fallbacks"), "Font: Configure Fallbacks opened again", .{});
    _ = try postPaletteText(self, io, out, font_test_family);
    _ = try postNamedKey(self, io, out, .enter, .{});
    fontCheck(out, &failures, try waitForConfig(self, io, out, .font_settled) and self.fonts.configuredFallbackCount() == 1 and
        try waitForConfig(self, io, out, .{ .reloads = reloads + 1 }) and try waitForConfig(self, io, out, .{ .no_element = "config.error" }) and
        fontFileIs(io, path, symbols_on ++ "font.fallbacks = " ++ font_test_family ++ "\n"), "an installed-only list cleared the error and was saved", .{});

    // The family picker by keyboard: the highlight previews, Escape reverts.
    const committed_file = symbols_on ++ "font.fallbacks = " ++ font_test_family ++ "\n";
    fontCheck(out, &failures, try runPaletteCommandByKeyboard(self, io, out, "Font: Change Family") and
        self.fontPickerSelection() == 0, "Font: Change Family opened by keyboard on the drawn family", .{});
    const pick_index = self.font_pick_index;
    var first_id_storage: [palette_semantic_capacity]u8 = undefined;
    const first_id = try std.fmt.bufPrint(&first_id_storage, "palette.choice.{d}.0", .{pick_index});
    const first_row = self.ui_tree.byId(.{ .value = first_id });
    const listed = self.font_choices.slice();
    var all_monospace = listed.len >= 2;
    for (listed[1..]) |choice| {
        const file = self.fonts.catalog.findFamily(choice.value) orelse {
            all_monospace = false;
            continue;
        };
        all_monospace = all_monospace and file.fixed_width;
    }
    fontCheck(out, &failures, first_row != null and std.mem.eql(u8, first_row.?.label, bundled_font_label) and all_monospace and
        self.font_choices.find(font_test_family) != null, "the picker lists the bundled face first and {d} installed monospace families, {s} among them", .{ listed.len - 1, font_test_family });
    fontCheck(out, &failures, try waitForConfig(self, io, out, .{ .element = "palette.preview" }), "the preview line shows the drawn family", .{});
    const target = self.font_choices.find(font_test_family) orelse {
        out.writeAll("font-test: FAIL " ++ font_test_family ++ " is not listed\n") catch {};
        return 1;
    };
    while (self.fontPickerSelection()) |selected| {
        if (selected == target) break;
        if (!try postNamedKey(self, io, out, .down, .{})) break;
    }
    const preview_settled = try waitForConfig(self, io, out, .{ .drawn_family = font_test_family });
    const preview_line = self.ui_tree.byId(.{ .value = "palette.preview" });
    fontCheck(out, &failures, preview_settled and self.fontPickerSelection() == target and
        std.mem.eql(u8, self.font_settings.values.family, "") and preview_line != null and
        std.mem.eql(u8, preview_line.?.label, "Showing " ++ font_test_family) and fontFileIs(io, path, committed_file), "Down previewed {s} live ({d}x{d}px cells) while the file stayed unchanged", .{ font_test_family, self.fonts.metrics().cell.width_px, self.fonts.metrics().cell.height_px });
    _ = try postNamedKey(self, io, out, .escape, .{});
    fontCheck(out, &failures, !self.paletteVisible() and try waitForConfig(self, io, out, .font_settled) and self.fonts.isFallback() and
        self.fonts.metrics().cell.height_px == base_height and fontFileIs(io, path, committed_file), "Escape closed the picker and reverted to the bundled face", .{});

    // The picker by mouse: hover previews, a click commits and saves.
    fontCheck(out, &failures, try clickPaletteCommand(self, io, out, font_pick_action, null) and self.fontPickerSelection() == 0, "the palette hint and the Font: Change Family row opened the picker by mouse", .{});
    var target_id_storage: [palette_semantic_capacity]u8 = undefined;
    const target_id = try std.fmt.bufPrint(&target_id_storage, "palette.choice.{d}.{d}", .{ pick_index, self.font_choices.find(font_test_family) orelse 0 });
    const target_row = self.ui_tree.byId(.{ .value = target_id });
    if (target_row) |row| {
        const point = elementCenter(row, self.window.state.scale);
        _ = try postMotion(self, io, out, .{ .x = point.x, .y = point.y });
    }
    fontCheck(out, &failures, target_row != null and try waitForConfig(self, io, out, .{ .drawn_family = font_test_family }) and
        self.paletteVisible() and fontFileIs(io, path, committed_file), "hovering {s} previewed it live", .{font_test_family});
    reloads = self.config_reload_count;
    loads = self.font_load_count;
    fontCheck(out, &failures, try clickTabsElement(self, io, out, target_id) and !self.paletteVisible() and
        std.mem.eql(u8, self.font_settings.values.family, font_test_family) and std.mem.eql(u8, self.fonts.familyName(), font_test_family) and
        self.font_load_count == loads, "clicking {s} committed the previewed face without building it again", .{font_test_family});
    fontCheck(out, &failures, fontFileIs(io, path, committed_file ++ "font.family = " ++ font_test_family ++ "\n"), "the settings file reads font.family = {s}", .{font_test_family});
    fontCheck(out, &failures, try fontReloadIsNoop(self, io, out, reloads, loads) and std.mem.eql(u8, self.fonts.familyName(), font_test_family), "the reload of that write rebuilt nothing", .{});

    out.print("font-test: {d} failure(s)\n", .{failures}) catch {};
    out.flush() catch {};
    return if (failures == 0) 0 else 1;
}

/// The deterministic peer behind `--profiles-test`'s first tab, and behind
/// a plain new tab until `shell` names a profile.
const profiles_test_script =
    "stty -echo; " ++
    "printf 'PROFILES-READY\\r\\n'; " ++
    "while IFS= read -r line; do printf 'PROFILES-ECHO:%s\\r\\n' \"$line\"; done";

/// A private absolute path for `--profiles-test`'s settings file.
fn profilesTestPath(io: Io, env: EnvSource, buffer: []u8) ![]const u8 {
    const base = firstEnv(env, temp_dir_vars[0..]) orelse "/tmp";
    const root = if (base.len != 0 and base[0] == '/') base else "/tmp";
    var id_buffer: [path_capacity]u8 = undefined;
    const id = try generateRunId(io, &id_buffer);
    return std.fmt.bufPrint(buffer, "{s}/conduit-profiles-test-{s}/conduit/config", .{ root, id });
}

/// The check's private directory, two levels above its settings file: the
/// directory profile `alpha` starts in.
fn profilesTestRoot(path: []const u8) ?[]const u8 {
    const conduit_dir = config.directoryOf(path) orelse return null;
    return config.directoryOf(conduit_dir);
}

/// Remove `--profiles-test`'s private directory.
fn removeProfilesTestDir(io: Io, path: []const u8) void {
    const root = profilesTestRoot(path) orelse return;
    if (std.mem.indexOf(u8, root, "conduit-profiles-test-") == null) return;
    Dir.cwd().deleteTree(io, root) catch |err| {
        log.warn("could not remove the profiles-test directory: {s}", .{@errorName(err)});
    };
}

/// The check's settings: `alpha` reports its variable and directory, `beta`
/// is a login shell reporting its `$0`, both then hand over to an
/// interactive `/bin/sh` that reads what the check types. `beta`'s HOME is
/// the private directory, so a login `sh` reads no `~/.profile` of the
/// person running the check. `extra` is appended.
fn profilesTestConfig(buffer: []u8, root: []const u8, extra: []const u8) ![]const u8 {
    return std.fmt.bufPrint(buffer,
        \\# --profiles-test settings
        \\profile = alpha = /bin/sh -c 'printf "PROFILE-A:%s\r\n" "$PROFILE_VAR"; exec /bin/sh'
        \\profile.alpha.env = PROFILE_VAR=alpha-env
        \\profile.alpha.cwd = {s}
        \\profile = beta = /bin/sh -c 'printf "PROFILE-B:%s\r\n" "$0"; exec /bin/sh'
        \\profile.beta.login = true
        \\profile.beta.env = HOME={s}
        \\{s}
    , .{ root, root, extra });
}

fn profilesCheck(out: *Writer, failures: *usize, ok: bool, comptime format: []const u8, args: anytype) void {
    out.print("profiles-test: {s} " ++ format ++ "\n", .{if (ok) "ok  " else "FAIL"} ++ args) catch {};
    if (!ok) failures.* += 1;
}

/// Type `line` into whatever has keyboard focus and press Enter, through
/// SDL's text and key events.
fn typeLine(self: *App, io: Io, out: *Writer, line: [:0]const u8) !bool {
    return try postPaletteText(self, io, out, line) and try postNamedKey(self, io, out, .enter, .{});
}

/// The label of choice `choice` of the open chooser for `definition`.
fn profileChoiceRowLabel(self: *const App, definition: usize, choice: usize) []const u8 {
    var buffer: [palette_semantic_capacity]u8 = undefined;
    const id = choiceRowId(&buffer, definition, choice) catch return "";
    const element = self.ui_tree.byId(.{ .value = id }) orelse return "";
    return element.label;
}

/// Exercise TASK-46 end to end through real SDL keys and pointer events,
/// real PTYs and real child processes: the profile chooser lists the
/// built-in and configured profiles; a tab opened from it by keyboard runs
/// the profile's argv with its environment in its directory (read back by
/// typing into the child); a login profile clicked with the mouse gets `-l`;
/// a split runs a profile in a new pane; `shell` makes a profile the
/// default for New tab; the Shells settings group shows the profiles; and a
/// malformed profile line is reported in `config.error`.
fn profilesTest(self: *App, io: Io, out: *Writer) !u8 {
    var failures: usize = 0;
    const path_copy = self.config_path orelse {
        out.writeAll("profiles-test: FAIL no settings path\n") catch {};
        return 1;
    };
    var path_buffer: [path_capacity]u8 = undefined;
    @memcpy(path_buffer[0..path_copy.len], path_copy);
    const path = path_buffer[0..path_copy.len];
    const root = profilesTestRoot(path) orelse return 1;
    var trace: EditorSpawnTrace = .{};
    self.profile_spawn_observer = .{ .context = &trace, .observe_fn = recordEditorSpawn };
    defer self.profile_spawn_observer = .{};

    try self.drawFrame();
    profilesCheck(out, &failures, try waitForPanes(self, io, out, .{ .focused_text = "PROFILES-READY" }), "the real profiles-test child became ready", .{});
    profilesCheck(out, &failures, self.configErrorText() == null and self.config_current.settings.shell_profiles.len == 2, "the two configured profiles loaded cleanly", .{});

    // The chooser by keyboard: the palette, the command, then the list.
    profilesCheck(out, &failures, try runPaletteCommandByKeyboard(self, io, out, "New tab with profile") and self.paletteVisible(), "New tab with profile opened its chooser from the palette by keyboard", .{});
    const tab_index = self.tab_profile_index;
    const login_row = profileChoiceRowLabel(self, tab_index, 0);
    const alpha_row = profileChoiceRowLabel(self, tab_index, 1);
    const beta_row = profileChoiceRowLabel(self, tab_index, 2);
    profilesCheck(out, &failures, std.mem.startsWith(u8, login_row, "login  /") and std.mem.endsWith(u8, login_row, "  built-in") and
        (std.mem.indexOf(u8, login_row, " -l  ") != null or std.mem.indexOf(u8, login_row, " --login  ") != null), "the built-in login profile is listed first: '{s}'", .{login_row});
    profilesCheck(out, &failures, std.mem.startsWith(u8, alpha_row, "alpha  /bin/sh -c ") and std.mem.endsWith(u8, alpha_row, "  profile"), "the configured alpha profile is listed: '{s}'", .{alpha_row});
    profilesCheck(out, &failures, std.mem.startsWith(u8, beta_row, "beta  /bin/sh -l -c ") and std.mem.endsWith(u8, beta_row, "  profile"), "the login beta profile is listed with -l: '{s}'", .{beta_row});
    try self.drawFrame();
    const chooser_pixels = try self.allocator.dupe(u8, try self.capture());
    defer self.allocator.free(chooser_pixels);

    const tabs_before_keyboard = self.activeWorkspace().tabCount();
    _ = try postNamedKey(self, io, out, .down, .{});
    _ = try postNamedKey(self, io, out, .enter, .{});
    // The directory is checked by the shell, not printed: a long path wraps
    // across rows. The answer is computed, so the echoed line never matches.
    const expected_a = "PROFILE-A:alpha-env";
    var cwd_probe_buffer: [path_capacity + 64]u8 = undefined;
    const cwd_probe = try std.fmt.bufPrintZ(&cwd_probe_buffer, "test \"$(pwd)\" = '{s}' && echo \"CWD-$((40+2))\"", .{root});
    var home_probe_buffer: [path_capacity + 64]u8 = undefined;
    const home_probe = try std.fmt.bufPrintZ(&home_probe_buffer, "test \"$HOME\" = '{s}' && echo \"HOME-$((40+2))\"", .{root});
    const keyboard_tab = self.activeWorkspace().activeTabId();
    profilesCheck(out, &failures, !self.paletteVisible() and self.activeWorkspace().tabCount() == tabs_before_keyboard + 1 and
        keyboard_tab != null and std.mem.eql(u8, self.activeWorkspace().tab(keyboard_tab.?).?.name(), "alpha"), "Down and Enter opened a tab named alpha", .{});
    profilesCheck(out, &failures, trace.calls == 1 and std.mem.startsWith(u8, trace.argv(), "/bin/sh -c printf ") and
        std.mem.eql(u8, trace.cwd(), root), "alpha spawned its argv in its directory: '{s}' in '{s}'", .{ trace.argv(), trace.cwd() });
    profilesCheck(out, &failures, try waitForPanes(self, io, out, .{ .focused_text = expected_a }), "the alpha child printed its variable", .{});
    profilesCheck(out, &failures, try typeLine(self, io, out, "echo \"E-$PROFILE_VAR\"") and
        try waitForPanes(self, io, out, .{ .focused_text = "E-alpha-env" }) and try typeLine(self, io, out, cwd_probe) and
        try waitForPanes(self, io, out, .{ .focused_text = "CWD-42" }), "typed input read the profile's variable and directory back from the shell", .{});

    // The chooser by mouse: the Palette hint, the command row, the beta row.
    const tabs_before_mouse = self.activeWorkspace().tabCount();
    profilesCheck(out, &failures, try clickPaletteCommand(self, io, out, tab_new_profile_action, 2) and
        self.activeWorkspace().tabCount() == tabs_before_mouse + 1, "clicking the beta row opened a tab", .{});
    profilesCheck(out, &failures, trace.calls == 2 and std.mem.startsWith(u8, trace.argv(), "/bin/sh -l -c printf "), "the login profile was started with -l: '{s}'", .{trace.argv()});
    profilesCheck(out, &failures, try waitForPanes(self, io, out, .{ .focused_text = "PROFILE-B:/bin/sh" }), "the beta child ran", .{});
    profilesCheck(out, &failures, try typeLine(self, io, out, home_probe) and
        try waitForPanes(self, io, out, .{ .focused_text = "HOME-42" }), "typed input read the login profile's HOME back from the shell", .{});

    // Split with profile, by keyboard.
    const split_tab = self.activeWorkspace().activeTabId() orelse return 1;
    profilesCheck(out, &failures, try runPaletteCommandByKeyboard(self, io, out, "Split with profile") and self.paletteVisible(), "Split with profile opened its chooser", .{});
    _ = try postNamedKey(self, io, out, .down, .{});
    _ = try postNamedKey(self, io, out, .enter, .{});
    profilesCheck(out, &failures, self.activeWorkspace().tab(split_tab).?.paneCount() == 2 and trace.calls == 3 and
        std.mem.eql(u8, trace.cwd(), root), "the split added a pane running alpha in its directory", .{});
    profilesCheck(out, &failures, try waitForPanes(self, io, out, .{ .focused_text = expected_a }), "the split pane's alpha child ran", .{});

    // Before `shell`, New tab runs the run's own child; after, the profile.
    const plain_tab_mods: platform.Mods = switch (self.binding_profile) {
        .macos => .{ .super = true },
        .linux_windows => .{ .ctrl = true, .shift = true },
    };
    _ = try postKey(self, io, out, 't', plain_tab_mods);
    profilesCheck(out, &failures, trace.calls == 3 and try waitForPanes(self, io, out, .{ .focused_text = "PROFILES-READY" }), "with shell unset, New tab ran the default child", .{});
    var config_buffer: [4096]u8 = undefined;
    const reloads_before_shell = self.config_reload_count;
    try writeConfigTestFile(io, path, try profilesTestConfig(&config_buffer, root, "shell = alpha\n"));
    profilesCheck(out, &failures, try waitForConfig(self, io, out, .{ .reloads = reloads_before_shell + 1 }) and
        std.mem.eql(u8, self.config_current.settings.shell, "alpha") and self.configErrorText() == null, "shell = alpha was reloaded without a restart", .{});
    _ = try postKey(self, io, out, 't', plain_tab_mods);
    const default_tab = self.activeWorkspace().activeTabId() orelse return 1;
    profilesCheck(out, &failures, trace.calls == 4 and std.mem.startsWith(u8, self.activeWorkspace().tab(default_tab).?.name(), "Terminal ") and
        try waitForPanes(self, io, out, .{ .focused_text = expected_a }), "with shell = alpha, the New tab chord ran alpha", .{});

    // The Shells group of the settings view.
    profilesCheck(out, &failures, try settingsChord(self, io, out) and self.settingsVisible(), "the settings chord opened the view", .{});
    profilesCheck(out, &failures, try selectSettingsRow(self, io, out, "settings.row.shell"), "Down reached the shell row", .{});
    const shell_label = settingsLabel(self, "settings.row.shell");
    profilesCheck(out, &failures, self.ui_tree.byId(.{ .value = "settings.heading.shells" }) != null and
        std.mem.startsWith(u8, shell_label, "shell") and std.mem.indexOf(u8, shell_label, "alpha ·") != null, "the Shells group shows shell = alpha from the file: '{s}'", .{shell_label});
    profilesCheck(out, &failures, try selectSettingsRow(self, io, out, "settings.row.profile.beta"), "Down reached the beta profile row", .{});
    const alpha_label = settingsLabel(self, "settings.row.profile.alpha");
    const beta_label = settingsLabel(self, "settings.row.profile.beta");
    profilesCheck(out, &failures, std.mem.startsWith(u8, alpha_label, "alpha") and std.mem.indexOf(u8, alpha_label, "/bin/sh -c printf") != null and
        std.mem.indexOf(u8, alpha_label, "…") != null, "the alpha row summarises its command: '{s}'", .{alpha_label});
    profilesCheck(out, &failures, std.mem.startsWith(u8, beta_label, "beta") and std.mem.indexOf(u8, beta_label, "/bin/sh -l -c") != null, "the beta row shows its login flag: '{s}'", .{beta_label});
    try self.drawFrame();
    const settings_pixels = try self.allocator.dupe(u8, try self.capture());
    defer self.allocator.free(settings_pixels);
    _ = try postNamedKey(self, io, out, .escape, .{});
    profilesCheck(out, &failures, !self.settingsVisible(), "Escape closed the settings view", .{});

    // A malformed profile line is reported and the rest of the file applies.
    const reloads_before_bad = self.config_reload_count;
    try writeConfigTestFile(io, path, try profilesTestConfig(&config_buffer, root, "shell = alpha\nprofile = broken = sh -c 'oops\n"));
    profilesCheck(out, &failures, try waitForConfig(self, io, out, .{ .reloads = reloads_before_bad + 1 }) and
        try waitForConfig(self, io, out, .{ .element = "config.error" }), "the malformed line showed config.error", .{});
    const error_label = settingsLabel(self, "config.error");
    profilesCheck(out, &failures, std.mem.eql(u8, error_label, "config:9: profile: unbalanced quotes") and
        self.config_current.settings.shell_profiles.len == 2, "config.error names the line and the key, and both good profiles stayed: '{s}'", .{error_label});

    var id_buffer: [path_capacity]u8 = undefined;
    const run_id = try generateRunId(io, &id_buffer);
    var chooser_path_buffer: [path_capacity]u8 = undefined;
    const chooser_path = try std.fmt.bufPrint(&chooser_path_buffer, "{s}{c}profiles-test-{s}-chooser.png", .{ fallback_log_dir, std.fs.path.sep, run_id });
    try writePngOffThread(self.allocator, io, chooser_path, chooser_pixels, self.size);
    var settings_path_buffer: [path_capacity]u8 = undefined;
    const settings_path = try std.fmt.bufPrint(&settings_path_buffer, "{s}{c}profiles-test-{s}-settings.png", .{ fallback_log_dir, std.fs.path.sep, run_id });
    try writePngOffThread(self.allocator, io, settings_path, settings_pixels, self.size);
    out.print("profiles-test: screenshot {s}\n", .{chooser_path}) catch {};
    out.print("profiles-test: screenshot {s}\n", .{settings_path}) catch {};
    out.print("profiles-test: {d} failure(s)\n", .{failures}) catch {};
    out.flush() catch {};
    return if (failures == 0) 0 else 1;
}

/// The deterministic peer behind `--settings-test`'s terminal.
const settings_test_script =
    "stty -echo; " ++
    "printf 'SETTINGS-READY\\r\\n'; " ++
    "while IFS= read -r line; do printf 'SETTINGS-ECHO:%s\\r\\n' \"$line\"; done";

/// The settings `--settings-test` starts with: everything at its default.
const settings_test_initial = "# --settings-test settings\n";

/// A private absolute path for `--settings-test`'s settings file.
fn settingsTestPath(io: Io, env: EnvSource, buffer: []u8) ![]const u8 {
    const base = firstEnv(env, temp_dir_vars[0..]) orelse "/tmp";
    const root = if (base.len != 0 and base[0] == '/') base else "/tmp";
    var id_buffer: [path_capacity]u8 = undefined;
    const id = try generateRunId(io, &id_buffer);
    return std.fmt.bufPrint(buffer, "{s}/conduit-settings-test-{s}/conduit/config", .{ root, id });
}

/// Remove `--settings-test`'s private directory: two levels above the file.
fn removeSettingsTestDir(io: Io, path: []const u8) void {
    const conduit_dir = config.directoryOf(path) orelse return;
    const root = config.directoryOf(conduit_dir) orelse return;
    if (std.mem.indexOf(u8, root, "conduit-settings-test-") == null) return;
    Dir.cwd().deleteTree(io, root) catch |err| {
        log.warn("could not remove the settings-test directory: {s}", .{@errorName(err)});
    };
}

fn settingsCheck(out: *Writer, failures: *usize, ok: bool, comptime format: []const u8, args: anytype) void {
    out.print("settings-test: {s} " ++ format ++ "\n", .{if (ok) "ok  " else "FAIL"} ++ args) catch {};
    if (!ok) failures.* += 1;
}

/// The shipped settings chord: Ctrl+Shift+, (Cmd+Shift+, on macOS).
fn settingsChord(self: *App, io: Io, out: *Writer) !bool {
    const mods: platform.Mods = switch (self.binding_profile) {
        .macos => .{ .shift = true, .super = true },
        .linux_windows => .{ .ctrl = true, .shift = true },
    };
    return postKey(self, io, out, ',', mods);
}

/// The id of the highlighted settings row, or "" while the view is closed.
fn settingsSelectedId(self: *const App) []const u8 {
    if (!self.settingsVisible() or self.settings_selected >= self.settings_row_count) return "";
    return self.settingsRowId(self.settings_selected);
}

/// Move the highlight with real Down presses until it is on `id`.
fn selectSettingsRow(self: *App, io: Io, out: *Writer, id: []const u8) !bool {
    for (0..self.settings_row_count + 1) |_| {
        if (std.mem.eql(u8, settingsSelectedId(self), id)) return true;
        if (!try postNamedKey(self, io, out, .down, .{})) return false;
    }
    return false;
}

/// The semantic label of element `id`, or "" when it is not in the tree.
fn settingsLabel(self: *const App, id: []const u8) []const u8 {
    const element = self.ui_tree.byId(.{ .value = id }) orelse return "";
    return element.label;
}

/// Exercise TASK-41 end to end through real SDL keys and pointer events: the
/// view opened from the palette and by its chord, keyboard navigation over
/// the group headings, a bool by Enter and by click, a percentage through the
/// inline Input, the size stepped with Right, an invalid value refused with
/// its diagnostic, a two-value enum cycled, a keybinding captured, a
/// conflicting chord refused and then taken, the raw-file row and modal
/// isolation, with the settings file read back after every change.
fn settingsTest(self: *App, io: Io, out: *Writer) !u8 {
    var failures: usize = 0;
    const path_copy = self.config_path orelse {
        out.writeAll("settings-test: FAIL no settings path\n") catch {};
        return 1;
    };
    var path_buffer: [path_capacity]u8 = undefined;
    @memcpy(path_buffer[0..path_copy.len], path_copy);
    const path = path_buffer[0..path_copy.len];
    var editor_trace: EditorSpawnTrace = .{};
    self.editor_spawn_observer = .{ .context = &editor_trace, .observe_fn = recordEditorSpawn };
    defer self.editor_spawn_observer = .{};

    const ligatures_off = settings_test_initial ++ "font.ligatures = false\n";
    const ligatures_on = settings_test_initial ++ "font.ligatures = true\n";
    const scratchpad_35 = ligatures_on ++ "scratchpad.size = 35\n";
    const size_15 = scratchpad_35 ++ "font.size = 15\n";
    const right_paste = size_15 ++ "mouse.right_click = paste\n";
    const right_menu = size_15 ++ "mouse.right_click = menu\n";
    const rebound = right_menu ++ "keybind = ctrl+shift+p=unbind\nkeybind = ctrl+alt+k=palette.open\n";
    const stolen = right_menu ++ "keybind = ctrl+shift+p=unbind\nkeybind = ctrl+shift+t=palette.open\n";
    const palette_row = "settings.row.keybind." ++ palette_open_action;

    try self.drawFrame();
    settingsCheck(out, &failures, try waitForPanes(self, io, out, .{ .focused_text = "SETTINGS-READY" }), "the real settings-test child became ready", .{});
    settingsCheck(out, &failures, try waitForConfig(self, io, out, .font_settled), "startup drew the bundled face", .{});

    // Opened from the palette by keyboard, on the first setting.
    settingsCheck(out, &failures, try runPaletteCommandByKeyboard(self, io, out, "Settings") and self.settingsVisible() and
        !self.paletteVisible() and self.ui_tree.byId(.{ .value = "settings.dialog" }) != null, "typing settings into the palette and Enter opened settings.dialog", .{});
    settingsCheck(out, &failures, std.mem.eql(u8, settingsSelectedId(self), "settings.row.theme") and
        self.ui_tree.byId(.{ .value = "settings.heading.appearance" }) != null and
        std.mem.indexOf(u8, settingsLabel(self, "settings.row.font.size"), "14") != null, "the first setting is highlighted under its heading and rows show live values", .{});

    // Navigation skips the headings and wraps.
    _ = try postNamedKey(self, io, out, .down, .{});
    settingsCheck(out, &failures, std.mem.eql(u8, settingsSelectedId(self), "settings.row.font.family"), "Down skipped the Fonts heading to font.family", .{});
    _ = try postNamedKey(self, io, out, .up, .{});
    _ = try postNamedKey(self, io, out, .up, .{});
    settingsCheck(out, &failures, std.mem.eql(u8, settingsSelectedId(self), "settings.raw"), "Up past the first heading wrapped to the raw-file row", .{});
    _ = try postNamedKey(self, io, out, .home, .{});
    const home = settingsSelectedId(self);
    _ = try postNamedKey(self, io, out, .end, .{});
    settingsCheck(out, &failures, std.mem.eql(u8, home, "settings.row.theme") and
        std.mem.eql(u8, settingsSelectedId(self), "settings.raw") and self.ui_tree.byId(.{ .value = "settings.raw" }) != null, "Home and End jump to the first and last rows and keep the highlight on screen", .{});
    _ = try postNamedKey(self, io, out, .escape, .{});
    settingsCheck(out, &failures, !self.settingsVisible() and self.ui_tree.byId(.{ .value = "settings.dialog" }) == null, "Escape closed the view", .{});
    settingsCheck(out, &failures, try settingsChord(self, io, out) and self.settingsVisible(), "the shipped Ctrl+Shift+, opened it again", .{});

    // A fixed-choice row opens the existing chooser.
    _ = try postNamedKey(self, io, out, .enter, .{});
    settingsCheck(out, &failures, !self.settingsVisible() and self.themePickerSelection() != null, "Enter on theme opened the theme chooser", .{});
    _ = try postNamedKey(self, io, out, .escape, .{});
    _ = try settingsChord(self, io, out);

    // A bool by keyboard and by mouse.
    settingsCheck(out, &failures, try selectSettingsRow(self, io, out, "settings.row.font.ligatures"), "Down reached font.ligatures", .{});
    _ = try postNamedKey(self, io, out, .enter, .{});
    settingsCheck(out, &failures, !self.font_settings.values.ligatures and !self.fonts.ligatures() and fontFileIs(io, path, ligatures_off) and
        std.mem.endsWith(u8, settingsLabel(self, "settings.row.font.ligatures"), "false ·"), "Enter turned ligatures off, wrote font.ligatures = false and marked the row as set in the file", .{});
    settingsCheck(out, &failures, try clickTabsElement(self, io, out, "settings.row.font.ligatures") and self.settingsVisible() and
        self.font_settings.values.ligatures and fontFileIs(io, path, ligatures_on), "clicking the row turned them back on and rewrote the same line", .{});

    // A percentage through the inline Input, by keyboard.
    settingsCheck(out, &failures, try selectSettingsRow(self, io, out, "settings.row.scratchpad.size"), "Down reached scratchpad.size", .{});
    _ = try postNamedKey(self, io, out, .enter, .{});
    const field = self.ui_tree.byId(.{ .value = "settings.input" });
    settingsCheck(out, &failures, field != null and field.?.state.focused and std.mem.eql(u8, self.settings_input.text(), "50"), "Enter opened the focused settings.input holding 50", .{});
    _ = try postNamedKey(self, io, out, .backspace, .{});
    _ = try postNamedKey(self, io, out, .backspace, .{});
    _ = try postPaletteText(self, io, out, "35");
    _ = try postNamedKey(self, io, out, .enter, .{});
    settingsCheck(out, &failures, self.settings_mode == .browse and self.ui_tree.byId(.{ .value = "settings.input" }) == null and
        self.scratchpad_percent_small == 35 and fontFileIs(io, path, scratchpad_35), "typing 35 and Enter saved scratchpad.size = 35", .{});
    _ = try postNamedKey(self, io, out, .escape, .{});
    _ = try scratchpadChord(self, io, out, false);
    const dock = self.scratchpadBounds();
    settingsCheck(out, &failures, dock != null and dock.?.height == expectedScratchpadHeight(self, 35), "the scratchpad chord opened a 35 percent dock", .{});
    _ = try scratchpadChord(self, io, out, false);

    // The size stepped with Right: cell metrics, the file, no second build.
    _ = try settingsChord(self, io, out);
    settingsCheck(out, &failures, try selectSettingsRow(self, io, out, "settings.row.font.size"), "Down reached font.size", .{});
    const height_before = self.fonts.metrics().cell.height_px;
    const reloads = self.config_reload_count;
    _ = try postNamedKey(self, io, out, .right, .{});
    const loads = self.font_load_count;
    settingsCheck(out, &failures, try waitForConfig(self, io, out, .font_settled) and self.font_settings.values.points == 15 and
        self.fonts.metrics().cell.height_px > height_before and fontFileIs(io, path, size_15), "Right stepped to 15 points: cell height {d}px -> {d}px and font.size = 15 saved", .{ height_before, self.fonts.metrics().cell.height_px });
    settingsCheck(out, &failures, try waitForConfig(self, io, out, .{ .reloads = reloads + 2 }) and try waitForConfig(self, io, out, .font_settled) and
        self.font_load_count == loads, "the watcher's reload of that write built nothing more", .{});

    // An invalid value: the diagnostic, and nothing written.
    _ = try postNamedKey(self, io, out, .enter, .{});
    _ = try postKey(self, io, out, 'a', switch (self.binding_profile) {
        .macos => .{ .super = true },
        .linux_windows => .{ .ctrl = true },
    });
    _ = try postPaletteText(self, io, out, "99");
    _ = try postNamedKey(self, io, out, .enter, .{});
    settingsCheck(out, &failures, std.mem.eql(u8, settingsLabel(self, "settings.error"), "font.size: expected 1 to 72 points") and
        self.settings_mode == .edit and self.font_settings.values.points == 15 and fontFileIs(io, path, size_15), "99 points was refused with '{s}' and the file is unchanged", .{settingsLabel(self, "settings.error")});
    _ = try postNamedKey(self, io, out, .escape, .{});
    settingsCheck(out, &failures, self.settings_mode == .browse and self.settingsVisible() and
        self.ui_tree.byId(.{ .value = "settings.error" }) == null, "Escape cancelled the edit and cleared the error", .{});

    // A two-value enum cycles.
    settingsCheck(out, &failures, try selectSettingsRow(self, io, out, "settings.row.mouse.right_click"), "Down reached mouse.right_click", .{});
    _ = try postNamedKey(self, io, out, .enter, .{});
    settingsCheck(out, &failures, self.right_click == .paste and fontFileIs(io, path, right_paste), "Enter cycled the right click to paste and saved it", .{});
    _ = try postNamedKey(self, io, out, .left, .{});
    settingsCheck(out, &failures, self.right_click == .menu and fontFileIs(io, path, right_menu), "Left cycled it back to menu", .{});

    // A keybinding captured through the real key path.
    const tabs = self.activeWorkspace().tabCount();
    settingsCheck(out, &failures, try selectSettingsRow(self, io, out, palette_row), "Down reached the Open command palette key row", .{});
    _ = try postNamedKey(self, io, out, .enter, .{});
    settingsCheck(out, &failures, self.settings_mode == .capture and
        std.mem.indexOf(u8, settingsLabel(self, palette_row), settings_capture_text) != null, "Enter asked for a chord", .{});
    _ = try postKey(self, io, out, 'k', .{ .ctrl = true, .alt = true });
    settingsCheck(out, &failures, self.settings_mode == .browse and fontFileIs(io, path, rebound) and
        std.mem.indexOf(u8, settingsLabel(self, palette_row), "Ctrl+Alt+K") != null, "Ctrl+Alt+K was captured and saved, replacing the shipped chord", .{});
    _ = try postNamedKey(self, io, out, .escape, .{});
    settingsCheck(out, &failures, try postKey(self, io, out, 'k', .{ .ctrl = true, .alt = true }) and self.paletteVisible(), "the captured Ctrl+Alt+K opened the palette", .{});
    _ = try postNamedKey(self, io, out, .escape, .{});
    _ = try paletteChord(self, io, out);
    settingsCheck(out, &failures, !self.paletteVisible(), "the old Ctrl+Shift+P no longer does", .{});

    // A chord another command holds: named, kept on Escape, taken on Enter.
    _ = try settingsChord(self, io, out);
    _ = try selectSettingsRow(self, io, out, palette_row);
    _ = try postNamedKey(self, io, out, .enter, .{});
    _ = try postKey(self, io, out, 't', .{ .ctrl = true, .shift = true });
    settingsCheck(out, &failures, self.settings_mode == .conflict and std.mem.eql(u8, settingsLabel(self, "settings.error"), "conflict: New tab") and
        self.activeWorkspace().tabCount() == tabs and fontFileIs(io, path, rebound), "Ctrl+Shift+T was reported as '{s}' without opening a tab", .{settingsLabel(self, "settings.error")});
    _ = try postNamedKey(self, io, out, .escape, .{});
    const kept = inputmod.findBinding(self.bindings, try inputmod.parseChord("ctrl+shift+t"));
    settingsCheck(out, &failures, self.settings_mode == .browse and self.ui_tree.byId(.{ .value = "settings.error" }) == null and
        kept != null and std.mem.eql(u8, kept.?.action, tab_new_action) and fontFileIs(io, path, rebound), "Escape kept New tab's chord and the file", .{});
    _ = try postNamedKey(self, io, out, .enter, .{});
    _ = try postKey(self, io, out, 't', .{ .ctrl = true, .shift = true });
    _ = try postNamedKey(self, io, out, .enter, .{});
    settingsCheck(out, &failures, self.settings_mode == .browse and fontFileIs(io, path, stolen) and
        std.mem.indexOf(u8, settingsLabel(self, palette_row), "Ctrl+Shift+T") != null, "Enter took Ctrl+Shift+T for the palette and saved it", .{});
    _ = try postNamedKey(self, io, out, .escape, .{});
    settingsCheck(out, &failures, try postKey(self, io, out, 't', .{ .ctrl = true, .shift = true }) and self.paletteVisible() and
        self.activeWorkspace().tabCount() == tabs, "Ctrl+Shift+T now opens the palette and no tab", .{});
    _ = try postNamedKey(self, io, out, .escape, .{});

    // Modal isolation: keys, text and clicks behind the view do nothing.
    _ = try settingsChord(self, io, out);
    const routes = self.terminal_key_route_count;
    const dispatches = self.action_dispatch_count;
    _ = try postKey(self, io, out, 't', .{ .ctrl = true, .shift = true });
    _ = try postKey(self, io, out, 'x', .{});
    _ = try postPaletteText(self, io, out, "zz");
    settingsCheck(out, &failures, self.settingsVisible() and !self.paletteVisible() and self.terminal_key_route_count == routes and
        self.action_dispatch_count == dispatches, "a bound chord, a key and typed text behind the view reached nothing", .{});
    _ = try postNamedKey(self, io, out, .home, .{});
    settingsCheck(out, &failures, try clickTabsElement(self, io, out, "settings.heading.appearance") and self.settingsVisible() and
        self.action_dispatch_count == dispatches, "clicking a heading did nothing", .{});
    _ = try postLeftClick(self, io, out, 2, 2);
    settingsCheck(out, &failures, !self.settingsVisible() and !self.paletteVisible() and !self.settings_pointer_owned and
        self.action_dispatch_count == dispatches and self.terminal_key_route_count == routes, "a click outside closed the view and reached nothing beneath", .{});

    // The raw-file row, by mouse, opens the file in an editor tab.
    _ = try settingsChord(self, io, out);
    _ = try postNamedKey(self, io, out, .end, .{});
    var expected_argv_buffer: [path_capacity + 16]u8 = undefined;
    const expected_argv = try std.fmt.bufPrint(&expected_argv_buffer, "vi -- {s}", .{path});
    settingsCheck(out, &failures, try clickTabsElement(self, io, out, "settings.raw") and !self.settingsVisible() and
        self.activeWorkspace().tabCount() == tabs + 1 and editor_trace.calls == 1 and std.mem.eql(u8, editor_trace.argv(), expected_argv), "clicking Open config file opened '{s}' in a new tab", .{editor_trace.argv()});
    settingsCheck(out, &failures, try waitForConfig(self, io, out, .{ .active_text = "ctrl+shift+t=palette.open" }), "the editor drew the saved file", .{});

    // Leave the view open with a row highlighted for the screenshot.
    _ = try settingsChord(self, io, out);
    _ = try postNamedKey(self, io, out, .down, .{});
    _ = try postNamedKey(self, io, out, .down, .{});
    try self.drawFrame();
    settingsCheck(out, &failures, self.settingsVisible() and std.mem.eql(u8, settingsSelectedId(self), "settings.row.font.bold"), "the view is open on font.bold for the screenshot", .{});

    out.print("settings-test: {d} failure(s)\n", .{failures}) catch {};
    out.flush() catch {};
    return if (failures == 0) 0 else 1;
}

const ime_test_commit: [:0]const u8 = "日本語";
const ime_test_preedit: [:0]const u8 = "にほん";
const ime_test_wide: [:0]const u8 = "日本";
const ime_test_screenshot_preedit: [:0]const u8 = "compose";
const ime_test_ready = "IME-READY\r\n";
const ime_test_done = "IME-DONE\r\n";
const ime_test_budget_ms: i64 = 5000;

/// A fixed real PTY peer for `--ime-test`. It announces readiness, reads the
/// exact commit length in raw mode, echoes those bytes as hex, then stays
/// blocked on input so the idle-loop measurement has a live child.
const ime_test_script = std.fmt.comptimePrint(
    "stty raw -echo; " ++
        "printf '\\033[48;2;17;31;47m\\033[2J\\033[?25lIME-READY\\r\\n'; " ++
        "dd bs=1 count={d} 2>/dev/null | od -An -tx1 -v | tr -d '\\n'; " ++
        "printf '\\r\\nIME-DONE\\r\\n'; " ++
        "while :; do dd bs=1 count=1 2>/dev/null >/dev/null; done",
    .{ime_test_commit.len},
);

fn imeCheck(out: *Writer, failures: *usize, ok: bool, comptime format: []const u8, args: anytype) void {
    out.print("ime-test: {s} " ++ format ++ "\n", .{if (ok) "ok  " else "FAIL"} ++ args) catch {};
    if (!ok) failures.* += 1;
}

fn positionTerminalCursor(self: *App, col: u16, row: u16) !void {
    var control: [32]u8 = undefined;
    const move = try std.fmt.bufPrint(&control, "\x1b[{d};{d}H", .{ row + 1, col + 1 });
    self.activeLive().terminal().feed(move);
    self.invalidateUi();
}

/// Drive inline composition through SDL's real queue and commit through a
/// real PTY. The fixture uses the same renderer, event handler and single
/// child-write site as an ordinary window.
fn imeTest(self: *App, io: Io, out: *Writer) !u8 {
    var failures: usize = 0;
    var trace: ClipboardTrace = .{};
    defer trace.deinit(self.allocator);
    self.trace = &trace;
    defer self.trace = null;

    if (self.activePresentation().load) |job| {
        if (job.thread) |thread| thread.join();
        job.thread = null;
    }
    _ = self.pollLoad();
    if (self.activeLive().child() == null) {
        imeCheck(out, &failures, false, "the child did not start", .{});
        return 1;
    }
    imeCheck(out, &failures, try waitForChildText(self, io, ime_test_ready), "the raw PTY child announced readiness", .{});
    try settle(self, out);

    const grid = self.activeLive().terminal().gridSize();
    const initial_col: u16 = @min(4, grid.cols - 1);
    const initial_row: u16 = @min(4, grid.rows - 1);
    try positionTerminalCursor(self, initial_col, initial_row);
    try self.drawFrame();
    const baseline = try self.allocator.dupe(u8, try self.capture());
    defer self.allocator.free(baseline);

    const sent_before_preedit = trace.sent.items.len;
    try self.window.postTextEditing(ime_test_preedit, 3, 3);
    imeCheck(out, &failures, try pumpUntil(self, io, out, .text_editing, ime_test_budget_ms), "SDL delivered the text-editing event", .{});
    imeCheck(out, &failures, trace.sent.items.len == sent_before_preedit, "the preedit wrote zero bytes to the child", .{});
    try self.drawFrame();
    const composed = try self.allocator.dupe(u8, try self.capture());
    defer self.allocator.free(composed);
    const initial_position = render.OverlayPosition{ .col = initial_col, .row = initial_row };
    const initial_rect = uiTestCellRect(self, initial_position);
    const projected = self.ui_canvas.view(&default_palette);
    const first = overlayCellAt(projected, initial_position);
    const preedit_element = self.ui_tree.byId(.{ .value = "ime.preedit" });
    const accent = ui.resolveRole(&default_palette, .accent);
    imeCheck(out, &failures, preedit_element != null and
        std.mem.eql(u8, preedit_element.?.role, "preedit") and
        std.mem.eql(u8, preedit_element.?.label, ime_test_preedit) and
        first != null and first.?.underline != null and
        sameColor(first.?.underline.?, accent), "the semantic preedit uses the accent underline at the terminal cursor", .{});
    imeCheck(out, &failures, countDifferingPixelsInRect(baseline, composed, self.size, initial_rect) > 0, "the styled preedit changed framebuffer pixels at the real cursor", .{});

    const logical_cell = platform.LogicalSize{
        .width = logicalPixels(self.fonts.metrics().cell.width_px, self.window.state.scale),
        .height = logicalPixels(self.fonts.metrics().cell.height_px, self.window.state.scale),
    };
    const area = self.window.textInputArea();
    const expected_caret_cells = preeditCellWidth(ime_test_preedit[0..3]) orelse 0;
    const expected_col = @min(@as(u32, initial_col) + expected_caret_cells, @as(u32, grid.cols - 1));
    const expected_area = platform.LogicalRect.forCell(expected_col, initial_row, logical_cell, 0);
    imeCheck(out, &failures, area != null and std.meta.eql(area.?.rect, expected_area), "the native candidate area follows the rendered preedit caret", .{});

    try self.window.postTextEditing("", 0, 0);
    imeCheck(out, &failures, try pumpUntil(self, io, out, .text_editing, ime_test_budget_ms), "SDL delivered composition cancellation", .{});
    try self.drawFrame();
    const restored = try self.capture();
    imeCheck(out, &failures, countDifferingPixels(baseline, restored) == 0, "removing the preedit restored the terminal framebuffer exactly", .{});

    const edge_col: u16 = if (grid.cols >= 2) grid.cols - 2 else 0;
    try positionTerminalCursor(self, edge_col, initial_row);
    try self.drawFrame();
    const edge_baseline = try self.allocator.dupe(u8, try self.capture());
    defer self.allocator.free(edge_baseline);
    const sent_before_wide = trace.sent.items.len;
    try self.window.postTextEditing(ime_test_wide, 0, 0);
    imeCheck(out, &failures, try pumpUntil(self, io, out, .text_editing, ime_test_budget_ms), "SDL delivered the right-edge wide preedit", .{});
    try self.drawFrame();
    const edge_composed = try self.allocator.dupe(u8, try self.capture());
    defer self.allocator.free(edge_composed);
    const edge_view = self.ui_canvas.view(&default_palette);
    const edge = overlayCellAt(edge_view, .{ .col = edge_col, .row = initial_row });
    imeCheck(out, &failures, trace.sent.items.len == sent_before_wide and edge_view.cells.len == 1 and edge != null and edge.?.span == .two and std.mem.eql(u8, edge.?.text, "日"), "a wide preedit clips whole graphemes at the right edge and writes no bytes", .{});
    const edge_rect = uiTestCellRect(self, .{ .col = edge_col, .row = initial_row });
    imeCheck(out, &failures, countDifferingPixelsInRect(edge_baseline, edge_composed, self.size, edge_rect) > 0, "the fitting wide grapheme changed framebuffer pixels", .{});

    try self.window.postTextEditing("", 0, 0);
    _ = try pumpUntil(self, io, out, .text_editing, ime_test_budget_ms);
    try self.drawFrame();
    imeCheck(out, &failures, countDifferingPixels(edge_baseline, try self.capture()) == 0, "removing the clipped preedit restored the edge", .{});

    try positionTerminalCursor(self, initial_col, initial_row);
    try self.window.postTextEditing(ime_test_commit, 3, 0);
    _ = try pumpUntil(self, io, out, .text_editing, ime_test_budget_ms);
    const commit_mark = trace.sent.items.len;
    try self.window.postTextInput(ime_test_commit);
    imeCheck(out, &failures, try pumpUntil(self, io, out, .text_input, ime_test_budget_ms), "SDL delivered the committed UTF-8", .{});
    const committed = trace.sent.items[commit_mark..];
    imeCheck(out, &failures, std.mem.eql(u8, committed, ime_test_commit), "the app wrote the committed UTF-8 exactly once ({d} bytes)", .{committed.len});
    var echo_buffer: [64]u8 = undefined;
    const echoed = try waitForEcho(self, io, ime_test_ready, ime_test_commit.len, &echo_buffer);
    imeCheck(out, &failures, std.mem.eql(u8, echoed, ime_test_commit), "the real child received the exact committed UTF-8", .{});
    imeCheck(out, &failures, try waitForChildText(self, io, ime_test_done), "the child completed its exact-length read", .{});
    try self.drawFrame();
    imeCheck(out, &failures, !self.composition.isComposing() and
        self.ui_tree.byId(.{ .value = "ime.preedit" }) == null and
        self.ui_canvas.view(&default_palette).cells.len == 0, "commit removed the semantic preedit and its overlay", .{});

    imeCheck(out, &failures, try waitForScratchpad(self, io, out, .prompt), "the deterministic hidden scratchpad settled before idle measurement", .{});
    try settle(self, out);
    if (self.scheduler.shouldDraw()) try self.drawFrame();
    const frames_before = self.scheduler.frames;
    const stats_before = self.focusedGrid().gridStats();
    const idle_deadline = Io.Clock.real.now(io).nanoseconds + 250 * std.time.ns_per_ms;
    try self.run(io, idle_deadline);
    const idle = statDelta(self.focusedGrid().gridStats(), stats_before);
    imeCheck(out, &failures, self.scheduler.frames == frames_before and idle.rows == 0 and idle.draws == 0 and idle.buffer_uploads == 0, "250 ms idle drew zero frames and did zero GPU work", .{});

    // Leave a representative live preedit for --screenshot inspection.
    try positionTerminalCursor(self, initial_col, initial_row);
    // Keep CJK in the byte and clipping assertions above, but use glyphs the
    // bundled JetBrains face owns for the human-facing capture. The middle
    // three letters remain selected, so both the accent underline and the
    // composition selection are visible without a system font fallback.
    try self.window.postTextEditing(ime_test_screenshot_preedit, 2, 3);
    _ = try pumpUntil(self, io, out, .text_editing, ime_test_budget_ms);
    try self.drawFrame();

    out.print("ime-test: {d} failure(s)\n", .{failures}) catch {};
    out.flush() catch {};
    return if (failures == 0) 0 else 1;
}

/// The TASK-7 integration check, against a real window and real pixels: a
/// surface that clears, events that arrive and are acted on, an idle loop that
/// draws nothing, and a close request that ends the run.
///
/// It drives the app the way a person does — by asking the OS for a resize, and
/// by asking the window to close through SDL's own queue — because Xvfb has no
/// window manager to click and no settings daemon to move a display. Everything
/// it prints is what the run measured, not what it intended: a step that did not
/// happen is reported as not having happened.
fn selfTest(self: *App, io: Io, out: *Writer) !void {
    const window = self.window;
    out.print(
        "self-test: window id {d}, {d}x{d} logical, scale {d:.2}, surface {d}x{d}, visible {}\n",
        .{
            window.id,
            window.state.logical.width,
            window.state.logical.height,
            window.state.scale.factor,
            self.size.width,
            self.size.height,
            window.isVisible(),
        },
    ) catch {};
    // The driver's own pixel size next to the one the scale rule derived: a
    // display where the two disagree shows up here rather than as a stretched
    // image.
    if (window.pixelSize()) |pixels| {
        out.print("self-test: driver pixel size {d}x{d}, scale rule {d}x{d}\n", .{
            pixels.width_px,
            pixels.height_px,
            window.state.surface.width_px,
            window.state.surface.height_px,
        }) catch {};
    }
    out.flush() catch {};

    // 1. The surface is cleared to the background colour, in every pixel of it.
    try self.drawFrame();
    try reportCapture(self, out, "self-test: first frame");

    // 1b. The grid the renderer drew, and what it did to draw it. The check runs
    //     with no child (`wantsChild`), and puts a known line on the screen
    //     first, so the grid has something to draw that is not a program's
    //     output arriving underneath the measurement.
    self.activeLive().terminal().feed("\x1b[2J\x1b[Hconduit self-test\x1b[1;1H");
    // No `refresh` here: `drawFrame` refreshes, and `Terminal.damage` reports the
    // damage of the *last* refresh. Refreshing twice would consume the damage
    // this frame is supposed to draw, and the known line would never reach the
    // surface — which is what the grid check below measures.
    try self.drawFrame();
    const failures = try selfTestGrid(self, out);
    out.print("self-test: {d} grid failure(s)\n", .{failures}) catch {};
    out.flush() catch {};

    // 2. A resize, driven the way a window manager drives one: the app asks the
    //    OS for a size and the event comes back through SDL's queue.
    const target: platform.LogicalSize = .{
        .width = @max(window.state.logical.width / 2, 1),
        .height = @max(window.state.logical.height / 2, 1),
    };
    out.print("self-test: asking the OS for {d}x{d} logical\n", .{ target.width, target.height }) catch {};
    try window.setLogicalSize(target);
    if (try pumpUntil(self, io, out, .{ .resize = target }, self_test_event_budget_ms)) {
        // Drain what is still queued — a window is configured once after it is
        // created, and that resize queues beside the one above — and then draw,
        // because a capture reads the surface as it stands, and the surface was
        // just re-created with nothing drawn into it.
        try settle(self, out);
        if (self.scheduler.shouldDraw()) try self.drawFrame();
        try reportCapture(self, out, "self-test: after resize");
    } else {
        out.print("self-test: NO resize event reported {d}x{d} logical\n", .{ target.width, target.height }) catch {};
    }

    // 3. A display-scale change, driven the way a settings daemon drives one. The
    //    app re-asks the display what it reports and acts on the answer, which is
    //    what makes a scale change a comparison rather than an assumption.
    try window.postDisplayScaleChanged();
    if (!try pumpUntil(self, io, out, .scale, self_test_event_budget_ms)) {
        out.print("self-test: NO display-scale-changed event arrived\n", .{}) catch {};
    }

    // 4. An untouched window. Anything the scale change invalidated is drawn
    //    first, so the interval measured below begins with a surface that matches
    //    the window — otherwise the first iteration's frame would be counted as
    //    idle work when it is really the tail of the event above.
    if (self.scheduler.shouldDraw()) try self.drawFrame();
    const frames_before = self.scheduler.frames;
    const idle_deadline = Io.Clock.real.now(io).nanoseconds + self_test_idle_ms * std.time.ns_per_ms;
    try self.run(io, idle_deadline);
    out.print(
        "self-test: {d} ms with nothing happening drew {d} frames (force_redraw {})\n",
        .{ self_test_idle_ms, self.scheduler.frames - frames_before, self.scheduler.force },
    ) catch {};
    out.flush() catch {};

    // 5. Close, through the same event a window manager's close button sends.
    try window.postCloseRequest();
    if (!try pumpUntil(self, io, out, .close, self_test_event_budget_ms)) {
        out.flush() catch {};
        return error.SelfTestCloseNotDelivered;
    }
    out.print("self-test: the close request ended the run\n", .{}) catch {};
    out.flush() catch {};
}

/// Pump events until one of `awaited` arrives, the budget runs out, or the app
/// decides to stop, printing each event as it is handled.
///
/// Returns whether the awaited event arrived. The events in between are handled
/// rather than discarded, because a real run would react to all of them: a resize
/// arriving with an expose beside it is the ordinary case, not a test artefact.
fn pumpUntil(
    self: *App,
    io: Io,
    out: *Writer,
    awaited: Awaited,
    budget_ms: i64,
) !bool {
    const deadline = Io.Clock.real.now(io).nanoseconds + budget_ms * std.time.ns_per_ms;
    while (true) {
        const event = self.window.pump(eventWaitBudget(io, deadline, false)) orelse {
            if (Io.Clock.real.now(io).nanoseconds >= deadline) return false;
            continue;
        };
        describeEvent(out, event) catch {};
        out.flush() catch {};
        const keep_going = try self.handle(event);
        if (isAwaited(awaited, event)) return true;
        if (!keep_going) return false;
    }
}

/// Handle events until the queue has been quiet for `settle_quiet_ms`, printing
/// each.
///
/// A window is configured once after it is created, and a resize queues beside
/// that, so the first moments of a run carry events nobody asked for. Draining
/// them means the next measurement is taken on a window that has finished moving
/// rather than on one still catching up — and it is what a real run does anyway,
/// because `handle` is where every event is reacted to.
fn settle(self: *App, out: *Writer) !void {
    while (self.window.pump(settle_quiet_ms)) |event| {
        describeEvent(out, event) catch {};
        out.flush() catch {};
        if (!try self.handle(event)) return;
    }
}

/// Write one event as the app saw it, so the sequence a run produced is in its
/// own output and not only in the log file.
fn describeEvent(out: *Writer, event: platform.Event) !void {
    switch (event) {
        .resized => |state| try out.print(
            "  event resized: {d}x{d} logical, surface {d}x{d}\n",
            .{ state.logical.width, state.logical.height, state.surface.width_px, state.surface.height_px },
        ),
        .scale_changed => |change| try out.print(
            "  event display scale changed: {d:.2} -> {d:.2}, surface {d}x{d}\n",
            .{ change.previous.factor, change.state.scale.factor, change.state.surface.width_px, change.state.surface.height_px },
        ),
        .focused => try out.print("  event focus gained\n", .{}),
        .unfocused => try out.print("  event focus lost\n", .{}),
        .exposed => try out.print("  event exposed\n", .{}),
        .close_requested => try out.print("  event close requested\n", .{}),
        .quit => try out.print("  event quit\n", .{}),
        // Pointer events are described rather than named, because for
        // `--mouse-test` the position and the modifiers *are* the measurement:
        // a line reading only "event mouse_button" would report that an event
        // happened, not where it happened or with what held.
        .mouse_button => |button| try out.print(
            "  event mouse button {s} {s} at ({d},{d}) shift={} alt={} ctrl={} super={}\n",
            .{
                @tagName(button.action),
                @tagName(button.button),
                @as(i32, @intFromFloat(@round(button.x))),
                @as(i32, @intFromFloat(@round(button.y))),
                button.mods.shift,
                button.mods.alt,
                button.mods.ctrl,
                button.mods.super,
            },
        ),
        .mouse_motion => |motion| try out.print(
            "  event mouse motion at ({d},{d}) left={} shift={} alt={}\n",
            .{
                @as(i32, @intFromFloat(@round(motion.x))),
                @as(i32, @intFromFloat(@round(motion.y))),
                motion.buttons.left,
                motion.mods.shift,
                motion.mods.alt,
            },
        ),
        // The input slice's events are named rather than described: this
        // function reports what the app saw, and the input path is what turns
        // them into something (TASK-12).
        else => |other| try out.print("  event {s}\n", .{@tagName(std.meta.activeTag(other))}),
    }
}

/// Report one capture: the surface's size, and what is actually in it.
///
/// The pixels come from `capture`, the same path a screenshot takes, and the
/// count is of pixels exactly equal to the background colour. "The surface is the
/// background" is then a measurement of every pixel rather than a claim about the
/// one that happened to be in the corner.
fn reportCapture(self: *App, out: *Writer, label: []const u8) !void {
    const pixels = try self.capture();
    const total = pixels.len / 4;
    const matched = countPixels(pixels, self.background);
    out.print("{s}: surface {d}x{d}, cleared to ", .{ label, self.size.width, self.size.height }) catch {};
    writeColor(out, self.background) catch {};
    out.print(", {d}/{d} pixels are that colour, top-left ", .{ matched, total }) catch {};
    writeColor(out, pixelAt(pixels, self.size, 0, 0)) catch {};
    out.print(", centre ", .{}) catch {};
    writeColor(out, pixelAt(pixels, self.size, self.size.width / 2, self.size.height / 2)) catch {};
    out.print(", bottom-right ", .{}) catch {};
    writeColor(out, pixelAt(pixels, self.size, self.size.width - 1, self.size.height - 1)) catch {};
    out.print("\n", .{}) catch {};
    out.flush() catch {};
}

/// Write a colour as the four bytes a capture holds, so a reader can compare it
/// with the colour the frame was cleared to.
fn writeColor(out: *Writer, color: render.Rgba) !void {
    try out.print("({d},{d},{d},{d})", .{ color.r, color.g, color.b, color.a });
}

/// The pixel at `x`, `y` of a capture, with `y` counted from the top: `read`
/// already flipped the rows, so the buffer is top-down.
fn pixelAt(pixels: []const u8, size: render.Size, x: u32, y: u32) render.Rgba {
    const offset = (@as(usize, y) * size.width + x) * 4;
    return .{ .r = pixels[offset], .g = pixels[offset + 1], .b = pixels[offset + 2], .a = pixels[offset + 3] };
}

/// How many pixels of a capture are exactly `want`.
fn countPixels(pixels: []const u8, want: render.Rgba) usize {
    var matched: usize = 0;
    var offset: usize = 0;
    while (offset + 4 <= pixels.len) : (offset += 4) {
        if (pixels[offset] == want.r and pixels[offset + 1] == want.g and
            pixels[offset + 2] == want.b and pixels[offset + 3] == want.a)
        {
            matched += 1;
        }
    }
    return matched;
}

/// Whether two colours are the same colour, which a capture's pixels and a
/// palette both speak in.
fn sameColor(one: render.Rgba, other: render.Rgba) bool {
    return one.r == other.r and one.g == other.g and one.b == other.b and one.a == other.a;
}

/// How many pixels of `rect` are not `background`. The count that says "there
/// is a glyph here" without claiming anything about its shape.
fn countOther(pixels: []const u8, size: render.Size, rect: render.PixelRect, backdrop: render.Rgba) usize {
    const x_end = @min(size.width, @as(u32, @intFromFloat(rect.x + rect.width)));
    const y_end = @min(size.height, @as(u32, @intFromFloat(rect.y + rect.height)));
    var counted: usize = 0;
    var y: u32 = @intFromFloat(rect.y);
    while (y < y_end) : (y += 1) {
        var x: u32 = @intFromFloat(rect.x);
        while (x < x_end) : (x += 1) {
            if (!sameColor(pixelAt(pixels, size, x, y), backdrop)) counted += 1;
        }
    }
    return counted;
}

/// The pixel in `rect` farthest from `backdrop`, or null when the rectangle is
/// entirely its background. Looking at the strongest coverage pixel makes a
/// glyph's requested foreground measurable without depending on a particular
/// face having a fully opaque texel.
fn farthestPixel(pixels: []const u8, size: render.Size, rect: render.PixelRect, backdrop: render.Rgba) ?render.Rgba {
    const x_end = @min(size.width, @as(u32, @intFromFloat(rect.x + rect.width)));
    const y_end = @min(size.height, @as(u32, @intFromFloat(rect.y + rect.height)));
    var farthest: ?render.Rgba = null;
    var farthest_distance: u32 = 0;
    var y: u32 = @intFromFloat(rect.y);
    while (y < y_end) : (y += 1) {
        var x: u32 = @intFromFloat(rect.x);
        while (x < x_end) : (x += 1) {
            const pixel = pixelAt(pixels, size, x, y);
            const distance = colorDistanceSquared(pixel, backdrop);
            if (distance > farthest_distance) {
                farthest = pixel;
                farthest_distance = distance;
            }
        }
    }
    return farthest;
}

/// Squared RGB distance. Alpha is omitted because the opaque grid background
/// leaves every captured glyph pixel opaque after compositing.
fn colorDistanceSquared(one: render.Rgba, other: render.Rgba) u32 {
    const red = @as(i32, one.r) - @as(i32, other.r);
    const green = @as(i32, one.g) - @as(i32, other.g);
    const blue = @as(i32, one.b) - @as(i32, other.b);
    return @intCast(red * red + green * green + blue * blue);
}

/// The smallest rectangle of device pixels that contains every pixel of `rect`
/// that is not `background`, or null when there is none.
const InkBox = struct {
    x: u32,
    y: u32,
    width: u32,
    height: u32,
};

fn inkBox(pixels: []const u8, size: render.Size, rect: render.PixelRect, backdrop: render.Rgba) ?InkBox {
    const x_end = @min(size.width, @as(u32, @intFromFloat(rect.x + rect.width)));
    const y_end = @min(size.height, @as(u32, @intFromFloat(rect.y + rect.height)));
    var left: u32 = x_end;
    var top: u32 = y_end;
    var right: u32 = 0;
    var bottom: u32 = 0;
    var y: u32 = @intFromFloat(rect.y);
    while (y < y_end) : (y += 1) {
        var x: u32 = @intFromFloat(rect.x);
        while (x < x_end) : (x += 1) {
            if (sameColor(pixelAt(pixels, size, x, y), backdrop)) continue;
            left = @min(left, x);
            top = @min(top, y);
            right = @max(right, x + 1);
            bottom = @max(bottom, y + 1);
        }
    }
    if (right <= left or bottom <= top) return null;
    return .{ .x = left, .y = top, .width = right - left, .height = bottom - top };
}

/// What two captures disagree about: how many pixels moved, and the smallest
/// rectangle containing all of them.
///
/// The count and the box are separate numbers and both are needed. The box
/// says *where* a frame touched, which is what proves it left the rest of the
/// surface alone; the count says *how much* it touched, so a frame that moved
/// one pixel inside the box cannot be mistaken for one that repainted all of
/// it. Reporting `box.width * box.height` as the pixel count — which is what
/// this used to do — overstates it by the empty space inside the box.
const Difference = struct {
    /// How many pixels differ, wherever they are.
    count: u32,
    /// The smallest rectangle containing every differing pixel.
    box: InkBox,

    /// Whether every differing pixel falls inside `rect`.
    pub fn inside(self: Difference, rect: InkBox) bool {
        return self.box.x >= rect.x and self.box.y >= rect.y and
            self.box.x + self.box.width <= rect.x + rect.width and
            self.box.y + self.box.height <= rect.y + rect.height;
    }
};

/// How two captures differ, or null when they are identical. Comparing every
/// pixel of every frame is not a cost worth optimising: this runs inside a
/// check, and a check that guesses which pixels moved is not a check.
fn diffPixels(before: []const u8, after: []const u8, size: render.Size) ?Difference {
    if (before.len != after.len) return null;
    var left: u32 = size.width;
    var top: u32 = size.height;
    var right: u32 = 0;
    var bottom: u32 = 0;
    var count: u32 = 0;
    var y: u32 = 0;
    while (y < size.height) : (y += 1) {
        var x: u32 = 0;
        while (x < size.width) : (x += 1) {
            const offset = (@as(usize, y) * size.width + x) * 4;
            if (std.mem.eql(u8, before[offset..][0..4], after[offset..][0..4])) continue;
            left = @min(left, x);
            top = @min(top, y);
            right = @max(right, x + 1);
            bottom = @max(bottom, y + 1);
            count += 1;
        }
    }
    if (count == 0) return null;
    return .{
        .count = count,
        .box = .{ .x = left, .y = top, .width = right - left, .height = bottom - top },
    };
}

/// What changed between two readings of a grid renderer's counters. Differences
/// are what "it did no work" and "it redrew one row" mean; the totals a counter
/// holds are not.
fn statDelta(now: render.GridStats, then: render.GridStats) render.GridStats {
    return .{
        .frames = now.frames - then.frames,
        .skipped_frames = now.skipped_frames - then.skipped_frames,
        .rows = now.rows - then.rows,
        .cells = now.cells - then.cells,
        .backgrounds = now.backgrounds - then.backgrounds,
        .glyphs = now.glyphs - then.glyphs,
        .draws = now.draws - then.draws,
        .buffer_uploads = now.buffer_uploads - then.buffer_uploads,
        .buffer_bytes = now.buffer_bytes - then.buffer_bytes,
        .atlas_uploads = now.atlas_uploads - then.atlas_uploads,
        .atlas_bytes = now.atlas_bytes - then.atlas_bytes,
        .rasterised = now.rasterised - then.rasterised,
    };
}

/// Report one measured claim, and count it as a failure when it did not hold.
fn reportCheck(out: *Writer, ok: bool, comptime format: []const u8, args: anytype) usize {
    out.print("  {s} ", .{if (ok) "ok  " else "FAIL"}) catch {};
    out.print(format, args) catch {};
    out.print("\n", .{}) catch {};
    out.flush() catch {};
    return if (ok) 0 else 1;
}

/// Persist one explicit `--screenshot` without making the render thread do
/// compression or filesystem IO. The event loop has ended before this join.
fn writePngOffThread(
    allocator: Allocator,
    io: Io,
    path: []const u8,
    pixels: []const u8,
    size: render.Size,
) !void {
    const owned_path = try allocator.dupe(u8, path);
    const owned_pixels = allocator.dupe(u8, pixels) catch |err| {
        allocator.free(owned_path);
        return err;
    };
    const job = allocator.create(ScreenshotJob) catch |err| {
        allocator.free(owned_pixels);
        allocator.free(owned_path);
        return err;
    };
    job.* = .{
        .allocator = allocator,
        .io = io,
        .window = null,
        .path = owned_path,
        .pixels = owned_pixels,
        .size = size,
    };
    defer job.deinit();
    try job.start();
    job.thread.?.join();
    job.thread = null;
    if (job.failure) |name| {
        log.err("screenshot persistence failed: {s}", .{name});
        return error.ScreenshotWriteFailed;
    }
}

// ---------------------------------------------------------------------------
// The grid check (--grid-test)
// ---------------------------------------------------------------------------

/// The grid the check draws: wide enough for a two-cell glyph and three cells
/// of control.
const check_columns = 12;
const check_rows = 5;

/// The character whose wide cell the check measures: U+6F22.
const wide_codepoint: u21 = 0x6f22;

/// A family that has CJK glyphs, tried when the requested one does not. It is
/// the second candidate rather than the first because a run should draw with
/// whatever family it was asked for; this only makes the wide-glyph row
/// measurable when the first family cannot.
const cjk_family = "Noto Sans Mono CJK SC";

/// The screen the check draws, written as a program would print it.
///
/// Row 0 carries one `A` in each face style, followed after two blank cells by
/// a concealed, decorated cell with an explicit background. Row 1 is a whole
/// row of pure red, set with a 24-bit SGR, so a background colour can be read
/// back as exactly itself. Row 2 is one inverse cell. Row 3 is a wide CJK
/// glyph, which owns two cells. Row 4 is a base letter with a combining acute
/// beside a plain one, so the mark can be shown to stay inside its own cell's
/// advance.
const check_screen =
    "\x1b[0m\x1b[2J\x1b[H" ++
    "A" ++
    "\x1b[1;31mA" ++
    "\x1b[0;3mA" ++
    "\x1b[0;1;3mA" ++
    "\x1b[0m  " ++
    "\x1b[4;9;53;8;38;5;15;48;2;12;34;56mC\x1b[0m\r\n" ++
    "\x1b[48;2;255;0;0m            \x1b[0m\r\n" ++
    "\x1b[7m \x1b[0m\r\n" ++
    "\xe6\xbc\xa2\x1b[0m\r\n" ++
    "e\xcc\x81e\x1b[0m";

/// The grid renderer's own check: the same screen drawn at two display scales,
/// read back pixel by pixel, with the work each frame did counted rather than
/// asserted.
fn gridTest(io: Io, allocator: Allocator, env: EnvSource, family: []const u8, out: *Writer) !u8 {
    var failures: usize = 0;
    // Two scales rather than one: a renderer that scales its output up is
    // correct at 1 and wrong everywhere else, and only the second run can tell
    // the two apart.
    for ([_]f32{ 1.0, 2.0 }) |scale| {
        failures += try gridTestAtScale(io, allocator, env, family, scale, out);
    }
    try out.print("grid-test: {s}, {d} failure(s)\n", .{
        if (failures == 0) "PASS" else "FAIL",
        failures,
    });
    out.flush() catch {};
    return if (failures == 0) 0 else 1;
}

fn gridTestAtScale(
    io: Io,
    allocator: Allocator,
    env: EnvSource,
    family: []const u8,
    scale: f32,
    out: *Writer,
) !usize {
    const size = font.Size.init(font_points, scale) catch |err| {
        try out.print("grid-test: a display scale of {d:.2} is not a usable font size: {s}\n", .{
            scale,
            @errorName(err),
        });
        return 1;
    };

    // The wide-glyph row is only measurable with a face that has a CJK glyph,
    // so a family that has one is preferred — but only after the family the run
    // asked for has been tried, because that is the family a user would see.
    var chosen: ?font.Manager = null;
    for ([_][]const u8{ family, cjk_family }) |candidate| {
        var manager = font.Manager.init(allocator, io, .{
            .family = candidate,
            .size = size,
            .home_dir = env.get("HOME"),
            .atlas_width_px = atlasSizeFor(scale).width_px,
            .atlas_height_px = atlasSizeFor(scale).height_px,
        }) catch |err| {
            try out.print("grid-test: scale {d:.2}: {s} could not be loaded: {s}\n", .{
                scale,
                candidate,
                @errorName(err),
            });
            continue;
        };
        if (manager.glyphIndex(wide_codepoint) != 0) {
            // This one can draw the wide row, so it replaces whatever was held.
            var previous: ?font.Manager = chosen;
            chosen = manager;
            if (previous) |*held| held.deinit();
            break;
        }
        // Otherwise it is only kept while nothing better has turned up yet.
        if (chosen == null) {
            chosen = manager;
        } else {
            var unused = manager;
            unused.deinit();
        }
    }
    var fonts = chosen orelse {
        try out.print("grid-test: scale {d:.2}: no face could be loaded at all\n", .{scale});
        return 1;
    };
    defer fonts.deinit();

    const metrics = fonts.metrics();
    const cell = metrics.cell;
    const has_wide_glyph = fonts.glyphIndex(wide_codepoint) != 0;
    try out.print(
        "grid-test: scale {d:.2}: {s} from {s}, cell {d}x{d}px, baseline {d}px, U+6F22 {s}\n",
        .{
            scale,
            fonts.familyName(),
            fonts.sourcePath(),
            cell.width_px,
            cell.height_px,
            metrics.baseline_px,
            if (has_wide_glyph) "present" else "MISSING",
        },
    );

    const surface_size: render.Size = .{
        .width = cell.width_px * check_columns,
        .height = cell.height_px * check_rows,
    };
    var surface = try render.Surface.init(surface_size);
    defer surface.deinit();

    var grid = try render.Grid.init(allocator, gridColors(default_palette));
    defer grid.deinit();
    try grid.attachAtlas(fonts.atlasPixels(), atlasSizeFor(scale));

    var terminal: term.Terminal = undefined;
    try terminal.init(io, allocator, try term.GridSize.init(check_columns, check_rows));
    defer terminal.deinit(allocator);

    const capture = try allocator.alloc(u8, render.readbackLen(surface_size));
    defer allocator.free(capture);
    // A second buffer, so the pixels before a partial frame can be compared
    // with the pixels after it. That comparison is what "the rest of the
    // surface was left alone" means.
    const earlier = try allocator.alloc(u8, render.readbackLen(surface_size));
    defer allocator.free(earlier);

    const colors = gridColors(default_palette);
    const backdrop = colors.background;
    var failures: usize = 0;
    const red: render.Rgba = .{ .r = 255, .g = 0, .b = 0 };

    terminal.feed(check_screen);
    try terminal.refresh(allocator);
    try grid.draw(&surface, &fonts, &terminal, true);
    const pixels = try surface.read(capture);

    // 1. A background colour is the colour that was asked for, in every pixel of
    //    the row it was set on. Spaces draw no glyph, so the row is nothing but
    //    its background and the count is the whole row.
    const red_row_area = @as(usize, cell.width_px) * cell.height_px * check_columns;
    const red_count = countPixels(pixels, red);
    const red_centre = pixelAt(pixels, surface_size, cell.width_px * 6, cell.height_px + cell.height_px / 2);
    failures += reportCheck(out, red_count == red_row_area, "row 1 background: {d}/{d} pixels are exactly (255,0,0), centre pixel {d},{d},{d}", .{
        red_count, red_row_area, red_centre.r, red_centre.g, red_centre.b,
    });

    // 2. A letter in the default colours puts pixels that are not the background
    //    inside its own cell. Cell 5 is deliberately blank and separated from
    //    the italic samples, so it stays background-only even when a face has
    //    an overhang.
    const letter_cell = render.cellRect(0, 0, cell);
    const letter_ink = countOther(pixels, surface_size, letter_cell, backdrop);
    const blank_ink = countOther(pixels, surface_size, render.cellRect(5, 0, cell), backdrop);
    failures += reportCheck(out, letter_ink > 0 and blank_ink == 0, "row 0 regular 'A': {d} inked pixels; separated blank cell has {d}", .{
        letter_ink, blank_ink,
    });

    // Bold, italic and bold-italic all arrive through the same terminal byte
    // path as a real program's SGR output. Their pixels may be identical when
    // the bundled regular-only fallback is in use, so the deterministic claim
    // is that the terminal retained each style and each cell produced ink.
    const bold_cell = terminal.cell(.{ .col = 1, .row = 0 });
    const italic_cell = terminal.cell(.{ .col = 2, .row = 0 });
    const bold_italic_cell = terminal.cell(.{ .col = 3, .row = 0 });
    const bold_attributes_ok = bold_cell != null and bold_cell.?.style.attributes.bold and
        !bold_cell.?.style.attributes.italic and bold_cell.?.style.fg.eql(.{ .palette = 1 });
    const italic_attributes_ok = italic_cell != null and !italic_cell.?.style.attributes.bold and
        italic_cell.?.style.attributes.italic;
    const bold_italic_attributes_ok = bold_italic_cell != null and bold_italic_cell.?.style.attributes.bold and
        bold_italic_cell.?.style.attributes.italic;
    failures += reportCheck(out, bold_attributes_ok and italic_attributes_ok and bold_italic_attributes_ok, "row 0 SGR styles: bold+red={}, italic={}, bold-italic={}", .{
        bold_attributes_ok, italic_attributes_ok, bold_italic_attributes_ok,
    });

    const bold_ink = countOther(pixels, surface_size, render.cellRect(1, 0, cell), backdrop);
    const italic_ink = countOther(pixels, surface_size, render.cellRect(2, 0, cell), backdrop);
    const bold_italic_ink = countOther(pixels, surface_size, render.cellRect(3, 0, cell), backdrop);
    failures += reportCheck(out, bold_ink > 0 and italic_ink > 0 and bold_italic_ink > 0, "row 0 styled 'A' ink: bold {d}px, italic {d}px, bold-italic {d}px", .{
        bold_ink, italic_ink, bold_italic_ink,
    });

    // SGR 1 changes the face, not an explicit foreground. The most-covered
    // pixel of the bold red glyph must therefore be closer to ANSI red than
    // bright red. This remains deterministic with antialiasing and with a
    // regular-only fallback because it does not assert a particular outline.
    const ansi_red = colors.ansi[1];
    const bright_red = colors.ansi[9];
    if (farthestPixel(pixels, surface_size, render.cellRect(1, 0, cell), backdrop)) |strongest| {
        const red_distance = colorDistanceSquared(strongest, ansi_red);
        const bright_distance = colorDistanceSquared(strongest, bright_red);
        failures += reportCheck(out, red_distance < bright_distance, "row 0 bold red: strongest pixel ({d},{d},{d}) is {d} from ANSI red and {d} from bright red", .{
            strongest.r, strongest.g, strongest.b, red_distance, bright_distance,
        });
    } else {
        failures += reportCheck(out, false, "row 0 bold red: the cell has no foreground pixel to measure", .{});
    }

    // Conceal suppresses the glyph and every foreground decoration, but not
    // the cell's explicit background. Two blank cells separate this sample
    // from the italic faces so an intentional glyph overhang cannot enter it.
    const concealed_cell = terminal.cell(.{ .col = 6, .row = 0 });
    const concealed_attributes_ok = concealed_cell != null and concealed_cell.?.style.attributes.invisible and
        concealed_cell.?.style.attributes.underline == .single and concealed_cell.?.style.attributes.strikethrough and
        concealed_cell.?.style.attributes.overline;
    failures += reportCheck(out, concealed_attributes_ok, "row 0 concealed cell: invisible+underline+strike+overline={}", .{concealed_attributes_ok});
    const concealed_background: render.Rgba = .{ .r = 12, .g = 34, .b = 56 };
    const concealed_rect = render.cellRect(6, 0, cell);
    const concealed_foreground = countOther(pixels, surface_size, concealed_rect, concealed_background);
    const concealed_centre = pixelAt(pixels, surface_size, cell.width_px * 6 + cell.width_px / 2, cell.height_px / 2);
    failures += reportCheck(out, concealed_foreground == 0 and sameColor(concealed_centre, concealed_background), "row 0 concealed cell: {d} non-background pixels, centre ({d},{d},{d})", .{
        concealed_foreground, concealed_centre.r, concealed_centre.g, concealed_centre.b,
    });

    // 3. A wide glyph owns two cells: the engine says so, and the pixels of both
    //    halves are inside the cell the glyph was written to.
    const wide_left = terminal.cell(.{ .col = 0, .row = 3 });
    const wide_right = terminal.cell(.{ .col = 1, .row = 3 });
    const wide_ink_left = countOther(pixels, surface_size, render.cellRect(0, 3, cell), backdrop);
    const wide_ink_right = countOther(pixels, surface_size, render.cellRect(1, 3, cell), backdrop);
    const wide_ink_after = countOther(pixels, surface_size, render.cellRect(2, 3, cell), backdrop);
    failures += reportCheck(out, wide_left != null and wide_left.?.wide and
        wide_right != null and wide_right.?.wide_tail, "row 3: cell 0 wide={}, cell 1 wide_tail={}", .{
        wide_left.?.wide, wide_right.?.wide_tail,
    });
    failures += reportCheck(out, wide_ink_after == 0, "row 3: cell 2 has {d} inked pixels, so the glyph stopped at two cells", .{
        wide_ink_after,
    });
    failures += reportCheck(out, !has_wide_glyph or (wide_ink_left > 0 and wide_ink_right > 0), "row 3: ink {d} px in cell 0 and {d} px in cell 1", .{ wide_ink_left, wide_ink_right });

    // 4. A combining mark stays inside the advance of the cell it belongs to:
    //    the marked letter's ink does not cross into the plain letter's cell,
    //    and it reaches higher than the plain one because of the accent.
    const marked = inkBox(pixels, surface_size, render.cellRect(0, 4, cell), backdrop);
    const plain = inkBox(pixels, surface_size, render.cellRect(1, 4, cell), backdrop);
    const marked_width = if (marked) |box| box.x + box.width else 0;
    const marked_top = if (marked) |box| box.y else 0;
    const plain_top = if (plain) |box| box.y else marked_top;
    failures += reportCheck(out, marked != null and plain != null and marked_width <= cell.width_px, "row 4: 'e'+U+0301 ink ends at x={d} of a {d}px cell", .{ marked_width, cell.width_px });
    failures += reportCheck(out, marked != null and plain != null and marked_top < plain_top, "row 4: the marked letter reaches y={d}, the plain one y={d}", .{ marked_top, plain_top });

    // 5. The cursor is drawn in the terminal's colour, over the cell the engine
    //    says it is on.
    const state = terminal.cursor();
    if (state.position) |at| {
        const cursor_centre = render.cellRect(at.col, at.row, cell);
        const x: u32 = @intFromFloat(cursor_centre.x + cursor_centre.width / 2);
        const y: u32 = @intFromFloat(cursor_centre.y + cursor_centre.height / 2);
        const got = pixelAt(pixels, surface_size, x, y);
        failures += reportCheck(out, sameColor(got, colors.cursor), "cursor: {s} at ({d},{d}), centre pixel {d},{d},{d}", .{
            @tagName(state.shape), at.col, at.row, got.r, got.g, got.b,
        });
    } else {
        failures += reportCheck(out, false, "cursor: the terminal reported no position", .{});
    }

    // 6. Damage: a frame with nothing to do does nothing. Every counter is
    //    printed, because "the boolean was false" is not the claim.
    try out.print("  -- one frame with no change --\n", .{});
    const before_idle = grid.gridStats();
    try terminal.refresh(allocator);
    try grid.draw(&surface, &fonts, &terminal, true);
    const idle = statDelta(grid.gridStats(), before_idle);
    try reportDamage(out, terminal.damage());
    failures += reportCheck(out, idle.frames == 0 and idle.skipped_frames == 1 and idle.rows == 0 and
        idle.cells == 0 and idle.glyphs == 0 and idle.draws == 0 and idle.buffer_uploads == 0 and
        idle.buffer_bytes == 0 and idle.atlas_uploads == 0, "idle frame: frames {d}, skipped {d}, rows {d}, cells {d}, glyphs {d}, draws {d}, buffer uploads {d} ({d} B), atlas uploads {d}", .{
        idle.frames,         idle.skipped_frames, idle.rows,          idle.cells, idle.glyphs, idle.draws,
        idle.buffer_uploads, idle.buffer_bytes,   idle.atlas_uploads,
    });

    // 7. A cursor that moves is a change of its own, and it is measured on its
    //    own. The row it left holds its pixels and has to be repainted; so does
    //    the row it reached. This was folded into the row check below, which is
    //    why that check hides the cursor first: a change that moves the cursor
    //    is never a change confined to one row, and asserting that it was is
    //    what made the row check fail against a correct renderer.
    try out.print("  -- the cursor leaves ({d},{d}) for row 1 --\n", .{ 2, check_rows - 1 });
    _ = try surface.read(earlier);
    const before_move = grid.gridStats();
    terminal.feed("\x1b[2;1H");
    try terminal.refresh(allocator);
    const move_damage = terminal.damage();
    try grid.draw(&surface, &fonts, &terminal, true);
    const moved = statDelta(grid.gridStats(), before_move);
    try reportDamage(out, move_damage);
    failures += reportCheck(out, damageIs(move_damage, &.{ 1, check_rows - 1 }), "cursor move: the terminal damaged the row it left and the row it reached", .{});
    failures += reportCheck(out, moved.rows == 2 and moved.cells == 2 * check_columns, "cursor move: {d} rows, {d} cells, {d} draws — the two damaged rows and no others", .{
        moved.rows, moved.cells, moved.draws,
    });
    // The row the cursor left really was repainted: the cell it was on is that
    // row's own background again, not the cursor's colour.
    const vacated = render.cellRect(2, check_rows - 1, cell);
    const after_move = try surface.read(capture);
    const vacated_pixel = pixelAt(after_move, surface_size, @intFromFloat(vacated.x + vacated.width / 2), @intFromFloat(vacated.y + vacated.height / 2));
    failures += reportCheck(out, !sameColor(vacated_pixel, colors.cursor), "cursor move: the cell it left at (2,{d}) is ({d},{d},{d}), not the cursor colour", .{
        check_rows - 1, vacated_pixel.r, vacated_pixel.g, vacated_pixel.b,
    });

    // The cursor is hidden from here on. A cursor whose pixels move is a second
    // change on top of whatever is written below, and each claim below is about
    // one change at a time.
    terminal.feed("\x1b[?25l");
    try terminal.refresh(allocator);
    try grid.draw(&surface, &fonts, &terminal, true);

    // 8. Damage: one changed row redraws one row, and only that one. The
    //    characters written are ones the atlas already holds — 'A' is on row 0
    //    already — so the rasterise and upload counts have to stay at zero as
    //    well: that is what proves a row whose glyphs the atlas already holds
    //    costs no upload.
    try out.print("  -- one changed row --\n", .{});
    _ = try surface.read(earlier);
    const before_row = grid.gridStats();
    terminal.feed("\x1b[48;2;255;0;0mAAAA");
    try terminal.refresh(allocator);
    const row_damage = terminal.damage();
    try grid.draw(&surface, &fonts, &terminal, true);
    const one_row = statDelta(grid.gridStats(), before_row);
    try reportDamage(out, row_damage);
    failures += reportCheck(out, damageIs(row_damage, &.{1}), "one changed row: the terminal damaged row 1 and nothing else", .{});
    failures += reportCheck(out, one_row.rows == 1 and one_row.cells == check_columns and
        one_row.backgrounds == check_columns, "one changed row: {d} rows, {d} cells, {d} backgrounds, {d} glyphs", .{
        one_row.rows, one_row.cells, one_row.backgrounds, one_row.glyphs,
    });
    failures += reportCheck(out, one_row.atlas_uploads == 0 and one_row.rasterised == 0, "one changed row: {d} glyphs rasterised, {d} atlas uploads", .{
        one_row.rasterised, one_row.atlas_uploads,
    });
    failures += reportCheck(out, one_row.buffer_uploads >= 1, "one changed row: {d} buffer uploads ({d} B)", .{
        one_row.buffer_uploads, one_row.buffer_bytes,
    });
    // Every pixel that moved is inside the row that changed. Not that the
    // renderer says it skipped the others: that the surface outside that row is
    // bit-for-bit what it was.
    const row_rect = InkBox{
        .x = 0,
        .y = cell.height_px,
        .width = surface_size.width,
        .height = cell.height_px,
    };
    const after_row = try surface.read(capture);
    if (diffPixels(earlier, after_row, surface_size)) |diff| {
        failures += reportCheck(out, diff.inside(row_rect), "one changed row: {d} pixels differ, ({d},{d})-({d},{d}); the row is (0,{d})-({d},{d})", .{
            diff.count, diff.box.x,                  diff.box.y,                   diff.box.x + diff.box.width, diff.box.y + diff.box.height,
            row_rect.y, row_rect.x + row_rect.width, row_rect.y + row_rect.height,
        });
    } else {
        failures += reportCheck(out, false, "one changed row: no pixel changed at all, so nothing was written", .{});
    }

    // 9. Damage: one changed cell moves that cell's pixels and nothing else.
    //    The four 'A's the row check above wrote leave the cursor on the fifth
    //    cell of the same row, so this writes one cell without moving the
    //    cursor off its row and without needing a new glyph.
    try out.print("  -- one changed cell --\n", .{});
    _ = try surface.read(earlier);
    const before_cell = grid.gridStats();
    terminal.feed("A");
    try terminal.refresh(allocator);
    const cell_damage = terminal.damage();
    try grid.draw(&surface, &fonts, &terminal, true);
    const one_cell = statDelta(grid.gridStats(), before_cell);
    try reportDamage(out, cell_damage);
    failures += reportCheck(out, damageIs(cell_damage, &.{1}), "one changed cell: the terminal damaged row 1 and nothing else", .{});
    failures += reportCheck(out, one_cell.rows == 1 and one_cell.cells == check_columns, "one changed cell: {d} rows, {d} cells, {d} backgrounds, {d} glyphs", .{
        one_cell.rows, one_cell.cells, one_cell.backgrounds, one_cell.glyphs,
    });
    const cell_rect = inkBounds(render.cellRect(4, 1, cell));
    const after_cell = try surface.read(capture);
    if (diffPixels(earlier, after_cell, surface_size)) |diff| {
        failures += reportCheck(out, diff.inside(cell_rect), "one changed cell: {d} pixels differ, ({d},{d})-({d},{d}); the cell is ({d},{d})-({d},{d})", .{
            diff.count,  diff.box.x,  diff.box.y,                    diff.box.x + diff.box.width,    diff.box.y + diff.box.height,
            cell_rect.x, cell_rect.y, cell_rect.x + cell_rect.width, cell_rect.y + cell_rect.height,
        });
    } else {
        failures += reportCheck(out, false, "one changed cell: no pixel changed at all, so the cell was not written", .{});
    }

    // 10. The cursor coming back. Hiding it repainted the row it was on and
    //     took its pixels with it; showing it again has to put them back, or a
    //     cursor a program un-hides never reappears until something else
    //     changes the screen. The terminal reports no damage at all here, so
    //     this is the frame the renderer has to reason about on its own — which
    //     is the whole of what the cursor bookkeeping is for.
    try out.print("  -- the cursor comes back --\n", .{});
    _ = try surface.read(earlier);
    const before_reveal = grid.gridStats();
    terminal.feed("\x1b[?25h");
    try terminal.refresh(allocator);
    const reveal_damage = terminal.damage();
    const revealed_state = terminal.cursor();
    try grid.draw(&surface, &fonts, &terminal, true);
    const revealed = statDelta(grid.gridStats(), before_reveal);
    try reportDamage(out, reveal_damage);
    failures += reportCheck(out, damageIs(reveal_damage, &.{}), "cursor back: the terminal reported no damage — nothing but the cursor changed", .{});
    failures += reportCheck(out, revealed.rows == 1 and revealed.cells == check_columns, "cursor back: {d} rows, {d} cells, {d} draws — the cursor's row and no other", .{
        revealed.rows, revealed.cells, revealed.draws,
    });
    if (revealed_state.position) |at| {
        const rect = render.cellRect(at.col, at.row, cell);
        const after_reveal = try surface.read(capture);
        const centre = pixelAt(after_reveal, surface_size, @intFromFloat(rect.x + rect.width / 2), @intFromFloat(rect.y + rect.height / 2));
        failures += reportCheck(out, sameColor(centre, colors.cursor), "cursor back: the cell at ({d},{d}) is ({d},{d},{d}), the cursor colour", .{
            at.col, at.row, centre.r, centre.g, centre.b,
        });
        // And the rest of the surface is bit-for-bit what it was.
        if (diffPixels(earlier, after_reveal, surface_size)) |diff| {
            failures += reportCheck(out, diff.inside(row_rect), "cursor back: {d} pixels differ, ({d},{d})-({d},{d}); the row is (0,{d})-({d},{d})", .{
                diff.count, diff.box.x,                  diff.box.y,                   diff.box.x + diff.box.width, diff.box.y + diff.box.height,
                row_rect.y, row_rect.x + row_rect.width, row_rect.y + row_rect.height,
            });
        } else {
            failures += reportCheck(out, false, "cursor back: no pixel changed at all, so the cursor did not come back", .{});
        }
    } else {
        failures += reportCheck(out, false, "cursor back: the terminal reported no position", .{});
    }

    return failures;
}

/// A cell rectangle as whole-pixel bounds, so a diff box can be compared with it.
fn inkBounds(rect: render.PixelRect) InkBox {
    const x: u32 = @intFromFloat(rect.x);
    const y: u32 = @intFromFloat(rect.y);
    return .{
        .x = x,
        .y = y,
        .width = @as(u32, @intFromFloat(rect.x + rect.width)) - x,
        .height = @as(u32, @intFromFloat(rect.y + rect.height)) - y,
    };
}

/// What the terminal said changed, as the note above a check's own numbers.
///
/// A renderer is only accountable for the rows it was handed, so a damage claim
/// that does not say what it was handed is not a claim anybody can check.
fn reportDamage(out: *Writer, damage: term.Damage) !void {
    try out.print("    ", .{});
    switch (damage) {
        .none => try out.print("damage: nothing changed", .{}),
        .full => try out.print("damage: the whole grid", .{}),
        .rows => |rows| {
            try out.print("damage: {d} row(s) [", .{rows.len});
            for (rows, 0..) |row, i| {
                if (i > 0) try out.print(",", .{});
                try out.print("{d}", .{row});
            }
            try out.print("]", .{});
        },
    }
    try out.print("\n", .{});
}

/// Whether the terminal's damage is exactly `expected`.
fn damageIs(damage: term.Damage, expected: []const u16) bool {
    return switch (damage) {
        .rows => |rows| std.mem.eql(u16, expected, rows),
        .none => expected.len == 0,
        .full => false,
    };
}

/// What `--self-test` says about the grid, on the grid the run actually has.
fn selfTestGrid(self: *App, out: *Writer) !usize {
    var failures: usize = 0;
    const cell = self.fonts.metrics().cell;
    const grid_size = self.activeLive().terminal().gridSize();
    try out.print(
        "self-test: grid {d}x{d} cells of {d}x{d}px, drawn with {s}\n",
        .{ grid_size.cols, grid_size.rows, cell.width_px, cell.height_px, self.fonts.familyName() },
    );
    try out.flush();

    const drawn = self.focusedGrid().gridStats();
    try out.print(
        "self-test: the grid has drawn {d} rows, {d} backgrounds, {d} glyphs, rasterised {d}, {d} atlas upload(s), {d} buffer upload(s)\n",
        .{ drawn.rows, drawn.backgrounds, drawn.glyphs, drawn.rasterised, drawn.atlas_uploads, drawn.buffer_uploads },
    );
    failures += reportCheck(out, drawn.glyphs > 0, "self-test: the first frame put {d} glyphs on the surface", .{drawn.glyphs});

    const before = self.focusedGrid().gridStats();
    try self.drawFrame();
    const idle = statDelta(self.focusedGrid().gridStats(), before);
    failures += reportCheck(out, idle.rows == 0 and idle.buffer_uploads == 0 and idle.skipped_frames == 1, "self-test: a second frame with no change drew {d} rows, {d} buffer uploads, {d} atlas uploads", .{
        idle.rows, idle.buffer_uploads, idle.atlas_uploads,
    });

    const state = self.activeLive().terminal().cursor();
    if (state.position) |at| {
        const rect = render.cellRect(at.col, at.row, cell);
        const pixels = try self.capture();
        const got = pixelAt(pixels, self.size, @intFromFloat(rect.x + rect.width / 2), @intFromFloat(rect.y + rect.height / 2));
        failures += reportCheck(out, sameColor(got, gridColors(default_palette).cursor), "self-test: the {s} cursor at ({d},{d}) is drawn as ({d},{d},{d})", .{
            @tagName(state.shape), at.col, at.row, got.r, got.g, got.b,
        });
    }
    return failures;
}

