/// Start the app. `main` returning is the clean exit: the window, the GL context
/// and the surface are gone by then, and the process allocator has nothing of
/// Conduit's left in it.
// ---------------------------------------------------------------------------
// The `conduit` command line client (TASK-60, TASK-66)
// ---------------------------------------------------------------------------

/// What a `conduit <command>` did before any window exists.
const CommandOutcome = union(enum) {
    /// Answered (or refused); leave with this status.
    exit: u8,
    /// No running instance answered: start one and run the command in it.
    start,
};

/// Forward `command` to a running Conduit, or say that one has to start.
///
/// Inside a Conduit terminal (`CONDUIT_CONTROL_ENDPOINT` and its token set)
/// the command goes to that terminal's own Conduit, scoped to its workspace.
/// Otherwise it goes to the per-user instance endpoint with the token from
/// the state directory. Nothing answering, at either, means start.
fn runCommand(init: std.process.Init, command: CliCommand, cwd: []const u8) CommandOutcome {
    const env = processEnv(init);
    const arena = init.arena.allocator();
    switch (command) {
        .control => |request| return .{ .exit = runControlCommand(init, env, request) },
        else => {},
    }
    const method = command.method().?;
    const params = instanceParams(arena, command, cwd) catch return .{ .exit = commandFailure("out of memory") };

    if (env.get(control_api.endpoint_env_name)) |endpoint| if (env.get(control_api.token_env_name)) |token| {
        const frame = controlFrame(arena, method.wireName(), token, env.get(control_api.session_env_name), params) catch
            return .{ .exit = commandFailure("out of memory") };
        if (exchangeControl(arena, endpoint, frame)) |reply| return .{ .exit = reportReply(reply, false) };
    };

    var endpoint_buffer: [path_capacity]u8 = undefined;
    var dir_buffer: [path_capacity]u8 = undefined;
    const dir = controlRuntimeDir(&dir_buffer, env, null) orelse return .start;
    const endpoint = std.fmt.bufPrint(&endpoint_buffer, "{s}/{s}", .{ dir, control_api.instance_endpoint_file_name }) catch return .start;
    var token_path_buffer: [path_capacity]u8 = undefined;
    const token_path = instanceTokenPath(&token_path_buffer, env, null) orelse return .start;
    var token_buffer: [control_api.Token.text_len + 2]u8 = undefined;
    const token_text = Dir.cwd().readFile(init.io, token_path, &token_buffer) catch return .start;
    const token = std.mem.trim(u8, token_text, " \r\n");
    _ = control_api.Token.parse(token) catch return .start;
    const frame = controlFrame(arena, method.wireName(), token, null, params) catch return .{ .exit = commandFailure("out of memory") };
    const reply = exchangeControl(arena, endpoint, frame) orelse return .start;
    return .{ .exit = reportReply(reply, false) };
}

/// The `params` object of `command`'s instance method, as compact JSON.
fn instanceParams(arena: Allocator, command: CliCommand, cwd: []const u8) ![]const u8 {
    var out: Io.Writer.Allocating = .init(arena);
    const writer = &out.writer;
    switch (command) {
        .open_directory => |path| {
            try writer.writeAll("{\"path\":");
            try std.json.Stringify.encodeJsonString(path, .{}, writer);
        },
        .open_ssh => |destination| {
            try writer.writeAll("{\"destination\":");
            try std.json.Stringify.encodeJsonString(destination, .{}, writer);
        },
        .open_workspace => |name| {
            try writer.writeAll("{\"name\":");
            try std.json.Stringify.encodeJsonString(name, .{}, writer);
            try writer.writeAll(",\"path\":");
            try std.json.Stringify.encodeJsonString(cwd, .{}, writer);
        },
        .agent => |launch| {
            try writer.writeAll("{\"harness\":");
            try std.json.Stringify.encodeJsonString(launch.harness, .{}, writer);
            if (launch.prompt.len != 0) {
                try writer.writeAll(",\"prompt\":");
                try std.json.Stringify.encodeJsonString(try std.mem.join(arena, " ", launch.prompt), .{}, writer);
            }
        },
        .control => unreachable, // sent raw by `runControlCommand`
    }
    try writer.writeByte('}');
    return out.written();
}

/// One request frame (without its newline). `params` is compact JSON.
fn controlFrame(arena: Allocator, method: []const u8, token: []const u8, session_text: ?[]const u8, params: []const u8) ![]const u8 {
    var out: Io.Writer.Allocating = .init(arena);
    const writer = &out.writer;
    try writer.writeAll("{\"id\":1,\"method\":");
    try std.json.Stringify.encodeJsonString(method, .{}, writer);
    try writer.writeAll(",\"token\":");
    try std.json.Stringify.encodeJsonString(token, .{}, writer);
    if (session_text) |text| if (std.fmt.parseInt(u32, text, 10)) |id| {
        if (id != 0) try writer.print(",\"session\":{d}", .{id});
    } else |_| {};
    try writer.writeAll(",\"params\":");
    try writer.writeAll(params);
    try writer.writeByte('}');
    return out.written();
}

/// Send one frame and read its reply, or null when nothing answered.
fn exchangeControl(arena: Allocator, endpoint: []const u8, frame: []const u8) ?[]u8 {
    var client = platform.DriverClient.connect(endpoint) catch return null;
    defer client.deinit();
    return client.exchange(arena, frame) catch null;
}

/// Print a refused reply's message (and, with `print`, any reply) and return
/// the exit status: 0 for a result, 1 for an error.
fn reportReply(reply: []const u8, print: bool) u8 {
    if (print) {
        writeStdoutLine(reply);
    }
    const message = replyError(reply) orelse return 0;
    if (!print) {
        writeStderrText("conduit: ") catch {};
        writeStderrText(message) catch {};
        writeStderrText("\n") catch {};
    }
    return 1;
}

/// The error message of a reply, or null for a result. A reply that is not
/// a JSON-RPC result counts as an error.
fn replyError(reply: []const u8) ?[]const u8 {
    var buffer: [4096]u8 = undefined;
    var fixed: std.heap.FixedBufferAllocator = .init(&buffer);
    const parsed = std.json.parseFromSliceLeaky(std.json.Value, fixed.allocator(), reply, .{}) catch return "MalformedReply";
    const object = switch (parsed) {
        .object => |value| value,
        else => return "MalformedReply",
    };
    if (object.get("result") != null) return null;
    const failure = object.get("error") orelse return "MalformedReply";
    if (failure == .object) if (failure.object.get("message")) |message| if (message == .string) {
        return replyMessageName(message.string);
    };
    return "MalformedReply";
}

/// A fault message from the fixed set, or a generic one: the reply's text
/// does not outlive `replyError`'s buffer otherwise.
fn replyMessageName(text: []const u8) []const u8 {
    inline for (std.meta.fields(control_api.FaultCode)) |field| {
        const code: control_api.FaultCode = @enumFromInt(field.value);
        if (std.mem.eql(u8, text, code.message())) return code.message();
    }
    return "Error";
}

fn writeStdoutLine(text: []const u8) void {
    var buffer: [1024]u8 = undefined;
    var out = File.stdout().writerStreaming(std.Io.Threaded.global_single_threaded.io(), &buffer);
    out.interface.writeAll(text) catch return;
    out.interface.writeByte('\n') catch return;
    out.interface.flush() catch return;
}

fn commandFailure(message: []const u8) u8 {
    writeStderrText("conduit: ") catch {};
    writeStderrText(message) catch {};
    writeStderrText("\n") catch {};
    return 1;
}

/// The longest hook input `conduit control agent.event` reads from stdin,
/// matching Claude Code's relay.
const max_hook_stdin_bytes: usize = 1024 * 1024;

/// `conduit control <method> [params]`: one raw request to this terminal's
/// endpoint; the reply is printed and the status says whether it succeeded.
///
/// For `agent.event`, stdin is the payload (wrapped as a Claude Code hook
/// line with `--event=<Hook>`), the agent is `--agent` or
/// `$CONDUIT_AGENT_TOKEN`, and when the endpoint does not take it the line is
/// appended to `$CONDUIT_AGENT_SINK/events.jsonl` instead. With `--event` the
/// command is a hook: it prints nothing and always exits 0, so Claude Code's
/// own behaviour never changes.
fn runControlCommand(init: std.process.Init, env: EnvSource, request: @FieldType(CliCommand, "control")) u8 {
    const arena = init.arena.allocator();
    const hook = request.event != null;
    const is_event = std.mem.eql(u8, request.method, "agent.event");
    var line: ?[]const u8 = null;
    const params: []const u8 = if (request.params) |text|
        compactObject(arena, text) orelse return usageFailure("params must be a JSON object")
    else if (is_event) event: {
        const agent_token = request.agent orelse env.get(agent.correlation_env_name) orelse
            return if (hook) 0 else usageFailure("no agent token (--agent or CONDUIT_AGENT_TOKEN)");
        line = hookLine(init, arena, request.event, agent_token) orelse
            return if (hook) 0 else usageFailure("stdin must be a JSON object");
        var out: Io.Writer.Allocating = .init(arena);
        out.writer.writeAll("{\"agent\":") catch return 1;
        std.json.Stringify.encodeJsonString(agent_token, .{}, &out.writer) catch return 1;
        out.writer.print(",\"payload\":{s}}}", .{line.?}) catch return 1;
        break :event out.written();
    } else "{}";

    const reply: ?[]u8 = reply: {
        const endpoint = env.get(control_api.endpoint_env_name) orelse break :reply null;
        const token = env.get(control_api.token_env_name) orelse break :reply null;
        const frame = controlFrame(arena, request.method, token, env.get(control_api.session_env_name), params) catch break :reply null;
        break :reply exchangeControl(arena, endpoint, frame);
    };
    if (reply) |bytes| {
        if (!hook) return reportReply(bytes, true);
        if (replyError(bytes) == null) return 0;
    }
    if (hook) {
        // Not delivered: the hook line still reaches its agent through the
        // sink the relay script would have written.
        if (line) |text| if (env.get(agent.pi.sink_env_name)) |sink_dir| appendSinkLine(sink_dir, text);
        return 0;
    }
    return commandFailure("no Conduit control endpoint answered (not inside a Conduit terminal?)");
}

fn usageFailure(message: []const u8) u8 {
    _ = commandFailure(message);
    return 2;
}

/// `text` re-encoded compactly when it is a JSON object, else null. The
/// encoding also removes any raw newline that would split the frame.
fn compactObject(arena: Allocator, text: []const u8) ?[]const u8 {
    const value = std.json.parseFromSliceLeaky(std.json.Value, arena, text, .{}) catch return null;
    if (value != .object) return null;
    return std.json.Stringify.valueAlloc(arena, value, .{}) catch null;
}

/// The event line for stdin: the object itself, or with `event` Claude Code's
/// relay format `{"conduit":{"v":1,"event":…,"token":…},"payload":<stdin>}`.
fn hookLine(init: std.process.Init, arena: Allocator, event: ?[]const u8, agent_token: []const u8) ?[]const u8 {
    var buffer: [4096]u8 = undefined;
    var reader = File.stdin().readerStreaming(init.io, &buffer);
    const input = reader.interface.allocRemaining(arena, .limited(max_hook_stdin_bytes)) catch return null;
    const trimmed = std.mem.trim(u8, input, " \t\r\n");
    const payload = compactObject(arena, if (trimmed.len == 0) "{}" else trimmed) orelse return null;
    const name = event orelse return payload;
    var out: Io.Writer.Allocating = .init(arena);
    const writer = &out.writer;
    writer.writeAll("{\"conduit\":{\"v\":1,\"event\":") catch return null;
    std.json.Stringify.encodeJsonString(name, .{}, writer) catch return null;
    writer.writeAll(",\"token\":") catch return null;
    std.json.Stringify.encodeJsonString(agent_token, .{}, writer) catch return null;
    writer.print("}},\"payload\":{s}}}", .{payload}) catch return null;
    return out.written();
}

/// Append one line to `<sink>/events.jsonl` with a single O_APPEND write, as
/// the relay script does. Best effort: a hook must never fail its harness.
fn appendSinkLine(sink_dir: []const u8, line: []const u8) void {
    if (comptime builtin.os.tag == .windows) return;
    if (sink_dir.len == 0 or sink_dir[0] != '/') return;
    var path_buffer: [path_capacity]u8 = undefined;
    const path = std.fmt.bufPrint(&path_buffer, "{s}/{s}", .{ sink_dir, agent.pi.events_file_name }) catch return;
    var line_buffer: std.ArrayList(u8) = .empty;
    defer line_buffer.deinit(std.heap.page_allocator);
    line_buffer.ensureTotalCapacity(std.heap.page_allocator, line.len + 1) catch return;
    line_buffer.appendSliceAssumeCapacity(line);
    line_buffer.appendAssumeCapacity('\n');
    const fd = std.posix.openat(std.posix.AT.FDCWD, path, .{ .ACCMODE = .WRONLY, .APPEND = true, .CREAT = true, .CLOEXEC = true }, 0o600) catch return;
    defer _ = std.posix.system.close(fd);
    // A short or failed append loses this one event; there is no one to tell.
    _ = std.posix.system.write(fd, line_buffer.items.ptr, line_buffer.items.len);
}

/// `command` with a directory resolved against `cwd` and checked to exist,
/// or null after saying why on stderr.
fn resolveCommand(io: Io, arena: Allocator, command: CliCommand, cwd: []const u8) ?CliCommand {
    switch (command) {
        .open_directory => |path| {
            const absolute = std.fs.path.resolve(arena, &.{ cwd, path }) catch return null;
            const stat = Dir.cwd().statFile(io, absolute, .{}) catch {
                _ = commandFailure("no such directory");
                return null;
            };
            if (stat.kind != .directory) {
                _ = commandFailure("not a directory");
                return null;
            }
            return .{ .open_directory = absolute };
        },
        else => return command,
    }
}

pub fn main(init: std.process.Init) !void {
    startup_epoch_ns = Io.Clock.awake.now(init.io).nanoseconds;
    const args = try collectArgs(init.arena.allocator(), init.minimal.args);
    var options = parseArgs(args, processEnv(init)) catch |err| {
        try writeStderrText("conduit: ");
        try writeStderrText(@errorName(err));
        try writeStderrText("\n\n");
        try writeStderrText(usage);
        std.process.exit(2);
    };

    if (options.help) {
        try writeStdout(init.io, usage);
        return;
    }
    // Answered before the log sink, SDL or any display work so packages can
    // prove their stamped version on a headless machine.
    if (options.print_version) {
        try writeStdout(init.io, "conduit " ++ version ++ "\n");
        return;
    }

    // A subcommand talks to a running Conduit before any log file or window
    // exists; only when none answers does this process become one.
    if (options.command) |command| {
        const cwd = try std.process.currentPathAlloc(init.io, init.arena.allocator());
        const resolved = resolveCommand(init.io, init.arena.allocator(), command, cwd) orelse std.process.exit(1);
        switch (runCommand(init, resolved, cwd)) {
            .exit => |status| {
                if (status != 0) std.process.exit(status);
                return;
            },
            .start => {
                options.command = resolved;
                options.command_cwd = cwd;
            },
        }
    }

    sink.install(init.io, options) catch |err| {
        // A log file that cannot be opened costs the file, not the run: the
        // sink is already installed, so stderr keeps working at the resolved
        // level. This message is written with `writeStderrText` rather than
        // `log.err` because it is about the log, and the level is not settled
        // from the caller's point of view yet.
        try writeStderrText("conduit: cannot open a log file (");
        try writeStderrText(@errorName(err));
        try writeStderrText("); continuing with stderr only\n");
    };

    const status = startRun(init, options) catch |err| blk: {
        log.err("conduit stopped: {s}", .{@errorName(err)});
        break :blk 1;
    };

    // The log file is flushed and closed while the sink stays installed, so the
    // leak report the process allocator prints on its way out still reaches
    // stderr. See `Sink.closeFile`.
    sink.closeFile();
    if (status != 0) std.process.exit(status);
}

/// Everything the run does once logging is up, in one place.
///
/// Split from `main` so that every path through it — help, a printed log path, a
/// normal run, a failure — ends at the same line, which closes the log file.
fn startRun(init: std.process.Init, options: Options) !u8 {
    log.info("conduit {s} starting on {s}", .{ version, buildTarget(&target_buf) catch "unknown" });

    // The resolved settings, at debug. This is the first thing an agent reading
    // a log needs and cannot see from the outside: which level the run is at,
    // and which file that level is going to.
    log.debug("logging at {s} to {s}", .{
        @tagName(sink.level),
        if (sink.logPath().len == 0) "stderr only" else sink.logPath(),
    });

    // `--print-log-path` answers before anything else can go wrong and before a
    // window exists, so a headless test driver can rely on it. When there is no
    // file to name, it says so rather than printing an empty line that a script
    // would treat as a path.
    if (options.print_log_path) {
        if (sink.logPath().len == 0) {
            try writeStdout(init.io, "(no log file: logging to stderr only)\n");
        } else {
            try writeStdout(init.io, sink.logPath());
            try writeStdout(init.io, "\n");
        }
        return 0;
    }

    const resolved = optionsForRun(options);
    log.debug("window {d}x{d} logical, {s}, {s}", .{
        resolved.run.width,
        resolved.run.height,
        if (resolved.run.hidden) "hidden" else "visible",
        if (resolved.run.run_ms) |_| "a run budget" else "run until closed",
    });
    return runApp(init, resolved);
}

/// Open the window, load the GPU bindings, and run until the window closes.
///
/// Everything taken here is given back in the reverse order: the app first, then
/// the window and its context, then SDL. A run that ends this way has nothing of
/// Conduit's left alive and nothing of Conduit's left allocated.
fn driverTestEndpoint(io: Io, buffer: []u8) ![]const u8 {
    var id_buffer: [path_capacity]u8 = undefined;
    const id = try generateRunId(io, &id_buffer);
    return if (builtin.os.tag == .windows)
        std.fmt.bufPrint(buffer, "\\\\.\\pipe\\conduit-{s}", .{id})
    else
        std.fmt.bufPrint(buffer, "{s}{c}driver-{s}.sock", .{ fallback_log_dir, std.fs.path.sep, id });
}

/// Make a directory name unique to this process run. The worker that writes
/// the first screenshot creates it; startup performs no artifact filesystem IO.
fn generatedArtifactDir(io: Io, base: []const u8, buffer: []u8) ![]const u8 {
    var id_buffer: [path_capacity]u8 = undefined;
    const id = try generateRunId(io, &id_buffer);
    return std.fmt.bufPrint(buffer, "{s}{c}conduit-artifacts-{s}", .{ base, std.fs.path.sep, id });
}

fn runApp(init: std.process.Init, initial_options: Options) !u8 {
    var options = initial_options;
    var driver_endpoint_buffer: [path_capacity]u8 = undefined;
    if (options.run.driver_test and options.run.test_driver_endpoint == null) {
        options.run.test_driver_endpoint = try driverTestEndpoint(init.io, &driver_endpoint_buffer);
    }
    var artifact_dir_buffer: [path_capacity]u8 = undefined;
    if (options.run.test_driver_endpoint != null and options.run.test_artifact_dir == null) {
        options.run.test_artifact_dir = try generatedArtifactDir(init.io, options.dir, &artifact_dir_buffer);
    }
    const env = processEnv(init);
    var config_path_buffer: [path_capacity]u8 = undefined;
    if (options.run.config_test) {
        options.run.config_path = try configTestPath(init.io, env, &config_path_buffer);
        try writeConfigTestFile(init.io, options.run.config_path.?, config_test_initial);
    }
    defer if (options.run.config_test) removeConfigTestDir(init.io, options.run.config_path.?);
    if (options.run.theme_test) {
        options.run.config_path = try themeTestPath(init.io, env, &config_path_buffer);
        try writeConfigTestFile(init.io, options.run.config_path.?, theme_test_initial);
    }
    defer if (options.run.theme_test) removeThemeTestDir(init.io, options.run.config_path.?);
    if (options.run.font_test) {
        options.run.config_path = try fontTestPath(init.io, env, &config_path_buffer);
        try writeConfigTestFile(init.io, options.run.config_path.?, font_test_initial);
    }
    defer if (options.run.font_test) removeFontTestDir(init.io, options.run.config_path.?);
    if (options.run.settings_test) {
        options.run.config_path = try settingsTestPath(init.io, env, &config_path_buffer);
        try writeConfigTestFile(init.io, options.run.config_path.?, settings_test_initial);
    }
    defer if (options.run.settings_test) removeSettingsTestDir(init.io, options.run.config_path.?);
    if (options.run.profiles_test) {
        options.run.config_path = try profilesTestPath(init.io, env, &config_path_buffer);
        var initial_buffer: [4096]u8 = undefined;
        const root = profilesTestRoot(options.run.config_path.?) orelse return error.InvalidPath;
        try writeConfigTestFile(init.io, options.run.config_path.?, try profilesTestConfig(&initial_buffer, root, ""));
    }
    defer if (options.run.profiles_test) removeProfilesTestDir(init.io, options.run.config_path.?);
    var agent_test_dir_buffer: [path_capacity]u8 = undefined;
    if (options.run.agent_test) {
        const dir = try agentTestDir(init.io, env, &agent_test_dir_buffer);
        options.run.agent_test_dir = dir;
        options.run.config_path = try std.fmt.bufPrint(&config_path_buffer, "{s}/conduit/config", .{dir});
        try writeConfigTestFile(init.io, options.run.config_path.?, agent_test_initial_config);
    }
    defer if (options.run.agent_test) removeAgentTestDir(init.io, options.run.agent_test_dir.?);
    // `--control-test` keeps its sockets, instance token and SSH config in
    // the same private directory, so neither the person's running Conduit
    // nor their `~/.ssh/config` is ever reached.
    var control_runtime_buffer: [path_capacity]u8 = undefined;
    var control_state_buffer: [path_capacity]u8 = undefined;
    if (options.run.control_test) {
        const dir = options.run.agent_test_dir.?;
        options.run.runtime_dir = try std.fmt.bufPrint(&control_runtime_buffer, "{s}/rt", .{dir});
        options.run.state_dir = try std.fmt.bufPrint(&control_state_buffer, "{s}/state", .{dir});
        options.run.ssh_test_dir = dir;
        options.run.control = true;
    }
    var ssh_test_dir_buffer: [path_capacity]u8 = undefined;
    if (options.run.ssh_test) {
        const dir = try sshTestDir(init.io, &ssh_test_dir_buffer);
        options.run.ssh_test_dir = dir;
        options.run.config_path = try std.fmt.bufPrint(&config_path_buffer, "{s}/conduit/config", .{dir});
        try writeConfigTestFile(init.io, options.run.config_path.?, "# --ssh-test\n");
    }
    defer if (options.run.ssh_test) removeSshTestDir(init.io, options.run.ssh_test_dir.?);
    try platform.setAppMetadata(.{
        .name = app_name,
        .version = version,
        .identifier = app_identifier,
    });
    // The clipboard check writes fixtures to the clipboard and the primary
    // selection. Pinned to `offscreen`, those are SDL's process-local copies;
    // on any other driver they would be the display's — someone's real
    // clipboard — so a run that cannot be pinned refuses to start.
    if (options.run.clipboard_test) {
        if (!platform.forceVideoDriver("offscreen")) return error.ClipboardTestDriverNotPinned;
    }
    var window = platform.Window.create(.{
        .title = window_title,
        .logical = .{ .width = options.run.width, .height = options.run.height },
        .fixed_scale = if (options.run.scale) |factor| platform.Scale.fromPlatform(factor) else null,
        .hidden = options.run.hidden,
    }) catch |err| switch (err) {
        // No display server, or no video driver will start. A windowed app on a
        // machine with no window system has nothing to draw in: it says so and
        // leaves, so `zig build run` still works on a headless development box. A
        // run that was asked to prove something does not get that answer — a check
        // that cannot run must fail rather than pass quietly.
        error.VideoUnavailable => {
            if (options.run.self_test or options.run.grid_test or options.run.scroll_test or
                options.run.mouse_test or options.run.clipboard_test or options.run.ui_test or
                options.run.ime_test or options.run.sidebar_test or options.run.tabs_test or options.run.panes_test or
                options.run.scratchpad_test or options.run.palette_test or options.run.workspaces_test or
                options.run.links_test or options.run.search_test or options.run.menu_test or
                options.run.config_test or options.run.theme_test or options.run.font_test or options.run.settings_test or
                options.run.profiles_test or options.run.git_test or options.run.agent_test or options.run.ssh_test or options.run.driver_test or
                options.run.restore_test or options.run.a11y_test) return err;
            var buffer: [256]u8 = undefined;
            log.warn(
                "no usable display ({s}): there is no window to draw in. Set DISPLAY, or run under xvfb-run",
                .{platform.lastError(&buffer)},
            );
            return 0;
        },
        else => return err,
    };
    defer window.deinit();
    if (startup_epoch_ns != 0) {
        var phase_buffer: [96]u8 = undefined;
        log.debug("{s}", .{startupPhaseLine(&phase_buffer, "window", Io.Clock.awake.now(init.io).nanoseconds - startup_epoch_ns)});
    }
    const runtime = window.runtimeInfo();
    log.info("window backend {s}, high-pixel-density {s}", .{
        runtime.video_backend orelse "unknown",
        if (runtime.high_pixel_density) "enabled" else "disabled",
    });
    if (runtime.pixel_density) |density| {
        log.info("window reports {d:.2} physical pixels per logical pixel", .{density});
    } else {
        log.debug("the window backend did not report a pixel density", .{});
    }
    if (runtime.logical_size) |logical| {
        if (runtime.pixel_size) |pixels| {
            log.info("window geometry {d}x{d} logical, {d}x{d} pixels", .{
                logical.width,
                logical.height,
                pixels.width_px,
                pixels.height_px,
            });
        } else {
            log.debug("window geometry {d}x{d} logical; pixel size unavailable", .{
                logical.width,
                logical.height,
            });
        }
    } else if (runtime.pixel_size) |pixels| {
        log.debug("window geometry {d}x{d} pixels; logical size unavailable", .{
            pixels.width_px,
            pixels.height_px,
        });
    } else {
        log.debug("the window backend did not report window geometry", .{});
    }
    if (options.run.clipboard_test) {
        const driver = platform.videoDriverName() orelse "";
        if (!std.mem.eql(u8, driver, "offscreen")) {
            log.err("--clipboard-test refuses to run on the {s} driver: its clipboard is the display's", .{driver});
            return error.ClipboardTestDriverNotPinned;
        }
    }

    try render.load();

    var out_buffer: [4096]u8 = undefined;
    var out_file = File.stdout().writerStreaming(init.io, &out_buffer);
    const out = &out_file.interface;

    // The grid check builds its own surfaces, faces and terminal: it has to
    // render the same screen at two display scales, which a window at one scale
    // cannot do, and a check that shares the app's state measures the app's
    // state rather than the grid.
    if (options.run.grid_test) {
        const status = try gridTest(init.io, init.gpa, env, options.run.font_family, out);
        out_file.interface.flush() catch {};
        return status;
    }

    // The restore check runs several apps, one after another, on this window:
    // a relaunch is what it proves.
    if (options.run.restore_test) {
        const status = try restoreTest(init, env, &window, options, out);
        out_file.interface.flush() catch {};
        return status;
    }

    // `--a11y-test` points the bridge at a private session bus with a
    // stand-in AT-SPI registry, so nothing reaches the person's own bus. They
    // are released after the app (and so after the bridge).
    var a11y_bus: accessibility.check.PrivateBus = .{ .io = init.io };
    var a11y_bus_started = false;
    defer if (a11y_bus_started) a11y_bus.stop();
    var a11y_registry: ?accessibility.check.FakeRegistry = null;
    defer if (a11y_registry) |*registry| registry.shutdown();
    if (options.run.a11y_test) {
        if (builtin.os.tag != .linux or !try a11y_bus.start()) {
            try out.writeAll("a11y-test: skipped: dbus-daemon is not installed\n");
            out_file.interface.flush() catch {};
            return 0;
        }
        a11y_bus_started = true;
        a11y_registry = .{
            .io = init.io,
            .conn = try accessibility.dbus.Connection.open(init.gpa, a11y_bus.address(), 64 * 1024, 64 * 1024),
            .bus_address = a11y_bus.address(),
        };
        try a11y_registry.?.serve();
        options.run.a11y_bus_address = a11y_bus.address();
    }

    const app = try App.init(init.io, env, init.gpa, &window, options);
    defer app.destroy();
    try app.syncTextInput();
    // A `conduit <command>` that found no running instance runs here.
    if (options.command) |command| try app.queueStartupCommand(command, options.command_cwd orelse "");

    // A check's status is the run's status: `--scroll-test` and `--mouse-test`
    // exit non-zero when a check failed, which is what a test script reads.
    var check_status: u8 = 0;
    if (options.run.a11y_test) {
        check_status = try a11yTest(app, init.io, init.gpa, out, &a11y_bus, &a11y_registry.?);
    } else if (options.run.driver_test) {
        check_status = try driverTest(app, init.io, out, options.run.test_driver_endpoint.?);
    } else if (options.run.self_test) {
        try selfTest(app, init.io, out);
    } else if (options.run.scroll_test) {
        check_status = try scrollTest(app, init.io, out);
    } else if (options.run.mouse_test) {
        check_status = try mouseTest(app, init.io, out);
    } else if (options.run.clipboard_test) {
        check_status = try clipboardTest(app, init.io, out);
    } else if (options.run.ui_test) {
        check_status = try uiTest(app, init.io, out);
    } else if (options.run.ime_test) {
        check_status = try imeTest(app, init.io, out);
    } else if (options.run.sidebar_test) {
        check_status = try sidebarTest(app, init.io, out);
    } else if (options.run.tabs_test) {
        check_status = try tabsTest(app, init.io, out);
    } else if (options.run.panes_test) {
        check_status = try panesTest(app, init.io, out);
    } else if (options.run.scratchpad_test) {
        check_status = try scratchpadTest(app, init.io, out);
    } else if (options.run.palette_test) {
        check_status = try paletteTest(app, init.io, out);
    } else if (options.run.workspaces_test) {
        check_status = try workspacesTest(app, init.io, out);
    } else if (options.run.links_test) {
        check_status = try linksTest(app, init.io, out);
    } else if (options.run.search_test) {
        check_status = try searchTest(app, init.io, out);
    } else if (options.run.menu_test) {
        check_status = try menuTest(app, init.io, out);
    } else if (options.run.config_test) {
        check_status = try configTest(app, init.io, out);
    } else if (options.run.theme_test) {
        check_status = try themeTest(app, init.io, out);
    } else if (options.run.font_test) {
        check_status = try fontTest(app, init.io, out);
    } else if (options.run.settings_test) {
        check_status = try settingsTest(app, init.io, out);
    } else if (options.run.profiles_test) {
        check_status = try profilesTest(app, init.io, out);
    } else if (options.run.git_test) {
        check_status = try gitTest(app, init.io, out);
    } else if (options.run.control_test) {
        check_status = try controlTest(app, init.io, out);
    } else if (options.run.agent_view_test) {
        check_status = try agentViewTest(app, init.io, out);
    } else if (options.run.agent_manager_test) {
        check_status = try agentManagerTest(app, init.io, out);
    } else if (options.run.agent_prompts_test) {
        check_status = try agentPromptsTest(app, init.io, out);
    } else if (options.run.backlog_test) {
        check_status = try backlogTest(app, init.io, out);
    } else if (options.run.agent_test) {
        check_status = try agentTest(app, init.io, out);
    } else if (options.run.ssh_test) {
        check_status = try sshTest(app, init.io, out);
    } else {
        try app.run(init.io, runDeadline(init.io, options.run.run_ms));
    }
    out_file.interface.flush() catch {};

    // The screenshot is the surface as the run left it, through the same
    // readback a `--self-test` capture uses, so what the file holds is what the
    // window was showing.
    if (options.run.screenshot) |path| {
        const pixels = try app.capture();
        try writePngOffThread(init.gpa, init.io, path, pixels, app.size);
        log.info("screenshot written to {s} ({d}x{d})", .{ path, app.size.width, app.size.height });
    }

    log.info("conduit leaving after {d} frames", .{app.scheduler.frames});
    return check_status;
}

/// Scratch for the startup line's target name. `main` owns the process, so a
/// buffer it never re-enters does not need to be threaded through.
var target_buf: [64]u8 = undefined;

/// The arguments as a slice, `argv[0]` first, exactly as the OS gave them.
fn collectArgs(allocator: Allocator, args: std.process.Args) ![]const []const u8 {
    var iterator = try std.process.Args.Iterator.initAllocator(args, allocator);
    defer iterator.deinit();

    var collected: std.ArrayList([]const u8) = .empty;
    // Copied: on Windows each argument is a slice of the iterator's own
    // buffer, which `deinit` frees (and Debug overwrites) before the caller
    // reads them, so every flag would arrive as garbage (TASK-49).
    while (iterator.next()) |arg| try collected.append(allocator, try allocator.dupe(u8, arg));
    return collected.items;
}

fn writeStdout(io: Io, text: []const u8) !void {
    var buffer: [1024]u8 = undefined;
    var out = File.stdout().writerStreaming(io, &buffer);
    try out.interface.writeAll(text);
    try out.interface.flush();
}

fn writeStderrText(text: []const u8) !void {
    var buffer: [1024]u8 = undefined;
    var out = std.debug.lockStderr(&buffer).terminal();
    defer std.debug.unlockStderr();
    try out.writer.writeAll(text);
    try out.writer.flush();
}

/// Describe the build target as `<arch>-<os>` into `buf`, for example
/// `x86_64-linux`. Only the two parts that are true on every target are
/// reported, so the startup line never claims an ABI it does not know.
pub fn buildTarget(buf: []u8) std.fmt.BufPrintError![]const u8 {
    return std.fmt.bufPrint(buf, "{s}-{s}", .{
        @tagName(builtin.target.cpu.arch),
        @tagName(builtin.target.os.tag),
    });
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

test "buildTarget names the architecture and the operating system" {
    var buf: [64]u8 = undefined;
    const got = try buildTarget(&buf);

    try std.testing.expectEqualStrings(
        @tagName(builtin.target.cpu.arch) ++ "-" ++ @tagName(builtin.target.os.tag),
        got,
    );
}

const test_env = struct {
    vars: []const [2][]const u8,

    fn get(ctx: *const anyopaque, key: []const u8) ?[]const u8 {
        const self: *const @This() = @ptrCast(@alignCast(ctx));
        for (self.vars) |pair| {
            if (std.mem.eql(u8, pair[0], key)) return pair[1];
        }
        return null;
    }

    fn entry(ctx: *const anyopaque, index: usize) ?EnvSource.Entry {
        const self: *const @This() = @ptrCast(@alignCast(ctx));
        if (index >= self.vars.len) return null;
        return .{ .key = self.vars[index][0], .value = self.vars[index][1] };
    }

    fn source(self: *const @This()) EnvSource {
        return .{ .ctx = self, .getFn = get, .entryFn = entry };
    }
};

