test "the instance token lives beside the state file, and the client's frames and replies are exact" {
    const env = test_env{ .vars = &.{ .{ "HOME", "/home/me" }, .{ "XDG_STATE_HOME", "/home/me/.state" } } };
    var buffer: [path_capacity]u8 = undefined;
